import {
	TableModelError,
	META_CAPABILITY_INTROSPECTION_DOCUMENT,
	MetaContractError,
	assessMetaCapabilities,
	assertMetaQuery,
	buildCreateDocument,
	buildDeleteDocument,
	buildListDocument,
	buildMetaDocument,
	buildUpdateDocument,
	createTableModelResolver,
} from '@constructive-io/data';
import type {
	ListResult,
	MetaCapabilities,
	MetaCapabilityIntrospectionQuery,
	MetaQuery,
	MutationOptions,
	TableModel,
	TableModelResolver,
} from '@constructive-io/data';

import { partialResultOf, type SheetsExecuteFn } from '../context/sheets-execute';
import { sheetsIdentifierToRowKey, type SheetsRowIdentifier } from '../row-identity';
import type {
	AdapterListQuery,
	AdapterListResult,
	AdapterTableContext,
	AdapterTableModelOptions,
	SheetsBackendAdapter,
} from './sheets-adapter';

/** Capability preflight, once per executor. */
const capabilityChecks = new WeakMap<SheetsExecuteFn, Promise<MetaCapabilities>>();
/** One model resolver per `_meta` result, so each schema version keeps its own type cache. */
const resolvers = new WeakMap<MetaQuery, TableModelResolver>();

async function ensureMetaCapabilities(execute: SheetsExecuteFn): Promise<MetaCapabilities> {
	const cached = capabilityChecks.get(execute);
	if (cached) return cached;

	const check = execute<MetaCapabilityIntrospectionQuery>(META_CAPABILITY_INTROSPECTION_DOCUMENT).then((result) => {
		const { compatibility, capabilities } = assessMetaCapabilities(result);
		if (compatibility.status !== 'compatible') throw new MetaContractError(compatibility);
		return capabilities;
	});
	capabilityChecks.set(execute, check);

	try {
		return await check;
	} catch (error) {
		// Contract mismatches remain deterministic, while transport failures can
		// recover on a later call instead of poisoning this executor forever.
		if (capabilityChecks.get(execute) === check) capabilityChecks.delete(execute);
		throw error;
	}
}

function resolverFor(meta: MetaQuery): TableModelResolver {
	let resolver = resolvers.get(meta);
	if (!resolver) {
		resolver = createTableModelResolver(meta);
		resolvers.set(meta, resolver);
	}
	return resolver;
}


/**
 * Create the default PostGraphile-backed adapter. The metadata preflight makes
 * an outdated endpoint distinguishable from an ordinary transport failure and
 * tells which optional `_meta` fields the server has. Table models resolve
 * lazily, one table at a time, from targeted introspection.
 */
/**
 * An update or delete the server answered without changing a row: no row matched, because a
 * row rule hides it from this user or it is gone. The server reports that without an error,
 * so without this check a refused write would read as saved.
 */
function writeNotApplied(model: TableModel, action: 'update' | 'delete'): TableModelError {
	const message = action === 'update'
		? 'This record was not changed. You may not be allowed to change it, or it no longer exists.'
		: 'This record was not deleted. You may not be allowed to delete it, or it no longer exists.';
	return new TableModelError('WRITE_NOT_APPLIED', message, { tableKey: model.key });
}

export function createPostGraphileAdapter(): SheetsBackendAdapter {
	return {
		async fetchMeta(execute: SheetsExecuteFn): Promise<MetaQuery> {
			const capabilities = await ensureMetaCapabilities(execute);
			const meta = await execute<MetaQuery>(buildMetaDocument(capabilities));
			assertMetaQuery(meta);
			return meta;
		},

		async fetchTableModel(
			execute: SheetsExecuteFn,
			meta: MetaQuery,
			tableRef: string,
			options: AdapterTableModelOptions = {},
		): Promise<TableModel> {
			return resolverFor(meta).resolve(execute, tableRef, { displayOverrides: options.displayOverrides });
		},

		async listRows<T = Record<string, unknown>>(
			ctx: AdapterTableContext,
			query: AdapterListQuery,
			execute: SheetsExecuteFn,
		): Promise<AdapterListResult<T>> {
			const { model } = ctx;
			const document = buildListDocument(model, {
				first: query.limit,
				offset: query.offset ? query.offset : undefined,
				after: query.after,
				where: query.where,
				orderBy: query.orderBy,
				relations: query.relations,
				relationPageSize: query.relationPageSize,
				columns: query.columns,
				totalCount: query.includeTotalCount !== false,
			});
			let result: ListResult;
			try {
				result = document.read(await execute(document.document, document.variables, { signal: query.signal }));
			} catch (error) {
				// Rows with cells the API could not serve (a float NaN) still load; each such
				// cell carries its error. Any other failure fails the read as before.
				const partial = partialResultOf(error);
				if (!partial) throw error;
				try {
					result = document.read(partial.data, partial.errors);
				} catch {
					throw error;
				}
			}
			return {
				rows: result.rows as T[],
				totalCount: result.totalCount ?? result.rows.length,
				pageInfo: result.pageInfo ?? undefined,
			};
		},

		async createRow<T = Record<string, unknown>>(
			ctx: AdapterTableContext,
			data: Record<string, unknown>,
			execute: SheetsExecuteFn,
			options: MutationOptions = {},
		): Promise<T | null> {
			// The caller decides which fields a new row gets: an empty string or a null is sent
			// as given, and a field that is left out is simply absent (the codec skips undefined).
			const { model } = ctx;
			const document = buildCreateDocument(model, data, { returning: options.returning });
			return document.read(await execute(document.document, document.variables)) as T | null;
		},

		async updateRow<T = Record<string, unknown>>(
			ctx: AdapterTableContext,
			id: SheetsRowIdentifier,
			patch: Record<string, unknown>,
			execute: SheetsExecuteFn,
			options: MutationOptions = {},
		): Promise<T | null> {
			// Clearing a field to null or '' is a real change and reaches the server.
			if (!Object.values(patch).some((value) => value !== undefined)) return null;
			const { model } = ctx;
			const document = buildUpdateDocument(model, sheetsIdentifierToRowKey(model, id), patch, {
				returning: options.returning,
			});
			const data = await execute(document.document, document.variables);
			if (document.applied?.(data) === false) throw writeNotApplied(model, 'update');
			return document.read(data) as T | null;
		},

		async deleteRow(ctx: AdapterTableContext, id: SheetsRowIdentifier, execute: SheetsExecuteFn): Promise<void> {
			const { model } = ctx;
			const document = buildDeleteDocument(model, sheetsIdentifierToRowKey(model, id));
			const data = await execute(document.document, document.variables);
			if (document.applied?.(data) === false) throw writeNotApplied(model, 'delete');
		},
	};
}

// Backend adapter contract.
//
// Sheets talks to its backend through ONE injectable seam: a SheetsBackendAdapter
// owns schema metadata, per-table models, row reads, and CRUD mutations. The
// default implementation (createPostGraphileAdapter) builds every document from
// the table model in @constructive-io/data; a host targeting a different backend
// implements this interface and passes it as `SheetsConfig.adapter`.
import type {
	DisplayFieldOverrides,
	MetaQuery,
	MutationOptions,
	SortSpec,
	TableModel,
} from '@constructive-io/data';

import type { SheetsExecuteFn } from '../context/sheets-execute';
import type { SheetsRowIdentifier } from '../row-identity';

/** The table being operated on. */
export interface AdapterTableContext {
	/** Model of the table (`useTableModel`, `fetchTableModel`). Every document the built-in adapter sends is built from it. */
	model: TableModel;
	/** The table name or `TableModel.key` the caller used. */
	tableName: string;
}

/** A normalized list query. */
export interface AdapterListQuery {
	/** A filter in the server's filter input shape. */
	where?: Readonly<Record<string, unknown>>;
	/** Sort, first entry first. Each field must be a sortable column of the model. */
	orderBy?: readonly SortSpec[];
	/** Page size. */
	limit?: number;
	/** Rows to skip. */
	offset?: number;
	/** Relay cursor for forward pagination (infinite/cursor mode). */
	after?: string;
	/** Relation fields to select: every readable relation, none (the default), or these field names. */
	relations?: 'all' | 'none' | readonly string[];
	/**
	 * Columns to select, for example the ones a view shows. The primary key and the
	 * local key fields of the selected relations are always added. Omitted: every readable column.
	 */
	columns?: readonly string[];
	/** Page size of list relations. */
	relationPageSize?: number;
	/** Count all matching rows. Default true. When false, `totalCount` is the number of rows returned. */
	includeTotalCount?: boolean;
	/** Aborts the request, for example when the filter or sort it was for has changed. */
	signal?: AbortSignal;
}

export interface AdapterPageInfo {
	endCursor?: string | null;
	startCursor?: string | null;
	hasNextPage?: boolean;
	hasPreviousPage?: boolean;
}

export interface AdapterListResult<T = Record<string, unknown>> {
	rows: T[];
	totalCount: number;
	pageInfo?: AdapterPageInfo;
}

export interface AdapterTableModelOptions {
	/** Host override for the fields that label a record. */
	displayOverrides?: DisplayFieldOverrides;
}

export interface SheetsBackendAdapter {
	/** Read the schema metadata. The default adapter checks and runs the July 2026 `_meta` contract. */
	fetchMeta(execute: SheetsExecuteFn): Promise<MetaQuery>;

	/**
	 * Model one table of a `_meta` result, by `TableModel.key` or bare name. A
	 * failure concerns that table only; other tables keep loading.
	 */
	fetchTableModel(
		execute: SheetsExecuteFn,
		meta: MetaQuery,
		tableRef: string,
		options?: AdapterTableModelOptions,
	): Promise<TableModel>;

	/** Read a page of rows, flattening relation connections into arrays. */
	listRows<T = Record<string, unknown>>(
		ctx: AdapterTableContext,
		query: AdapterListQuery,
		execute: SheetsExecuteFn,
	): Promise<AdapterListResult<T>>;

	/** Create a row; resolves to the created row (or null). */
	createRow<T = Record<string, unknown>>(
		ctx: AdapterTableContext,
		data: Record<string, unknown>,
		execute: SheetsExecuteFn,
		options?: MutationOptions,
	): Promise<T | null>;

	/** Update a row by its primary key (a scalar for a one-field key, or the key object); resolves to the updated row (or null). */
	updateRow<T = Record<string, unknown>>(
		ctx: AdapterTableContext,
		id: SheetsRowIdentifier,
		patch: Record<string, unknown>,
		execute: SheetsExecuteFn,
		options?: MutationOptions,
	): Promise<T | null>;

	/** Delete a row by its primary key (a scalar for a one-field key, or the key object). */
	deleteRow(
		ctx: AdapterTableContext,
		id: SheetsRowIdentifier,
		execute: SheetsExecuteFn,
		options?: MutationOptions,
	): Promise<void>;
}

import { createPostGraphileAdapter } from './postgraphile-adapter';
import type { SheetsBackendAdapter } from './sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';

// Stable module-level singleton: the default adapter is stateless, so every hook
// that falls back to it shares one instance (no per-render churn).
const defaultAdapter = createPostGraphileAdapter();

/**
 * Resolve the active backend adapter. A consumer that never sets
 * `config.adapter` transparently gets the default PostGraphile adapter,
 * preserving today's behavior exactly.
 */
export function useSheetsAdapter(): SheetsBackendAdapter {
	const { config } = useSheetsContext();
	return config.adapter ?? defaultAdapter;
}

// =============================================================================
// @constructive-io/sheets/advanced — Power-user / extension primitives
// =============================================================================
// Lower-level building blocks for consumers composing their own editors and
// cells. Everything here is optional; the root entry stays sufficient for
// ordinary usage. Importing from this subpath keeps the core surface slim.

// -- Native editor registry (DOM overlay editors) -----------------------------
export type { NativeEditor } from './grid-dom/editors/editor-registry-dom';
export { DOM_EDITOR_REGISTRY, resolveNativeEditor, wrapNativeEditor } from './grid-dom/editors/editor-registry-dom';
export type { EditorProps } from './grid-dom/editors/editor-props';

// -- Overlay editor primitives ------------------------------------------------
export { OVERLAY, OVERLAY_SM, OVERLAY_MD, OVERLAY_LG, OVERLAY_XL } from './grid/editors/overlay-presets';
export { EditorFocusTrap } from './grid/editors/editor-focus-trap';
export { OverlayViewportGuard } from './grid/editors/overlay-viewport-guard';

// -- Native cell content (DOM render payload) ---------------------------------
export { createSheetsCell } from './cell-model/create-sheets-cell';
export type { SheetsCell, SheetsCellKind } from './cell-model/sheets-cell';

import type { SheetsConfig } from '../context/sheets-context';

/**
 * Execute a GraphQL mutation against the auth endpoint.
 * Falls back to the data endpoint if authEndpoint is not configured.
 */
export async function executeAuthMutation<TResult = unknown>(
	config: SheetsConfig,
	query: string,
	variables?: Record<string, unknown>,
): Promise<TResult> {
	const url = config.authEndpoint || config.endpoint;
	if (!url) {
		throw new Error('No auth endpoint configured.');
	}

	const headers: Record<string, string> = {
		'Content-Type': 'application/json',
		Accept: 'application/graphql-response+json',
	};

	let response: Response;
	try {
		response = await fetch(url, {
			method: 'POST',
			headers,
			body: JSON.stringify({
				query,
				...(variables !== undefined && { variables }),
			}),
		});
	} catch (error) {
		throw new Error(
			`Network error: ${error instanceof Error ? error.message : 'Failed to connect to auth endpoint'}`,
		);
	}

	if (!response.ok) {
		const { status, statusText } = response;
		try {
			const body = await response.json();
			if (body.errors?.length) {
				const firstError = body.errors[0];
				const err = new Error(firstError.message || `Auth request failed: ${status}`);
				(err as any).code = firstError.extensions?.code;
				(err as any).errors = body.errors;
				throw err;
			}
		} catch (e) {
			if (e instanceof Error && (e as any).errors) throw e;
		}
		throw new Error(`Auth request failed: ${status} ${statusText}`);
	}

	const result = await response.json();

	if (result.errors?.length) {
		const firstError = result.errors[0];
		const err = new Error(firstError.message || 'Auth mutation failed');
		(err as any).code = firstError.extensions?.code;
		(err as any).errors = result.errors;
		throw err;
	}

	return result.data as TResult;
}

import { useState } from 'react';

import { useSheetsContext } from '../context/sheets-context';
import { useSheetsStore } from '../store/sheets-store';
import { useSheetsLogin } from './hooks/use-login';
import { useSheetsRegister } from './hooks/use-register';
import { useSheetsForgotPassword } from './hooks/use-forgot-password';
import { useSheetsResetPassword } from './hooks/use-reset-password';
import { SheetsLoginForm } from './ui/login-form';
import { SheetsRegisterForm } from './ui/register-form';
import { SheetsForgotPasswordForm } from './ui/forgot-password-form';
import { SheetsResetPasswordForm } from './ui/reset-password-form';
import { AuthScreenHeader, type AuthBrandingProps } from './ui/auth-screen-header';
import { AuthScreenLayout } from './ui/auth-screen-layout';

type AuthMode = 'login' | 'register' | 'forgot' | 'reset';

const AUTH_CONTENT: Record<AuthMode, { title: string; description: string }> = {
	login: {
		title: 'Welcome back',
		description: 'Sign in to your account',
	},
	register: {
		title: 'Create an account',
		description: 'Get started with your free account',
	},
	forgot: {
		title: 'Reset your password',
		description: "We'll send you a password reset link",
	},
	reset: {
		title: 'Set a new password',
		description: 'Enter your new password below',
	},
} as const;

export interface SheetsAuthGateProps extends AuthBrandingProps {
	children: React.ReactNode;
	loginComponent?: React.ComponentType;
	resetToken?: string;
	roleId?: string;
}

export function SheetsAuthGate({
	children,
	loginComponent: CustomLoginComponent,
	resetToken,
	roleId,
	logo,
	appName,
	showLogo,
}: SheetsAuthGateProps) {
	const { config } = useSheetsContext();
	const isAuthenticated = useSheetsStore((s) => s.isAuthenticated);

	// Embedded mode: auth gate is transparent, always renders children
	if (config.auth.mode === 'embedded') {
		return <>{children}</>;
	}

	// Standalone mode: check auth state
	if (isAuthenticated) {
		return <>{children}</>;
	}

	// Not authenticated in standalone mode — show login UI
	if (CustomLoginComponent) {
		return <CustomLoginComponent />;
	}

	return (
		<StandaloneAuthUI
			resetToken={resetToken}
			roleId={roleId}
			logo={logo}
			appName={appName}
			showLogo={showLogo}
		/>
	);
}

interface StandaloneAuthUIProps extends AuthBrandingProps {
	resetToken?: string;
	roleId?: string;
}

function StandaloneAuthUI({ resetToken, roleId, logo, appName, showLogo }: StandaloneAuthUIProps) {
	const initialMode: AuthMode = resetToken ? 'reset' : 'login';
	const [mode, setMode] = useState<AuthMode>(initialMode);

	const loginMutation = useSheetsLogin();
	const registerMutation = useSheetsRegister();
	const forgotPasswordMutation = useSheetsForgotPassword();
	const resetPasswordMutation = useSheetsResetPassword();

	const { title, description } = AUTH_CONTENT[mode];

	return (
		<AuthScreenLayout fill='parent' logo={logo} appName={appName} showLogo={showLogo}>
			<AuthScreenHeader
				title={title}
				description={description}
				logo={logo}
				appName={appName}
				showLogo={showLogo}
			/>

			<div>
				{mode === 'login' && (
					<SheetsLoginForm
						onLogin={(credentials) => loginMutation.mutateAsync(credentials).then(() => {})}
						onShowForgot={() => setMode('forgot')}
						onShowRegister={() => setMode('register')}
					/>
				)}
				{mode === 'register' && (
					<SheetsRegisterForm
						onRegister={(data) => registerMutation.mutateAsync(data)}
						onShowLogin={() => setMode('login')}
					/>
				)}
				{mode === 'forgot' && (
					<SheetsForgotPasswordForm
						onForgotPassword={(data) => forgotPasswordMutation.mutateAsync(data)}
						onShowLogin={() => setMode('login')}
					/>
				)}
				{mode === 'reset' && (
					<SheetsResetPasswordForm
						resetToken={resetToken || ''}
						roleId={roleId}
						onResetPassword={(input) => resetPasswordMutation.mutateAsync(input)}
						onShowLogin={() => setMode('login')}
					/>
				)}
			</div>
		</AuthScreenLayout>
	);
}

// ============================================================================
// Auth Result Types
// ============================================================================

export interface AuthResultRecord {
	id: string;
	userId: string;
	accessToken: string;
	accessTokenExpiresAt: string;
	isVerified?: boolean | null;
	totpEnabled?: boolean | null;
}

// ============================================================================
// Generic Helper
// ============================================================================

export type MutationVariables<TInput> = { input: TInput };

// ============================================================================
// SignIn Mutation
// ============================================================================

export interface SignInInput {
	email: string;
	password: string;
	rememberMe?: boolean;
}

export type SignInMutationVariables = MutationVariables<SignInInput>;

export interface SignInMutationResult {
	signIn?: {
		result?: AuthResultRecord | null;
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// SignUp Mutation
// ============================================================================

export interface SignUpInput {
	email: string;
	password: string;
}

export type SignUpMutationVariables = MutationVariables<SignUpInput>;

export interface SignUpMutationResult {
	signUp?: {
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Forgot Password Mutation
// ============================================================================

export interface ForgotPasswordInput {
	email: string;
}

export type ForgotPasswordMutationVariables = MutationVariables<ForgotPasswordInput>;

export interface ForgotPasswordMutationResult {
	forgotPassword?: {
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Reset Password Mutation
// ============================================================================

export interface ResetPasswordInput {
	newPassword: string;
	resetToken: string;
	roleId?: string;
}

export type ResetPasswordMutationVariables = MutationVariables<ResetPasswordInput>;

export interface ResetPasswordMutationResult {
	resetPassword?: {
		result?: boolean | null;
		clientMutationId?: string | null;
	} | null;
}

// ============================================================================
// Token Helper
// ============================================================================

export function toAuthToken(record: AuthResultRecord | null | undefined): { accessToken: string; expiresAt: string } | null {
	if (!record?.accessToken || !record?.accessTokenExpiresAt) {
		return null;
	}
	return {
		accessToken: record.accessToken,
		expiresAt: record.accessTokenExpiresAt,
	};
}

export { useSheetsLogin } from './use-login';
export { useSheetsRegister } from './use-register';
export { useSheetsForgotPassword } from './use-forgot-password';
export { useSheetsResetPassword } from './use-reset-password';

import { useMutation } from '@tanstack/react-query';

import { useSheetsContext } from '../../context/sheets-context';
import { executeAuthMutation } from '../auth-execute';
import type { ForgotPasswordMutationResult, ForgotPasswordMutationVariables } from '../auth-types';

const FORGOT_PASSWORD_MUTATION = /* GraphQL */ `
	mutation ForgotPassword($input: ForgotPasswordInput!) {
		forgotPassword(input: $input) {
			clientMutationId
		}
	}
`;

export function useSheetsForgotPassword() {
	const { config } = useSheetsContext();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'forgotPassword'],
		mutationFn: async ({ email }: { email: string }) => {
			await executeAuthMutation<ForgotPasswordMutationResult>(
				config,
				FORGOT_PASSWORD_MUTATION,
				{
					input: { email },
				} satisfies ForgotPasswordMutationVariables,
			);
			return { email };
		},
	});
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

import { createInvalidCredentialsError } from '../utils/auth-errors';
import type { LoginFormData } from '../utils/schemas';
import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsStoreApi } from '../../store/sheets-store';
import { setStoredToken } from '../utils/token-store';
import { executeAuthMutation } from '../auth-execute';
import { toAuthToken, type SignInMutationResult, type SignInMutationVariables } from '../auth-types';

const SIGN_IN_MUTATION = /* GraphQL */ `
	mutation SignIn($input: SignInInput!) {
		signIn(input: $input) {
			result {
				id
				userId
				accessToken
				accessTokenExpiresAt
				isVerified
				totpEnabled
			}
			clientMutationId
		}
	}
`;

export function useSheetsLogin() {
	const queryClient = useQueryClient();
	const { config } = useSheetsContext();
	const storeApi = useSheetsStoreApi();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'signIn'],
		mutationFn: async (credentials: LoginFormData) => {
			const result = await executeAuthMutation<SignInMutationResult>(
				config,
				SIGN_IN_MUTATION,
				{
					input: {
						email: credentials.email,
						password: credentials.password,
						rememberMe: credentials.rememberMe,
					},
				} satisfies SignInMutationVariables,
			);

			const signInResult = result.signIn?.result;
			if (!signInResult) {
				throw createInvalidCredentialsError();
			}

			const token = toAuthToken(signInResult);
			if (!token) {
				throw createInvalidCredentialsError();
			}

			return { token, email: credentials.email, identityKey: signInResult.userId };
		},
		onSuccess: ({ token, identityKey }) => {
			const databaseId = config.databaseId || 'default';
			setStoredToken(databaseId, token.accessToken, token.expiresAt, identityKey);
			storeApi.getState().setAuthenticated(token.accessToken, token.expiresAt, identityKey);
			queryClient.invalidateQueries({ queryKey: ['sheets'] });
		},
	});
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

import type { RegisterFormData } from '../utils/schemas';
import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsStoreApi } from '../../store/sheets-store';
import { executeAuthMutation } from '../auth-execute';
import { type SignUpMutationResult, type SignUpMutationVariables } from '../auth-types';

const SIGN_UP_MUTATION = /* GraphQL */ `
	mutation SignUp($input: SignUpInput!) {
		signUp(input: $input) {
			clientMutationId
		}
	}
`;

export function useSheetsRegister() {
	const queryClient = useQueryClient();
	const { config } = useSheetsContext();
	const storeApi = useSheetsStoreApi();

	return useMutation({
		mutationKey: ['sheets', 'auth', 'signUp'],
		mutationFn: async (formData: RegisterFormData) => {
			// sign_up never signs anyone in: the address is mailed a link that does
			await executeAuthMutation<SignUpMutationResult>(
				config,
				SIGN_UP_MUTATION,
				{
					input: {
						email: formData.email,
						password: formData.password,
					},
				} satisfies SignUpMutationVariables,
			);

			return { email: formData.email };
		},
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ['sheets'] });
		},
		onError: () => {
			storeApi.getState().setUnauthenticated();
		},
