				)}
			</div>
		);
	}

	return (
		<div className='space-y-5'>
			<AuthScreenHeader title='Set a new password' description='Enter your new password below' />

			<form
				onSubmit={(e) => {
					e.preventDefault();
					e.stopPropagation();
					form.handleSubmit();
				}}
				className='space-y-4 px-8'
			>
				<AuthErrorAlert error={error} />
				<form.Field
					name='password'
					validators={{
						onChange: ({ value }) => {
							if (!value) return 'Password is required';
							if (value.length < 8) return 'Password must be at least 8 characters';
							if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/.test(value)) {
								return 'Password must contain uppercase, lowercase, number, and special character';
							}
							return undefined;
						},
					}}
				>
					{(field) => (
						<div className='space-y-2'>
							<FormField
								field={field}
								label='New Password'
								placeholder='Enter your new password'
								type='password'
							/>
							<PasswordStrength password={field.state.value} />
						</div>
					)}
				</form.Field>

				<form.Field
					name='confirmPassword'
					validators={{
						onChange: ({ value }) => {
							if (!value) return 'Please confirm your password';
							const password = form.getFieldValue('password');
							if (value !== password) return 'Passwords do not match';
							return undefined;
						},
					}}
				>
					{(field) => (
						<FormField
							field={field}
							label='Confirm New Password'
							placeholder='Confirm your new password'
							type='password'
						/>
					)}
				</form.Field>

				<div className='pt-2'>
					<AuthLoadingButton
						type='submit'
						className='w-full'
						isLoading={isSubmitting}
						disabled={!form.state.canSubmit || isSubmitting}
						data-testid='auth-reset-submit'
					>
						Reset Password
					</AuthLoadingButton>
				</div>
			</form>

			{onShowLogin && (
				<div className='text-muted-foreground text-center text-sm'>
					Remember your password?{' '}
					<Button
						variant='link'
						className='text-primary hover:text-primary/80 h-auto p-0 font-medium'
						onClick={onShowLogin}
						type='button'
					>
						Sign in
					</Button>
				</div>
			)}
		</div>
	);
}

/**
 * Auth Error Handling
 *
 * Centralized error code mapping and parsing for auth forms.
 * Handles GraphQL errors, validation errors (Zod-like), and custom AuthErrors.
 *
 * Backend error codes handled:
 * - INCORRECT_PASSWORD: Wrong password
 * - PASSWORD_INSECURE: Password doesn't meet security requirements
 * - ACCOUNT_LOCKED_EXCEED_ATTEMPTS: Too many failed login attempts
 * - ACCOUNT_DISABLED: Account has been disabled
 * - ACCOUNT_EXISTS: Email already registered
 * - PASSWORD_LEN: Password length invalid (must be 8-63 characters)
 * - INVITE_NOT_FOUND: Invitation code not found
 * - INVITE_LIMIT: Invitation usage limit reached
 * - INVITE_EMAIL_NOT_FOUND: Email not associated with invitation
 */

// ============================================================================
// Error Code Constants
// ============================================================================

/**
 * Known backend error codes.
 * These codes are returned in GraphQL error extensions.
 */
export const ERROR_CODES = {
	// Auth errors - login
	INVALID_CREDENTIALS: 'INVALID_CREDENTIALS', // Generic - prevents user enumeration
	INCORRECT_PASSWORD: 'INCORRECT_PASSWORD',
	ACCOUNT_LOCKED_EXCEED_ATTEMPTS: 'ACCOUNT_LOCKED_EXCEED_ATTEMPTS',
	ACCOUNT_DISABLED: 'ACCOUNT_DISABLED',

	// Password validation errors
	PASSWORD_INSECURE: 'PASSWORD_INSECURE',
	PASSWORD_LEN: 'PASSWORD_LEN',

	// Registration errors
	ACCOUNT_EXISTS: 'ACCOUNT_EXISTS',

	// Invitation errors
	INVITE_NOT_FOUND: 'INVITE_NOT_FOUND',
	INVITE_LIMIT: 'INVITE_LIMIT',
	INVITE_EMAIL_NOT_FOUND: 'INVITE_EMAIL_NOT_FOUND',
} as const;

export type ErrorCode = (typeof ERROR_CODES)[keyof typeof ERROR_CODES];

// ============================================================================
// User-Friendly Error Messages
// ============================================================================

/**
 * User-friendly error messages for each error code.
 * These messages are shown to users in the UI.
 */
export const ERROR_MESSAGES: Record<ErrorCode, string> = {
	[ERROR_CODES.INVALID_CREDENTIALS]: 'Invalid email or password.',
	[ERROR_CODES.INCORRECT_PASSWORD]: 'The password you entered is incorrect. Please try again.',
	[ERROR_CODES.ACCOUNT_LOCKED_EXCEED_ATTEMPTS]:
		'Your account has been temporarily locked due to too many failed login attempts. Please try again later or reset your password.',
	[ERROR_CODES.ACCOUNT_DISABLED]:
		'Your account has been disabled. Please contact support for assistance.',
	[ERROR_CODES.PASSWORD_INSECURE]:
		'This password is not secure enough. Please choose a stronger password.',
	[ERROR_CODES.PASSWORD_LEN]: 'Password must be between 8 and 63 characters long.',
	[ERROR_CODES.ACCOUNT_EXISTS]:
		'An account with this email already exists. Please sign in or use a different email.',
	[ERROR_CODES.INVITE_NOT_FOUND]:
		'The invitation code is invalid or has expired. Please check the code or request a new invitation.',
	[ERROR_CODES.INVITE_LIMIT]:
		'This invitation has reached its usage limit. Please request a new invitation.',
	[ERROR_CODES.INVITE_EMAIL_NOT_FOUND]:
		'This email is not associated with the invitation. Please use the email address the invitation was sent to.',
};

/**
 * Generic fallback message when no specific error code is matched.
 */
export const DEFAULT_ERROR_MESSAGE = 'Something went wrong. Please try again.';

// ============================================================================
// AuthError Class
// ============================================================================

/**
 * Custom error class for authentication errors.
 * Provides typed error codes that map to user-friendly messages.
 *
 * @example
 * ```ts
 * // Throw with a known error code
 * throw new AuthError('INVALID_CREDENTIALS');
 *
 * // Throw with custom message override
 * throw new AuthError('ACCOUNT_DISABLED', 'Your account has been suspended.');
 *
 * // In catch block, get user-friendly message
 * catch (err) {
 *   if (err instanceof AuthError) {
 *     setError(err.userMessage);
 *   }
 * }
 * ```
 */
export class AuthError extends Error {
	public readonly code: ErrorCode;
	public readonly userMessage: string;

	constructor(code: ErrorCode, customMessage?: string) {
		const userMessage = customMessage ?? ERROR_MESSAGES[code];
		super(userMessage);
		this.name = 'AuthError';
		this.code = code;
		this.userMessage = userMessage;

		if (Error.captureStackTrace) {
			Error.captureStackTrace(this, AuthError);
		}
	}

	/**
	 * Check if an error is an AuthError with a specific code.
	 */
	static isCode(error: unknown, code: ErrorCode): error is AuthError {
		return error instanceof AuthError && error.code === code;
	}
}

/**
 * Create an AuthError for invalid credentials.
 * Use this when login fails due to null token response.
 * The generic message prevents user enumeration attacks.
 */
export function createInvalidCredentialsError(): AuthError {
	return new AuthError('INVALID_CREDENTIALS');
}

// ============================================================================
// Configuration
// ============================================================================

/**
 * Options for parseGraphQLError.
 */
export interface ParseGraphQLErrorOptions {
	/**
	 * Custom fallback message when no known error code is matched.
	 * Defaults to DEFAULT_ERROR_MESSAGE.
	 */
	defaultMessage?: string;

	/**
	 * Custom error code to message mapping to extend or override defaults.
	 * Merged with ERROR_MESSAGES (custom takes precedence).
	 */
	customMessages?: Record<string, string>;
}

// ============================================================================
// Error Parsing Utilities
// ============================================================================

/**
 * Shape of a GraphQL error with extensions.
 */
interface GraphQLErrorLike {
	message?: string;
	extensions?: {
		code?: string;
		[key: string]: unknown;
	};
}

/**
 * Check if a value looks like a GraphQL error object.
 */
function isGraphQLErrorLike(value: unknown): value is GraphQLErrorLike {
	if (!value || typeof value !== 'object') return false;
	return 'message' in value || 'extensions' in value;
}

/**
 * Shape of a validation error (Zod-like).
 * Detected by duck typing to avoid tight coupling to Zod.
 */
interface ValidationErrorLike {
	name: string;
	issues: Array<{ message: string; path?: (string | number)[] }>;
}

/**
 * Check if a value looks like a Zod validation error.
 * Uses duck typing (name + issues array) for portability.
 */
function isValidationError(value: unknown): value is ValidationErrorLike {
	if (!value || typeof value !== 'object') return false;
	const err = value as Record<string, unknown>;
	return (
		err.name === 'ZodError' &&
		Array.isArray(err.issues) &&
		err.issues.length > 0 &&
		typeof err.issues[0]?.message === 'string'
	);
}

/**
 * Extract error code from various error formats.
 *
 * Checks (in order):
 * 1. AuthError instance (has typed code)
 * 2. error.extensions.code (GraphQL error format)
 * 3. error.code (generic error format)
 * 4. Error code embedded in message (e.g., "Error (Code: ACCOUNT_EXISTS)")
 * 5. Direct code match in error message (e.g., "ACCOUNT_EXISTS")
 */
function extractErrorCode(error: unknown, knownCodes: string[]): string | null {
	// Handle AuthError instances
	if (error instanceof AuthError) {
		return error.code;
	}

	// Handle GraphQLRequestError (has .errors array with GraphQL error objects)
	if (error && typeof error === 'object' && 'errors' in error) {
		const gqlErrors = (error as { errors: Array<{ message?: string; extensions?: Record<string, unknown> }> })
			.errors;
		if (Array.isArray(gqlErrors) && gqlErrors.length > 0) {
			const firstError = gqlErrors[0];
			if (firstError.extensions?.code) return String(firstError.extensions.code);
			if (firstError.message) {
				const codeMatch = firstError.message.match(/\(\s*[Cc]ode:\s*([A-Z_]+)\s*\)/);
				if (codeMatch) return codeMatch[1];
				for (const code of knownCodes) {
					if (firstError.message.includes(code)) return code;
				}
			}
		}
	}

	// Handle GraphQL error with extensions
	if (isGraphQLErrorLike(error) && error.extensions?.code) {
		return String(error.extensions.code);
	}

	// Handle error object with code property
	if (error && typeof error === 'object' && 'code' in error) {
		const code = (error as { code: unknown }).code;
		if (typeof code === 'string') return code;
	}

	// Extract message for pattern matching
	let message: string | null = null;
	if (error instanceof Error) {
		message = error.message;
	} else if (isGraphQLErrorLike(error) && error.message) {
		message = error.message;
	} else if (typeof error === 'string') {
		message = error;
	}

	if (!message) return null;

	// Try to extract code from message pattern: "(Code: ERROR_CODE)"
	const codeMatch = message.match(/\(\s*[Cc]ode:\s*([A-Z_]+)\s*\)/);
	if (codeMatch) {
		return codeMatch[1];
	}

	// Check if any known error code appears in the message
	for (const code of knownCodes) {
		if (message.includes(code)) {
			return code;
		}
	}

	return null;
}

/**
 * Check if an error code is a known error code.
 */
export function isKnownErrorCode(code: string | null): code is ErrorCode {
	if (!code) return false;
	return Object.values(ERROR_CODES).includes(code as ErrorCode);
}

/**
 * Get the user-friendly message for an error code.
 */
export function getErrorMessage(code: ErrorCode): string {
	return ERROR_MESSAGES[code];
}

/**
 * Check if a message looks like technical/internal error (not user-friendly).
 */
function isTechnicalMessage(message: string): boolean {
	const lower = message.toLowerCase();
	return (
		lower.includes('graphql') ||
		lower.includes('fetch') ||
		lower.includes('network') ||
		lower.includes('econnrefused') ||
		lower.includes('undefined') ||
		lower.includes('null') ||
		lower.includes('timeout') ||
		lower.includes('connection') ||
		lower.includes('socket') ||
		lower.includes('enotfound') ||
		lower.includes('abort')
	);
}

// ============================================================================
// Main Parse Function
// ============================================================================

/**
 * Result of parsing a GraphQL error.
 */
export interface ParsedGraphQLError {
	/** The extracted error code, if any */
	code: string | null;
	/** User-friendly error message */
	message: string;
	/** Whether a known error code was found */
	isKnownError: boolean;
	/** Original error for debugging */
	originalError: unknown;
}

/**
 * Parse a GraphQL error and return a user-friendly message.
 *
 * This function:
 * 1. Extracts the error code from various error formats
 * 2. Maps known codes to user-friendly messages
 * 3. Falls back to generic message for unknown/technical errors
 *
 * @param error - The error to parse (can be Error, GraphQL error, string, etc.)
 * @param options - Optional configuration for custom messages
 * @returns ParsedGraphQLError with code, message, and metadata
 *
 * @example
 * ```ts
 * // Basic usage
 * const { message } = parseGraphQLError(error);
 * setError(message);
 *
 * // With custom default message
 * const { message } = parseGraphQLError(error, {
 *   defaultMessage: 'Unable to sign in. Please try again.'
 * });
 *
 * // With custom error code mappings
 * const { message } = parseGraphQLError(error, {
 *   customMessages: {
 *     'CUSTOM_ERROR': 'A custom error occurred.',
 *   }
 * });
 * ```
 */
export function parseGraphQLError(
	error: unknown,
	options: ParseGraphQLErrorOptions = {}
): ParsedGraphQLError {
	// Fast path for AuthError - already has user-friendly message
	if (error instanceof AuthError) {
		return {
			code: error.code,
			message: error.userMessage,
			isKnownError: true,
			originalError: error,
		};
	}

	// Handle validation errors (Zod-like) - detect by shape, not import
	// This keeps the module portable without tight coupling to Zod
	if (isValidationError(error)) {
		// Get the first error message (most relevant for form validation)
		const firstIssue = error.issues[0];
		const message = firstIssue?.message || 'Validation failed. Please check your input.';
		return {
			code: 'VALIDATION_ERROR',
			message,
			isKnownError: true,
			originalError: error,
		};
	}

	const { defaultMessage = DEFAULT_ERROR_MESSAGE, customMessages = {} } = options;

	// Merge custom messages with defaults (custom takes precedence)
	const allMessages: Record<string, string> = { ...ERROR_MESSAGES, ...customMessages };
	const allKnownCodes = Object.keys(allMessages);

	const code = extractErrorCode(error, allKnownCodes);
	const isKnown = code !== null && code in allMessages;

	let message: string;
	if (isKnown && code) {
		message = allMessages[code];
	} else {
		// Use error message if available and not technical
		if (error instanceof Error && error.message && !isTechnicalMessage(error.message)) {
			message = error.message;
		} else if (
			error instanceof Error &&
			isTechnicalMessage(error.message) &&
			'errors' in error &&
			Array.isArray((error as { errors: unknown[] }).errors)
		) {
			// Extract user-friendly message from GraphQLRequestError's inner errors
			const innerMsg = (
				(error as { errors: Array<{ message?: string }> }).errors[0] as { message?: string } | undefined
			)?.message;
			message = innerMsg && !isTechnicalMessage(innerMsg) ? innerMsg : defaultMessage;
		} else {
			message = defaultMessage;
		}
	}

	return {
		code: isKnown ? code : null,
		message,
		isKnownError: isKnown,
		originalError: error,
	};
}

import { z } from 'zod';

/**
 * Password validation schema with strong requirements
 */
const passwordSchema = z
	.string()
	.min(8, 'Password must be at least 8 characters')
	.regex(
		/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
		'Password must contain uppercase, lowercase, number, and special character',
	);

/**
 * Email validation schema
 */
const emailSchema = z.string().email('Please enter a valid email address');

/**
 * Login form validation schema
 */
export const loginSchema = z.object({
	email: emailSchema,
	password: z.string().min(1, 'Password is required'),
	rememberMe: z.boolean().optional(),
});

/**
 * Registration form validation schema
 * Backend only receives email/password - confirmPassword is frontend-only validation
 * Password strength is validated by backend to avoid duplicate/conflicting rules
 */
export const registerSchema = z
	.object({
		email: emailSchema,
		password: z.string().min(1, 'Password is required'),
		confirmPassword: z.string().min(1, 'Please confirm your password'),
	})
	.refine((data) => data.password === data.confirmPassword, {
		message: 'Passwords do not match',
		path: ['confirmPassword'],
	});

/**
 * Forgot password form validation schema
 */
export const forgotPasswordSchema = z.object({
	email: emailSchema,
});

/**
 * Reset password form validation schema
 */
export const resetPasswordSchema = z
	.object({
		password: passwordSchema,
		confirmPassword: z.string(),
		token: z.string().min(1, 'Reset token is required'),
	})
	.refine((data) => data.password === data.confirmPassword, {
		message: 'Passwords do not match',
		path: ['confirmPassword'],
	});

/**
 * TypeScript types inferred from schemas
 */
export type LoginFormData = z.infer<typeof loginSchema>;
export type RegisterFormData = z.infer<typeof registerSchema>;
export type ForgotPasswordFormData = z.infer<typeof forgotPasswordSchema>;
export type ResetPasswordFormData = z.infer<typeof resetPasswordSchema>;

const KEY_PREFIX = 'sheets-auth-token';

function storageKey(databaseId: string): string {
	return `${KEY_PREFIX}:${databaseId}`;
}

function getStorage(): Storage | null {
	if (typeof window === 'undefined') return null;
	try {
		return window.localStorage;
	} catch {
		return null;
	}
}

export interface StoredToken {
	accessToken: string;
	expiresAt: string;
	identityKey?: string | null;
}

export function getStoredToken(databaseId: string): StoredToken | null {
	const storage = getStorage();
	if (!storage) return null;

	try {
		const raw = storage.getItem(storageKey(databaseId));
		if (!raw) return null;
		const parsed = JSON.parse(raw) as StoredToken;
		if (!parsed.accessToken || !parsed.expiresAt) return null;
		if (parsed.identityKey != null && typeof parsed.identityKey !== 'string') return null;
		return parsed;
	} catch {
		return null;
	}
}

export function setStoredToken(
	databaseId: string,
	accessToken: string,
	expiresAt: string,
	identityKey?: string | null,
): void {
	const storage = getStorage();
	if (!storage) return;

	try {
		const data: StoredToken = { accessToken, expiresAt, identityKey };
		storage.setItem(storageKey(databaseId), JSON.stringify(data));
	} catch {
		// Silently fail — localStorage might be full or unavailable
	}
}

export function clearStoredToken(databaseId: string): void {
	const storage = getStorage();
	if (!storage) return;

	try {
		storage.removeItem(storageKey(databaseId));
	} catch {
		// Silently fail
	}
}

/**
 * Custom validation functions for authentication forms
 */

/**
 * Calculate password strength score (0-5)
 */
export function getPasswordStrength(password: string): number {
	let score = 0;

	// Length check
	if (password.length >= 8) score++;

	// Character variety checks
	if (/[a-z]/.test(password)) score++;
	if (/[A-Z]/.test(password)) score++;
	if (/\d/.test(password)) score++;
	if (/[@$!%*?&]/.test(password)) score++;

	return score;
}

/**
 * Get password strength label
 */
export function getPasswordStrengthLabel(score: number): string {
	const labels = ['Very Weak', 'Weak', 'Fair', 'Good', 'Strong'];
	return labels[score - 1] || 'Very Weak';
}

/**
 * Get password strength color class
 */
export function getPasswordStrengthColor(score: number): string {
	const colors = ['bg-red-500', 'bg-orange-500', 'bg-yellow-500', 'bg-blue-500', 'bg-green-500'];
	return colors[score - 1] || 'bg-red-500';
}

/**
 * Validate email format (additional validation beyond zod)
 */
export function validateEmail(email: string): boolean {
	const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
	return emailRegex.test(email);
}

/**
 * Check if password meets minimum requirements
 */
export function isPasswordValid(password: string): boolean {
	return getPasswordStrength(password) >= 3;
}

/**
 * Async email availability check (placeholder - integrate with your API)
 */
export async function checkEmailAvailability(email: string): Promise<boolean> {
	// Placeholder implementation - replace with actual API call
	return new Promise((resolve) => {
		setTimeout(() => {
			// Simulate API call
			const unavailableEmails = ['admin@example.com', 'test@example.com'];
			resolve(!unavailableEmails.includes(email));
		}, 500);
	});
}

/**
 * Validate password confirmation
 */
export function validatePasswordConfirmation(password: string, confirmPassword: string): boolean {
	return password === confirmPassword && password.length > 0;
}

// The badge / category color system (DESIGN_SPEC §7) — the signature element.
//
// Category pills render as a tinted chip: a soft same-hue background paired with
// saturated same-hue text. The DEFAULT tone is `neutral`; color is OPT-IN. The
// consumer assigns a tone per value via a `Record<string, BadgeTone>` overrides
// map (exact value -> tone) or a `(value) => BadgeTone | undefined` resolver
// (e.g. CRM grids letting users color their own categories). There is NO
// automatic hashing — an unconfigured grid stays calm and on-brand, resolving
// every value to `neutral`.
//
// `neutral` is the only tone built from semantic tokens (so it themes for free);
// the 8-hue categorical palette below is intentional data-viz color and ships
// explicit `dark:` pairs — the one sanctioned exception to the tokens-not-palette
// law (§6).

export type BadgeTone = 'neutral' | 'blue' | 'green' | 'amber' | 'red' | 'purple' | 'pink' | 'teal';

export const BADGE_TONES: Record<BadgeTone, string> = {
	neutral: 'bg-muted text-muted-foreground',
	blue: 'bg-blue-50 text-blue-700 dark:bg-blue-500/15 dark:text-blue-300',
	green: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300',
	amber: 'bg-amber-50 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300',
	red: 'bg-rose-50 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300',
	purple: 'bg-violet-50 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300',
	pink: 'bg-pink-50 text-pink-700 dark:bg-pink-500/15 dark:text-pink-300',
	teal: 'bg-teal-50 text-teal-700 dark:bg-teal-500/15 dark:text-teal-300',
};

/**
 * Resolve a badge value to its tone. Resolution order (first hit wins):
 *   1. `overrides[value]` — exact value -> tone map.
 *   2. `resolver?.(value)` — programmatic resolver.
 *   3. `'neutral'` — the default; color is neutral-until-configured.
 *
 * No automatic hashing: an unmapped value is always `neutral`.
 */
export function resolveBadgeTone(
	value: string,
	overrides?: Record<string, BadgeTone>,
	resolver?: (v: string) => BadgeTone | undefined,
): BadgeTone {
	return overrides?.[value] ?? resolver?.(value) ?? 'neutral';
}

// Public component contract for a native DOM cell view. Pure types.

import type { CellType } from '../cell-types/types';
import type { SheetsCell } from './sheets-cell';

/** Smallest render-column descriptor a cell view needs now. Overridable. */
export interface CellColumnDescriptor {
	key: string;
	name: string;
	cellType: CellType;
}

/** Props every native cell view receives. Minimal and overridable. */
export interface CellProps {
	cell: SheetsCell;
	value: unknown;
	colKey: string;
	rowId: string;
	rowIndex: number;
	column: CellColumnDescriptor;
	isEditing: boolean;
	onStartEdit: () => void;
	disabled: boolean;
	readOnlyReason?: string;
	/** True when this is the grid's active (keyboard cursor) cell; a view may then offer actions (for example open a linked record). */
	isActive?: boolean;
}

// Consumer-facing cell-component override slots. A thin sugar over the native
// `cell` field of a CellTypeDefinition: a `CellSlots` map (keyed by cell typeKey)
// compiles down to component-only CellTypeDefinitions that the registry resolves
// via `getCellComponent`. Pure logic — no React render, no glide.

import type { CellTypeDefinition } from '../cell-types/define-cell-type';
import type { CellProps } from './cell-props';
import type { EditorProps } from '../grid-dom/editors/editor-props';

/**
 * A single slot: either a bare cell component, or an object overriding the cell
 * view and/or the native editor for a typeKey. The object form lets a consumer
 * override JUST the editor (`{ editor: MyEditor }`) without touching the view.
 */
export type CellSlot =
	| React.ComponentType<CellProps>
	| { cell?: React.ComponentType<CellProps>; editor?: React.ComponentType<EditorProps> };

/** Consumer cell-component / editor overrides keyed by cell typeKey. */
export type CellSlots = Record<string, CellSlot>;

/**
 * Compile a {@link CellSlots} map into {@link CellTypeDefinition}s. The function
 * form yields `{ typeKey, cell }` (view-only); the object form yields
 * `{ typeKey, cell?, editorComponent? }`. Entries that resolve to neither a cell
 * nor an editor (e.g. `{ json: {} }`) are skipped. Returns `[]` for empty/undefined.
 */
export function compileSlots(slots: CellSlots | undefined): CellTypeDefinition[] {
	if (!slots) return [];
	const defs: CellTypeDefinition[] = [];
	for (const [typeKey, slot] of Object.entries(slots)) {
		if (typeof slot === 'function') {
			defs.push({ typeKey, cell: slot });
			continue;
		}
		const { cell, editor } = slot;
		if (!cell && !editor) continue;
		defs.push({ typeKey, cell, editorComponent: editor });
	}
	return defs;
}

// The SheetsCell DISPATCHER — the native analogue of v1's `createCellContent`
// (grid/cell-content-factory.ts). Given a (value, metadata) it selects the first
// family factory whose `canHandle(cellType, value)` is true and returns its
// neutral {@link SheetsCell} render payload. Geometry stays out-of-band: the
// optional `deriveGeometry` hook is threaded straight through to the geometry
// factory (v1's `createGeometryCell` mirror) so this module never imports the
// leaflet-backed geometry view.
//
// Precedence MIRRORS v1 CELL_FACTORIES exactly (image, uri, badges, dateTime,
// interval, geometry, relation, number, boolean, text) — `text` is the universal
// fallback and MUST stay last. Null handling mirrors `createEmptyCell`: pick the
// first factory that claims the cellType for a null value and let it emit its own
// empty cell.

import type { CellType } from '../cell-types/types';
import type { CellCreationMetadata } from '../grid/grid-cell-types';
import { badgesSheetsCellFactory } from './factories/badges';
import { booleanSheetsCellFactory } from './factories/boolean';
import { choiceSheetsCellFactory } from './factories/choice';
import { dateTimeSheetsCellFactory } from './factories/datetime';
import { geometrySheetsCellFactory } from './factories/geometry';
import { imageSheetsCellFactory } from './factories/image';
import { intervalSheetsCellFactory } from './factories/interval';
import { numberSheetsCellFactory } from './factories/number';
import { relationSheetsCellFactory } from './factories/relation';
import { structuredSheetsCellFactory } from './factories/structured';
import { textSheetsCellFactory } from './factories/text';
import type { SheetsCellFactory } from './factories/types';
import { uriSheetsCellFactory } from './factories/uri';
import type { SheetsCell } from './sheets-cell';

// Registry of all SheetsCell factories — SAME precedence as glide CELL_FACTORIES
// (more specific first; the text fallback MUST be last).
const SHEETS_CELL_FACTORIES: SheetsCellFactory[] = [
	imageSheetsCellFactory,
	uriSheetsCellFactory,
	choiceSheetsCellFactory,
	badgesSheetsCellFactory,
	dateTimeSheetsCellFactory,
	intervalSheetsCellFactory,
	structuredSheetsCellFactory,
	geometrySheetsCellFactory,
	relationSheetsCellFactory,
	numberSheetsCellFactory,
	booleanSheetsCellFactory,
	textSheetsCellFactory, // Fallback — must be last.
];

/**
 * Build the neutral {@link SheetsCell} for a (value, metadata). Mirrors v1
 * `createCellContent`: null/undefined → the first claiming factory's empty cell
 * (mirror of `createEmptyCell`); otherwise the first factory whose
 * `canHandle(cellType, value)` is true. `deriveGeometry` is threaded to the
 * geometry factory unchanged. The `text` factory's `canHandle` always returns
 * true, so a factory is always found and the explicit final fallback below is a
 * defensive belt-and-braces guard.
 */
/**
 * Stamp the resolved cellType onto the cell's `meta` so the cell SELF-DESCRIBES
 * its type (the host reads `SheetsCellResolution.typeKey`, but the cell carrying
 * `meta.cellType` keeps it self-contained for the editor adapters that already
 * read it — date/geometry). MERGE (not replace) so any factory-set meta key
 * (e.g. geometry's `geometryType`) survives. This does not change display or
 * copy text because projection ignores `meta`.
 */
function withTypeKey(cell: SheetsCell, cellType: string): SheetsCell {
	return { ...cell, meta: { ...cell.meta, cellType: cellType as CellType } };
}

export function createSheetsCell(
	value: unknown,
	metadata: CellCreationMetadata,
	deriveGeometry?: (value: unknown) => SheetsCell,
): SheetsCell {
	const { cellType } = metadata;

	if (value === null || value === undefined) {
		const emptyFactory = SHEETS_CELL_FACTORIES.find((f) => f.canHandle(cellType, null));
		if (emptyFactory) {
			return withTypeKey(emptyFactory.create(null, metadata, deriveGeometry), cellType);
		}
		return withTypeKey({ kind: 'text', data: '', displayData: '', readonly: false }, cellType);
	}

	const factory = SHEETS_CELL_FACTORIES.find((f) => f.canHandle(cellType, value));
	if (factory) {
		return withTypeKey(factory.create(value, metadata, deriveGeometry), cellType);
	}

	return withTypeKey(
		{
			kind: 'text',
			data: value,
			displayData: String(value),
			readonly: false,
		},
		cellType,
	);
}

// Badges SheetsCell factory — native analogue of v1 `ArrayCellFactory`.
//
// Owns the array/bubble family: every array-like cellType plus `tsvector`. The
// glide `BubbleCell` carries `data: string[]` and NO `displayData`, so the
// neutral payload mirrors that exactly — `data` is the string[] (copyText ===
// JSON.stringify(array)), `displayData` is '' (no display side in v1), and the
// kind is the neutral `badges`. ALL domain logic from v1 is ported verbatim
// (tags array/comma-string, tsvector lexeme preview, generic per-item
// stringify, null/undefined -> [], non-array fallback -> [String(value)]); the
// tsvector parser is copied in so this file never imports the glide factory
// (which is deleted at cutover).

import type { CellType } from '../../cell-types/types';
import { isArrayCellType } from '../../cell-types/cell-type-groups';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

// Minimal tsvector parser for previews — copied verbatim from v1
// cell-content-factory.ts (do NOT import it; it stays glide-only).
function parseTsvectorForPreview(tsvector: string): Array<{ lexeme: string; weights: Array<'A' | 'B' | 'C' | 'D'> }> {
	if (!tsvector || typeof tsvector !== 'string') return [];
	const results: Array<{ lexeme: string; weights: Array<'A' | 'B' | 'C' | 'D'> }> = [];
	try {
		const regex = /'([^']+)':([0-9A-D,]+)/g;
		let match: RegExpExecArray | null;
		while ((match = regex.exec(tsvector)) !== null) {
			const lexeme = match[1];
			const posStr = match[2];
			const weights = Array.from(
				new Set(
					posStr
						.split(',')
						.map((p) => p.match(/[A-D]$/)?.[0] as 'A' | 'B' | 'C' | 'D' | undefined)
						.filter((w): w is 'A' | 'B' | 'C' | 'D' => !!w),
				),
			).sort();
			results.push({ lexeme, weights });
		}
	} catch {
		// ignore parsing errors
	}
	return results;
}

// Compute the string[] the v1 BubbleCell put in `.data`, branch-for-branch.
function deriveBadges(value: unknown, metadata: CellCreationMetadata): string[] {
	if (value === null || value === undefined) {
		return [];
	}

	if (metadata.cellType === 'tags') {
		if (Array.isArray(value)) {
			return value.map((v) => (v == null ? '' : String(v))).filter((v) => v.length > 0);
		}
		if (typeof value === 'string') {
			return value
				.split(',')
				.map((v) => v.trim())
				.filter((v) => v.length > 0);
		}
	}

	if (metadata.cellType === 'tsvector' && typeof value === 'string') {
		const tokens = parseTsvectorForPreview(value);
		return tokens.map((t) => (t.weights.length ? `${t.lexeme} ${t.weights.join(',')}` : t.lexeme));
	}

	if (Array.isArray(value)) {
		return value.map((item) => {
			if (item === null || item === undefined) return '';
			if (typeof item === 'string') return item;
			if (typeof item === 'number') return String(item);
			if (typeof item === 'boolean') return String(item);
			if (item instanceof Date) return item.toISOString().split('T')[0];
			if (typeof item === 'object') return JSON.stringify(item);
			return String(item);
		});
	}

	return [String(value)];
}

export const badgesSheetsCellFactory: SheetsCellFactory = {
	canHandle(cellType: string, _value: unknown): boolean {
		return isArrayCellType(cellType) || cellType === 'tsvector';
	},

	create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
		return {
			kind: 'badges',
			data: deriveBadges(value, metadata),
			displayData: '',
			readonly: false,
			meta: { cellType: metadata.cellType as CellType },
		};
	},
};

// Boolean SheetsCell factory — native analogue of v1's BooleanCellFactory
// (grid/cell-content-factory.ts). Claims BOOLEAN_TYPES (boolean, toggle).
//
// The cell keeps the boolean in `data` for the view and leaves `displayData` empty
// because the view owns its visual representation. A null value stays null (an
// empty cell), so "no value" never shows as false.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { BOOLEAN_TYPES } from '../../cell-types/cell-type-groups';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return BOOLEAN_TYPES.has(cellType);
}

function create(value: unknown, _metadata: CellCreationMetadata): SheetsCell {
	const boolValue = value === null || value === undefined ? null : typeof value === 'boolean' ? value : Boolean(value);
	return { kind: 'boolean', data: boolValue, displayData: '', readonly: false };
}

export const booleanSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Choice SheetsCell factory — enum columns and text columns with an allowed-values
// list (`select`, `multi-select`). The stored value is the wire value; the cell shows
// each value's label as a badge. A stored value that is not in the option list still
// shows, as it is.

import type { CellType } from '../../cell-types/types';
import { CHOICE_TYPES } from '../../cell-types/cell-type-groups';
import { choiceLabel } from '../../cell-types/column-value';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return CHOICE_TYPES.has(cellType);
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const values = value === null || value === undefined ? [] : Array.isArray(value) ? value : [value];
	const labels = values.filter((entry) => entry !== null && entry !== undefined).map((entry) => choiceLabel(metadata.column, entry));
	return {
		kind: 'badges',
		data: labels,
		displayData: labels.join(', '),
		readonly: false,
		meta: { cellType: metadata.cellType as CellType },
	};
}

export const choiceSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// SheetsCell factory for the datetime family (date, datetime, time, timestamptz): a
// neutral `text` cell shown by the one date and time rule (`formatDateTimeText`: a date
// as stored, a time "HH:mm:ss" and a date and time "YYYY-MM-DD HH:mm:ss" with fractions
// only when not zero, a zoned value in the viewer's zone). `data` keeps the exact
// stored text; the title shows it with the zone used. Copy and export read the raw
// value. No value is ''.

import type { CellType } from '../../cell-types/types';
import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import { dateTimeKindOf, dateTimeTitle, formatDateTimeText } from '../../cell-types/date-time-format';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return DATE_TIME_TYPES.has(cellType);
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const meta = { cellType: metadata.cellType as CellType };

	if (value === null || value === undefined) {
		return { kind: 'text', data: '', displayData: '', readonly: false, meta };
	}

	const text = String(value);
	const kind = dateTimeKindOf(metadata.cellType);
	if (!kind) return { kind: 'text', data: text, displayData: text, readonly: false, meta };
	const shown = formatDateTimeText(text, kind);
	return { kind: 'text', data: text, displayData: shown.text, readonly: false, meta: { ...meta, title: dateTimeTitle(text, shown.zone) } };
}

export const dateTimeSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Geometry SheetsCell factory — native analogue of v1 `GeometryCellFactory`.
//
// Owns GEOMETRY_TYPES (geometry, geometry-point, geometry-collection). Geometry
// stays out-of-band: when the caller supplies a `deriveGeometry` builder (the
// native mirror of v1's `createGeometryCell`), this factory delegates to it so
// this module never imports the leaflet-backed geometry view. Without a builder,
// it falls back to a compact JSON preview as both the copy value and the display
// string — identical to v1's Text fallback.
//
// Copy and display text intentionally use the same compact JSON preview when no
// geometry-specific builder is available.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { GEOMETRY_TYPES } from '../../cell-types/cell-type-groups';
import { summarizeShape } from '../../cell-types/shape-kind';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return GEOMETRY_TYPES.has(cellType);
}

function create(
	value: unknown,
	_metadata: CellCreationMetadata,
	deriveGeometry?: (value: unknown) => SheetsCell,
): SheetsCell {
	if (deriveGeometry) {
		return deriveGeometry(value ?? null);
	}

	// No value: an empty cell, like every other kind (not the text "null").
	const summary = summarizeShape(value);
	if (!summary) return { kind: 'geometry', data: '', displayData: '', readonly: false };

	// The view shows the summary (kind and part count); the compact JSON stays the text
	// for the title. A value that cannot be read as a shape carries the reason.
	const display = compactJsonPreview(value, 80);
	return {
		kind: 'geometry',
		data: display,
		displayData: display,
		readonly: false,
		meta: { shapeLabel: summary.label, shapeCategory: summary.category, shapeProblem: summary.problem },
	};
}

export const geometrySheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Native SheetsCell factory for file columns: image, upload, lists of uploads,
// and attachment links (the MEDIA family).
//
// `data` holds the durable URL of each file (`['']` for an empty single cell),
// so copy and export carry stored URLs only. A signed preview URL never enters
// this payload: it expires. `meta` carries the column and table models so the
// view can resolve previews and show the column's upload state.

import type { ColumnModel, TableModel } from '@constructive-io/data';

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { MEDIA_TYPES } from '../../cell-types/cell-type-groups';
import { storedFilesOf } from '../../utils/file.utils';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

/** What a file cell's `meta` carries beside its cell type. */
export interface FileCellMeta {
	cellType: CellType;
	/** The column model, or null when the grid has not modeled the column. */
	column: ColumnModel | null;
	/** The table model, or null. */
	table: TableModel | null;
}

/** The file meta of a cell, when the cell is a file cell. */
export function fileCellMetaOf(cell: SheetsCell): FileCellMeta | null {
	const meta = cell.meta as Partial<FileCellMeta> | undefined;
	if (!meta?.cellType) return null;
	return { cellType: meta.cellType, column: meta.column ?? null, table: meta.table ?? null };
}

export const imageSheetsCellFactory: SheetsCellFactory = {
	canHandle(cellType: string): boolean {
		return MEDIA_TYPES.has(cellType);
	},

	create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
		const column = metadata.column ?? null;
		const files = storedFilesOf(value, column?.value.file);
		const urls = files.map((file) => file.url ?? '');
		const data = urls.length > 0 ? urls : [''];
		const meta: FileCellMeta = { cellType: metadata.cellType as CellType, column, table: metadata.table ?? null };
		return {
			kind: 'image',
			data,
			displayData: JSON.stringify(data),
			readonly: false,
			meta: { ...meta },
		};
	}
};

// Interval SheetsCell factory — native analogue of v1 `IntervalCellFactory`
// (grid/cell-content-factory.ts). Claims `cellType === 'interval'` and emits a
// neutral `text` SheetsCell whose displayData is the compact interval label and
// whose data is the raw string (or JSON of the object). The display/copy
// projection parity with the glide factory is the whole point of this phase.
//
// `formatIntervalForDisplay` (+ its `IntervalValue` shape) is interval-only domain
// logic copied VERBATIM from cell-content-factory.ts — it is intentionally NOT
// imported, because that module stays glide-only and is deleted at cutover.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

// PostgreSQL interval value structure
interface IntervalValue {
	years?: number;
	months?: number;
	days?: number;
	hours?: number;
	minutes?: number;
	seconds?: number;
}

/**
 * Format a PostgreSQL interval value for compact cell display.
 * Shows only non-zero units in descending order of magnitude.
 * Examples: "1y 6mo", "2h 30m", "7d", "45s"
 */
function formatIntervalForDisplay(value: unknown): string {
	if (value === null || value === undefined) return '';

	let interval: IntervalValue;

	if (typeof value === 'string') {
		try {
			interval = JSON.parse(value);
		} catch {
			if (/\d+[yMwdhms]/.test(value)) {
				return value;
			}
			return value;
		}
	} else if (typeof value === 'object') {
		interval = value as IntervalValue;
	} else {
		return String(value);
	}

	const parts: string[] = [];

	if (interval.years && interval.years !== 0) {
		parts.push(`${interval.years}y`);
	}
	if (interval.months && interval.months !== 0) {
		parts.push(`${interval.months}mo`);
	}
	if (interval.days && interval.days !== 0) {
		parts.push(`${interval.days}d`);
	}
	if (interval.hours && interval.hours !== 0) {
		parts.push(`${interval.hours}h`);
	}
	if (interval.minutes && interval.minutes !== 0) {
		parts.push(`${interval.minutes}m`);
	}
	if (interval.seconds && interval.seconds !== 0) {
		// Seconds show as stored (6.789s); a rounded display would hide part of the value.
		parts.push(`${interval.seconds}s`);
	}

	if (parts.length === 0) {
		return '0s';
	}

	return parts.join(' ');
}

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'interval';
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	if (value === null || value === undefined) {
		return {
			kind: 'text',
			data: '',
			displayData: '',
			readonly: false,
			meta: { cellType: metadata.cellType as CellType },
		};
	}

	const displayValue = formatIntervalForDisplay(value);
	const dataValue = typeof value === 'string' ? value : JSON.stringify(value);

	return {
		kind: 'text',
		data: dataValue,
		displayData: displayValue,
		readonly: false,
		meta: { cellType: metadata.cellType as CellType },
	};
}

export const intervalSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Number SheetsCell factory — native analogue of v1's NumberCellFactory
// (grid/cell-content-factory.ts). Claims NUMBER_TYPES (number, integer, smallint,
// bigint, decimal, currency, percentage, AND `rating` — `rating` lives in NUMBER_TYPES
// so the number family wins it before the text fallback; a deliberate v1 quirk).
//
// A string value is an exact decimal (whole numbers beyond 2^53, exact decimals,
// "NaN", "Infinity") and is shown digit for digit: it is never parsed into a JS
// number. A number value shows as its string form. Null is an empty cell.

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { NUMBER_TYPES } from '../../cell-types/cell-type-groups';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return NUMBER_TYPES.has(cellType);
}

function create(value: unknown, _metadata: CellCreationMetadata): SheetsCell {
	if (value === null || value === undefined || value === '') {
		return { kind: 'number', data: undefined, displayData: '', readonly: false };
	}
	if (typeof value === 'string') {
		return { kind: 'number', data: value, displayData: value, readonly: false };
	}
	if (typeof value === 'number') {
		return { kind: 'number', data: value, displayData: String(value), readonly: false };
	}
	return { kind: 'number', data: undefined, displayData: String(value), readonly: false };
}

export const numberSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Native SheetsCell factory for the `relation` family. Single relations
// (belongsTo/hasOne) render one label; list relations (hasMany/manyToMany)
// render chips and a "+N more" overflow counted from the connection total
// when the model says the relation reports one.
//
// Labels come from the related table's display rule
// (`RelationModel.target.labelFields`, host override included); a record
// whose label fields are empty shows its key value. No field-name lists.
//
// Cell payload:
//   - single: data = displayData = the (truncated) label; meta.relationTitle = full label.
//   - list:   data = string[] chips (truncated), plus a trailing "+N" when more exist;
//             meta.relationTitles = full chip labels, meta.relationCount = every linked record.
//   - both:   meta.relationTarget = { tableKey, tableName } of the related table (or null) and
//             meta.relationLinks = one { key, label } per shown record, `key` being its
//             primary-key values (null when it cannot be identified), so the view can open it.

import type { RelationModel, RelationTargetModel } from '@constructive-io/data';

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { fieldValues, linkFields } from '../../relations/relation-keys';
import { targetRecordLabel } from '../../relations/relation-label';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

const DEFAULT_MAX_RELATION_CHIPS = 3;
const DEFAULT_RELATION_LABEL_MAX_LEN = 24;
const DRAFT_PREFIX = 'draft:';

function truncateLabel(s: string, max: number): string {
	if (s.length <= max) return s;
	if (max <= 1) return '…';
	return s.slice(0, Math.max(0, max - 1)) + '…';
}

function isDraftKey(value: unknown): boolean {
	return typeof value === 'string' && value.startsWith(DRAFT_PREFIX);
}

interface LabelRule {
	target: RelationTargetModel;
	fallbackFields: readonly string[];
}

/** A shown linked record the view can open: its primary-key values and full label. */
export interface RelationCellLink {
	key: Readonly<Record<string, unknown>> | null;
	label: string;
}

function linkOf(entry: unknown, label: string, rule: LabelRule): RelationCellLink {
	const record = entry && typeof entry === 'object' && !Array.isArray(entry) ? (entry as Record<string, unknown>) : null;
	return { key: fieldValues(record, rule.target.primaryKey), label };
}

function targetOf(metadata: CellCreationMetadata): { tableKey: string; tableName: string } | null {
	const relation = metadata.relation ?? metadata.relationInfo?.relation ?? null;
	return relation?.targetKey ? { tableKey: relation.targetKey, tableName: relation.targetName } : null;
}

function labelRuleOf(metadata: CellCreationMetadata): LabelRule {
	const relation: RelationModel | null = metadata.relation ?? metadata.relationInfo?.relation ?? null;
	if (relation) return { target: relation.target, fallbackFields: linkFields(relation) };
	return { target: { primaryKey: [], labelFields: metadata.relationInfo?.displayCandidates ?? [] }, fallbackFields: [] };
}

/** The full label of one related record; '' for nothing or for a draft placeholder. */
function recordLabel(entry: unknown, rule: LabelRule): string {
	if (entry === null || entry === undefined) return '';
	if (typeof entry === 'string' || typeof entry === 'number') {
		return isDraftKey(entry) ? '' : String(entry).trim();
	}
	if (typeof entry !== 'object' || Array.isArray(entry)) return '';
	const record = entry as Record<string, unknown>;
	if (rule.target.primaryKey.some((field) => isDraftKey(record[field]))) return '';
	return targetRecordLabel(record, rule.target, rule.fallbackFields);
}

function isListRelation(metadata: CellCreationMetadata): boolean {
	const kind = metadata.relation?.kind ?? metadata.relationInfo?.kind;
	return kind === 'hasMany' || kind === 'manyToMany';
}

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'relation';
}

function create(value: unknown, metadata: CellCreationMetadata, _deriveGeometry?: (value: unknown) => SheetsCell): SheetsCell {
	const relOptions = metadata.relationOptions;
	const chipLimit = relOptions?.relationChipLimit ?? DEFAULT_MAX_RELATION_CHIPS;
	const labelMax = relOptions?.relationLabelMaxLength ?? DEFAULT_RELATION_LABEL_MAX_LEN;
	const rule = labelRuleOf(metadata);

	const relationTarget = targetOf(metadata);

	if (isListRelation(metadata)) {
		const entries = Array.isArray(value) ? value : [];
		const labelled = entries
			.map((entry) => ({ entry, label: recordLabel(entry, rule) }))
			.filter((item) => item.label.length > 0);
		const labels = labelled.map((item) => item.label);
		const shown = labels.slice(0, chipLimit);
		const relationLinks = labelled.slice(0, chipLimit).map((item) => linkOf(item.entry, item.label, rule));
		const reported = metadata.relationTotalCount;
		const count = typeof reported === 'number' && reported >= labels.length ? reported : labels.length;
		const remaining = count - shown.length;
		const chips = shown.map((label) => truncateLabel(label, labelMax));
		return {
			kind: 'relation',
			data: remaining > 0 ? [...chips, `+${remaining}`] : chips,
			displayData: '',
			readonly: false,
			meta: { relationTitles: shown, relationCount: count, relationTarget, relationLinks },
		};
	}

	const single = Array.isArray(value) ? value[0] : value;
	const full = recordLabel(single, rule);
	const label = truncateLabel(full, labelMax);
	const relationLinks = full ? [linkOf(single, full, rule)] : [];
	return {
		kind: 'relation',
		data: label,
		displayData: label,
		readonly: false,
		meta: { relationTitle: full, relationTarget, relationLinks },
	};
}

export const relationSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Structured-value SheetsCell factory — JSON, ranges, records, points and the
// view-only kinds (raw bytes, number vectors, values of an unknown kind). Each value
// renders as compact, readable text; the full value stays in the row for copy and for
// the viewer or editor overlay.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import { fieldLabel } from '../../cell-types/field-label';
import { dateTimeTitle, formatDateTimeText, isTimestampText } from '../../cell-types/date-time-format';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

const STRUCTURED_CELL_TYPES: ReadonlySet<string> = new Set([
	'json',
	'jsonb',
	'range',
	'composite',
	'point',
	'binary',
	'vector',
	'unknown',
]);

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function scalarText(value: unknown): string {
	if (value === null || value === undefined) return '';
	return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

/**
 * `[1, 10)`, `[2024-01-01, ∞)`; both ends open reads as "Any value" (the wire cannot
 * tell it from an empty range). With `shown`, timestamp ends read by the date and time
 * rule (`[2024-01-01 07:00:00, …)`, a zoned end in the viewer's zone, whose name is
 * passed to `onZone`); without it, they are exact.
 */
export function formatRange(value: unknown, shown = false, onZone?: (zone: string) => void): string {
	if (!isRecord(value)) return scalarText(value);
	const endText = (end: unknown) => {
		if (!shown || typeof end !== 'string' || !isTimestampText(end)) return scalarText(end);
		const display = formatDateTimeText(end, 'datetime');
		if (display.zone) onZone?.(display.zone);
		return display.text;
	};
	const bound = (side: unknown) => (isRecord(side) && side.value !== null && side.value !== undefined ? side : null);
	const start = bound(value.start);
	const end = bound(value.end);
	if (!start && !end) return 'Any value';
	const open = start ? (start.inclusive === false ? '(' : '[') : '(';
	const close = end ? (end.inclusive === true ? ']' : ')') : ')';
	return `${open}${start ? endText(start.value) : '-∞'}, ${end ? endText(end.value) : '∞'}${close}`;
}

function formatComposite(value: unknown): string {
	if (!isRecord(value)) return scalarText(value);
	return Object.entries(value)
		.filter(([name, field]) => name !== '__typename' && field !== null && field !== undefined)
		.map(([name, field]) => `${fieldLabel(name)}: ${scalarText(field)}`)
		.join(', ');
}

function formatPoint(value: unknown): string {
	if (!isRecord(value)) return scalarText(value);
	return `(${scalarText(value.x)}, ${scalarText(value.y)})`;
}

/** Byte count of a base64 text. */
function base64Size(text: string): number {
	const clean = text.replace(/\s/g, '');
	const padding = clean.endsWith('==') ? 2 : clean.endsWith('=') ? 1 : 0;
	return Math.max(0, Math.floor((clean.length * 3) / 4) - padding);
}

function formatBinary(value: unknown): string {
	if (typeof value !== 'string') return scalarText(value);
	const size = base64Size(value);
	const summary = `${size} ${size === 1 ? 'byte' : 'bytes'}`;
	return value ? `${summary} · ${value}` : summary;
}

function formatVector(value: unknown): string {
	if (!Array.isArray(value)) return scalarText(value);
	return `${value.length} ${value.length === 1 ? 'number' : 'numbers'} · [${value.map(scalarText).join(', ')}]`;
}

function display(cellType: string, value: unknown): string {
	switch (cellType) {
		case 'range':
			return formatRange(value, true);
		case 'composite':
			return formatComposite(value);
		case 'point':
			return formatPoint(value);
		case 'binary':
			return formatBinary(value);
		case 'vector':
			return formatVector(value);
		default:
			// JSON keeps its JSON form so a JSON string reads as "text", not as bare text.
			return compactJsonPreview(JSON.stringify(value) ?? String(value), 200);
	}
}

function canHandle(cellType: string, _value: unknown): boolean {
	return STRUCTURED_CELL_TYPES.has(cellType);
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const meta = { cellType: metadata.cellType as CellType };
	if (value === null || value === undefined) {
		return { kind: 'text', data: '', displayData: '', readonly: false, meta };
	}
	if (metadata.cellType === 'range') {
		// A range's timestamp ends read by the date and time rule; the exact text, and the
		// zone a zoned end is shown in, are the title.
		let zone: string | null = null;
		const shownText = formatRange(value, true, (name) => (zone = name));
		const exact = formatRange(value);
		return { kind: 'text', data: exact, displayData: shownText, readonly: false, meta: { ...meta, title: dateTimeTitle(exact, zone) } };
	}
	const text = display(metadata.cellType, value);
	return { kind: 'text', data: text, displayData: text, readonly: false, meta };
}

export const structuredSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Default (fallback) SheetsCell factory — native analogue of v1's TextCellFactory
// (grid/cell-content-factory.ts). It is the LAST factory in dispatcher precedence:
// `canHandle` returns true for every cellType, so it only WINS the types no
// earlier family claimed (text, textarea, phone, citext, bpchar, json, jsonb,
// inet, uuid, color, origin, unknown).
//
// v1 emits a Text glide cell: null/undefined -> data/displayData ''; string ->
// data/displayData = value; anything else -> compactJsonPreview(value, 80) for
// both. `compactJsonPreview` is shared (sheets.formatters), so it is imported
// rather than copied.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import { compactJsonPreview } from '../../grid/sheets.formatters';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(_cellType: string, _value: unknown): boolean {
	return true;
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const meta = { cellType: metadata.cellType as CellType };

	if (value === null || value === undefined) {
		return { kind: 'text', data: '', displayData: '', readonly: false, meta };
	}

	if (typeof value === 'string') {
		return { kind: 'text', data: value, displayData: value, readonly: false, meta };
	}

	const display = compactJsonPreview(value, 80);
	return { kind: 'text', data: display, displayData: display, readonly: false, meta };
}

export const textSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// SheetsCell factory contract — the native analogue of v1's cell-content-factory
// family. Each factory claims a set of `cellType`s (and/or value shapes) and emits
// the neutral {@link SheetsCell} render payload. Geometry stays out-of-band: the
// optional `deriveGeometry` hook lets a factory delegate to a geometry builder
// without this module importing leaflet peers (mirrors v1 createGeometryCell).

import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';

export interface SheetsCellFactory {
	canHandle(cellType: string, value: unknown): boolean;
	create(value: unknown, metadata: CellCreationMetadata, deriveGeometry?: (value: unknown) => SheetsCell): SheetsCell;
}

// Native SheetsCell factory — URI family (url | email). Ports v1
// `UriCellFactory` (grid/cell-content-factory.ts) to the neutral SheetsCell
// render payload. All domain logic (email -> mailto, url passthrough, empty
// guard) is reproduced here verbatim so this file is glide-free at cutover.
//
// `data` holds the navigable URI while `displayData` keeps the user-facing
// string; the DOM view owns click behavior.

import type { CellType } from '../../cell-types/types';
import type { CellCreationMetadata } from '../../grid/grid-cell-types';
import type { SheetsCell } from '../sheets-cell';
import type { SheetsCellFactory } from './types';

function canHandle(cellType: string, _value: unknown): boolean {
	return cellType === 'url' || cellType === 'email';
}

function create(value: unknown, metadata: CellCreationMetadata): SheetsCell {
	const cellType = metadata.cellType as CellType;

	if (value === null || value === undefined || value === '') {
		return { kind: 'uri', data: '', displayData: '', readonly: false, meta: { cellType } };
	}

	const stringValue = String(value);
	const isEmail = metadata.cellType === 'email';
	const data = isEmail ? `mailto:${stringValue}` : stringValue;

	return { kind: 'uri', data, displayData: stringValue, readonly: false, meta: { cellType } };
}

export const uriSheetsCellFactory: SheetsCellFactory = { canHandle, create };

// Bounded module-level LRU that RETAINS decoded images by URL so they stay warm in
// the browser's in-memory cache across unmount/remount. In a virtualized grid the
// body <img> is destroyed when its row scrolls off-screen; without a live reference
// the decoded bitmap is dropped and a remounted <img src> refetches/repaints (flicker,
// pop-in). Holding a decoded Image reference keeps the URL warm — a remounted <img>
// paints from memory instead of refetching, even for no-cache/short-lived URLs.

const CAP = 256;
const cache = new Map<string, HTMLImageElement>(); // Map preserves insertion order → LRU.

export function warmImage(url: string): void {
	if (!url || typeof Image === 'undefined') return; // SSR / empty-url guard.

	if (cache.has(url)) {
		// Mark most-recently-used: re-insert moves it to the end of the iteration order.
		const img = cache.get(url)!;
		cache.delete(url);
		cache.set(url, img);
		return;
	}

	const img = new Image();
	img.decoding = 'async';
	img.src = url;
	cache.set(url, img);

	while (cache.size > CAP) {
		// Evict the oldest (front of insertion order).
		const oldest = cache.keys().next().value;
		if (oldest === undefined) break;
		cache.delete(oldest);
	}
}

// Native cell model — the DOM render payload that replaces glide `GridCell`.
//
// Pure types: no @tanstack/* or virtual import. `SheetsCellKind` is the neutral
// render vocabulary consumed by the DOM cell host.

import type { CellType } from '../cell-types/types';

/**
 * Neutral render kinds. `loading` and `draft-action` originate from grid-internal
 * state, not the `CellType` system.
 */
export type SheetsCellKind =
	| 'text'
	| 'number'
	| 'boolean'
	| 'badges'
	| 'uri'
	| 'image'
	| 'geometry'
	| 'relation'
	| 'loading'
	| 'draft-action'
	| 'custom';

/** Per-cell visual hint, open-ish so later phases can enrich it. */
export interface SheetsCellStyleHint {
	draft?: boolean;
	faded?: boolean;
	/** This draft cell has a field-level validation error (draftMeta.errors[colKey]). */
	error?: boolean;
	/** The server could not send this value: the cell shows a muted notice instead. */
	unreadable?: boolean;
	[extra: string]: unknown;
}

/**
 * The factory output + render payload. A SINGLE interface with a `kind` field
 * (not a per-kind discriminated union): text/number/boolean share this payload
 * and do not diverge yet.
 *
 * TODO(phases 2+): enrich `meta` per kind (badges/uri/image/geometry/relation)
 * once their factories and views are ported.
 */
export interface SheetsCell {
	kind: SheetsCellKind;
	data: unknown;
	displayData: string;
	readonly: boolean;
	styleHint?: SheetsCellStyleHint;
	meta?: { cellType?: CellType; [extra: string]: unknown };
}

// The one rule for opening the address in an email or web address cell, shared by the
// cell view (its link) and the grid's "Open link" command. A web address cell holds text
// that people typed, so only http, https and mailto addresses ever open: a typed
// `javascript:` or `data:` address must never run, and text that is not a full address
// (`example.com`) is not a link.

import type { SheetsCell } from './sheets-cell';

const OPENABLE_PROTOCOLS: ReadonlySet<string> = new Set(['http:', 'https:', 'mailto:']);

/** The address as the browser would open it, or null when it is not a full http, https or mailto address. */
function openableHref(text: string): string | null {
	let url: URL;
	try {
		url = new URL(text);
	} catch {
		return null;
	}
	return OPENABLE_PROTOCOLS.has(url.protocol) ? url.href : null;
}

/** The address a link cell (`kind: 'uri'`) opens, or null: an empty cell, another kind, or an address that may not open. */
export function uriCellHref(cell: SheetsCell): string | null {
	if (cell.kind !== 'uri' || typeof cell.data !== 'string' || cell.data === '') return null;
	return openableHref(cell.data);
}

/**
 * Open a link cell's address: a web address in a new tab (no opener, no referrer), an
 * email address in the mail app. An address that may not open is ignored.
 */
export function openUriCellLink(href: string): void {
	const safe = openableHref(href);
	if (!safe) return;
	// A mailto address hands off to the mail app without leaving the page; in a new tab it
	// would leave an empty tab behind.
	if (safe.startsWith('mailto:')) window.open(safe, '_self');
	else window.open(safe, '_blank', 'noopener,noreferrer');
}

// Default DOM view for the `badges` SheetsCell family — the native analogue of
// v1's glide BubbleCell render. Dependency-light: plain JSX + Tailwind v4 + a
// local `cn`, with no shared primitive dependency. Reads the string[] off
// `props.cell.data` (the badges payload) and renders one tonal chip per item per
// DESIGN_SPEC §7; an empty array renders an empty cell.
//
// Chips default to the `neutral` tone — the palette is wired for opt-in color
// later (consumer-supplied tone map / resolver); an unconfigured grid stays calm.

import { BADGE_TONES, resolveBadgeTone } from '../badge-tones';
import { cn } from '../../utils/cn';
import type { CellProps } from '../cell-props';

export function BadgesCellView(props: CellProps) {
	const items = Array.isArray(props.cell.data) ? (props.cell.data as string[]) : [];

	return (
		<div
			data-slot="badges-cell"
			className={cn(
				'flex h-full w-full items-center gap-1 overflow-hidden px-3',
				// Single row in the fixed-height cell (no vertical cramming): pills that run
				// past the right edge fade out, signalling more items beyond the cut (DESIGN_SPEC §7).
				// The fade runs over the last 2rem of the content and is fully clear by the end
				// padding, so a cut pill dissolves instead of stopping mid-letter at the cell edge.
				// It only bites when content reaches that far, so a short list shows no fade.
				'[mask-image:linear-gradient(to_right,black,black_calc(100%_-_2.75rem),transparent_calc(100%_-_0.75rem))]',
			)}
		>
			{items.map((item, index) => (
				<span
					key={`${index}-${item}`}
					className={cn(
						'inline-flex shrink-0 items-center rounded-md px-2 py-0.5 text-xs font-medium tabular-nums',
						BADGE_TONES[resolveBadgeTone(item)],
					)}
				>
					{item}
				</span>
			))}
		</div>
	);
}

// Default DOM view for the boolean family. A boolean column IS a checkbox column, so it
// renders the design-system Checkbox: checked for true, unchecked for false, nothing for
// null/undefined ("no value" never reads as false).
//
// One click on the checkbox flips the value. The click target is a plain element around
// the checkbox, not the checkbox button: the grid root keeps the keyboard focus, and the
// gridcell stays the one thing a screen reader announces. A click anywhere else in the
// cell only selects it; Enter and double-click on the cell flip the value as before.
// A cell that cannot be changed shows the checkbox with no click target.
// Keyed off the boolean payload in `cell.data` (NOT displayData — the factory leaves
// displayData '' for parity).

import type { MouseEvent } from 'react';

import { Checkbox } from '@/components/ui/checkbox';

import { cn } from '../../utils/cn';
import type { CellProps } from '../cell-props';

function stopEvent(event: MouseEvent) {
	event.stopPropagation();
}

export function BooleanCellView(props: CellProps) {
	const value = props.cell.data;
	const hasValue = value === true || value === false;
	const editable = !props.cell.readonly && !props.readOnlyReason && !props.disabled;

	if (!editable) {
		return (
			<div data-slot="boolean-cell" className="flex h-full w-full items-center px-3">
				{hasValue ? <Checkbox checked={value === true} readOnly tabIndex={-1} className="pointer-events-none" /> : null}
			</div>
		);
	}

	// A click with Shift, Ctrl or Cmd belongs to the selection (extend a range), not to the value.
	const toggle = (event: MouseEvent) => {
		if (event.shiftKey || event.metaKey || event.ctrlKey) return;
		props.onStartEdit();
	};

	return (
		<div data-slot="boolean-cell" className="group/boolean flex h-full w-full items-center px-3">
			<span
				data-slot="boolean-toggle"
				// The margin and padding cancel out: a 28px target around a 16px checkbox, same layout.
				className="-m-1.5 inline-flex cursor-pointer items-center justify-center p-1.5"
				onClick={toggle}
				// Two clicks are two flips; the cell's own double-click must not add a third.
				onDoubleClick={stopEvent}
			>
				{hasValue ? (
					<Checkbox checked={value === true} readOnly tabIndex={-1} className="pointer-events-none" />
				) : (
					// An empty cell has no checkbox, so it never reads as false. A dashed box shows
					// where to click when the pointer or the cursor is on the cell.
					<span
						aria-hidden="true"
						data-slot="boolean-empty"
						className={cn(
							'border-input size-4.5 rounded-xs border border-dashed opacity-0 group-hover/boolean:opacity-100 sm:size-4',
							props.isActive && 'opacity-100',
						)}
					/>
				)}
			</span>
		</div>
	);
}

// Default DOM view for the datetime family. v1 renders the formatted date/time
// as plain text inside the canvas; the native analogue is a single truncated
// text span. Dependency-light: plain JSX + Tailwind v4 + local `cn`, no
// shared primitive dependency. Reads the rendered string off the SheetsCell
// payload (`cell.displayData`) so it stays in lockstep with the factory.

import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

