// Native DOM view for the `draft-action` column — the REAL <Button> that replaces
// the canvas fake-button painter (grid/custom-cells/draft-action-cell.tsx, which
// snapshot-captured design-system button styles into a canvas paint via
// captureButtonStyle/BUTTON_STYLE_CACHE). Mirrors that painter's states 1:1:
//   - idle    -> outline button labelled "Save"
//   - saving  -> disabled, spinner + "Saving..." (canvas drew an animated arc)
//   - errored -> red dot indicator top-right; the button stays interactive
//                (the canvas painter never disabled on `errored`)
// The host special-cases this column and passes these explicit props instead of the
// generic CellProps, so the view stays a dumb presenter and onClick -> onSubmit().

import { LoaderIcon } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { cn } from '../../utils/cn';

export type DraftActionStatus = 'idle' | 'saving' | 'error';

export interface DraftActionCellViewProps {
	status?: DraftActionStatus;
	disabled?: boolean;
	errored?: boolean;
	/** Why the row was not saved; the button's tooltip and its description while `errored`. */
	errorMessage?: string | null;
	onSubmit?: () => void;
}

const SAVE_LABEL = 'Save';
const SAVING_LABEL = 'Saving...';

export function DraftActionCellView(props: DraftActionCellViewProps) {
	const status = props.status ?? 'idle';
	const isSaving = status === 'saving';
	// Saving locks the button so a real DOM click can't double-submit mid-flight;
	// the canvas relied on the shell to guard, the DOM disables outright.
	const isDisabled = Boolean(props.disabled) || isSaving;
	const reason = props.errored ? props.errorMessage || null : null;

	return (
		<div className="flex h-full w-full items-center justify-center px-2">
			<Button
				type="button"
				variant="outline"
				size="sm"
				disabled={isDisabled}
				onClick={props.onSubmit}
				data-slot="draft-action-cell"
				className="relative"
				title={reason ?? undefined}
				aria-description={reason ?? undefined}
			>
				{isSaving && <LoaderIcon className="animate-spin" aria-hidden="true" />}
				{isSaving ? SAVING_LABEL : SAVE_LABEL}
				{props.errored && (
					<span
						data-slot="draft-action-error"
						role="status"
						aria-label="Save failed"
						className={cn(
							'absolute -top-1 -right-1 size-2 rounded-full bg-destructive',
							'ring-2 ring-background',
						)}
					/>
				)}
			</Button>
		</div>
	);
}

// DOM view for geometry cells: a geo ICON tinted by the shape's category
// (point/line/polygon/collection) and the shape in plain words ("Point", "Line",
// "3 polygons", "Empty shape"). The factory summarizes the stored value
// (`meta.shapeLabel` / `shapeCategory` / `shapeProblem`, from `summarizeShape`); a
// cell built by a host `deriveGeometry` builder carries a `geometryType` hint
// instead, named the same way. "Not a shape" appears only for a value that cannot
// be read as one, with the reason in the title. No value is an empty cell.

import { shapeKindName, type ShapeCategory } from '../../cell-types/shape-kind';
import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

type GeometryCategory = ShapeCategory;

// Canvical-cell category buckets keyed by GeoJSON type — mirrors geometry-cell.tsx
// ICON_COLORS grouping (point/line/polygon families share a colour).
const TYPE_CATEGORY: Record<string, GeometryCategory> = {
	Point: 'point',
	MultiPoint: 'point',
	LineString: 'line',
	MultiLineString: 'line',
	Polygon: 'polygon',
	MultiPolygon: 'polygon',
	GeometryCollection: 'collection',
};

// Tints mirror geometry-cell.tsx ICON_COLORS (blue/purple/green/amber, grey when
// empty, red for a value that is not a shape).
const CATEGORY_COLOR: Record<GeometryCategory, string> = {
	point: '#3b82f6',
	line: '#8b5cf6',
	polygon: '#10b981',
	collection: '#f59e0b',
	empty: '#a1a1aa',
	invalid: '#ef4444',
};

/** Read an explicit geometry type from the cell hint (meta or a derived data object). */
function readHintedType(cell: CellProps['cell']): string | undefined {
	const fromMeta = cell.meta?.geometryType;
	if (typeof fromMeta === 'string' && fromMeta) return fromMeta;
	const data = cell.data;
	if (data && typeof data === 'object') {
		const gt = (data as { geometryType?: unknown }).geometryType;
		if (typeof gt === 'string' && gt) return gt;
	}
	return undefined;
}

/** The single-line preview text the factory emitted (copy/display parity). */
function readDisplayText(cell: CellProps['cell']): string {
	if (typeof cell.displayData === 'string' && cell.displayData) return cell.displayData;
	if (typeof cell.data === 'string') return cell.data;
	return '';
}

interface ShapeShown {
	category: GeometryCategory;
	label: string;
	problem: string | null;
}

/** What to show: the factory's summary, or a host builder's type hint named in plain words. */
function shapeShown(cell: CellProps['cell']): ShapeShown | null {
	const meta = cell.meta ?? {};
	if (typeof meta.shapeLabel === 'string' && typeof meta.shapeCategory === 'string') {
		return {
			category: meta.shapeCategory as GeometryCategory,
			label: meta.shapeLabel,
			problem: typeof meta.shapeProblem === 'string' ? meta.shapeProblem : null,
		};
	}
	const hinted = readHintedType(cell);
	if (!hinted) return null;
	const category = TYPE_CATEGORY[hinted];
	return category
		? { category, label: shapeKindName(hinted), problem: null }
		: { category: 'invalid', label: 'Not a shape', problem: `"${hinted}" is not a GeoJSON shape type.` };
}

// Inline SVG geo icons — one per category, tinted via `color`. A point is a map
// pin; line/polygon/collection use a map glyph; invalid is a warning triangle.
function GeometryIcon({ category, color }: { category: GeometryCategory; color: string }) {
	const common = {
		width: 14,
		height: 14,
		viewBox: '0 0 24 24',
		fill: 'none',
		stroke: color,
		strokeWidth: 2,
		strokeLinecap: 'round' as const,
		strokeLinejoin: 'round' as const,
		'aria-hidden': true,
		className: 'shrink-0',
	};
	if (category === 'point') {
		return (
			<svg {...common} data-geometry-icon="point">
				<path d="M12 21s-6-5.686-6-10a6 6 0 1 1 12 0c0 4.314-6 10-6 10z" />
				<circle cx="12" cy="11" r="2" />
			</svg>
		);
	}
	if (category === 'invalid') {
		return (
			<svg {...common} data-geometry-icon="invalid">
				<path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
				<line x1="12" y1="9" x2="12" y2="13" />
				<line x1="12" y1="17" x2="12.01" y2="17" />
			</svg>
		);
	}
	// line / polygon / collection — a folded map glyph.
	return (
		<svg {...common} data-geometry-icon={category}>
			<polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6" />
			<line x1="8" y1="2" x2="8" y2="18" />
			<line x1="16" y1="6" x2="16" y2="22" />
		</svg>
	);
}

export function GeometryCellView(props: CellProps) {
	const { cell } = props;
	const shape = shapeShown(cell);

	// No value — an empty cell, like every other kind.
	if (!shape) {
		return <div data-slot="geometry-cell" className="h-full w-full" />;
	}

	return (
		<div
			data-slot="geometry-cell"
			data-geometry-category={shape.category}
			title={shape.problem ?? (readDisplayText(cell) || undefined)}
			className={cn('flex h-full w-full items-center gap-1.5 overflow-hidden px-3')}
		>
			<GeometryIcon category={shape.category} color={CATEGORY_COLOR[shape.category]} />
			<span
				className={cn(
					'truncate text-xs font-medium tabular-nums',
					(shape.category === 'invalid' || shape.category === 'empty') && 'text-muted-foreground',
				)}
			>
				{shape.label}
			</span>
		</div>
	);
}

// Native DOM view for file cells: image, upload, lists of uploads, attachment links.
//
//   image file      a square thumbnail (object-fit: cover) over a muted box; a
//                   public URL from the projection, otherwise a signed URL
//                   resolved in batches through the column's files table.
//   other file      a chip: icon and name; type and size in the title.
//   list            up to three small previews and the file count.
//   link            a chip with the link's last path segment.
//
// A file whose preview cannot be resolved still shows its name. While a new
// file waits for the server's confirmation the cell shows "Processing file…";
// a write that did not land shows "Not saved" with a retry.
//
// Virtualization destroys off-screen rows, so durable URLs are kept warm in a
// module LRU (`warmImage`); signed URLs live in the query cache and are never warmed.
//
// The cell host is the `gridcell` and carries the read-only reason for assistive
// technology; these views add no role. A reason the host cannot know (uploads
// unavailable for this column) is in the view's title and in the editor's note.

import { AlertCircleIcon, FileIcon, LinkIcon, Loader2, LockIcon, RotateCcwIcon, XIcon } from 'lucide-react';
import type React from 'react';

import type { ColumnFileModel } from '@constructive-io/data';

import { useSheetsContext } from '../../context/sheets-context';
import { useSheetsMediaUrl } from '../../hooks/use-sheets-media-url';
import { useColumnMediaResolver, useFileUploadState, type ColumnMediaResolver } from '../../hooks/use-sheets-upload';
import { pendingWriteKey, usePendingFileWrite, type PendingFileWrite } from '../../uploads/pending-file-writes';
import { cn } from '../../utils/cn';
import { fileDetails, fileLabel, isImageFile, storedFilesOf, type StoredFile } from '../../utils/file.utils';
import type { CellProps } from '../cell-props';
import { fileCellMetaOf } from '../factories/image';
import { warmImage } from '../image-cache';

type FileKind = ColumnFileModel['kind'];

const LIST_PREVIEW_LIMIT = 3;

function kindOf(model: ColumnFileModel | null, cellType: string): FileKind {
	if (model) return model.kind;
	if (cellType === 'image' || cellType === 'attachment') return cellType;
	return 'upload';
}

function stop(event: React.SyntheticEvent) {
	event.stopPropagation();
}

function FileChip({ file, kind, reason }: { file: StoredFile; kind: FileKind; reason?: string }) {
	const Icon = kind === 'attachment' ? LinkIcon : FileIcon;
	const details = kind === 'attachment' && file.url ? `${fileLabel(file)}\n${file.url}` : fileDetails(file);
	return (
		<div
			data-slot="file-cell"
			className="flex h-full w-full items-center gap-1.5 overflow-hidden px-3"
		>
			<Icon className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />
			<span className="truncate text-sm" title={reason ? `${details}\n${reason}` : details}>
				{fileLabel(file)}
			</span>
		</div>
	);
}

/** One file's preview: a thumbnail when it is an image and a URL resolves, else null. */
function usePreview(file: StoredFile, kind: FileKind, media: ColumnMediaResolver) {
	const previewImage = kind !== 'attachment' && isImageFile(file, kind);
	const preview = useSheetsMediaUrl(file.raw, { previewImage, resolver: media.resolver });
	const isLoading = previewImage && !preview.durableUrl && (preview.isLoading || media.isLoading);
	return { ...preview, previewImage, isLoading };
}

function Thumbnail({ preview, className }: { preview: ReturnType<typeof usePreview>; className?: string }) {
	const { url, durableUrl, onImageError, onImageLoad } = preview;
	return (
		<div className={cn('relative aspect-square h-full max-h-full shrink-0 overflow-hidden rounded-sm bg-muted', className)}>
			{url ? (
				<img
					key={url}
					src={url}
					decoding="async"
					alt=""
					onError={onImageError}
					onLoad={() => {
						onImageLoad();
						if (durableUrl) warmImage(durableUrl);
					}}
					className="absolute inset-0 h-full w-full rounded-sm object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10"
				/>
			) : null}
		</div>
	);
}

function SingleFile({ file, kind, media, reason }: { file: StoredFile; kind: FileKind; media: ColumnMediaResolver; reason?: string }) {
	const preview = usePreview(file, kind, media);
	if (!preview.previewImage || (!preview.url && !preview.isLoading)) return <FileChip file={file} kind={kind} reason={reason} />;
	return (
		<div
			data-slot="image-cell"
			title={reason ? `${fileDetails(file)}\n${reason}` : fileDetails(file)}
			className="flex h-full w-full items-center overflow-hidden px-3 py-1"
		>
			<Thumbnail preview={preview} />
		</div>
	);
}

function ListItemPreview({ file, kind, media }: { file: StoredFile; kind: FileKind; media: ColumnMediaResolver }) {
	const preview = usePreview(file, kind, media);
	if (preview.previewImage && (preview.url || preview.isLoading)) return <Thumbnail preview={preview} className="h-6" />;
	return (
		<span className="flex size-6 shrink-0 items-center justify-center rounded-sm bg-muted" aria-hidden="true">
			<FileIcon className="size-3.5 text-muted-foreground" />
		</span>
	);
}

function FileList({ files, kind, media, reason }: { files: StoredFile[]; kind: FileKind; media: ColumnMediaResolver; reason?: string }) {
	const count = `${files.length} ${files.length === 1 ? 'file' : 'files'}`;
	const title = [...files.map(fileLabel), reason].filter(Boolean).join('\n');
	return (
		<div
			data-slot="file-list-cell"
			title={title}
			className="flex h-full w-full items-center gap-1 overflow-hidden px-3"
		>
			{files.slice(0, LIST_PREVIEW_LIMIT).map((file, index) => (
				<ListItemPreview key={`${file.id ?? file.url ?? file.key ?? 'file'}-${index}`} file={file} kind={kind} media={media} />
			))}
			<span className="ms-0.5 truncate text-xs text-muted-foreground tabular-nums">{count}</span>
		</div>
	);
}

const PENDING_ACTION =
	'flex size-6 shrink-0 items-center justify-center rounded-sm text-muted-foreground outline-hidden hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50';

function PendingWrite({ pending }: { pending: PendingFileWrite }) {
	if (pending.status === 'processing') {
		return (
			<div data-slot="file-cell-pending" className="flex h-full w-full items-center gap-1.5 overflow-hidden px-3">
				<Loader2 className="size-3.5 shrink-0 animate-spin text-muted-foreground" aria-hidden="true" />
				<span role="status" className="truncate text-sm text-muted-foreground">Processing file…</span>
			</div>
		);
	}
	return (
		// The two actions sit side by side with no gap, and the icon side keeps a smaller
		// inset, so "Not saved" fits a default-width column.
		<div data-slot="file-cell-failed" className="flex h-full w-full items-center gap-1 overflow-hidden ps-3 pe-1">
			<AlertCircleIcon className="size-3.5 shrink-0 text-destructive" aria-hidden="true" />
			<span className="truncate text-sm" title={pending.message}>Not saved</span>
			<div className="ms-auto flex shrink-0 items-center">
				<button
					type="button"
					className={PENDING_ACTION}
					aria-label="Retry saving the file"
					title={`${pending.message}\nRetry`}
					onMouseDown={stop}
					onDoubleClick={stop}
					onClick={(event) => {
						event.stopPropagation();
						pending.retry();
					}}
				>
					<RotateCcwIcon className="size-3.5" aria-hidden="true" />
				</button>
				<button
					type="button"
					className={PENDING_ACTION}
					aria-label="Discard the unsaved file"
					onMouseDown={stop}
					onDoubleClick={stop}
					onClick={(event) => {
						event.stopPropagation();
						pending.dismiss();
					}}
				>
					<XIcon className="size-3.5" aria-hidden="true" />
				</button>
			</div>
		</div>
	);
}

function EmptyFileCell({ kind, reason }: { kind: FileKind; reason?: string }) {
	return (
		<div
			data-slot="image-cell"
			data-empty=""
			title={reason}
			className="flex h-full w-full items-center gap-1.5 overflow-hidden px-3 py-1"
		>
			{kind === 'image' ? <div className="aspect-square h-full max-h-full rounded-sm bg-muted/60" aria-hidden="true" /> : null}
			{reason ? <LockIcon className="size-3 shrink-0 text-muted-foreground/60" aria-hidden="true" /> : null}
		</div>
	);
}

export function ImageCellView(props: CellProps) {
	const meta = fileCellMetaOf(props.cell);
	const column = meta?.column ?? null;
	const table = meta?.table ?? null;
	const fileModel = column?.value.file ?? null;
	const kind = kindOf(fileModel, props.column.cellType);
	const files = storedFilesOf(props.value, fileModel);
	const { scopeKey } = useSheetsContext();
	const pending = usePendingFileWrite(scopeKey, table ? pendingWriteKey(table.key, props.rowId, props.colKey) : null);
	const media = useColumnMediaResolver(table, column);
	const upload = useFileUploadState(table, column);
	const reason = props.readOnlyReason ?? (upload.status === 'unavailable' ? upload.reason : undefined);

	if (pending) return <PendingWrite pending={pending} />;
	if (files.length === 0) return <EmptyFileCell kind={kind} reason={reason} />;
	if (fileModel?.multiple || files.length > 1) return <FileList files={files} kind={kind} media={media} reason={reason} />;
	return <SingleFile file={files[0]!} kind={kind} media={media} reason={reason} />;
}

// Default DOM view for the interval SheetsCell family. Dependency-light: plain
// JSX + Tailwind v4 + a local `cn`, with no shared primitive dependency. The
// compact interval label already lives in `cell.displayData` (computed by the
// interval factory), so the view is a pure read of that string.

import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

export function IntervalCellView(props: CellProps) {
	const { cell } = props;
	return (
		<div
			data-slot="interval-cell"
			className={cn('flex h-full w-full items-center truncate px-3 text-sm tabular-nums')}
		>
			{cell.displayData}
		</div>
	);
}

// Default DOM view for the grid-internal `loading` SheetsCell kind — the cell an
// infinite-scroll row shows while its page is still in flight (getRowAtIndex is
// null, so there is no value to render). The native analogue of v1's canvas
// loading skeleton: a subtle `animate-pulse` placeholder bar filling the cell.
// Dependency-light: plain JSX + Tailwind v4 + local `cn`, with no shared primitive dependency.

import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

export function LoadingCellView(_props: CellProps) {
	return (
		<div
			data-slot="loading-cell"
			aria-busy="true"
			className={cn('flex h-full w-full items-center px-3')}
		>
			<span
				aria-hidden="true"
				className={cn('h-3 w-3/5 max-w-full rounded-full bg-muted', 'animate-pulse')}
			/>
		</div>
	);
}

// Default DOM view for the number SheetsCell family. Dependency-light: plain JSX
// + Tailwind v4 + a `data-slot` hook, with no shared primitive dependency. Numbers
// render right-aligned with tabular figures so digits line up column-wise. Reads
// the already-formatted string off `props.cell.displayData` (the factory put the
// exact value there); the view does no numeric formatting itself.
//
// A value wider than its column must never read as a different number. Right
// alignment alone would clip it on the LEFT (dropping the sign and the leading
// digits, with no marker), so the text sits in a shrinkable span: while it fits it
// is right-aligned; when it does not, it keeps its sign and leading digits and ends
// with an ellipsis. The full value is always in the title.

import type { CellProps } from '../cell-props';

export function NumberCellView(props: CellProps) {
	const text = props.cell.displayData;
	const title = [text, props.readOnlyReason].filter(Boolean).join('\n');
	return (
		<div
			data-slot="number-cell"
			title={title || undefined}
			className="flex h-full w-full min-w-0 items-center justify-end px-3 text-sm tabular-nums text-foreground"
		>
			<span data-truncate="end" className="min-w-0 truncate">
				{text}
			</span>
		</div>
	);
}

// Default DOM view for the `relation` SheetsCell family. Reads the payload
// relationSheetsCellFactory produced:
//   - list relation   -> cell.data is string[] chips, possibly ending in "+N";
//                        cell.meta.relationTitles holds the full chip labels and
//                        cell.meta.relationCount every linked record.
//   - single relation -> cell.data is a string label; cell.meta.relationTitle the full label.
//   - both            -> cell.meta.relationTarget / relationLinks name the shown records.
// Truncated labels carry their full text as a title. In the ACTIVE cell, when the
// host handles opening linked records (SheetsOpenRecordContext), each identifiable
// chip gets an open icon (as in the record panel) that opens its record, and a
// Mod+click on the chip does the same. A plain click or a double-click on the chip
// keeps its grid meaning (select the cell, open the link editor), so one gesture
// never opens two surfaces.

import React from 'react';
import { ExternalLink } from 'lucide-react';

import { useOpenRecordHandler, type SheetsOpenRecordHandler } from '../../relations/relation-navigation';
import { cn } from '../../utils/cn';
import type { RelationCellLink } from '../factories/relation';
import type { CellProps } from '../cell-props';

const OVERFLOW_CHIP = /^\+(\d+)$/;

function stringList(value: unknown): string[] | null {
	return Array.isArray(value) && value.every((entry) => typeof entry === 'string') ? (value as string[]) : null;
}

function linksOf(value: unknown): RelationCellLink[] {
	return Array.isArray(value) ? (value as RelationCellLink[]) : [];
}

function targetOf(value: unknown): { tableKey: string; tableName: string } | null {
	if (!value || typeof value !== 'object') return null;
	const target = value as { tableKey?: unknown; tableName?: unknown };
	return typeof target.tableKey === 'string' && typeof target.tableName === 'string'
		? { tableKey: target.tableKey, tableName: target.tableName }
		: null;
}

/** A chip label, with an icon that opens its record when it can. */
function ChipContent({
	text,
	title,
	link,
	open,
	className,
	inChip = false,
}: {
	text: string;
	title: string;
	link: RelationCellLink | undefined;
	open: ((link: RelationCellLink) => void) | null;
	className?: string;
	/**
	 * In a list chip the icon shows only while the chip is hovered; a single link pins it to
	 * the cell's right edge. Either way a press on the middle of the cell selects or edits it.
	 */
	inChip?: boolean;
}) {
	const openLink = open && link?.key ? () => open(link) : null;
	return (
		<>
			<span
				className={cn('truncate', !inChip && 'min-w-0 flex-1', className)}
				title={title || undefined}
				onClick={
					openLink
						? (event) => {
								// Mod+click opens the record; a plain click belongs to the cell.
								if (!(event.metaKey || event.ctrlKey)) return;
								event.stopPropagation();
								openLink();
							}
						: undefined
				}
			>
				{text}
			</span>
			{openLink ? (
				<button
					type='button'
					data-slot='relation-open'
					className={cn(
						'text-muted-foreground hover:text-foreground focus-visible:text-foreground inline-flex size-4 shrink-0 items-center justify-center rounded-sm outline-none',
						inChip && 'invisible group-hover/chip:visible',
					)}
					title={`Open ${title}`}
					aria-label={`Open ${title}`}
					onClick={(event) => {
						event.stopPropagation();
						openLink();
					}}
					// A fast second click on the icon is still opening, never the cell's editor.
					onDoubleClick={(event) => event.stopPropagation()}
				>
					<ExternalLink className='size-3' aria-hidden='true' />
				</button>
			) : null}
		</>
	);
}

function useOpenLink(props: CellProps): ((link: RelationCellLink) => void) | null {
	const handler: SheetsOpenRecordHandler | null = useOpenRecordHandler();
	const target = targetOf(props.cell.meta?.relationTarget);
	if (!props.isActive || !handler || !target) return null;
	return (link) => {
		if (link.key) handler({ tableKey: target.tableKey, tableName: target.tableName, key: link.key, label: link.label });
	};
}

export function RelationCellView(props: CellProps): React.JSX.Element {
	const { cell } = props;
	const meta = cell.meta ?? {};
	const links = linksOf(meta.relationLinks);
	const open = useOpenLink(props);

	if (!Array.isArray(cell.data)) {
		const label = String(cell.data ?? '');
		const title = typeof meta.relationTitle === 'string' && meta.relationTitle ? meta.relationTitle : label;
		return (
			<div
				data-slot="relation-cell"
				className="flex h-full w-full items-center gap-1 overflow-hidden px-3 text-sm"
			>
				<ChipContent text={label} title={title} link={links[0]} open={open} className="text-foreground" />
			</div>
		);
	}

	const chips = cell.data as unknown[];
	const titles = stringList(meta.relationTitles) ?? [];
	const lastMatch = typeof chips[chips.length - 1] === 'string' ? OVERFLOW_CHIP.exec(chips[chips.length - 1] as string) : null;
	const labels = lastMatch ? chips.slice(0, -1) : chips;
	const overflow = lastMatch ? Number(lastMatch[1]) : 0;
	const count = typeof meta.relationCount === 'number' ? meta.relationCount : labels.length + overflow;

	return (
		<div
			data-slot="relation-cell"
			className="flex h-full w-full items-center gap-1 overflow-hidden px-3 text-sm"
		>
			{count > 0 ? (
				<span
					data-slot="relation-count-badge"
					className={cn(
						'inline-flex shrink-0 items-center rounded-sm border border-border bg-muted',
						'px-1 text-[10px] font-medium text-muted-foreground tabular-nums',
					)}
				>
					{count}
				</span>
			) : null}
			{labels.map((chip, index) => (
				<span
					key={index}
					className={cn(
						'group/chip inline-flex min-w-0 max-w-[12rem] shrink items-center gap-0.5 rounded-md bg-muted px-1.5 py-0.5',
						'text-xs font-medium text-muted-foreground',
					)}
				>
					<ChipContent text={String(chip)} title={titles[index] ?? String(chip)} link={links[index]} open={open} inChip />
				</span>
			))}
			{overflow > 0 ? (
				<span className="inline-flex shrink-0 items-center px-1 text-xs text-muted-foreground tabular-nums" title={`${overflow} more linked records`}>
					+{overflow} more
				</span>
			) : null}
		</div>
	);
}

// Default DOM view for the text family (the fallback). v1 renders the value as
// plain truncated text inside the canvas; the native analogue is a single
// truncated span. Dependency-light: plain JSX + Tailwind v4 + local `cn`, no
// shared primitive dependency. Reads the rendered string off the SheetsCell
// payload (`cell.displayData`) so it stays in lockstep with the factory.

import { TABULAR_TEXT_TYPES } from '../../cell-types/cell-type-groups';
import type { CellProps } from '../cell-props';
import { cn } from '../../utils/cn';

/** The title behind a display that is not the stored text: the factory's title (a date or
 * time with the zone it is shown in), else the exact stored text. */
function exactText(cell: CellProps['cell']): string {
	if (typeof cell.meta?.title === 'string' && cell.meta.title) return cell.meta.title;
	return typeof cell.data === 'string' && cell.data !== cell.displayData ? cell.data : '';
}

export function TextCellView(props: CellProps) {
	const text = props.cell.displayData;
	// Dates, times and other digit-heavy values line up down the column (tabular figures).
	const tabular = TABULAR_TEXT_TYPES.has(props.cell.meta?.cellType ?? '');

	return (
		<div
			data-slot="text-cell"
			title={[exactText(props.cell) || text, props.readOnlyReason].filter(Boolean).join('\n')}
			className={cn('flex h-full w-full items-center truncate px-3 text-sm', tabular && 'tabular-nums')}
		>
			<span className="truncate">{text}</span>
		</div>
	);
}

// Native DOM view for the URI family (url | email). Dependency-light: plain JSX
// + Tailwind v4 + local `cn`. Reads the render payload off `props.cell`
// (`data` -> address, `displayData` -> visible label). Only an address that may open
// (`uriCellHref`: http, https or mailto) is shown as a link; an empty cell or any other
// text is plain text.
//
// The link works only in the active cell, the same rule as the relation chips: the
// first click on a cell selects it, and a deliberate click on the link in the active
// cell opens it (a new tab, or the mail app for an email). Before that the label is
// plain text in the link color, so a selecting click never leaves the grid. The second
// click of a double-click belongs to the cell (it opens the editor), so it never follows
// the link. From the keyboard, Enter edits the cell and the grid's "Open link" command
// opens it (through `openUriCellLink`, the same rule).

import type { CellProps } from '../cell-props';
import { uriCellHref } from '../uri-link';
import { cn } from '../../utils/cn';

export function UriCellView(props: CellProps) {
	const label = props.cell.displayData;
	const href = uriCellHref(props.cell);

	return (
		<div data-slot="uri-cell" className="flex h-full w-full min-w-0 items-center px-3 text-sm">
			{href && props.isActive ? (
				<a
					href={href}
					// The mail app takes a mailto address without leaving the page; a new tab would stay empty.
					target={href.startsWith('mailto:') ? undefined : '_blank'}
					rel="noreferrer"
					title={label}
					className={cn('truncate text-info underline-offset-2 hover:underline', 'focus-visible:outline-hidden')}
					onClick={(event) => {
						if (event.detail >= 2) event.preventDefault();
					}}
				>
					{label}
				</a>
			) : (
				<span className={cn('truncate', href && 'text-info')} title={label || undefined}>
					{label}
				</span>
			)}
		</div>
	);
}

import type { CellType } from './types';

import type { CellPlugin, CellRegistryEntry, CellRenderer } from './types';

class CellRegistryClass {
	private entries = new Map<CellType, CellRegistryEntry>();
	private plugins = new Map<string, CellPlugin>();

	// Register a cell renderer for a cell type
	register(entry: CellRegistryEntry): void {
		this.entries.set(entry.type, entry);
	}

	// Register multiple entries at once
	registerBatch(entries: CellRegistryEntry[]): void {
		entries.forEach((entry) => this.register(entry));
	}

	// Get cell renderer for a type
	get(type: CellType): CellRegistryEntry | undefined {
		return this.entries.get(type);
	}

	// Get all registered cell types
	getAll(): CellRegistryEntry[] {
		return Array.from(this.entries.values());
	}

	// Get cell component for a type
	getComponent(type: CellType): CellRenderer | undefined {
		const entry = this.entries.get(type);
		return entry?.component;
	}

	// Find cell entry by match function
	// NOTE: Cell type is determined ONLY from schema metadata, never from runtime values
	findByMatch(metadata: {
		gqlType: string;
		isArray: boolean;
		pgAlias?: string | null;
		pgType?: string | null;
		subtype?: string | null;
		fieldName?: string;
	}): CellRegistryEntry | undefined {
		// Iterate through all entries and find the first one with a matching match function
		for (const entry of this.entries.values()) {
			if (entry.match && entry.match(metadata)) {
				return entry;
			}
		}
		return undefined;
	}

	// Get cell component using match function first, then fallback to type
	// NOTE: Cell type is determined ONLY from schema metadata, never from runtime values
	getComponentWithMatch(
		type: CellType,
		metadata?: {
			gqlType: string;
			isArray: boolean;
			pgAlias?: string | null;
			pgType?: string | null;
			subtype?: string | null;
			fieldName?: string;
		},
	): CellRenderer | undefined {
		// First try to find by match function if metadata is provided
		if (metadata) {
			const matchedEntry = this.findByMatch(metadata);
			if (matchedEntry) {
				return matchedEntry.component;
			}
		}

		// Fallback to regular type-based lookup
		return this.getComponent(type);
	}

	// Get edit component for a type
	getEditComponent(type: CellType): CellRenderer | undefined {
		const entry = this.entries.get(type);
		return entry?.editComponent || entry?.component;
	}

	// Check if a type is registered
	has(type: CellType): boolean {
		return this.entries.has(type);
	}

	// Install a plugin
	installPlugin(plugin: CellPlugin): void {
		if (this.plugins.has(plugin.name)) {
			console.warn(`Plugin ${plugin.name} is already installed`);
			return;
		}

		// Install plugin cells
		plugin.cells.forEach((cell) => this.register(cell));

		// Run plugin install hook
		plugin.install?.();

		this.plugins.set(plugin.name, plugin);
	}

	// Uninstall a plugin
	uninstallPlugin(pluginName: string): void {
		const plugin = this.plugins.get(pluginName);
		if (!plugin) {
			console.warn(`Plugin ${pluginName} is not installed`);
			return;
		}

		// Remove plugin cells
		plugin.cells.forEach((cell) => this.entries.delete(cell.type));

		// Run plugin uninstall hook
		plugin.uninstall?.();

		this.plugins.delete(pluginName);
	}

	// Get installed plugins
	getInstalledPlugins(): CellPlugin[] {
		return Array.from(this.plugins.values());
	}

	// Clear all entries (useful for testing)
	clear(): void {
		this.entries.clear();
		this.plugins.clear();
	}

	// Get entries by category
	getByCategory(category: string): CellRegistryEntry[] {
		return Array.from(this.entries.values()).filter((entry) => entry.metadata?.category === category);
	}
}

// Export singleton instance
/**
 * @deprecated since 0.2.0 — pass cell types via <SheetsProvider config={{ plugins }}> or <Sheets cellTypes>. CellRegistry only ever affected detection.
 */
export const CellRegistry = new CellRegistryClass();

// Export factory function for testing
export function createCellRegistry(): CellRegistryClass {
	return new CellRegistryClass();
}

