	toggleAll(): void;
	/** Extract a cell matrix for a range (pure helper, re-exported into ctx for copy). */
	getCellsInRange(rect: SelectionRect): CellMatrix;
	/** Serialize a value matrix to TSV (pure helper). */
	toTSV(values: (readonly unknown[])[]): string;
	/** Emit an observational event (analytics/telemetry; never changes behavior). */
	emit(type: SheetsEvent['type'], meta?: Record<string, unknown>): void;

	// ---- view (filter, sort, search) ----
	readonly view: GridViewCommandTarget;

	// ---- record panel (optional: absent when the grid has none) ----
	readonly record?: GridRecordCommandTarget;
	readonly newRecord?: GridNewRecordCommandTarget;

	// ---- links and the context menu (optional) ----
	readonly link?: GridLinkCommandTarget;
	readonly contextMenu?: GridContextMenuCommandTarget;
}

/**
 * The ONE interceptable dispatch pipeline (P4 Phase 1).
 *
 * `dispatch(command, native?, payload?)`:
 *   1. resolve `command` in the registry — a missing / null id is a silent NO-OP
 *      (so an unbound key falls through to the browser: NO `preventDefault`).
 *   2. run the interceptor chain (reduceRight → first-listed is OUTERMOST). Each
 *      interceptor may VETO (not call `next` → command never runs, nothing prevented),
 *      TRANSFORM (mutate `ev.payload` before `next`), or OBSERVE (read `next()`'s result).
 *   3. AFTER the chain, check `command.canRun(ctx, payload)` — false NO-OPs (and does
 *      NOT preventDefault).
 *   4. `native?.preventDefault()` happens ONLY here in the core (so a vetoed / unresolved /
 *      can't-run command leaves the native event untouched and the key reaches the browser).
 *   5. `command.run(ctx, payload)` — synchronous return (it MAY kick a Promise; we never
 *      await — NO async-dispatch / re-entrancy machinery).
 *
 * Phase 1 ships ZERO interceptors (the consumer seam is Phase 2); the chain is wired so
 * adding one later is purely additive and behavior stays byte-for-byte identical.
 */

import type { GridCommandContext } from './context';
import type { GridCommandRegistry } from './types';

/** The mutable event threaded through the interceptor chain. */
export interface DispatchEvent {
	/** The resolved command id. */
	command: string;
	/** The originating native event, if any (the funnel's `preventDefault` target). */
	native?: Event;
	/** The command payload — interceptors MAY mutate this in place to TRANSFORM. */
	payload?: unknown;
}

/** Result of a dispatch attempt — observable by interceptors via `next()`. */
export interface CommandResult {
	/** The dispatched command id (or null when nothing resolved). */
	command: string | null;
	/** Whether `command.run` was invoked (false = unresolved / vetoed / canRun=false). */
	ran: boolean;
	/** Whether `native.preventDefault()` was called. */
	prevented: boolean;
}

/**
 * An interceptor wraps the rest of the chain (`next`). Call `next()` to continue
 * (returning its CommandResult); SKIP it to VETO; mutate `ev.payload` before `next()`
 * to TRANSFORM. The OUTERMOST (first-listed) interceptor sees the final result.
 */
export type Interceptor = (ev: DispatchEvent, next: () => CommandResult) => CommandResult;

/** The dispatch fn signature wired into the grid root. */
export type Dispatch = (command: string | null, native?: Event, payload?: unknown) => CommandResult;

const UNRESOLVED: CommandResult = { command: null, ran: false, prevented: false };

/**
 * Wrap an `onCommand(ev, result)` callback as an INNERMOST tail OBSERVER interceptor:
 * it always calls `next()` (never vetoes / transforms), then reports the final
 * {@link CommandResult} to the consumer. Listed LAST in the interceptor array so it
 * runs after all consumer interceptors (closest to the core) and observes the actual
 * outcome — purely observational, never altering behavior.
 */
export function tailObserver(onCommand: (ev: DispatchEvent, result: CommandResult) => void): Interceptor {
	return (ev, next) => {
		const result = next();
		onCommand(ev, result);
		return result;
	};
}

/**
 * Build the dispatch fn over a registry + live context + (optional) interceptor list.
 * `getContext` is read fresh per dispatch so the latched context is always current.
 */
export function makeDispatch(
	registry: GridCommandRegistry,
	getContext: () => GridCommandContext,
	interceptors: Interceptor[] = [],
): Dispatch {
	return function dispatch(command, native, payload): CommandResult {
		if (command == null) return UNRESOLVED;
		const cmd = registry.get(command);
		if (!cmd) return { command, ran: false, prevented: false };

		const ev: DispatchEvent = { command, native, payload };

		// The CORE runs last (innermost): canRun gate → preventDefault → run.
		const core = (): CommandResult => {
			const ctx = getContext();
			if (cmd.canRun && !cmd.canRun(ctx, ev.payload)) {
				return { command, ran: false, prevented: false };
			}
			let prevented = false;
			if (ev.native) {
				ev.native.preventDefault();
				prevented = true;
			}
			void cmd.run(ctx, ev.payload);
			return { command, ran: true, prevented };
		};

		// reduceRight so the FIRST-LISTED interceptor is the OUTERMOST wrapper.
		const chain = interceptors.reduceRight<() => CommandResult>(
			(next, interceptor) => () => interceptor(ev, next),
			core,
		);
		return chain();
	};
}

/**
 * Keybinding primitives — COPIED from packages/command-palette/src/keybinding.ts
 * (kbd / matchKeyBinding / isMac / isEditableTarget) so @constructive-io/sheets stays
 * distributable WITHOUT a dependency on command-palette. Keep the two in sync by hand;
 * the logic is intentionally identical (strict modifier matching, Mac mod=meta).
 */

/** Modifier key abstraction. 'mod' = Cmd on Mac, Ctrl on Windows/Linux. */
export type KeyModifier = 'mod' | 'shift' | 'alt';

/** Structured key binding — matchable against KeyboardEvents. */
export interface KeyBinding {
	modifiers?: KeyModifier[];
	/** Lowercase key name: 'h', 'k', 'enter', 'backspace', ',', '/', etc. */
	key: string;
}

/** Ergonomic KeyBinding factory. */
export function kbd(key: string, ...modifiers: KeyModifier[]): KeyBinding {
	return modifiers.length > 0 ? { key, modifiers } : { key };
}

/** Platform detection with SSR fallback (assumes non-Mac). */
export function isMac(): boolean {
	if (typeof navigator === 'undefined') return false;
	return /mac|ipod|iphone|ipad/i.test(navigator.platform ?? '');
}

/** Check if event target is an editable element (input, textarea, select, contenteditable). */
export function isEditableTarget(target: EventTarget | null): boolean {
	if (!target || !(target instanceof HTMLElement)) return false;
	const tag = target.tagName;
	if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true;
	return target.contentEditable === 'true';
}

/** Match a KeyboardEvent against a KeyBinding with strict modifier check. */
export function matchKeyBinding(event: KeyboardEvent, binding: KeyBinding): boolean {
	// Compare key (case-insensitive)
	if (event.key.toLowerCase() !== binding.key.toLowerCase()) return false;

	const mods = binding.modifiers ?? [];
	const wantMod = mods.includes('mod');
	const wantShift = mods.includes('shift');
	const wantAlt = mods.includes('alt');

	// On Mac, 'mod' maps to metaKey; elsewhere, ctrlKey
	const modPressed = isMac() ? event.metaKey : event.ctrlKey;

	// Strict: every required modifier must be pressed, no extras
	if (wantMod !== modPressed) return false;
	if (wantShift !== event.shiftKey) return false;
	if (wantAlt !== event.altKey) return false;

	// Prevent false positives: if mod maps to meta on Mac, ctrl shouldn't be pressed (and vice versa)
	if (isMac()) {
		if (!wantMod && event.ctrlKey) return false;
	} else {
		if (!wantMod && event.metaKey) return false;
	}

	return true;
}

/**
 * DEFAULT_KEYMAP + resolveKeyCommand (P4 Phase 1).
 *
 * A keymap is an ordered Binding[]; `resolveKeyCommand` returns the FIRST matching
 * binding's command id (first-match-wins) or `null` when nothing matches. The grid tries
 * every binding of a chord in order (`resolveKeyBindings`) and runs the first whose command
 * can run, so one key can mean "close the panel, else clear the selection". Nothing matches
 * an unbound PRINTABLE key either, so the dispatch funnel can fall to the `editor.typeToEdit`
 * sentinel (the printable-key path is NOT in the keymap; the funnel routes it explicitly).
 *
 * Triggers come in three kinds — `key` (matched here via the copied matchKeyBinding),
 * `pointer` (gesture, wired in Stage B / Phase 2), and `native` (a raw DOM event name).
 * Pointer + native triggers are declared in the table for invariant completeness even
 * though only key triggers resolve through `resolveKeyCommand`.
 *
 * `Mod` is ctrl on win/linux, cmd on mac — encoded as the copied `'mod'` KeyModifier, so
 * matchKeyBinding's platform branch (isMac) picks the right physical key.
 */

import { kbd, matchKeyBinding, type KeyBinding } from './keybinding';

/** A pointer gesture name (resolved by the pointer handlers, not the key funnel). */
export type PointerGesture =
	| 'click'
	| 'shiftClick'
	| 'dblclick'
	| 'headerClick'
	| 'headerShiftClick'
	| 'rowToggle'
	| 'rowToggleAll';

/** What fires a command. */
export type Trigger =
	| { kind: 'key'; binding: KeyBinding }
	| { kind: 'pointer'; gesture: PointerGesture }
	| { kind: 'native'; event: string };

/** A trigger -> command id mapping. */
export interface Binding {
	trigger: Trigger;
	command: string;
	/**
	 * Keep the key from the browser while the grid has focus even when the command
	 * does not run. For chords whose browser action loses work (Mod+R reloads the page).
	 */
	claim?: boolean;
}

/** key-trigger shorthand. */
function key(binding: KeyBinding, command: string, options: { claim?: boolean } = {}): Binding {
	return { trigger: { kind: 'key', binding }, command, ...(options.claim ? { claim: true } : {}) };
}

/** pointer-trigger shorthand. */
function pointer(gesture: PointerGesture, command: string): Binding {
	return { trigger: { kind: 'pointer', gesture }, command };
}

/**
 * The default key + pointer + native bindings. Order matters for the key kind
 * (first-match-wins). matchKeyBinding is STRICT on modifiers, so the undo (Mod+Z) and
 * redo (Mod+Shift+Z) chords never alias even though they share the 'z' key.
 */
export const DEFAULT_KEYMAP: Binding[] = [
	// undo / redo
	key(kbd('z', 'mod'), 'edit.undo'),
	key(kbd('z', 'mod', 'shift'), 'edit.redo'),
	key(kbd('y', 'mod'), 'edit.redo'),

	// select all
	key(kbd('a', 'mod'), 'selection.all'),

	// clear cells (Delete / Backspace → null over the active range). The funnel bails
	// while an overlay editor is open, so these still edit text inside an editor.
	key(kbd('Delete'), 'cell.clear'),
	key(kbd('Backspace'), 'cell.clear'),

	// fill (Mod = Cmd/mac, Ctrl/win). Mod+R is the spreadsheet chord for fill right and the
	// browser chord for reload. The grid claims it, so pressing it on a selection that cannot
	// fill right never reloads the page and loses unsaved drafts.
	key(kbd('d', 'mod'), 'fill.down'),
	key(kbd('r', 'mod'), 'fill.right', { claim: true }),

	// view: search, filters, sort
	key(kbd('f', 'mod'), 'view.focusSearch'),
	key(kbd('f', 'mod', 'shift'), 'view.openFilters'),
	key(kbd('s', 'mod', 'shift'), 'view.openSort'),
	key(kbd('s', 'mod'), 'view.saveView'),

	// record panel: open the active row (plain Space stays type-to-edit)
	key(kbd(' ', 'shift'), 'record.open'),

	// Escape, outermost first: close the record panel, else collapse the range, else clear the
	// active cell. An open editor or popover takes Escape before the grid sees it.
	key(kbd('Escape'), 'record.close'),
	key(kbd('Escape'), 'selection.clear'),

	// context menu at the active cell (its "Open link" item opens a link cell from the keyboard)
	key(kbd('F10', 'shift'), 'cell.openContextMenu'),
	key(kbd('ContextMenu'), 'cell.openContextMenu'),

	// columns: header menu, move the active cell's column
	key(kbd('ArrowDown', 'alt'), 'column.openMenu'),
	key(kbd('ArrowLeft', 'alt', 'shift'), 'column.moveLeft'),
	key(kbd('ArrowRight', 'alt', 'shift'), 'column.moveRight'),

	// arrow move (plain)
	key(kbd('ArrowUp'), 'cell.moveUp'),
	key(kbd('ArrowDown'), 'cell.moveDown'),
	key(kbd('ArrowLeft'), 'cell.moveLeft'),
	key(kbd('ArrowRight'), 'cell.moveRight'),

	// arrow extend (shift)
	key(kbd('ArrowUp', 'shift'), 'cell.extendUp'),
	key(kbd('ArrowDown', 'shift'), 'cell.extendDown'),
	key(kbd('ArrowLeft', 'shift'), 'cell.extendLeft'),
	key(kbd('ArrowRight', 'shift'), 'cell.extendRight'),

	// absolute nav — base + ctrl/meta + shift variants all resolve to one command (the
	// command body branches on the payload via computeKeyNavTarget, matching the original).
	key(kbd('Tab'), 'cell.navAbsolute'),
	key(kbd('Tab', 'shift'), 'cell.navAbsolute'),
	key(kbd('Home'), 'cell.navAbsolute'),
	key(kbd('Home', 'mod'), 'cell.navAbsolute'),
	key(kbd('End'), 'cell.navAbsolute'),
	key(kbd('End', 'mod'), 'cell.navAbsolute'),
	key(kbd('PageUp'), 'cell.navAbsolute'),
	key(kbd('PageDown'), 'cell.navAbsolute'),

	// open editor at active cell
	key(kbd('Enter'), 'editor.openActive'),
	key(kbd('F2'), 'editor.openActive'),

	// pointer gestures (wired Stage B / Phase 2)
	pointer('click', 'cell.activate'),
	pointer('shiftClick', 'cell.extendToClicked'),
	pointer('dblclick', 'editor.open'),
	pointer('headerClick', 'header.sortToggle'),
	pointer('headerShiftClick', 'header.sortToggle'),
	pointer('rowToggle', 'rowmarker.toggleRow'),
	pointer('rowToggleAll', 'rowmarker.toggleAll'),
];

/**
 * Resolve a KeyboardEvent to a command id via the keymap (first key-trigger match wins).
 * Returns `null` when no key binding matches — including unbound printable keys — so the
 * caller can fall to the `editor.typeToEdit` sentinel. Pointer / native triggers are
 * ignored here (they are not key events).
 */
export function resolveKeyCommand(event: KeyboardEvent, keymap: Binding[] = DEFAULT_KEYMAP): string | null {
	return resolveKeyBinding(event, keymap)?.command ?? null;
}

/** The first key binding that matches the event, or null. Use it to honor `claim`. */
export function resolveKeyBinding(event: KeyboardEvent, keymap: Binding[] = DEFAULT_KEYMAP): Binding | null {
	return resolveKeyBindings(event, keymap)[0] ?? null;
}

/** Every key binding that matches the event, in keymap order (consumer bindings first). */
export function resolveKeyBindings(event: KeyboardEvent, keymap: Binding[] = DEFAULT_KEYMAP): Binding[] {
	return keymap.filter((binding) => binding.trigger.kind === 'key' && matchKeyBinding(event, binding.trigger.binding));
}

/**
 * DEFAULT_COMMANDS + createGridCommandRegistry (P4 Phase 1).
 *
 * Each command body is LIFTED VERBATIM from grid/sheets.tsx's handleGridKeyDown /
 * handleActivateCell / openEditor / openEditorAtActiveCell branches — same dispatcher
 * calls, same anchor resets, same clamp/scroll order. The handler's local guards
 * (`if (rows === 0 || colCount === 0) return`) are preserved as `canRun` where the
 * original returned WITHOUT preventing default, and inline where the original DID
 * prevent default first (Ctrl+A / arrows / nav: the original called preventDefault()
 * before the empty-grid early return, so the no-op must still preventDefault — that is
 * the core's job once the command resolves, and the body simply returns early).
 *
 * Phase 1 is a refactor: these bodies call `ctx.<dispatcher>` (the existing stable fns).
 */

import { computeKeyNavTarget, emptySheetsSelection, selectAllCells, selectCell } from '../selection/selection-model';
import type { SelectionRect, SheetsSelection } from '../selection/selection-model';
import { parseTSV, tileMatrix } from '../selection/tsv';
import { fillDownWrites, fillRightWrites, extendedFillRect, fillDragWrites } from '../selection/fill';
import type { CellWrite } from '../grid/hooks/use-batch-commit';
import type { GridCommand, GridCommandRegistry } from './types';
import type { GridCommandContext, CellMatrix } from './context';

/** Payload for `cell.activate` / `cell.extendToClicked` (pointer). */
export interface CellPointerPayload {
	col: number;
	row: number;
}

/** Payload for `editor.open` (dblclick). */
export interface EditorOpenPayload {
	rowIndex: number;
	colKey: string;
	anchorRect: DOMRect;
	initialText?: string;
}

/** Payload for `editor.typeToEdit` (printable key sentinel). */
export interface TypeToEditPayload {
	char: string;
}

/** Payload for `cell.navAbsolute` (Tab/Home/End/PageUp/PageDown). */
export interface NavAbsolutePayload {
	key: string;
	ctrlOrMeta: boolean;
	shift: boolean;
	/** Visible page span (rows); the funnel derives this from the scroll element clientHeight. */
	pageRows: number;
}

/** Payload for `header.sortToggle`. `additive` (Shift+click) adds the column to the sort. */
export interface SortTogglePayload {
	colKey: string;
	additive?: boolean;
}

/** Optional payload for `view.sortAscending` / `view.sortDescending`; defaults to the active cell's column. */
export interface SortColumnPayload {
	colKey?: string;
}

/** Payload for `rowmarker.toggleRow`. */
export interface ToggleRowPayload {
	rowIndex: number;
	shift: boolean;
}

/** Payload for `fill.drag` (fill-handle nub release). `from` = source band, `to` = `[col,row]` under the pointer. */
export interface FillDragPayload {
	from: SelectionRect;
	to: [number, number];
}

/**
 * The minimal `DataTransfer` slice the clipboard commands read/write — `ClipboardEvent.clipboardData`
 * conforms (so does a test stub). Kept narrow so the command never depends on the full DOM type.
 */
export interface ClipboardLike {
	getData(format: string): string;
	setData(format: string, data: string): void;
}

/** Payload for `clipboard.copy` / `clipboard.cut` / `clipboard.paste` (native clipboard event). */
export interface ClipboardPayload {
	clipboard: ClipboardLike | null;
}

/** Shared empty-grid guard (the original `rows === 0 || colCount === 0` short-circuit). */
function gridNonEmpty(ctx: GridCommandContext): boolean {
	return ctx.rowCount > 0 && ctx.colCount > 0;
}

/** Payload of `selection.clear`. `whole` clears the cell and its range in one step (a press outside the grid). */
export interface SelectionClearPayload {
	whole?: boolean;
}

/** The range covers more than one cell. */
function hasMultiCellRange(selection: SheetsSelection | undefined): boolean {
	const range = selection?.current?.range;
	return !!range && range.width * range.height > 1;
}

/** Drop the active cell and its range; the row checkbox selection stays. */
function withoutActiveCell(selection: SheetsSelection): SheetsSelection {
	return { rows: selection.rows, columns: selection.columns };
}

/**
 * Bring the cursor back when the grid has no active cell: the last active cell while it is
 * still inside the grid, else the first cell. Navigation keys do this instead of moving, so the
 * first key press after a clear shows where the cursor is.
 */
function resumeCursor(ctx: GridCommandContext): void {
	const [col, row] = ctx.resumeCell ?? [0, 0];
	ctx.setAnchor([col, row]);
	ctx.setActiveCell(col, row);
	ctx.scrollToCell(col, row);
}

/**
 * The cell range the clipboard commands act on: the active selection range when present,
 * else a 1×1 rect at the active cell. `null` when there is no active cell (empty grid /
 * no cursor) — the copy/cut/paste `canRun` guards return false on null.
 */
function clipboardRange(ctx: GridCommandContext): SelectionRect | null {
	const range = ctx.selection?.current?.range;
	if (range) return range;
	const cell = ctx.activeCell;
	if (!cell) return null;
	return { x: cell[0], y: cell[1], width: 1, height: 1 };
}

/** Build a `null` write for every cell in `rect` (clamped to the column keys). */
function clearRangeWrites(rect: SelectionRect, columnKeys: readonly string[]): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < rect.height; r++) {
		for (let c = 0; c < rect.width; c++) {
			const colKey = columnKeys[rect.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex: rect.y + r, colKey, value: null });
		}
	}
	return writes;
}

/** True when the async `navigator.clipboard` API is reachable (secure context, browser). */
function navigatorClipboard(): Clipboard | null {
	return typeof navigator !== 'undefined' && navigator.clipboard ? navigator.clipboard : null;
}

/** The `null` writes that clear every cell of a copied/cut matrix (cut's source clear). */
function cutRangeWrites(matrix: CellMatrix): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < matrix.rows.length; r++) {
		for (let c = 0; c < matrix.cols.length; c++) {
			const colKey = matrix.cols[c];
			if (colKey == null) continue;
			writes.push({ rowIndex: matrix.rows[r], colKey, value: null });
		}
	}
	return writes;
}

/**
 * Tile a parsed TSV `source` onto the target and build the clamped writes — the shared body
 * of both paste paths (native event + navigator fallback). `anchor` is the active cell's
 * top-left; `range` (when present + larger than the source) drives tiling.
 */
function pasteWrites(ctx: GridCommandContext, anchor: readonly [number, number], text: string): CellWrite[] {
	const source = parseTSV(text);
	const range = ctx.selection?.current?.range;
	const targetW = range ? range.width : source[0]?.length ?? 0;
	const targetH = range ? range.height : source.length;
	const matrix = tileMatrix(source, targetW, targetH);

	const [anchorCol, anchorRow] = anchor;
	const writes: CellWrite[] = [];
	for (let r = 0; r < matrix.length; r++) {
		const rowIndex = anchorRow + r;
		if (rowIndex >= ctx.rowCount) break; // clamp to grid bottom
		const line = matrix[r];
		for (let c = 0; c < line.length; c++) {
			const colIndex = anchorCol + c;
			if (colIndex >= ctx.colCount) break; // clamp to grid right
			const colKey = ctx.columnKeys[colIndex];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value: line[c] });
		}
	}
	return writes;
}

/** Optional payload of the column commands; defaults to the active cell's column. */
export interface ColumnCommandPayload {
	colKey?: string;
}

/** The column a command acts on: the payload's, else the active cell's. */
function targetColumn(ctx: GridCommandContext, payload: unknown): string | null {
	const explicit = (payload as SortColumnPayload | undefined)?.colKey;
	if (explicit) return explicit;
	const cell = ctx.activeCell;
	return cell ? ctx.columnKeys[cell[0]] ?? null : null;
}

function makeSortColumnCommand(id: string, direction: 'asc' | 'desc'): GridCommand {
	return {
		id,
		canRun: (ctx, payload) => {
			const column = targetColumn(ctx, payload);
			return column !== null && ctx.view.canSort(column);
		},
		run: (ctx, payload) => {
			const column = targetColumn(ctx, payload);
			if (column) ctx.view.sortBy(column, direction);
		},
	};
}

/** A command on one column, runnable when `can` allows it for that column. */
function columnCommand(id: string, can: (ctx: GridCommandContext, column: string) => boolean, run: (ctx: GridCommandContext, column: string) => void): GridCommand {
	return {
		id,
		canRun: (ctx, payload) => {
			const column = targetColumn(ctx, payload);
			return column !== null && can(ctx, column);
		},
		run: (ctx, payload) => {
			const column = targetColumn(ctx, payload);
			if (column) run(ctx, column);
		},
	};
}

/** Move the column one place and keep the cursor on it. */
function moveColumnCommand(id: string, step: -1 | 1): GridCommand {
	return columnCommand(
		id,
		(ctx, column) => ctx.view.canMove(column, step),
		(ctx, column) => {
			ctx.view.move(column, step);
			const cell = ctx.activeCell;
			if (cell && ctx.columnKeys[cell[0]] === column) {
				const next: [number, number] = [cell[0] + step, cell[1]];
				ctx.setAnchor(next);
				ctx.setActiveCell(next[0], next[1]);
				ctx.scrollToCell(next[0], next[1]);
			}
		},
	);
}

/** Optional payload of `record.open`; defaults to the active cell's row. */
export interface RecordOpenPayload {
	rowIndex?: number;
}

function targetRow(ctx: GridCommandContext, payload: unknown): number | null {
	const explicit = (payload as RecordOpenPayload | undefined)?.rowIndex;
	if (typeof explicit === 'number') return explicit;
	return ctx.activeCell?.[1] ?? null;
}

/** Column layout, saved-view and record commands. */
export const COLUMN_COMMANDS: GridCommand[] = [
	columnCommand('column.hide', (ctx, column) => ctx.view.canHide(column), (ctx, column) => ctx.view.hide(column)),
	moveColumnCommand('column.moveLeft', -1),
	moveColumnCommand('column.moveRight', 1),
	columnCommand('column.freezeUpTo', (ctx, column) => ctx.columnKeys.includes(column), (ctx, column) => ctx.view.freezeUpTo(column)),
	{ id: 'column.unfreeze', canRun: (ctx) => ctx.view.frozenCount > 0, run: (ctx) => ctx.view.unfreeze() },
	columnCommand(
		'column.openMenu',
		(ctx, column) => ctx.columnKeys.includes(column),
		(ctx, column) => {
			const cell = ctx.activeCell;
			ctx.scrollToCell(ctx.columnKeys.indexOf(column), cell?.[1] ?? 0);
			ctx.view.openColumnMenu(column);
		},
	),
	columnCommand('view.filterByColumn', (ctx, column) => ctx.view.canFilterBy(column), (ctx, column) => ctx.view.filterBy(column)),
	{ id: 'view.openFields', canRun: (ctx) => ctx.view.canOpenFields, run: (ctx) => ctx.view.openFields() },
	{ id: 'view.openViews', canRun: (ctx) => ctx.view.canOpenViews, run: (ctx) => ctx.view.openViews() },
	{ id: 'view.saveView', canRun: (ctx) => ctx.view.canSaveView, run: (ctx) => ctx.view.saveView() },
	{
		id: 'record.open',
		canRun: (ctx, payload) => {
			const row = targetRow(ctx, payload);
			return row !== null && Boolean(ctx.record?.canOpen(row));
		},
		run: (ctx, payload) => {
			const row = targetRow(ctx, payload);
			if (row !== null) ctx.record?.open(row);
		},
	},
	{
		id: 'record.close',
		canRun: (ctx) => Boolean(ctx.record?.isOpen?.()),
		run: (ctx) => ctx.record?.close?.(),
	},
	{
		id: 'record.new',
		canRun: (ctx) => Boolean(ctx.newRecord?.canCreate()),
		run: (ctx) => ctx.newRecord?.open(),
	},
];

/** The link the active cell holds, or null. */
function activeLink(ctx: GridCommandContext): string | null {
	const cell = ctx.activeCell;
	return cell && ctx.link ? ctx.link.hrefAt(cell[0], cell[1]) : null;
}

/** Cell commands that reach past the grid: open a link, open the context menu from the keyboard. */
export const CELL_COMMANDS: GridCommand[] = [
	{
		id: 'cell.openLink',
		canRun: (ctx) => activeLink(ctx) !== null,
		run: (ctx) => {
			const href = activeLink(ctx);
			if (href) ctx.link?.open(href);
		},
	},
	{
		id: 'cell.openContextMenu',
		canRun: (ctx) => ctx.activeCell != null && ctx.contextMenu != null,
		run: (ctx) => {
			const cell = ctx.activeCell;
			if (cell) ctx.contextMenu?.open(cell[0], cell[1]);
		},
	},
];

/**
 * Filter, sort and search commands. Each is runnable only when the table model
 * supports it, so an unsupported chord falls through to the browser.
 */
export const VIEW_COMMANDS: GridCommand[] = [
	{
		id: 'view.focusSearch',
		canRun: (ctx) => ctx.view.canSearch,
		run: (ctx) => {
			ctx.view.focusSearch();
		},
	},
	{
		id: 'view.clearSearch',
		canRun: (ctx) => ctx.view.hasSearch,
		run: (ctx) => ctx.view.clearSearch(),
	},
	{
