import { mapToFrontendCellType } from '../cell-types/type-mapping';

import { createMetadataHash } from './metadata-hash';
import type {
	BuildFormSpecOptions,
	DynamicFormSpec,
	MetaField,
	MetaTable,
	ScalarFieldKind,
	ScalarFieldSpec,
} from './types';

const SCALAR_CELL_TYPE_TO_KIND: Partial<Record<string, ScalarFieldKind>> = {
	text: 'text',
	textarea: 'multiline',
	citext: 'text',
	bpchar: 'text',
	email: 'email',
	url: 'url',
	phone: 'phone',
	uuid: 'uuid',
	inet: 'inet',
	number: 'number',
	integer: 'integer',
	// Cell types this builder predates keep the kind they had before (big whole numbers were integers).
	bigint: 'integer',
	smallint: 'smallint',
	decimal: 'decimal',
	currency: 'currency',
	percentage: 'percentage',
	boolean: 'boolean',
	bit: 'bit',
	bitstring: 'bit',
	date: 'date',
	datetime: 'datetime',
	time: 'time',
	timestamptz: 'timestamptz',
	json: 'json',
	jsonb: 'json',
	tsvector: 'tsvector',
};

const HUMAN_CASE_REGEX = /([a-z0-9])([A-Z])/g;

/**
 * Build a form spec from a raw `_meta` table.
 *
 * @deprecated Use `buildModelFormSpec(tableModel, mode)` and `buildModelFormSchema(spec)`:
 * they follow the table model's write flags, limits and choices, and check values with
 * the same rules as the grid.
 */
export function buildScalarFormSpec(metaTable: MetaTable, options: BuildFormSpecOptions = {}): DynamicFormSpec | null {
	const fields: ScalarFieldSpec[] = [];
	const uniqueFieldSet = collectSingleFieldUniqueNames(metaTable);
	const primaryFieldSet = collectSingleFieldPrimaryNames(metaTable);

	for (const field of metaTable.fields ?? []) {
		if (!field) continue;

		const spec = createScalarFieldSpec(field, options, uniqueFieldSet, primaryFieldSet);
		if (!spec) continue;

		fields.push(spec);
	}

	if (fields.length === 0) {
		return null;
	}

	const versionHash = createMetadataHash({
		table: metaTable.name,
		fields: fields.map((f) => ({
			name: f.name,
			kind: f.kind,
			nullable: f.nullable,
			metadata: f.metadata,
			maxLength: f.maxLength,
			minLength: f.minLength,
			minimum: f.minimum,
			maximum: f.maximum,
			enumValues: f.enumValues,
		})),
	});

	return {
		tableName: metaTable.name,
		versionHash,
		fields,
	};
}

export function findTableFormSpec(
	meta: MetaTable[] | null | undefined,
	tableName: string,
	options: BuildFormSpecOptions = {},
): DynamicFormSpec | null {
	if (!meta) return null;
	const table = meta.find((item) => item?.name === tableName);
	if (!table) return null;
	return buildScalarFormSpec(table, options);
}

function createScalarFieldSpec(
	metaField: MetaField,
	options: BuildFormSpecOptions,
	uniqueFields: Set<string>,
	primaryFields: Set<string>,
): ScalarFieldSpec | null {
	const { multilineFields } = options;
	const cellType = mapToFrontendCellType({
		gqlType: metaField.type.gqlType,
		isArray: metaField.type.isArray,
		pgAlias: metaField.type.pgAlias,
		pgType: metaField.type.pgType,
		subtype: metaField.type.subtype ?? undefined,
		encoding: metaField.type.encoding,
	});

	if (metaField.type.isArray) {
		return null;
	}

	let kind = SCALAR_CELL_TYPE_TO_KIND[cellType];

	if (!kind && cellType === 'text' && multilineFields?.has(metaField.name)) {
		kind = 'multiline';
	}

	if (!kind) {
		return null;
	}

	const nullable = isFieldNullable(metaField);
	const { maxLength, numericPrecision, numericScale } = extractTypmodConstraints(metaField);

	const label = humanize(metaField.name);
	const description = buildDescription(metaField);

	const spec: ScalarFieldSpec = {
		name: metaField.name,
		label,
		description,
		kind,
		nullable,
		metadata: {
			cellType,
			gqlType: metaField.type.gqlType,
			pgAlias: metaField.type.pgAlias ?? undefined,
			pgType: metaField.type.pgType ?? undefined,
			subtype: metaField.type.subtype ?? undefined,
			typmod: metaField.type.typmod ?? undefined,
			encoding: metaField.type.encoding ?? undefined,
		},
		constraints: {
			isUnique: uniqueFields.has(metaField.name) || undefined,
			isPrimaryKey: primaryFields.has(metaField.name) || undefined,
		},
	};

	if (metaField.enumValues?.values?.length) {
		spec.enumValues = [...metaField.enumValues.values];
	}

	if (maxLength != null) {
		spec.maxLength = maxLength;
	}

	if (numericPrecision != null) {
		spec.numericPrecision = numericPrecision;
	}

	if (numericScale != null) {
		spec.numericScale = numericScale;
	}

	if (
		kind === 'decimal' ||
		kind === 'number' ||
		kind === 'integer' ||
		kind === 'smallint' ||
		kind === 'currency' ||
		kind === 'percentage'
	) {
		const { minimum, maximum } = extractNumericCheckBounds(metaField);
		if (minimum != null) spec.minimum = minimum;
		if (maximum != null) spec.maximum = maximum;
	}

	if (kind === 'json') {
		spec.description = description ?? 'JSON value';
	}

	if (kind === 'boolean') {
		spec.defaultValue = false;
	}

	return spec;
}

function buildDescription(metaField: MetaField): string | undefined {
	if (metaField.description) return metaField.description;
	const details: string[] = [];
	const { pgAlias, pgType, subtype } = metaField.type;

	if (pgAlias && pgAlias !== pgType) {
		details.push(pgAlias);
	}
	if (pgType) {
		details.push(pgType);
	}
	if (subtype) {
		details.push(subtype);
	}

	return details.length > 0 ? details.join(' • ') : undefined;
}

function humanize(name: string): string {
	return name.replace(HUMAN_CASE_REGEX, '$1 $2').replace(/^./, (str) => str.toUpperCase());
}

function isFieldNullable(metaField: MetaField): boolean {
	if (metaField.isNotNull === true || metaField.type.isNotNull === true) return false;
	const gqlType = metaField.type.gqlType;
	if (gqlType.endsWith('!')) return false;
	// Note: modifier is a numeric code from PostgreSQL, not a string enum
	// The gqlType check above is the primary indicator of non-nullability
	return true;
}

function extractTypmodConstraints(metaField: MetaField): {
	maxLength?: number;
	numericPrecision?: number;
	numericScale?: number;
} {
	const typmod = metaField.type.typmod ?? null;
	const pgType = metaField.type.pgType?.toLowerCase();

	if (typmod == null || typmod < 0) {
		return {};
	}

	if (pgType === 'varchar' || pgType === 'character varying' || pgType === 'bpchar' || pgType === 'character') {
		return { maxLength: Math.max(0, typmod - 4) };
	}

	if (pgType === 'numeric' || pgType === 'decimal') {
		const precision = ((typmod - 4) >> 16) & 65535;
		const scale = (typmod - 4) & 65535;
		return {
			numericPrecision: precision || undefined,
			numericScale: scale || undefined,
		};
	}

	return {};
}

function extractNumericCheckBounds(_metaField: MetaField): { minimum?: number; maximum?: number } {
	// Placeholder for future enhancements: currently return empty bounds.
	// Backend check constraints can be parsed here when the metadata exposes readable expressions.
	return {};
}

function collectSingleFieldUniqueNames(metaTable: MetaTable): Set<string> {
	const result = new Set<string>();

	for (const constraint of metaTable.uniqueConstraints ?? []) {
		if (!constraint || !constraint.fields) continue;
		const fields = constraint.fields.filter((field): field is MetaField => Boolean(field));
		if (fields.length === 1) {
			result.add(fields[0].name);
		}
	}

	return result;
}

function collectSingleFieldPrimaryNames(metaTable: MetaTable): Set<string> {
	const result = new Set<string>();
	for (const constraint of metaTable.primaryKeyConstraints ?? []) {
		if (!constraint) continue;
		const fields = constraint.fields?.filter((field): field is MetaField => Boolean(field));
		if (fields && fields.length === 1) {
			result.add(fields[0].name);
		}
	}
	return result;
}

export * from './types';
export * from './metadata-hash';
export * from './form-spec-builder';
export * from './zod-schema';
export * from './mutations';
export * from './model-form';

export function createMetadataHash(value: unknown): string {
	const serialized = JSON.stringify(value, stableReplacer);
	let hash = 0;
	for (let index = 0; index < serialized.length; index += 1) {
		hash = (hash * 33) ^ serialized.charCodeAt(index);
	}

	return `h${(hash >>> 0).toString(16)}`;
}

function stableReplacer(_key: string, value: unknown): unknown {
	if (value && typeof value === 'object' && !Array.isArray(value)) {
		return Object.keys(value)
			.sort()
			.reduce<Record<string, unknown>>((acc, key) => {
				acc[key] = (value as Record<string, unknown>)[key];
				return acc;
			}, {});
	}
	return value;
}

// Form spec and validation schema built from the table model, for a record form
// (create a record, or edit one) that must follow the same rules as the grid.
//
// Each field carries its column, its cell type (the same routing the grid uses), and
// whether it can be written in this mode, with the reason when it cannot. The schema
// checks every value with `parseColumnInput`, so a form and a grid cell accept and
// refuse exactly the same values, and it outputs the parsed values (exact decimal
// strings, enum wire values) ready for `encodeWriteValues`.

import { z } from 'zod';

import type { ColumnModel, ColumnOption, TableModel } from '@constructive-io/data';

import { parseColumnInput } from '../cell-types/column-value';
import { fieldLabel } from '../cell-types/field-label';
import { resolveModelCellRoute } from '../grid/cell-routing';
import { createMetadataHash } from './metadata-hash';

/** Whether the form creates a record or edits an existing one. */
export type ModelFormMode = 'create' | 'update';

export interface ModelFormField {
	/** Field name on the row (also the key in the form values). */
	name: string;
	/** Readable label. */
	label: string;
	/** Column comment, or null. */
	description: string | null;
	/** The table-model column. */
	column: ColumnModel;
	/** The cell type key the grid uses for this column (a built-in cell type or a host override); it picks the editor. */
	cellType: string;
	/** The form may set this field in this mode. */
	writable: boolean;
	/** Why the field cannot be set in this mode, or null when it can. */
	readOnlyReason: string | null;
	/** A value must be given: create requires it (no default), or an edit cannot empty it. */
	required: boolean;
	/** The column accepts no value. */
	nullable: boolean;
	/** Fixed choices, or null. `value` is what is stored. */
	options: readonly ColumnOption[] | null;
	maxLength: number | null;
	precision: number | null;
	scale: number | null;
}

export interface ModelFormSpec {
	/** `TableModel.key` of the table. */
	tableKey: string;
	/** GraphQL type name of the table. */
	tableName: string;
	mode: ModelFormMode;
	/** Changes whenever a field's rules change; use it as a cache key. */
	versionHash: string;
	/** Readable fields, in column order. */
	fields: ModelFormField[];
}

export interface BuildModelFormSpecOptions {
	/** Host cell-type overrides keyed by `tableName.fieldName` (`SheetsConfig.fieldTypeOverrides`). */
	typeOverrides?: Readonly<Record<string, string>>;
}

/**
 * Build the fields of a create or edit form from the table model. Each field's cell
 * type and read-only reason come from the grid's own routing (`resolveModelCellRoute`:
 * a create is routed like a draft row, an edit like a saved row with its key fixed),
 * so a form and a grid cell never disagree.
 */
export function buildModelFormSpec(model: TableModel, mode: ModelFormMode, options: BuildModelFormSpecOptions = {}): ModelFormSpec {
	const lockedFields = new Set(model.primaryKey);
	const fields: ModelFormField[] = model.columns
		.filter((column) => column.readable)
		.map((column) => {
			const { cellType, readOnlyReason } = resolveModelCellRoute({
				column,
				table: model,
				isDraftRow: mode === 'create',
				cellError: null,
				typeOverride: options.typeOverrides?.[`${model.name}.${column.name}`] ?? null,
				lockedFields,
			});
			const writable = readOnlyReason === null;
			return {
				name: column.name,
				label: fieldLabel(column.name),
				description: column.description,
				column,
				cellType,
				writable,
				readOnlyReason,
				required: writable && (mode === 'create' ? column.write.requiredOnCreate : !column.nullable),
				nullable: column.nullable,
				options: column.value.options,
				maxLength: column.value.maxLength,
				precision: column.value.precision,
				scale: column.value.scale,
			};
		});

	const versionHash = createMetadataHash({
		table: model.key,
		mode,
		fields: fields.map((field) => ({
			name: field.name,
			cellType: field.cellType,
			writable: field.writable,
			required: field.required,
			nullable: field.nullable,
			options: field.options,
			maxLength: field.maxLength,
			precision: field.precision,
			scale: field.scale,
		})),
	});

	return { tableKey: model.key, tableName: model.name, mode, versionHash, fields };
}

function requiredOnSubmit(field: ModelFormField, mode: ModelFormMode): boolean {
	return mode === 'create' && field.required;
}

function fieldSchema(field: ModelFormField, mode: ModelFormMode): z.ZodType<unknown> {
	return z
		.unknown()
		.optional()
		.transform((value, ctx) => {
			// An untouched field is left out: the database default applies on create, the stored value stays on edit.
			if (value === undefined) return undefined;
			if (requiredOnSubmit(field, mode) && (value === null || value === '')) {
				ctx.addIssue({ code: 'custom', message: `${field.label} is required` });
				return z.NEVER;
			}
			// Clearing follows the column rules: null, '' for text that cannot be empty but has a default
			// (or on create), or a refusal.
			const parsed = parseColumnInput(field.column, value, { fromText: typeof value === 'string', creating: mode === 'create' });
			if (parsed.ok === false) {
				ctx.addIssue({ code: 'custom', message: parsed.reason });
				return z.NEVER;
			}
			return parsed.value;
		});
}

const modelSchemaCache = new Map<string, z.ZodObject<Record<string, z.ZodType<unknown>>>>();

/**
 * Build the validation schema of a model form. Only writable fields are in it; each
 * one is checked and parsed by the column's rules. Unknown keys are dropped, so a
 * read-only field can never reach a write.
 */
export function buildModelFormSchema(spec: ModelFormSpec): z.ZodObject<Record<string, z.ZodType<unknown>>> {
	const cached = modelSchemaCache.get(spec.versionHash);
	if (cached) return cached;
	const shape: Record<string, z.ZodType<unknown>> = {};
	for (const field of spec.fields) {
		if (field.writable) shape[field.name] = fieldSchema(field, spec.mode);
	}
	// A field a create requires must be present; an absent key never reaches its own check.
	const schema = z.object(shape).superRefine((values, ctx) => {
		for (const field of spec.fields) {
			if (!field.writable || !requiredOnSubmit(field, spec.mode)) continue;
			if (values[field.name] === undefined) ctx.addIssue({ code: 'custom', path: [field.name], message: `${field.label} is required` });
		}
	});
	modelSchemaCache.set(spec.versionHash, schema);
	return schema;
}

import * as React from 'react';

import { useSheetsTable } from '../hooks/use-sheets-table';
import type { SheetsRowIdentifier } from '../row-identity';

export interface DynamicMutationResult<TData = unknown> {
	submit: (values: Record<string, unknown>) => Promise<TData | null>;
	isSubmitting: boolean;
	error: Error | null;
}

export function useDynamicCreate(tableName: string): DynamicMutationResult {
	const table = useSheetsTable(tableName, { enabled: false });

	const submit = React.useCallback(
		async (values: Record<string, unknown>) => {
			const result = await table.create(values);
			return result.createdRow ?? null;
		},
		[table],
	);

	return {
		submit,
		isSubmitting: table.isCreating,
		error: table.createError,
	};
}

export function useDynamicUpdate(tableName: string, rowId: SheetsRowIdentifier): DynamicMutationResult {
	const table = useSheetsTable(tableName, { enabled: false });

	const submit = React.useCallback(
		async (values: Record<string, unknown>) => {
			const result = await table.update(rowId, values);
			return result.updatedRow ?? null;
		},
		[table, rowId],
	);

	return {
		submit,
		isSubmitting: table.isUpdating,
		error: table.updateError,
	};
}

import type { CellType } from '../cell-types/types';
import type { MetaQuery } from '@constructive-io/data';

export type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;

export type MetaField = NonNullable<NonNullable<MetaTable['fields']>[number]>;

export interface ScalarConstraintHints {
	isUnique?: boolean;
	isPrimaryKey?: boolean;
}

export type ScalarFieldKind =
	| 'text'
	| 'multiline'
	| 'email'
	| 'url'
	| 'phone'
	| 'uuid'
	| 'inet'
	| 'number'
	| 'integer'
	| 'smallint'
	| 'decimal'
	| 'currency'
	| 'percentage'
	| 'boolean'
	| 'bit'
	| 'date'
	| 'datetime'
	| 'timestamptz'
	| 'time'
	| 'json'
	| 'tsvector';

export interface ScalarFieldSpec {
	name: string;
	label: string;
	description?: string;
	kind: ScalarFieldKind;
	nullable: boolean;
	defaultValue?: unknown;
	enumValues?: string[];
	maxLength?: number;
	minLength?: number;
	minimum?: number;
	maximum?: number;
	numericPrecision?: number;
	numericScale?: number;
	metadata: {
		cellType: CellType;
		gqlType: string;
		pgType?: string | null;
		pgAlias?: string | null;
		subtype?: string | null;
		typmod?: number | null;
		encoding?: MetaField['type']['encoding'];
	};
	constraints: ScalarConstraintHints;
}

export interface DynamicFormSpec {
	tableName: string;
	versionHash: string;
	fields: ScalarFieldSpec[];
}

export interface BuildFormSpecOptions {
	/**
	 * Optional set of field names that should be treated as multiline inputs despite being text-based.
	 */
	multilineFields?: Set<string>;
}

import { z } from 'zod';

import type { DynamicFormSpec, ScalarFieldSpec } from './types';

const schemaCache = new Map<string, z.ZodObject<Record<string, z.ZodTypeAny>>>();

export function buildZodSchema(spec: DynamicFormSpec): z.ZodObject<Record<string, z.ZodTypeAny>> {
	const cached = schemaCache.get(spec.versionHash);
	if (cached) {
		return cached;
	}

	const shape: Record<string, z.ZodTypeAny> = {};

	for (const field of spec.fields) {
		shape[field.name] = buildFieldSchema(field);
	}

	const schema = z.object(shape);
	schemaCache.set(spec.versionHash, schema);
	return schema;
}

function buildFieldSchema(field: ScalarFieldSpec): z.ZodTypeAny {
	let baseSchema: z.ZodTypeAny;
	let isStringSchema = false;

	switch (field.kind) {
		case 'email':
			baseSchema = z.string({ error: 'Email is required' }).email('Invalid email address');
			isStringSchema = true;
			break;
		case 'url':
			baseSchema = z.string({ error: 'URL is required' }).url('Invalid URL');
			isStringSchema = true;
			break;
		case 'phone':
			baseSchema = z
				.string({ error: 'Phone number is required' })
				.refine((value) => /^\+?[0-9\-()\s]+$/.test(value), { message: 'Invalid phone number' });
			break;
		case 'uuid':
			baseSchema = z.string({ error: 'UUID is required' }).uuid('Invalid UUID');
			isStringSchema = true;
			break;
		case 'inet':
			baseSchema = z
				.string({ error: 'IP address is required' })
				.refine((value) => isValidInet(value), { message: 'Invalid IP address' });
			break;
		case 'boolean':
			baseSchema = z.preprocess(
				(value) => {
					if (typeof value === 'string') {
						if (value === 'true') return true;
						if (value === 'false') return false;
					}
					return value;
				},
				z.boolean({ error: 'Required' }),
			);
			break;
		case 'bit':
			baseSchema = z.union([z.literal('0'), z.literal('1')]);
			break;
		case 'integer':
		case 'smallint':
		case 'number':
		case 'decimal':
		case 'currency':
		case 'percentage':
			baseSchema = buildNumericSchema(field);
			break;
		case 'date':
		case 'datetime':
		case 'timestamptz':
		case 'time':
			baseSchema = z
				.string({ error: 'Required' })
				.refine((value) => value.length > 0, { message: 'Required' });
			break;
		case 'json':
			baseSchema = z
				.string({ error: 'JSON is required' })
				.superRefine((value, ctx) => {
					if (value === '' && field.nullable) {
						return;
					}

				try {
					JSON.parse(value);
				} catch (_error) {
						ctx.addIssue({
							code: z.ZodIssueCode.custom,
							message: 'Invalid JSON',
						});
					}
				})
				.transform((value) => {
					if (value === '') {
						return null;
					}
					return JSON.parse(value);
				});
			break;
		case 'tsvector':
		case 'multiline':
		case 'text':
		default:
			baseSchema = z.string({ error: 'Required' });
			isStringSchema = true;
			break;
	}

	// Apply string constraints (tracked via isStringSchema flag for zod v4 compat)
	if (isStringSchema) {
		if ('maxLength' in field && typeof field.maxLength === 'number') {
			baseSchema = (baseSchema as z.ZodString).max(field.maxLength, `Must be at most ${field.maxLength} characters`);
		}

		if ('minLength' in field && typeof field.minLength === 'number') {
			baseSchema = (baseSchema as z.ZodString).min(field.minLength, `Must be at least ${field.minLength} characters`);
		}
	}

	if (field.enumValues && field.enumValues.length > 0) {
		baseSchema = z.enum(field.enumValues as [string, ...string[]]);
	}

	if (!field.nullable) {
		return baseSchema;
	}

	if (field.kind === 'json') {
		return baseSchema.optional().nullable();
	}

	return baseSchema.nullable().optional();
}

function buildNumericSchema(field: ScalarFieldSpec): z.ZodTypeAny {
	// Build inner number schema with all constraints
	const preprocessFn = (value: unknown) => {
		if (value === '' || value === null || value === undefined) {
			return value;
		}
		if (typeof value === 'number') return value;
		if (typeof value === 'string') {
			const parsed = Number(value);
			return Number.isNaN(parsed) ? value : parsed;
		}
		return value;
	};

	let innerSchema = z.number({
		error: 'Must be a valid number',
	});

	// Apply integer constraint
	if (field.kind === 'integer' || field.kind === 'smallint') {
		innerSchema = innerSchema.int('Must be an integer');
	}

	// Apply range constraints
	if (field.kind === 'smallint') {
		innerSchema = innerSchema.min(-32768, 'Must be >= -32768').max(32767, 'Must be <= 32767');
	} else {
		if (typeof field.minimum === 'number') {
			innerSchema = innerSchema.min(field.minimum, `Must be >= ${field.minimum}`);
		}

		if (typeof field.maximum === 'number') {
			innerSchema = innerSchema.max(field.maximum, `Must be <= ${field.maximum}`);
		}
	}

	return z.preprocess(preprocessFn, innerSchema);
}

function isValidInet(value: string): boolean {
	const ipv4 = /^(25[0-5]|2[0-4]\d|[0-1]?\d?\d)(\.(25[0-5]|2[0-4]\d|[0-1]?\d?\d)){3}$/;
	const ipv6 = /^(([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}|::1)$/;
	return ipv4.test(value) || ipv6.test(value);
}

'use client';

// Native array editor — a thin EditorProps adapter that RE-HOSTS the value-native
// `ArrayEditor` ({ value, onChange, onFinished }). Each item is checked by the
// column's element rules (`parseColumnInput`): a whole-number list takes whole
// numbers, a date list takes dates, a choice list takes its choices. The committed
// value is the parsed list (numbers stay numbers, exact decimals stay strings).
// `onFinished(undefined)` (cancel / Escape) -> `onCancel()`.

import { useCallback } from 'react';

import { parseColumnInput } from '../../cell-types/column-value';
import { fieldLabel } from '../../cell-types/field-label';
import { ArrayEditor } from '../../grid/editors/array-editor';
import type { EditorProps } from './editor-props';

export function ArrayEditorDom({ value, column, colKey, onCommit, onCancel }: EditorProps) {
	const initial = Array.isArray(value) ? value : [];
	const validate = useCallback(
		(next: unknown[]) => {
			if (!column) return null;
			const parsed = parseColumnInput(column, next);
			return parsed.ok === false ? parsed.reason : null;
		},
		[column],
	);
	return (
		<div data-slot='array-editor'>
			<ArrayEditor
				value={initial}
				onChange={() => {}}
				validate={validate}
				title={fieldLabel(column?.name ?? colKey)}
				nullable={Boolean(column?.nullable)}
				onFinished={(next) => {
					if (next === undefined) {
						onCancel();
						return;
					}
					if (next === null) {
						onCommit(null);
						return;
					}
					const parsed = column ? parseColumnInput(column, next) : null;
					onCommit(parsed?.ok ? parsed.value : next);
				}}
			/>
		</div>
	);
}

'use client';

// Native date editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) `DateEditor` verbatim. The UI (calendar, time input, footer, OVERLAY.sm
// width, own EditorFocusTrap) is reused as-is; only the contract is mapped:
//   • initial value — the raw EditorProps.value is read directly by the source.
//   • dateType — narrowed from EditorProps.cell.meta?.cellType via DATE_TIME_TYPES,
//     mirroring the original `createDateEditorFactory` precedence.
//   • commit — `onFinishedEditing(next)` -> `onCommit(next)` (the RAW serialized
//     value; the host builds the cell). `onFinishedEditing(undefined)` -> `onCancel()`.
//
// DateEditor stays in its own chunk (it pulls @internationalized/date and
// react-aria-components). The grid preloads it in idle time when its table has a
// date or time column (`useDateEditorPreload`), so it is normally ready before the
// first open. When it is not, the editor waits behind `OverlayPending`: the overlay
// stays hidden until the editor has rendered, then appears once at its final size and
// place. A placeholder cannot reserve that size, because the calendar's height depends
// on how many weeks the month spans.

import { lazy, Suspense, useState } from 'react';

import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import { fieldLabel } from '../../cell-types/field-label';
import type { DateEditorType } from '../../grid/editors/date-editor';
import { OverlayPending } from '../overlay/overlay-pending';
import type { EditorProps } from './editor-props';

type DateEditorModule = typeof import('../../grid/editors/date-editor');

let loading: Promise<DateEditorModule> | null = null;
let loaded: DateEditorModule | null = null;

/** Load the date editor's chunk once. A failed load is retried on the next call. */
export function loadDateEditor(): Promise<DateEditorModule> {
	loading ??= import('../../grid/editors/date-editor').then(
		(module) => (loaded = module),
		(error: unknown) => {
			loading = null;
			throw error;
		},
	);
	return loading;
}

const LazyDateEditor = lazy(() => loadDateEditor().then((module) => ({ default: module.DateEditor })));

export function DateEditorDom({ value, initialText, cell, column, colKey, onCommit, onCancel }: EditorProps) {
	const cellType = cell.meta?.cellType;
	const dateType: DateEditorType | undefined =
		cellType && DATE_TIME_TYPES.has(cellType) ? (cellType as DateEditorType) : undefined;
	// Chosen once per open: an editor that started behind Suspense keeps that path, so a
	// later re-render never remounts it (and never drops what the user typed).
	const [ReadyEditor] = useState(() => loaded?.DateEditor ?? null);
	const editorProps = {
		value,
		dateType,
		canClear: Boolean(column?.nullable),
		title: fieldLabel(column?.name ?? colKey),
		initialText,
		onFinishedEditing: (next?: unknown) => (next === undefined ? onCancel() : onCommit(next)),
	};

	return (
		<div data-slot='date-editor'>
			{ReadyEditor ? (
				<ReadyEditor {...editorProps} />
			) : (
				<Suspense fallback={<OverlayPending />}>
					<LazyDateEditor {...editorProps} />
				</Suspense>
			)}
		</div>
	);
}

// The SINGLE edit-intent resolver — the host's one entry point for "what happens
// when this cell is activated?". It replaces the host's brittle
// `resolveNativeEditor(cell.meta?.cellType ?? 'text')` lookup (which mis-routed
// EVERY non-text cell to TextEditor) with an AUTHORITATIVE, exhaustive mapping
// from a `typeKey` (CellType) + the cell's readonly flag to exactly one of:
//   • { mode: 'inline-toggle' } — no overlay; the host commits `!currentBool`.
//   • { mode: 'inline-edit' }   — no overlay; the host edits IN PLACE with a bare
//                                 single-line <input> (the SIMPLE text-representable
//                                 types: text-like + number-like). url/inet are NOT
//                                 here — they keep their specialised overlay editors.
//   • { mode: 'overlay', editor } — open the resolved native overlay editor.
//   • { mode: 'none' }           — not editable (readonly / non-editable type).
//
// EXHAUSTIVENESS is structural: the buckets are DRIVEN OFF the canonical
// cell-type-groups Sets (BOOLEAN_TYPES / NUMBER_TYPES / DATE_TIME_TYPES /
// GEOMETRY_TYPES / MEDIA_TYPES / isArrayCellType / NON_EDITABLE_TYPES /
// VIEWER_ONLY_TYPES), never a hand-maintained list — so adding a member to a
// group automatically routes it here. Every CellType in cell-types/types.ts lands
// in exactly one bucket; anything unrecognised falls through to the text default
// (TextEditor), matching the `unknown` cell-type contract.
//
// CONSUMER OVERRIDE: a registered `def.editorComponent` for the typeKey (looked up
// via the injected `consumer`, i.e. `registry.getEditorComponent`) WINS as the
// overlay editor for any type that opens an overlay — same precedence the glide
// path gave `def.editor`. It does NOT override inline-toggle or readonly `none`.

import type { ComponentType } from 'react';

import {
	BOOLEAN_TYPES,
	CHOICE_TYPES,
	DATE_TIME_TYPES,
	GEOMETRY_TYPES,
	MEDIA_TYPES,
	NON_EDITABLE_TYPES,
	NUMBER_TYPES,
	VIEWER_ONLY_TYPES,
	isArrayCellType,
} from '../../cell-types/cell-type-groups';
import { DOM_EDITOR_REGISTRY, type NativeEditor } from './editor-registry-dom';
import type { EditorProps } from './editor-props';

export type EditIntent =
	| { mode: 'overlay'; editor: NativeEditor }
	| { mode: 'inline-toggle' }
	| { mode: 'inline-edit' }
	| { mode: 'none' };

type EditorConsumer = (typeKey: string) => ComponentType<EditorProps> | undefined;

/** Build the overlay intent for a typeKey: consumer override wins, else the registry entry. */
function overlay(typeKey: string, consumer: EditorConsumer | undefined): EditIntent {
	const editor = (consumer?.(typeKey) as NativeEditor | undefined) ?? DOM_EDITOR_REGISTRY[typeKey];
	// No editor resolved for a type that should open one — degrade to no-edit rather
	// than portal an empty overlay. (Cannot happen for the buckets below: every one
	// has a DOM_EDITOR_REGISTRY entry.)
	return editor ? { mode: 'overlay', editor } : { mode: 'none' };
}

/**
 * Simple text-representable types (text-like + number-like) edit IN PLACE with a bare
 * <input> — no overlay. A registered consumer editor for the typeKey still WINS as an
 * overlay editor (same override precedence the overlay types give `def.editor`); only
 * the built-in path becomes inline. The host derives text-vs-number from the cell kind.
 */
function inlineOrOverride(typeKey: string, consumer: EditorConsumer | undefined): EditIntent {
	const editor = consumer?.(typeKey) as NativeEditor | undefined;
	if (editor) return { mode: 'overlay', editor };
	return { mode: 'inline-edit' };
}

/**
 * Resolve the edit intent for a cell.
 *
 * @param typeKey  - resolved CellType key (the `SheetsCellResolution.typeKey`).
 * @param opts     - `readonly` mirrors the cell's readonly flag (READONLY_CONDITIONS / draft-id / relation-not-inline).
 * @param consumer - optional per-instance editor override (`registry.getEditorComponent`).
 */
export function resolveEditIntent(
	typeKey: string,
	opts: { readonly?: boolean },
	consumer?: EditorConsumer,
): EditIntent {
	// 1) View-only kinds (full-text, raw bytes, vectors, unknown values) open a read-only
	//    viewer whether or not the cell can be written: viewing and copying is the point.
	if (VIEWER_ONLY_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 1b) Relations and files always open their editor: it shows the links or the file (view,
	//     download), decides what may change, and says why when nothing may (the cell's reason
	//     is passed along as `readOnlyReason`).
	if (typeKey === 'relation' || MEDIA_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 2) Readonly cell — never editable, regardless of type (the host reports the reason).
	if (opts.readonly) return { mode: 'none' };
	if (NON_EDITABLE_TYPES.has(typeKey)) return { mode: 'none' };

	// 3) Booleans → inline toggle (no overlay; the host commits `!currentBool`).
	if (BOOLEAN_TYPES.has(typeKey)) return { mode: 'inline-toggle' };

	// 3b) Choices (enums, allowed-values text) → the option picker overlay.
	if (CHOICE_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 4) Number-like → inline edit (simple text-representable). Overlay families below stay
	//    overlay, driven off the canonical groups so they stay exhaustive.
	if (NUMBER_TYPES.has(typeKey)) return inlineOrOverride(typeKey, consumer);
	if (DATE_TIME_TYPES.has(typeKey)) return overlay(typeKey, consumer);
	if (isArrayCellType(typeKey)) return overlay(typeKey, consumer);
	if (GEOMETRY_TYPES.has(typeKey)) return overlay(typeKey, consumer);

	// 5) Singleton overlay types (each has a DOM_EDITOR_REGISTRY entry).
	if (typeKey === 'interval') return overlay(typeKey, consumer);
	if (typeKey === 'range' || typeKey === 'composite' || typeKey === 'point') return overlay(typeKey, consumer);
	if (typeKey === 'json' || typeKey === 'jsonb') return overlay(typeKey, consumer);
	if (typeKey === 'inet') return overlay(typeKey, consumer);
	if (typeKey === 'url') return overlay(typeKey, consumer);

	// 6) Text-like default (text/textarea/email/phone/citext/bpchar/uuid/color/
	//    origin/bitstring/path + anything unrecognised) → inline edit. `color` is NOT a real
	//    backend data type — just a hex/text string — so it edits inline too (no dedicated
	//    color editor). A consumer override on a text-like typeKey still wins as an overlay
	//    editor via `inlineOrOverride`; otherwise the cell edits in place.
	return inlineOrOverride(typeKey, consumer);
}

// Public contract for a NATIVE (DOM React-portal) overlay editor. Pure types.
//
// The Phase-4 analogue of the glide `ProvideEditorComponent` payload, but value-
// native: VALUE editors (text/json/…) call `onCommit(next)` to push a value down
// the glide value-commit path (onCellEdited -> editCell), and `onCancel()` to
// dismiss with no write. SELF-COMMITTING editors (relation/image, Phase 5) use
// the optimistic `onSubmitDraftRow`/`onInvalidateData` callbacks instead.
//
// `overlay` carries the geometry the OverlayManager already computed (via the
// reused `computeOverlayGeometry`) so editors can size/scroll without re-measuring.

import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import type { FieldMetadata } from '../../cell-types/cell-type-resolver';
import type { SheetsCell } from '../../cell-model/sheets-cell';
import type { DraftSubmitResult } from '../../grid/draft-types';
import type { RelationInfo } from '../../store/relation-info-slice';
import type { SheetsRowIdentifier } from '../../row-identity';

export interface EditorProps {
	value: unknown;
	cell: SheetsCell;
	colKey: string;
	rowId: string;
	rowIdentifier?: SheetsRowIdentifier | null;
	/** The row being edited (server or draft), or null. Relation editors read the row's own key values from it. */
	row?: Readonly<Record<string, unknown>> | null;
	rowIndex: number;
	tableName?: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	/** The table-model column behind this cell, or null when the cell is not a column. */
	column?: ColumnModel | null;
	/** The table-model relation behind this cell, or null when the cell is not a relation. */
	relation?: RelationModel | null;
	/** The table model of the grid, or null while it loads. */
	table?: TableModel | null;
	/** Why the cell cannot be written, from the table model; null when it can. */
	readOnlyReason?: string | null;
	/**
	 * Type-to-edit seed: when the overlay was opened by typing a printable char on the
	 * active cell, this carries that char. Value editors (text/number) initialize their
	 * input to it in OVERWRITE mode (replacing the cell value); other editors ignore it.
	 */
	initialText?: string;
	/** Commit a value down the glide value-commit path (onCellEdited -> editCell). */
	onCommit: (next: unknown) => void;
	/**
	 * Self-committing editors (relation/image): commit a MULTI-field patch after an
	 * out-of-band server mutation, routed through the existing optimistic-update path
	 * (handleEditorSaveComplete). Value editors use {@link onCommit} instead.
	 */
	onCommitPatch?: (patch: Record<string, unknown>) => void;
	/** Dismiss the overlay with no write. */
	onCancel: () => void;
	/** Self-committing editors: submit a client-side draft row and return its creation result. */
	onSubmitDraftRow?: (draftRowId: string) => Promise<DraftSubmitResult>;
	/** Self-committing editors: invalidate cached data after an out-of-band mutation. */
	onInvalidateData?: () => void;
	/** Geometry pre-computed by the OverlayManager (reused `computeOverlayGeometry`). */
	overlay: { maxHeight: number; flipped: boolean };
}

// Native (DOM React-portal) editor registry — the Phase-4 analogue of the glide
// `grid/editor-registry.ts` `EDITOR_REGISTRY` + `createEditor`, but value-native.
//
// The OverlayManager already supplies the focus-trap, error-guard, flip geometry
// and overlay-preset width class, so a native editor is just a `ComponentType<
// EditorProps>` — no glide `ProvideEditorCallbackResult`/`disableStyling` wrapper.
// `wrapNativeEditor` is therefore a thin passthrough that only TAGS a preset width
// class (so the OverlayManager can read it) — it does NOT re-wrap the trap/guard.
//
// `resolveNativeEditor` mirrors the glide precedence: a consumer override
// (`def.editor`, looked up via the injected `consumer` fn) wins, else the
// built-in `DOM_EDITOR_REGISTRY` entry. The `consumer` lookup is injected (not the
// CellTypeRegistry directly) so this module stays decoupled from the registry
// shape; Stage 3+ wires `registry.getEditorComponent` in at the call site.
//
// PER-EDITOR COMMIT PATTERN (Phase 5 fan-out — every native re-host must follow one):
//   • VALUE editors (text/json/date/geometry/interval/inet/array/tsvector/url):
//       read the initial value from `EditorProps.value`; on save call
//       `onCommit(nextRawValue)` (the host serialises + builds the cell). Cancel ->
//       `onCancel()`. These DO NOT mutate the server.
//   • IMAGE/upload (self-committing): the editor uploads, then
//       `onCommitPatch({ [colKey]: imageData })` (single field). On a DRAFT row it
//       must first `onSubmitDraftRow(draftRowId)` to obtain a real id, and use
//       `onInvalidateData` as the post-upload `onDraftUploadComplete`.
//   • RELATION (self-committing): the editor mutates, then
//       `onCommitPatch({ [foreignKeyField]: fkValue, [relationField ?? colKey]: relationData })`
//       (MULTI field for belongsTo). FK/display fields come from EditorProps.relationInfo.
//   The host wires onCommit/onCommitPatch/onSubmitDraftRow/onInvalidateData/onCancel
//   in SheetsDomInner; an editor only PICKS the matching callback(s) for its kind.

import type { ComponentType } from 'react';

import { ArrayEditorDom } from './array-editor';
import { DateEditorDom } from './date-editor';
import type { EditorProps } from './editor-props';
import { GeometryEditorDom } from './geometry-editor';
import { ImageEditorDom } from './image-editor';
import { InetEditorDom } from './inet-editor';
import { IntervalEditorDom } from './interval-editor';
import { JsonEditorDom } from './json-editor';
import { NumberEditorDom } from './number-editor';
import { RangeEditorDom } from './range-editor';
import { RecordEditorDom } from './record-editor';
import { RelationEditorDom } from './relation-editor';
import { SelectEditorDom } from './select-editor';
import { TextEditor } from './text-editor';
import { TsvectorEditorDom } from './tsvector-editor';
import { UrlEditorDom } from './url-editor';
import { ValueViewerDom } from './value-viewer';

/**
 * A native editor that optionally advertises its overlay-preset width class and whether it
 * commits-on-click-away (Stage B): `commitsOnBlur` editors own an `onBlur → onCommit` path,
 * so the OverlayManager dismisses them with `dismissMode='commit'` (blur the input → commit)
 * instead of cancelling. Editors without it keep cancel-on-outside.
 */
export type NativeEditor = ComponentType<EditorProps> & { overlayPresetClass?: string; commitsOnBlur?: boolean };

/**
 * Tag a native editor with an overlay-preset width class so the OverlayManager can
 * size the portal. Thin passthrough — the trap/guard/geometry are the manager's job.
 */
export function wrapNativeEditor(Editor: ComponentType<EditorProps>, presetClass?: string): NativeEditor {
	if (!presetClass) return Editor;
	const wrapped = Editor as NativeEditor;
	// Tag in place — no re-render wrapper needed; the manager reads the class off
	// the resolved component. (A fresh object would break referential identity of
	// memoised editors, so we annotate the component the registry already holds.)
	wrapped.overlayPresetClass = presetClass;
	return wrapped;
}

// Built-in native editors, keyed by cell-type key. This is the CONSUMER-FACING
// overlay-editor table — the type->component map `resolveEditIntent` reads when it
// decides a type opens an overlay. It now covers EVERY type the authoritative
// edit-intent enumeration routes to an overlay (edit-intent.ts), so the host never
// falls back to TextEditor for a typed cell:
//   • number/integer/smallint/decimal/currency/percentage/rating -> NumberEditorDom.
//   • url -> UrlEditorDom (native, wired here — went through the text overlay before
//     the routing fix). NOTE: `color` is NOT here — it is not a real backend data
//     type (just a hex/text string), so it routes to the plain TextEditor via the
//     edit-intent text-like default; there is no dedicated color editor.
//   • image/file/video/audio/upload -> ImageEditorDom (the media family).
// (Booleans are NOT here — they are an inline toggle with no overlay; see edit-intent.)
export const DOM_EDITOR_REGISTRY: Record<string, NativeEditor> = {
	// Text types
	text: TextEditor,
	varchar: TextEditor,
	bitstring: TextEditor,
	path: TextEditor,
	// Choices (enums, allowed-values text)
	select: SelectEditorDom,
	'multi-select': SelectEditorDom,
	// Number types (the whole NUMBER_TYPES family, incl. rating)
	number: NumberEditorDom,
	integer: NumberEditorDom,
	smallint: NumberEditorDom,
	bigint: NumberEditorDom,
	decimal: NumberEditorDom,
	currency: NumberEditorDom,
	percentage: NumberEditorDom,
	rating: NumberEditorDom,
	// Media types (the whole MEDIA_TYPES family reuses the image editor, as in glide)
	image: ImageEditorDom,
	file: ImageEditorDom,
	video: ImageEditorDom,
	audio: ImageEditorDom,
	upload: ImageEditorDom,
	attachment: ImageEditorDom,
	// Date/time types
	date: DateEditorDom,
	datetime: DateEditorDom,
	timestamptz: DateEditorDom,
	time: DateEditorDom,
	// Geometry types
	geometry: GeometryEditorDom,
	'geometry-point': GeometryEditorDom,
	'geometry-collection': GeometryEditorDom,
	// Other complex types
	interval: IntervalEditorDom,
	range: RangeEditorDom,
	composite: RecordEditorDom,
	point: RecordEditorDom,
	// View-only kinds open a viewer that shows and copies the value
	binary: ValueViewerDom,
	vector: ValueViewerDom,
	unknown: ValueViewerDom,
	relation: RelationEditorDom,
	tsvector: TsvectorEditorDom,
	inet: InetEditorDom,
	url: UrlEditorDom,
	// Array types
	array: ArrayEditorDom,
	'text-array': ArrayEditorDom,
	'uuid-array': ArrayEditorDom,
	'number-array': ArrayEditorDom,
	'integer-array': ArrayEditorDom,
	'date-array': ArrayEditorDom,
	tags: ArrayEditorDom,
	// JSON types
	json: JsonEditorDom,
	jsonb: JsonEditorDom,
};

/**
 * Resolve the native editor for a type key. A consumer override wins (mirrors the
 * glide `def.editor` precedence), else the built-in `DOM_EDITOR_REGISTRY` entry.
 *
 * @param typeKey - resolved cell-type key (e.g. `text`, `json`).
 * @param consumer - optional per-instance override lookup (`registry.getEditorComponent`).
 */
export function resolveNativeEditor(
	typeKey: string,
	consumer?: (typeKey: string) => ComponentType<EditorProps> | undefined,
): NativeEditor | undefined {
	return consumer?.(typeKey) ?? DOM_EDITOR_REGISTRY[typeKey];
}

'use client';

// Native geometry editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) `GeometryEditor` verbatim. The UI (map/JSON tabs, randomizer, OVERLAY.xl
// width, own EditorFocusTrap, internally-lazy MapPicker) is reused as-is; the contract
// maps directly to value-native EditorProps:
//   • value (raw geojson string or object) -> read directly by the source.
//   • expectedType <- EditorProps.column.value.geometrySubtype (the declared shape).
//   • onFinishedEditing(next) -> onCommit(next) (raw geojson string; host builds the
//     cell), onFinishedEditing(undefined) -> onCancel().
// Leaflet loads on first use inside the map picker, behind a placeholder of the map's own
// height, so the editor needs no loading state of its own. Escape is handled by the
// reused editor's EditorFocusTrap -> handleCancel -> onFinishedEditing(undefined).

import { fieldLabel } from '../../cell-types/field-label';
import { GeometryEditor } from '../../grid/editors/geometry-editor';
import type { EditorProps } from './editor-props';

export function GeometryEditorDom({ value, column, colKey, fieldMeta, onCommit, onCancel }: EditorProps) {
	// The declared shape (Point, Polygon, ...) from the table model; raw metadata only without a model.
	const expectedType = column?.value.geometrySubtype || fieldMeta?.type?.subtype || undefined;
	return (
		<div data-slot='geometry-editor'>
			<GeometryEditor
				value={value}
				expectedType={expectedType}
				title={fieldLabel(column?.name ?? colKey)}
				nullable={Boolean(column?.nullable)}
				onFinishedEditing={(next) => (next === undefined ? onCancel() : onCommit(next))}
			/>
		</div>
	);
}

'use client';

// Native file editor: a thin EditorProps adapter over the self-committing
// `ImageEditor` (image, upload, upload lists, attachment links). The contract
// maps onto EditorProps:
//   • value          -> the raw row value, read directly by the editor.
//   • column / table -> the table model (kind, list or single, write rules).
//   • recordId       -> typed EditorProps.rowIdentifier; rowId keys the cell's pending state.
//   • isDraftRow     -> no server identity and a draft rowId.
//   • onSaveComplete -> onCommitPatch({ [colKey]: saveData.imageData })  (single field).
//   • onSubmitDraft  -> onSubmitDraftRow(draftRowId).
//   • onDraftUploadComplete -> onInvalidateData.
//   • onFinishedEditing(next?) -> onCancel() (a CLOSE; the editor self-commits).
// Suspense is preserved (the source editor is lazy-loaded under <Suspense fallback={null}>).

import { Suspense } from 'react';

import { ImageEditor, type ImageSaveData } from '../../grid/editors/image-editor';
import type { EditorProps } from './editor-props';

const DRAFT_PREFIX = 'draft:';

export function ImageEditorDom({
	value,
	cell,
	colKey,
	rowId,
	rowIdentifier,
	tableName,
	column,
	table,
	readOnlyReason,
	onCommitPatch,
	onCancel,
	onSubmitDraftRow,
	onInvalidateData,
}: EditorProps) {
	const isDraftRow = rowIdentifier == null && rowId.startsWith(DRAFT_PREFIX);
	// Without a column model, only the `image` cell type is image-only; every other
	// media type accepts any file. A missing cellType defaults to image-only.
	const cellType = cell.meta?.cellType;
	const acceptAnyFile = cellType != null && cellType !== 'image';

	// Self-commit: the editor uploads and writes the cell, then hands back the saved
	// value as a single-field optimistic patch.
	const handleSaveComplete = onCommitPatch
		? (saveData: ImageSaveData) => onCommitPatch({ [colKey]: saveData.imageData })
		: undefined;

	const handleSubmitDraft = isDraftRow && onSubmitDraftRow
		? () => onSubmitDraftRow(rowId)
		: undefined;

	return (
		<div data-slot="image-editor">
			<Suspense fallback={<div className='h-64 w-full min-w-[480px] animate-pulse rounded-lg bg-muted' />}>
				<ImageEditor
					value={value}
					acceptAnyFile={acceptAnyFile}
					onFinishedEditing={() => onCancel()}
					tableName={tableName}
					fieldName={colKey}
					recordId={rowIdentifier ?? null}
					rowId={rowId}
					column={column ?? null}
					table={table ?? null}
					readOnlyReason={readOnlyReason ?? null}
					onSaveComplete={handleSaveComplete}
					isDraftRow={isDraftRow}
					onSubmitDraft={handleSubmitDraft}
					onDraftUploadComplete={onInvalidateData}
				/>
			</Suspense>
		</div>
	);
}

'use client';

// Native inet editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) `InetEditor` verbatim. The UI (input, inline type badge, validation,
// footer, OVERLAY.sm width, own EditorFocusTrap + native keydown listener) is
// reused as-is; the contract maps directly to value-native EditorProps.
//
// The source reads its seed from the raw `value` and, on save, emits the raw
// trimmed value — so the raw row value flows straight through:
// `onFinishedEditing(next)` -> `onCommit(next)`, `onFinishedEditing(undefined)` ->
// `onCancel()`.

import { fieldLabel } from '../../cell-types/field-label';
import { InetEditor } from '../../grid/editors/inet-editor';
import type { EditorProps } from './editor-props';

export function InetEditorDom({ value, column, colKey, onCommit, onCancel }: EditorProps) {
	return (
		<div data-slot='inet-editor'>
			<InetEditor
				value={value}
				title={fieldLabel(column?.name ?? colKey)}
				nullable={Boolean(column?.nullable)}
				onFinishedEditing={(next) => (next === undefined ? onCancel() : onCommit(next))}
			/>
		</div>
	);
}

'use client';

// Native interval editor. With a table-model column whose write input lists the
// duration fields (years, months, days, hours, minutes, seconds), it renders the
// shared field form, so every part of the duration round-trips as an object. Without
// one (a host grid with no table model) it re-hosts the legacy `IntervalEditor`.

import { fieldLabel } from '../../cell-types/field-label';
import { IntervalEditor } from '../../grid/editors/interval-editor';
import type { EditorProps } from './editor-props';
import { RecordForm } from './record-editor';

/** A duration's parts, largest first, the way the cell reads ("1y 2mo 3d 4h 5m 6.789s"). */
const DURATION_ORDER = ['years', 'months', 'days', 'hours', 'minutes', 'seconds'] as const;

export function IntervalEditorDom({ value, column, colKey, onCommit, onCancel }: EditorProps) {
	if (column?.value.input?.fields?.length) {
		return <RecordForm column={column} value={value} title={fieldLabel(column.name ?? colKey)} onCommit={onCommit} fieldOrder={DURATION_ORDER} />;
	}
	return (
		<IntervalEditor
			value={value}
			title={fieldLabel(column?.name ?? colKey)}
			nullable={Boolean(column?.nullable)}
			onFinishedEditing={(next) => (next === undefined ? onCancel() : onCommit(next))}
		/>
	);
}

'use client';

// Native JSON editor — a thin EditorProps adapter that RE-HOSTS the value-native
// `JsonEditor` ({ value, onChange, onFinished }). The editor edits JSON text: the
// cell value (any JSON value, including a string or a number at the top level) is
// seeded as its JSON text, and an empty text clears the cell. `onFinished(next)` ->
// `onCommit(next)`, `onFinished(undefined)` -> `onCancel()`.

import { fieldLabel } from '../../cell-types/field-label';
import { JsonEditor } from '../../grid/editors/json-editor';
import type { EditorProps } from './editor-props';

/** JSON text of the stored value; '' for no value. */
function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	return JSON.stringify(value, null, 2) ?? '';
}

export function JsonEditorDom({ value, column, colKey, onCommit, onCancel }: EditorProps) {
	return (
		<JsonEditor
			value={seedText(value)}
			title={fieldLabel(column?.name ?? colKey)}
			nullable={Boolean(column?.nullable)}
			onChange={() => {}}
			onFinished={(next) => (next === undefined ? onCancel() : onCommit(next))}
		/>
	);
}

'use client';

// Native number editor — value-native single-line numeric <input> for the
// NUMBER_TYPES family (number/integer/smallint/decimal/currency/percentage/
// rating). Sibling of TextEditor: dependency-light (no glide cell types), the
// OverlayManager hosts the focus-trap + error-guard + width sizing, so this is
// just the input + a Save affordance. Glide-free by construction.
//
// VALUE editor (no server mutation): seeds from EditorProps.value, parses the
// text on commit and pushes a `number` (or `null` for empty) down the glide
// value-commit path (onCommit). Non-numeric text is rejected — Save is disabled
// and Enter is a no-op while the field cannot parse — so the last committed
// value is never clobbered by garbage.

import { useRef, useState } from 'react';

import type { ColumnModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';

import { parseColumnInput, type ColumnInputResult } from '../../cell-types/column-value';

import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

/** Seed the input text from the raw value (number or numeric string), else ''. */
function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	if (typeof value === 'number') return Number.isFinite(value) ? String(value) : '';
	return String(value);
}

/**
 * Parse the input text. With a table-model column its rules decide (whole numbers and
 * exact decimals stay exact strings); without one, '' -> null, else a finite number.
 */
function parseValue(text: string, column: ColumnModel | null | undefined): ColumnInputResult {
	if (column) return parseColumnInput(column, text, { fromText: true });
	const trimmed = text.trim();
	if (trimmed === '') return { ok: true, value: null };
	const n = Number(trimmed);
	return Number.isFinite(n) ? { ok: true, value: n } : { ok: false, reason: 'Enter a number.' };
}

export function NumberEditorDom({ value, initialText, colKey, fieldMeta, column, onCommit, onCancel }: EditorProps) {
	// Type-to-edit seed (OVERWRITE): a typed printable char replaces the cell value; the
	// parse/canSave guard below still rejects non-numeric content (e.g. a typed letter).
	const [text, setText] = useState(() => (initialText != null ? initialText : seedText(value)));
	// COMMIT-ON-BLUR GUARD (Stage B): an Escape-cancel also blurs the input as it unmounts —
	// `escapedRef` tells the blur handler to skip its commit so Escape never double-fires.
	const escapedRef = useRef(false);

	const parsed = parseValue(text, column);
	// Save is blocked while the text does not fit the column; an empty field clears it.
	const canSave = parsed.ok;

	function commit() {
		if (!parsed.ok) return;
		onCommit(parsed.value);
	}

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
		if (e.key === 'Enter') {
			e.preventDefault();
			commit();
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			escapedRef.current = true;
			onCancel();
		}
	}

	// Commit-on-click-away: commit only when focus genuinely leaves the whole overlay (the
	// focus-trap `[role="dialog"]`) — testing the element focus actually moved to (relatedTarget,
	// else post-blur document.activeElement) against the dialog root, NOT the slot. This avoids a
	// spurious commit on the open-time focus churn (focus momentarily lands on the trap container,
	// inside the dialog), while the in-overlay Save button (focus stays inside) does NOT
	// double-commit. Non-numeric garbage is still rejected (`commit()` no-ops when !canSave,
	// mirroring the Enter no-op). Skipped right after an Escape-cancel.
	function handleBlur(e: React.FocusEvent<HTMLInputElement>) {
		if (escapedRef.current) return;
		// Containment root: the focus-trap dialog in production (so the trap container counts as
		// "inside"); the editor slot when rendered bare (tests). Use whichever encloses the input.
		const root = e.currentTarget.closest('[role="dialog"]') ?? e.currentTarget.closest('[data-slot="number-editor"]');
		const landed = (e.relatedTarget as Node | null) ?? document.activeElement;
		if (root && landed && root.contains(landed)) return;
		commit();
	}

	return (
		<div
			data-slot='number-editor'
			className={cn('bg-popover flex flex-wrap items-center gap-2 rounded-lg border p-2.5 shadow-lg', OVERLAY_SM)}
		>
			<input
				aria-label={`Edit ${fieldMeta?.name ?? colKey}`}
				value={text}
				onChange={(e) => setText(e.target.value)}
				onKeyDown={handleKeyDown}
				onBlur={handleBlur}
				inputMode='decimal'
				spellCheck={false}
				className='bg-muted/40 border-border/40 min-w-0 flex-1 rounded-md border px-2.5 py-1.5 font-sans text-sm tabular-nums outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
				autoFocus
			/>
			<Button onClick={commit} disabled={!canSave} size='xs' variant='default' className='shrink-0'>
				Save
			</Button>
			{parsed.ok === false && text.trim() !== '' ? (
				<p role='alert' className='text-destructive basis-full text-xs'>
					{parsed.reason}
				</p>
			) : null}
		</div>
	);
}

// Opt into commit-on-click-away (Stage B) — see TextEditor.commitsOnBlur. The OverlayManager
// reads this to pick `dismissMode='commit'` (blur → onBlur commits) instead of cancelling.
NumberEditorDom.commitsOnBlur = true as const;

'use client';

// Range editor: a start and an end, each with a value, whether it is included, and
// whether that end is open (no limit). The bound values are checked by the column's
// own rules (`parseColumnInput`), so a whole-number range takes whole numbers and a
// date range takes dates. The API cannot tell an empty range from one with both ends
// open, so both ends open is shown as "any value".
//
// Date and date-time ranges use the browser's date and date-time fields, stacked so
// each shows its whole value; a date-time field shows the local time, as the date
// editor does. A bound the user does not change is written back exactly as stored.

import { useState } from 'react';

import type { ColumnModel } from '@constructive-io/data';

import { EditorFooter, EditorHeader, editorClear } from '../../grid/editors/editor-frame';
import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { parseColumnInput } from '../../cell-types/column-value';
import { fieldLabel } from '../../cell-types/field-label';
import { localInputToTimestamp, timestampToLocalInput } from '../../cell-types/timestamp-text';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

/** How a bound's value is entered: a date field, a date-time field, or text (numbers). */
type BoundField = 'date' | 'datetime' | 'text';

/** The bound value's type, from the range input's `start.value` field. */
function boundField(column: ColumnModel | null | undefined): BoundField {
	const start = column?.value.input?.fields?.find((field) => field.name === 'start');
	const typeName = start?.value.fields?.find((field) => field.name === 'value')?.value.typeName;
	if (typeName === 'Date') return 'date';
	if (typeName === 'Datetime') return 'datetime';
	return 'text';
}

interface BoundDraft {
	/** The value as it is written: the stored text until the user changes it. */
	text: string;
	inclusive: boolean;
	open: boolean;
}

function seedBound(bound: unknown, defaultInclusive: boolean): BoundDraft {
	if (!bound || typeof bound !== 'object') return { text: '', inclusive: defaultInclusive, open: true };
	const record = bound as { value?: unknown; inclusive?: unknown };
	if (record.value === null || record.value === undefined) return { text: '', inclusive: defaultInclusive, open: true };
	return { text: String(record.value), inclusive: record.inclusive !== false, open: false };
}

function seedRange(value: unknown): { start: BoundDraft; end: BoundDraft } {
	const record = value && typeof value === 'object' ? (value as { start?: unknown; end?: unknown }) : {};
	return { start: seedBound(record.start, true), end: seedBound(record.end, false) };
}

const INPUT =
	'bg-muted/40 border-border/40 w-full min-w-0 rounded-md border px-2.5 py-1.5 text-sm tabular-nums outline-none disabled:opacity-50 focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35';

interface BoundFieldsProps {
	id: string;
	label: string;
	field: BoundField;
	bound: BoundDraft;
	onChange: (next: BoundDraft) => void;
	autoFocus?: boolean;
}

function BoundFields({ id, label, field, bound, onChange, autoFocus }: BoundFieldsProps) {
	const common = {
		id: `${id}-value`,
		'aria-label': `${label} value`,
		disabled: bound.open,
		autoFocus: autoFocus && !bound.open,
		className: INPUT,
	};
	return (
		<fieldset className='flex min-w-0 flex-col gap-1.5'>
			<legend className='text-muted-foreground mb-1 text-xs'>{label}</legend>
			{field === 'date' ? (
				<input {...common} type='date' value={bound.text.slice(0, 10)} onChange={(e) => onChange({ ...bound, text: e.target.value })} />
			) : field === 'datetime' ? (
				<input
					{...common}
					type='datetime-local'
					step='1'
					value={timestampToLocalInput(bound.text)}
					onChange={(e) => onChange({ ...bound, text: e.target.value ? localInputToTimestamp(e.target.value) : '' })}
				/>
			) : (
				<input {...common} value={bound.text} spellCheck={false} onChange={(e) => onChange({ ...bound, text: e.target.value })} />
			)}
			<div className='flex items-center gap-3 text-xs'>
				<label className='flex items-center gap-1.5'>
					<input
						type='checkbox'
						checked={bound.inclusive}
						disabled={bound.open}
						onChange={(e) => onChange({ ...bound, inclusive: e.target.checked })}
					/>
					Included
				</label>
				<label className='flex items-center gap-1.5'>
					<input type='checkbox' checked={bound.open} onChange={(e) => onChange({ ...bound, open: e.target.checked })} />
					No limit
				</label>
			</div>
		</fieldset>
	);
}

export function RangeEditorDom({ value, column, colKey, onCommit }: EditorProps) {
	const [range, setRange] = useState(() => seedRange(value));
	const [error, setError] = useState<string | null>(null);
	const id = `range-${column?.name ?? colKey}`;
	const field = boundField(column);

	function save() {
		if (!column) return;
		const bound = (draft: BoundDraft) => (draft.open ? null : { value: draft.text, inclusive: draft.inclusive });
		const parsed = parseColumnInput(column, { start: bound(range.start), end: bound(range.end) });
		if (parsed.ok === false) {
			setError(parsed.reason);
			return;
		}
		onCommit(parsed.value);
	}

	function update(side: 'start' | 'end', next: BoundDraft) {
		setError(null);
		setRange((current) => ({ ...current, [side]: next }));
	}

	return (
		<div
			data-slot='range-editor'
			className={cn('bg-popover flex flex-col gap-3 rounded-lg border p-3 shadow-lg', OVERLAY_SM)}
			onKeyDown={(e) => {
				if (e.key === 'Enter') {
					e.preventDefault();
					save();
				}
			}}
		>
			<EditorHeader title={fieldLabel(column?.name ?? colKey)} />
			{/* Numbers fit side by side; date and date-time fields need the full width to show their value. */}
			<div className={cn('grid gap-3', field === 'text' ? 'grid-cols-2' : 'grid-cols-1')}>
				<BoundFields id={`${id}-start`} label='Start' field={field} bound={range.start} onChange={(next) => update('start', next)} autoFocus />
				<BoundFields id={`${id}-end`} label='End' field={field} bound={range.end} onChange={(next) => update('end', next)} />
			</div>
			{range.start.open && range.end.open ? (
				<p className='text-muted-foreground text-xs'>Both ends open means any value.</p>
			) : null}
			{error ? (
				<p role='alert' className='text-destructive text-xs'>
					{error}
				</p>
			) : null}
			<EditorFooter
				onSave={save}
				saveShortcut='Enter'
				saveBlockedReason={column ? null : 'This range cannot be changed here.'}
				clear={editorClear(column?.nullable, () => onCommit(null))}
			/>
		</div>
	);
}

'use client';

// Small form for values made of named fields: records (composite values), plain x/y
// points and durations. The fields come from the column's write input
// (`column.value.input.fields`), so the form matches what the API accepts. The whole
// value is checked by `parseColumnInput` before it is committed; a problem shows in
// the form and nothing is written.

import { useMemo, useState } from 'react';

import type { ColumnModel, InputFieldModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';

import { EditorFooter, EditorHeader, editorClear } from '../../grid/editors/editor-frame';
import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { parseColumnInput } from '../../cell-types/column-value';
import { fieldLabel } from '../../cell-types/field-label';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

function fieldText(value: unknown): string {
	if (value === null || value === undefined) return '';
	return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

function seedFields(fields: readonly InputFieldModel[], value: unknown): Record<string, string> {
	const record = value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
	return Object.fromEntries(fields.map((field) => [field.name, fieldText(record[field.name])]));
}

/** Plain-language hint for a field's value, from its standard GraphQL type. */
function fieldHint(field: InputFieldModel): string | undefined {
	switch (field.value.typeName) {
		case 'Int':
		case 'BigInt':
			return 'Whole number';
		case 'Float':
		case 'BigFloat':
			return 'Number';
		case 'Date':
			return 'Date, for example 2024-01-31';
		case 'Datetime':
			return 'Date and time';
		default:
			return undefined;
	}
}

interface RecordFormProps {
	column: ColumnModel;
	value: unknown;
	title: string;
	onCommit: (next: unknown) => void;
	/** Field names in the order to show them; fields not listed follow in the API's order. */
	fieldOrder?: readonly string[];
}

function orderFields(fields: readonly InputFieldModel[], order: readonly string[] | undefined): readonly InputFieldModel[] {
	if (!order) return fields;
	const rank = (name: string) => {
		const index = order.indexOf(name);
		return index === -1 ? order.length : index;
	};
	return [...fields].sort((a, b) => rank(a.name) - rank(b.name));
}

/** The form itself, for a column whose write input lists its fields. */
export function RecordForm({ column, value, title, onCommit, fieldOrder }: RecordFormProps) {
	const fields = useMemo(() => orderFields(column.value.input?.fields ?? [], fieldOrder), [column, fieldOrder]);
	const [texts, setTexts] = useState<Record<string, string>>(() => seedFields(fields, value));
	const [error, setError] = useState<string | null>(null);

	function save() {
		const draft: Record<string, unknown> = {};
		for (const field of fields) {
			const text = texts[field.name] ?? '';
			draft[field.name] = text.trim() === '' ? null : field.value.typeName === 'Boolean' ? text === 'true' : text;
		}
		const parsed = parseColumnInput(column, draft);
		if (parsed.ok === false) {
			setError(parsed.reason);
			return;
		}
		onCommit(parsed.value);
	}

	function handleKeyDown(e: React.KeyboardEvent) {
		if (e.key === 'Enter' && !e.shiftKey) {
			e.preventDefault();
			save();
		}
	}

	return (
		<div
			data-slot='record-editor'
			className={cn('bg-popover flex flex-col gap-3 rounded-lg border p-3 shadow-lg', OVERLAY_SM)}
			onKeyDown={handleKeyDown}
		>
			<EditorHeader title={title} />
			<div className='grid grid-cols-[auto_1fr] items-center gap-x-3 gap-y-2'>
				{fields.map((field, index) => {
					const id = `record-field-${column.name}-${field.name}`;
					const hint = fieldHint(field);
					return (
						<div key={field.name} className='contents'>
							<label htmlFor={id} className='text-muted-foreground text-xs'>
								{fieldLabel(field.name)}
								{field.required ? <span aria-hidden> *</span> : null}
							</label>
							{field.value.typeName === 'Boolean' ? (
								<input
									id={id}
									type='checkbox'
									checked={texts[field.name] === 'true'}
									onChange={(e) => setTexts((current) => ({ ...current, [field.name]: String(e.target.checked) }))}
									className='justify-self-start'
								/>
							) : (
								<input
									id={id}
									value={texts[field.name] ?? ''}
									placeholder={hint}
									onChange={(e) => {
										setError(null);
										setTexts((current) => ({ ...current, [field.name]: e.target.value }));
									}}
									spellCheck={false}
									autoFocus={index === 0}
									className='bg-muted/40 border-border/40 min-w-0 rounded-md border px-2.5 py-1.5 text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
								/>
							)}
						</div>
					);
				})}
			</div>
			{error ? (
				<p role='alert' className='text-destructive text-xs'>
					{error}
				</p>
			) : null}
			<EditorFooter onSave={save} saveShortcut='Enter' clear={editorClear(column.nullable, () => onCommit(null))} />
		</div>
	);
}

/** Overlay editor for record, point and duration cells. */
export function RecordEditorDom({ value, column, colKey, onCancel, onCommit }: EditorProps) {
	if (!column?.value.input?.fields?.length) {
		// Routing makes such a cell read-only; this guards a consumer that routes here anyway.
		return (
			<div data-slot='record-editor' className={cn('bg-popover flex flex-col gap-2 rounded-lg border p-3 text-sm shadow-lg', OVERLAY_SM)}>
				<p>The parts of this value are not known, so it cannot be changed here.</p>
				<div className='flex justify-end'>
					<Button size='xs' variant='outline' onClick={onCancel}>
						Close
					</Button>
				</div>
			</div>
		);
	}
	return <RecordForm column={column} value={value} title={fieldLabel(column.name ?? colKey)} onCommit={onCommit} />;
}

'use client';

// Native relation editor: maps EditorProps onto the model-driven RelationEditor.
//   • relation / table -> EditorProps.relation / .table (the table model of the grid);
//                         resolved from the grid's model when a host renders the editor
//                         without them.
//   • row              -> EditorProps.row: the editor reads this row's own key values
//                         (they need not be the primary key).
//   • rowIdentifier    -> the server row's primary key; a draft row has none.
//   • onCommitPatch    -> belongsTo only: the local key fields plus the chosen record under
//                         the relation field (a draft keeps them locally; a server row gets
//                         the saved link). Other kinds write the related tables and refetch.
//   • onCancel         -> close without writing.

import type { RelationModel, TableModel } from '@constructive-io/data';

import { EditorFocusTrap } from '../../grid/editors/editor-focus-trap';
import { OVERLAY } from '../../grid/editors/overlay-presets';
import { RelationEditor } from '../../grid/editors/relation-editor';
import { useTableModel } from '../../hooks/use-table-model';
import type { RecordValues } from '../../relations/relation-keys';
import type { EditorProps } from './editor-props';

const DRAFT_PREFIX = 'draft:';

/** The relation behind a column: the relation field itself, or a belongsTo through one of its key fields. */
function relationForColumn(table: TableModel, colKey: string): RelationModel | null {
	return (
		table.relations.find((relation) => relation.fieldName === colKey) ??
		table.relations.find((relation) => relation.kind === 'belongsTo' && relation.keys.some((pair) => pair.local === colKey)) ??
		null
	);
}

export function RelationEditorDom({
	value,
	colKey,
	rowId,
	rowIdentifier,
	row,
	tableName,
	relation: relationProp,
	table: tableProp,
	onCommitPatch,
	onInvalidateData,
	onCancel,
}: EditorProps) {
	const fallback = useTableModel(tableProp ? null : (tableName ?? null));
	const table = tableProp ?? fallback.model;
	const relation = relationProp ?? (table ? relationForColumn(table, colKey) : null);
	const isDraft = rowIdentifier == null && rowId.startsWith(DRAFT_PREFIX);
	const record = (row ?? null) as RecordValues | null;

	if (!table || !relation) {
		const message = fallback.error ? fallback.error.message : fallback.isLoading ? 'Loading…' : 'This field is not a link.';
		return (
			<div data-slot='relation-editor'>
				<EditorFocusTrap onEscape={onCancel} className={`bg-popover ${OVERLAY.md} rounded-lg border p-4 text-sm shadow-lg`}>
					<p role='status' className='text-muted-foreground'>
						{message}
					</p>
				</EditorFocusTrap>
			</div>
		);
	}

	const relationValue = record && relation.fieldName in record ? record[relation.fieldName] : colKey === relation.fieldName ? value : null;

	return (
		<div data-slot='relation-editor'>
			<RelationEditor
				relation={relation}
				table={table}
				row={record}
				rowIdentifier={rowIdentifier ?? null}
				isDraft={isDraft}
				value={relationValue}
				onCommitPatch={onCommitPatch}
				onInvalidateData={onInvalidateData}
				onClose={onCancel}
			/>
		</div>
	);
}

'use client';

// Option picker for choice columns (enums and text with an allowed-values list).
// Shows each option's label and writes its wire value. A single choice commits on
// pick; a list of choices toggles options and commits with Save. A long list gets a
// search box. A stored value that is not in the option list still shows, so the user
// can see it and remove it. Keyboard: arrows move, Enter picks, Escape cancels.

import { useEffect, useMemo, useRef, useState } from 'react';
import { Check } from 'lucide-react';

import type { ColumnOption } from '@constructive-io/data';
import { Button } from '@/components/ui/button';

import { EditorHeader, modifierKeyLabel, VALUE_REQUIRED_REASON } from '../../grid/editors/editor-frame';
import { fieldLabel } from '../../cell-types/field-label';
import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { choiceLabel } from '../../cell-types/column-value';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

/** Option lists longer than this get a search box. */
const SEARCH_THRESHOLD = 7;
/** The footer buttons sit 5px inside the editor's 10px corners, like the options. */
const FOOTER_BUTTON_RADIUS = 'rounded-[calc(var(--radius-lg)-5px)] before:rounded-[calc(var(--radius-lg)-6px)]';

function initialSelection(value: unknown, multiple: boolean): string[] {
	if (value === null || value === undefined) return [];
	const values = multiple && Array.isArray(value) ? value : [value];
	return values.filter((entry): entry is string => typeof entry === 'string');
}

export function SelectEditorDom({ value, column, colKey, cell, onCommit }: EditorProps) {
	const multiple = column ? column.value.isArray : cell.meta?.cellType === 'multi-select';
	const options = useMemo<readonly ColumnOption[]>(() => column?.value.options ?? [], [column]);
	const [selected, setSelected] = useState<string[]>(() => initialSelection(value, multiple));
	const [query, setQuery] = useState('');
	const [active, setActive] = useState(0);
	const listRef = useRef<HTMLUListElement | null>(null);

	const searchable = options.length > SEARCH_THRESHOLD;
	// Stored values that are not options stay visible so they can be seen and removed.
	const unknownSelected = selected.filter((entry) => !options.some((option) => option.value === entry));
	const visible = useMemo(() => {
		const needle = query.trim().toLowerCase();
		const all: ColumnOption[] = [...unknownSelected.map((entry) => ({ value: entry, label: entry })), ...options];
		if (!needle) return all;
		return all.filter((option) => option.label.toLowerCase().includes(needle) || option.value.toLowerCase().includes(needle));
	}, [options, query, unknownSelected]);

	// Without a search box the list itself takes focus, after the focus trap's own pass.
	useEffect(() => {
		if (!searchable) listRef.current?.focus();
	}, [searchable]);

	const label = fieldLabel(column?.name ?? colKey);
	const clampedActive = Math.min(active, Math.max(visible.length - 1, 0));

	function pick(option: ColumnOption) {
		if (!multiple) {
			onCommit(option.value);
			return;
		}
		setSelected((current) =>
			current.includes(option.value) ? current.filter((entry) => entry !== option.value) : [...current, option.value],
		);
	}

	function save() {
		onCommit(multiple ? selected : selected[0] ?? null);
	}

	function handleKeyDown(e: React.KeyboardEvent) {
		if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
			e.preventDefault();
			const step = e.key === 'ArrowDown' ? 1 : -1;
			setActive((current) => (visible.length ? (Math.min(current, visible.length - 1) + step + visible.length) % visible.length : 0));
			return;
		}
		if (e.key === 'Enter') {
			e.preventDefault();
			if (multiple && (e.metaKey || e.ctrlKey)) {
				save();
				return;
			}
			const option = visible[clampedActive];
			if (option) pick(option);
		}
		// Escape is handled by the overlay's focus trap (onCancel).
	}

	return (
		<div
			data-slot='select-editor'
			// The options, the search field and the footer buttons sit 5px inside the 10px corners
			// (1px border + 4px padding), so their radius is 10px - 5px and the curves stay parallel.
			className={cn('bg-popover flex flex-col gap-1 rounded-lg border p-1 shadow-lg', OVERLAY_SM)}
			onKeyDown={handleKeyDown}
		>
			{/* The field's name, like every value editor's title; inset to line up with the options' text. */}
			<EditorHeader title={label} className='px-2 pt-1' />
			{searchable ? (
				<input
					aria-label={`Search ${label} options`}
					value={query}
					onChange={(e) => {
						setQuery(e.target.value);
						setActive(0);
					}}
					placeholder='Search options'
					spellCheck={false}
					className='bg-muted/40 border-border/40 rounded-[calc(var(--radius-lg)-5px)] border px-2.5 py-1.5 text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
					autoFocus
				/>
			) : null}
			<ul
				ref={listRef}
				role='listbox'
				aria-label={`${label} options`}
				aria-multiselectable={multiple || undefined}
				aria-activedescendant={visible[clampedActive] ? `select-option-${clampedActive}` : undefined}
				tabIndex={searchable ? -1 : 0}
				className='max-h-64 overflow-y-auto outline-none'
			>
				{visible.length === 0 ? (
					<li className='text-muted-foreground px-2 py-1.5 text-sm'>No matching options</li>
				) : (
					visible.map((option, index) => {
						const isSelected = selected.includes(option.value);
						const isUnknown = !options.some((entry) => entry.value === option.value);
						return (
							<li
								key={option.value}
								id={`select-option-${index}`}
								role='option'
								aria-selected={isSelected}
								onMouseEnter={() => setActive(index)}
								onClick={() => pick(option)}
								className={cn(
									'flex cursor-pointer items-center justify-between gap-2 rounded-[calc(var(--radius-lg)-5px)] px-2 py-1.5 text-sm',
									index === clampedActive && 'bg-muted',
								)}
							>
								{/* The chip swaps surfaces with the highlighted row (popover on muted), so its shape stays visible. */}
								<span
									className={cn(
										'text-muted-foreground truncate rounded-md px-2 py-0.5 text-xs font-medium',
										index === clampedActive ? 'bg-popover' : 'bg-muted',
									)}
									title={option.label}
								>
									{isUnknown ? choiceLabel(column, option.value) : option.label}
								</span>
								{isUnknown ? <span className='text-muted-foreground text-xs'>Not in the list</span> : null}
								{isSelected ? <Check aria-hidden className='size-4 shrink-0' /> : null}
							</li>
						);
					})
				)}
			</ul>
			{multiple || (column?.nullable && selected.length > 0) ? (
				<div className='-mx-1 flex items-center justify-end gap-2 border-t px-1 pt-1'>
					{/* The value editors' footer: Clear when the column takes no value (a list of choices
					    shows it disabled, with the reason, when it must have one), then Save. */}
					{column?.nullable ? (
						<Button size='xs' variant='ghost' className={FOOTER_BUTTON_RADIUS} onClick={() => onCommit(null)} title='Remove the value'>
							Clear
						</Button>
					) : (
						<Button size='xs' variant='ghost' className={FOOTER_BUTTON_RADIUS} disabled focusableWhenDisabled title={VALUE_REQUIRED_REASON}>
							Clear
						</Button>
					)}
					{multiple ? (
						<Button size='xs' className={FOOTER_BUTTON_RADIUS} onClick={save} title={`Save (${modifierKeyLabel()} Enter)`}>
							Save
						</Button>
					) : null}
				</div>
			) : null}
		</div>
	);
}

'use client';

// Native text editor — value-native single-line <input> for text/varchar cells.
// The Phase-4 analogue of glide's built-in text overlay (text/varchar return
// `undefined` from the glide factory to use it). Dependency-light: no UI-package
// Button, no glide types. Commit/cancel flow through EditorProps; the
// OverlayManager already hosts the focus-trap + error-guard + width sizing, so
// this is just the input + a Save affordance.

import { useRef, useState } from 'react';

import { Button } from '@/components/ui/button';

import { OVERLAY_SM } from '../../grid/editors/overlay-presets';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

export function TextEditor({ value, initialText, colKey, fieldMeta, onCommit, onCancel }: EditorProps) {
	// Type-to-edit seed (OVERWRITE): when opened by typing a printable char, start from that
	// char instead of the cell value; otherwise seed from the cell value as usual.
	const [text, setText] = useState(() => (initialText != null ? initialText : String(value ?? '')));
	// COMMIT-ON-BLUR GUARD (Stage B): Escape cancels WITHOUT committing, but the cancel also
	// blurs the input as it unmounts — `escapedRef` tells the blur handler to skip its commit
	// so an Escape never double-fires as a commit.
	const escapedRef = useRef(false);

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
		if (e.key === 'Enter') {
			e.preventDefault();
			onCommit(text);
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			escapedRef.current = true;
			onCancel();
		}
	}

	// Commit-on-click-away: commit the current value only when focus genuinely leaves the whole
	// overlay (the focus-trap `[role="dialog"]`). We test the element focus actually MOVED TO —
	// `e.relatedTarget` when set, else the post-blur `document.activeElement` — against the
	// dialog root, NOT the text-editor slot. This is what distinguishes a real click-away (focus
	// lands on body / an outside element) from the open-time focus churn the EditorFocusTrap
	// causes (focus momentarily lands on the trap CONTAINER, which is inside the dialog but
	// outside the slot — committing on that would fire a spurious commit on mount). Clicking the
	// in-overlay Save button keeps focus inside the dialog, so it does NOT double-commit either.
	// Skipped right after an Escape-cancel (escapedRef).
	function handleBlur(e: React.FocusEvent<HTMLInputElement>) {
		if (escapedRef.current) return;
		// Containment root: the focus-trap dialog in production (so the trap container counts as
		// "inside"); the editor slot when rendered bare (tests). Use whichever encloses the input.
		const root = e.currentTarget.closest('[role="dialog"]') ?? e.currentTarget.closest('[data-slot="text-editor"]');
		const landed = (e.relatedTarget as Node | null) ?? document.activeElement;
		if (root && landed && root.contains(landed)) return;
		onCommit(text);
	}

	return (
		<div data-slot='text-editor' className={cn('bg-popover flex items-center gap-2 rounded-lg border p-2.5 shadow-lg', OVERLAY_SM)}>
			<input
				aria-label={`Edit ${fieldMeta?.name ?? colKey}`}
				value={text}
				onChange={(e) => setText(e.target.value)}
				onKeyDown={handleKeyDown}
				onBlur={handleBlur}
				spellCheck={false}
				className='bg-muted/40 border-border/40 min-w-0 flex-1 rounded-md border px-2.5 py-1.5 font-sans text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
				autoFocus
			/>
			<Button onClick={() => onCommit(text)} size='xs' variant='default' className='shrink-0'>
				Save
			</Button>
		</div>
	);
}

// Opt this editor into commit-on-click-away (Stage B): the OverlayManager reads this off the
// resolved component to pick `dismissMode='commit'` (blur the input → onBlur commits) instead
// of cancelling. Only editors with a real `onBlur → onCommit` set this.
TextEditor.commitsOnBlur = true as const;

'use client';

