'use client';

// Native URL editor — a thin EditorProps adapter that RE-HOSTS the (now value-
// native) `UrlEditor` verbatim. Its UI (input + preview + test-link + OVERLAY.md
// width + own EditorFocusTrap) is reused as-is; the contract maps directly to
// value-native EditorProps.
//
// VALUE editor (no server mutation): the editor reads the raw row value and emits
// the formatted URL string back, so the value flows straight through:
// `onFinishedEditing(next)` -> `onCommit(next)`, `onFinishedEditing(undefined)`
// (cancel / Escape) -> `onCancel()`. Parity note: glide url cells fell back to the
// built-in text overlay, so this is a ported, consumer-overridable editor (not
// registry-wired by default).

import { fieldLabel } from '../../cell-types/field-label';
import { UrlEditor } from '../../grid/editors/url-editor';
import type { EditorProps } from './editor-props';

export function UrlEditorDom({ value, column, colKey, onCommit, onCancel }: EditorProps) {
	return (
		<div data-slot='url-editor'>
			<UrlEditor
				value={value}
				title={fieldLabel(column?.name ?? colKey)}
				nullable={Boolean(column?.nullable)}
				onFinishedEditing={(next) => (next === undefined ? onCancel() : onCommit(next))}
			/>
		</div>
	);
}

'use client';

// Preload the built-in date editor's chunk when the grid's table has a date or time
// column, so the first open shows the editor at once instead of waiting for its code.
// It runs once, in idle time after the grid has rows: a table without such a column,
// or a host that brings its own date editor, loads nothing.

import type { ComponentType } from 'react';
import { useEffect } from 'react';

import type { TableModel } from '@constructive-io/data';

import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import { cellTypeForColumn } from '../../cell-types/column-routing';
import type { EditorProps } from './editor-props';
import { loadDateEditor } from './date-editor';

export interface DateEditorPreloadInput {
	table: TableModel | null;
	/** Host cell-type overrides (`SheetsConfig.fieldTypeOverrides`), keyed `Table.field`. */
	typeOverrides?: Readonly<Record<string, string>>;
	/** The grid has rendered rows; nothing is loaded before the first paint of data. */
	hasRows: boolean;
	/** The host's editor for a cell type, when it replaces the built-in one. */
	getEditorComponent?: (typeKey: string) => ComponentType<EditorProps> | undefined;
	/** Injected in tests; defaults to the date editor's own loader. */
	load?: () => Promise<unknown>;
}

/** True when a column of the table opens the built-in date editor. */
export function tableUsesDateEditor(
	table: TableModel | null,
	typeOverrides?: Readonly<Record<string, string>>,
	getEditorComponent?: DateEditorPreloadInput['getEditorComponent'],
): boolean {
	if (!table) return false;
	return table.columns.some((column) => {
		const cellType = typeOverrides?.[`${table.name}.${column.name}`] || cellTypeForColumn(column);
		return DATE_TIME_TYPES.has(cellType) && !getEditorComponent?.(cellType);
	});
}

/** Run `task` when the browser is idle (or soon, where idle callbacks are missing). Returns a cancel. */
function whenIdle(task: () => void): () => void {
	if (typeof window.requestIdleCallback === 'function') {
		const handle = window.requestIdleCallback(task, { timeout: 2000 });
		return () => window.cancelIdleCallback(handle);
	}
	const handle = window.setTimeout(task, 200);
	return () => window.clearTimeout(handle);
}

export function useDateEditorPreload({
	table,
	typeOverrides,
	hasRows,
	getEditorComponent,
	load = loadDateEditor,
}: DateEditorPreloadInput): void {
	const needed = hasRows && tableUsesDateEditor(table, typeOverrides, getEditorComponent);
	useEffect(() => {
		if (!needed) return;
		// A failed preload is not an error: the editor loads again when it is opened.
		return whenIdle(() => void load().catch(() => {}));
	}, [needed, load]);
}

'use client';

// Read-only viewer for values the grid shows but does not edit: raw bytes, number
// vectors and values of a kind the grid does not know. It shows the whole value and
// a short summary (size or length), says why the value cannot be changed here, and
// copies the value as text.

import { useState } from 'react';

import { Button } from '@/components/ui/button';

import { OVERLAY_MD } from '../../grid/editors/overlay-presets';
import { formatColumnValue, VIEW_ONLY_REASON } from '../../cell-types/column-value';
import { fieldLabel } from '../../cell-types/field-label';
import { cn } from '../../utils/cn';
import type { EditorProps } from './editor-props';

function summary(cellType: string | undefined, value: unknown): string | null {
	if (value === null || value === undefined) return 'No value';
	if (cellType === 'binary' && typeof value === 'string') {
		const clean = value.replace(/\s/g, '');
		const padding = clean.endsWith('==') ? 2 : clean.endsWith('=') ? 1 : 0;
		const size = Math.max(0, Math.floor((clean.length * 3) / 4) - padding);
		return `${size} ${size === 1 ? 'byte' : 'bytes'}, shown as base64`;
	}
	if (Array.isArray(value)) return `${value.length} ${value.length === 1 ? 'item' : 'items'}`;
	return null;
}

export function ValueViewerDom({ value, column, colKey, cell, readOnlyReason, onCancel }: EditorProps) {
	const [copied, setCopied] = useState(false);
	const text = formatColumnValue(column, value);
	const detail = summary(cell.meta?.cellType, value);

	function copy() {
		const clipboard = typeof navigator !== 'undefined' ? navigator.clipboard : undefined;
		if (!clipboard) return;
		void clipboard.writeText(text).then(() => setCopied(true)).catch(() => setCopied(false));
	}

	return (
		<div data-slot='value-viewer' className={cn('bg-popover flex flex-col gap-2 rounded-lg border p-3 shadow-lg', OVERLAY_MD)}>
			<div className='flex items-baseline justify-between gap-2'>
				<h3 className='text-sm font-medium'>{fieldLabel(column?.name ?? colKey)}</h3>
				{detail ? <span className='text-muted-foreground text-xs'>{detail}</span> : null}
			</div>
			<pre className='bg-muted/40 max-h-64 overflow-auto rounded-md p-2 text-xs break-all whitespace-pre-wrap'>{text}</pre>
			<p className='text-muted-foreground text-xs'>{readOnlyReason ?? VIEW_ONLY_REASON}</p>
			<div className='flex justify-end gap-2 border-t pt-2'>
				<Button size='xs' variant='outline' onClick={copy} disabled={!text} autoFocus>
					{copied ? 'Copied' : 'Copy'}
				</Button>
				<Button size='xs' variant='ghost' onClick={onCancel}>
					Close
				</Button>
			</div>
		</div>
	);
}

'use client';

// Inline (in-cell) editor — a bare input rendered DIRECTLY inside the cell for the
// SIMPLE text-representable types (text-like + number-like). The non-overlay
// counterpart of the portal editors: there is no card, no Save button and no React
// portal — the input fills the cell (`absolute inset-0`) and overlays the cell view
// while editing. Routed here by `resolveEditIntent` → `{ mode: 'inline-edit' }`.
//
// VALUE RULES: with a table-model column, the text is parsed by the column's rules
// (`parseColumnInput`): whole numbers and exact decimals stay exact strings, a length
// limit is enforced, and a value that does not fit shows its reason under the cell and
// is never committed. Without a column (a host grid without a model) a numeric cell
// parses to a finite number and anything else commits as text.
//
// MULTI-LINE TEXT: a value with line breaks edits in a textarea anchored on the cell
// and taller than it; Shift+Enter adds a line break. A single-line <input> would drop
// the breaks. The textarea and the "does not fit" notice are portalled (fixed, at the
// cell's rect) because the next row paints over anything that overflows the cell.
//
// COMMIT MODEL (mirrors the overlay text/number editors, minus the chrome):
//   • Enter / blur (click-away) → commit. Escape → cancel. A value that does not fit
//     blocks Enter (stay editing, reason shown) and is discarded on blur, with the
//     reason reported through `onReject` — never written as garbage.
//   • `doneRef` makes commit/cancel idempotent: the explicit path returns focus to the
//     grid root (so keyboard nav resumes), and the blur THAT focus shift triggers is
//     short-circuited so it never double-fires.
//   • Pointer events stopPropagation so selecting text with the mouse does not trip the
//     cell's click-to-activate / range-drag handlers on the host wrapper.

import { useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import type { ColumnModel } from '@constructive-io/data';

import { parseColumnInput, type ColumnInputResult } from '../cell-types/column-value';
import { cn } from '../utils/cn';

interface InlineCellEditorProps {
	/** Accessible name derived from the owning column. */
	ariaLabel: string;
	/** The cell's committed value — seeds the input unless `initialText` overrides (type-to-edit). */
	value: unknown;
	/** Type-to-edit seed (OVERWRITE): a printable char that opened the editor replaces the value. */
	initialText?: string;
	/** Number-like cell — right-align like the view (and, without a column, parse to a number). */
	numeric?: boolean;
	/** The table-model column: its rules parse and check the text. */
	column?: ColumnModel | null;
	/** The cell is in a record not created yet: emptying a required text field is allowed there. */
	creating?: boolean;
	/** Commit the next value; `move` is where the cursor goes next (Enter, Tab, Shift+Tab). */
	onCommit: (next: unknown, move?: InlineEditMove) => void;
	/** Discard — Escape, or a value that does not fit on blur. */
	onCancel: () => void;
	/** A value that did not fit was discarded on blur; `reason` says why. */
	onReject?: (reason: string) => void;
}

/** Seed the input text from the raw value (anything stringifiable), else ''. */
function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	if (typeof value === 'object') return JSON.stringify(value);
	return String(value);
}

/** Parse without a column: '' → null (a valid clear); else a finite number, or a refusal. */
function parseLegacy(text: string, numeric: boolean): ColumnInputResult {
	if (!numeric) return { ok: true, value: text };
	const trimmed = text.trim();
	if (trimmed === '') return { ok: true, value: null };
	const n = Number(trimmed);
	return Number.isFinite(n) ? { ok: true, value: n } : { ok: false, reason: 'Enter a number.' };
}

/** Where the cursor goes after a commit, as in a spreadsheet. */
export type InlineEditMove = 'down' | 'up' | 'right' | 'left';

export function InlineCellEditor({ ariaLabel, value, initialText, numeric, column, creating = false, onCommit, onCancel, onReject }: InlineCellEditorProps) {
	const [text, setText] = useState(() => (initialText != null ? initialText : seedText(value)));
	const [multiline, setMultiline] = useState(() => /[\r\n]/.test(initialText ?? seedText(value)));
	const [error, setError] = useState<string | null>(null);
	const fieldRef = useRef<HTMLInputElement | HTMLTextAreaElement | null>(null);
	// The grid root (role=grid, tabIndex=0) — focus returns here on commit/cancel so arrow-key
	// nav resumes (the input unmounts and would otherwise drop focus to <body>). Captured once.
	const gridRef = useRef<HTMLElement | null>(null);
	// Guards commit/cancel idempotency: set before the explicit focus-return so the resulting
	// blur skips its commit-on-blur (no double commit, no commit-after-Escape).
	const doneRef = useRef(false);
	// Set when Shift+Enter switches to the textarea, so the remount keeps the caret at the end.
	const switchedRef = useRef(false);
	// Fills the cell; its rect anchors the portalled textarea and notice.
	const anchorRef = useRef<HTMLSpanElement | null>(null);
	const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);
	const needsAnchor = multiline || error !== null;

	useLayoutEffect(() => {
		gridRef.current = (anchorRef.current?.closest('[role="grid"]') as HTMLElement | null) ?? null;
		if (!needsAnchor) return;
		// The portalled field and notice sit at a fixed place on screen, so they measure the cell
		// again whenever anything scrolls (the grid, the page) or the window resizes.
		const measure = () => {
			const next = anchorRef.current?.getBoundingClientRect() ?? null;
			// Keep the same rect while the cell has not moved, so a scroll elsewhere renders nothing.
			setAnchorRect((prev) =>
				prev && next && prev.left === next.left && prev.top === next.top && prev.width === next.width && prev.height === next.height
					? prev
					: next,
			);
		};
		measure();
		window.addEventListener('scroll', measure, true);
		window.addEventListener('resize', measure);
		return () => {
			window.removeEventListener('scroll', measure, true);
			window.removeEventListener('resize', measure);
		};
	}, [needsAnchor]);

	const fieldMounted = !multiline || anchorRect !== null;
	useLayoutEffect(() => {
		const el = fieldRef.current;
		if (!el || !fieldMounted) return;
		el.focus();
		// Seeded from the cell value (Enter / F2 / double-click) → select all so the first keystroke
		// replaces. A type-to-edit seed already IS the replacement, so leave the caret at the end.
		if (initialText == null && !switchedRef.current) el.select();
		else el.setSelectionRange(el.value.length, el.value.length);
	}, [initialText, multiline, fieldMounted]);

	const parse = (next: string): ColumnInputResult =>
		column ? parseColumnInput(column, next, { fromText: true, creating }) : parseLegacy(next, Boolean(numeric));

	function finish(commit: boolean, move?: InlineEditMove) {
		if (doneRef.current) return;
		doneRef.current = true;
		// Return focus to the grid BEFORE the input unmounts; doneRef makes the blur a no-op.
		gridRef.current?.focus();
		if (!commit) {
			onCancel();
			return;
		}
		const parsed = parse(text);
		if (parsed.ok === false) {
			onCancel(); // does not fit on commit-by-blur → discard rather than clobber
			onReject?.(parsed.reason);
			return;
		}
		onCommit(parsed.value, move);
	}

	/** Commit and move, or stay editing and say why the value does not fit. */
	function commitAndMove(move: InlineEditMove) {
		const parsed = parse(text);
		if (parsed.ok === false) {
			setError(parsed.reason);
			return;
		}
		finish(true, move);
	}

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) {
		if (e.key === 'Enter' && e.shiftKey && !numeric) {
			if (!multiline) {
				e.preventDefault();
				const el = e.currentTarget;
				const start = el.selectionStart ?? text.length;
				const end = el.selectionEnd ?? text.length;
				switchedRef.current = true;
				setText(`${text.slice(0, start)}\n${text.slice(end)}`);
				setMultiline(true);
			}
			return; // a textarea inserts the line break itself
		}
		// Enter saves and moves down (Shift+Enter up, in a number), Tab right and Shift+Tab left.
		if (e.key === 'Enter') {
			e.preventDefault();
			commitAndMove(e.shiftKey ? 'up' : 'down');
			return;
		}
		if (e.key === 'Tab') {
			e.preventDefault();
			commitAndMove(e.shiftKey ? 'left' : 'right');
			return;
		}
		if (e.key === 'Escape') {
			e.preventDefault();
			finish(false);
		}
		// Other keys (incl. arrows / Home / End) act on the input text. They bubble to the grid
		// root, which ignores keys while an editor is active, so they never move the grid cursor.
	}

	const shared = {
		'aria-label': ariaLabel,
		'aria-invalid': error ? true : undefined,
		value: text,
		onKeyDown: handleKeyDown,
		onBlur: () => finish(true),
		onPointerDown: (e: React.PointerEvent) => e.stopPropagation(),
		onClick: (e: React.MouseEvent) => e.stopPropagation(),
		onDoubleClick: (e: React.MouseEvent) => e.stopPropagation(),
		spellCheck: false,
	};

	const portalHost = typeof document !== 'undefined' ? (document.getElementById('portal-root') ?? document.body) : null;
	const floating = (rect: DOMRect, top: number): React.CSSProperties => ({
		position: 'fixed',
		left: rect.left,
		top,
		zIndex: 'var(--z-layer-floating)',
		pointerEvents: 'auto',
	});

	return (
		<>
			<span ref={anchorRef} aria-hidden className='pointer-events-none absolute inset-0' />
			{multiline ? (
				anchorRect && portalHost
					? createPortal(
						<textarea
							{...shared}
							data-slot='inline-cell-editor'
							ref={(node) => {
								fieldRef.current = node;
							}}
							rows={4}
							onChange={(e) => {
								setError(null);
								setText(e.target.value);
							}}
							style={{ ...floating(anchorRect, anchorRect.top), width: Math.max(anchorRect.width, 280) }}
							className='bg-background ring-primary min-h-[6rem] resize-y rounded-sm px-3 py-2 font-sans text-sm shadow-lg outline-none ring-2 ring-inset'
						/>,
						portalHost,
					)
					: null
			) : (
				<input
					{...shared}
					data-slot='inline-cell-editor'
					ref={(node) => {
						fieldRef.current = node;
					}}
					onChange={(e) => {
						setError(null);
						setText(e.target.value);
					}}
					inputMode={numeric ? 'decimal' : undefined}
					className={cn(
						'bg-background ring-primary absolute inset-0 h-full w-full px-3 font-sans text-sm outline-none ring-2 ring-inset',
						numeric && 'text-right tabular-nums',
						error && 'ring-destructive',
					)}
				/>
			)}
			{error && anchorRect && portalHost
				? createPortal(
					<p
						role='alert'
						style={floating(anchorRect, anchorRect.bottom + 4)}
						className='bg-popover text-destructive max-w-xs rounded-md border px-2 py-1 text-xs shadow-md'
					>
						{error}
					</p>,
					portalHost,
				)
				: null}
		</>
	);
}

'use client';

// Native (DOM React-portal) overlay container — the Phase-4 analogue of glide's
// `#portal` fixed host, but it anchors off the cell DOM node's measured rect and
// portals straight into `document.body` (viewport coords, matching the
// `window.innerHeight` assumption in `computeOverlayGeometry`). It REUSES the pure
// flip math + `EditorFocusTrap` + `EditorErrorGuard` + overlay-preset width class.
// It NEVER mutates `.gdg-clip-region` — that DOM coupling stays in the canvas
// `OverlayViewportGuard` so the glide path is untouched.

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import { computeOverlayGeometry, OverlayMeasureContext } from '../../grid/editors/overlay-viewport-guard';
import { EditorFocusTrap } from '../../grid/editors/editor-focus-trap';
import { EditorErrorGuard } from '../../grid/feedback/editor-error-boundary';
import { cn } from '../../utils/cn';
import { OVERLAY_PENDING_ATTRIBUTE } from './overlay-pending';

const MARGIN_PX = 12;
const MIN_BELOW_PX = 320;

// Opening and closing a cell editor is one of the most frequent keyboard actions in
// the grid (Enter, F2, type-to-edit, Escape), so the overlay appears and disappears at
// once, with no scale or fade (Craft: Hover Restraint). It stays hidden only until its
// measured, viewport-clamped position is applied, so it never flashes at a wrong spot.

// Nested floating layers an editor MIGHT portal outside the overlay (Base UI / Radix
// / Floating UI popover, select, menu, dialog, tooltip). A pointerdown inside one of
// these must NOT dismiss the overlay. The current editors render their pickers inline
// inside the overlay, so this is a forward-looking safety net.
const FLOATING_LAYER_SELECTOR =
	'[role="listbox"],[role="menu"],[role="dialog"],[role="tooltip"],[data-floating-ui-portal],[data-base-ui-positioner],[data-radix-popper-content-wrapper]';

interface OverlayManagerProps {
	anchorRect: DOMRect | null;
	open: boolean;
	presetClass?: string;
	onCancel: () => void;
	/**
	 * Outside-pointerdown policy (Stage B). `'cancel'` (default) dismisses with no write
	 * — for editors that DON'T commit-on-blur (relation/date/json/url/inet/…). `'commit'`
	 * — for the commit-on-blur value editors (text/number) — instead BLURS the focused
	 * element inside the overlay so its `onBlur → onCommit` fires (commit-on-click-away),
	 * rather than cancelling. The blur path then commits AND closes; the manager does NOT
	 * also call onCancel, so there is exactly one dismiss per click-away.
	 */
	dismissMode?: 'cancel' | 'commit';
	children: React.ReactNode;
}

export function OverlayManager({ anchorRect, open, presetClass, onCancel, dismissMode = 'cancel', children }: OverlayManagerProps): React.ReactNode {
	const containerRef = useRef<HTMLDivElement | null>(null);
	// Measured, viewport-clamped position (both axes). Null until the overlay has been
	// measured once, so first paint stays hidden rather than flashing at an unclamped
	// spot. Covers the FLIP (no room below -> open above) AND the horizontal shift (an
	// anchor near the right edge -> slide left so the overlay stays on-screen instead of
	// overflowing off the viewport, e.g. the last column's editor).
	const [pos, setPos] = useState<{ left: number; top: number } | null>(null);

	const targetY = anchorRect?.top;
	const targetH = anchorRect?.height;
	const vh = typeof window !== 'undefined' ? window.innerHeight : 800;
	const { shouldFlip, maxHeight } = computeOverlayGeometry(vh, targetY, targetH, MARGIN_PX, MIN_BELOW_PX);

	// Geometry an editor needs to self-bound its internal scroll areas (the canvas path
	// supplied this via OverlayViewportGuard; the DOM host must too). WITHOUT it, editors
	// that read OverlayMeasureContext (relation/image/geometry) see the default maxHeight:0,
	// skip their scroll-budget effect, and render UNBOUNDED lists — so a relation editor's
	// infinite "related records" sentinel stays permanently in view and pages continuously.
	const overlayMeasure = useMemo(() => ({ maxHeight, shouldFlip }), [maxHeight, shouldFlip]);

	// Measure the rendered overlay, then position it: vertically below the anchor (or
	// flipped above when there's no room), horizontally left-aligned to the anchor (or
	// shifted left to stay on-screen), clamped into the viewport on BOTH axes. DOM-read
	// only — mirrors the canvas guard's layout-effect measure; no hasMounted flag.
	useLayoutEffect(() => {
		if (!open || !anchorRect) {
			setPos(null);
			return;
		}
		const el = containerRef.current;
		if (!el) return;
		const place = () => {
			// An editor still loading its code stays hidden; it is placed (and shown) once it
			// has rendered, when the resize observer reports its real size.
			if (el.querySelector(`[${OVERLAY_PENDING_ATTRIBUTE}]`)) {
				setPos(null);
				return;
			}
			const width = el.offsetWidth;
			const height = el.offsetHeight;
			const vw = window.innerWidth;
			const vhNow = window.innerHeight;

			let left = anchorRect.left;
			left = Math.max(MARGIN_PX, Math.min(left, vw - MARGIN_PX - width));
			if (!Number.isFinite(left)) left = MARGIN_PX;

			let top = shouldFlip ? anchorRect.top - height : anchorRect.bottom;
			top = Math.max(MARGIN_PX, Math.min(top, vhNow - MARGIN_PX - height));
			if (!Number.isFinite(top)) top = MARGIN_PX;

			setPos((prev) => (prev && prev.left === left && prev.top === top ? prev : { left, top }));
		};
		place();
		// Lazy editors (date) and state changes (image) resize after opening; keep the
		// overlay clamped on-screen as its content settles.
		if (typeof ResizeObserver === 'undefined') return;
		const observer = new ResizeObserver(place);
		observer.observe(el);
		return () => observer.disconnect();
	}, [open, shouldFlip, anchorRect, maxHeight]);

	// Dismiss on a pointerdown OUTSIDE the overlay — standard popover behaviour. The
	// overlay was previously only closable via Esc / commit / scroll, so a click in the
	// grid or page left it stuck open. Attached in an effect (after commit) so the
	// activating double-click that OPENED the overlay has fully settled and cannot
	// self-dismiss; capture phase so an inner editor that stops propagation can't
	// suppress it. Clicks inside the overlay (or a nested floating layer it portals)
	// are ignored.
	useEffect(() => {
		if (!open) return;
		const onPointerDown = (e: PointerEvent) => {
			const el = containerRef.current;
			const target = e.target as Node | null;
			if (!el || (target && el.contains(target))) return;
			if (target instanceof Element && target.closest(FLOATING_LAYER_SELECTOR)) return;
			// COMMIT-ON-CLICK-AWAY (Stage B): for commit-on-blur editors, move DOM focus out of
			// the overlay so the focused input's `onBlur → onCommit` fires (commit, then close).
			// We DON'T also call onCancel — the blur path closes the overlay, so this is exactly
			// one dismiss. A bare outside element may not be focusable (so a natural focus shift
			// wouldn't fire), hence we blur explicitly. Falls back to onCancel when nothing in the
			// overlay is focused. `'cancel'` editors discard as before.
			if (dismissMode === 'commit') {
				const focused = document.activeElement;
				if (focused instanceof HTMLElement && el.contains(focused)) {
					focused.blur();
					return;
				}
			}
			onCancel();
		};
		document.addEventListener('pointerdown', onPointerDown, true);
		return () => document.removeEventListener('pointerdown', onPointerDown, true);
	}, [open, onCancel, dismissMode]);

	if (!open || !anchorRect || typeof document === 'undefined') return null;

	// Reveal only once the measured, viewport-clamped position is applied, so the
	// entrance never fights the layout-effect measure.
	const positioned = pos !== null;
	const style: React.CSSProperties = {
		position: 'fixed',
		// Pre-measure default = the ANCHOR position (below, or above when flipping), NOT a
		// screen corner. So an overlay that fits (the common case) renders at its FINAL spot
		// with zero left/top change once measured — no travel. It stays transparent until measured
		// and left/top are never transitioned, so the rare off-screen clamp is instant and the
		// overlay is never seen sliding to the anchor (the correction happens pre-reveal).
		left: pos ? pos.left : anchorRect.left,
		top: pos ? pos.top : shouldFlip ? anchorRect.top : anchorRect.bottom,
		// The width is the editor's own (max-content, bounded by its preset and the viewport),
		// never the room left of the right edge. A fixed box with no width shrinks to the
		// space between `left` and the viewport edge, so near the right edge each clamp moved
		// `left` 1px, the box grew 1px, the resize observer clamped again, and the editor
		// visibly grew leftwards one pixel per frame until it reached its natural width.
		width: 'max-content',
		maxWidth: `calc(100vw - ${MARGIN_PX * 2}px)`,
		maxHeight,
		// Transparent until measured to avoid a 1-frame flash at an unclamped position. Not
		// `visibility: hidden`: the editor's focus trap focuses its input on mount, before the
		// measure, and a hidden element cannot take focus, so the keyboard would stay on the grid.
		opacity: positioned ? undefined : 0,
		// Join the shared design-system overlay layer instead of an
		// arbitrary z, so the editor and any popover/tooltip it opens (e.g. the relation
		// "Record Data" popover, which portals into #portal-root) stack coherently.
		zIndex: 'var(--z-layer-floating)',
	};

	// Portal into the app's shared floating-overlay host (#portal-root) so the editor and
	// nested UI popovers live in the SAME stacking context (siblings) — fixing the
	// host-dependent z-index race where the editor could paint OVER a popover opened from
	// within it. Fall back to <body> when no portal root is mounted (e.g. tests). The host
	// has pointer-events:none, so the overlay opts back in with pointer-events-auto.
	const portalHost = document.getElementById('portal-root') ?? document.body;

	return createPortal(
		<div
			ref={containerRef}
			data-slot='sheets-editor-overlay'
			data-state={positioned ? 'open' : 'closed'}
			style={style}
			className='pointer-events-auto'
		>
			{/* Provide the overlay geometry so editors (relation/image/geometry) can self-bound their
			    internal scroll lists; without it they read maxHeight:0 and render unbounded (the
			    relation infinite-scroll bug). Mirrors the canvas OverlayViewportGuard's provider. */}
			<OverlayMeasureContext.Provider value={overlayMeasure}>
				<EditorErrorGuard onClose={onCancel}>
					{/* overflow-VISIBLE, never auto/hidden: each editor renders its own rounded card with a
					    `shadow-lg`, and a clipping wrapper the same size as the card squares off that shadow
					    into the "weird halo" around the rounded corners. Editors self-bound their height
					    (relation/image/json scroll internally), so the wrapper never needs to scroll. */}
					<EditorFocusTrap onEscape={onCancel} className={cn('overflow-visible', presetClass)}>
						{children}
					</EditorFocusTrap>
				</EditorErrorGuard>
			</OverlayMeasureContext.Provider>
		</div>,
		portalHost,
	);
}

'use client';

// A Suspense fallback for an overlay editor whose code is still loading. While it is in
// the overlay, the OverlayManager keeps the overlay hidden, so the editor appears once,
// at its final size and place, when its code arrives. It draws nothing itself.

/** Marks an overlay whose editor is not ready to be shown yet. */
export const OVERLAY_PENDING_ATTRIBUTE = 'data-overlay-pending';

export function OverlayPending() {
	return <div {...{ [OVERLAY_PENDING_ATTRIBUTE]: '' }} aria-busy='true' />;
}

// Native overlay open/close state machine. The Phase-4 analogue of glide's
// imperative editor activation, but as a tiny React hook with NO heavy effects:
// `open(cell)` records the active cell (rect captured by the caller from the cell
// DOM node), `close()` clears it. `handleKeyDown` is a host-attachable helper —
// Enter/F2 open (the caller supplies the cell to open, since only the host knows
// which DOM node is focused), Escape closes.
//
// TODO(Phase 7): Tab should commit-and-open-next; today Tab is left to default.

import { useCallback, useState } from 'react';
import type { SheetsScopeKey } from '../../context/sheets-context';
import type { SheetsCellResolution } from '../use-sheets-content';

export interface OverlayCell {
	rowIndex: number;
	colKey: string;
	anchorRect: DOMRect;
	/** Type-to-edit seed: when set, value editors initialize the input to this char (overwrite). */
	initialText?: string;
	/** Keep the media editor mounted when creating its row removes the draft. */
	mediaDraft?: {
		rowId: string;
		tableName: string;
		scopeKey: SheetsScopeKey;
		value: unknown;
		resolution: SheetsCellResolution;
	};
	/**
	 * Edit surface for this active cell. `'overlay'` (default when omitted) renders the portal
	 * editor; `'inline'` edits IN PLACE inside the cell (no portal — the cell host renders the
	 * input) yet still rides this controller so nav/clipboard suppression + scroll commit-on-unmount
	 * are shared. The portal (`OverlayManager` / `editorNode`) is skipped for `'inline'`.
	 */
	mode?: 'overlay' | 'inline';
}

export interface OverlayController {
	active: OverlayCell | null;
	isOpen: boolean;
	open: (cell: OverlayCell) => void;
	close: () => void;
	/**
	 * Re-anchor the open overlay to a freshly-measured rect WITHOUT changing the active
	 * cell — the editor-follows-cell-on-scroll path (Stage B). No-op when closed. Keeps
	 * the same {@link OverlayCell} identity for every field except `anchorRect`, so the
	 * editor's local state (in-progress value, focus) survives the reposition.
	 */
	reanchor: (anchorRect: DOMRect) => void;
	/**
	 * Host key handler. Enter/F2 open the cell returned by `resolveCell` (the host
	 * resolves the focused cell + measures its rect); Escape closes. `resolveCell`
	 * may return null (nothing focused / not editable) — then the open is skipped.
	 */
	handleKeyDown: (e: React.KeyboardEvent, resolveCell: () => OverlayCell | null) => void;
}

export function useOverlayController(): OverlayController {
	const [active, setActive] = useState<OverlayCell | null>(null);

	const open = useCallback((cell: OverlayCell) => {
		setActive(cell);
	}, []);

	const close = useCallback(() => {
		setActive(null);
	}, []);

	const reanchor = useCallback((anchorRect: DOMRect) => {
		setActive((prev) => (prev ? { ...prev, anchorRect } : prev));
	}, []);

	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent, resolveCell: () => OverlayCell | null) => {
			if (e.key === 'Enter' || e.key === 'F2') {
				const cell = resolveCell();
				if (!cell) return;
				e.preventDefault();
				setActive(cell);
				return;
			}
			if (e.key === 'Escape') {
				e.preventDefault();
				setActive(null);
			}
			// TODO(Phase 7): Tab -> commit current + open next cell.
		},
		[],
	);

	return { active, isOpen: active != null, open, close, reanchor, handleKeyDown };
}

// The DOM cell host — the `getCellContent` → React port. Given a cell's render context
// (its row, column and state) it asks the injected resolver for the
// {@link SheetsCellResolution} ({ cell, component? })
// and renders the consumer component when present, else dispatches on the neutral
// `kind` to the matching built-in view (cell-model/views/*).
//
// Phase 3 replaces the Phase-1 value→kind STOPGAP (`deriveSheetsCell`) with
// registry-driven resolution: the host no longer guesses a kind from the JS value
// — `getSheetsCellContent(rowIndex, colKey)` runs the full `createCellContent` →
// `toSheetsCell` routing and (when the consumer registered a `cellComponent` for
// the resolved typeKey) hands back the component to render instead of a built-in
// view. SheetsDomInner injects the resolver via the `renderCell` closure.
//
// The kind→view map covers every native SheetsCellKind. datetime/interval cells
// carry kind 'text' (formatted text in v1), so they route through TextCellView
// alongside the grid-internal kinds (loading/draft-action/custom); their dedicated
// DateTimeCellView/IntervalCellView stay exported for per-typeKey use later.
// Dependency-light: local `cn` only, with no shared primitive dependency.
import { memo, useCallback, useRef } from 'react';
import type React from 'react';

import { cn } from '../utils/cn';
import { getDraftMeta, type SheetsRow } from '../grid/row-model';
import { DRAFT_ACTION_COLUMN_KEY } from '../grid/sheets.constants';
import { DRAFT_ROW_ERROR_KEY } from '../grid/draft-guidance';
import type { RenderCellContext } from '../table/grid-viewport';
import type { CellProps } from '../cell-model/cell-props';
import { BadgesCellView } from '../cell-model/views/badges-view';
import { BooleanCellView } from '../cell-model/views/boolean-view';
import { DraftActionCellView, type DraftActionStatus } from '../cell-model/views/draft-action-view';
import { GeometryCellView } from '../cell-model/views/geometry-view';
import { ImageCellView } from '../cell-model/views/image-view';
import { LoadingCellView } from '../cell-model/views/loading-view';
import { NumberCellView } from '../cell-model/views/number-view';
import { RelationCellView } from '../cell-model/views/relation-view';
import { TextCellView } from '../cell-model/views/text-view';
import { UriCellView } from '../cell-model/views/uri-view';
import { reportRejectedWrites } from '../grid/write-feedback';
import { InlineCellEditor, type InlineEditMove } from './inline-cell-editor';
import type { SheetsCellResolution } from './use-sheets-content';

/** Native DOM content resolver injected by the shell — mirrors `getCellContent`. */
export type GetSheetsCellContent = (rowIndex: number, colKey: string) => SheetsCellResolution;

/**
 * Open the native overlay editor for a cell. Threaded from `SheetsDomInner` through
 * `renderCell` so only the host knows the cell's DOM node (it measures the anchor
 * rect off `getBoundingClientRect`). Phase-4 additive — the canvas path is untouched.
 */
export type OpenEditor = (rowIndex: number, colKey: string, anchorRect: DOMRect, initialText?: string) => void;

/**
 * Submit a client-side draft row by its draft id. Threaded from `SheetsDomInner` (the
 * shell's `submitDraftRow`) so the draft-action cell's REAL `<Button>` can wire its
 * onClick. Phase-7 Stage-4 consumes it; Stage-2 only plumbs it through.
 */
export type SubmitDraftRow = (draftRowId: string) => Promise<unknown>;

// COMPLETE kind→view map. `loading` routes to its skeleton view; `draft-action` is
// special-cased UPSTREAM (rendered as DraftActionCellView with explicit props, never
// reaching here), so it — like `custom`/`text` — falls back to TextCellView if it ever does.
function renderKindView(props: CellProps) {
	switch (props.cell.kind) {
		case 'number':
			return <NumberCellView {...props} />;
		case 'boolean':
			return <BooleanCellView {...props} />;
		case 'badges':
			return <BadgesCellView {...props} />;
		case 'uri':
			return <UriCellView {...props} />;
		case 'image':
			return <ImageCellView {...props} />;
		case 'geometry':
			return <GeometryCellView {...props} />;
		case 'relation':
			return <RelationCellView {...props} />;
		case 'loading':
			return <LoadingCellView {...props} />;
		case 'text':
		case 'draft-action':
		case 'custom':
		default:
			return <TextCellView {...props} />;
	}
}

/** Explicit draft-action descriptor for a draft row, derived from its DraftMeta. */
interface DraftActionInfo {
	draftRowId: string;
	status: DraftActionStatus;
	errored: boolean;
	disabled: boolean;
	/** Why the row was not saved: what it still needs, or the server's reason. */
	errorMessage: string | null;
}

/**
 * Derive the draft-action cell's props from a row's draft metadata — the DOM analogue
 * of the canvas draft-action-cell reading the draft slice. `errored`/`disabled` mirror
 * the canvas: an error status surfaces the red dot but keeps the button live (the canvas
 * painter never disabled on error); `saving` disables (DraftActionCellView also self-locks).
 */
function deriveDraftActionInfo(row: SheetsRow | null | undefined): DraftActionInfo | null {
	const meta = getDraftMeta(row);
	if (!meta) return null;
	const status: DraftActionStatus = meta.status;
	const errored = status === 'error';
	const errorMessage = errored ? (meta.errors?.[DRAFT_ROW_ERROR_KEY] ?? null) : null;
	return { draftRowId: meta.draftRowId, status, errored, disabled: status === 'saving', errorMessage };
}

interface SheetsCellHostInnerProps {
	resolution: SheetsCellResolution;
	/** The row is a new (draft) row: its values are checked as a whole when it is saved. */
	isDraftRow: boolean;
	rowId: string;
	colKey: string;
	rowIndex: number;
	columnIndex: number;
	value: unknown;
	isEditing: boolean;
	/** True when this is the active (keyboard cursor) cell — drives the focus ring. */
	isActive: boolean;
	/** True for the active cell and every cell of the active range — drives aria-selected. */
	isSelected: boolean;
	/** Open the overlay editor for this cell; undefined on render paths without editing (e.g. tests). */
	openEditor?: OpenEditor;
	/** Type-to-edit seed for the inline editor (only meaningful when `isEditing`). */
	inlineInitialText?: string;
	/** Commit an inline (in-cell) edit. Set on the inline-edit render path; reuses the host's
	 * value-commit pipeline (bulk-or-single). */
	onInlineCommit?: (rowIndex: number, colKey: string, value: unknown, move?: InlineEditMove) => void;
	/** Cancel an inline (in-cell) edit — discards and closes. */
	onInlineCancel?: () => void;
	/** Park the active cell on this cell (click-to-activate). `shiftKey` extends the range from the
	 * anchor instead of resetting it. Undefined on render paths without nav. */
	onActivateCell?: (col: number, row: number, shiftKey?: boolean) => void;
	/** Right-click this cell — opens the grid context menu anchored at the pointer. The grid first
	 * activates the cell when it is outside the current selection, so the menu acts on it. */
	onContextMenu?: (col: number, row: number, clientX: number, clientY: number) => void;
	/** Submit a draft row by id — wired to the draft-action cell's Button (Stage 4). */
	onSubmitDraftRow?: SubmitDraftRow;
	/** Draft-action descriptor when this is the draft-action column of a draft row; null otherwise. */
	draftAction?: DraftActionInfo | null;
	className?: string;
}

/** Build the full {@link CellProps} for a resolved cell. `onStartEdit` is supplied by the host. */
function toCellProps(props: SheetsCellHostInnerProps, onStartEdit: () => void): CellProps {
	const { cell } = props.resolution;
	return {
		cell,
		value: props.value,
		colKey: props.colKey,
		rowId: props.rowId,
		rowIndex: props.rowIndex,
		column: { key: props.colKey, name: props.colKey, cellType: cell.meta?.cellType ?? 'unknown' },
		isEditing: props.isEditing,
		onStartEdit,
		disabled: false,
		readOnlyReason: props.resolution.readOnlyReason,
		isActive: props.isActive,
	};
}

// Memoized on (rowId, colKey, value, isEditing, openEditor) — the DOM analogue of
// glide's `updateCells`: only the changed cell re-renders, never the whole window.
// The resolution is derived from the first four inputs, so they fully gate the
// output; openEditor is added so the wrapper's handlers stay current.
const SheetsCellHostInner = memo(
	function SheetsCellHostInner(props: SheetsCellHostInnerProps) {
		const wrapperRef = useRef<HTMLDivElement | null>(null);

		// Start editing anchored to THIS cell's DOM node — the host is the only place
		// that knows the cell's rect (read off getBoundingClientRect, viewport coords,
		// matching the OverlayManager's window.innerHeight assumption). A read-only cell
		// still goes through the edit route: a value viewer opens, or the reason is shown.
		const startEdit = useCallback(() => {
			const open = props.openEditor;
			const el = wrapperRef.current;
			if (!open || !el) return;
			open(props.rowIndex, props.colKey, el.getBoundingClientRect());
		}, [props.openEditor, props.rowIndex, props.colKey]);

		// Click parks the active cell here (the grid root owns keys via aria-activedescendant).
		// A shift-click EXTENDS the cell range from the latched anchor instead of resetting it.
		const onActivateCell = props.onActivateCell;
		const columnIndex = props.columnIndex;
		const cellRowIndex = props.rowIndex;
		const activate = useCallback((e: React.MouseEvent) => {
			onActivateCell?.(columnIndex, cellRowIndex, e.shiftKey);
		}, [onActivateCell, columnIndex, cellRowIndex]);

		// Right-click: open the grid context menu at the pointer. preventDefault suppresses the
		// browser menu; the grid handler activates this cell first when it is outside the selection.
		const onContextMenu = props.onContextMenu;
		const contextMenu = useCallback((e: React.MouseEvent) => {
			if (!onContextMenu) return;
			e.preventDefault();
			onContextMenu(columnIndex, cellRowIndex, e.clientX, e.clientY);
		}, [onContextMenu, columnIndex, cellRowIndex]);

		const onSubmitDraftRow = props.onSubmitDraftRow;
		const draftAction = props.draftAction;
		const submitDraft = useCallback(() => {
			if (draftAction && onSubmitDraftRow) void onSubmitDraftRow(draftAction.draftRowId);
		}, [draftAction, onSubmitDraftRow]);

		const cellProps = toCellProps(props, startEdit);
		const Component = props.resolution.component;
		const styleHint = props.resolution.cell.styleHint;
		// DOM equivalent of applyDraftDisabledStyle / applyDraftErrorStyle: a draft cell
		// fades (muted text + tinted bg); a per-cell error overrides with a red bg/text.
		const draftClasses = cn(
			styleHint?.draft && 'bg-muted/40 text-muted-foreground',
			styleHint?.error && 'bg-destructive/10 text-destructive',
			// A value the server could not send shows a muted notice, never an empty cell.
			styleHint?.unreadable && 'text-muted-foreground italic',
		);
		// The draft-action column renders the REAL <Button> (DraftActionCellView), which
		// takes its own prop shape — bypass the kind→view map and the value/editor wiring.
		const isDraftActionCell = props.colKey === DRAFT_ACTION_COLUMN_KEY || props.resolution.cell.kind === 'draft-action';
		// Border wrapper carries the mouse activation handlers (click parks the active cell,
		// double-click opens the editor). Keys are owned by the grid root (aria-activedescendant
		// pattern), so the wrapper is NOT individually focusable. It is the gridcell: the grid's
		// aria-activedescendant points at its id, so its role, selection, column index and
		// read-only state are what a screen reader announces. The views inside are plain content.
		return (
			<div
				ref={wrapperRef}
				role='gridcell'
				id={`sheets-cell-${props.rowIndex}-${props.columnIndex}`}
				aria-colindex={props.columnIndex + 1}
				aria-selected={props.isSelected || undefined}
				aria-readonly={props.resolution.readOnlyReason ? true : undefined}
				aria-description={props.resolution.readOnlyReason ?? undefined}
				title={props.resolution.readOnlyReason ?? props.resolution.errorMessage}
				onClick={activate}
				onDoubleClick={startEdit}
				onContextMenu={contextMenu}
				className={cn(
					'relative h-full w-full overflow-hidden outline-none',
					props.isActive && 'z-20 ring-2 ring-inset ring-primary',
					draftClasses,
					props.className,
				)}
			>
				{isDraftActionCell ? (
					draftAction ? (
						<DraftActionCellView
							status={draftAction.status}
							errored={draftAction.errored}
							errorMessage={draftAction.errorMessage}
							disabled={draftAction.disabled}
							onSubmit={submitDraft}
						/>
					) : null
				) : props.isEditing ? (
					// Inline (in-cell) edit for the simple text-representable types — a bare <input>
					// overlaying the view. `isEditing` is set true ONLY for inline-edit intents (the
					// shell short-circuits inline-toggle/overlay/none before here), so the cell kind is
					// always text or number → derive the numeric variant from it.
					<InlineCellEditor
						ariaLabel={`Edit ${props.resolution.column?.name ?? props.resolution.fieldMeta?.name ?? props.colKey}`}
						value={props.value}
						initialText={props.inlineInitialText}
						numeric={props.resolution.cell.kind === 'number'}
						column={props.resolution.column ?? null}
						creating={props.isDraftRow}
						onCommit={(next, move) => props.onInlineCommit?.(props.rowIndex, props.colKey, next, move)}
						onCancel={() => props.onInlineCancel?.()}
						onReject={(reason) => reportRejectedWrites([{ rowIndex: props.rowIndex, colKey: props.colKey, reason }], 1)}
					/>
				) : Component ? (
					<Component {...cellProps} />
				) : (
					renderKindView(cellProps)
				)}
			</div>
		);
	},
	(prev, next) =>
		prev.rowId === next.rowId &&
		prev.colKey === next.colKey &&
		// The id (the aria-activedescendant target) and aria-colindex come from the indexes.
		prev.rowIndex === next.rowIndex &&
		prev.columnIndex === next.columnIndex &&
		prev.value === next.value &&
		prev.isEditing === next.isEditing &&
		// initialText seeds the inline editor on open; it only differs for the editing cell.
		prev.inlineInitialText === next.inlineInitialText &&
		prev.onInlineCommit === next.onInlineCommit &&
		prev.onInlineCancel === next.onInlineCancel &&
		// isActive must gate the memo or the focus ring will not move between cells.
		prev.isActive === next.isActive &&
		prev.isDraftRow === next.isDraftRow &&
		prev.isSelected === next.isSelected &&
		prev.openEditor === next.openEditor &&
		prev.onActivateCell === next.onActivateCell &&
		prev.onContextMenu === next.onContextMenu &&
		prev.onSubmitDraftRow === next.onSubmitDraftRow &&
		prev.resolution.cell.readonly === next.resolution.cell.readonly &&
		prev.resolution.readOnlyReason === next.resolution.readOnlyReason &&
		prev.resolution.errorMessage === next.resolution.errorMessage &&
		prev.resolution.cell.styleHint?.unreadable === next.resolution.cell.styleHint?.unreadable &&
		// styleHint.draft/error and the draft-action status can flip while `value` is
		// unchanged (validation result arrives, save in flight), so gate on them too.
		prev.resolution.cell.styleHint?.draft === next.resolution.cell.styleHint?.draft &&
		prev.resolution.cell.styleHint?.error === next.resolution.cell.styleHint?.error &&
		sameDraftAction(prev.draftAction, next.draftAction)
);

/** Draft-action equality for the memo gate — status/errored/disabled/reason drive the Button. */
function sameDraftAction(a: DraftActionInfo | null | undefined, b: DraftActionInfo | null | undefined): boolean {
	if (a === b) return true;
	if (!a || !b) return false;
	return (
		a.draftRowId === b.draftRowId &&
		a.status === b.status &&
		a.errored === b.errored &&
		a.disabled === b.disabled &&
		a.errorMessage === b.errorMessage
	);
}

export interface SheetsCellHostProps {
	/** The cell's row, column and state, from the viewport (`isEditing` renders the bare <input>). */
	ctx: RenderCellContext;
	getSheetsCellContent: GetSheetsCellContent;
	/** Open the overlay editor for the activated cell (double-click; grid root owns Enter / F2). */
	openEditor?: OpenEditor;
	/** Commit an inline (in-cell) edit — reuses the host value-commit pipeline. */
	onInlineCommit?: (rowIndex: number, colKey: string, value: unknown, move?: InlineEditMove) => void;
	/** Cancel an inline (in-cell) edit. */
	onInlineCancel?: () => void;
	/** Park the active cell on click; `shiftKey` extends the cell range from the anchor. */
	onActivateCell?: (col: number, row: number, shiftKey?: boolean) => void;
	/** Right-click → open the grid context menu anchored at the pointer. */
	onContextMenu?: (col: number, row: number, clientX: number, clientY: number) => void;
	/** Submit a draft row by id — wired to the draft-action cell's Button (Stage 4). */
	onSubmitDraftRow?: SubmitDraftRow;
	className?: string;
}

/**
 * Render one cell as DOM. Wire via the {@link GridViewport} `renderCell` closure,
 * which injects the shell's resolver: `(ctx) => <SheetsCellHost ctx={ctx}
 * getSheetsCellContent={getSheetsCellContent} openEditor={openEditor} />`.
 */
export function SheetsCellHost({ ctx, getSheetsCellContent, openEditor, onInlineCommit, onInlineCancel, onActivateCell, onContextMenu, onSubmitDraftRow, className }: SheetsCellHostProps) {
	const { rowIndex, columnId: colKey, row } = ctx;
	const value = row?.[colKey];
	const resolution = getSheetsCellContent(rowIndex, colKey);
	// Only the draft-action column needs the row's draft status; for every other column
	// this is null and the inner skips the Button branch. The row carries the
	// Symbol-keyed DraftMeta (it's the live row ref, never spread away).
	const draftAction = colKey === DRAFT_ACTION_COLUMN_KEY ? deriveDraftActionInfo(row) : null;
	return (
		<SheetsCellHostInner
			resolution={resolution}
			isDraftRow={Boolean(getDraftMeta(row))}
			rowId={ctx.rowId}
			colKey={colKey}
			rowIndex={rowIndex}
			columnIndex={ctx.columnIndex}
			value={value}
			isEditing={ctx.isEditing}
			inlineInitialText={ctx.inlineInitialText}
			onInlineCommit={onInlineCommit}
			onInlineCancel={onInlineCancel}
			isActive={ctx.isActive}
			isSelected={ctx.isSelected}
			openEditor={openEditor}
			onActivateCell={onActivateCell}
			onContextMenu={onContextMenu}
			onSubmitDraftRow={onSubmitDraftRow}
			draftAction={draftAction}
			className={className}
		/>
	);
}

// The DOM content resolver — the native analogue of the canvas `useGridContent`
// (grid/hooks/use-grid-content.ts). It MIRRORS that hook's routing steps 1:1 but
// produces a neutral {@link SheetsCell} (+ the resolved view component) instead of
// a glide `GridCell`, so the DOM grid never touches the canvas render path.
//
// It deliberately does NOT own the `ensureRelationInfo` effect: the canvas
// `useGridContent` already runs that effect for the same table, so this hook takes
// `relationInfoByField` + `meta` as INPUTS to avoid a duplicate store write/effect.
// Draft VISUAL styling (faded/error theme overrides) is intentionally deferred to
// Phase 7 — here we only blank the leaked draft-id text and tag `styleHint.draft`
// so Phase 7 can style from a neutral flag (no glide theme imports).

import { useCallback, useMemo, useRef } from 'react';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import type { CellType } from '../cell-types/types';
import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import type { CellCreationMetadata } from '../grid/grid-cell-types';
import type { CellProps } from '../cell-model/cell-props';
import type { SheetsCell } from '../cell-model/sheets-cell';
import type { SheetsRow } from '../grid/row-model';
import type { RelationInfo } from '../store/relation-info-slice';
import type { ColumnModel, MetaQuery, RelationModel, TableModel } from '@constructive-io/data';
import { readCellError, readRelationTotalCount } from '@constructive-io/data';
import type { CellTypeMatchInput } from '../cell-types/define-cell-type';
import {
	CELL_READ_ERROR_TEXT,
	buildRelationFieldNameSet,
	relationCellReadOnlyReason,
	resolveGridCellRoute,
	resolveModelCellRoute,
} from '../grid/cell-routing';
import { getDraftMeta } from '../grid/row-model';
import { unwrapRelationValue } from '../grid/sheets.utils';
import { MEDIA_TYPES } from '../cell-types/cell-type-groups';
import type { SheetsRowIdentifier } from '../row-identity';

interface RelationOptions {
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
}

/** Resolved DOM cell payload: the neutral cell plus its (optional) view component. */
export interface SheetsCellResolution {
	cell: SheetsCell;
	component?: React.ComponentType<CellProps>;
	colKey: string;
	/**
	 * The resolved cell-type key (post detection-override) — the SINGLE source of
	 * truth the host feeds to `resolveEditIntent` to route activation. Always set;
	 * `'text'` for the loading/empty fallthrough cells that carry no type. (Mirror
	 * of the `meta.cellType` the cell itself now self-describes.)
	 */
	typeKey: string;
	/** Typed server row locator, separate from the grid's string key. */
	rowIdentifier?: SheetsRowIdentifier | null;
	readOnlyReason?: string;
	/** Field metadata for the column — fed to a native overlay editor's EditorProps.fieldMeta. */
	fieldMeta?: FieldMetadata;
	/** Relation info for the column (when relational) — fed to a native overlay editor's EditorProps.relationInfo. */
	relationInfo?: RelationInfo;
	/** The table-model column behind this cell, or null when the cell is not a column. */
	column?: ColumnModel | null;
	/** The table-model relation behind this cell, or null when the cell is not a relation. */
	relation?: RelationModel | null;
	/** A problem with this draft cell's value (for example a missing required value), shown on the cell. */
	errorMessage?: string;
}

export interface UseSheetsContentArgs {
	data: SheetsRow[];
	columnKeys: string[];
	fieldMetaMap: ReadonlyMap<string, FieldMetadata>;
	registry: CellTypeRegistry;
	tableName?: string;
	options?: RelationOptions;
	/** Relation info per field — owned by the canvas `useGridContent` ensureRelationInfo effect. */
	relationInfoByField: ReadonlyMap<string, RelationInfo>;
	/** Schema meta (same value the canvas path reads via useSheetsMeta). */
	meta: MetaQuery | undefined;
	/** The table model of the grid, or null while it loads. */
	tableModel?: TableModel | null;
	/** Disable every persisted-row editor when the table cannot expose update mutations. */
	serverRowsReadOnly?: boolean;
	/** Primary-key fields are immutable after insertion because they define row identity. */
	serverReadOnlyFields?: ReadonlySet<string>;
	/** Resolve the GraphQL mutation identity. */
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	canUpload?: boolean;
	canCreate?: boolean;
	/** Host cell-type overrides by `Table.field` (`SheetsConfig.fieldTypeOverrides`). */
	fieldTypeOverrides?: Readonly<Record<string, string>>;
}

function isDraftId(value: unknown): boolean {
	return typeof value === 'string' && value.startsWith('draft:');
}

/**
 * DISPLAY-LEVEL suppression of an internal draft key leaking as visible cell text —
 * the {@link SheetsCell} mirror of the canvas `suppressDraftIdText`. When the row is
 * a draft AND the value being rendered is the draft key (the `id` column starting
 * with `draft:`, or any value equal to the draft id), blank the cell's display/data
 * text while preserving kind and structural flags. Narrow by design: nothing else.
 */
export function suppressDraftIdText(
	cell: SheetsCell,
	args: { isDraftRow: boolean; colKey: string; rawValue: unknown; draftId: string | undefined },
): SheetsCell {
	const { isDraftRow, colKey, rawValue, draftId } = args;
	if (!isDraftRow) return cell;

	const isIdColumnDraftKey = colKey === 'id' && isDraftId(rawValue);
	const valueIsDraftId = typeof draftId === 'string' && rawValue === draftId;
	if (!isIdColumnDraftKey && !valueIsDraftId) return cell;

	return { ...cell, data: typeof cell.data === 'string' ? '' : cell.data, displayData: '' };
}

/**
 * Tag the cell as a draft row so the host can apply faded/error styling from a flag —
 * the DOM mirror of the canvas applyDraftDisabledStyle/applyDraftErrorStyle split.
 * `error` is set when draftMeta.errors carries a field-level error for THIS colKey
 * (canvas: applyDraftErrorStyle); `draft` always (canvas: faded/disabled visuals).
 */
function tagDraftStyle(cell: SheetsCell, hasError: boolean): SheetsCell {
	return { ...cell, styleHint: { ...cell.styleHint, draft: true, error: hasError } };
}

/** The cell for a value the list read could not serve: a notice, read-only. */
function unreadableCell(cellType: string): SheetsCell {
	return {
		kind: 'text',
		data: '',
		displayData: CELL_READ_ERROR_TEXT,
		readonly: true,
		styleHint: { unreadable: true },
		meta: { cellType: cellType as CellType },
	};
}

/**
 * Build the DOM content resolver. Returns `getSheetsCell(rowIndex, colKey)` which
 * mirrors the canvas `getCellContent` routing exactly (draftMeta → fieldMeta →
 * relationInfo → route → relation value unwrap → matchInput → resolveTypeKey →
 * metadata → registry.toSheetsCell), then suppresses any leaked draft-id text and
 * tags draft rows. The view component is resolved alongside via `getCellComponent`.
 */
export function useSheetsContent(args: UseSheetsContentArgs) {
	const {
		data,
		columnKeys,
		fieldMetaMap,
		registry,
		tableName,
		options,
		relationInfoByField,
		meta,
		serverRowsReadOnly = false,
		serverReadOnlyFields,
		getRowIdentifier,
		canUpload = true,
		canCreate = true,
		tableModel = null,
		fieldTypeOverrides,
	} = args;

	const columnByName = useMemo(
		() => new Map((tableModel?.columns ?? []).map((column) => [column.name, column] as const)),
		[tableModel],
	);
	const relationByField = useMemo(
		() => new Map((tableModel?.relations ?? []).map((relation) => [relation.fieldName, relation] as const)),
		[tableModel],
	);

	const relationFieldNamesFromMeta = useMemo(() => buildRelationFieldNameSet(meta, tableName), [meta, tableName]);

	// The rows are read at call time, so the resolver keeps its identity when the row array
	// changes (a page loads, a cell saves). The grid rows memoized on it then render again only
	// when their own row object changes, not the whole window on every data change.
	const dataRef = useRef(data);
	dataRef.current = data;

	// RESULT CACHE, per row object and column. The cell host calls `getSheetsCell` for every
	// visible cell it renders, almost always re-deriving an identical resolution, and the full
	// pipeline (route → relation unwrap → resolveTypeKey → toSheetsCell) allocates ≥3 objects.
	//
	// SAFETY: a resolution reads only its row object's fields (draft meta, cell errors, the
	// relation fields) and the deps below, never the row's index. Row objects are never
	// changed in place: a server row is a new object after a refetch or an optimistic update
	// (see useInfiniteGridData), and a draft row after any draft change (see useDraftRows).
	// So a row object's cached resolution stays valid until one of these deps changes, which
	// throws the whole cache away.
	const cache = useMemo(
		() => new WeakMap<object, Map<string, SheetsCellResolution>>(),
		[columnKeys, fieldMetaMap, registry, relationFieldNamesFromMeta, relationInfoByField, options, serverRowsReadOnly, serverReadOnlyFields, getRowIdentifier, canUpload, canCreate, tableModel, columnByName, relationByField, fieldTypeOverrides, tableName],
	);

	const getSheetsCell = useCallback(
		(rowIndex: number, colKey: string): SheetsCellResolution => {
			// UNLOADED INFINITE ROW → loading skeleton. In infinite-scroll mode `data` is the
			// null-backed proxy from useSheets: a server index whose page is still in flight reads
			// back as `null` (drafts are real objects, never null). Resolve those slots to a neutral
			// `kind: 'loading'` cell with NO component, so the host's kind→view map paints
			// LoadingCellView (the canvas analogue is glide's loadingCell). Without this the row
			// coerces to `{}` below and every cell renders as blank text instead of a skeleton.
			const rawRow = (dataRef.current as any[])[rowIndex];
			if (colKey && rawRow == null) {
				return {
					cell: { kind: 'loading', data: null, displayData: '', readonly: true },
					colKey,
					typeKey: 'text',
					column: null,
					relation: null,
				};
			}
			const rowData = rawRow ?? {};
			if (!colKey) {
				return { cell: { kind: 'text', data: '', displayData: '', readonly: false }, colKey, typeKey: 'text', column: null, relation: null };
			}

			const rawValue = rowData?.[colKey];

			// RESULT-CACHE FAST PATH: the row object fully determines its resolution (see the cache).
			let rowCache = cache.get(rowData);
			const hit = rowCache?.get(colKey);
			if (hit) return hit;
			const draftMeta = getDraftMeta(rowData);
			const isDraftRow = Boolean(draftMeta?.isDraft);

			const fieldMeta: FieldMetadata | undefined = fieldMetaMap.get(colKey);
			const column = columnByName.get(colKey) ?? null;
			const relation = relationByField.get(colKey) ?? null;
			const relationInfo = relationInfoByField.get(colKey);
			// The name-based fallback only covers keys the table model does not describe as a column.
			const isRelationFallback = !column && relationFieldNamesFromMeta.has(colKey);
			const isRelation = Boolean(relation) || Boolean(relationInfo) || isRelationFallback;

			// A table-model column routes from the model alone (kind, write flags, reasons).
			// Relations keep the relation route; the relation lane owns their editing rules.
			const cellError = column ? readCellError(rowData, colKey) : null;
			const modelRoute = column && tableModel && !isRelation
				? resolveModelCellRoute({
					column,
					table: tableModel,
					isDraftRow,
					cellError,
					typeOverride: tableName ? fieldTypeOverrides?.[`${tableName}.${colKey}`] : null,
					lockedFields: serverReadOnlyFields,
				})
				: null;

			const foreignKeyField = relationInfo?.foreignKeyField;
			const canEditRelationInline =
				relationInfo?.kind === 'belongsTo' &&
				typeof foreignKeyField === 'string' &&
				fieldMetaMap.has(foreignKeyField);
			const route = modelRoute
				? null
				: resolveGridCellRoute({
					colKey,
					fieldMeta,
					relationInfo,
					isRelationFallback,
					hasForeignKeyField: canEditRelationInline,
				});
			// A table-model relation opens the relation editor, which decides each link and says why;
			// the cell carries the relation-level reason (not editable, or the row cannot be written).
			const relationReason = relation ? relationCellReadOnlyReason(relation, tableModel, isDraftRow) : null;
			const tableForcedReadOnly = !modelRoute && !relation && !isDraftRow && (
				serverRowsReadOnly || Boolean(serverReadOnlyFields?.has(colKey))
			);

			// A table-model relation hands its factory and editor the raw related record(s) of
			// `row[relation.fieldName]`; only legacy relation info (no model relation) is wrapped.
			let valueForCell = rawValue;
			const legacyRelationInfo = relation ? undefined : relationInfo;

			if (legacyRelationInfo && legacyRelationInfo.relationField && legacyRelationInfo.relationField !== colKey) {
				const relatedValue = (rowData as any)?.[legacyRelationInfo.relationField];
				if (relatedValue !== undefined && relatedValue !== null) {
					valueForCell = relatedValue;
				} else if (typeof rawValue === 'string' && rawValue && !isDraftId(rawValue)) {
					valueForCell = { id: rawValue };
				}
			} else if (legacyRelationInfo && valueForCell == null) {
				const fkField = legacyRelationInfo.foreignKeyField;
				const fkValue = fkField ? (rowData as any)?.[fkField] : undefined;
				if (fkValue && !isDraftId(fkValue)) {
					valueForCell = { id: fkValue };
				}
			}

			if (isRelation) {
				valueForCell = unwrapRelationValue(valueForCell);
			}

			// Consumer detection override: a registered def's match() may override the
			// resolved typeKey. With no consumer cell types this returns the routed type.
			const builtinCellType = modelRoute?.cellType ?? route?.cellType ?? 'text';
			const matchInput: CellTypeMatchInput = {
				gqlType: column?.value.typeName ?? fieldMeta?.type?.gqlType ?? '',
				isArray: column ? column.value.isArray : Boolean(fieldMeta?.type?.isArray),
				pgType: fieldMeta?.type?.pgType ?? null,
				subtype: fieldMeta?.type?.subtype ?? null,
				fieldName: colKey,
				kind: column?.value.kind ?? null,
				semantic: column?.value.semantic ?? null,
				column,
			};
			const cellType = registry.resolveTypeKey(matchInput, () => builtinCellType);
			const rowIdentifier = !isDraftRow ? getRowIdentifier?.(rowData) : null;
			const isMedia = MEDIA_TYPES.has(cellType);
			const lacksMediaTarget = isMedia && (isDraftRow ? !canCreate || serverRowsReadOnly : rowIdentifier == null);
			const readOnlyReason =
				modelRoute?.readOnlyReason ?? relationReason ?? (isMedia && !canUpload ? 'Uploads need a storage endpoint' : null) ?? undefined;
			const routeReadOnly = modelRoute
				? Boolean(modelRoute.readOnlyReason)
				: relation
					? Boolean(relationReason)
					: Boolean(route?.isReadonly);
			const forcedReadOnly = tableForcedReadOnly || lacksMediaTarget || !!readOnlyReason;

			const metadata: CellCreationMetadata = {
				cellType,
				fieldName: colKey,
				fieldMeta,
				relationInfo,
				column,
				relation,
				table: tableModel,
				relationTotalCount: relation?.hasTotalCount ? readRelationTotalCount(rowData, relation.fieldName) : null,
				relationOptions: relationInfo ? options || {} : undefined,
				canEdit: !routeReadOnly && (route && !relation ? route.canEdit : true) && !forcedReadOnly,
				isReadonly: routeReadOnly || forcedReadOnly,
				activationBehavior: route?.activationBehavior ?? 'double-click',
			};

			const resolvedCell = cellError
				? unreadableCell(cellType)
				: registry.toSheetsCell(cellType, valueForCell, { metadata });
			const cell = (forcedReadOnly || routeReadOnly) && !resolvedCell.readonly
				? { ...resolvedCell, readonly: true }
				: resolvedCell;

			// Blank any internal draft key that would otherwise render as visible text
			// (kind unchanged); narrow to the draft id, nothing else.
			const displaySafe = suppressDraftIdText(cell, {
				isDraftRow,
				colKey,
				rawValue,
				draftId: draftMeta?.draftRowId,
			});

			// Flag draft rows (faded) and per-cell errors (error) so the host can paint
			// the DOM equivalent of applyDraftDisabledStyle / applyDraftErrorStyle.
			const draftErrors = draftMeta?.errors ?? null;
			const hasCellError = Boolean(draftErrors && colKey in draftErrors);
			const errorMessage = hasCellError && draftErrors ? draftErrors[colKey] : undefined;
			const styled = isDraftRow ? tagDraftStyle(displaySafe, hasCellError) : displaySafe;

			// An unreadable cell always shows the built-in notice, never a consumer component.
			const component = cellError ? undefined : registry.getCellComponent(cellType);
			// Surface the already-computed field/relation meta so a native overlay editor
			// (relation/image, Phase 5) can read EditorProps.fieldMeta / relationInfo without
			// re-resolving — no extra work, just exposing what this routing already derived.
			// `typeKey` is the resolved cellType — the single source of truth for edit-intent.
			const resolution: SheetsCellResolution = {
				cell: styled, component, colKey, typeKey: cellType, fieldMeta, relationInfo, column, relation, rowIdentifier, readOnlyReason, errorMessage,
			};
			if (!rowCache) {
				rowCache = new Map();
				cache.set(rowData, rowCache);
			}
			rowCache.set(colKey, resolution);
			return resolution;
		},
		[cache, columnKeys, fieldMetaMap, registry, relationFieldNamesFromMeta, relationInfoByField, options, serverRowsReadOnly, serverReadOnlyFields, getRowIdentifier, canUpload, canCreate, tableModel, columnByName, relationByField, fieldTypeOverrides, tableName],
	);

	return { getSheetsCell };
}

// What each cell shows and whether it can be written: the model's relation entries and
// the native content resolver, with the files-table preview cells on top.
import { useMemo, useRef } from 'react';

import type { MetaField, MetaQuery, TableModel } from '@constructive-io/data';

import type { CellTypeRegistry } from '../../cell-types/cell-type-registry';
import type { SheetsConfig } from '../../context/sheets-context';
import { useSheetsContent } from '../../grid-dom/use-sheets-content';
import type { SheetsRowIdentifier } from '../../row-identity';
import { relationInfoFromModel } from '../../store/relation-info-slice';
import { withFilePreviewCells } from '../../uploads/files-table-preview';
import type { SheetsRow } from '../row-model';
import { mapFromRelationInfoMap } from '../sheets.utils';

export interface UseSheetsCellContentInput {
	tableName: string;
	tableModel: TableModel | null;
	combinedRows: SheetsRow[];
	gridColumnKeys: string[];
	fieldMetaMap: Map<string, MetaField>;
	cellRegistry: CellTypeRegistry;
	relationChipLimit: number | undefined;
	relationLabelMaxLength: number | undefined;
	filterMeta: MetaQuery | undefined;
	canCreate: boolean;
	canUpdate: boolean;
	primaryKeyFields: ReadonlySet<string>;
	getRowIdentifier: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	canUpload: boolean;
	config: SheetsConfig;
}

export function useSheetsCellContent({
	tableName,
	tableModel,
	combinedRows,
	gridColumnKeys,
	fieldMetaMap,
	cellRegistry,
	relationChipLimit,
	relationLabelMaxLength,
	filterMeta,
	canCreate,
	canUpdate,
	primaryKeyFields,
	getRowIdentifier,
	canUpload,
	config,
}: UseSheetsCellContentInput) {
	// ============== RELATION INFO (model-derived) ==============
	// Per-field relation entries from the table model; a new model (after a `_meta`
	// refetch) rebuilds them. Used by the content resolver + draft/relation routing.
	const relationInfoByField = useMemo(() => relationInfoFromModel(tableModel), [tableModel]);

	const relationInfoObject = useMemo(() => mapFromRelationInfoMap(relationInfoByField), [relationInfoByField]);

	// The resolver, its cache and every grid row memoized on it keep their identity while these
	// do; a new object here each render made every visible cell resolve again on every render.
	const contentOptions = useMemo(
		() => ({ relationChipLimit, relationLabelMaxLength }),
		[relationChipLimit, relationLabelMaxLength],
	);

	// Native DOM content resolver (mirrors the canvas getCellContent routing → SheetsCell).
	const { getSheetsCell: getColumnCellContent } = useSheetsContent({
		data: combinedRows,
		columnKeys: gridColumnKeys,
		fieldMetaMap,
		registry: cellRegistry,
		tableName,
		options: contentOptions,
		relationInfoByField,
		meta: filterMeta,
		serverRowsReadOnly: !canUpdate,
		serverReadOnlyFields: primaryKeyFields,
		getRowIdentifier,
		canUpload,
		canCreate,
		tableModel,
		fieldTypeOverrides: config.fieldTypeOverrides,
	});
	// Rows are read when a cell resolves, so this keeps its identity across data changes
	// (like the resolver it wraps) and the grid rows memoized on it stay put.
	const rowsRef = useRef(combinedRows);
	rowsRef.current = combinedRows;
	const getSheetsCellContent = useMemo(
		() => withFilePreviewCells(getColumnCellContent, (rowIndex) => rowsRef.current[rowIndex], tableModel),
		[getColumnCellContent, tableModel],
	);

	return { relationInfoByField, relationInfoObject, getSheetsCellContent };
}

// The grid's columns: the view's layout over every column of the table, the files-table
// preview column and the draft action column, with committed widths and the resize rule.
import { useCallback, useMemo } from 'react';

import type { MetaField, TableModel } from '@constructive-io/data';

import { useDataGridColumns, type RelationGridColumn } from '../../hooks/use-relation-columns';
import { filesTablePreviewColumn } from '../../uploads/files-table-preview';
import { layoutGridColumns } from '../columns/layout-grid-columns';
import type { useGridState } from '../hooks/use-grid-state';
import type { useInfiniteGridData } from '../hooks/use-infinite-grid-data';
import type { SheetsRow } from '../row-model';
import { DRAFT_ACTION_COLUMN_KEY } from '../sheets.constants';
import { mapFromFieldMetaMap } from '../sheets.utils';
import type { SheetsViewBindings } from '../view-state/use-sheets-view';

export interface UseSheetsColumnsInput {
	tableName: string;
	infiniteScroll: boolean;
	infiniteGridData: ReturnType<typeof useInfiniteGridData>;
	normalizedServerData: unknown[];
	combinedRows: SheetsRow[];
	fieldMetaMap: Map<string, MetaField>;
	tableModel: TableModel | null;
	view: SheetsViewBindings;
	hasDraftRows: boolean;
	gridState: ReturnType<typeof useGridState>['state'];
	gridActions: ReturnType<typeof useGridState>['actions'];
}

export function useSheetsColumns({
	tableName,
	infiniteScroll,
	infiniteGridData,
	normalizedServerData,
	combinedRows,
	fieldMetaMap,
	tableModel,
	view,
	hasDraftRows,
	gridState,
	gridActions,
}: UseSheetsColumnsInput) {
	const fieldMetaByKey = useMemo(() => mapFromFieldMetaMap(fieldMetaMap), [fieldMetaMap]);

	// Build columns with actual data
	// In infinite scroll mode, check if we have initial data
	const hasServerRows = infiniteScroll ? infiniteGridData.hasInitialData : normalizedServerData.length > 0;

	const { columns: allColumns, columnKeys: allColumnKeys } = useDataGridColumns(
		tableName,
		hasServerRows ? combinedRows : undefined,
	);
	// The view's column layout: which columns show, in what order (see grid/columns).
	const { columns: baseColumns, columnKeys } = useMemo(
		() => layoutGridColumns(allColumns, view.layout),
		[allColumns, view.layout],
	);

	// A storage files table gets a preview column (thumbnail and download link).
	const filePreviewColumn = useMemo(() => filesTablePreviewColumn(tableModel), [tableModel]);
	const gridColumnKeys = useMemo(() => {
		const keys = filePreviewColumn ? [...columnKeys, filePreviewColumn.id] : columnKeys;
		if (!hasDraftRows) return keys;
		return [...keys, DRAFT_ACTION_COLUMN_KEY];
	}, [columnKeys, filePreviewColumn, hasDraftRows]);

	// Apply custom widths to columns (the header draws the sort carets itself)
	const columns = useMemo<RelationGridColumn[]>(() => {
		const mapped = baseColumns.map((col) => ({
			...col,
			width: gridState.columnWidths.get(col.id || '') ?? col.width,
		}));

		if (filePreviewColumn) {
			mapped.push({ ...filePreviewColumn, width: gridState.columnWidths.get(filePreviewColumn.id) ?? filePreviewColumn.width });
		}

		if (hasDraftRows) {
			mapped.push({
				id: DRAFT_ACTION_COLUMN_KEY,
				title: '',
				width: gridState.columnWidths.get(DRAFT_ACTION_COLUMN_KEY) ?? 132,
			});
		}

		return mapped;
	}, [baseColumns, filePreviewColumn, gridState.columnWidths, hasDraftRows]);

	// Frozen columns come from the view's layout; a width drag on a table column goes to the
	// layout, one on a column the grid adds itself (preview, draft actions) to the grid state.
	const frozenCount = view.layout.frozenCount;
	const layoutSetWidth = view.layout.setWidth;
	const resizeColumn = useCallback(
		(id: string, width: number) => (allColumnKeys.includes(id) ? layoutSetWidth(id, width) : gridActions.resizeColumn(id, width)),
		[allColumnKeys, layoutSetWidth, gridActions],
	);

	return { fieldMetaByKey, allColumnKeys, columnKeys, gridColumnKeys, columns, frozenCount, resizeColumn };
}

// The rows source: infinite scroll or paginated, unified into one shape, plus the
// write capabilities the table model proves and the row identity helpers.
import { useCallback, useMemo } from 'react';

import type { SortSpec } from '@constructive-io/data';

import { resolveSheetsRowIdentity, sheetsRowKey, type SheetsRowIdentifier } from '../../row-identity';
import type { useGridState } from '../hooks/use-grid-state';
import { useInfiniteGridData } from '../hooks/use-infinite-grid-data';
import { useDataLoading } from '../hooks/use-load-grid';
import { getDraftMeta, type SheetsRow } from '../row-model';

export interface UseSheetsDataInput {
	tableName: string;
	pageSize: number;
	infiniteScroll: boolean;
	orderByClause: SortSpec[] | undefined;
	effectiveWhere: Record<string, unknown> | undefined;
	fetchColumns: string[] | undefined;
	fetchRelations: string[] | undefined;
	gridState: ReturnType<typeof useGridState>['state'];
}

export function useSheetsData({
	tableName,
	pageSize,
	infiniteScroll,
	orderByClause,
	effectiveWhere,
	fetchColumns,
	fetchRelations,
	gridState,
}: UseSheetsDataInput) {
	// ============== INFINITE SCROLL MODE ==============
	const infiniteGridData = useInfiniteGridData({
		tableName,
		pageSize,
		orderBy: orderByClause,
		where: effectiveWhere,
		columns: fetchColumns,
		relations: fetchRelations,
		enabled: infiniteScroll,
	});

	// ============== PAGINATED MODE ==============
	const initialQueryOptions = useMemo(
		() => ({
			limit: pageSize,
			offset: gridState.pageIndex * pageSize,
			orderBy: orderByClause,
			where: effectiveWhere,
			columns: fetchColumns,
			relations: fetchRelations,
		}),
		[pageSize, gridState.pageIndex, orderByClause, effectiveWhere, fetchColumns, fetchRelations],
	);

	// In infinite scroll mode we still use mutations from useDataLoading,
	// but disable row/count queries to avoid duplicate fetching.
	const dataLoadingResult = useDataLoading({
		tableName,
		queryOptions: initialQueryOptions,
		enabled: !infiniteScroll,
	});

	// ============== UNIFIED DATA ACCESS ==============
	// Choose data source based on mode
	const {
		serverData,
		totalCount,
		tableMeta,
		tableModel,
		fieldMetaMap,
		allRelationFields,
		hasCompletedInitialLoad,
		dataError,
		isInitialLoading,
		isFetchingRows,
	} = useMemo(() => {
		if (infiniteScroll) {
			return {
				serverData: [] as any[], // Not used directly in infinite mode
				totalCount: infiniteGridData.totalCount,
				tableMeta: infiniteGridData.tableMeta,
				tableModel: infiniteGridData.tableModel,
				fieldMetaMap: infiniteGridData.fieldMetaMap,
				allRelationFields: infiniteGridData.allRelationFields,
				hasCompletedInitialLoad: infiniteGridData.hasInitialData,
				dataError: infiniteGridData.error,
				// Only the first load (no rows yet) should show the loading screen; refetches keep previous data.
				isInitialLoading: infiniteGridData.isLoading && !infiniteGridData.hasInitialData,
				isFetchingRows: infiniteGridData.isFetching,
			};
		}
		const ctx = dataLoadingResult.contextValue;
		const rows = ctx.data || [];
		return {
			serverData: rows,
			totalCount: ctx.totalCount,
			tableMeta: ctx.tableMeta,
			tableModel: ctx.tableModel,
			fieldMetaMap: ctx.fieldMetaMap,
			allRelationFields: ctx.allRelationFields,
			hasCompletedInitialLoad: !ctx.isLoading,
			dataError: ctx.error,
			// isLoading is true only until the active scope receives its first result.
			isInitialLoading: ctx.isLoading && rows.length === 0,
			isFetchingRows: ctx.isFetching,
		};
	}, [infiniteScroll, infiniteGridData, dataLoadingResult.contextValue]);

	// Writes are allowed only for operations the table model proved against the schema.
	const canCreate = Boolean(tableModel?.operations.create);
	const canUpdate = Boolean(tableModel?.operations.update);
	const canDelete = Boolean(tableModel?.operations.delete);
	const primaryKeyFields = useMemo(() => new Set(tableModel?.primaryKey ?? []), [tableModel]);
	const readOnlyReason = tableModel && !canUpdate
		? tableModel.issues.find((issue) => issue.scope === 'operation' && issue.target === 'update')?.message ?? null
		: null;
	const getRowIdentifier = useCallback(
		(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null => {
			if (!tableMeta) return null;
			const resolution = resolveSheetsRowIdentity(tableMeta, row);
			return resolution.status === 'identified' ? resolution.identifier : null;
		},
		[tableMeta],
	);
	const getRowId = useCallback(
		(row: SheetsRow | null | undefined, index: number): string => {
			const draftMeta = getDraftMeta(row);
			if (draftMeta) return draftMeta.draftRowId;
			if (row && tableMeta) return sheetsRowKey(tableMeta, row, index);
			return `${tableMeta?.schemaName ?? ''}:${tableName}:row:${index}`;
		},
		[tableMeta, tableName],
	);

	return {
		infiniteGridData,
		dataLoadingResult,
		serverData,
		totalCount,
		tableMeta,
		tableModel,
		fieldMetaMap,
		allRelationFields,
		hasCompletedInitialLoad,
		dataError,
		isInitialLoading,
		isFetchingRows,
		canCreate,
		canUpdate,
		canDelete,
		primaryKeyFields,
		readOnlyReason,
		getRowIdentifier,
		getRowId,
	};
}

// Client-side draft rows: their column metadata (kept in sync with the model), adding one,
// and submitting them (all selected drafts, or one from a self-committing editor).
import { useCallback, useEffect, useMemo, useRef } from 'react';

import type { TableModel } from '@constructive-io/data';

import { computeDraftMetaSignature } from '../../store/draft-rows-slice';
import type { DraftSubmitResult } from '../draft-types';
import type { useDraftRows } from '../hooks/use-draft-rows';
import { useDraftSubmission } from '../hooks/use-draft-submission';
import { useGridSelectionState } from '../hooks/use-grid-selection';
import type { useGridState } from '../hooks/use-grid-state';
import type { useInfiniteGridData } from '../hooks/use-infinite-grid-data';
import type { useDataLoading } from '../hooks/use-load-grid';
import type { SheetsRow } from '../row-model';
import type { mapFromFieldMetaMap, mapFromRelationInfoMap } from '../sheets.utils';
import type { SheetsEmit } from './use-sheets-events';

type DraftRows = ReturnType<typeof useDraftRows>;
type FieldMetaByKey = ReturnType<typeof mapFromFieldMetaMap>;
type RelationInfoByKey = ReturnType<typeof mapFromRelationInfoMap>;

/** Draft rows carry every column; their metadata follows the model. */
export function useDraftColumnMeta({
	tableKey,
	allColumnKeys,
	fieldMetaByKey,
	relationInfoObject,
	syncDraftRowsWithMeta,
}: {
	tableKey: string;
	allColumnKeys: string[];
	fieldMetaByKey: FieldMetaByKey;
	relationInfoObject: RelationInfoByKey;
	syncDraftRowsWithMeta: DraftRows['syncDraftRowsWithMeta'];
}) {
	// Draft rows carry every column, shown or hidden.
	const effectiveColumnOrder = useMemo(() => {
		if (allColumnKeys.length > 0) return allColumnKeys;
		return Object.keys(fieldMetaByKey);
	}, [allColumnKeys, fieldMetaByKey]);

	const metaSignature = useMemo(
		() => computeDraftMetaSignature(effectiveColumnOrder, fieldMetaByKey, relationInfoObject),
		[effectiveColumnOrder, fieldMetaByKey, relationInfoObject],
	);

	useEffect(() => {
		if (!effectiveColumnOrder.length) return;
		syncDraftRowsWithMeta({
			tableKey,
			columnOrder: effectiveColumnOrder,
			fieldMetaByKey,
			relationInfoByKey: relationInfoObject,
			metaVersion: metaSignature,
		});
	}, [effectiveColumnOrder, fieldMetaByKey, relationInfoObject, metaSignature, syncDraftRowsWithMeta, tableKey]);

	return { effectiveColumnOrder, metaSignature };
}

export interface UseSheetsDraftActionsInput {
	tableKey: string;
	tableModel: TableModel | null;
	canCreate: boolean;
	emit: SheetsEmit;
	infiniteScroll: boolean;
	infiniteGridData: ReturnType<typeof useInfiniteGridData>;
	combinedRows: SheetsRow[];
	serverRowCount: number;
	draftRows: DraftRows['draftRows'];
	draftRowsTable: DraftRows['draftRowsTable'];
	createDraftRow: DraftRows['createDraftRow'];
	removeDraftRow: DraftRows['removeDraftRow'];
	setDraftRowStatus: DraftRows['setDraftRowStatus'];
	create: ReturnType<typeof useDataLoading>['contextValue']['create'];
	effectiveColumnOrder: string[];
	fieldMetaByKey: FieldMetaByKey;
	relationInfoObject: RelationInfoByKey;
	metaSignature: string;
	gridState: ReturnType<typeof useGridState>['state'];
	gridActions: ReturnType<typeof useGridState>['actions'];
	operationFeedback: Parameters<typeof useDraftSubmission>[0]['feedback'];
}

/** Add a draft row, and submit draft rows. */
export function useSheetsDraftActions({
	tableKey,
	tableModel,
	canCreate,
	emit,
	infiniteScroll,
	infiniteGridData,
	combinedRows,
	serverRowCount,
	draftRows,
	draftRowsTable,
	createDraftRow,
	removeDraftRow,
	setDraftRowStatus,
	create,
	effectiveColumnOrder,
	fieldMetaByKey,
	relationInfoObject,
	metaSignature,
	gridState,
	gridActions,
	operationFeedback,
}: UseSheetsDraftActionsInput) {
	// Ref to hold submitDraftRowForEditor - populated after useDraftSubmission
	// This breaks the circular dependency: editors need the function, but useDraftSubmission
	// needs hasDraftSelection which comes from useGridSelectionState which needs combinedRows
	const submitDraftRowForEditorRef = useRef<((draftRowId: string) => Promise<DraftSubmitResult>) | null>(null);

	const handleSubmitDraftRowForEditor = useCallback(
		async (draftRowId: string): Promise<DraftSubmitResult> => {
			if (!submitDraftRowForEditorRef.current) {
				return { createdRow: null };
			}
			return submitDraftRowForEditorRef.current(draftRowId);
		},
		[],
	);

	const handleRowAppended = useCallback(async () => {
		if (!canCreate) return undefined;
		if (draftRows.length > 0) {
			return serverRowCount + draftRows.length - 1;
		}

		// Silently skip if metadata isn't ready - this is a transient state
		if (!effectiveColumnOrder.length) return undefined;

		createDraftRow({
			tableKey,
			columnOrder: effectiveColumnOrder,
			fieldMetaByKey: fieldMetaByKey as Record<string, any>,
			relationInfoByKey: relationInfoObject,
			metaVersion: metaSignature,
		});

		const rowIndex = serverRowCount + draftRows.length;
		emit('row:create', { rowIndex });
		return rowIndex;
	}, [
		createDraftRow,
		effectiveColumnOrder,
		fieldMetaByKey,
		relationInfoObject,
		metaSignature,
		tableKey,
		draftRows,
		serverRowCount,
		canCreate,
		emit,
	]);

	const { selectedRowCount, selectedDraftRowEntries, hasDraftSelection } = useGridSelectionState({
		gridSelection: gridState.gridSelection,
		combinedRows,
		draftRowsTable,
	});

	const {
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		submitDraftRowForEditor,
	} = useDraftSubmission({
		tableKey,
		draftRowsTable,
		selectedDraftRowEntries,
		hasDraftSelection,
		create,
		removeDraftRow,
		setDraftRowStatus,
		clearSelection: () => gridActions.setGridSelection(undefined),
		tableModel,
		relationInfoByKey: relationInfoObject,
		onSubmittedSuccessfully: infiniteScroll ? infiniteGridData.invalidate : undefined,
		feedback: operationFeedback,
	});

	// Populate the ref for editor access (breaks circular dependency)
	submitDraftRowForEditorRef.current = submitDraftRowForEditor;

	return {
		handleRowAppended,
		selectedRowCount,
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		handleSubmitDraftRowForEditor,
	};
}

// Observational events of the grid (`onEvent`): the emitter, load success or failure,
// and sort, filter and search changes. Purely observational: nothing here changes data.
import { useCallback, useEffect, useRef } from 'react';

import type { SheetsEvent } from '../sheets.types';
import type { SheetsViewBindings } from '../view-state/use-sheets-view';

export type SheetsEmit = (type: SheetsEvent['type'], meta?: Record<string, unknown>) => void;

/** The `onEvent` emitter, stable per table. */
export function useSheetsEmit(tableName: string, onEvent: ((event: SheetsEvent) => void) | undefined): SheetsEmit {
	// Keep the latest onEvent in a ref so firing events never depends on (or churns)
	// the callbacks/effects below — purely observational, no behavioral coupling.
	const onEventRef = useRef(onEvent);
	onEventRef.current = onEvent;
	const emit = useCallback((type: SheetsEvent['type'], meta?: Record<string, unknown>) => {
		onEventRef.current?.({ type, tableName, at: Date.now(), meta });
	}, [tableName]);
	return emit;
}

/** Emit load:success / load:error once per transition. */
export function useLoadEvents({
	dataError,
	hasCompletedInitialLoad,
	totalCount,
	emit,
}: {
	dataError: Error | null;
	hasCompletedInitialLoad: boolean;
	totalCount: number;
	emit: SheetsEmit;
}): void {
	// Emit load:success / load:error once per transition. Tracked via a ref so we
	// don't re-fire on unrelated re-renders.
	const lastLoadEmitRef = useRef<'success' | 'error' | null>(null);
	useEffect(() => {
		if (dataError) {
			if (lastLoadEmitRef.current !== 'error') {
				lastLoadEmitRef.current = 'error';
				emit('load:error', { error: dataError });
			}
			return;
		}
		if (hasCompletedInitialLoad && lastLoadEmitRef.current !== 'success') {
			lastLoadEmitRef.current = 'success';
			emit('load:success', { totalCount });
		}
	}, [dataError, hasCompletedInitialLoad, totalCount, emit]);
}

/** Emit sort:change / filter:apply / search:change when the applied view state changes. */
export function useViewChangeEvents({
	view,
	effectiveWhere,
	emit,
}: {
	view: SheetsViewBindings;
	effectiveWhere: Readonly<Record<string, unknown>> | undefined;
	emit: SheetsEmit;
}): void {
	// Emit sort:change / filter:apply / search:change when the applied state changes (not on
	// mount). Watching the state rather than the controls covers every path that changes it.
	const sortSignature = JSON.stringify(view.state.sort);
	const appliedWhereSignature = JSON.stringify(effectiveWhere ?? null);
	const appliedSearch = view.state.search.trim();
	const lastViewEventsRef = useRef({ sort: sortSignature, where: appliedWhereSignature, search: appliedSearch });
	useEffect(() => {
		const last = lastViewEventsRef.current;
		if (last.sort !== sortSignature) {
			const [first] = view.state.sort;
			emit('sort:change', { sort: view.state.sort, field: first?.column ?? null, direction: first?.direction ?? null });
		}
		if (last.search !== appliedSearch) emit('search:change', { search: appliedSearch });
		else if (last.where !== appliedWhereSignature) emit('filter:apply', { conditionCount: view.appliedCount });
		lastViewEventsRef.current = { sort: sortSignature, where: appliedWhereSignature, search: appliedSearch };
	}, [sortSignature, appliedWhereSignature, appliedSearch, view.state.sort, view.appliedCount, emit]);
}

// The rows the grid shows: server rows (normalized relations) and the client-side
// draft rows after them; in infinite mode a proxy that reads each server row lazily.
import { useMemo } from 'react';

import type { useInfiniteGridData } from '../hooks/use-infinite-grid-data';
import type { useDataLoading } from '../hooks/use-load-grid';
import { useDraftRows } from '../hooks/use-draft-rows';
import { attachDraftMeta, type SheetsRow } from '../row-model';
import { normalizeServerRow } from '../sheets.utils';

export interface UseSheetsRowsInput {
	tableKey: string;
	infiniteScroll: boolean;
	infiniteGridData: ReturnType<typeof useInfiniteGridData>;
	dataLoadingResult: ReturnType<typeof useDataLoading>;
	serverData: unknown;
	totalCount: number;
	allRelationFields: string[];
	hasCompletedInitialLoad: boolean;
}

export function useSheetsRows({
	tableKey,
	infiniteScroll,
	infiniteGridData,
	dataLoadingResult,
	serverData,
	totalCount,
	allRelationFields,
	hasCompletedInitialLoad,
}: UseSheetsRowsInput) {
	// Get CRUD operations (only available in paginated mode for now)
	const { update, create, delete: deleteRow } = dataLoadingResult.contextValue;

	const relationFieldNames = useMemo(() => new Set(allRelationFields), [allRelationFields]);

	const normalizedServerData = useMemo(() => {
		if (infiniteScroll) return [] as any[]; // Not used in infinite mode
		if (!Array.isArray(serverData) || serverData.length === 0 || relationFieldNames.size === 0) {
			return serverData as any[];
		}
		return (serverData as any[]).map((row) => normalizeServerRow(row, relationFieldNames));
	}, [infiniteScroll, serverData, relationFieldNames]);

	const {
		draftRowsTable,
		draftRows,
		hasDraftRows,
		combinedRows: paginatedCombinedRows,
		draftRowIndices: paginatedDraftRowIndices,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
	} = useDraftRows({
		tableKey,
		serverRows: normalizedServerData as any[],
		hasCompletedInitialLoad,
	});

	const serverRowCount = infiniteScroll ? totalCount : normalizedServerData.length;

	const draftDataRows = useMemo(() => {
		if (!draftRows.length) return [] as SheetsRow[];
		return draftRows.map((draft) => {
			const row = { ...draft.values } as SheetsRow;
			return attachDraftMeta(row, {
				isDraft: true,
				draftRowId: draft.id,
				status: draft.status,
				errors: draft.errors,
			});
		});
	}, [draftRows]);

	// ============== INFINITE SCROLL: Virtual rows array ==============
	// Create a proxy array for infinite scroll mode that uses getRowAtIndex and appends draft rows.
	// It is rebuilt only when a row read can change (a page's data, the count or the drafts), so a
	// render that changes no data keeps the array and everything memoized on it.
	const getRowAtIndex = infiniteGridData.getRowAtIndex;
	const infiniteRowsProxy = useMemo<SheetsRow[]>(() => {
		if (!infiniteScroll) return [];

		// Create an array-like object with a Proxy to intercept index access
		const handler: ProxyHandler<any[]> = {
			get(target, prop) {
				// Handle array methods and properties
				if (prop === 'length') {
					return serverRowCount + draftDataRows.length;
				}
				if (prop === Symbol.iterator) {
					return function* () {
						const len = serverRowCount + draftDataRows.length;
						for (let i = 0; i < len; i++) {
							if (i < serverRowCount) {
								yield getRowAtIndex(i);
							} else {
								yield draftDataRows[i - serverRowCount];
							}
						}
					};
				}
				// Handle numeric indices
				if (typeof prop === 'string' && !isNaN(Number(prop))) {
					const index = Number(prop);
					if (index < serverRowCount) {
						return getRowAtIndex(index);
					}
					return draftDataRows[index - serverRowCount];
				}
				// Delegate to target for other properties
				return Reflect.get(target, prop);
			},
		};

		// Single localized cast: the Proxy intercepts numeric index + length access to
		// surface server rows (via getRowAtIndex) and appended draft rows as SheetsRow,
		// so downstream `combinedRows[i]` reads are SheetsRow with no per-use cast.
		return new Proxy([], handler) as unknown as SheetsRow[];
	}, [infiniteScroll, getRowAtIndex, serverRowCount, draftDataRows]);

	// Choose the appropriate rows array based on mode
	const combinedRows: SheetsRow[] = infiniteScroll ? infiniteRowsProxy : paginatedCombinedRows;

	const draftRowIndices = useMemo(() => {
		if (!draftDataRows.length) return [] as number[];
		if (infiniteScroll) {
			return draftDataRows.map((_, index) => serverRowCount + index);
		}
		return paginatedDraftRowIndices;
	}, [draftDataRows, infiniteScroll, paginatedDraftRowIndices, serverRowCount]);

	return {
		update,
		create,
		deleteRow,
		normalizedServerData,
		draftRowsTable,
		draftRows,
		hasDraftRows,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
		serverRowCount,
		combinedRows,
		draftRowIndices,
	};
}

// Filters, sort and search (the view state) turned into list variables, the columns
// and relations the view shows, saved views, and the page reset on a view change.
import { useEffect, useMemo, useRef } from 'react';

import { modelFieldLabel } from '../../cell-types/field-label';
import type { SheetsConfig, SheetsScopeKey } from '../../context/sheets-context';
import { useTableModel } from '../../hooks/use-table-model';
import type { useGridState } from '../hooks/use-grid-state';
import type { SheetsViewProps } from '../view-state/use-sheets-view';
import { useSheetsView } from '../view-state/use-sheets-view';
import { useSavedViews } from '../views/use-saved-views';
import { defaultViewStorage } from '../views/view-storage';

export interface UseSheetsViewQueryInput {
	tableName: string;
	props: SheetsViewProps;
	config: SheetsConfig;
	scopeKey: SheetsScopeKey;
	infiniteScroll: boolean;
	gridActions: ReturnType<typeof useGridState>['actions'];
}

export function useSheetsViewQuery({ tableName, props, config, scopeKey, infiniteScroll, gridActions }: UseSheetsViewQueryInput) {
	// ============== FILTERS / SORT / SEARCH → LIST VARIABLES ==============
	// The view state is checked against the table model before it builds the list
	// filter and sort, so the model is needed before the data hooks run (it is the
	// same cached query the data hooks read).
	const { model: viewModel } = useTableModel(tableName);
	// Fields are named with the shared readable label everywhere (toolbar, header menu, notices);
	// a relation reads as a relation (the related records and what links them).
	const columnLabel = useMemo(() => modelFieldLabel(viewModel), [viewModel]);
	const {
		view,
		where: effectiveWhere,
		orderBy: orderByClause,
		querySignature: viewSignature,
	} = useSheetsView({
		model: viewModel,
		columnLabel,
		filters: props.filters,
		onFiltersChange: props.onFiltersChange,
		sort: props.sort,
		onSortChange: props.onSortChange,
		search: props.search,
		onSearchChange: props.onSearchChange,
		columns: props.columns,
		onColumnsChange: props.onColumnsChange,
	});

	const viewQuery = useMemo(() => ({ where: effectiveWhere, orderBy: orderByClause }), [effectiveWhere, orderByClause]);

	// Only the columns the view shows are fetched (the data layer adds keys and relation keys).
	const fetchColumns = useMemo(() => {
		if (!viewModel) return undefined;
		const scalar = new Set(viewModel.columns.map((column) => column.name));
		return view.layout.visibleKeys.filter((key) => scalar.has(key));
	}, [viewModel, view.layout.visibleKeys]);
	// Likewise only the relations the view shows.
	const fetchRelations = useMemo(() => {
		if (!viewModel) return undefined;
		const relations = new Set(viewModel.relations.map((relation) => relation.fieldName));
		return view.layout.visibleKeys.filter((key) => relations.has(key));
	}, [viewModel, view.layout.visibleKeys]);

	// Saved views of this table, kept in the host's storage or this browser's.
	const viewStorage = useMemo(() => config.views ?? defaultViewStorage(), [config.views]);
	const viewScope = useMemo(
		() => (viewModel ? { ...scopeKey, tableKey: viewModel.key } : null),
		[scopeKey, viewModel],
	);
	const savedViews = useSavedViews({
		storage: viewStorage,
		scope: viewScope,
		model: viewModel,
		current: view.state,
		apply: view.applyState,
		label: columnLabel,
	});

	// Reset to page 0 when the filter, sort or search changes (paginated mode)
	const prevViewSignatureRef = useRef(viewSignature);
	useEffect(() => {
		if (prevViewSignatureRef.current !== viewSignature) {
			prevViewSignatureRef.current = viewSignature;
			if (!infiniteScroll) {
				gridActions.setPageIndex(0);
			}
		}
	}, [viewSignature, infiniteScroll, gridActions]);

	return {
		columnLabel,
		view,
		effectiveWhere,
		orderByClause,
		viewSignature,
		viewQuery,
		fetchColumns,
		fetchRelations,
		savedViews,
	};
}

// Every write the grid makes to saved rows and drafts: the batched cell commit (paste,
// fill, bulk and the single cell, undoable), patches from self-committing editors, deletes,
// optimistic infinite-cache patches, and the error cards a refused write leaves.
import { useCallback, useMemo } from 'react';

import type { MetaField, TableModel } from '@constructive-io/data';

import type { SheetsConfig } from '../../context/sheets-context';
import type { SheetsCellResolution } from '../../grid-dom/use-sheets-content';
import type { SheetsRowIdentifier } from '../../row-identity';
import type { RelationInfo } from '../../store/relation-info-slice';
import { sheetsLogger } from '../../utils/sheets-logger';
import { recordLabel, writeErrorMessages, type WriteAction } from '../feedback';
import type { useFeedback } from '../feedback';
import { useBatchCommit } from '../hooks/use-batch-commit';
import { useCellEditing } from '../hooks/use-cell-editing';
import type { useDraftRows } from '../hooks/use-draft-rows';
import { useGridOperations } from '../hooks/use-grid-operations';
import type { useGridState } from '../hooks/use-grid-state';
import type { useInfiniteGridData } from '../hooks/use-infinite-grid-data';
import type { useDataLoading } from '../hooks/use-load-grid';
import { useUndoRedo } from '../hooks/use-undo-redo';
import { getDraftMeta, type SheetsRow } from '../row-model';
import type { DataGridProps } from '../sheets.types';
import type { SheetsEmit } from './use-sheets-events';

type DataContext = ReturnType<typeof useDataLoading>['contextValue'];

export interface UseSheetsWritesInput {
	tableName: string;
	tableKey: string;
	config: SheetsConfig;
	feedback: ReturnType<typeof useFeedback>;
	emit: SheetsEmit;
	infiniteScroll: boolean;
	infiniteGridData: ReturnType<typeof useInfiniteGridData>;
	tableModel: TableModel | null;
	combinedRows: SheetsRow[];
	fieldMetaMap: Map<string, MetaField>;
	relationInfoByField: Map<string, RelationInfo>;
	getSheetsCellContent: (rowIndex: number, colKey: string) => SheetsCellResolution;
	getRowIdentifier: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	primaryKeyFields: ReadonlySet<string>;
	canUpdate: boolean;
	canDelete: boolean;
	update: DataContext['update'];
	deleteRow: DataContext['delete'];
	updateDraftCell: ReturnType<typeof useDraftRows>['updateDraftCell'];
	removeDraftRow: ReturnType<typeof useDraftRows>['removeDraftRow'];
	gridState: ReturnType<typeof useGridState>['state'];
	gridActions: ReturnType<typeof useGridState>['actions'];
	columnLabel: (name: string) => string;
	onCellEdit: DataGridProps['onCellEdit'];
}

export function useSheetsWrites({
	tableName,
	tableKey,
	config,
	feedback,
	emit,
	infiniteScroll,
	infiniteGridData,
	tableModel,
	combinedRows,
	fieldMetaMap,
	relationInfoByField,
	getSheetsCellContent,
	getRowIdentifier,
	primaryKeyFields,
	canUpdate,
	canDelete,
	update,
	deleteRow,
	updateDraftCell,
	removeDraftRow,
	gridState,
	gridActions,
	columnLabel,
	onCellEdit,
}: UseSheetsWritesInput) {
	const { startOperation, updateOperationProgress, completeOperation, reportWriteError } = feedback;

	/**
	 * Unified optimistic update handler for overlay editors. Editors that handle
	 * mutations internally (RelationEditor, ImageEditor, etc.) call this callback with
	 * a patch to update the grid cache without full refetch. The DOM grid re-renders
	 * reactively off `combinedRows`, so no surgical per-cell repaint is needed.
	 */
	const handleEditorSaveComplete = useCallback(
		(colKey: string, rowIndex: number, patch: Record<string, unknown>) => {
			void colKey;
			const rowData = combinedRows[rowIndex];

			// Draft row: update draft store directly
			const dm = getDraftMeta(rowData);
			if (dm) {
				for (const [key, value] of Object.entries(patch)) {
					updateDraftCell({ tableKey, draftRowId: dm.draftRowId, columnKey: key, value });
				}
				return;
			}

			// Server row: update infinite scroll cache (paginated handled by React Query)
			if (!infiniteScroll) return;

			// Apply optimistic update to infinite scroll cache; self-heal on a cache
			// miss (patch targeted a not-yet-cached page) by falling back to a refetch.
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, patch);
			if (!ok) infiniteGridData.invalidate();
		},
		[combinedRows, infiniteScroll, infiniteGridData, updateDraftCell, tableKey],
	);

	// Memoize feedback callbacks for grid operations
	const operationFeedback = useMemo(
		() => ({
			onStart: startOperation,
			onProgress: updateOperationProgress,
			onComplete: completeOperation,
		}),
		[startOperation, updateOperationProgress, completeOperation],
	);

	const gridOpsOptions = useMemo(
		() => ({
			onRemoveDraftRow: (draftRowId: string) => removeDraftRow(tableKey, draftRowId),
			getRowIdentifier,
			canDeleteServerRows: canDelete,
			feedback: operationFeedback,
			onDeleteErrors: (errors: readonly unknown[]) => {
				const messages = [...new Set(errors.flatMap((error) => writeErrorMessages(error, 'delete')))];
				reportWriteError(`${errors.length} ${errors.length === 1 ? 'row was' : 'rows were'} not deleted`, messages);
				for (const error of errors) config.onError?.(error, { source: 'mutation', tableName });
			},
		}),
		[removeDraftRow, tableKey, getRowIdentifier, canDelete, operationFeedback, reportWriteError, config, tableName],
	);

	const { deleteRows: baseDeleteRows } = useGridOperations(
		combinedRows,
		deleteRow,
		gridState.gridSelection,
		() => gridActions.setGridSelection(undefined),
		{
			...gridOpsOptions,
			onAfterServerDeletes: infiniteScroll ? infiniteGridData.invalidate : undefined,
		},
	);

	// Wrap the delete handler to emit an observational row:delete event with the
	// row count, then delegate to the real deletion logic.
	const deleteRows = useCallback(
		async (rows: readonly number[]) => {
			emit('row:delete', { count: rows.length });
			await baseDeleteRows(rows);
		},
		[baseDeleteRows, emit],
	);
	const deleteSelected = useCallback(
		() => deleteRows(gridState.gridSelection?.rows.toArray() ?? []),
		[deleteRows, gridState.gridSelection],
	);

	// Infinite-mode optimistic cache patch, handed to `useCellEditing` so a server-row
	// edit flips the cell BEFORE the `update` round-trip. Snapshots the prior values for
	// the patched keys and returns a revert thunk replayed only if the mutation rejects.
	// A cache miss (unloaded page) self-heals via `invalidate()`. Paginated mode returns
	// undefined here — its optimism lives in the update mutation's onMutate (use-table.ts).
	const applyOptimisticCellPatch = useCallback(
		(rowIndex: number, patch: Record<string, unknown>): (() => void) | void => {
			if (!infiniteScroll) return;
			const current = infiniteGridData.getRowAtIndex(rowIndex) as Record<string, unknown> | null;
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, patch);
			if (!ok) {
				infiniteGridData.invalidate();
				return;
			}
			const snapshot: Record<string, unknown> = {};
			for (const key of Object.keys(patch)) snapshot[key] = current ? current[key] : undefined;
			return () => {
				const reverted = infiniteGridData.updateRowAtIndex(rowIndex, snapshot);
				if (!reverted) infiniteGridData.invalidate();
			};
		},
		[infiniteScroll, infiniteGridData],
	);

	const editCell = useCellEditing({
		combinedRows,
		fieldMetaMap,
		relationInfoByField,
		updateDraftCell,
		tableKey,
		update,
		getRowIdentifier,
		readOnlyFields: primaryKeyFields,
		canUpdate,
		onCellEdit,
		applyOptimisticPatch: applyOptimisticCellPatch,
	});

	// History (undo/redo) for server-row value writes. Draft edits are NOT recorded.
	const history = useUndoRedo();

	// Re-sync a canonical server row over the optimistic patch after the mutation
	// resolves (infinite mode only; paginated reconciles via React Query).
	const resyncRow = useCallback(
		(rowIndex: number, updatedRow: Record<string, unknown>) => {
			if (!infiniteScroll) return;
			const ok = infiniteGridData.updateRowAtIndex(rowIndex, updatedRow);
			if (!ok) infiniteGridData.invalidate();
		},
		[infiniteScroll, infiniteGridData],
	);

	// BATCHED commit primitive — the single server-row value-write path (paste / fill /
	// bulk AND, routed below, the single cell). Coalesces optimistic patches + server
	// mutations per row and records an undoable HistoryEntry (unless opts.record===false).
	// A refused write lists every message the server returned, titled by the cell or row
	// when the write names one. It stays until dismissed.
	const reportServerWrite = useCallback(
		(error: unknown, action: WriteAction, title: string) => {
			reportWriteError(title, writeErrorMessages(error, action));
			config.onError?.(error, { source: 'mutation', tableName });
		},
		[reportWriteError, config, tableName],
	);
	const handleWriteFailure = useCallback(
		(error: unknown, cellCount: number, target?: { rowIndex: number; fields: readonly string[] }) => {
			let title = cellCount > 1 ? `${cellCount} changes were not saved` : 'The change was not saved';
			if (target) {
				const record = recordLabel(tableModel, combinedRows[target.rowIndex], target.rowIndex);
				title =
					target.fields.length === 1
						? `${columnLabel(target.fields[0]!)} was not saved for ${record}`
						: `${target.fields.length} changes were not saved for ${record}`;
			}
			reportServerWrite(error, 'update', title);
		},
		[reportServerWrite, tableModel, combinedRows, columnLabel],
	);
	const commitCells = useBatchCommit({
		combinedRows,
		fieldMetaMap,
		relationInfoByField,
		update,
		getRowIdentifier,
		readOnlyFields: primaryKeyFields,
		resolveCell: getSheetsCellContent,
		tableModel,
		onServerError: handleWriteFailure,
		canUpdate,
		applyOptimisticPatch: applyOptimisticCellPatch,
		resyncRow,
		editCell,
		onCellEdit,
		record: history.record,
		feedback: operationFeedback,
	});

	// @internal NATIVE value-commit for the TanStack DOM grid's portal editors.
	// Maps a (rowIndex, colKey, rawValue) commit straight onto the native `editCell`
	// (draft `updateDraftCell` / server mutation) — the raw value flows through with
	// NO glide cell round-trip (this is what keeps a boolean `false` as `false`). For
	// server edits `editCell` already applied the OPTIMISTIC infinite-cache patch before
	// awaiting the mutation (and reverted it on failure); here we only re-sync the
	// canonical server row when it comes back, then emit the observational `cell:edit`.
	// The DOM grid re-renders reactively from `combinedRows`.
	const commitCellValue = useCallback(
		(rowIndex: number, colKey: string, nextValue: unknown): void => {
			void (async () => {
				try {
					// Single-cell edits route through the SAME batched primitive so a normal cell
					// edit becomes undoable (server rows) — coercion / readonly / optimistic patch
					// / re-sync all live inside commitCells (draft rows take its per-cell branch).
					const isDraft = !!getDraftMeta(combinedRows[rowIndex]);
					// An editor hands over a value, not text to parse (a JSON string stays a string).
					const { applied } = await commitCells([{ rowIndex, colKey, value: nextValue, fromText: false }]);

					// Observational: a real cell edit landed — skip no-ops (applied 0 + non-draft).
					if (applied > 0 || isDraft) {
						emit('cell:edit', { field: colKey, rowIndex, target: isDraft ? 'draft' : 'server' });
					}
				} catch (e) {
					// A failure the commit did not report itself: it gets an error card like any refused save.
					reportWriteError('The change was not saved', writeErrorMessages(e, 'update'));
					sheetsLogger().error('Cell edit error:', e);
					config.onError?.(e, { source: 'mutation', tableName });
				}
			})();
		},
		[commitCells, combinedRows, config, tableName, emit, reportWriteError],
	);

	// @internal NATIVE patch-commit for self-committing DOM portal editors (relation/
	// image). These editors mutate server-side themselves, then push a MULTI-field
	// patch — routes straight through the EXISTING `handleEditorSaveComplete` (draft
	// store update / infinite-cache patch), using the FIRST patch key as the primary colKey.
	const commitCellPatch = useCallback(
		(rowIndex: number, patch: Record<string, unknown>): void => {
			const primaryColKey = Object.keys(patch)[0];
			if (!primaryColKey) return;
			handleEditorSaveComplete(primaryColKey, rowIndex, patch);
		},
		[handleEditorSaveComplete],
	);

	// @internal NATIVE data-invalidate for self-committing DOM portal editors. Mirrors
	// the canvas wiring: infinite mode refetches via the React Query cache; paginated
	// invalidation is already handled by React Query in use-table, so this is a no-op there.
	const invalidateData = useCallback(() => {
		if (infiniteScroll) infiniteGridData.invalidate();
	}, [infiniteScroll, infiniteGridData]);

	return { operationFeedback, deleteRows, deleteSelected, commitCells, commitCellValue, commitCellPatch, invalidateData, history };
}

// The public and internal result types of `useSheets` (re-exported from `../use-sheets`).
