/** Draft-row bindings for a headless shell. */
export interface SheetsDraftBindings {
	/** Whether any client-side draft rows exist. */
	hasDrafts: boolean;
	/** Append a new draft row. Returns the new row index. */
	appendRow: () => Promise<number | undefined>;
	/** Submit all pending draft rows. */
	submitDrafts: () => Promise<void>;
	/** Delete the currently selected rows (draft + server). */
	deleteSelected: () => Promise<void>;
	/** Delete these rows by index: a saved row is deleted, a new row is discarded. */
	deleteRows: (rows: readonly number[]) => Promise<void>;
}

/**
 * Selection bindings for a headless shell.
 *
 * The selection value is the native {@link SheetsSelection} (RangeSet-backed `rows`).
 */
export interface SheetsSelectionBindings {
	/** Current native grid selection. */
	gridSelection: SheetsSelection | undefined;
	/** Setter. */
	setGridSelection: (selection: SheetsSelection | undefined) => void;
	/** Park the active cell on `[col, row]` (preserves row/column selection). */
	setActiveCell: (col: number, row: number) => void;
	/** Move the active cell by `[dCol, dRow]`, clamped to grid bounds. */
	moveActive: (dCol: number, dRow: number, colCount: number, rowCount: number) => void;
}

/** Pagination bindings for a headless shell (paginated mode). */
export interface SheetsPaginationBindings {
	/** Current zero-based page index. */
	pageIndex: number;
	/** Total page count (>= 1). */
	pageCount: number;
	/** Set the page index (emits a `page:change` event). */
	setPageIndex: (updater: number | ((prev: number) => number)) => void;
}

/**
 * Stable headless surface returned by {@link useSheets}. (The hook also returns a
 * few `_shell`-grouped extras consumed only by the built-in {@link Sheets} chrome —
 * those are not part of this supported contract.)
 */
export interface UseSheetsResult {
	/** Native column descriptors (key/title/width). */
	columns: RelationGridColumn[];
	/** Number of rows to render. */
	rowCount: number;
	/** Draft-row bindings. */
	draft: SheetsDraftBindings;
	/** Selection bindings. */
	selection: SheetsSelectionBindings;
	/** Pagination bindings. */
	pagination: SheetsPaginationBindings;
	/** True only during the very first load (refetches keep previous data). */
	isInitialLoading: boolean;
	/** Data-load error, if any. */
	dataError: Error | null;
	/** Whether the initial load has completed (success). */
	hasCompletedInitialLoad: boolean;
	/** True when loaded, no server rows, no drafts, and no active filter. */
	isEmpty: boolean;
	/** Refetch the underlying data (mode-aware: infinite vs paginated). */
	refetch: () => void;
	/** Read the table's shape (`_meta`) and its rows again. */
	refreshFromServer: () => void;
}

/**
 * Internal bindings consumed only by the built-in {@link Sheets} chrome
 * (toolbar, dock, pagination chrome). NOT a supported part of the headless contract.
 */
export interface SheetsShellBindings {
	combinedRows: SheetsRow[];
	columnKeys: string[];
	totalCount: number;
	serverRowCount: number;
	draftRowCount: number;
	infiniteScroll: boolean;
	/** @internal Filter, sort and search state and actions (toolbar, header, view commands). NOT a stable API. */
	view: SheetsViewBindings;
	/** @internal Saved views of the table (switcher, save, discard). NOT a stable API. */
	savedViews: SavedViewsBindings;
	/** Number of filter conditions in the state, applied or not. */
	filterConditionCount: number;
	/** The list filter and sort of the view, as the data hooks get them (full-result export). */
	viewQuery: { where: Readonly<Record<string, unknown>> | undefined; orderBy: readonly SortSpec[] | undefined };
	/** True while rows for the current filter, sort or search are being fetched (the previous rows may still show). */
	isFetchingRows: boolean;
	setGridSelectionForControls: (selection: SheetsSelection | null) => void;
	/** Prefetch the rows in an inclusive visible window (native range, infinite mode). */
	onVisibleRegionChanged: (range: VisibleRowRange) => void;
	/** Changes exactly when sort, filters or search change the rows (selection resets on it). */
	viewSignature: string;
	/** @internal Committed column widths (id → px) — the DOM grid maps these to v9 columnSizing. NOT a stable API. */
	columnWidths: ReturnType<typeof useGridState>['state']['columnWidths'];
	/** @internal Commit a column width (id, px) — the DOM resize handle drives this directly. NOT a stable API. */
	resizeColumn: ReturnType<typeof useGridState>['actions']['resizeColumn'];
	/** Leading columns that stay in place under horizontal scroll (the view's layout). */
	frozenCount: number;
	/** Row height in pixels (the view's layout). */
	rowHeightPx: number;
	selectedRowCount: number;
	canCreate: boolean;
	canUpdate: boolean;
	canDelete: boolean;
	/** Human-readable reason shown when the table model proves rows cannot be changed. */
	readOnlyReason: string | null;
	/** @internal The table model (kinds, options, write flags, relations, sort and filter names), or null while it loads. NOT a stable API. */
	tableModel: TableModel | null;
	/** Stable identity for selection, TanStack rows, and editor instances. */
	getRowId: (row: SheetsRow | null | undefined, index: number) => string;
	isSubmittingDrafts: boolean;
	submitDraftButtonDisabled: boolean;
	submitDraftLabel: string;
	/** @internal Native DOM content resolver for the TanStack DOM grid. NOT a stable API. */
	getSheetsCellContent: (rowIndex: number, colKey: string) => SheetsCellResolution;
	/** @internal Per-instance cell-type registry (consumer overrides over built-ins). NOT a stable API. */
	cellRegistry: CellTypeRegistry;
	/** @internal Native value-commit for the TanStack DOM portal editors. NOT a stable API. */
	commitCellValue: (rowIndex: number, colKey: string, nextValue: unknown) => void;
	/** @internal Batched server-row value commit (paste/fill/bulk + the single cell). NOT a stable API. */
	commitCells: (writes: CellWrite[], opts?: CommitCellsOptions) => Promise<CommitCellsResult>;
	/** @internal Native MULTI-field patch-commit for self-committing DOM portal editors (relation/image). NOT a stable API. */
	commitCellPatch: (rowIndex: number, patch: Record<string, unknown>) => void;
	/** @internal Submit a client-side draft row for a self-committing DOM portal editor. NOT a stable API. */
	submitDraftRow: (draftRowId: string) => Promise<DraftSubmitResult>;
	/** @internal Invalidate cached grid data after a self-committing DOM portal editor mutates out-of-band. NOT a stable API. */
	invalidateData: () => void;
	/** @internal Undo the last recorded server-row value write. NOT a stable API. */
	undo: () => Promise<void>;
	/** @internal Redo the last undone server-row value write. NOT a stable API. */
	redo: () => Promise<void>;
	/** @internal Whether an undo is available. NOT a stable API. */
	canUndo: boolean;
	/** @internal Whether a redo is available. NOT a stable API. */
	canRedo: boolean;
	/** @internal Add a step to the undo history (a link editor's saved change). NOT a stable API. */
	recordHistory: (entry: HistoryEntry) => void;
	/** @internal Observational event emitter (analytics/telemetry) — threaded into the command context. NOT a stable API. */
	emit: (type: SheetsEvent['type'], meta?: Record<string, unknown>) => void;
}

export type UseSheetsInternalResult<TRow extends SheetsRow = SheetsRow> = UseSheetsResult & {
	/** @internal Bindings for the built-in <Sheets> chrome — not a stable API. */
	_shell: SheetsShellBindings;
};

// What a copied cell puts on the clipboard: a column's value in the grid's copy format, a link
// cell's record labels (never the record's JSON).
import type { TableModel } from '@constructive-io/data';

import { copyText } from '../cell-types/column-value';
import { relationCopyText } from '../relations/relation-label';

export function cellCopyText(model: Pick<TableModel, 'columns' | 'relations'> | null | undefined, colKey: string, value: unknown): string {
	const relation = model?.relations.find((candidate) => candidate.fieldName === colKey);
	return relation ? relationCopyText(relation, value) : copyText(model?.columns, colKey, value);
}

import type { ColumnModel, MetaQuery, RelationModel, TableModel } from '@constructive-io/data';

import { NON_EDITABLE_TYPES } from '../cell-types/cell-type-groups';
import { resolveCellType, type FieldMetadata } from '../cell-types/cell-type-resolver';
import { cellTypeForColumn } from '../cell-types/column-routing';
import { VIEW_ONLY_REASON } from '../cell-types/column-value';
import type { RelationInfo } from '../store/relation-info-slice';

/** Shown on a cell whose value the server could not send. */
export const CELL_READ_ERROR_TEXT = 'This value cannot be shown';
const CELL_READ_ERROR_REASON = 'The server could not send this value, so it cannot be shown or changed here.';
const KEY_LOCKED_REASON = 'This field identifies the record, so it cannot be changed here.';
const UNDESCRIBED_PARTS_REASON = 'The parts of this value are not known, so it cannot be changed here.';

/** Cell types whose editor builds the value from the fields of the column's write input. */
const FIELD_BUILT_TYPES: ReadonlySet<string> = new Set(['composite', 'point', 'range', 'interval']);

export interface ModelCellRouteInput {
	column: ColumnModel;
	table: TableModel;
	/** The row is a draft that has not been created yet. */
	isDraftRow: boolean;
	/** The list read could not serve this cell's value. */
	cellError: string | null;
	/** Host override of the cell type (`SheetsConfig.fieldTypeOverrides`). */
	typeOverride?: string | null;
	/** Fields of saved rows that stay fixed because they identify the row. */
	lockedFields?: ReadonlySet<string>;
}

export interface ModelCellRoute {
	cellType: string;
	/** Why the cell cannot be written, or null when it can. Safe to show to the user. */
	readOnlyReason: string | null;
}

function operationIssue(table: TableModel, operation: 'create' | 'update'): string | null {
	return table.issues.find((issue) => issue.scope === 'operation' && issue.target === operation)?.message ?? null;
}

/** Why a cell of this column cannot be written in this row, from the table model only. */
function modelReadOnlyReason(input: ModelCellRouteInput, cellType: string): string | null {
	const { column, table, isDraftRow, cellError, lockedFields } = input;
	if (cellError) return CELL_READ_ERROR_REASON;
	if (!column.readable) return column.readReason ?? 'This field cannot be read.';
	if (NON_EDITABLE_TYPES.has(cellType)) return VIEW_ONLY_REASON;
	if (FIELD_BUILT_TYPES.has(cellType) && column.value.input && !column.value.input.fields?.length) {
		return UNDESCRIBED_PARTS_REASON;
	}
	if (isDraftRow) {
		if (!table.operations.create) return operationIssue(table, 'create') ?? 'New records cannot be added to this table.';
		return column.write.create ? null : column.write.createReason ?? 'This field cannot be set on a new record.';
	}
	if (!table.operations.update) return operationIssue(table, 'update') ?? 'Records in this table cannot be changed.';
	if (lockedFields?.has(column.name)) return KEY_LOCKED_REASON;
	return column.write.update ? null : column.write.updateReason ?? 'This field cannot be changed.';
}

/**
 * Why a relation cell cannot change its links, or null when the relation editor may
 * (it decides the details per link). A belongsTo writes this table's row, so it also
 * needs the row's create (draft) or update operation; the other kinds write the
 * related or junction table, which the relation editor checks.
 */
export function relationCellReadOnlyReason(relation: RelationModel, table: TableModel | null, isDraftRow: boolean): string | null {
	if (!relation.readable || !relation.editable) return relation.reason ?? 'These links cannot be changed here.';
	if (relation.kind !== 'belongsTo' || !table) return null;
	if (isDraftRow) return table.operations.create ? null : operationIssue(table, 'create') ?? 'New records cannot be added to this table.';
	return table.operations.update ? null : operationIssue(table, 'update') ?? 'Records in this table cannot be changed.';
}

/**
 * Route one column cell from the table model: its cell type and, when it cannot be
 * written in this row, the reason. A host type override changes the cell type only;
 * it never makes a read-only column writable.
 */
export function resolveModelCellRoute(input: ModelCellRouteInput): ModelCellRoute {
	const cellType = input.typeOverride || cellTypeForColumn(input.column);
	return { cellType, readOnlyReason: modelReadOnlyReason(input, cellType) };
}

type MetaTable = NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number];

export interface GridCellRouteInput {
	colKey: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	isRelationFallback?: boolean;
	isCustomGeometryCell?: boolean;
	isDraftIdCell?: boolean;
	hasForeignKeyField?: boolean;
}

export interface GridCellRoute {
	cellType: string;
	baseCellType: string;
	isRelation: boolean;
	canEdit: boolean;
	canActivate: boolean;
	isReadonly: boolean;
	activationBehavior: 'single-click' | 'double-click';
}

export function buildRelationFieldNameSet(meta: MetaQuery | undefined, tableName?: string): Set<string> {
	if (!tableName) return new Set<string>();

	const table = meta?._meta?.tables?.find((entry): entry is MetaTable => Boolean(entry && entry.name === tableName));
	if (!table?.relations) return new Set<string>();

	const out = new Set<string>();
	const push = (fieldName?: string | null) => {
		if (fieldName) out.add(fieldName);
	};

	table.relations.belongsTo?.forEach((relation) => {
		push(relation?.fieldName);
		relation?.keys?.forEach((key) => push(key?.name));
	});
	table.relations.hasOne?.forEach((relation) => push(relation?.fieldName));
	table.relations.hasMany?.forEach((relation) => push(relation?.fieldName));
	table.relations.manyToMany?.forEach((relation) => push(relation?.fieldName));

	return out;
}

export function resolveGridCellRoute({
	colKey,
	fieldMeta,
	relationInfo,
	isRelationFallback = false,
	isCustomGeometryCell = false,
	isDraftIdCell = false,
	hasForeignKeyField = false,
}: GridCellRouteInput): GridCellRoute {
	const base = resolveCellType(colKey, fieldMeta);
	const isRelation = Boolean(relationInfo) || isRelationFallback;
	const canEditRelationInline = Boolean(
		relationInfo && relationInfo.kind === 'belongsTo' && relationInfo.foreignKeyField && hasForeignKeyField,
	);

	const canEdit = isDraftIdCell ? false : isRelation ? canEditRelationInline : base.canEdit;
	const canActivate = isDraftIdCell ? false : isRelation ? true : base.canActivate;
	const isReadonly = isDraftIdCell ? true : isRelation ? !canEditRelationInline : base.isReadonly;

	let cellType = isRelation ? 'relation' : base.cellType;
	if (!isRelation && isCustomGeometryCell) {
		cellType = 'geometry';
	}

	return {
		cellType,
		baseCellType: base.cellType,
		isRelation,
		canEdit,
		canActivate,
		isReadonly,
		activationBehavior: base.activationBehavior,
	};
}

/**
 * The menu in a column header: sort, filter by the field, move, freeze, hide.
 * Every item runs a named command for this column, so it is interceptable and
 * has the same keyboard equivalents; an item whose command cannot run is
 * disabled and says why.
 */
import { Fragment } from 'react';
import {
	RiArrowDownSLine,
	RiArrowLeftLine,
	RiArrowRightLine,
	RiEyeOffLine,
	RiFilterLine,
	RiPushpinLine,
	RiSortAsc,
	RiSortDesc,
	RiUnpinLine,
} from '@remixicon/react';

import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuShortcut,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

import { cn } from '../../utils/cn';
import { INSTANT_POPUP } from '../popup-classes';
import type { ColumnCommandPayload } from '../../commands/registry';
import { viewCommandReason } from '../view-state/view-command-target';
import type { SheetsViewBindings } from '../view-state/use-sheets-view';

export interface ColumnHeaderMenuProps {
	colKey: string;
	view: SheetsViewBindings;
	/** Run a command with this column as its payload. */
	run: (commandId: string, payload: ColumnCommandPayload) => void;
	/** Whether a command can run with this column as its payload. */
	canRun: (commandId: string, payload: ColumnCommandPayload) => boolean;
}

interface Item {
	commandId: string;
	label: string;
	icon: React.ReactNode;
	shortcut?: string;
}

const icon = (Icon: typeof RiSortAsc) => <Icon className='size-4' aria-hidden='true' />;

export function ColumnHeaderMenu({ colKey, view, run, canRun }: ColumnHeaderMenuProps) {
	const { layout } = view;
	const label = view.columnLabel(colKey);
	const open = layout.menuColumn === colKey;
	const frozen = layout.visibleKeys.indexOf(colKey) < layout.frozenCount;
	const payload: ColumnCommandPayload = { colKey };

	const groups: Item[][] = [
		[
			{ commandId: 'view.sortAscending', label: 'Sort ascending', icon: icon(RiSortAsc) },
			{ commandId: 'view.sortDescending', label: 'Sort descending', icon: icon(RiSortDesc) },
			{ commandId: 'view.filterByColumn', label: 'Filter by this field', icon: icon(RiFilterLine) },
		],
		[
			{ commandId: 'column.moveLeft', label: 'Move left', icon: icon(RiArrowLeftLine), shortcut: '⌥⇧←' },
			{ commandId: 'column.moveRight', label: 'Move right', icon: icon(RiArrowRightLine), shortcut: '⌥⇧→' },
			frozen
				? { commandId: 'column.unfreeze', label: 'Unfreeze fields', icon: icon(RiUnpinLine) }
				: { commandId: 'column.freezeUpTo', label: 'Freeze up to this field', icon: icon(RiPushpinLine) },
			{ commandId: 'column.hide', label: 'Hide field', icon: icon(RiEyeOffLine) },
		],
	];

	return (
		<DropdownMenu open={open} onOpenChange={(next) => layout.setMenuColumn(next ? colKey : null)}>
			<DropdownMenuTrigger
				aria-label={`Field options for ${label}`}
				data-part-id='sheets-header-menu-trigger'
				className={cn(
					'text-muted-foreground hover:text-foreground hover:bg-muted rounded p-0.5 focus-visible:opacity-100',
					!open && 'opacity-0 group-hover:opacity-100',
				)}
			>
				<RiArrowDownSLine className='size-3.5' aria-hidden='true' />
			</DropdownMenuTrigger>
			<DropdownMenuContent align='end' aria-label={`Options for ${label}`} className={INSTANT_POPUP}>
				{groups.map((group, index) => (
					<Fragment key={index}>
						{index > 0 && <DropdownMenuSeparator />}
						{group.map((item) => {
							const enabled = canRun(item.commandId, payload);
							const reason = enabled ? null : viewCommandReason(view, item.commandId, colKey);
							return (
								<DropdownMenuItem
									key={item.commandId}
									disabled={!enabled}
									title={reason ?? undefined}
									onClick={() => {
										layout.setMenuColumn(null);
										run(item.commandId, payload);
									}}
								>
									{item.icon}
									{item.label}
									{item.shortcut && <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>}
								</DropdownMenuItem>
							);
						})}
					</Fragment>
				))}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

/**
 * Column layout: pure helpers over `SheetsColumnLayout`.
 *
 * `available` is always the table's grid column keys in the table's order
 * (`gridColumnKeys(model)`). A layout names keys by field name, so it survives
 * a schema change: keys it names that the table lost are ignored here (and
 * reported by the validator), keys the table gained follow at the end.
 */
import type { ColumnValueKind, TableModel } from '@constructive-io/data';

import type { SheetsColumnLayout, SheetsRowHeight } from '../view-state/view-state.types';

/** Row height of each setting, in pixels. */
export const ROW_HEIGHT_PX: Readonly<Record<SheetsRowHeight, number>> = {
	short: 32,
	medium: 44,
	tall: 64,
	extraTall: 96,
};

export const ROW_HEIGHT_LABELS: Readonly<Record<SheetsRowHeight, string>> = {
	short: 'Short',
	medium: 'Medium',
	tall: 'Tall',
	extraTall: 'Extra tall',
};

export const ROW_HEIGHTS = Object.keys(ROW_HEIGHT_PX) as SheetsRowHeight[];

/** Narrowest and widest a column can be dragged or stored. */
export const MIN_COLUMN_WIDTH = 40;
export const MAX_COLUMN_WIDTH = 2000;

/** The layout with every column shown in the table's order and the first column frozen. */
export function createColumnLayout(): SheetsColumnLayout {
	return { order: [], hidden: [], frozenCount: 1, widths: {}, rowHeight: 'medium' };
}

/** Every available key in display order: the layout's order first, then the rest in the table's order. */
export function orderedColumnKeys(available: readonly string[], layout: SheetsColumnLayout): string[] {
	const known = new Set(available);
	const named = layout.order.filter((key) => known.has(key));
	const placed = new Set(named);
	return [...named, ...available.filter((key) => !placed.has(key))];
}

/** The keys that show, in display order. */
export function visibleColumnKeys(available: readonly string[], layout: SheetsColumnLayout): string[] {
	const hidden = new Set(layout.hidden);
	return orderedColumnKeys(available, layout).filter((key) => !hidden.has(key));
}

/** How many leading visible columns stay in place, within the visible count. */
export function effectiveFrozenCount(available: readonly string[], layout: SheetsColumnLayout): number {
	return Math.max(0, Math.min(layout.frozenCount, visibleColumnKeys(available, layout).length));
}

/** The layout with `key` shown or hidden. */
export function setColumnHidden(layout: SheetsColumnLayout, key: string, hidden: boolean): SheetsColumnLayout {
	const rest = layout.hidden.filter((entry) => entry !== key);
	return { ...layout, hidden: hidden ? [...rest, key] : rest };
}

/** Show every column. */
export function showAllColumns(layout: SheetsColumnLayout): SheetsColumnLayout {
	return { ...layout, hidden: [] };
}

/** Hide every column but the first one in display order (at least one column always shows). */
export function hideAllColumns(available: readonly string[], layout: SheetsColumnLayout): SheetsColumnLayout {
	const [first, ...rest] = orderedColumnKeys(available, layout);
	return first === undefined ? layout : { ...layout, hidden: rest };
}

/** The layout with `key` moved to `index` of the full display order. */
export function moveColumnTo(
	available: readonly string[],
	layout: SheetsColumnLayout,
	key: string,
	index: number,
): SheetsColumnLayout {
	const order = orderedColumnKeys(available, layout);
	const from = order.indexOf(key);
	if (from === -1) return layout;
	order.splice(from, 1);
	order.splice(Math.max(0, Math.min(index, order.length)), 0, key);
	return { ...layout, order };
}

/** The layout with `key` placed just before or after `target` (header drag, Fields drag). */
export function moveColumnBeside(
	available: readonly string[],
	layout: SheetsColumnLayout,
	key: string,
	target: string,
	side: 'before' | 'after',
): SheetsColumnLayout {
	if (key === target) return layout;
	const without = orderedColumnKeys(available, layout).filter((entry) => entry !== key);
	const at = without.indexOf(target);
	if (at === -1) return layout;
	without.splice(side === 'before' ? at : at + 1, 0, key);
	return { ...layout, order: without };
}

/**
 * The layout with `key` moved one place among the visible columns (header
 * menu, keyboard). Hidden columns in between keep their places.
 */
export function moveColumnStep(
	available: readonly string[],
	layout: SheetsColumnLayout,
	key: string,
	step: -1 | 1,
): SheetsColumnLayout {
	const visible = visibleColumnKeys(available, layout);
	const at = visible.indexOf(key);
	const neighbour = visible[at + step];
	if (at === -1 || neighbour === undefined) return layout;
	return moveColumnBeside(available, layout, key, neighbour, step === -1 ? 'before' : 'after');
}

/** Freeze the visible columns up to and including `key`. */
export function freezeColumnsUpTo(available: readonly string[], layout: SheetsColumnLayout, key: string): SheetsColumnLayout {
	const at = visibleColumnKeys(available, layout).indexOf(key);
	return at === -1 ? layout : { ...layout, frozenCount: at + 1 };
}

export function clampColumnWidth(width: number): number {
	return Math.round(Math.max(MIN_COLUMN_WIDTH, Math.min(MAX_COLUMN_WIDTH, width)));
}

/** The layout with a stored width for `key`. */
export function setColumnWidth(layout: SheetsColumnLayout, key: string, width: number): SheetsColumnLayout {
	const next = clampColumnWidth(width);
	return layout.widths[key] === next ? layout : { ...layout, widths: { ...layout.widths, [key]: next } };
}

/** Value kinds that read at a glance in a narrow column: a checkbox and numbers. */
const NARROW_KINDS: ReadonlySet<ColumnValueKind> = new Set<ColumnValueKind>(['boolean', 'integer', 'bigint', 'decimal', 'float']);

/**
 * The table's checkbox and number columns (single values, not lists). When the grid is
 * wider than its columns, they keep their width while other columns can take the space.
 */
export function narrowColumnNames(model: TableModel | null): ReadonlySet<string> {
	const names = (model?.columns ?? []).filter((column) => !column.value.isArray && NARROW_KINDS.has(column.value.kind)).map((column) => column.name);
	return new Set(names);
}

/**
 * The toolbar "Fields" control: find a field, show or hide it, reorder by drag
 * or with the move buttons, show all / hide all, choose how many fields stay
 * in place and the row height.
 */
import { useMemo, useRef, useState } from 'react';
import { RiArrowDownLine, RiArrowUpLine, RiDraggable, RiLayoutColumnLine } from '@remixicon/react';

import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

import { cn } from '../../utils/cn';
import { TOOLBAR_POPOVER } from '../popup-classes';
import { ViewToggleButton } from '../toolbar/toolbar-button';
import { ROW_HEIGHTS, ROW_HEIGHT_LABELS } from './column-layout';
import type { ColumnLayoutBindings } from './use-column-layout';
import type { SheetsRowHeight } from '../view-state/view-state.types';

export interface FieldsControlProps {
	layout: ColumnLayoutBindings;
	columnLabel: (name: string) => string;
	/** Whether the table model has loaded; before that the control waits. */
	ready: boolean;
}

interface DropTarget {
	key: string;
	side: 'before' | 'after';
}

function FieldList({ layout, columnLabel }: Omit<FieldsControlProps, 'ready'>) {
	const [query, setQuery] = useState('');
	const dragging = useRef<string | null>(null);
	const [dropTarget, setDropTarget] = useState<DropTarget | null>(null);
	const term = query.trim().toLowerCase();
	const keys = useMemo(
		() =>
			layout.orderedKeys.filter((key) => !term || columnLabel(key).toLowerCase().includes(term) || key.toLowerCase().includes(term)),
		[layout.orderedKeys, term, columnLabel],
	);
	const last = layout.orderedKeys.length - 1;

	return (
		<div className='grid gap-2'>
			<Input
				size='sm'
				aria-label='Find a field'
				placeholder='Find a field'
				value={query}
				onChange={(event) => setQuery(event.target.value)}
			/>
			{keys.length === 0 ? (
				<p className='text-muted-foreground px-1 py-2 text-sm'>No field matches “{query.trim()}”.</p>
			) : (
				<ul aria-label='Fields' className='grid max-h-72 gap-0.5 overflow-auto'>
					{keys.map((key) => {
						const label = columnLabel(key);
						const shown = !layout.isHidden(key);
						const reason = layout.hideReason(key);
						const index = layout.orderedKeys.indexOf(key);
						const side = dropTarget?.key === key && dragging.current !== key ? dropTarget.side : null;
						return (
							<li
								key={key}
								data-part-id='sheets-field'
								data-field={key}
								draggable
								onDragStart={(event) => {
									dragging.current = key;
									event.dataTransfer?.setData('text/plain', key);
								}}
								onDragOver={(event) => {
									if (!dragging.current) return;
									event.preventDefault();
									const rect = event.currentTarget.getBoundingClientRect();
									setDropTarget({ key, side: event.clientY < rect.top + rect.height / 2 ? 'before' : 'after' });
								}}
								onDrop={(event) => {
									event.preventDefault();
									const from = dragging.current;
									if (from && dropTarget && from !== dropTarget.key) layout.moveBeside(from, dropTarget.key, dropTarget.side);
									dragging.current = null;
									setDropTarget(null);
								}}
								onDragEnd={() => {
									dragging.current = null;
									setDropTarget(null);
								}}
								className={cn(
									'hover:bg-muted/60 relative flex items-center gap-2 rounded px-1 py-1',
									side === 'before' && 'before:bg-primary before:absolute before:inset-x-0 before:top-0 before:h-0.5',
									side === 'after' && 'after:bg-primary after:absolute after:inset-x-0 after:bottom-0 after:h-0.5',
								)}
							>
								<RiDraggable className='text-muted-foreground size-4 shrink-0 cursor-grab' aria-hidden='true' />
								<Checkbox
									checked={shown}
									disabled={reason !== null}
									title={reason ?? undefined}
									aria-label={`Show ${label}`}
									onCheckedChange={(checked) => layout.setHidden(key, !checked)}
								/>
								<span className='min-w-0 flex-1 truncate text-sm' title={key}>
									{label}
								</span>
								<Button
									variant='ghost'
									size='icon-xs'
									aria-label={`Move ${label} up`}
									disabled={index <= 0}
									onClick={() => layout.moveTo(key, index - 1)}
								>
									<RiArrowUpLine aria-hidden='true' />
								</Button>
								<Button
									variant='ghost'
									size='icon-xs'
									aria-label={`Move ${label} down`}
									disabled={index >= last}
									onClick={() => layout.moveTo(key, index + 1)}
								>
									<RiArrowDownLine aria-hidden='true' />
								</Button>
							</li>
						);
					})}
				</ul>
			)}
		</div>
	);
}

export function FieldsControl({ layout, columnLabel, ready }: FieldsControlProps) {
	const hiddenCount = layout.orderedKeys.length - layout.visibleKeys.length;
	const frozenChoices = Array.from({ length: layout.visibleKeys.length + 1 }, (_, count) => count);
	return (
		<Popover open={layout.fieldsOpen} onOpenChange={layout.setFieldsOpen}>
			<PopoverTrigger asChild>
				<ViewToggleButton
					icon={RiLayoutColumnLine}
					label='Fields'
					count={hiddenCount}
					countLabel='hidden'
					disabled={!ready}
					title={ready ? undefined : 'Fields are available once the table has loaded.'}
					aria-label={hiddenCount > 0 ? `Fields (${hiddenCount} hidden)` : 'Fields'}
				/>
			</PopoverTrigger>
			<PopoverContent className={cn('w-[22rem]', TOOLBAR_POPOVER)} align='start'>
				<div className='grid gap-3' data-part-id='sheets-fields-control'>
					<h4 className='leading-none font-medium'>Fields</h4>
					<FieldList layout={layout} columnLabel={columnLabel} />
					<div className='flex items-center gap-2'>
						<Button variant='ghost' size='xs' onClick={layout.showAll} disabled={hiddenCount === 0}>
							Show all
						</Button>
						<Button variant='ghost' size='xs' onClick={layout.hideAll} disabled={layout.visibleKeys.length <= 1}>
							Hide all
						</Button>
					</div>
					<div className='grid grid-cols-[auto_1fr] items-center gap-x-3 gap-y-2 border-t pt-3 text-sm'>
						<span className='text-muted-foreground'>Frozen fields</span>
						<Select value={String(layout.frozenCount)} onValueChange={(value) => (Number(value) === 0 ? layout.unfreeze() : layout.freezeUpTo(layout.visibleKeys[Number(value) - 1]!))}>
							<SelectTrigger size='sm' aria-label='Frozen fields'>
								<SelectValue />
							</SelectTrigger>
							<SelectContent>
								{frozenChoices.map((count) => (
									<SelectItem key={count} value={String(count)}>
										{count === 0 ? 'None' : count === 1 ? `First field (${columnLabel(layout.visibleKeys[0]!)})` : `First ${count} fields`}
									</SelectItem>
								))}
							</SelectContent>
						</Select>
						<span className='text-muted-foreground'>Row height</span>
						<Select value={layout.layout.rowHeight} onValueChange={(value) => layout.setRowHeight(value as SheetsRowHeight)}>
							<SelectTrigger size='sm' aria-label='Row height'>
								<SelectValue />
							</SelectTrigger>
							<SelectContent>
								{ROW_HEIGHTS.map((height) => (
									<SelectItem key={height} value={height}>
										{ROW_HEIGHT_LABELS[height]}
									</SelectItem>
								))}
							</SelectContent>
						</Select>
					</div>
				</div>
			</PopoverContent>
		</Popover>
	);
}

import type { RelationGridColumn } from '../../hooks/use-relation-columns';
import type { ColumnLayoutBindings } from './use-column-layout';

/**
 * The grid columns a view shows: the layout's visible keys in order, each with
 * its stored width (or its default width).
 */
export function layoutGridColumns(
	columns: readonly RelationGridColumn[],
	layout: ColumnLayoutBindings,
): { columns: RelationGridColumn[]; columnKeys: string[] } {
	const byId = new Map(columns.map((column) => [column.id, column]));
	const shown = layout.visibleKeys.flatMap((key) => {
		const column = byId.get(key);
		return column ? [{ ...column, width: layout.layout.widths[key] ?? column.width }] : [];
	});
	return { columns: shown, columnKeys: shown.map((column) => column.id) };
}

/**
 * Column layout bindings over the validated layout: what shows, in what order,
 * the actions the Fields control, the header and the commands use, and the
 * open state of the Fields popover and the header menus.
 */
import { useCallback, useMemo, useState } from 'react';

import type { SheetsColumnLayout, SheetsRowHeight } from '../view-state/view-state.types';
import {
	ROW_HEIGHT_PX,
	effectiveFrozenCount,
	freezeColumnsUpTo,
	hideAllColumns,
	moveColumnBeside,
	moveColumnStep,
	moveColumnTo,
	orderedColumnKeys,
	setColumnHidden,
	setColumnWidth,
	showAllColumns,
	visibleColumnKeys,
} from './column-layout';

export interface ColumnLayoutBindings {
	layout: SheetsColumnLayout;
	/** Every grid column key of the table, in display order (shown and hidden). */
	orderedKeys: readonly string[];
	/** The keys that show, in display order. */
	visibleKeys: readonly string[];
	/** How many leading visible columns stay in place. */
	frozenCount: number;
	/** Row height in pixels. */
	rowHeightPx: number;
	isHidden: (key: string) => boolean;
	/** Why a column cannot be hidden (it is the last one shown), or null. */
	hideReason: (key: string) => string | null;
	setHidden: (key: string, hidden: boolean) => void;
	showAll: () => void;
	hideAll: () => void;
	/** Move to a position of the full display order (Fields list). */
	moveTo: (key: string, index: number) => void;
	/** Move beside another column (drag and drop). */
	moveBeside: (key: string, target: string, side: 'before' | 'after') => void;
	/** Move one place among the visible columns; false when it is already at that end. */
	moveStep: (key: string, step: -1 | 1) => boolean;
	freezeUpTo: (key: string) => void;
	unfreeze: () => void;
	setWidth: (key: string, width: number) => void;
	setRowHeight: (rowHeight: SheetsRowHeight) => void;
	fieldsOpen: boolean;
	setFieldsOpen: (open: boolean) => void;
	/** The column whose header menu is open, or null. */
	menuColumn: string | null;
	setMenuColumn: (key: string | null) => void;
}

export interface UseColumnLayoutOptions {
	/** The validated layout in use. */
	layout: SheetsColumnLayout;
	setLayout: (layout: SheetsColumnLayout) => void;
	/** Every grid column key of the table, in the table's order. */
	available: readonly string[];
}

const LAST_VISIBLE = 'At least one field must stay visible.';

export function useColumnLayout({ layout, setLayout, available }: UseColumnLayoutOptions): ColumnLayoutBindings {
	const [fieldsOpen, setFieldsOpen] = useState(false);
	const [menuColumn, setMenuColumn] = useState<string | null>(null);

	const orderedKeys = useMemo(() => orderedColumnKeys(available, layout), [available, layout]);
	const visibleKeys = useMemo(() => visibleColumnKeys(available, layout), [available, layout]);
	const hidden = useMemo(() => new Set(layout.hidden), [layout.hidden]);

	const isHidden = useCallback((key: string) => hidden.has(key), [hidden]);
	const hideReason = useCallback(
		(key: string) => (!hidden.has(key) && visibleKeys.length <= 1 ? LAST_VISIBLE : null),
		[hidden, visibleKeys],
	);
	const setHidden = useCallback(
		(key: string, next: boolean) => {
			if (next && !hidden.has(key) && visibleKeys.length <= 1) return;
			setLayout(setColumnHidden(layout, key, next));
		},
		[hidden, visibleKeys, layout, setLayout],
	);
	const moveStep = useCallback(
		(key: string, step: -1 | 1) => {
			const next = moveColumnStep(available, layout, key, step);
			if (next === layout) return false;
			setLayout(next);
			return true;
		},
		[available, layout, setLayout],
	);

	return useMemo<ColumnLayoutBindings>(
		() => ({
			layout,
			orderedKeys,
			visibleKeys,
			frozenCount: effectiveFrozenCount(available, layout),
			rowHeightPx: ROW_HEIGHT_PX[layout.rowHeight],
			isHidden,
			hideReason,
			setHidden,
			showAll: () => setLayout(showAllColumns(layout)),
			hideAll: () => setLayout(hideAllColumns(available, layout)),
			moveTo: (key, index) => setLayout(moveColumnTo(available, layout, key, index)),
			moveBeside: (key, target, side) => setLayout(moveColumnBeside(available, layout, key, target, side)),
			moveStep,
			freezeUpTo: (key) => setLayout(freezeColumnsUpTo(available, layout, key)),
			unfreeze: () => setLayout({ ...layout, frozenCount: 0 }),
			setWidth: (key, width) => {
				const next = setColumnWidth(layout, key, width);
				if (next !== layout) setLayout(next);
			},
			setRowHeight: (rowHeight) => setLayout({ ...layout, rowHeight }),
			fieldsOpen,
			setFieldsOpen,
			menuColumn,
			setMenuColumn,
		}),
		[layout, orderedKeys, visibleKeys, available, isHidden, hideReason, setHidden, moveStep, setLayout, fieldsOpen, menuColumn],
	);
}

// What a new (draft) row still needs before it can be saved, said in the grid's own terms.
//
// The table model knows which fields a create requires. The grid does not always show those
// fields: a foreign key is filled through its link column (`projectId` through "Project", a
// composite key through one link). Every surface that guides the user (the cursor after Add
// row, the message after Save, the tint on missing cells, the Save button's reason) reads the
// same answer from here, so they never disagree.
import type { TableModel } from '@constructive-io/data';

import { modelFieldLabel } from '../cell-types/field-label';
import { validateDraftRowRequiredFields } from './sheets.utils';

/** The draft-error key that holds why the whole row was not saved (shown on its Save button). */
export const DRAFT_ROW_ERROR_KEY = 'submit';

export interface DraftFieldGap {
	/** The model field without a value. */
	field: string;
	/** The grid column that fills it: the field itself, or the link column of the relation it keys. */
	columnKey: string;
	/** The column's label, as its header shows it. */
	label: string;
}

/** The grid column that fills a model field: a belongsTo key field is filled through its link column. */
export function draftColumnOf(field: string, model: Pick<TableModel, 'relations'>): string {
	const link = model.relations.find(
		(relation) => relation.kind === 'belongsTo' && relation.keys.some((pair) => pair.local === field),
	);
	return link?.fieldName ?? field;
}

/** The required fields a draft still lacks, one entry per grid column (a composite key is one link). */
export function missingDraftFields(values: Readonly<Record<string, unknown>>, model: TableModel): DraftFieldGap[] {
	const label = modelFieldLabel(model);
	const gaps: DraftFieldGap[] = [];
	const seen = new Set<string>();
	for (const field of Object.keys(validateDraftRowRequiredFields(values, model))) {
		const columnKey = draftColumnOf(field, model);
		if (seen.has(columnKey)) continue;
		seen.add(columnKey);
		gaps.push({ field, columnKey, label: label(columnKey) });
	}
	return gaps;
}

function listOf(labels: readonly string[]): string {
	if (labels.length <= 1) return labels.join('');
	return `${labels.slice(0, -1).join(', ')} and ${labels[labels.length - 1]}`;
}

/** "Fill in Title and Project to save this row." */
export function incompleteDraftMessage(gaps: readonly DraftFieldGap[]): string {
	return `Fill in ${listOf(gaps.map((gap) => gap.label))} to save this row.`;
}

/**
 * The errors a draft keeps after a refused Save: one per missing field and per grid column that
 * fills it (so the visible cell is marked, not only a hidden key field), and the row's reason.
 */
export function incompleteDraftErrors(gaps: readonly DraftFieldGap[]): Record<string, string> {
	const errors: Record<string, string> = {};
	for (const gap of gaps) {
		const message = `${gap.label} needs a value.`;
		errors[gap.field] = message;
		errors[gap.columnKey] = message;
	}
	errors[DRAFT_ROW_ERROR_KEY] = incompleteDraftMessage(gaps);
	return errors;
}

/**
 * The column the cursor should land on in a draft: the first column (in display order) that
 * still needs a value, else the first one that can be filled at all. Null when none can.
 */
export function draftColumnToFill(
	columnKeys: readonly string[],
	gaps: readonly DraftFieldGap[],
	canFill: (columnKey: string) => boolean,
): string | null {
	const needed = new Set(gaps.map((gap) => gap.columnKey));
	return columnKeys.find((key) => needed.has(key) && canFill(key)) ?? columnKeys.find(canFill) ?? null;
}

// Survivor types relocated out of `grid/editor-registry.ts` (deleted in the glide
// cutover). `DraftSubmitResult` is the result of submitting a client-side draft row;
// it is consumed by the draft-submission hook, use-sheets, and the image editor's
// DOM re-host.

import type { DraftFieldGap } from './draft-guidance';

/** Result of submitting a draft row */
export interface DraftSubmitResult {
	/** The created row with its metadata-defined primary-key fields. */
	createdRow: Record<string, unknown> | null;
	/** Required fields the draft still lacks, when Save was refused before sending. */
	missing?: readonly DraftFieldGap[];
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { Badge } from '@/components/ui/badge';
import { XIcon } from 'lucide-react';

import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear, modifierKeyLabel } from './editor-frame';
import { OVERLAY } from './overlay-presets';


// Minimal editor component for scalar arrays using tag chips UI
// It works with Glide's provideEditor by emitting a Text cell with JSON string

type Props = {
	value: unknown[];
	onChange: (next: unknown[]) => void;
	/** The saved list, null when cleared, or undefined when cancelled. */
	onFinished: (next?: unknown[] | null) => void;
	/** Check the list before it is saved; return the reason it cannot be saved, or null. */
	validate?: (next: unknown[]) => string | null;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** The column takes no value, so Clear is offered. */
	nullable?: boolean;
};

// One item per line: a comma is part of an item ("Smith, Jane"), never a separator.
function parsePendingItems(input: string): string[] {
	if (!input) return [];
	return input
		.split(/\n/g)
		.map((token) => token.trim())
		.filter((token) => token.length > 0);
}

export function mergeArrayEditorValues(list: unknown[], pendingInput: string): unknown[] {
	const pendingItems = parsePendingItems(pendingInput);
	if (!pendingItems.length) return list;
	return [...list, ...pendingItems];
}

export function ArrayEditor({ value, onChange, onFinished, validate, title = 'List', nullable = false }: Props) {
	const items = useMemo(() => (Array.isArray(value) ? value : []), [value]);
	const [list, setList] = useState<unknown[]>(items);
	const [input, setInput] = useState('');
	const [error, setError] = useState<string | null>(null);
	const inputRef = useRef<HTMLInputElement>(null);
	const keyContainerRef = useRef<HTMLDivElement>(null);

	const handleCancel = useCallback(() => onFinished(undefined), [onFinished]);
	const handleSave = useCallback(() => {
		const next = mergeArrayEditorValues(list, input);
		setList(next);
		setInput('');
		const problem = validate?.(next) ?? null;
		setError(problem);
		if (problem) return;
		onChange(next);
		onFinished(next);
	}, [input, list, onChange, onFinished, validate]);

	const add = useCallback(() => {
		const next = mergeArrayEditorValues(list, input);
		if (next.length === list.length) return;
		setList(next);
		setInput('');
		setError(null);
		onChange(next);
	}, [input, list, onChange]);

	const remove = useCallback(
		(idx: number) => {
			const next = list.filter((_, i) => i !== idx);
			setList(next);
			onChange(next);
			// Refocus input after removing a tag
			inputRef.current?.focus();
		},
		[list, onChange],
	);

	// Keep refs to latest callbacks/state so the native handler always has fresh values.
	const actionsRef = useRef({ add, handleSave, remove, handleCancel });
	actionsRef.current = { add, handleSave, remove, handleCancel };
	const stateRef = useRef({ input, listLength: list.length });
	stateRef.current = { input, listLength: list.length };

	// Native DOM keydown listener on a wrapper div.
	// Glide's overlay intercepts Enter/Tab/Escape via React onKeyDown on .gdg-clip-region.
	// React's stopPropagation doesn't reliably prevent this in portal contexts.
	// A native listener fires before React's root delegation, so we handle keys here
	// and stopPropagation to prevent Glide from closing the overlay.
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { add, handleSave, remove, handleCancel } = actionsRef.current;
			const { input, listLength } = stateRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if (e.key === 'Backspace' && !input && listLength > 0) {
				e.preventDefault();
				e.stopPropagation();
				remove(listLength - 1);
				return;
			}
			if (e.key === 'Enter' && !e.metaKey && !e.ctrlKey) {
				e.preventDefault();
				e.stopPropagation();
				add();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			if (e.key === 'Tab') {
				e.stopPropagation();
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			className={`bg-popover ${OVERLAY.sm} rounded-lg border p-2.5 shadow-lg`}
		>
			{/* Key event boundary — native listener prevents Glide from intercepting */}
			<div ref={keyContainerRef} className='flex flex-col gap-2'>
				<EditorHeader title={title} className='px-1' />
				{/* Unified tag surface — tags and input share one container */}
				<div
					className='flex min-h-[2.5rem] cursor-text flex-wrap items-center gap-2 rounded-md px-1 py-1'
					onClick={() => inputRef.current?.focus()}
				>
					{list.map((item, i) => (
						<Badge
							key={i}
							variant='outline'
							size='sm'
							className='group/tag !animate-none !transition-none gap-0.5 pe-0.5'
						>
							<span className='max-w-[180px] truncate tabular-nums' title={item === null ? 'Empty item' : String(item)}>
								{item === null ? '(empty)' : String(item)}
							</span>
							<button
								className='text-muted-foreground/60 hover:bg-muted hover:text-foreground -me-px inline-flex size-4 items-center justify-center rounded-xs'
								onClick={(e) => {
									e.stopPropagation();
									remove(i);
								}}
								aria-label={`Remove ${String(item)}`}
								tabIndex={-1}
							>
								<XIcon className='size-3' />
							</button>
						</Badge>
					))}

					<input
						ref={inputRef}
						value={input}
						onChange={(e) => setInput(e.target.value)}
						placeholder={list.length === 0 ? 'Type and press Enter...' : 'Add more...'}
						className='placeholder:text-muted-foreground/50 min-w-[80px] flex-1 bg-transparent py-0.5 text-sm outline-none'
					/>
				</div>

				{error ? (
					<p role='alert' className='text-destructive px-1 text-xs'>
						{error}
					</p>
				) : null}

				<EditorFooter
					className='px-1'
					onSave={handleSave}
					saveShortcut={`${modifierKeyLabel()} Enter`}
					clear={editorClear(nullable, () => onFinished(null))}
				/>
			</div>
		</EditorFocusTrap>
	);
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { getLocalTimeZone, parseDate as parseAriaDate, today } from '@internationalized/date';
import type { DateValue as DateValueType } from 'react-aria-components';

import { Calendar } from '@/components/ui/calendar-rac';

import { DATE_TIME_TYPES } from '../../cell-types/cell-type-groups';
import { dateTimeTitle, formatDateTimeText, type DateTimeKind } from '../../cell-types/date-time-format';

import {
	emptyDateValueParts,
	normalizeTimeInput,
	readDateValueParts,
	writeDateValueParts,
	type DateEditorType,
	type DateValueParts,
} from './date-value-parts';
import { parseTypedDate, typedDateExample } from './date-text';
import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear, modifierKeyLabel } from './editor-frame';
import { OVERLAY } from './overlay-presets';

export type { DateEditorType } from './date-value-parts';

/** The editor's type from the cell type, else guessed from the stored text. */
export function resolveDateType(value: unknown, explicitType?: string): DateEditorType {
	if (explicitType && DATE_TIME_TYPES.has(explicitType)) return explicitType as DateEditorType;
	if (typeof value === 'string') {
		if (value.includes('T') || value.includes(' ')) return /[+-]\d{2}(:?\d{2})?$|Z$/.test(value) ? 'timestamptz' : 'datetime';
		if (value.includes(':') && !value.includes('-')) return 'time';
	}
	return 'date';
}

function displayKind(type: DateEditorType): DateTimeKind {
	return type === 'date' ? 'date' : type === 'time' ? 'time' : 'datetime';
}

const TIME_INPUT =
	'bg-muted/40 border-border/40 text-foreground w-full rounded-md border px-2.5 py-1.5 text-sm tabular-nums outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35';

// The calendar fills the editor's content box: seven equal day columns and a header whose
// arrows sit at its two ends. The arrows' focus ring is drawn inside them, so it is no
// larger than the button.
const CALENDAR_FILL = [
	'w-full',
	'[&_table]:w-full [&_table]:table-fixed',
	'[&_td>[role=button]]:mx-auto [&_th]:w-auto',
	'[&_header_button:focus-visible]:ring-2 [&_header_button:focus-visible]:ring-inset',
].join(' ');

interface DateEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	dateType?: DateEditorType;
	/** Offer a Clear action that commits null (the column accepts no value). */
	canClear?: boolean;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** Text typed on the cell to open the editor; it starts the date field. */
	initialText?: string;
}

/** A date for the calendar, or null when the text is not one. */
function calendarDate(iso: string | null | undefined): DateValueType | null {
	if (!iso) return null;
	try {
		return parseAriaDate(iso);
	} catch {
		return null;
	}
}

export const DateEditor: React.FC<DateEditorProps> = ({
	value,
	onFinishedEditing,
	dateType: forcedDateType,
	canClear = false,
	title = 'Date',
	initialText,
}) => {
	const stored = typeof value === 'string' ? value : '';
	const dateType = resolveDateType(stored, forcedDateType);
	const isTimeOnly = dateType === 'time';
	const isDateTimeType = dateType === 'datetime' || dateType === 'timestamptz';

	// The parts of the stored text; nothing changes until the user picks a day or a time.
	const [parts, setParts] = useState<DateValueParts | null>(() => readDateValueParts(stored, dateType));
	const [dirty, setDirty] = useState(false);
	const keyContainerRef = useRef<HTMLDivElement>(null);

	const selectedDate = useMemo(() => calendarDate(parts?.date), [parts?.date]);

	// The date can also be typed. The field starts with what was typed on the cell, else the
	// stored day; a whole date moves the calendar there, and Save refuses text that is not one.
	const [dateText, setDateText] = useState(() => initialText ?? parts?.date ?? '');
	const [dateError, setDateError] = useState<string | null>(null);
	const [focusedDate, setFocusedDate] = useState<DateValueType>(() => selectedDate ?? today(getLocalTimeZone()));
	const dateInputRef = useRef<HTMLInputElement>(null);
	useEffect(() => {
		const input = dateInputRef.current;
		if (!input) return;
		// Typing replaces the stored day; text typed on the cell goes on where it ended.
		if (initialText == null) input.select();
		else input.setSelectionRange(input.value.length, input.value.length);
		// Only on open.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);

	const setDay = useCallback(
		(date: string) => {
			// Only the day changes: the time, its fraction and its zone stay as they are.
			setParts((current) => ({ ...(current ?? emptyDateValueParts(dateType)), date }));
			setDirty(true);
		},
		[dateType],
	);

	const handleDateText = useCallback(
		(text: string) => {
			setDateText(text);
			setDateError(null);
			const date = parseTypedDate(text);
			if (!date) return;
			setDay(date);
			const shown = calendarDate(date);
			if (shown) setFocusedDate(shown);
		},
		[setDay],
	);

	useEffect(() => {
		// Text typed on the cell that is already a whole date counts at once.
		if (initialText != null) handleDateText(initialText);
		// Only on open.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);

	const handleDateSelect = useCallback(
		(picked: DateValueType | readonly DateValueType[] | null) => {
			// The shared Calendar also supports multi-select; this editor picks one day.
			if (!picked || Array.isArray(picked)) return;
			const day = picked as DateValueType;
			const date = `${String(day.year).padStart(4, '0')}-${String(day.month).padStart(2, '0')}-${String(day.day).padStart(2, '0')}`;
			setDay(date);
			setDateText(date);
			setDateError(null);
		},
		[setDay],
	);

	const handleTimeChange = useCallback(
		(input: string) => {
			const time = normalizeTimeInput(input);
			if (!time) return;
			// The field edits whole seconds; the stored fraction of a second is kept.
			setParts((current) => ({ ...(current ?? emptyDateValueParts(dateType)), time }));
			setDirty(true);
		},
		[dateType],
	);

	const written = parts && dirty && (isTimeOnly || parts.date) ? writeDateValueParts(parts, dateType) : null;

	const handleSave = useCallback(() => {
		if (!isTimeOnly) {
			const text = dateText.trim();
			// An emptied date field clears the value where the column allows no value.
			if (text === '' && stored) {
				if (canClear) onFinishedEditing(null);
				else setDateError('This field needs a value.');
				return;
			}
			if (text !== '' && !parseTypedDate(text)) {
				setDateError(`Enter a date like ${typedDateExample()}.`);
				dateInputRef.current?.focus();
				return;
			}
		}
		// Nothing changed: close without writing, so the stored text stays exactly as it is.
		if (!written) {
			onFinishedEditing();
			return;
		}
		onFinishedEditing(written);
	}, [isTimeOnly, dateText, stored, canClear, written, onFinishedEditing]);

	const handleCancel = useCallback(() => {
		onFinishedEditing();
	}, [onFinishedEditing]);

	// Refs for native key handler
	const actionsRef = useRef({ handleSave, handleCancel });
	actionsRef.current = { handleSave, handleCancel };

	// Native DOM keydown listener — prevents Glide from intercepting keys in portal context
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { handleSave, handleCancel } = actionsRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			// Stop Tab from reaching Glide
			if (e.key === 'Tab') {
				e.stopPropagation();
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	// The value as the cells show it, in the same zone; the title has the exact text.
	const shownText = written ?? stored;
	const shown = shownText ? formatDateTimeText(shownText, displayKind(dateType)) : null;

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			// A calendar is as wide as its seven 36px days; the editor takes that width so the
			// month sits with equal space on both sides. A time alone keeps the small editor width.
			className={`bg-popover rounded-lg border p-2.5 shadow-lg ${isTimeOnly ? OVERLAY.sm : 'w-[min(20rem,calc(100vw-1.5rem))]'}`}
		>
			<div ref={keyContainerRef} className='flex flex-col gap-2'>
				<EditorHeader title={title} />
				{/* The value so far, as the cell shows it, on the calendar's left edge. */}
				<p
					data-slot='date-editor-value'
					className='text-muted-foreground -mt-1 text-xs tabular-nums'
					title={shown && shownText ? dateTimeTitle(shownText, shown.zone) : undefined}
				>
					{shown?.text || 'No value'}
				</p>
				{isTimeOnly ? (
					<input
						type='time'
						step='1'
						aria-label={`${title} time`}
						value={parts?.time ?? ''}
						onChange={(e) => handleTimeChange(e.target.value)}
						className={TIME_INPUT}
						autoFocus
					/>
				) : (
					<>
						<input
							ref={dateInputRef}
							type='text'
							autoComplete='off'
							spellCheck={false}
							aria-label={`${title} date`}
							aria-invalid={dateError ? true : undefined}
							aria-describedby={dateError ? 'sheets-date-editor-error' : undefined}
							placeholder={typedDateExample()}
							value={dateText}
							onChange={(e) => handleDateText(e.target.value)}
							onKeyDown={(e) => {
								// Enter saves what was typed, as in a cell.
								if (e.key !== 'Enter' || e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
								e.preventDefault();
								e.stopPropagation();
								handleSave();
							}}
							className={TIME_INPUT}
							autoFocus
						/>
						{dateError ? (
							<p id='sheets-date-editor-error' role='alert' className='text-destructive -mt-1 text-xs'>
								{dateError}
							</p>
						) : null}
						<Calendar
							value={selectedDate}
							onChange={handleDateSelect}
							focusedValue={focusedDate}
							onFocusChange={setFocusedDate}
							aria-label='Select date'
							className={CALENDAR_FILL}
						/>
						{isDateTimeType ? (
							<input
								type='time'
								step='1'
								aria-label={`${title} time`}
								value={parts?.time ?? ''}
								onChange={(e) => handleTimeChange(e.target.value)}
								className={TIME_INPUT}
							/>
						) : null}
					</>
				)}
				<EditorFooter
					onSave={handleSave}
					saveShortcut={`${modifierKeyLabel()} Enter`}
					clear={editorClear(canClear, () => onFinishedEditing(null))}
				/>
			</div>
		</EditorFocusTrap>
	);
};

// A date typed as text. Year first (2024-01-31, 2024/1/31) is read as year, month, day; a date
// that ends with the year (31/01/2024, 1.31.2024) is read in the order the locale writes its
// dates, so 03/04/2024 is 3 April where the day comes first and March 4 where the month does.
// A two-digit year is not guessed.

type Part = 'day' | 'month' | 'year';

const YEAR_FIRST = /^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/;
const YEAR_LAST = /^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/;

/** The order of day and month in the locale's numeric dates. */
export function dayMonthOrder(locale?: string): 'day-month' | 'month-day' {
	const parts = new Intl.DateTimeFormat(locale, { year: 'numeric', month: 'numeric', day: 'numeric' })
		.formatToParts(new Date(Date.UTC(2024, 0, 31, 12)))
		.map((part) => part.type)
		.filter((type): type is Part => type === 'day' || type === 'month' || type === 'year');
	return parts.indexOf('day') < parts.indexOf('month') ? 'day-month' : 'month-day';
}

const pad = (value: number, width = 2) => String(value).padStart(width, '0');

function isoDate(year: number, month: number, day: number): string | null {
	const probe = new Date(Date.UTC(year, month - 1, day));
	probe.setUTCFullYear(year);
	if (probe.getUTCFullYear() !== year || probe.getUTCMonth() !== month - 1 || probe.getUTCDate() !== day) return null;
	return `${pad(year, 4)}-${pad(month)}-${pad(day)}`;
}

/** The date `text` names, as YYYY-MM-DD, or null when it is not a whole, real date. */
export function parseTypedDate(text: string, locale?: string): string | null {
	const trimmed = text.trim();
	const yearFirst = YEAR_FIRST.exec(trimmed);
	if (yearFirst) return isoDate(Number(yearFirst[1]), Number(yearFirst[2]), Number(yearFirst[3]));
	const yearLast = YEAR_LAST.exec(trimmed);
	if (!yearLast) return null;
	const [first, second, year] = [Number(yearLast[1]), Number(yearLast[2]), Number(yearLast[3])];
	return dayMonthOrder(locale) === 'day-month' ? isoDate(year, second, first) : isoDate(year, first, second);
}

/** What to type, for the hint: "2024-01-31 or 31/01/2024" in the locale's order. */
export function typedDateExample(locale?: string): string {
	return dayMonthOrder(locale) === 'day-month' ? '2024-01-31 or 31/01/2024' : '2024-01-31 or 01/31/2024';
}

// The date editor works on the parts of the stored text, never on a JS Date, so
// nothing the user did not change is lost: microseconds ("13:45:30.123456"), a time's
// own zone ("+00:00") and a wall time without a zone all survive a save. A date and
// time with a zone is an instant: the editor shows and edits it in the viewer's zone,
// as the cells do, and writes it back with the viewer's offset for that moment.

export type DateEditorType = 'date' | 'datetime' | 'timestamptz' | 'time';

export interface DateValueParts {
	/** Calendar day, "YYYY-MM-DD" (in the viewer's zone for an instant); '' for a time. */
	date: string;
	/** Time of day, "HH:mm:ss" (in the viewer's zone for an instant); '' for a date. */
	time: string;
	/** Fraction of a second as stored (".123456"), or ''. Kept when the time changes. */
	fraction: string;
	/** A time-of-day value's own zone ("+00:00"), kept as stored; '' when it has none. */
	timeZone: string;
	/** A date and time with a zone: an instant, written with the viewer's offset. */
	instant: boolean;
}

const DATE_RE = /^(\d{4,})-(\d{2})-(\d{2})$/;
const TIME_RE = /^(\d{1,2}):(\d{2})(?::(\d{2})(\.\d+)?)?(Z|[+-]\d{2}(?::?\d{2})?)?$/;
const DATE_TIME_RE = /^(\d{4,}-\d{2}-\d{2})[T ](\d{1,2}):(\d{2})(?::(\d{2})(\.\d+)?)?(Z|[+-]\d{2}(?::?\d{2})?)?$/;

function pad2(value: number | string): string {
	return String(value).padStart(2, '0');
}

function localDate(instant: Date): string {
	return `${String(instant.getFullYear()).padStart(4, '0')}-${pad2(instant.getMonth() + 1)}-${pad2(instant.getDate())}`;
}

function localTime(instant: Date): string {
	return `${pad2(instant.getHours())}:${pad2(instant.getMinutes())}:${pad2(instant.getSeconds())}`;
}

/** The parts of stored text, or null for no value or text that is not of this type. */
export function readDateValueParts(text: string, type: DateEditorType): DateValueParts | null {
	const value = text.trim();
	if (!value) return null;
	if (type === 'date') {
		const match = DATE_RE.exec(value) ?? DATE_RE.exec(value.slice(0, 10));
		return match ? { date: value.slice(0, 10), time: '', fraction: '', timeZone: '', instant: false } : null;
	}
	if (type === 'time') {
		const match = TIME_RE.exec(value);
		if (!match) return null;
		const [, hours, minutes, seconds = '00', fraction = '', zone = ''] = match;
		return { date: '', time: `${pad2(hours!)}:${minutes}:${seconds}`, fraction, timeZone: zone, instant: false };
	}
	const match = DATE_TIME_RE.exec(value);
	if (!match) return null;
	const [, date, hours, minutes, seconds = '00', fraction = '', zone] = match;
	if (!zone) return { date: date!, time: `${pad2(hours!)}:${minutes}:${seconds}`, fraction, timeZone: '', instant: false };
	// An instant: read in the viewer's zone. Offsets are whole minutes, so the seconds and
	// their fraction do not change.
	const instant = new Date(value.replace(' ', 'T').replace(/(\.\d{3})\d+/, '$1'));
	if (Number.isNaN(instant.getTime())) return null;
	return { date: localDate(instant), time: localTime(instant), fraction, timeZone: '', instant: true };
}

/** The viewer's offset at this local wall time ("+07:00"). */
function localOffset(date: string, time: string): string {
	const instant = new Date(`${date}T${time}`);
	const minutes = Number.isNaN(instant.getTime()) ? -new Date().getTimezoneOffset() : -instant.getTimezoneOffset();
	const sign = minutes >= 0 ? '+' : '-';
	const absolute = Math.abs(minutes);
	return `${sign}${pad2(Math.floor(absolute / 60))}:${pad2(absolute % 60)}`;
}

/** Stored text for these parts. */
export function writeDateValueParts(parts: DateValueParts, type: DateEditorType): string {
	if (type === 'date') return parts.date;
	if (type === 'time') return `${parts.time}${parts.fraction}${parts.timeZone}`;
	const time = parts.time || '00:00:00';
	const base = `${parts.date}T${time}${parts.fraction}`;
	return parts.instant ? `${base}${localOffset(parts.date, time)}` : base;
}

/** Parts for a value the user starts from nothing. A zoned type is an instant. */
export function emptyDateValueParts(type: DateEditorType): DateValueParts {
	return { date: '', time: type === 'date' ? '' : '00:00:00', fraction: '', timeZone: '', instant: type === 'timestamptz' };
}

/** A time field's value ("HH:mm" or "HH:mm:ss") as "HH:mm:ss", or null when it is not a time. */
export function normalizeTimeInput(value: string): string | null {
	const match = /^(\d{1,2}):(\d{2})(?::(\d{2}))?/.exec(value.trim());
	if (!match) return null;
	const [, hours, minutes, seconds = '00'] = match;
	if (Number(hours) > 23 || Number(minutes) > 59 || Number(seconds) > 59) return null;
	return `${pad2(hours!)}:${minutes}:${seconds}`;
}

import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';

interface EditorFocusTrapProps {
	children: React.ReactNode;
	onEscape?: () => void;
	onKeyDown?: (e: React.KeyboardEvent) => void;
	className?: string;
	style?: React.CSSProperties;
}

const FOCUSABLE_SELECTOR = [
	'button:not([disabled])',
	'input:not([disabled])',
	'textarea:not([disabled])',
	'select:not([disabled])',
	'a[href]',
	'[tabindex]:not([tabindex="-1"])',
].join(', ');

/** Filter to only truly visible focusable elements */
function getVisibleFocusable(container: HTMLElement): HTMLElement[] {
	return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)).filter(
		(el) => el.offsetParent !== null,
	);
}

export function EditorFocusTrap({ children, onEscape, onKeyDown, className, style }: EditorFocusTrapProps) {
	const containerRef = useRef<HTMLDivElement>(null);
	// The element to give focus back to on close (the grid, or the button that opened the
	// editor). Read on the first render, before any child mounts: an `autoFocus` input inside
	// the editor takes focus during the commit, before this component's own effects run.
	const [previousActiveElement] = useState<Element | null>(() => (typeof document === 'undefined' ? null : document.activeElement));

	// Focus the first visible focusable element synchronously before paint, so the
	// editor input is focused instantly on open (no setTimeout settle, no focus-jump
	// off an input the user already started typing in). Runs once on mount.
	useLayoutEffect(() => {
		if (!containerRef.current) return;

		const visibleElements = getVisibleFocusable(containerRef.current);
		if (visibleElements.length > 0) {
			visibleElements[0].focus();
		} else {
			// If no visible focusable elements, focus the container itself
			containerRef.current.focus();
		}
	}, []);

	// Restore focus to the previously active element when unmounting (only if still
	// in DOM).
	useEffect(() => {
		return () => {
			if (previousActiveElement instanceof HTMLElement && previousActiveElement.isConnected) {
				previousActiveElement.focus();
			}
		};
	}, [previousActiveElement]);

	// Handle keyboard events — forward all keys to parent, then handle Escape/Tab
	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Forward all key events to parent before handling
			onKeyDown?.(e);

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				onEscape?.();
				return;
			}

			if (e.key !== 'Tab') return;

			const container = containerRef.current;
			if (!container) return;

			const focusableElements = getVisibleFocusable(container);
			if (focusableElements.length === 0) return;

			const firstElement = focusableElements[0];
			const lastElement = focusableElements[focusableElements.length - 1];
			const activeElement = document.activeElement;

			if (e.shiftKey) {
				// Shift+Tab: going backwards
				if (activeElement === firstElement) {
					e.preventDefault();
					lastElement.focus();
				}
			} else {
				// Tab: going forwards
				if (activeElement === lastElement) {
					e.preventDefault();
					firstElement.focus();
				}
			}
		},
		[onEscape, onKeyDown],
	);

	return (
		<div
			ref={containerRef}
			className={className}
			style={style}
			onKeyDown={handleKeyDown}
			tabIndex={-1}
			role="dialog"
			aria-modal="true"
		>
			{children}
		</div>
	);
}

'use client';

// The parts every value editor shares, so their frames read the same: a title row (the
// field's readable name, an optional chip for the kind of value, optional controls on
// the right) and a footer with Clear and Save. Keyboard shortcuts are in the buttons'
// titles, not printed in the popover.

import type { ReactNode } from 'react';

import { Button } from '@/components/ui/button';

import { cn } from '../../utils/cn';

const MAC_UA_RE = /Mac|iPod|iPhone|iPad/;

/** The platform's name for the modifier key in a shortcut ("⌘" or "Ctrl"). */
export function modifierKeyLabel(): string {
	return typeof navigator !== 'undefined' && MAC_UA_RE.test(navigator.userAgent) ? '⌘' : 'Ctrl';
}

/** Why Clear is not offered: the column requires a value. */
export const VALUE_REQUIRED_REASON = 'This field cannot be empty.';

/** Clear for a nullable column, or the reason it cannot be cleared. */
export type EditorClear = { onClear: () => void } | { reason: string };

export function editorClear(nullable: boolean | undefined, onClear: () => void): EditorClear {
	return nullable ? { onClear } : { reason: VALUE_REQUIRED_REASON };
}

interface EditorHeaderProps {
	title: string;
	/** Extra detail on hover (the field's API name, for example). */
	titleHint?: string;
	/** The kind of value, when it helps (a shape kind, for example). */
	chip?: string | null;
	/** Controls on the right (a mode switch). */
	children?: ReactNode;
	className?: string;
}

export function EditorHeader({ title, titleHint, chip, children, className }: EditorHeaderProps) {
	return (
		<div data-slot='editor-header' className={cn('flex items-center justify-between gap-2', className)}>
			{/* As tall as a small switch, so a header is the same height with or without one. */}
			<div className='flex min-h-7 min-w-0 items-center gap-2'>
				<h3 className='truncate text-sm font-medium' title={titleHint}>
					{title}
				</h3>
				{chip ? (
					<span className='bg-muted text-muted-foreground shrink-0 rounded-md px-2 py-0.5 text-xs font-medium'>{chip}</span>
				) : null}
			</div>
			{children}
		</div>
	);
}

interface EditorFooterProps {
	onSave: () => void;
	/** The keys that save, for the Save button's title ("Enter", or "⌘ Enter"). */
	saveShortcut?: string;
	/** Why Save is not available (an invalid value), shown as its title. */
	saveBlockedReason?: string | null;
	/** Clear, or why the value cannot be cleared; omitted when clearing does not apply. */
	clear?: EditorClear | null;
	/** A short status on the left, such as why the value is not valid. */
	status?: ReactNode;
	className?: string;
}

export function EditorFooter({ onSave, saveShortcut, saveBlockedReason, clear, status, className }: EditorFooterProps) {
	const blocked = Boolean(saveBlockedReason);
	return (
		<div data-slot='editor-footer' className={cn('flex items-center justify-end gap-2 border-t pt-2', className)}>
			{status ? <div className='me-auto min-w-0 truncate text-xs'>{status}</div> : null}
			{clear ? (
				'onClear' in clear ? (
					<Button size='xs' variant='ghost' onClick={clear.onClear} title='Remove the value'>
						Clear
					</Button>
				) : (
					<Button size='xs' variant='ghost' disabled focusableWhenDisabled title={clear.reason}>
						Clear
					</Button>
				)
			) : null}
			<Button
				size='xs'
				onClick={onSave}
				disabled={blocked}
				focusableWhenDisabled={blocked}
				title={blocked ? saveBlockedReason ?? undefined : saveShortcut ? `Save (${saveShortcut})` : undefined}
			>
				Save
			</Button>
		</div>
	);
}

import React, { useCallback, useContext, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { AlertCircle, FileText, Map } from 'lucide-react';

import { cn } from '../../utils/cn';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Textarea } from '@/components/ui/textarea';

import { shapeKindName } from '../../cell-types/shape-kind';
import { MapPicker } from '../../utils/map-picker';
import { useMapSettings } from '../../utils/map-settings';
import { sheetsLogger } from '../../utils/sheets-logger';
import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear, modifierKeyLabel } from './editor-frame';
import { MapLoadBoundary } from './map-load-boundary';
import { OVERLAY } from './overlay-presets';
import { OverlayMeasureContext } from './overlay-viewport-guard';


// GeoJSON validation according to RFC 7946
const VALID_GEOJSON_TYPES = [
	'Point',
	'LineString',
	'Polygon',
	'MultiPoint',
	'MultiLineString',
	'MultiPolygon',
	'GeometryCollection',
];

interface GeometryType {
	geojson: any; // GeoJSON object
	srid: number; // Integer
	x: number; // Float
	y: number; // Float
}

interface MapPickerValue {
	geojson: {
		type: 'Point';
		coordinates: [number, number];
	};
	srid: number;
	x: number;
	y: number;
}

function isValidGeoJSON(obj: any): boolean {
	if (!obj || typeof obj !== 'object') return false;

	// Must have a type property
	if (!obj.type || typeof obj.type !== 'string') return false;

	// Feature/FeatureCollection are valid GeoJSON per RFC 7946 but PostGIS
	// ST_GeomFromGeoJSON only accepts geometry types — reject them here.
	if (obj.type === 'Feature' || obj.type === 'FeatureCollection') return false;

	// Type must be one of the valid GeoJSON geometry types
	if (!VALID_GEOJSON_TYPES.includes(obj.type)) return false;

	// Structural validation for types with well-defined coordinate shapes.
	// Multi* and GeometryCollection are accepted with a type-name check only.
	switch (obj.type) {
		case 'Point':
			return Array.isArray(obj.coordinates) && obj.coordinates.length >= 2;
		case 'LineString':
			return (
				Array.isArray(obj.coordinates) &&
				obj.coordinates.length >= 2 &&
				obj.coordinates.every((coord: any) => Array.isArray(coord) && coord.length >= 2)
			);
		case 'Polygon':
			return (
				Array.isArray(obj.coordinates) &&
				obj.coordinates.length >= 1 &&
				obj.coordinates.every((ring: any) => Array.isArray(ring) && ring.length >= 4)
			);
		default:
			return true;
	}
}

/** Returns a helpful hint when the GeoJSON type is recognized but unsupported by PostGIS. */
function getGeoJSONHint(obj: any): string | undefined {
	if (!obj || typeof obj !== 'object' || typeof obj.type !== 'string') return undefined;
	if (obj.type === 'Feature') return 'Feature type is not supported by PostGIS. Extract the geometry property first.';
	if (obj.type === 'FeatureCollection') return 'FeatureCollection type is not supported by PostGIS. Extract individual geometries first.';
	return undefined;
}

function isValidGeometry(obj: any): boolean {
	if (!obj || typeof obj !== 'object') return false;

	// Must have all required properties
	if (!('geojson' in obj) || !('srid' in obj) || !('x' in obj) || !('y' in obj)) {
		return false;
	}

	// Validate geojson
	if (!isValidGeoJSON(obj.geojson)) return false;

	// Validate srid (must be integer)
	if (!Number.isInteger(obj.srid)) return false;

	// Validate x and y (must be finite numbers)
	if (!Number.isFinite(obj.x) || !Number.isFinite(obj.y)) return false;

	return true;
}

// Accept wrapped objects which only contain a valid `geojson` property (no srid/x/y)
function isWrappedGeoJSON(obj: any): boolean {
	if (!obj || typeof obj !== 'object') return false;
	if (!('geojson' in obj)) return false;
	return isValidGeoJSON(obj.geojson);
}

// Detect bare {x, y} point format (e.g., from GeometryPoint query returning { x, y } subfields)
function isBarePoint(obj: any): obj is { x: number; y: number } {
	return (
		obj && typeof obj === 'object' &&
		'x' in obj && 'y' in obj &&
		typeof obj.x === 'number' && typeof obj.y === 'number' &&
		!('type' in obj) && !('geojson' in obj)
	);
}

/** Extract raw GeoJSON geometry from any accepted format, or null if unrecognized. */
function extractRawGeoJSON(obj: any): any | null {
	if (isValidGeoJSON(obj)) return obj;
	if (obj?.geojson && isValidGeoJSON(obj.geojson)) return obj.geojson;
	if (isBarePoint(obj)) return { type: 'Point', coordinates: [obj.x, obj.y] };
	return null;
}

/** Extract Point coordinates from a GeoJSON geometry, defaulting to (0,0) for non-Point types. */
function extractPointCoords(geojson: any): { x: number; y: number } {
	if (geojson?.type === 'Point' && Array.isArray(geojson.coordinates)) {
		return { x: Number(geojson.coordinates[0]), y: Number(geojson.coordinates[1]) };
	}
	return { x: 0, y: 0 };
}

function validateGeometry(jsonString: string, expectedType?: string): true | string {
	if (!jsonString.trim()) return true; // Allow empty

	try {
		const parsed = JSON.parse(jsonString);

		if (!isValidGeometry(parsed) && !isValidGeoJSON(parsed) && !isWrappedGeoJSON(parsed) && !isBarePoint(parsed)) {
			const hint = getGeoJSONHint(parsed?.geojson ?? parsed);
			if (hint) return hint;
			return 'Invalid geometry. Expected GeoJSON (e.g., {"type": "Point", "coordinates": [0, 0]}).';
		}

		// Validate geometry type matches column constraint
		if (expectedType) {
			const geojson = extractRawGeoJSON(parsed) ?? parsed;
			const actualType = geojson?.type as string | undefined;
			if (actualType && actualType !== expectedType) {
				return `Column expects ${expectedType} but got ${actualType}.`;
			}
		}

		return true;
	} catch {
		return 'Invalid JSON format';
	}
}

// Helper functions for map integration
function isPointGeometry(geometry: GeometryType | null | undefined): boolean {
	return !!(geometry?.geojson?.type === 'Point' && Array.isArray(geometry.geojson.coordinates));
}

function formatGeometry(val: any): string {
	if (val == null) return '';
	try {
		const obj = typeof val === 'string' ? JSON.parse(val) : val;
		return prettyGeoJson(obj);
	} catch {
		return String(val);
	}
}

function parseGeometryValue(value: any): GeometryType | null {
	if (!value) return null;

	try {
		const parsed = typeof value === 'string' ? JSON.parse(value) : value;

		if (isValidGeometry(parsed)) return parsed;

		if (isValidGeoJSON(parsed)) {
			return { geojson: parsed, srid: 4326, ...extractPointCoords(parsed) };
		}

		if (isWrappedGeoJSON(parsed)) {
			const gj = parsed.geojson;
			return { geojson: gj, srid: Number(parsed.srid) || 4326, ...extractPointCoords(gj) };
		}

		if (isBarePoint(parsed)) {
			const geojson = { type: 'Point' as const, coordinates: [parsed.x, parsed.y] };
			return { geojson, srid: 4326, x: parsed.x, y: parsed.y };
		}

		return null;
	} catch {
		return null;
	}
}

/**
 * GeoJSON text for editing: indented like JSON.stringify(…, null, 2), but each position
 * (an array of numbers) stays on one line, so a polygon reads as one corner per line.
 */
function prettyGeoJson(value: unknown): string {
	return JSON.stringify(value, null, 2).replace(/\[\s*(-?[\d.eE+-]+(?:,\s*-?[\d.eE+-]+)*)\s*\]/g, (_match, numbers: string) =>
		`[${numbers.split(/,\s*/).join(', ')}]`,
	);
}

// Geometry placeholder examples by type
const GEOMETRY_PLACEHOLDERS: Record<string, string> = {
	Point: prettyGeoJson({ type: 'Point', coordinates: [0, 0] }),
	Polygon: prettyGeoJson({ type: 'Polygon', coordinates: [[[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]]] }),
	LineString: prettyGeoJson({ type: 'LineString', coordinates: [[0, 0], [1, 1], [2, 0]] }),
	MultiPoint: prettyGeoJson({ type: 'MultiPoint', coordinates: [[0, 0], [1, 1]] }),
	MultiPolygon: prettyGeoJson({ type: 'MultiPolygon', coordinates: [[[[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]]]] }),
	MultiLineString: prettyGeoJson({ type: 'MultiLineString', coordinates: [[[0, 0], [1, 1]], [[2, 2], [3, 3]]] }),
};
const DEFAULT_GEOMETRY_PLACEHOLDER = GEOMETRY_PLACEHOLDERS.Point;

interface GeometryEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	/** Expected geometry type from column definition (e.g., "Point", "Polygon", "LineString") */
	expectedType?: string;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** The column takes no value, so Clear is offered. */
	nullable?: boolean;
}

// The Map / GeoJSON switch, sized for this 28px header. The shared tab sizes are for page
// tabs (a 40px minimum height for touch), so here every tab is 24px inside a 28px track:
// a 2px inset on all sides, and the tab corners are the track's 8px minus that inset (the
// shared tab already uses radius-md - 2px). The focus ring is drawn inside the tab so it
// stays within the track. Icons are 12px with a little less padding on their side.
const SWITCH_TRACK = 'h-7 p-0.5';
const SWITCH_TAB =
	'h-6 min-h-0 min-w-0 gap-1.5 ps-2 pe-2.5 text-xs pointer-coarse:min-h-0 focus-visible:ring-2 focus-visible:ring-inset [&_svg]:size-3';

export const GeometryEditor: React.FC<GeometryEditorProps> = ({ value, onFinishedEditing, expectedType, title = 'Shape', nullable = false }) => {
	const currentGeometryData = value;
	const geometryValue = useMemo(() => parseGeometryValue(currentGeometryData), [currentGeometryData]);

	const [editingValue, setEditingValue] = useState<string>(() => {
		if (!currentGeometryData) return '';
		// Normalize to raw GeoJSON — the backend GeoJSON scalar only accepts { type, coordinates }
		const geo = parseGeometryValue(currentGeometryData);
		if (geo?.geojson) return prettyGeoJson(geo.geojson);
		return formatGeometry(currentGeometryData);
	});

	// Only show map when we KNOW it's a Point: either expectedType says so, or existing value is a Point.
	// For empty cells without expectedType, default to JSON tab (prevents Point-on-Polygon errors).
	// A host that turns the map tiles off (SheetsConfig.map.tiles: 'off') gets the GeoJSON text editor.
	const mapSettings = useMapSettings();
	const canShowMap =
		mapSettings.tiles !== null &&
		(expectedType === 'Point' || (!expectedType && geometryValue != null && isPointGeometry(geometryValue)));
	// The map is optional (leaflet peers): when it cannot load, the shape is edited as GeoJSON text.
	const [mapUnavailable, setMapUnavailable] = useState(false);
	const showMap = canShowMap && !mapUnavailable;

	const validationResult = useMemo(() => validateGeometry(editingValue, expectedType), [editingValue, expectedType]);
	const isValid = validationResult === true;
	const validationError = typeof validationResult === 'string' ? validationResult : undefined;
	const [activeTab, setActiveTab] = useState<'map' | 'json'>(() => (canShowMap ? 'map' : 'json'));

	const handleMapUnavailable = useCallback((error: unknown) => {
		sheetsLogger().warn('The map editor could not load; editing the shape as GeoJSON.', error);
		setMapUnavailable(true);
		setActiveTab('json');
	}, []);

	const handleMapChange = useCallback((mapValue: MapPickerValue | undefined) => {
		if (mapValue?.geojson?.type) {
			setEditingValue(prettyGeoJson(mapValue.geojson));
		} else {
			setEditingValue('');
		}
	}, []);

	const handleSave = useCallback(() => {
		if (!isValid) return;

		let finalValue: string;

		if (!editingValue.trim()) {
			finalValue = '';
		} else {
			try {
				const parsed = JSON.parse(editingValue);
				// Backend GeoJSON scalar requires { type: "Point", ... } at the top level
				finalValue = JSON.stringify(extractRawGeoJSON(parsed) ?? parsed);
			} catch {
				finalValue = editingValue;
			}
		}

		onFinishedEditing(finalValue);
	}, [editingValue, isValid, onFinishedEditing]);

	const handleCancel = useCallback(() => {
		onFinishedEditing();
	}, [onFinishedEditing]);

	const handleEditorKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
				e.preventDefault();
				if (isValid) handleSave();
			}
		},
		[isValid, handleSave],
	);

	const mapPickerValue = useMemo(() => {
		try {
			if (editingValue) {
				const raw = extractRawGeoJSON(JSON.parse(editingValue));
				if (raw) return raw;
			}
		} catch {
			// fall back to initial value on parse error
		}
		if (geometryValue && isPointGeometry(geometryValue)) {
			return geometryValue.geojson;
		}
		return undefined;
	}, [editingValue, geometryValue]);

	// Viewport-aware scroll budget (same pattern as relation-editor)
	const { maxHeight: overlayMaxHeight } = useContext(OverlayMeasureContext);
	const editorRef = useRef<HTMLDivElement>(null);
	const contentRef = useRef<HTMLDivElement>(null);
	const [scrollBudget, setScrollBudget] = useState<number | undefined>();

	useLayoutEffect(() => {
		const editor = editorRef.current;
		const content = contentRef.current;
		if (!editor || !content || overlayMaxHeight <= 0) return;
		const fixedUI = editor.scrollHeight - content.scrollHeight;
		setScrollBudget(Math.max(0, overlayMaxHeight - fixedUI));
	}, [overlayMaxHeight]);

	const shapeKind = expectedType ? shapeKindName(expectedType) : null;
	// Shared header: the field's name and the kind of shape, like the other editors' titles,
	// with the Map / GeoJSON switch when the map can be used.
	const header = (
		<EditorHeader title={title} chip={shapeKind} className='px-3 pt-3 pb-2'>
			{showMap && (
				<TabsList className={SWITCH_TRACK}>
					<TabsTrigger value='map' className={SWITCH_TAB}>
						<Map aria-hidden />
						Map
					</TabsTrigger>
					<TabsTrigger value='json' className={SWITCH_TAB}>
						<FileText aria-hidden />
						GeoJSON
					</TabsTrigger>
				</TabsList>
			)}
		</EditorHeader>
	);

	// Shared JSON content
	const jsonContent = (
		<div className='space-y-3 p-3'>
			{mapUnavailable ? (
				<p role='status' className='text-muted-foreground text-xs'>
					The map is not available here. Edit the shape as GeoJSON.
				</p>
			) : null}
			<Textarea
				id='geometry-json'
				value={editingValue}
				onChange={(e) => setEditingValue(e.target.value)}
				className={cn('min-h-[200px] resize-none font-mono text-sm', !isValid && 'border-destructive')}
				placeholder={GEOMETRY_PLACEHOLDERS[expectedType ?? ''] ?? DEFAULT_GEOMETRY_PLACEHOLDER}
				autoFocus={!showMap || activeTab === 'json'}
			/>

			{validationError && (
				<div className='text-destructive flex items-center gap-2 text-sm'>
					<AlertCircle className='h-4 w-4 shrink-0' />
					{validationError}
				</div>
			)}

		</div>
	);

	// Shared footer: Clear (when the column takes no value) and Save, like every value editor.
	const footer = (
		<EditorFooter
			className='px-3 py-2'
			onSave={handleSave}
			saveShortcut={`${modifierKeyLabel()} Enter`}
			saveBlockedReason={isValid ? null : (validationError ?? 'Enter a valid GeoJSON shape.')}
			clear={editorClear(nullable, () => onFinishedEditing(null))}
		/>
	);

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			className={`bg-popover flex w-full ${OVERLAY.xl} flex-col overflow-hidden rounded-lg border shadow-lg`}
		>
			<div ref={editorRef} onKeyDown={handleEditorKeyDown} className='flex min-h-0 flex-1 flex-col'>
				{showMap ? (
					<Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as 'map' | 'json')} className='flex min-h-0 flex-1 flex-col'>
						{header}
						<div ref={contentRef} className='min-h-0 flex-1 overflow-y-auto border-t' style={{ maxHeight: scrollBudget }}>
							<TabsContent value='map' className='mt-0 p-3'>
								<MapLoadBoundary onUnavailable={handleMapUnavailable}>
									{/* The picker's search row, frame and location line render at once; only the map
									    itself (Leaflet, loaded on first use) waits, in a placeholder of the map's own
									    height, so the editor opens at its final size. */}
									<MapPicker
										value={mapPickerValue}
										onChange={handleMapChange}
										height={280}
										placeholder='Search for a location or click on the map...'
										tiles={mapSettings.tiles ?? undefined}
										placeSearch={mapSettings.placeSearch}
									/>
								</MapLoadBoundary>
							</TabsContent>
							<TabsContent value='json' className='mt-0'>
								{jsonContent}
							</TabsContent>
						</div>
						{footer}
					</Tabs>
				) : (
					<>
						{header}
						<div ref={contentRef} className='min-h-0 flex-1 overflow-y-auto border-t' style={{ maxHeight: scrollBudget }}>
							{jsonContent}
						</div>
						{footer}
					</>
				)}
			</div>
		</EditorFocusTrap>
	);
};

// The file editor for image, upload, upload-list and attachment cells.
//
// It reads the column from the table model (`column.value.file`: kind and
// whether the cell holds several files) and saves through the model-driven
// upload path: pick, drop or paste files; replace or remove them; reorder a
// list; open or download a stored file; watch each upload and cancel it. A
// draft row is created first. The cell write waits out the server's file
// confirmation and, if the editor closes, keeps going on the cell.
//
// State and the save sequence live in `uploads/editor/use-file-editor.ts`.

import React, { useCallback, useContext, useMemo, useRef } from 'react';
import { Loader2, LockIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { toast } from '@/components/ui/toast';

import type { ColumnModel, TableModel } from '@constructive-io/data';

import { fieldLabel } from '../../cell-types/field-label';
import { useTableModel } from '../../hooks/use-table-model';
import {
	fileWriteReason,
	rowKeyOfRow,
	useColumnMediaResolver,
	useFileCellWriter,
	useFileUploadState,
	type UploadResponse,
} from '../../hooks/use-sheets-upload';
import { sheetsRowKey, type SheetsRowIdentifier } from '../../row-identity';
import { FileDropzone } from '../../uploads/editor/file-dropzone';
import { FileEntryRow } from '../../uploads/editor/file-entry-row';
import { ADD_CONTROL, CLOSE_CONTROL, useEditorFocus } from '../../uploads/editor/use-editor-focus';
import { useFileEditor, type FileEditorPhase, type SaveTarget } from '../../uploads/editor/use-file-editor';
import { useOptionalFeedback } from '../feedback/feedback-context';
import { EditorHeader, modifierKeyLabel } from './editor-frame';
import { EditorFocusTrap } from './editor-focus-trap';
import { OVERLAY } from './overlay-presets';
import { OverlayMeasureContext } from './overlay-viewport-guard';
import type { DraftSubmitResult } from '../draft-types';

/** Data passed to onSaveComplete for the optimistic cell update. */
export interface ImageSaveData {
	imageData: UploadResponse;
}

interface ImageEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	tableName?: string;
	fieldName?: string;
	recordId?: SheetsRowIdentifier | null;
	/** Grid row id of the cell (keys its pending state). Defaults to the record id. */
	rowId?: string;
	onSaveComplete?: (data: ImageSaveData) => void;
	isDraftRow?: boolean;
	onSubmitDraft?: () => Promise<DraftSubmitResult>;
	onDraftUploadComplete?: () => void;
	/** Without a column model: accept any file (true) or images only (false). */
	acceptAnyFile?: boolean;
	/** The column model; resolved from `tableName` and `fieldName` when absent. */
	column?: ColumnModel | null;
	/** The table model; resolved from `tableName` when absent. */
	table?: TableModel | null;
	/** Why the cell cannot be written, from the grid; null when it can. */
	readOnlyReason?: string | null;
}

function phaseText(phase: FileEditorPhase, noun: string): string | null {
	switch (phase.name) {
		case 'creating-row': return 'Creating row…';
		case 'uploading': return `Uploading ${noun}…`;
		case 'saving': return 'Saving…';
		case 'processing': return 'Processing file… The cell is saved as soon as the storage service accepts the file. You can close this.';
		case 'failed': return phase.message;
		default: return null;
	}
}

export const ImageEditor: React.FC<ImageEditorProps> = ({
	value,
	onFinishedEditing,
	tableName,
	fieldName,
	recordId,
	rowId,
	onSaveComplete,
	isDraftRow = false,
	onSubmitDraft,
	onDraftUploadComplete,
	acceptAnyFile = false,
	column: columnProp,
	table: tableProp,
	readOnlyReason,
}) => {
	const { maxHeight: overlayMaxHeight } = useContext(OverlayMeasureContext);
	const inputRef = useRef<HTMLInputElement>(null);
	const editorRef = useRef<HTMLDivElement>(null);

	const resolved = useTableModel(tableName ?? null);
	const table = tableProp ?? resolved.model;
	const column = columnProp ?? table?.columns.find((candidate) => candidate.name === fieldName) ?? null;
	const fileModel = column?.value.file ?? null;
	const kind = fileModel?.kind ?? (acceptAnyFile ? 'upload' : 'image');
	const multiple = Boolean(fileModel?.multiple);
	const noun = multiple ? 'files' : kind === 'image' ? 'image' : 'file';
	const Noun = kind === 'attachment' ? 'Link' : multiple ? 'Files' : kind === 'image' ? 'Image' : 'File';
	// The shared frame's title: the field's readable name (the raw name in the tooltip), the kind as its chip.
	const rawName = column?.name ?? fieldName ?? '';

	const writeReason = readOnlyReason ?? fileWriteReason(table, column);
	const upload = useFileUploadState(table, column, writeReason);
	const media = useColumnMediaResolver(table, column);
	const write = useFileCellWriter();

	const target = useMemo<SaveTarget | null>(
		() => (recordId != null && !isDraftRow ? { rowKey: recordId, rowId: rowId ?? String(recordId) } : null),
		[isDraftRow, recordId, rowId],
	);
	const metaTable = resolved.metaTable;
	const targetOfCreatedRow = useCallback((row: Record<string, unknown>): SaveTarget | null => {
		if (!table) return null;
		const rowKey = rowKeyOfRow(table, row);
		if (rowKey == null) return null;
		return { rowKey, rowId: metaTable ? sheetsRowKey(metaTable, row, 0) : typeof rowKey === 'object' ? JSON.stringify(rowKey) : String(rowKey) };
	}, [metaTable, table]);

	// The grid's save status reports the save once the editor closes; outside a grid, a toast does.
	const noteWrite = useOptionalFeedback()?.noteWrite;
	const onSaved = useCallback((saved: unknown, info: { createdRow: boolean }) => {
		if (info.createdRow) onDraftUploadComplete?.();
		else onSaveComplete?.({ imageData: saved });
		const message = saved == null || (Array.isArray(saved) && saved.length === 0) ? `${Noun} cleared` : `${Noun} saved`;
		if (noteWrite) noteWrite('update', 'success', message);
		else toast.success({ message });
		onFinishedEditing();
	}, [Noun, noteWrite, onDraftUploadComplete, onFinishedEditing, onSaveComplete]);

	const editor = useFileEditor({
		value,
		table,
		column,
		multiple,
		upload,
		write,
		target,
		submitDraft: isDraftRow ? onSubmitDraft : undefined,
		targetOfCreatedRow,
		onUploadError: (message) => toast.error({ message }),
		onRowCreated: onDraftUploadComplete,
		onSaved,
	});
	const { entries, phase, busy, dirty, addFiles } = editor;

	const writeBlocked = writeReason != null;
	const uploadBlocked = upload.status !== 'ready';
	const uploadReason = upload.status === 'unavailable' ? upload.reason : null;
	const canAdd = !writeBlocked && !uploadBlocked && !busy;
	useEditorFocus(editorRef, canAdd);

	const takeFiles = useCallback((files: readonly File[]) => {
		if (!canAdd || files.length === 0) return;
		if (kind === 'image') {
			const images = files.filter((file) => file.type.startsWith('image/'));
			if (images.length < files.length) toast.error({ message: 'Please select an image file' });
			addFiles(images);
			return;
		}
		addFiles(files);
	}, [addFiles, canAdd, kind]);

	const openPicker = useCallback(() => inputRef.current?.click(), []);
	const hasNewFiles = entries.some((entry) => entry.file && entry.status !== 'uploaded');
	const save = editor.save;
	const close = useCallback(() => {
		// A write already sent keeps going on the cell; only uploads in flight stop.
		editor.cancelUploads();
		onFinishedEditing();
	}, [editor, onFinishedEditing]);

	const primaryLabel = phase.name === 'creating-row' ? 'Creating…'
		: phase.name === 'uploading' ? 'Uploading…'
		: phase.name === 'saving' ? 'Saving…'
		: phase.name === 'processing' ? 'Processing file…'
		: hasNewFiles ? (editor.needsRowCreation ? 'Create Row & Upload' : 'Upload & Save')
		: phase.name === 'failed' ? 'Retry saving'
		: dirty ? 'Save' : 'Done';
	const primaryAction = () => (hasNewFiles || dirty || phase.name === 'failed' ? void save() : onFinishedEditing());

	const status = phaseText(phase, noun);
	// While storage is still resolving the dropzone shows, disabled; a reason hides it.
	const showDropzone = !writeBlocked && upload.status !== 'unavailable' && (multiple || entries.length === 0);
	const hint = upload.status === 'loading'
		? 'Checking storage…'
		: kind === 'image' ? 'Images only' : kind === 'attachment' ? 'Any file; the cell keeps a link to it' : 'Any file type';

	return (
		<EditorFocusTrap
			onEscape={close}
			className={`bg-popover flex ${OVERLAY.lg} flex-col gap-0 overflow-hidden rounded-lg border p-0 shadow-lg`}
			style={overlayMaxHeight > 0 ? { maxHeight: overlayMaxHeight } : undefined}
		>
			<div
				ref={editorRef}
				className="flex min-h-0 flex-1 flex-col"
				data-upload-state={upload.status}
				onKeyDown={(event) => {
					if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
						event.preventDefault();
						primaryAction();
					}
				}}
				onPaste={(event) => {
					const files = Array.from(event.clipboardData?.files ?? []);
					if (files.length === 0) return;
					event.preventDefault();
					takeFiles(files);
				}}
			>
				<EditorHeader
					title={rawName ? fieldLabel(rawName) : Noun}
					titleHint={rawName || undefined}
					chip={Noun}
					className="shrink-0 px-3 pt-3 pb-2"
				/>

				<input
					ref={inputRef}
					type="file"
					multiple={multiple}
					accept={kind === 'image' ? 'image/*' : undefined}
					className="hidden"
					aria-label={`Upload ${noun}`}
					tabIndex={-1}
					onChange={(event) => {
						takeFiles(Array.from(event.target.files ?? []));
						event.target.value = '';
					}}
				/>

				<div className="min-h-0 flex-1 overflow-y-auto border-t">
					<div className="flex flex-col gap-3 p-3">
						{writeReason || uploadReason ? (
							<p role="note" className="flex items-start gap-2 rounded-md bg-muted/40 px-3 py-2 text-xs text-muted-foreground">
								<LockIcon className="mt-0.5 size-3 shrink-0" aria-hidden="true" />
								<span>{writeReason ?? uploadReason}</span>
							</p>
						) : null}

						{entries.length > 0 ? (
							<ul className="flex flex-col gap-1.5" aria-label={Noun}>
								{entries.map((entry, index) => (
									<FileEntryRow
										key={entry.key}
										entry={entry}
										kind={kind}
										resolver={media.resolver}
										reorder={multiple ? { index, count: entries.length } : null}
										disabled={busy}
										readOnly={writeBlocked}
										onMove={(delta) => editor.move(entry.key, delta)}
										onRemove={() => editor.remove(entry.key)}
									/>
								))}
							</ul>
						) : !showDropzone ? (
							<p className="py-6 text-center text-sm text-muted-foreground">No {noun}</p>
						) : null}

						{showDropzone ? (
							<FileDropzone
								noun={noun}
								hint={hint}
								disabled={!canAdd}
								compact={entries.length > 0}
								onPick={openPicker}
								onFiles={takeFiles}
							/>
						) : canAdd && !multiple && entries.length > 0 ? (
							<Button type="button" variant="outline" size="sm" className="self-start" onClick={openPicker} data-initial-focus={ADD_CONTROL}>
								Replace {noun}
							</Button>
						) : null}

						{status ? (
							<p
								role={phase.name === 'failed' ? 'alert' : 'status'}
								className={phase.name === 'failed' ? 'text-xs text-destructive' : 'flex items-center gap-1.5 text-xs text-muted-foreground'}
							>
								{phase.name !== 'failed' ? <Loader2 className="size-3 shrink-0 animate-spin" aria-hidden="true" /> : null}
								<span>{status}</span>
							</p>
						) : null}
					</div>
				</div>

				<div className="flex shrink-0 justify-end gap-2 border-t px-3 py-2">
					<Button type="button" variant="outline" size="xs" onClick={close} data-initial-focus={CLOSE_CONTROL}>
						{writeBlocked || phase.name === 'processing' || phase.name === 'saving' ? 'Close' : 'Cancel'}
					</Button>
					{!writeBlocked ? (
						<Button
							type="button"
							size="xs"
							onClick={primaryAction}
							disabled={busy || (hasNewFiles && uploadBlocked)}
							title={busy ? undefined : `${primaryLabel} (${modifierKeyLabel()} Enter)`}
						>
							{busy ? <Loader2 className="size-3.5 animate-spin" aria-hidden="true" /> : null}
							{primaryLabel}
						</Button>
					) : null}
				</div>
			</div>
		</EditorFocusTrap>
	);
};

import React, { useCallback, useEffect, useRef, useState } from 'react';


import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear } from './editor-frame';
import { OVERLAY } from './overlay-presets';

const IPV4_RE = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
const IPV6_FULL_RE = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;
const IPV6_COMPRESSED_RE =
	/^([0-9a-fA-F]{1,4}:)*::([0-9a-fA-F]{1,4}:)*[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:)*::[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:)*::$/;

interface InetEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** The column takes no value, so Clear is offered. */
	nullable?: boolean;
}

function isValidIPv4(ip: string): boolean {
	return IPV4_RE.test(ip);
}

function isValidIPv6(ip: string): boolean {
	return IPV6_FULL_RE.test(ip) || IPV6_COMPRESSED_RE.test(ip);
}

function isValidCIDR(cidr: string): boolean {
	const parts = cidr.split('/');
	if (parts.length !== 2) return false;

	const [ip, prefix] = parts;
	const prefixNum = parseInt(prefix, 10);

	if (isValidIPv4(ip)) {
		return prefixNum >= 0 && prefixNum <= 32;
	} else if (isValidIPv6(ip)) {
		return prefixNum >= 0 && prefixNum <= 128;
	}

	return false;
}

function isValidInet(value: string): boolean {
	if (!value || typeof value !== 'string') return false;

	const trimmed = value.trim();

	if (trimmed.includes('/')) {
		return isValidCIDR(trimmed);
	}

	return isValidIPv4(trimmed) || isValidIPv6(trimmed);
}

function getInetType(value: string): string {
	if (!value) return '';

	const trimmed = value.trim();

	if (trimmed.includes('/')) {
		const [ip] = trimmed.split('/');
		if (isValidIPv4(ip)) return 'IPv4 Network';
		if (isValidIPv6(ip)) return 'IPv6 Network';
	} else {
		if (isValidIPv4(trimmed)) return 'IPv4 Address';
		if (isValidIPv6(trimmed)) return 'IPv6 Address';
	}

	return 'Invalid';
}

export const InetEditor: React.FC<InetEditorProps> = ({ value, onFinishedEditing, title = 'Network address', nullable = false }) => {
	const currentInetData = typeof value === 'string' ? value : '';
	const [editingValue, setEditingValue] = useState<string>(currentInetData);
	const [validationError, setValidationError] = useState<string>('');
	const keyContainerRef = useRef<HTMLDivElement>(null);

	const handleSave = useCallback(() => {
		if (editingValue.trim() && !isValidInet(editingValue.trim())) {
			setValidationError('Invalid IP address or CIDR');
			return;
		}

		onFinishedEditing(editingValue.trim());
	}, [editingValue, onFinishedEditing]);

	const handleCancel = useCallback(() => {
		onFinishedEditing();
	}, [onFinishedEditing]);

	const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
		setEditingValue(e.target.value);
		setValidationError('');
	}, []);

	// Refs for native key handler
	const actionsRef = useRef({ handleSave, handleCancel });
	actionsRef.current = { handleSave, handleCancel };

	// Native DOM keydown listener — prevents Glide from intercepting keys in portal context
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { handleSave, handleCancel } = actionsRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if (e.key === 'Enter' && !e.metaKey && !e.ctrlKey) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			// Stop Tab from reaching Glide
			if (e.key === 'Tab') {
				e.stopPropagation();
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	const trimmed = editingValue.trim();
	const isValid = !trimmed || isValidInet(trimmed);
	const inetType = trimmed ? getInetType(trimmed) : '';

	return (
		<EditorFocusTrap
			onEscape={handleCancel}
			className={`bg-popover ${OVERLAY.sm} rounded-lg border p-2.5 shadow-lg`}
		>
			<div ref={keyContainerRef} className='flex flex-col gap-2'>
				<EditorHeader title={title} className='px-1' />
				{/* Input + inline type badge */}
				<div className='space-y-1.5'>
					<div className='relative'>
						<input
							type='text'
							value={editingValue}
							onChange={handleInputChange}
							placeholder='192.168.1.1 or 10.0.0.0/24'
							className='bg-muted/40 border-border/40 text-foreground w-full rounded-md border px-3 py-2 font-mono text-sm outline-none focus-visible:border-ring/60 focus-visible:ring-[3px] focus-visible:ring-ring/35'
							autoFocus
						/>
					</div>

					{/* Inline type indicator + validation */}
					<div className='flex items-center gap-2 px-0.5'>
						{validationError ? (
							<span className='text-destructive text-xs'>{validationError}</span>
						) : trimmed && isValid && inetType ? (
							<span className='text-muted-foreground text-xs tabular-nums'>{inetType}</span>
						) : trimmed && !isValid ? (
							<span className='text-destructive text-xs'>Invalid format</span>
						) : null}
					</div>
				</div>

				<EditorFooter
					className='px-1'
					onSave={handleSave}
					saveShortcut='Enter'
					saveBlockedReason={validationError || null}
					clear={editorClear(nullable, () => onFinishedEditing(null))}
				/>
			</div>
		</EditorFocusTrap>
	);
};

import React, { useCallback, useState } from 'react';

import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear, modifierKeyLabel } from './editor-frame';
import { OVERLAY } from './overlay-presets';

interface IntervalValue {
	days?: number;
	hours?: number;
	minutes?: number;
	seconds?: number;
}

interface IntervalEditorProps {
	value: unknown;
	onFinishedEditing: (next?: unknown) => void;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** The column takes no value, so Clear is offered. */
	nullable?: boolean;
}

const INTERVAL_PATTERNS: { regex: RegExp; key: keyof IntervalValue }[] = [
	{ regex: /(\d+)\s*d(ays?)?/i, key: 'days' },
	{ regex: /(\d+)\s*h(ours?)?/i, key: 'hours' },
	{ regex: /(\d+)\s*m(in(utes?)?)?/i, key: 'minutes' },
	{ regex: /(\d+)\s*s(ec(onds?)?)?/i, key: 'seconds' },
];

function parseIntervalValue(data: string): IntervalValue {
	if (!data || typeof data !== 'string') {
		return { days: 0, hours: 0, minutes: 0, seconds: 0 };
	}

	try {
		const parsed = JSON.parse(data);
		if (typeof parsed === 'object' && parsed !== null) {
			return {
				days: parsed.days || 0,
				hours: parsed.hours || 0,
				minutes: parsed.minutes || 0,
				seconds: parsed.seconds || 0,
			};
		}
	} catch {
		// Try to parse text format like "1d 2h 30m 45s"
		const interval: IntervalValue = { days: 0, hours: 0, minutes: 0, seconds: 0 };

		INTERVAL_PATTERNS.forEach(({ regex, key }) => {
			const match = data.match(regex);
			if (match) {
				interval[key] = parseInt(match[1], 10);
			}
		});

		return interval;
	}

	return { days: 0, hours: 0, minutes: 0, seconds: 0 };
}

function formatIntervalValue(interval: IntervalValue): string {
	const parts = [];
	if (interval.days && interval.days > 0) parts.push(`${interval.days}d`);
	if (interval.hours && interval.hours > 0) parts.push(`${interval.hours}h`);
	if (interval.minutes && interval.minutes > 0) parts.push(`${interval.minutes}m`);
	if (interval.seconds && interval.seconds > 0) parts.push(`${interval.seconds}s`);
	return parts.join(' ') || '0s';
}

export const IntervalEditor: React.FC<IntervalEditorProps> = ({ value, onFinishedEditing, title = 'Duration', nullable = false }) => {
	// Extract current interval data from the raw value
	const currentIntervalData = typeof value === 'string' ? value : '';

	const [editingValue, setEditingValue] = useState<IntervalValue>(() => parseIntervalValue(currentIntervalData));

	const handleSave = useCallback(() => {
		onFinishedEditing(JSON.stringify(editingValue));
	}, [editingValue, onFinishedEditing]);

	const handleCancel = useCallback(() => {
		onFinishedEditing();
	}, [onFinishedEditing]);

	const handleInputChange = useCallback((field: keyof IntervalValue, newValue: string) => {
		const numValue = parseInt(newValue) || 0;
		setEditingValue((prev) => ({
			...prev,
			[field]: Math.max(0, numValue), // Ensure non-negative values
		}));
	}, []);

	// Handle Ctrl+Enter to save
	const handleEditorKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
				e.preventDefault();
				handleSave();
			}
		},
		[handleSave],
	);

	const previewText = formatIntervalValue(editingValue);

	return (
		<EditorFocusTrap onEscape={handleCancel} className={`bg-popover flex ${OVERLAY.sm} flex-col gap-3 rounded-lg border p-3 shadow-lg`}>
			<div onKeyDown={handleEditorKeyDown} className='flex flex-col gap-3'>
			<EditorHeader title={title} />

			{/* Input Fields */}
			<div className='grid grid-cols-2 gap-3'>
				<div className='space-y-1'>
					<Label htmlFor='days' className='text-muted-foreground text-xs'>
						Days
					</Label>
					<Input
						id='days'
						type='number'
						min='0'
						value={editingValue.days || ''}
						onChange={(e) => handleInputChange('days', e.target.value)}
						className='h-8 text-sm'
						placeholder='0'
					/>
				</div>
				<div className='space-y-1'>
					<Label htmlFor='hours' className='text-muted-foreground text-xs'>
						Hours
					</Label>
					<Input
						id='hours'
						type='number'
						min='0'
						max='23'
						value={editingValue.hours || ''}
						onChange={(e) => handleInputChange('hours', e.target.value)}
						className='h-8 text-sm'
						placeholder='0'
					/>
				</div>
				<div className='space-y-1'>
					<Label htmlFor='minutes' className='text-muted-foreground text-xs'>
						Minutes
					</Label>
					<Input
						id='minutes'
						type='number'
						min='0'
						max='59'
						value={editingValue.minutes || ''}
						onChange={(e) => handleInputChange('minutes', e.target.value)}
						className='h-8 text-sm'
						placeholder='0'
					/>
				</div>
				<div className='space-y-1'>
					<Label htmlFor='seconds' className='text-muted-foreground text-xs'>
						Seconds
					</Label>
					<Input
						id='seconds'
						type='number'
						min='0'
						max='59'
						value={editingValue.seconds || ''}
						onChange={(e) => handleInputChange('seconds', e.target.value)}
						className='h-8 text-sm'
						placeholder='0'
					/>
				</div>
			</div>

			{/* Preview */}
			<div className='space-y-1'>
				<Label className='text-muted-foreground text-xs'>Preview</Label>
				<div className='bg-muted rounded px-3 py-2 font-mono text-sm'>{previewText}</div>
			</div>

			<EditorFooter
				onSave={handleSave}
				saveShortcut={`${modifierKeyLabel()} Enter`}
				clear={editorClear(nullable, () => onFinishedEditing(null))}
			/>
			</div>
		</EditorFocusTrap>
	);
};

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';


import { EditorFocusTrap } from './editor-focus-trap';
import { EditorFooter, EditorHeader, editorClear, modifierKeyLabel } from './editor-frame';
import { OVERLAY } from './overlay-presets';


const JSON_HIGHLIGHT_STYLES = `
.json-highlight .jh-key { color: var(--color-foreground); }
.json-highlight .jh-str { color: oklch(0.72 0.14 168); }
.json-highlight .jh-num { color: oklch(0.7 0.14 250); }
.json-highlight .jh-bool { color: oklch(0.75 0.14 55); }
.json-highlight .jh-punct { color: var(--color-muted-foreground); }
@media (prefers-color-scheme: light) {
	.json-highlight .jh-str { color: oklch(0.5 0.16 168); }
	.json-highlight .jh-num { color: oklch(0.48 0.16 250); }
	.json-highlight .jh-bool { color: oklch(0.55 0.16 55); }
}
`;

// Zero-dependency JSON syntax highlighter using regex tokenisation.
// Returns HTML string with spans for: strings, numbers, booleans/null, keys, punctuation.
function highlightJson(json: string): string {
	// Escape HTML entities first
	const escaped = json.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

	return escaped.replace(
		// Match JSON tokens: strings, numbers, booleans, null, structural chars
		/("(?:[^"\\]|\\.)*")\s*(?=:)|("(?:[^"\\]|\\.)*")|(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\b|(true|false|null)\b|([{}[\]:,])/g,
		(match, key, str, num, bool, punct) => {
			if (key !== undefined) return `<span class="jh-key">${key}</span>`;
			if (str !== undefined) return `<span class="jh-str">${str}</span>`;
			if (num !== undefined) return `<span class="jh-num">${num}</span>`;
			if (bool !== undefined) return `<span class="jh-bool">${bool}</span>`;
			if (punct !== undefined) return `<span class="jh-punct">${punct}</span>`;
			return match;
		},
	);
}

type Props = {
	value: unknown;
	onChange: (next: unknown) => void;
	onFinished: (next?: unknown) => void;
	/** The field's readable name, shown as the title. */
	title?: string;
	/** The column takes no value, so Clear is offered. */
	nullable?: boolean;
};

export function JsonEditor({ value, onChange, onFinished, title = 'JSON value', nullable = false }: Props) {
	const [text, setText] = useState(() => (typeof value === 'string' ? value : JSON.stringify(value, null, 2)));
	const textareaRef = useRef<HTMLTextAreaElement>(null);
	const preRef = useRef<HTMLPreElement>(null);
	const keyContainerRef = useRef<HTMLDivElement>(null);

	const { parsed, valid } = useMemo(() => {
		// An empty text is a valid "no value".
		if (text.trim() === '') return { parsed: null, valid: true };
		try {
			return { parsed: JSON.parse(text), valid: true };
		} catch {
			return { parsed: text, valid: false };
		}
	}, [text]);

	const handleChange = useCallback(
		(e: React.ChangeEvent<HTMLTextAreaElement>) => {
			const next = e.target.value;
			setText(next);
			try {
				onChange(JSON.parse(next));
			} catch {
				// invalid JSON — don't propagate
			}
		},
		[onChange],
	);

	const handleCancel = useCallback(() => onFinished(undefined), [onFinished]);
	const handleSave = useCallback(() => {
		if (valid) onFinished(parsed);
	}, [onFinished, parsed, valid]);

	// Sync scroll between textarea and highlighted pre
	const handleScroll = useCallback(() => {
		const ta = textareaRef.current;
		const pre = preRef.current;
		if (ta && pre) {
			pre.scrollTop = ta.scrollTop;
			pre.scrollLeft = ta.scrollLeft;
		}
	}, []);

	// Refs for native key handler
	const actionsRef = useRef({ handleSave, handleCancel });
	actionsRef.current = { handleSave, handleCancel };

	// Native DOM keydown listener — prevents Glide from intercepting keys
	useEffect(() => {
		const el = keyContainerRef.current;
		if (!el) return;
		const handler = (e: KeyboardEvent) => {
			const { handleSave, handleCancel } = actionsRef.current;

			if (e.key === 'Escape') {
				e.preventDefault();
				e.stopPropagation();
				handleCancel();
				return;
			}
			if ((e.key === 'Enter' && (e.metaKey || e.ctrlKey)) || (e.key === 's' && (e.metaKey || e.ctrlKey))) {
				e.preventDefault();
				e.stopPropagation();
				handleSave();
				return;
			}
			// Stop Tab from reaching Glide (allow default tab-indent behavior)
			if (e.key === 'Tab') {
				e.stopPropagation();
				// Insert tab character at cursor
				e.preventDefault();
				const ta = textareaRef.current;
				if (ta) {
					const start = ta.selectionStart;
					const end = ta.selectionEnd;
					const val = ta.value;
					const newVal = val.substring(0, start) + '  ' + val.substring(end);
					ta.value = newVal;
					ta.selectionStart = ta.selectionEnd = start + 2;
					ta.dispatchEvent(new Event('input', { bubbles: true }));
				}
			}
		};
		el.addEventListener('keydown', handler);
		return () => el.removeEventListener('keydown', handler);
	}, []);

	// Memoize highlighted HTML
	const highlighted = useMemo(() => highlightJson(text), [text]);


	return (
		<EditorFocusTrap onEscape={handleCancel} className={`bg-popover ${OVERLAY.lg} rounded-lg border p-2.5 shadow-lg`}>
			<div ref={keyContainerRef} className='flex flex-col gap-2'>
				<EditorHeader title={title} className='px-1' />
				{/* Editor area — grid overlay technique for matched sizing */}
				<div
					className='bg-muted/40 grid cursor-text overflow-hidden rounded-md border border-border/40'
					style={{ height: 300 }}
					onClick={() => textareaRef.current?.focus()}
				>
					{/* Both layers occupy the same grid cell */}
					<pre
						ref={preRef}
						className='json-highlight pointer-events-none col-start-1 row-start-1 m-0 overflow-hidden whitespace-pre-wrap break-words bg-transparent p-3 font-mono text-sm leading-relaxed [word-break:break-all]'
						aria-hidden='true'
						dangerouslySetInnerHTML={{ __html: highlighted + '\n' }}
					/>
					<textarea
						ref={textareaRef}
						value={text}
						onChange={handleChange}
						onScroll={handleScroll}
						spellCheck={false}
						className='col-start-1 row-start-1 m-0 resize-none overflow-auto whitespace-pre-wrap break-words bg-transparent p-3 font-mono text-sm leading-relaxed text-transparent outline-none [word-break:break-all]'
						style={{ caretColor: 'var(--color-foreground)' }}
						autoFocus
					/>
				</div>

				<EditorFooter
					className='px-1'
					onSave={handleSave}
					saveShortcut={`${modifierKeyLabel()} Enter`}
					saveBlockedReason={valid ? null : 'Enter valid JSON.'}
					status={valid ? null : <span className='text-destructive'>Not valid JSON</span>}
					clear={editorClear(nullable, () => onFinished(null))}
				/>

				{/* Syntax highlighting styles — uses CSS variables for theme compatibility */}
				<style>{JSON_HIGHLIGHT_STYLES}</style>
			</div>
		</EditorFocusTrap>
	);
}

