import { cn } from '../../utils/cn';

function getErrorMessage(error: unknown): string {
	if (error instanceof Error) return error.message;
	if (typeof error === 'string') return error;
	return 'Something went wrong while loading this table.';
}


interface SheetsStateShellProps {
	className?: string;
	children: React.ReactNode;
}

/** Centered, full-size container shared by the error/empty/loading states. */
function SheetsStateShell({ className, children }: SheetsStateShellProps) {
	return (
		<div
			className={cn(
				'bg-background flex h-full min-h-0 flex-1 flex-col items-center justify-center gap-3 rounded-lg border p-8 text-center',
				className,
			)}
		>
			{children}
		</div>
	);
}

interface SheetsErrorStateProps {
	error: unknown;
	onRetry?: () => void;
	/** The table that failed. Only this table's grid shows the error; other tables keep working. */
	tableName?: string;
}

/** Shown when one table's rows (or its model) fail to load. */
export function SheetsErrorState({ error, onRetry, tableName }: SheetsErrorStateProps) {
	return (
		<SheetsStateShell>
			<RiErrorWarningLine className='text-destructive h-8 w-8' aria-hidden='true' />
			<div className='space-y-1' role='alert'>
				<p className='text-foreground text-sm font-medium'>Failed to load data</p>
				{tableName && <p className='text-muted-foreground text-sm'>The table “{tableName}” could not be loaded.</p>}
				<p className='text-muted-foreground max-w-md text-sm'>{getErrorMessage(error)}</p>
			</div>
			{onRetry && (
				<Button variant='outline' size='sm' onClick={onRetry}>
					Retry
				</Button>
			)}
		</SheetsStateShell>
	);
}

interface SheetsEmptyStateProps {
	tableName?: string;
	onAddRow?: () => void;
	readOnlyReason?: string | null;
}

/** Shown when the table loaded successfully but has no rows. */
export function SheetsEmptyState({ tableName, onAddRow, readOnlyReason }: SheetsEmptyStateProps) {
	return (
		<SheetsStateShell>
			<RiInboxLine className='text-muted-foreground h-8 w-8' />
			<div className='space-y-1'>
				<p className='text-foreground text-sm font-medium'>No rows yet</p>
				<p className='text-muted-foreground max-w-md text-sm'>
					{readOnlyReason ?? (tableName ? `The “${tableName}” table is empty.` : 'This table is empty.')}
				</p>
			</div>
			{onAddRow && (
				<Button variant='outline' size='sm' onClick={onAddRow}>
					<RiAddLine className='h-4 w-4' />
					<span>Add row</span>
				</Button>
			)}
		</SheetsStateShell>
	);
}

/** Column-width hints (px) for the skeleton bars — varied so it reads as a real table. */
const SKELETON_COLS = [120, 88, 152, 64, 108, 132, 80];
const SKELETON_ROWS = 12;

/**
 * Shown during the initial data load. A STRUCTURAL skeleton of the grid (baseline-ui:
 * prefer skeletons over spinners) — mirrors the real grid's 40px header + 44px rows +
 * horizontal hairlines so the load→loaded swap doesn't jump. Pulse is motion-safe only.
 */
export function SheetsLoadingState() {
	return (
		<div
			className='bg-background flex h-full min-h-0 flex-1 flex-col overflow-hidden rounded-lg border'
			role='status'
			aria-busy='true'
			aria-label='Loading data'
		>
			<div className='flex shrink-0 items-center gap-6 border-b px-3' style={{ height: 40 }}>
				{SKELETON_COLS.map((w, i) => (
					<div key={i} className='bg-muted h-2.5 shrink-0 rounded-sm' style={{ width: Math.round(w * 0.7) }} />
				))}
			</div>
			{Array.from({ length: SKELETON_ROWS }).map((_, r) => (
				<div key={r} className='flex shrink-0 items-center gap-6 border-b px-3' style={{ height: 44 }}>
					{SKELETON_COLS.map((w, i) => (
						<div key={i} className='bg-muted/60 h-3 shrink-0 rounded-sm motion-safe:animate-pulse' style={{ width: w }} />
					))}
				</div>
			))}
		</div>
	);
}

'use client';

import { RiCloseLine, RiErrorWarningLine } from '@remixicon/react';

import { cn } from '../../utils/cn';
import { useFeedback } from './feedback-context';

/**
 * Failed writes, each with every message the server returned. They stay until
 * the user dismisses them, so a message is never lost to a timeout.
 */
export function WriteErrorStack({ className }: { className?: string }) {
	const { state, dismissWriteError } = useFeedback();
	if (state.writeErrors.length === 0) return null;
	return (
		<div className={cn('pointer-events-auto flex w-[min(28rem,calc(100vw-2rem))] flex-col gap-2', className)} data-part-id='sheets-write-errors'>
			{state.writeErrors.map((report) => (
				<div
					key={report.id}
					role='alert'
					data-part-id='sheets-write-error'
					className='border-destructive/30 bg-background flex items-start gap-2 rounded-lg border px-3 py-2 shadow-lg'
				>
					<RiErrorWarningLine className='text-destructive mt-0.5 size-4 shrink-0' aria-hidden='true' />
					<div className='min-w-0 flex-1'>
						<p className='text-foreground text-sm font-medium [overflow-wrap:anywhere]'>{report.title}</p>
						{report.messages.length === 1 ? (
							<p className='text-muted-foreground text-sm [overflow-wrap:anywhere]'>{report.messages[0]}</p>
						) : (
							<ul className='text-muted-foreground list-disc ps-4 text-sm'>
								{report.messages.map((message) => (
									<li key={message} className='[overflow-wrap:anywhere]'>
										{message}
									</li>
								))}
							</ul>
						)}
					</div>
					<button
						type='button'
						className='text-muted-foreground hover:text-foreground -mr-1 rounded p-0.5'
						aria-label='Dismiss'
						onClick={() => dismissWriteError(report.id)}
					>
						<RiCloseLine className='size-4' aria-hidden='true' />
					</button>
				</div>
			))}
		</div>
	);
}

/**
 * What a failed write tells the user: every message the server returned, in
 * plain words, with a title that names the cell or row when the write did.
 * A permission refusal reads as a permission problem; only an explicit
 * authentication error means the session ended.
 */
import { getConstraintMessage, getErrorCode, isAuthenticationCode } from '@constructive-io/data';
import type { TableModel } from '@constructive-io/data';

import { fieldLabel } from '../../cell-types/field-label';
import { responseErrorsOf } from '../../context/sheets-execute';

export type WriteAction = 'update' | 'create' | 'delete';

const PERMISSION_CODES = new Set(['FORBIDDEN', '42501']);
const PERMISSION_TEXT = /\bpermission denied\b|\bnot allowed\b|\binsufficient privilege/i;

// The server's words when an update or delete matched no row it lets this user change.
const NOT_APPLIED_TEXT = /\bNo values were (?:updated|deleted) in collection\b/i;

const NOT_APPLIED_MESSAGES: Record<WriteAction, string> = {
	update: 'This record was not changed. You may not be allowed to change it, or it no longer exists.',
	create: 'This record was not created.',
	delete: 'This record was not deleted. You may not be allowed to delete it, or it no longer exists.',
};

const PERMISSION_MESSAGES: Record<WriteAction, string> = {
	update: 'You do not have permission to change this record.',
	create: 'You do not have permission to add records to this table.',
	delete: 'You do not have permission to delete this record.',
};

// A delete the database refuses because other rows still reference the record. The server
// sends no code for it, only its words, which name the referencing table.
const STILL_REFERENCED_TEXT = /\bviolates (?:RESTRICT setting of )?foreign key constraint "[^"]*" on table "([^"]+)"/i;

const RULE_CODES = new Set(['UNIQUE_VIOLATION', 'NOT_NULL_VIOLATION', 'CHECK_VIOLATION', 'FOREIGN_KEY_VIOLATION']);

interface MessageSource {
	message?: string | null;
	code?: string | null;
	context?: Readonly<Record<string, unknown>> | null;
}

/** A refusal the server classified (a database rule), in plain words. */
function ruleMessage(source: MessageSource, action: WriteAction): string | null {
	// A message registered for the exact constraint (or its suffix) says it best.
	const constraint = typeof source.context?.constraint === 'string' ? source.context.constraint : null;
	const registered = constraint ? getConstraintMessage(constraint) : undefined;
	if (registered && RULE_CODES.has(source.code ?? '')) return registered;
	switch (source.code) {
		case 'UNIQUE_VIOLATION':
			return 'Another record already has this value.';
		case 'NOT_NULL_VIOLATION': {
			const column = typeof source.context?.column === 'string' ? source.context.column : null;
			return column ? `${fieldLabel(column)} needs a value.` : 'A required field needs a value.';
		}
		case 'CHECK_VIOLATION':
			return 'This value is not allowed by a rule of this table.';
		case 'FOREIGN_KEY_VIOLATION':
			return action === 'delete' ? 'Other records still link to this record.' : 'The linked record does not exist.';
		default:
			return null;
	}
}

function plainMessage(source: MessageSource, action: WriteAction): string | null {
	const message = source.message?.trim() ?? '';
	if ((source.code && PERMISSION_CODES.has(source.code)) || PERMISSION_TEXT.test(message)) return PERMISSION_MESSAGES[action];
	if (NOT_APPLIED_TEXT.test(message)) return NOT_APPLIED_MESSAGES[action];
	if (isAuthenticationCode(source.code)) return 'Your session has ended. Sign in again to save changes.';
	const rule = ruleMessage(source, action);
	if (rule) return rule;
	const referencing = STILL_REFERENCED_TEXT.exec(message)?.[1];
	if (referencing && action === 'delete') return `Other records in ${fieldLabel(referencing)} still link to this record. Change or remove them first.`;
	return message || null;
}

/** Every distinct message of a failed write, in plain words. */
export function writeErrorMessages(error: unknown, action: WriteAction): string[] {
	const responseErrors = responseErrorsOf(error) ?? [];
	const fromResponse = responseErrors.map((entry) =>
		plainMessage({ message: entry.message, code: entry.extensions?.code ?? null, context: entry.extensions?.context ?? null }, action),
	);
	const messages = fromResponse.filter((message): message is string => Boolean(message));
	if (messages.length === 0) {
		const message = error instanceof Error ? error.message : typeof error === 'string' ? error : null;
		const context = error && typeof error === 'object' ? ((error as { context?: Record<string, unknown> }).context ?? null) : null;
		const plain = plainMessage({ message, code: getErrorCode(error), context }, action);
		messages.push(plain ?? 'The change could not be saved.');
	}
	return [...new Set(messages)];
}

/** The text that names a record: its display fields, else its position. */
export function recordLabel(model: TableModel | null, row: Readonly<Record<string, unknown>> | null | undefined, rowIndex: number): string {
	const parts = (model?.display.fields ?? [])
		.map((field) => row?.[field])
		.filter((value) => value !== null && value !== undefined && value !== '' && typeof value !== 'object')
		.map(String);
	const label = parts.join(' · ');
	if (!label) return `row ${rowIndex + 1}`;
	return label.length > 60 ? `"${label.slice(0, 57)}..."` : `"${label}"`;
}

/** One failed write, as the grid shows it. */
export interface WriteErrorReport {
	id: string;
	title: string;
	messages: readonly string[];
}

let nextReportId = 0;

export function createWriteErrorReport(title: string, messages: readonly string[]): WriteErrorReport {
	nextReportId += 1;
	return { id: `write-error-${nextReportId}`, title, messages };
}

/**
 * Filter operators from the table model.
 *
 * A column offers exactly the operators its filter input really has
 * (`ColumnModel.filter.operators`). Each operator gets a plain label, a group,
 * and the value control its input shape and the column's kind call for. An
 * operator this file does not know still appears, named from its field name.
 */
import type { ColumnModel, ColumnOption, FilterOperatorModel, InputValueModel } from '@constructive-io/data';

export type FilterOperatorGroup = 'match' | 'text' | 'compare' | 'items' | 'empty' | 'other';

/** Group headings, in display order. */
export const FILTER_OPERATOR_GROUPS: readonly { group: FilterOperatorGroup; label: string }[] = [
	{ group: 'match', label: 'Match' },
	{ group: 'text', label: 'Text' },
	{ group: 'compare', label: 'Compare' },
	{ group: 'items', label: 'Items' },
	{ group: 'empty', label: 'Empty' },
	{ group: 'other', label: 'More' },
];

/** A control for one value. */
export type ScalarValueControl =
	| { kind: 'text' }
	/** A whole number that fits a JavaScript number; sent as a number. */
	| { kind: 'integer' }
	/** A floating-point number; sent as a number. */
	| { kind: 'number' }
	/** A whole number of any size; sent as exact text. */
	| { kind: 'exact-integer' }
	/** A decimal number of any size; sent as exact text. */
	| { kind: 'exact-decimal' }
	| { kind: 'date' }
	| { kind: 'datetime' }
	| { kind: 'time' }
	| { kind: 'boolean' }
	/** One of a fixed list. `value` is the wire value. */
	| { kind: 'choice'; options: readonly ColumnOption[] }
	| { kind: 'json' };

export interface FilterValueField {
	name: string;
	label: string;
	required: boolean;
	control: ScalarValueControl;
}

/** The control a condition shows for its operator. */
export type FilterValueControl =
	| ScalarValueControl
	/** The operator takes no value from the user. */
	| { kind: 'none' }
	/** The operator takes a list of values. */
	| { kind: 'multi'; item: ScalarValueControl }
	/** The operator takes an object: one control per field. */
	| { kind: 'fields'; fields: readonly FilterValueField[] }
	/** The editor cannot enter this operator's value. */
	| { kind: 'unsupported'; reason: string };

export interface FilterOperatorOption {
	/** Unique within a column: the operator name, or `isNull:true` / `isNull:false`. */
	id: string;
	/** Operator field name. */
	operator: string;
	label: string;
	group: FilterOperatorGroup;
	control: FilterValueControl;
	/** The operand of an operator that takes no value from the user (`isNull`). */
	fixedValue?: boolean;
}

const UNSUPPORTED_VALUE = 'This condition needs a value the filter editor cannot enter yet.';

