/** Display order: operators named here come first within their group, in this order. */
const PREFERRED_ORDER = Object.keys(GROUP_OF);

/** Operators whose value is compared for equality, so a column's option list applies. */
const OPTION_OPERATORS = new Set([
	'equalTo',
	'notEqualTo',
	'distinctFrom',
	'notDistinctFrom',
	'in',
	'notIn',
	'contains',
	'containedBy',
	'overlaps',
	'anyEqualTo',
	'anyNotEqualTo',
]);

/** A readable name from an operator field name: `bboxIntersects2D` -> `bbox intersects 2D`. */
export function humanizeOperatorName(name: string): string {
	const words = name
		.replace(/([a-z])([A-Z0-9])/g, '$1 $2')
		.replace(/([0-9])([A-Z][a-z])/g, '$1 $2')
		.split(/\s+/)
		.filter(Boolean)
		.map((word, index) => (index > 0 && /^[A-Z][a-z]/.test(word) ? word.toLowerCase() : word));
	return words.join(' ') || name;
}

/** A readable name from an input field name: `postalCode` -> `Postal code`. */
function humanizeFieldName(name: string): string {
	const text = humanizeOperatorName(name).replace(/_/g, ' ');
	return text.charAt(0).toUpperCase() + text.slice(1);
}

function isNumericKind(column: ColumnModel): boolean {
	const { kind } = column.value;
	return kind === 'integer' || kind === 'bigint' || kind === 'decimal' || kind === 'float';
}

function isTimeKind(column: ColumnModel): boolean {
	const { kind } = column.value;
	return kind === 'date' || kind === 'time' || kind === 'datetime';
}

/** The label of one operator on one column. */
export function filterOperatorLabel(column: ColumnModel, operator: string): string {
	if (column.value.isArray && LIST_LABELS[operator]) return LIST_LABELS[operator]!;
	if (column.value.kind === 'path' && PATH_LABELS[operator]) return PATH_LABELS[operator]!;
	if (!column.value.isArray && isNumericKind(column) && NUMBER_LABELS[operator]) return NUMBER_LABELS[operator]!;
	if (!column.value.isArray && isTimeKind(column) && TIME_LABELS[operator]) return TIME_LABELS[operator]!;
	return GENERIC_LABELS[operator] ?? humanizeOperatorName(operator);
}

function enumOptions(input: InputValueModel, column: ColumnModel | null): ColumnOption[] {
	const labels = new Map((column?.value.options ?? []).map((option) => [option.value, option.label]));
	return (input.enumValues ?? []).map((value) => ({ value, label: labels.get(value) ?? humanizeFieldName(value.toLowerCase()) }));
}

/** The control for a scalar of a known GraphQL scalar type, or null for an unknown type. */
function builtinScalarControl(typeName: string): ScalarValueControl | null {
	switch (typeName) {
		case 'Boolean':
			return { kind: 'boolean' };
		case 'Int':
			return { kind: 'integer' };
		case 'Float':
			return { kind: 'number' };
		case 'BigInt':
			return { kind: 'exact-integer' };
		case 'BigFloat':
			return { kind: 'exact-decimal' };
		case 'Date':
			return { kind: 'date' };
		case 'Datetime':
			return { kind: 'datetime' };
		case 'Time':
			return { kind: 'time' };
		case 'JSON':
		case 'GeoJSON':
			return { kind: 'json' };
		default:
			return null;
	}
}

/** The control for the column's own value kind (a domain type over a number, a date, ...). */
function kindControl(column: ColumnModel): ScalarValueControl {
	switch (column.value.kind) {
		case 'integer':
			return { kind: 'integer' };
		case 'bigint':
			return { kind: 'exact-integer' };
		case 'decimal':
			return { kind: 'exact-decimal' };
		case 'float':
			return { kind: 'number' };
		case 'date':
			return { kind: 'date' };
		case 'time':
			return { kind: 'time' };
		case 'datetime':
			return { kind: 'datetime' };
		case 'boolean':
			return { kind: 'boolean' };
		case 'json':
		case 'vector':
		case 'geometry':
			return { kind: 'json' };
		case 'file':
			// An attachment is a URL; an image or upload is a file object.
			return column.value.file?.kind === 'attachment' || column.value.semantic === 'attachment' ? { kind: 'text' } : { kind: 'json' };
		default:
			return { kind: 'text' };
	}
}

function scalarControl(input: InputValueModel, column: ColumnModel | null, operator: string): ScalarValueControl | null {
	if (input.shape === 'enum') {
		const options = enumOptions(input, column);
		return options.length > 0 ? { kind: 'choice', options } : null;
	}
	if (input.shape !== 'scalar') return null;
	if (input.typeName === 'Boolean') return { kind: 'boolean' };
	const ownType = column && (input.typeName === column.value.input?.typeName || input.typeName === column.value.typeName);
	if (column && ownType && column.value.options && column.value.options.length > 0 && OPTION_OPERATORS.has(operator)) {
		return { kind: 'choice', options: column.value.options };
	}
	if (column && ownType) return kindControl(column);
	return builtinScalarControl(input.typeName) ?? { kind: 'text' };
}

function objectControl(input: InputValueModel): FilterValueControl {
	if (!input.fields || input.fields.length === 0) return { kind: 'unsupported', reason: UNSUPPORTED_VALUE };
	const fields: FilterValueField[] = [];
	for (const field of input.fields) {
		if (field.value.isList) return { kind: 'unsupported', reason: UNSUPPORTED_VALUE };
		const control = scalarControl(field.value, null, field.name);
		if (!control) return { kind: 'unsupported', reason: UNSUPPORTED_VALUE };
		fields.push({ name: field.name, label: humanizeFieldName(field.name), required: field.required, control });
	}
	return { kind: 'fields', fields };
}

/** The value control for one operator of one column. */
export function filterValueControl(column: ColumnModel, operator: FilterOperatorModel): FilterValueControl {
	const { input } = operator;
	if (input.shape === 'object') {
		return input.isList ? { kind: 'unsupported', reason: UNSUPPORTED_VALUE } : objectControl(input);
	}
	const item = scalarControl(input, column, operator.name);
	if (!item) return { kind: 'unsupported', reason: UNSUPPORTED_VALUE };
	return input.isList ? { kind: 'multi', item } : item;
}

function orderIndex(operator: string): number {
	const index = PREFERRED_ORDER.indexOf(operator);
	return index === -1 ? PREFERRED_ORDER.length : index;
}

/**
 * Every operator a column's filter has, as the builder offers them: grouped,
 * labelled, each with its value control. `isNull` becomes two choices, "is
 * empty" and "is not empty". Empty when the column cannot be filtered.
 */
export function filterOperatorOptions(column: ColumnModel): FilterOperatorOption[] {
	const operators = column.filter?.operators ?? [];
	const options: FilterOperatorOption[] = [];
	for (const operator of operators) {
		if (operator.name === 'isNull' && operator.input.shape === 'scalar' && operator.input.typeName === 'Boolean') {
			options.push(
				{ id: 'isNull:true', operator: 'isNull', label: 'is empty', group: 'empty', control: { kind: 'none' }, fixedValue: true },
				{ id: 'isNull:false', operator: 'isNull', label: 'is not empty', group: 'empty', control: { kind: 'none' }, fixedValue: false },
			);
			continue;
		}
		options.push({
			id: operator.name,
			operator: operator.name,
			label: filterOperatorLabel(column, operator.name),
			group: GROUP_OF[operator.name] ?? 'other',
			control: filterValueControl(column, operator),
		});
	}
	const groupOrder = FILTER_OPERATOR_GROUPS.map((entry) => entry.group);
	return options
		.map((option, position) => ({ option, position }))
		.sort(
			(left, right) =>
				groupOrder.indexOf(left.option.group) - groupOrder.indexOf(right.option.group) ||
				orderIndex(left.option.operator) - orderIndex(right.option.operator) ||
				left.position - right.position,
		)
		.map((entry) => entry.option);
}

/** The option a condition uses: its operator, and for `isNull` its boolean operand. */
export function findOperatorOption(
	options: readonly FilterOperatorOption[],
	operator: string,
	value: unknown,
): FilterOperatorOption | null {
	if (operator === 'isNull') return options.find((option) => option.operator === 'isNull' && option.fixedValue === (value !== false)) ?? null;
	return options.find((option) => option.operator === operator) ?? null;
}

/** Operators a new condition prefers, by what the column holds. */
function defaultPreference(column: ColumnModel): readonly string[] {
	if (column.value.isArray) return ['contains', 'anyEqualTo', 'overlaps', 'equalTo'];
	if (column.value.options?.length || column.value.kind === 'enum') return ['in', 'equalTo'];
	if (column.value.kind === 'text') return ['includesInsensitive', 'includes', 'equalTo'];
	return ['equalTo'];
}

/** The operator a new condition on this column starts with. */
export function defaultOperatorOption(column: ColumnModel): FilterOperatorOption | null {
	const options = filterOperatorOptions(column).filter((option) => option.control.kind !== 'unsupported');
	for (const name of defaultPreference(column)) {
		const match = options.find((option) => option.operator === name);
		if (match) return match;
	}
	return options[0] ?? null;
}

/** True when the column has at least one operator the builder can use. */
export function isColumnFilterable(column: ColumnModel): boolean {
	return column.readable && defaultOperatorOption(column) !== null;
}

/**
 * A filter group that matches the rows whose columns equal given values, for
 * opening a table on the rows that belong to one record (for example the
 * junction rows of a project: `projectId = 1`). A host can pass the group
 * straight to `<Sheets filters>`.
 */
import type { TableModel } from '@constructive-io/data';

import { filterValueControl } from '../filter-operators';
import { createFilterGroup, createFilterNodeId } from '../view-state/view-state';
import type { SheetsColumnCondition, SheetsFilterGroup } from '../view-state/view-state.types';
import { encodeFilterValue } from './filter-value';

/** A value as the server sends it, in the form the filter editor holds: numbers as their text. */
function enteredValue(wire: unknown): string | boolean | null {
	if (typeof wire === 'string' || typeof wire === 'boolean') return wire;
	if (typeof wire === 'number' && Number.isFinite(wire)) return String(wire);
	return null;
}

/**
 * One `equalTo` condition per column, combined with "and". Null when a column is
 * not in the model, cannot be filtered by `equalTo`, or holds a value the filter
 * would not send back exactly as given (a timestamp the editor normalizes, an
 * object, null), so a caller never opens a table on the wrong rows.
 */
export function equalityFilterGroup(model: TableModel, values: Readonly<Record<string, unknown>>): SheetsFilterGroup | null {
	const entries = Object.entries(values);
	if (entries.length === 0 || !model.operations.list?.filter) return null;
	const conditions: SheetsColumnCondition[] = [];
	for (const [name, wire] of entries) {
		const column = model.columns.find((candidate) => candidate.name === name);
		const operator = column?.readable ? column.filter?.operators.find((candidate) => candidate.name === 'equalTo') : undefined;
		const value = enteredValue(wire);
		if (!column || !operator || value === null) return null;
		const encoded = encodeFilterValue(filterValueControl(column, operator), value);
		if (encoded.status !== 'ready' || String(encoded.value) !== String(wire)) return null;
		conditions.push({ kind: 'column', id: createFilterNodeId(), column: name, operator: 'equalTo', value });
	}
	return createFilterGroup('and', conditions);
}

/**
 * The filter builder: nested groups of conditions on columns and relations,
 * offering only the fields, operators and group logic the table model has.
 * Changes apply as they are made; typed values commit after a pause.
 */
import { memo, useMemo } from 'react';
import { RiAddLine, RiCloseLine } from '@remixicon/react';

import type { RelationModel, TableKey, TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
	Select,
	SelectContent,
	SelectGroup,
	SelectGroupLabel,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select';

import type { ConditionStatus } from '../view-state/build-view-query';
import { MAX_FILTER_DEPTH, createFilterGroup, removeFilterNode, replaceFilterNode } from '../view-state/view-state';
import type {
	SheetsColumnCondition,
	SheetsFilterCondition,
	SheetsFilterGroup,
	SheetsFilterLogic,
	SheetsRelationCondition,
	SheetsRelationTest,
} from '../view-state/view-state.types';
import { FILTER_OPERATOR_GROUPS, filterOperatorOptions, findOperatorOption } from '../filter-operators';
import { filterFieldsOf, newCondition, type FilterField } from './filter-fields';
import { emptyFilterValue, valueFitsControl } from './filter-value';
import { FilterValueInput } from './filter-value-control';
import { relationFilterTests } from './relation-filters';
import { useCommittedText } from './use-committed-text';

interface BuilderContext {
	fields: readonly FilterField[];
	logicalOperators: readonly ('and' | 'or' | 'not')[];
	conditions: ReadonlyMap<string, ConditionStatus>;
	relatedModel: (key: TableKey) => TableModel | null;
}

function fieldOf(ctx: BuilderContext, condition: SheetsFilterCondition): FilterField | undefined {
	const key = condition.kind === 'column' ? `column:${condition.column}` : `relation:${condition.relation}`;
	return ctx.fields.find((field) => field.key === key);
}

function relatedOf(ctx: BuilderContext, relation: RelationModel): TableModel | null {
	return relation.targetKey ? ctx.relatedModel(relation.targetKey) : null;
}

function FieldSelect({
	ctx,
	value,
	onChange,
}: {
	ctx: BuilderContext;
	value: string;
	onChange: (field: FilterField) => void;
}) {
	const columns = ctx.fields.filter((field) => field.kind === 'column');
	const relations = ctx.fields.filter((field) => field.kind === 'relation');
	return (
		<Select
			value={value}
			onValueChange={(key) => {
				const field = ctx.fields.find((candidate) => candidate.key === key);
				if (field) onChange(field);
			}}
		>
			<SelectTrigger size='sm' className='w-[10rem]' aria-label='Field'>
				<SelectValue placeholder='Field' />
			</SelectTrigger>
			<SelectContent>
				{columns.length > 0 && (
					<SelectGroup>
						<SelectGroupLabel>Columns</SelectGroupLabel>
						{columns.map((field) => (
							<SelectItem key={field.key} value={field.key} title={field.name}>
								{field.label}
							</SelectItem>
						))}
					</SelectGroup>
				)}
				{relations.length > 0 && (
					<SelectGroup>
						<SelectGroupLabel>Linked records</SelectGroupLabel>
						{relations.map((field) => (
							<SelectItem key={field.key} value={field.key} title={field.name}>
								{field.label}
							</SelectItem>
						))}
					</SelectGroup>
				)}
			</SelectContent>
		</Select>
	);
}

function RemoveButton({ label, onRemove }: { label: string; onRemove: () => void }) {
	return (
		<Button variant='ghost' size='icon-xs' onClick={onRemove} aria-label={label}>
			<RiCloseLine aria-hidden='true' />
		</Button>
	);
}

function errorOf(ctx: BuilderContext, id: string): string | null {
	const status = ctx.conditions.get(id);
	return status?.status === 'invalid' ? status.message : null;
}

/** The operator select and value control of a column condition. */
function ColumnConditionControls({
	ctx,
	condition,
	field,
	onChange,
}: {
	ctx: BuilderContext;
	condition: SheetsColumnCondition;
	field: Extract<FilterField, { kind: 'column' }>;
	onChange: (next: SheetsFilterCondition) => void;
}) {
	const options = useMemo(() => filterOperatorOptions(field.column), [field.column]);
	const current = findOperatorOption(options, condition.operator, condition.value);
	const groups = FILTER_OPERATOR_GROUPS.map((entry) => ({
		...entry,
		options: options.filter((option) => option.group === entry.group),
	})).filter((entry) => entry.options.length > 0);

	return (
		<>
			<Select
				value={current?.id ?? null}
				onValueChange={(id) => {
					const option = options.find((candidate) => candidate.id === id);
					if (!option) return;
					const value =
						option.control.kind === 'none'
							? option.fixedValue ?? null
							: valueFitsControl(option.control, condition.value)
								? condition.value
								: emptyFilterValue(option.control);
					onChange({ ...condition, operator: option.operator, value });
				}}
			>
				<SelectTrigger size='sm' className='w-[11rem]' aria-label={`Condition for ${field.label}`}>
					<SelectValue placeholder='Condition' />
				</SelectTrigger>
				<SelectContent>
					{groups.map((group) => (
						<SelectGroup key={group.group}>
							<SelectGroupLabel>{group.label}</SelectGroupLabel>
							{group.options.map((option) => (
								<SelectItem
									key={option.id}
									value={option.id}
									disabled={option.control.kind === 'unsupported'}
									title={option.control.kind === 'unsupported' ? option.control.reason : undefined}
								>
									{option.label}
								</SelectItem>
							))}
						</SelectGroup>
					))}
				</SelectContent>
			</Select>
			{current && (
				<FilterValueInput
					key={`${field.key}:${current.id}`}
					control={current.control}
					value={condition.value}
					onChange={(value) => onChange({ ...condition, value })}
					label={`Value for ${field.label}`}
					error={errorOf(ctx, condition.id)}
				/>
			)}
		</>
	);
}

function LabelText({ value, onCommit, label }: { value: string; onCommit: (text: string) => void; label: string }) {
	const { text, change, flush } = useCommittedText(value, onCommit);
	return (
		<Input
			size='sm'
			className='w-[11rem]'
			aria-label={label}
			placeholder='Text'
			value={text}
			onChange={(event) => change(event.target.value)}
			onBlur={flush}
			onKeyDown={(event) => {
				if (event.key === 'Enter') flush();
			}}
		/>
	);
}

/** The test select and text of a relation condition. Tests the model cannot run are listed disabled with the reason. */
function RelationConditionControls({
	ctx,
	condition,
	field,
	onChange,
}: {
	ctx: BuilderContext;
	condition: SheetsRelationCondition;
	field: Extract<FilterField, { kind: 'relation' }>;
	onChange: (next: SheetsFilterCondition) => void;
}) {
	const tests = relationFilterTests(field.relation, relatedOf(ctx, field.relation));
	const error = errorOf(ctx, condition.id);
	return (
		<>
			<Select
				value={condition.test}
				onValueChange={(test) => {
					const next = test as SheetsRelationTest;
					onChange({ ...condition, test: next, value: next === 'labelContains' ? condition.value ?? '' : null });
				}}
			>
				<SelectTrigger size='sm' className='w-[13rem]' aria-label={`Condition for ${field.label}`}>
					<SelectValue placeholder='Condition' />
				</SelectTrigger>
				<SelectContent>
					{tests.map((test) => (
						<SelectItem key={test.test} value={test.test} disabled={Boolean(test.reason)} title={test.reason ?? undefined}>
							{test.label}
						</SelectItem>
					))}
				</SelectContent>
			</Select>
			{condition.test === 'labelContains' && (
				<div className='flex flex-col gap-1'>
					<LabelText
						value={condition.value ?? ''}
						onCommit={(value) => onChange({ ...condition, value })}
						label={`Value for ${field.label}`}
					/>
					{error && (
						<p className='text-destructive text-xs' role='alert'>
							{error}
						</p>
					)}
				</div>
			)}
		</>
	);
}

/**
 * One condition. The field select stays the same element when the field changes
 * kind (column to relation), so it keeps keyboard focus.
 */
function ConditionRow({
	ctx,
	condition,
	onChange,
	onRemove,
}: {
	ctx: BuilderContext;
	condition: SheetsFilterCondition;
	onChange: (next: SheetsFilterCondition) => void;
	onRemove: () => void;
}) {
	const field = fieldOf(ctx, condition);
	if (!field || field.kind !== condition.kind) {
		return (
			<div data-part-id='sheets-filter-condition' className='text-muted-foreground flex items-center gap-2 text-xs'>
				<span>This condition names a field the table no longer has.</span>
				<RemoveButton label='Remove condition' onRemove={onRemove} />
			</div>
		);
	}
	const onFieldChange = (next: FilterField) => {
		const replacement = newCondition(next, next.kind === 'relation' ? relatedOf(ctx, next.relation) : null);
		if (replacement) onChange({ ...replacement, id: condition.id });
	};
	return (
		<div data-part-id='sheets-filter-condition' className='flex flex-wrap items-start gap-2'>
			<FieldSelect ctx={ctx} value={field.key} onChange={onFieldChange} />
			{field.kind === 'relation' && condition.kind === 'relation' && (
				<RelationConditionControls ctx={ctx} condition={condition} field={field} onChange={onChange} />
			)}
			{field.kind === 'column' && condition.kind === 'column' && (
				<ColumnConditionControls ctx={ctx} condition={condition} field={field} onChange={onChange} />
			)}
			<RemoveButton label={`Remove condition on ${field.label}`} onRemove={onRemove} />
		</div>
	);
}

const LOGIC_LABEL: Record<SheetsFilterLogic, string> = { and: 'all', or: 'any' };

const GroupEditor = memo(function GroupEditor({
	ctx,
	group,
	depth,
	onChange,
	onRemove,
}: {
	ctx: BuilderContext;
	group: SheetsFilterGroup;
	depth: number;
	onChange: (next: SheetsFilterGroup) => void;
	onRemove?: () => void;
}) {
	const logics = (['and', 'or'] as const).filter((logic) => logic === group.logic || ctx.logicalOperators.includes(logic));
	const childLogic: SheetsFilterLogic = group.logic === 'and' && ctx.logicalOperators.includes('or') ? 'or' : 'and';
	const firstField = ctx.fields[0];

	const addCondition = () => {
		if (!firstField) return;
		const condition = newCondition(firstField, firstField.kind === 'relation' ? relatedOf(ctx, firstField.relation) : null);
		if (condition) onChange({ ...group, children: [...group.children, condition] });
	};

	return (
		<div
			role='group'
			aria-label={depth === 0 ? 'Filters' : 'Filter group'}
			data-part-id='sheets-filter-group'
			className={depth > 0 ? 'border-muted-foreground/20 ml-1 border-l-2 pl-3' : undefined}
		>
			<div className='mb-2 flex items-center gap-1.5 text-xs'>
				<span className='text-muted-foreground'>Match</span>
				{logics.length > 1 ? (
					<Select value={group.logic} onValueChange={(logic) => onChange({ ...group, logic: logic as SheetsFilterLogic })}>
						<SelectTrigger size='sm' className='h-7 w-[5.5rem]' aria-label='Match all or any'>
							<SelectValue />
						</SelectTrigger>
						<SelectContent>
							{logics.map((logic) => (
								<SelectItem key={logic} value={logic}>
									{LOGIC_LABEL[logic]}
								</SelectItem>
							))}
						</SelectContent>
					</Select>
				) : (
					<span className='font-medium'>{LOGIC_LABEL[group.logic]}</span>
				)}
				<span className='text-muted-foreground'>of these conditions</span>
				{onRemove && (
					<span className='ml-auto'>
						<RemoveButton label='Remove group' onRemove={onRemove} />
					</span>
				)}
			</div>

			<div className='grid gap-2'>
				{group.children.map((child) =>
					child.kind === 'group' ? (
						<GroupEditor
							key={child.id}
							ctx={ctx}
							group={child}
							depth={depth + 1}
							onChange={(next) => onChange(replaceFilterNode(group, child.id, next))}
							onRemove={() => onChange(removeFilterNode(group, child.id))}
						/>
					) : (
						<ConditionRow
							key={child.id}
							ctx={ctx}
							condition={child}
							onChange={(next) => onChange(replaceFilterNode(group, child.id, next))}
							onRemove={() => onChange(removeFilterNode(group, child.id))}
						/>
					),
				)}
			</div>

			<div className='mt-2 flex items-center gap-2'>
				<Button variant='ghost' size='xs' onClick={addCondition} disabled={!firstField}>
					<RiAddLine aria-hidden='true' /> Add condition
				</Button>
				{depth < MAX_FILTER_DEPTH - 1 && (
					<Button
						variant='ghost'
						size='xs'
						onClick={() => onChange({ ...group, children: [...group.children, createFilterGroup(childLogic)] })}
						disabled={!firstField}
					>
						<RiAddLine aria-hidden='true' /> Add group
					</Button>
				)}
			</div>
		</div>
	);
});

export interface FilterBuilderProps {
	model: TableModel | null;
	filters: SheetsFilterGroup;
	onChange: (filters: SheetsFilterGroup) => void;
	conditions: ReadonlyMap<string, ConditionStatus>;
	columnLabel: (name: string) => string;
	relatedModel: (key: TableKey) => TableModel | null;
}

export function FilterBuilder({ model, filters, onChange, conditions, columnLabel, relatedModel }: FilterBuilderProps) {
	const fields = useMemo(() => filterFieldsOf(model, columnLabel), [model, columnLabel]);
	const ctx = useMemo<BuilderContext>(
		() => ({ fields, logicalOperators: model?.operations.list?.logicalOperators ?? [], conditions, relatedModel }),
		[fields, model, conditions, relatedModel],
	);
	if (!model) return <p className='text-muted-foreground text-sm'>Filters are available once the table has loaded.</p>;
	if (fields.length === 0) return <p className='text-muted-foreground text-sm'>This table cannot be filtered.</p>;
	return <GroupEditor ctx={ctx} group={filters} depth={0} onChange={onChange} />;
}

/**
 * The columns and relations a table can be filtered by, and the condition a
 * new filter on one of them starts with.
 */
import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import { defaultOperatorOption, isColumnFilterable } from '../filter-operators';
import { createFilterNodeId } from '../view-state/view-state';
import type { SheetsFilterCondition } from '../view-state/view-state.types';
import { emptyFilterValue } from './filter-value';
import { isRelationFilterable, relationFilterTests } from './relation-filters';

/** A column or relation the builder can filter by. */
export type FilterField =
	| { kind: 'column'; key: string; name: string; label: string; column: ColumnModel }
	| { kind: 'relation'; key: string; name: string; label: string; relation: RelationModel };

/** Every filterable column and relation of a table, in table order. */
export function filterFieldsOf(model: TableModel | null, label: (name: string) => string): FilterField[] {
	if (!model?.operations.list?.filter) return [];
	const columns: FilterField[] = model.columns
		.filter(isColumnFilterable)
		.map((column) => ({ kind: 'column', key: `column:${column.name}`, name: column.name, label: label(column.name), column }));
	const relations: FilterField[] = model.relations
		.filter((relation) => relation.readable && isRelationFilterable(relation))
		.map((relation) => ({
			kind: 'relation',
			key: `relation:${relation.fieldName}`,
			name: relation.fieldName,
			label: label(relation.fieldName),
			relation,
		}));
	return [...columns, ...relations];
}

/** A new condition on a field, with its default test or operator. */
export function newCondition(field: FilterField, related: TableModel | null): SheetsFilterCondition | null {
	if (field.kind === 'relation') {
		const tests = relationFilterTests(field.relation, related);
		// "Linked record contains" waits for the related table's model, which loads once the builder is open.
		const waitsForModel = !related && Boolean(field.relation.targetKey && field.relation.filter?.recordFilterType);
		const test = tests.find((entry) => !entry.reason) ?? (waitsForModel ? tests.find((entry) => entry.test === 'labelContains') : undefined);
		if (!test) return null;
		return { kind: 'relation', id: createFilterNodeId(), relation: field.name, test: test.test, value: test.test === 'labelContains' ? '' : null };
	}
	const option = defaultOperatorOption(field.column);
	if (!option) return null;
	return {
		kind: 'column',
		id: createFilterNodeId(),
		column: field.name,
		operator: option.operator,
		value: option.control.kind === 'none' ? option.fixedValue ?? null : emptyFilterValue(option.control),
	};
}

/**
 * The value control of one filter condition, chosen by the operator's value
 * control (see `filterValueControl`). Text-like inputs commit after a pause in
 * typing; pickers and choices commit at once.
 */
import { useState } from 'react';
import { RiCloseLine } from '@remixicon/react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

import { cn } from '../../utils/cn';
import type { FilterValueControl, ScalarValueControl } from '../filter-operators';
import type { SheetsFilterValue } from '../view-state/view-state.types';
import { useCommittedText } from './use-committed-text';

/** Most options shown as toggles; a longer list is picked one value at a time. */
const MAX_TOGGLE_OPTIONS = 12;

interface ScalarInputProps {
	control: ScalarValueControl;
	value: string;
	onCommit: (value: string) => void;
	label: string;
	invalid?: boolean;
	className?: string;
}

const PLACEHOLDERS: Partial<Record<ScalarValueControl['kind'], string>> = {
	text: 'Value',
	integer: 'Whole number',
	number: 'Number',
	'exact-integer': 'Whole number',
	'exact-decimal': 'Number',
	json: 'JSON value',
};

const INPUT_MODES: Partial<Record<ScalarValueControl['kind'], React.HTMLAttributes<HTMLInputElement>['inputMode']>> = {
	integer: 'numeric',
	'exact-integer': 'numeric',
	number: 'decimal',
	'exact-decimal': 'decimal',
};

/** `datetime-local` text for an ISO timestamp, in the viewer's time zone. */
function toLocalDateTime(iso: string): string {
	const time = Date.parse(iso);
	if (Number.isNaN(time)) return '';
	const date = new Date(time);
	const pad = (part: number) => String(part).padStart(2, '0');
	return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function CommittedInput({ control, value, onCommit, label, invalid, className }: ScalarInputProps) {
	const { text, change, flush } = useCommittedText(value, onCommit);
	return (
		<Input
			size='sm'
			className={cn('w-[11rem]', className)}
			aria-label={label}
			aria-invalid={invalid || undefined}
			inputMode={INPUT_MODES[control.kind]}
			placeholder={PLACEHOLDERS[control.kind] ?? 'Value'}
			value={text}
			onChange={(event) => change(event.target.value)}
			onBlur={flush}
			onKeyDown={(event) => {
				if (event.key === 'Enter') flush();
			}}
		/>
	);
}

function ChoiceSelect({
	options,
	value,
	onCommit,
	label,
	placeholder = 'Choose a value',
}: {
	options: readonly { value: string; label: string }[];
	value: string;
	onCommit: (value: string) => void;
	label: string;
	placeholder?: string;
}) {
	return (
		<Select value={value || null} onValueChange={onCommit}>
			<SelectTrigger size='sm' className='w-[11rem]' aria-label={label}>
				<SelectValue placeholder={placeholder} />
			</SelectTrigger>
			<SelectContent>
				{options.map((option) => (
					<SelectItem key={option.value} value={option.value}>
						{option.label}
					</SelectItem>
				))}
			</SelectContent>
		</Select>
	);
}

const BOOLEAN_OPTIONS = [
	{ value: 'true', label: 'true' },
	{ value: 'false', label: 'false' },
];

/** One scalar value. Booleans are reported as booleans, everything else as text. */
function ScalarControl({
	control,
	value,
	onChange,
	label,
	invalid,
}: {
	control: ScalarValueControl;
	value: SheetsFilterValue;
	onChange: (value: SheetsFilterValue) => void;
	label: string;
	invalid?: boolean;
}) {
	const text = typeof value === 'string' ? value : '';
	switch (control.kind) {
		case 'boolean':
			return (
				<ChoiceSelect
					options={BOOLEAN_OPTIONS}
					value={typeof value === 'boolean' ? String(value) : ''}
					onCommit={(next) => onChange(next === 'true')}
					label={label}
				/>
			);
		case 'choice':
			return <ChoiceSelect options={control.options} value={text} onCommit={onChange} label={label} />;
		case 'date':
			return (
				<Input
					type='date'
					size='sm'
					className='w-[11rem]'
					aria-label={label}
					aria-invalid={invalid || undefined}
					value={text}
					onChange={(event) => onChange(event.target.value)}
				/>
			);
		case 'time':
			return (
				<Input
					type='time'
					step={1}
					size='sm'
					className='w-[11rem]'
					aria-label={label}
					aria-invalid={invalid || undefined}
					value={text}
					onChange={(event) => onChange(event.target.value)}
				/>
			);
		case 'datetime':
			return (
				<Input
					type='datetime-local'
					size='sm'
					className='w-[13rem]'
					aria-label={label}
					aria-invalid={invalid || undefined}
					value={toLocalDateTime(text)}
					onChange={(event) => {
						const local = event.target.value;
						const time = Date.parse(local);
						onChange(local === '' || Number.isNaN(time) ? '' : new Date(time).toISOString());
					}}
				/>
			);
		default:
			return <CommittedInput control={control} value={text} onCommit={onChange} label={label} invalid={invalid} />;
	}
}

/** A list of values: toggles for a short option list, a picker for a long one, chips for typed values. */
function MultiControl({
	item,
	value,
	onChange,
	label,
}: {
	item: ScalarValueControl;
	value: readonly string[];
	onChange: (value: SheetsFilterValue) => void;
	label: string;
}) {
	const [draft, setDraft] = useState('');
	const add = (entry: string) => {
		const next = entry.trim();
		if (next && !value.includes(next)) onChange([...value, next]);
	};
	const remove = (entry: string) => onChange(value.filter((candidate) => candidate !== entry));
	const options = item.kind === 'choice' ? item.options : item.kind === 'boolean' ? BOOLEAN_OPTIONS : null;

	if (options && options.length <= MAX_TOGGLE_OPTIONS) {
		return (
			<div role='group' aria-label={label} className='flex max-w-[22rem] flex-wrap gap-1'>
				{options.map((option) => {
					const on = value.includes(option.value);
					return (
						<Button
							key={option.value}
							type='button'
							size='xs'
							variant={on ? 'secondary' : 'outline'}
							aria-pressed={on}
							onClick={() => (on ? remove(option.value) : add(option.value))}
						>
							{option.label}
						</Button>
					);
				})}
			</div>
		);
	}

	const labelOf = (entry: string) => options?.find((option) => option.value === entry)?.label ?? entry;
	return (
		<div className='flex max-w-[22rem] flex-wrap items-center gap-1'>
			{value.map((entry) => (
				<span key={entry} className='bg-muted inline-flex h-7 max-w-[10rem] items-center gap-1 rounded-md px-2 text-xs'>
					<span className='truncate' title={labelOf(entry)}>
						{labelOf(entry)}
					</span>
					<button
						type='button'
						className='text-muted-foreground hover:text-foreground'
						aria-label={`Remove ${labelOf(entry)}`}
						onClick={() => remove(entry)}
					>
						<RiCloseLine className='size-3.5' aria-hidden='true' />
					</button>
				</span>
			))}
			{options ? (
				<ChoiceSelect
					options={options.filter((option) => !value.includes(option.value))}
					value=''
					onCommit={add}
					label={`Add to ${label}`}
					placeholder='Add a value'
				/>
			) : (
				<Input
					size='sm'
					className='w-[9rem]'
					aria-label={`Add to ${label}`}
					placeholder='Type, then Enter'
					value={draft}
					onChange={(event) => setDraft(event.target.value)}
					onKeyDown={(event) => {
						if (event.key === 'Enter' || event.key === ',') {
							event.preventDefault();
							add(draft);
							setDraft('');
						}
					}}
					onBlur={() => {
						if (draft.trim()) {
							add(draft);
							setDraft('');
						}
					}}
				/>
			)}
		</div>
	);
}

export interface FilterValueControlProps {
	control: FilterValueControl;
	value: SheetsFilterValue;
	onChange: (value: SheetsFilterValue) => void;
	/** Accessible name, for example "Value for Title". */
	label: string;
	/** Why the value is not valid, or null. */
	error: string | null;
}

export function FilterValueInput({ control, value, onChange, label, error }: FilterValueControlProps) {
	let body: React.ReactNode;
	switch (control.kind) {
		case 'none':
			return null;
		case 'unsupported':
			return <p className='text-muted-foreground max-w-[16rem] text-xs'>{control.reason}</p>;
		case 'multi':
			body = (
				<MultiControl item={control.item} value={Array.isArray(value) ? (value as readonly string[]) : []} onChange={onChange} label={label} />
			);
			break;
		case 'fields': {
			const entered = value && typeof value === 'object' && !Array.isArray(value) ? (value as Readonly<Record<string, string>>) : {};
			body = (
				<div role='group' aria-label={label} className='flex flex-wrap items-center gap-1'>
					{control.fields.map((field) => (
						<ScalarControl
							key={field.name}
							control={field.control}
							value={entered[field.name] ?? ''}
							label={`${field.label}${field.required ? '' : ' (optional)'}`}
							onChange={(next) => onChange({ ...entered, [field.name]: typeof next === 'string' ? next : String(next) })}
						/>
					))}
				</div>
			);
			break;
		}
		default:
			body = <ScalarControl control={control} value={value} onChange={onChange} label={label} invalid={Boolean(error)} />;
	}
	return (
		<div className='flex flex-col gap-1'>
			{body}
			{error && (
				<p className='text-destructive text-xs' role='alert'>
					{error}
				</p>
			)}
		</div>
	);
}

/**
 * Filter values: from what the user entered to what the filter input takes.
 *
 * Big whole numbers and decimals stay exact text (never `Number()`), dates and
 * times stay ISO text, and an object operand is built field by field. A value
 * the control cannot accept is `invalid` with a message for the user; a value
 * not entered yet is `incomplete`, and the condition is simply not applied.
 */
import type { FilterValueControl, ScalarValueControl } from '../filter-operators';
import type { SheetsFilterValue } from '../view-state/view-state.types';

export type FilterValueResult =
	| { status: 'ready'; value: unknown }
	| { status: 'incomplete' }
	| { status: 'invalid'; message: string };

const INCOMPLETE: FilterValueResult = { status: 'incomplete' };

const invalid = (message: string): FilterValueResult => ({ status: 'invalid', message });
const ready = (value: unknown): FilterValueResult => ({ status: 'ready', value });

const WHOLE_NUMBER = /^[+-]?\d+$/;
const DECIMAL = /^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
const TIME = /^(\d{2}):(\d{2})(?::(\d{2})(\.\d+)?)?$/;

/** Exact decimal text without a leading `+`. */
function exactText(text: string): string {
	return text.startsWith('+') ? text.slice(1) : text;
}

function encodeText(control: ScalarValueControl, raw: string): FilterValueResult {
	const text = control.kind === 'text' || control.kind === 'json' ? raw : raw.trim();
	if (text.trim() === '') return INCOMPLETE;
	switch (control.kind) {
		case 'text':
			return ready(text);
		case 'integer': {
			const value = Number(text);
			return WHOLE_NUMBER.test(text) && Number.isSafeInteger(value) ? ready(value) : invalid('Enter a whole number.');
		}
		case 'number': {
			const value = Number(text);
			return DECIMAL.test(text) && Number.isFinite(value) ? ready(value) : invalid('Enter a number.');
		}
		case 'exact-integer':
			return WHOLE_NUMBER.test(text) ? ready(exactText(text)) : invalid('Enter a whole number.');
		case 'exact-decimal':
			return DECIMAL.test(text) ? ready(exactText(text)) : invalid('Enter a number.');
		case 'date':
			return DATE.test(text) && !Number.isNaN(Date.parse(text)) ? ready(text) : invalid('Enter a date.');
		case 'datetime':
			return Number.isNaN(Date.parse(text)) ? invalid('Enter a date and time.') : ready(new Date(text).toISOString());
		case 'time': {
			const match = TIME.exec(text);
			if (!match) return invalid('Enter a time.');
			return ready(`${match[1]}:${match[2]}:${match[3] ?? '00'}${match[4] ?? ''}`);
		}
		case 'choice':
			return control.options.some((option) => option.value === text)
				? ready(text)
				: invalid('Choose one of the listed values.');
		case 'json':
			try {
				return ready(JSON.parse(text));
			} catch {
				return invalid('Enter valid JSON.');
			}
		case 'boolean':
			return text === 'true' ? ready(true) : text === 'false' ? ready(false) : invalid('Choose true or false.');
	}
}

function encodeScalar(control: ScalarValueControl, value: SheetsFilterValue): FilterValueResult {
	if (value === null || value === undefined) return INCOMPLETE;
	if (control.kind === 'boolean') {
		if (typeof value === 'boolean') return ready(value);
		return typeof value === 'string' ? encodeText(control, value) : invalid('Choose true or false.');
	}
	return typeof value === 'string' ? encodeText(control, value) : invalid('This value does not fit this condition.');
}

/**
 * The operand for a condition, from its value control and the entered value.
 * `fixedValue` is the operand of an operator that takes no value (`isNull`).
 */
export function encodeFilterValue(
	control: FilterValueControl,
	value: SheetsFilterValue,
	fixedValue?: boolean,
): FilterValueResult {
	switch (control.kind) {
		case 'none':
			return fixedValue === undefined ? invalid('This condition has no value.') : ready(fixedValue);
		case 'unsupported':
			return invalid(control.reason);
		case 'multi': {
			if (!Array.isArray(value)) return value === null || value === '' ? INCOMPLETE : invalid('This value does not fit this condition.');
			const items = (value as readonly string[]).filter((item) => typeof item === 'string' && item.trim() !== '');
			if (items.length === 0) return INCOMPLETE;
			const encoded: unknown[] = [];
			for (const item of items) {
				const result = encodeScalar(control.item, item);
				if (result.status === 'invalid') return invalid(`"${item}": ${result.message}`);
				if (result.status === 'ready') encoded.push(result.value);
			}
			return ready(encoded);
		}
		case 'fields': {
			if (!value || typeof value !== 'object' || Array.isArray(value)) return INCOMPLETE;
			const entered = value as Readonly<Record<string, string>>;
			const operand: Record<string, unknown> = {};
			let missingRequired = false;
			for (const field of control.fields) {
				const raw = entered[field.name];
				const result = typeof raw === 'string' ? encodeScalar(field.control, raw) : INCOMPLETE;
				if (result.status === 'invalid') return invalid(`${field.label}: ${result.message}`);
				if (result.status === 'ready') operand[field.name] = result.value;
				else if (field.required) missingRequired = true;
			}
			return missingRequired || Object.keys(operand).length === 0 ? INCOMPLETE : ready(operand);
		}
		default:
			return encodeScalar(control, value);
	}
}

/** The value a new condition starts with for a control. */
export function emptyFilterValue(control: FilterValueControl): SheetsFilterValue {
	switch (control.kind) {
		case 'none':
		case 'unsupported':
			return null;
		case 'multi':
			return [];
		case 'fields':
			return {};
		case 'boolean':
			return true;
		default:
			return '';
	}
}

/**
 * Whether a value entered for one control can carry over to another, so a
 * condition keeps its value when the operator changes within the same shape.
 */
export function valueFitsControl(control: FilterValueControl, value: SheetsFilterValue): boolean {
	switch (control.kind) {
		case 'none':
		case 'unsupported':
			return value === null;
		case 'multi':
			return Array.isArray(value);
		case 'fields':
			return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
		case 'boolean':
			return typeof value === 'boolean';
		case 'choice':
			return typeof value === 'string' && (value === '' || control.options.some((option) => option.value === value));
		default:
			return typeof value === 'string';
	}
}

/**
 * Conditions on relations, built only from what the table models prove.
 *
 * "Has any" / "has none" use the relation's exists field. "Linked record
 * contains" matches the related table's label columns that have a
 * case-insensitive contains operator, and only when the relation's record filter
 * is the related table's own filter input, so the related model's column filters
 * apply to it.
 */
import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import type { SheetsRelationCondition, SheetsRelationTest } from '../view-state/view-state.types';
import type { FilterValueResult } from './filter-value';

export interface RelationFilterTest {
	test: SheetsRelationTest;
	label: string;
	/** Why the test cannot be used, or null when it can. */
	reason: string | null;
}

const CONTAINS = 'includesInsensitive';

function isMany(relation: RelationModel): boolean {
	return relation.kind === 'hasMany' || relation.kind === 'manyToMany';
}

/** Label columns of the related table that a "contains" condition can match. */
export function relationLabelColumns(relation: RelationModel, related: TableModel | null): ColumnModel[] {
	const filter = relation.filter;
	if (!filter || !related || !filter.recordFilterType) return [];
	if (related.operations.list?.filter?.typeName !== filter.recordFilterType) return [];
	if (filter.many && !filter.many.some) return [];
	return relation.target.labelFields.flatMap((name) => {
		const column = related.columns.find((candidate) => candidate.name === name);
		const contains = column?.filter?.operators.find((operator) => operator.name === CONTAINS);
		return column && contains && contains.input.shape === 'scalar' && !contains.input.isList ? [column] : [];
	});
}

/** The tests a relation offers, with the reason for each one it cannot use. */
export function relationFilterTests(relation: RelationModel, related: TableModel | null): RelationFilterTest[] {
	const filter = relation.filter;
	const many = isMany(relation);
	const noExists = 'This table cannot test whether a record has links here.';
	const labelReason = !relation.targetKey
		? 'The linked table is not available.'
		: !related
		? 'The linked table is still loading.'
		: relationLabelColumns(relation, related).length === 0
			? 'The linked records cannot be searched by their name.'
			: null;
	return [
		{ test: 'any', label: many ? 'has any linked records' : 'has a linked record', reason: filter?.exists ? null : noExists },
		{ test: 'none', label: many ? 'has no linked records' : 'has no linked record', reason: filter?.exists ? null : noExists },
		{ test: 'labelContains', label: many ? 'has a linked record that contains' : 'linked record contains', reason: filter ? labelReason : noExists },
	];
}

/** True when the relation can be filtered by any test without its related model. */
export function isRelationFilterable(relation: RelationModel): boolean {
	return Boolean(relation.filter && (relation.filter.exists || relation.filter.recordFilterType));
}

export interface RelationWhereResult {
	result: FilterValueResult;
	/** `TableModel.key` of a related table whose model the condition still needs, or null. */
	waitingFor: string | null;
}

/** The filter for one relation condition, as a part of this table's filter input. */
export function relationConditionWhere(
	relation: RelationModel,
	condition: SheetsRelationCondition,
	related: TableModel | null,
): RelationWhereResult {
	const filter = relation.filter;
	if (!filter) return { result: { status: 'invalid', message: 'This relation cannot be filtered.' }, waitingFor: null };
	if (condition.test === 'any' || condition.test === 'none') {
		if (!filter.exists) return { result: { status: 'invalid', message: 'This table cannot test whether a record has links here.' }, waitingFor: null };
		return { result: { status: 'ready', value: { [filter.exists]: condition.test === 'any' } }, waitingFor: null };
	}

	const text = (condition.value ?? '').trim();
	if (text === '') return { result: { status: 'incomplete' }, waitingFor: null };
	if (!related) {
		return { result: { status: 'incomplete' }, waitingFor: relation.targetKey };
	}
	const columns = relationLabelColumns(relation, related);
	if (columns.length === 0) {
		return { result: { status: 'invalid', message: 'The linked records cannot be searched by their name.' }, waitingFor: null };
	}
	const parts = columns.map((column) => ({ [column.filter!.field]: { [CONTAINS]: text } }));
	const canOr = related.operations.list?.logicalOperators.includes('or') ?? false;
	const record = parts.length === 1 || !canOr ? parts[0]! : { or: parts };
	const value = filter.many ? { [filter.field]: { [filter.many.some!]: record } } : { [filter.field]: record };
	return { result: { status: 'ready', value }, waitingFor: null };
}

import { useCallback, useEffect, useRef, useState } from 'react';

/** Pause after the last keystroke before typed text is committed. */
export const TEXT_COMMIT_DELAY_MS = 250;

export interface CommittedText {
	/** The text in the input. */
	text: string;
	/** Set the text and commit it after a pause in typing. */
	change: (text: string) => void;
	/** Commit the current text now (Enter, blur). */
	flush: () => void;
	/** Set and commit `text` now (clear, pick). */
	commitNow: (text: string) => void;
}

/**
 * Text that a control commits after a pause in typing, so a list query runs
 * once per pause instead of once per keystroke. A new committed value from
 * outside (a host or a reset) replaces the text unless the user is typing.
 */
export function useCommittedText(value: string, commit: (text: string) => void, delay = TEXT_COMMIT_DELAY_MS): CommittedText {
	const [text, setText] = useState(value);
	const pending = useRef<ReturnType<typeof setTimeout> | null>(null);
	const latest = useRef({ text, commit, value });
	latest.current = { text, commit, value };

	const cancel = () => {
		if (pending.current) clearTimeout(pending.current);
		pending.current = null;
	};

	useEffect(() => {
		if (!pending.current) setText(value);
	}, [value]);

	// Unmounting drops a pending commit: the commit would carry the closure of a condition that
	// may have changed since. Leaving the input (blur) and Enter commit at once.
	useEffect(() => cancel, []);

	const flush = useCallback(() => {
		cancel();
		if (latest.current.text !== latest.current.value) latest.current.commit(latest.current.text);
	}, []);

	const change = useCallback(
		(next: string) => {
			setText(next);
			latest.current.text = next;
			cancel();
			pending.current = setTimeout(() => {
				pending.current = null;
				if (latest.current.text !== latest.current.value) latest.current.commit(latest.current.text);
			}, delay);
		},
		[delay],
	);

	const commitNow = useCallback((next: string) => {
		cancel();
		setText(next);
		latest.current.text = next;
		if (next !== latest.current.value) latest.current.commit(next);
	}, []);

	return { text, change, flush, commitNow };
}

import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import type { RelationInfo } from '../store/relation-info-slice';

// Relation rendering options surfaced to cell factories alongside metadata
export interface RelationCellOptions {
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
}

// Metadata used when creating cells from values
export interface CellCreationMetadata {
	cellType: string;
	fieldName: string;
	fieldMeta?: FieldMetadata;
	relationInfo?: RelationInfo;
	/** The table-model column behind this cell, or null when the cell is not a column (a relation, a draft action). */
	column?: ColumnModel | null;
	/** The table-model relation behind this cell, or null when the cell is not a relation. */
	relation?: RelationModel | null;
	/** The table model of the grid, or null while it loads. */
	table?: TableModel | null;
	/** Every record a list relation links to when the relation reports a total, else null ("+N more"). */
	relationTotalCount?: number | null;
	relationOptions?: RelationCellOptions;
	canEdit: boolean;
	isReadonly: boolean;
	activationBehavior: 'single-click' | 'double-click';
}

// The grid's undo history, for parts that write on their own (the link editor, in a cell or the
// record panel) so their changes take a step in it too. Null outside a grid.
import { createContext, useContext } from 'react';

import type { HistoryEntry } from './use-undo-redo';

export const SheetsHistoryContext = createContext<((entry: HistoryEntry) => void) | null>(null);

/** Add a step to the grid's undo history, or null outside a grid. */
export function useRecordHistory(): ((entry: HistoryEntry) => void) | null {
	return useContext(SheetsHistoryContext);
}

/**
 * useBatchCommit — the batched cell-value commit primitive behind paste / fill /
 * bulk-edit AND (routed through it) the single-cell edit, so EVERY server-row value
 * write is one undoable, coalesced operation.
 *
 * It owns NO coercion/readonly rules of its own: server-row writes go through the
 * shared {@link resolveServerPatch} (the same resolver `useCellEditing` uses), so the
 * UUID-id guard, relation normalization and readonly skips stay in ONE place.
 *
 * Coalescing contract (load-bearing for a 1000-cell paste):
 *   • prior values are captured from `combinedRows` BEFORE any optimistic patch, so
 *     undo restores the EXACT pre-edit value.
 *   • ONE optimistic cache patch is applied per affected ROW (merged col patches),
 *     not per cell — N rows -> N patches, never N×cols.
 *   • ONE server `update(rowId, {merged})` is issued per row, and the commit stops at
 *     the first row the server refuses. Rows saved before it keep their values; the
 *     refused row and the rows not sent yet go back to their prior values.
 *   • when recording, the HistoryEntry's `undo`/`redo` re-enter `commitCells` with
 *     `{ record: false }` so replays never double-record. A commit that stops part
 *     way records the rows it saved. A replay that the server refuses in any row
 *     throws, so the history keeps the step for another try.
 *
 * Draft-row writes are NOT batched here — they route to the existing per-cell draft
 * path (`editCell`) and are excluded from history (draft undo is out of P3 scope).
 */
import { useCallback, useMemo, useRef } from 'react';

import type { ColumnModel, TableModel } from '@constructive-io/data';

import { parseColumnInput } from '../../cell-types/column-value';
import { resolveServerPatch } from './use-cell-editing';
import type { CellEditingResult } from './use-cell-editing';
import { getDraftMeta, type SheetsRow } from '../row-model';
import { reportRejectedWrites, type RejectedWrite } from '../write-feedback';
import type { SheetsRowIdentifier } from '../../row-identity';

/** A single cell write request. */
export interface CellWrite {
	rowIndex: number;
	colKey: string;
	value: unknown;
	/**
	 * The value is text the user typed or pasted (JSON and lists are read from it).
	 * Defaults to true for a string value, false otherwise; an editor or a fill that
	 * hands over a stored value sets it to false.
	 */
	fromText?: boolean;
}

export interface CommitCellsOptions {
	/** When false, the commit is NOT pushed to history (used by undo/redo replays). Default true. */
	record?: boolean;
}

export interface CommitCellsResult {
	/** Number of server cells actually written (post readonly/null/no-op filtering). */
	applied: number;
	/** Cells the server refused, or did not get after it refused a row, when there are any. */
	unsaved?: number;
	/** Writes refused before sending (the value did not fit, or the cell is read-only), when there are any. */
	rejected?: readonly RejectedWrite[];
}

interface UseBatchCommitParams {
	combinedRows: SheetsRow[];
	fieldMetaMap: Map<string, any>;
	relationInfoByField: Map<string, any>;
	update: (id: SheetsRowIdentifier, data: Record<string, unknown>) => Promise<{ updatedRow?: Record<string, unknown> | null }>;
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	readOnlyFields?: ReadonlySet<string>;
	isCellReadOnly?: (rowIndex: number, colKey: string) => boolean;
	/** The grid's cell resolver: a write to a cell with a `readOnlyReason` is refused and reported. */
	resolveCell?: (rowIndex: number, colKey: string) => { readOnlyReason?: string | null };
	/** The table model: every write to one of its columns is parsed by the column's rules first. */
	tableModel?: TableModel | null;
	/** Report the writes that were refused. Defaults to a notification. */
	onRejected?: (rejected: readonly RejectedWrite[], total: number) => void;
	/**
	 * Report a save the server refused, with the number of changes not saved (those cells
	 * already show their prior values again). When given, `commitCells` resolves instead of
	 * throwing, so fire-and-forget callers (paste, fill, clear) still surface the failure.
	 */
	onServerError?: (error: unknown, cellCount: number, failed: ServerWriteFailure) => void;
	canUpdate?: boolean;
	/** Single-write optimistic cache patch (infinite mode) — returns a revert thunk. */
	applyOptimisticPatch?: (rowIndex: number, patch: Record<string, unknown>) => (() => void) | void;
	/** Re-sync a server row over the optimistic patch after the mutation resolves (infinite mode). */
	resyncRow?: (rowIndex: number, updatedRow: Record<string, unknown>) => void;
	/** Existing per-cell editor (draft routing + single-cell server coercion). */
	editCell: (rowIndex: number, colKey: string, rawValue: unknown) => Promise<CellEditingResult>;
	/** Observational per-server-write callback (mirrors useCellEditing's onCellEdit). */
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	/** Push a reversible step to the history. */
	record: (entry: { label: string; undo: () => Promise<void> | void; redo: () => Promise<void> | void }) => void;
	/** The grid's save status: the server writes of one commit report as one save. */
	feedback?: {
		onStart?: (type: 'update', total: number) => string;
		onComplete?: (id: string, status: 'success' | 'partial' | 'error', message: string) => void;
	};
}

function changes(count: number): string {
	return `${count.toLocaleString()} ${count === 1 ? 'change' : 'changes'}`;
}

/** The status of a commit the server stopped: what it saved before, and what it did not. */
function notSavedMessage(saved: number, unsaved: number): string {
	if (saved === 0) return unsaved === 1 ? 'Not saved' : `${changes(unsaved)} not saved`;
	return `${changes(saved)} saved, ${unsaved.toLocaleString()} not saved`;
}

/** The row whose save the server refused, and the fields that save patched. */
export interface ServerWriteFailure {
	rowIndex: number;
	fields: readonly string[];
}

/** Why a paste, fill or clear does not change a linked-records cell. */
export const RELATION_WRITE_REASON = 'Use the link editor to change linked records.';

/** A resolved server write: its row, the patch field, the next + prior values. */
interface ResolvedWrite {
	rowIndex: number;
	rowId: SheetsRowIdentifier;
	field: string;
	value: unknown;
	prior: unknown;
}

const NO_RELATIONS: Map<string, unknown> = new Map();

function legacyRowIdentifier(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null {
	return typeof row.id === 'string' || typeof row.id === 'number' ? row.id : null;
}

export function useBatchCommit({
	combinedRows,
	fieldMetaMap,
	relationInfoByField,
	update,
	getRowIdentifier = legacyRowIdentifier,
	readOnlyFields,
	isCellReadOnly,
	resolveCell,
	tableModel,
	onRejected = reportRejectedWrites,
	onServerError,
	canUpdate = true,
	applyOptimisticPatch,
	resyncRow,
	editCell,
	onCellEdit,
	record,
	feedback,
}: UseBatchCommitParams) {
	const columnByName = useMemo(
		() => new Map<string, ColumnModel>((tableModel?.columns ?? []).map((column) => [column.name, column])),
		[tableModel],
	);
	const relationFields = useMemo(
		() => new Set((tableModel?.relations ?? []).map((relation) => relation.fieldName)),
		[tableModel],
	);

	// Holds the latest commitCells so a recorded HistoryEntry (captured at record-time)
	// always re-enters the CURRENT closure — avoids a stale-row snapshot. Per-hook
	// instance, so multiple grids never share a commit fn.
	const commitRef = useRef<((writes: CellWrite[], opts?: CommitCellsOptions) => Promise<CommitCellsResult>) | null>(null);

	const commitCells = useCallback(
		async (writes: CellWrite[], opts?: CommitCellsOptions): Promise<CommitCellsResult> => {
			if (!writes.length) return { applied: 0 };

			const resolved: ResolvedWrite[] = [];
			const draftWrites: CellWrite[] = [];
			const rejected: RejectedWrite[] = [];

			for (const original of writes) {
				const rowData = combinedRows[original.rowIndex] as Record<string, unknown> | null | undefined;
				// Null-guard unfetched proxy rows — skip writes whose row is not loaded.
				if (!rowData) continue;
				if (isCellReadOnly?.(original.rowIndex, original.colKey)) continue;
				const readOnlyReason = resolveCell?.(original.rowIndex, original.colKey).readOnlyReason ?? null;
				if (readOnlyReason) {
					rejected.push({ rowIndex: original.rowIndex, colKey: original.colKey, reason: readOnlyReason });
					continue;
				}

				// A table-model column takes only a value that fits it; anything else is refused, never coerced.
				const column = columnByName.get(original.colKey);
				// Linked records change only through the link editor: a pasted or filled value cannot
				// name a related record safely (its key may be composite or not called id).
				if (!column && (relationFields.has(original.colKey) || relationInfoByField.has(original.colKey))) {
					rejected.push({ rowIndex: original.rowIndex, colKey: original.colKey, reason: RELATION_WRITE_REASON });
					continue;
				}
				let w = original;
				if (column) {
					const parsed = parseColumnInput(column, original.value, {
						fromText: original.fromText ?? typeof original.value === 'string',
						creating: Boolean(getDraftMeta(rowData)),
					});
					if (parsed.ok === false) {
						rejected.push({ rowIndex: original.rowIndex, colKey: original.colKey, reason: parsed.reason });
						continue;
					}
					w = { ...original, value: parsed.value, fromText: false };
				}

				// Draft rows keep their existing per-cell path; excluded from coalescing + history.
				if (getDraftMeta(rowData)) {
					draftWrites.push(w);
					continue;
				}

				if (!canUpdate) continue;
				// A model column writes its own parsed value; only keys outside the model keep the legacy relation route.
				const resolution = resolveServerPatch(w.colKey, w.value, fieldMetaMap, column ? NO_RELATIONS : relationInfoByField, readOnlyFields);
				if (resolution.kind === 'noop') continue;
				const rowIdentifier = getRowIdentifier(rowData);
				if (rowIdentifier === null) continue;

				resolved.push({
					rowIndex: w.rowIndex,
					rowId: rowIdentifier,
					field: resolution.field,
					value: resolution.value,
					// Capture the PRIOR value of the patched field BEFORE any optimistic patch.
					prior: rowData[resolution.field],
				});
			}

			if (rejected.length) onRejected(rejected, writes.length);
			const withRejected = (applied: number): CommitCellsResult =>
				rejected.length ? { applied, rejected } : { applied };

			// Fire draft writes through the existing path (not batched, not recorded).
			for (const dw of draftWrites) {
				// eslint-disable-next-line no-await-in-loop
				await editCell(dw.rowIndex, dw.colKey, dw.value);
			}

			if (!resolved.length) return withRejected(0);

			// Group by row: one merged optimistic patch + one merged server PATCH per row.
			const byRow = new Map<number, ResolvedWrite[]>();
			for (const r of resolved) {
				const list = byRow.get(r.rowIndex);
				if (list) list.push(r);
				else byRow.set(r.rowIndex, [r]);
			}

			// Apply ONE optimistic patch per row (merged), keeping each row's revert thunk.
			const reverts = new Map<number, () => void>();
			for (const [rowIndex, group] of byRow) {
				const patch: Record<string, unknown> = {};
				for (const r of group) patch[r.field] = r.value;
				const revert = applyOptimisticPatch?.(rowIndex, patch);
				if (revert) reverts.set(rowIndex, revert);
			}

			// Record the inverse (prior values) of the saved writes, so undo restores the exact pre-edit state.
			const recordSaved = (writes: readonly ResolvedWrite[]): void => {
				if (opts?.record === false || writes.length === 0) return;
				const priorWrites: CellWrite[] = writes.map((r) => ({
					rowIndex: r.rowIndex,
					colKey: r.field,
					value: r.prior,
					fromText: false,
				}));
				const redoWrites: CellWrite[] = writes.map((r) => ({
					rowIndex: r.rowIndex,
					colKey: r.field,
					value: r.value,
					fromText: false,
				}));
				// Capture the live commit fn via the closure below (commitRef).
				// A replay the server refuses in any row throws, so the history keeps the step for
				// another try. Its writes are values, so trying again also suits the rows that saved.
				const replay = async (cells: CellWrite[]) => {
					const result = await commitRef.current?.(cells, { record: false });
					if (result?.unsaved) throw new Error(`${changes(result.unsaved)} not saved`);
				};
				record({
					label: writes.length > 1 ? `Edit ${writes.length} cells` : 'Edit cell',
					undo: () => replay(priorWrites),
					redo: () => replay(redoWrites),
				});
			};

			// Issue ONE server mutation per row, and stop at the first row the server refuses.
			// A saved row keeps its values; the refused row and the rows not sent yet are reverted.
			// The whole commit is one save in the status, whatever the number of rows.
			const statusId = feedback?.onStart?.('update', resolved.length);
			const saved: ResolvedWrite[] = [];
			let failing: ServerWriteFailure | null = null;
			try {
				for (const [rowIndex, group] of byRow) {
					failing = { rowIndex, fields: group.map((r) => r.field) };
					const patch: Record<string, unknown> = {};
					for (const r of group) patch[r.field] = r.value;
					// eslint-disable-next-line no-await-in-loop
					const result = await update(group[0].rowId, patch);
					reverts.delete(rowIndex);
					saved.push(...group);
					if (result?.updatedRow) resyncRow?.(rowIndex, result.updatedRow);
					for (const r of group) onCellEdit?.(r.rowId, r.field, r.value);
				}
			} catch (error) {
				for (const revert of reverts.values()) revert();
				const unsaved = resolved.length - saved.length;
				if (statusId) feedback?.onComplete?.(statusId, saved.length > 0 ? 'partial' : 'error', notSavedMessage(saved.length, unsaved));
				recordSaved(saved);
				if (!onServerError) throw error;
				onServerError(error, unsaved, failing ?? { rowIndex: resolved[0].rowIndex, fields: [resolved[0].field] });
				return { ...withRejected(saved.length), unsaved };
			}

			if (statusId) feedback?.onComplete?.(statusId, 'success', resolved.length === 1 ? 'Saved' : `${changes(resolved.length)} saved`);
			recordSaved(resolved);
			return withRejected(resolved.length);
		},
		[combinedRows, fieldMetaMap, relationInfoByField, update, getRowIdentifier, readOnlyFields, isCellReadOnly, resolveCell, columnByName, relationFields, onRejected, onServerError, canUpdate, applyOptimisticPatch, resyncRow, editCell, onCellEdit, record, feedback],
	);

	commitRef.current = commitCells;
	return commitCells;
}

import { useCallback } from 'react';

import { DRAFT_ACTION_COLUMN_KEY } from '../sheets.constants';
import { prepareDraftRelationValue } from '../sheets.utils';
import type { DraftRowsState } from './use-draft-rows';
import { getDraftMeta } from '../row-model';
import type { SheetsRowIdentifier } from '../../row-identity';

/** Result from the useCellEditing hook */
export interface CellEditingResult {
	/** Type of edit: 'draft' for local draft row, 'server' for server mutation, 'noop' for no action */
	type: 'draft' | 'server' | 'noop';
	/** The updated row data from the server (only for 'server' type) */
	updatedRow?: Record<string, unknown> | null;
	/** The field that was patched (only for 'server' type) */
	patchField?: string;
	/** The value that was sent (only for 'server' type) */
	patchValue?: unknown;
}

interface UseCellEditingParams {
	combinedRows: any[];
	fieldMetaMap: Map<string, any>;
	relationInfoByField: Map<string, any>;
	updateDraftCell: DraftRowsState['updateDraftCell'];
	tableKey: string;
	update: (id: SheetsRowIdentifier, data: Record<string, unknown>) => Promise<{ updatedRow?: Record<string, unknown> | null }>;
	getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
	readOnlyFields?: ReadonlySet<string>;
	canUpdate?: boolean;
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	/**
	 * Optimistic server-row cache patch. Applied to the local (infinite) cache BEFORE
	 * the `update` round-trip so the cell flips instantly; returns a revert thunk that
	 * the hook calls if `update` rejects. Omitted (e.g. paginated mode / unit tests) =>
	 * no pre-await patch and the consumer reconciles after the await as before.
	 */
	applyOptimisticPatch?: (rowIndex: number, patch: Record<string, unknown>) => (() => void) | void;
}

function legacyRowIdentifier(row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null {
	return typeof row.id === 'string' || typeof row.id === 'number' ? row.id : null;
}

/**
 * Normalize a relation value for a server PATCH: a JSON string is parsed, an array
 * is mapped to its ids (single id for belongsTo/hasOne, list otherwise), a single
 * object to its id. Mirrors the relation branch the canvas `handleCellEdit` ran,
 * but on the RAW native value instead of an extracted glide cell.
 */
export function normalizeRelationPatchValue(rawValue: unknown, relationKind: string | undefined): unknown {
	let value = rawValue;

	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (trimmed === '') {
			value = null;
		} else {
			try {
				value = JSON.parse(trimmed);
			} catch {
				value = trimmed;
			}
		}
	}

	if (Array.isArray(value)) {
		const mapped = value
			.map((entry) => (entry && typeof entry === 'object' ? ((entry as any).id ?? entry) : entry))
			.filter((entry) => entry !== undefined && entry !== null);
		value = relationKind === 'belongsTo' || relationKind === 'hasOne' ? (mapped[0] ?? null) : mapped;
	} else if (value && typeof value === 'object') {
		value = (value as any).id ?? null;
	}

	if (value === '') value = null;
	return value;
}

/** The resolved server PATCH for one cell write, or a reason it is a no-op. */
export type ServerPatchResolution =
	| { kind: 'patch'; field: string; value: unknown }
	| { kind: 'noop' };

/**
 * Derive the single-field server PATCH for a server-row cell write — the ONE place
 * that owns the relation normalization and the key guard (fields in `readOnlyFields`,
 * the primary key from the table model, are never patched). Value parsing happens
 * before this, in `commitCells`, by the column's rules. Shared by `useCellEditing`
 * (single cell) and the batched `commitCells` (paste/fill/bulk) so neither forks the
 * rules. PURE; never touches the cache or network.
 */
export function resolveServerPatch(
	colKey: string,
	rawValue: unknown,
	fieldMetaMap: Map<string, any>,
	relationInfoByField: Map<string, any>,
	readOnlyFields?: ReadonlySet<string>,
): ServerPatchResolution {
	if (!colKey || colKey === DRAFT_ACTION_COLUMN_KEY) return { kind: 'noop' };
	if (readOnlyFields?.has(colKey)) return { kind: 'noop' };

	const relationInfo = relationInfoByField.get(colKey);
	let value: unknown = rawValue;

	if (relationInfo) {
		const patchFieldCandidate = relationInfo.foreignKeyField || colKey;
		const canEditRelationInline = relationInfo.kind === 'belongsTo' && fieldMetaMap.has(patchFieldCandidate);
		if (!canEditRelationInline) return { kind: 'noop' };
		value = normalizeRelationPatchValue(rawValue, relationInfo.kind);
	}

	if (value === undefined) return { kind: 'noop' };

	const field = relationInfo?.foreignKeyField || colKey;
	return { kind: 'patch', field, value };
}

export function useCellEditing({
	combinedRows,
	fieldMetaMap,
	relationInfoByField,
	updateDraftCell,
	tableKey,
	update,
	getRowIdentifier = legacyRowIdentifier,
	readOnlyFields,
	canUpdate = true,
	onCellEdit,
	applyOptimisticPatch,
}: UseCellEditingParams) {
	return useCallback(
		// NATIVE signature: the DOM editors / inline-toggle pass a raw value that flows
		// straight through — no glide cell round-trip. This is what fixes the boolean
		// toggle: a raw `false` persists as `false`, never stringified to "false".
		async (rowIndex: number, colKey: string, rawValue: unknown): Promise<CellEditingResult> => {
			const rowData = combinedRows[rowIndex];
			if (!colKey || !rowData) return { type: 'noop' };

			if (colKey === DRAFT_ACTION_COLUMN_KEY) {
				return { type: 'noop' };
			}

			const draftMeta = getDraftMeta(rowData);

			if (draftMeta?.isDraft) {
				const draftRowId: string | undefined = draftMeta.draftRowId;
				if (!draftRowId) return { type: 'noop' };

				const baseValue = rawValue;
				const relationInfo = relationInfoByField.get(colKey);

				let storedValue: unknown = baseValue;
				let extraValues: Record<string, unknown> | undefined;

				if (relationInfo) {
					const { relationData, foreignKeyUpdates, relationReferences } = prepareDraftRelationValue(
						baseValue,
						relationInfo,
					);
					const relationFieldKey = relationInfo.relationField;
					const foreignKeyFieldKey = relationInfo.foreignKeyField;
					const editingRelationField = relationFieldKey ? relationFieldKey === colKey : false;
					const editingForeignKeyField = foreignKeyFieldKey ? foreignKeyFieldKey === colKey : false;

					const processedRelationData = Array.isArray(relationData)
						? relationData.filter((entry) => entry !== undefined)
						: relationData;

					const relationExtra = relationFieldKey
						? processedRelationData === undefined
							? undefined
							: processedRelationData === null
								? { [relationFieldKey]: null }
								: typeof processedRelationData === 'object'
									? { [relationFieldKey]: processedRelationData }
									: undefined
						: undefined;

					const processedReferenceValue = Array.isArray(relationReferences)
						? relationReferences.filter((entry) => entry !== undefined)
						: relationReferences;

					const foreignKeyExtra = foreignKeyFieldKey
						? processedReferenceValue !== undefined
							? { [foreignKeyFieldKey]: processedReferenceValue }
							: undefined
						: undefined;

					if (editingRelationField) {
						storedValue = processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
						};
					} else if (editingForeignKeyField) {
						storedValue = processedReferenceValue ?? processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
							...(relationExtra ?? {}),
						};
					} else {
						storedValue = processedRelationData;
						extraValues = {
							...(foreignKeyUpdates ?? {}),
							...(relationExtra ?? {}),
							...(foreignKeyExtra ?? {}),
						};
					}
				}

				updateDraftCell({
					tableKey,
					draftRowId,
					columnKey: colKey,
					value: storedValue,
					extraValues: extraValues && Object.keys(extraValues).length > 0 ? extraValues : undefined,
				});
				return { type: 'draft' };
			}

			// Server row edit — derive the PATCH via the shared resolver (the single owner
			// of server-row coercion + readonly guards, also used by batched `commitCells`).
			if (!canUpdate) return { type: 'noop' };
			const resolution = resolveServerPatch(colKey, rawValue, fieldMetaMap, relationInfoByField, readOnlyFields);
			if (resolution.kind === 'noop') return { type: 'noop' };
			const { field: patchField, value } = resolution;
			const rowIdentifier = getRowIdentifier(rowData);
			if (rowIdentifier === null) return { type: 'noop' };

			// Optimistic: patch the local cache with the new value BEFORE awaiting the
			// server so the cell updates instantly. `applyOptimisticPatch` returns a revert
			// thunk (snapshot of the prior value) which we replay only if `update` rejects.
			const revertOptimisticPatch = applyOptimisticPatch?.(rowIndex, { [patchField]: value });

			let result: { updatedRow?: Record<string, unknown> | null };
			try {
				result = await update(rowIdentifier, { [patchField]: value });
			} catch (error) {
				if (typeof revertOptimisticPatch === 'function') revertOptimisticPatch();
				throw error;
			}
			onCellEdit?.(rowIdentifier, patchField, value);

			return {
				type: 'server',
				updatedRow: result?.updatedRow ?? null,
				patchField,
				patchValue: value,
			};
		},
		[combinedRows, fieldMetaMap, relationInfoByField, tableKey, update, getRowIdentifier, readOnlyFields, canUpdate, onCellEdit, updateDraftCell, applyOptimisticPatch],
	);
}

import { useMemo } from 'react';

import { useSheetsStore } from '../../store/sheets-store';
import type { DraftRow, DraftRowsSlice } from '../../store/draft-rows-slice';
import { attachDraftMeta, isDraftRow } from '../row-model';

export interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

interface UseDraftRowsParams {
	tableKey: string;
	serverRows: any[];
	hasCompletedInitialLoad: boolean;
}

export interface DraftRowsState {
	draftRowsTable?: DraftRowsTableState;
	draftRows: DraftRow[];
	hasDraftRows: boolean;
	combinedRows: any[];
	draftRowIndices: number[];
	createDraftRow: DraftRowsSlice['createDraftRow'];
	updateDraftCell: DraftRowsSlice['updateDraftCell'];
	removeDraftRow: DraftRowsSlice['removeDraftRow'];
	syncDraftRowsWithMeta: DraftRowsSlice['syncDraftRowsWithMeta'];
	setDraftRowStatus: DraftRowsSlice['setDraftRowStatus'];
}

export function useDraftRows({
	tableKey,
	serverRows,
	hasCompletedInitialLoad,
}: UseDraftRowsParams): DraftRowsState {
	const draftRowsTable = useSheetsStore(
		(state) => state.draftRowsByTable[tableKey] as DraftRowsTableState | undefined,
	);
	const createDraftRow = useSheetsStore((state) => state.createDraftRow);
	const updateDraftCell = useSheetsStore((state) => state.updateDraftCell);
	const removeDraftRow = useSheetsStore((state) => state.removeDraftRow);
	const syncDraftRowsWithMeta = useSheetsStore((state) => state.syncDraftRowsWithMeta);
	const setDraftRowStatus = useSheetsStore((state) => state.setDraftRowStatus);

	const draftRows = useMemo(() => {
		if (!draftRowsTable) return [] as DraftRow[];
		return draftRowsTable.order.map((id) => draftRowsTable.map[id]).filter((row): row is DraftRow => Boolean(row));
	}, [draftRowsTable]);

	const mayShowDrafts = hasCompletedInitialLoad || serverRows.length > 0 || draftRows.length > 0;

	const combinedRows = useMemo(() => {
		if (!draftRows.length || !mayShowDrafts) return serverRows as any[];

		const draftDataRows = draftRows.map((draft) => {
			const row = { ...draft.values } as Record<string, unknown>;
			return attachDraftMeta(row, {
				isDraft: true,
				draftRowId: draft.id,
				status: draft.status,
				errors: draft.errors,
			});
		});

		return [...(serverRows as any[]), ...draftDataRows];
	}, [serverRows, draftRows, mayShowDrafts]);

	const draftRowIndices = useMemo(() => {
		const indices: number[] = [];
		combinedRows.forEach((row, index) => {
			if (isDraftRow(row)) {
				indices.push(index);
			}
		});
		return indices;
	}, [combinedRows]);

	const hasDraftRows = draftRows.length > 0 && mayShowDrafts;

	return {
		draftRowsTable,
		draftRows,
		hasDraftRows,
		combinedRows,
		draftRowIndices,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
	};
}

import { useCallback, useMemo, useState } from 'react';

import type { TableModel } from '@constructive-io/data';

import type { RelationInfo } from '../../store/relation-info-slice';
import type { DraftRow } from '../../store/draft-rows-slice';
import { SHEETS_CONCURRENCY } from '../../config/sheets-concurrency';

import { prepareDraftSubmissionPayload } from '../sheets.utils';
import { DRAFT_ROW_ERROR_KEY, incompleteDraftErrors, missingDraftFields } from '../draft-guidance';
import type { DraftSubmitResult } from '../draft-types';
import type { DraftRowEntry } from './use-grid-selection';
import { sheetsLogger } from '../../utils/sheets-logger';

interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

interface OperationFeedbackCallbacks {
	onStart?: (type: 'submit', total: number) => string;
	onProgress?: (id: string, completed: number, failed: number) => void;
	onComplete?: (id: string, status: 'success' | 'partial' | 'error', message: string) => void;
}

function rows(count: number): string {
	return `${count.toLocaleString()} ${count === 1 ? 'row' : 'rows'}`;
}

/** The save status after rows were submitted; null when nothing was submitted. */
export function submitOutcome(success: number, failed: number): { status: 'success' | 'partial' | 'error'; message: string } | null {
	if (failed === 0 && success > 0) return { status: 'success', message: success === 1 ? 'Row created' : `${rows(success)} created` };
	if (success > 0 && failed > 0) return { status: 'partial', message: `${rows(success)} created, ${failed.toLocaleString()} not created` };
	if (failed > 0) return { status: 'error', message: failed === 1 ? 'Row not created' : `${rows(failed)} not created` };
	return null;
}

interface UseDraftSubmissionParams {
	tableKey: string;
	draftRowsTable?: DraftRowsTableState;
	selectedDraftRowEntries: DraftRowEntry[];
	hasDraftSelection: boolean;
	create: (data: Record<string, unknown>) => Promise<{ createdRow?: Record<string, unknown> | null }>;
	removeDraftRow: (tableKey: string, draftRowId: string) => void;
	setDraftRowStatus: (args: {
		tableKey: string;
		draftRowId: string;
		status: DraftRow['status'];
		errors?: Record<string, string> | null;
	}) => void;
	clearSelection: () => void;
	/** The table model: which columns a create accepts and which it requires. Drafts cannot be submitted without it. */
	tableModel: TableModel | null;
	relationInfoByKey?: Record<string, RelationInfo | undefined>;
	onSubmittedSuccessfully?: (result: { success: number; failed: number }) => void;
	/** Feedback callbacks for inline status indicators */
	feedback?: OperationFeedbackCallbacks;
}

export function useDraftSubmission({
	tableKey,
	draftRowsTable,
	selectedDraftRowEntries,
	hasDraftSelection,
	create,
	removeDraftRow,
	setDraftRowStatus,
	clearSelection,
	tableModel,
	relationInfoByKey,
	onSubmittedSuccessfully,
	feedback,
}: UseDraftSubmissionParams) {
	const [isSubmittingDrafts, setIsSubmittingDrafts] = useState(false);

	const submitDraftEntries = useCallback(
		async (entries: DraftRowEntry[], operationId?: string): Promise<{ success: number; failed: number }> => {
			if (!entries.length) {
				return { success: 0, failed: 0 };
			}

			setIsSubmittingDrafts(true);

			const submissionResults = {
				success: 0,
				failed: 0,
			};

			try {
				let nextEntryIndex = 0;
				const workerCount = Math.min(SHEETS_CONCURRENCY.draftSubmit, entries.length);

				const runSubmitWorker = async () => {
					while (nextEntryIndex < entries.length) {
						const currentIndex = nextEntryIndex;
						nextEntryIndex += 1;
						const { draftRowId, draftRow } = entries[currentIndex];

						// Without a table model nothing proves which columns a create accepts.
						if (!tableModel) {
							submissionResults.failed += 1;
							setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: { [DRAFT_ROW_ERROR_KEY]: 'The table is still loading.' } });
							continue;
						}
						// Pre-validate required fields before sending to server
						const gaps = missingDraftFields(draftRow.values, tableModel);
						if (gaps.length > 0) {
							submissionResults.failed += 1;
							setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: incompleteDraftErrors(gaps) });
							if (operationId) {
								feedback?.onProgress?.(operationId, submissionResults.success, submissionResults.failed);
							}
							continue;
						}

						setDraftRowStatus({ tableKey, draftRowId, status: 'saving', errors: null });
						const payload = prepareDraftSubmissionPayload(draftRow.values, tableModel, relationInfoByKey);

						try {
							await create(payload);
							removeDraftRow(tableKey, draftRowId);
							submissionResults.success += 1;
						} catch (error) {
							submissionResults.failed += 1;
							const message = error instanceof Error ? error.message : 'Failed to submit draft row';
							sheetsLogger().error('submitDraftRow failed', error);
							setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: { [DRAFT_ROW_ERROR_KEY]: message } });
						}

						if (operationId) {
							feedback?.onProgress?.(
								operationId,
								submissionResults.success,
								submissionResults.failed,
							);
						}
					}
				};

				await Promise.all(Array.from({ length: workerCount }, () => runSubmitWorker()));
			} finally {
				setIsSubmittingDrafts(false);
			}

			if (submissionResults.success > 0) {
				onSubmittedSuccessfully?.(submissionResults);
			}

			return submissionResults;
		},
		[
			tableModel,
			relationInfoByKey,
			create,
			removeDraftRow,
			setDraftRowStatus,
			tableKey,
			feedback,
			onSubmittedSuccessfully,
		],
	);

	const handleSubmitDraftRows = useCallback(async () => {
		if (!draftRowsTable || !hasDraftSelection) {
			return;
		}

		const total = selectedDraftRowEntries.length;
		const operationId = feedback?.onStart?.('submit', total);

		const submissionResults = await submitDraftEntries(selectedDraftRowEntries, operationId);

		if (operationId) {
			const outcome = submitOutcome(submissionResults.success, submissionResults.failed);
			if (outcome) feedback?.onComplete?.(operationId, outcome.status, outcome.message);
		}

		if (submissionResults.success > 0) {
			clearSelection();
		}
	}, [draftRowsTable, hasDraftSelection, selectedDraftRowEntries, submitDraftEntries, clearSelection, feedback]);

	const handleSubmitSingleDraftRow = useCallback(
		async (draftRowId: string) => {
			if (!draftRowsTable) {
				return;
			}

			const draftRow = draftRowsTable.map[draftRowId];
			if (!draftRow) {
				return;
			}

			// The row shows its own state; the save status reports the outcome with every other write.
			const operationId = feedback?.onStart?.('submit', 1);
			const { success, failed } = await submitDraftEntries([{ draftRowId, draftRow }], operationId);
			const outcome = submitOutcome(success, failed);
			if (operationId && outcome) feedback?.onComplete?.(operationId, outcome.status, outcome.message);
		},
		[draftRowsTable, submitDraftEntries, feedback],
	);

	const submitDraftLabel = useMemo(() => {
		if (!hasDraftSelection) {
			return 'Submit draft rows';
		}
		const count = selectedDraftRowEntries.length;
		return `Submit ${count} draft ${count === 1 ? 'row' : 'rows'}`;
	}, [hasDraftSelection, selectedDraftRowEntries.length]);

	const submitDraftButtonDisabled = isSubmittingDrafts || !hasDraftSelection;

	/**
	 * Submit a single draft row for editor workflows (e.g., ImageEditor upload).
	 * Returns the created row with real database ID for subsequent operations.
	 *
	 * NOTE: This does NOT call onSingleRowSubmitted - the editor is responsible
	 * for triggering data refresh after any follow-up operations (like upload)
	 * are complete. This prevents premature cache invalidation.
	 */
	const submitDraftRowForEditor = useCallback(
		async (draftRowId: string): Promise<DraftSubmitResult> => {
			if (!draftRowsTable) {
				return { createdRow: null };
			}

			const draftRow = draftRowsTable.map[draftRowId];
			if (!draftRow || !tableModel) {
				return { createdRow: null };
			}

			// Required fields are checked here too, so the row's own Save never sends an incomplete record;
			// the caller gets what is missing, to say so and to move the cursor there.
			const gaps = missingDraftFields(draftRow.values, tableModel);
			if (gaps.length > 0) {
				setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: incompleteDraftErrors(gaps) });
				return { createdRow: null, missing: gaps };
			}

			const operationId = feedback?.onStart?.('submit', 1);
			try {
				setDraftRowStatus({ tableKey, draftRowId, status: 'saving', errors: null });

				const payload = prepareDraftSubmissionPayload(draftRow.values, tableModel, relationInfoByKey);

				const result = await create(payload);
				const createdRow = result?.createdRow ?? null;

				if (createdRow) {
					removeDraftRow(tableKey, draftRowId);
					// NOTE: Don't call onSingleRowSubmitted here - let the editor
					// trigger refresh after follow-up operations complete
				}
				if (operationId) feedback?.onComplete?.(operationId, 'success', 'Row created');

				return { createdRow };
			} catch (error) {
				const message = error instanceof Error ? error.message : 'Failed to create row';
				setDraftRowStatus({ tableKey, draftRowId, status: 'error', errors: { [DRAFT_ROW_ERROR_KEY]: message } });
				if (operationId) feedback?.onComplete?.(operationId, 'error', 'Row not created');
				throw error;
			}
		},
		[draftRowsTable, setDraftRowStatus, tableKey, tableModel, relationInfoByKey, create, removeDraftRow, feedback],
	);

	return {
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		handleSubmitSingleDraftRow,
		submitDraftRowForEditor,
	};
}

import { useCallback, useMemo, useState } from 'react';

import type { TableKey, TableModel } from '@constructive-io/data';

import { buildViewQuery, type ConditionStatus } from '../view-state/build-view-query';
import { validateSheetsViewState } from '../view-state/validate-view-state';
import { createFilterGroup } from '../view-state/view-state';
import { SHEETS_VIEW_STATE_VERSION, type SheetsFilterGroup, type SheetsViewStateDrop } from '../view-state/view-state.types';

/** Filter bindings for a headless shell. */
export interface DataFilteringContextValue {
	/** The filters in use, valid for the model. */
	filters: SheetsFilterGroup;
	setFilters: (filters: SheetsFilterGroup) => void;
	clearFilters: () => void;
	/** The list filter for the conditions that are complete and valid, or undefined. */
	where: Record<string, unknown> | undefined;
	/** Conditions in `where`. */
	appliedCount: number;
	/** Status of every condition, by condition id. */
	conditions: ReadonlyMap<string, ConditionStatus>;
	/** Conditions of `initialFilters` the model does not support. */
	dropped: readonly SheetsViewStateDrop[];
}

export interface UseDataFilteringConfig {
	/** The table model, or null while it loads. */
	model: TableModel | null;
	/** Filters to start with, for example from a saved view. */
	initialFilters?: SheetsFilterGroup;
	/** Models of related tables, for "linked record contains" conditions. */
	relatedModel?: (key: TableKey) => TableModel | null;
}

/**
 * Headless filter state over the table model, for a custom shell. The built-in
 * grid uses the same pieces through `useSheetsView`.
 */
export function useDataFiltering({ model, initialFilters, relatedModel }: UseDataFilteringConfig): DataFilteringContextValue {
	const [raw, setRaw] = useState<SheetsFilterGroup>(() => initialFilters ?? createFilterGroup());
	const clearFilters = useCallback(() => setRaw(createFilterGroup()), []);

	return useMemo((): DataFilteringContextValue => {
		if (!model) {
			return { filters: raw, setFilters: setRaw, clearFilters, where: undefined, appliedCount: 0, conditions: new Map(), dropped: [] };
		}
		const { state, dropped } = validateSheetsViewState(
			{ version: SHEETS_VIEW_STATE_VERSION, filters: raw, sort: [], search: '' },
			model,
		);
		const query = buildViewQuery(state, model, relatedModel);
		return {
			filters: state.filters,
			setFilters: setRaw,
			clearFilters,
			where: query.where,
			appliedCount: query.appliedCount,
			conditions: query.conditions,
			dropped,
		};
	}, [model, raw, relatedModel, clearFilters]);
}

import { useCallback } from 'react';

import type { SheetsSelection } from '../../selection/selection-model';
import { SHEETS_CONCURRENCY } from '../../config/sheets-concurrency';
import { sheetsLogger } from '../../utils/sheets-logger';
import { getDraftMeta } from '../row-model';
import type { SheetsRowIdentifier } from '../../row-identity';

interface OperationFeedbackCallbacks {
	onStart?: (type: 'delete', total: number) => string;
	onProgress?: (id: string, completed: number, failed: number) => void;
	onComplete?: (id: string, status: 'success' | 'partial' | 'error', message: string) => void;
}

type DeleteOutcome = { status: 'success' | 'partial' | 'error'; message: string } | null;

/**
 * Build the completion toast for a bulk delete, distinguishing UNSAVED draft rows
 * (discarded client-side, nothing hit the server) from real server-row deletes.
 *
 * `drafts` = draft rows discarded, `deleted` = server rows deleted, `failed` =
 * server deletes that errored. All-success wording reflects reality:
 *   - only drafts  -> "Discarded N draft(s)"
 *   - only server  -> "Deleted N row(s)"  (unchanged)
 *   - mixed        -> "Deleted N rows, discarded M drafts"
 * The partial/error (failure) wording is unchanged from prior behavior.
 */
export function summarizeDeleteResult(drafts: number, deleted: number, failed: number): DeleteOutcome {
	const successes = drafts + deleted;

	if (failed === 0 && successes > 0) {
		let message: string;
		if (deleted === 0) {
			message = `${drafts} ${drafts === 1 ? 'draft' : 'drafts'} discarded`;
		} else if (drafts === 0) {
			message = deleted === 1 ? 'Row deleted' : `${deleted} rows deleted`;
		} else {
			message = `${deleted} ${deleted === 1 ? 'row' : 'rows'} deleted, ${drafts} ${drafts === 1 ? 'draft' : 'drafts'} discarded`;
		}
		return { status: 'success', message };
	}

	if (successes > 0 && failed > 0) {
		return { status: 'partial', message: `${successes} deleted, ${failed} not deleted` };
	}

	if (failed > 0) {
		return { status: 'error', message: failed === 1 ? 'Row not deleted' : `${failed} rows not deleted` };
	}

	return null;
}

export function useGridOperations(
	data: any[],
	deleteRow: (id: SheetsRowIdentifier) => Promise<any>,
	gridSelection: SheetsSelection | undefined,
	clearSelection: () => void,
	options?: {
		onRemoveDraftRow?: (draftRowId: string) => void;
		onAfterServerDeletes?: () => void;
		getRowIdentifier?: (row: Readonly<Record<string, unknown>>) => SheetsRowIdentifier | null;
		canDeleteServerRows?: boolean;
		feedback?: OperationFeedbackCallbacks;
		/** Called once after a bulk delete with the error of every server delete that failed. */
		onDeleteErrors?: (errors: readonly unknown[]) => void;
	},
) {
	const deleteRows = useCallback(async (rows: readonly number[]) => {
		if (rows.length === 0) return;

			// Start operation feedback
			const operationId = options?.feedback?.onStart?.('delete', rows.length);

			let successes = 0;
			let failures = 0;
			let serverSuccesses = 0;
			let draftDiscards = 0;
			const deleteErrors: unknown[] = [];
			const records = rows.map((idx) => data[idx]);
			let nextRecordIndex = 0;
			const workerCount = Math.min(SHEETS_CONCURRENCY.bulkDelete, records.length);

			const runDeleteWorker = async () => {
				while (nextRecordIndex < records.length) {
					const currentIndex = nextRecordIndex;
					nextRecordIndex += 1;
					const record = records[currentIndex];

					const draftMeta = getDraftMeta(record);
					if (draftMeta?.isDraft && options?.onRemoveDraftRow) {
						const draftRowId = draftMeta.draftRowId;
						if (draftRowId) {
							options.onRemoveDraftRow(draftRowId);
							successes += 1;
							draftDiscards += 1;
						} else {
							failures += 1;
						}
					} else if (options?.canDeleteServerRows !== false) {
						const identifier = options?.getRowIdentifier
							? options.getRowIdentifier(record)
							: typeof record?.id === 'string' || typeof record?.id === 'number'
								? record.id
								: null;
						if (identifier === null) {
							failures += 1;
							continue;
						}
						try {
							await deleteRow(identifier);
							successes += 1;
							serverSuccesses += 1;
						} catch (error) {
							sheetsLogger().error('Failed to delete record', { identifier, error });
							deleteErrors.push(error);
							failures += 1;
						}
					} else {
						failures += 1;
					}

					if (operationId) {
						options?.feedback?.onProgress?.(operationId, successes, failures);
					}
				}
			};

			await Promise.all(Array.from({ length: workerCount }, () => runDeleteWorker()));

			// Complete operation feedback — distinguish discarded drafts from server deletes.
			if (operationId) {
				const outcome = summarizeDeleteResult(draftDiscards, serverSuccesses, failures);
				if (outcome) {
					options?.feedback?.onComplete?.(operationId, outcome.status, outcome.message);
				}
			}

		if (deleteErrors.length > 0) {
			options?.onDeleteErrors?.(deleteErrors);
		}

		if (serverSuccesses > 0) {
			options?.onAfterServerDeletes?.();
		}

		// Always clear selection so indices don't point to new rows after deletion
		clearSelection();
	}, [data, deleteRow, clearSelection, options]);

	const deleteSelected = useCallback(() => deleteRows(gridSelection?.rows.toArray() ?? []), [deleteRows, gridSelection]);

	return {
		deleteRows,
		deleteSelected,
	};
}

import { useMemo } from 'react';

import type { SheetsSelection } from '../../selection/selection-model';
import type { DraftRow } from '../../store/draft-rows-slice';
import { getDraftMeta, type DraftMeta } from '../row-model';

interface DraftRowsTableState {
	order: string[];
	map: Record<string, DraftRow>;
	template: Record<string, unknown>;
	metaVersion: string;
	columnOrder: string[];
}

export interface DraftRowEntry {
	draftRowId: string;
	draftRow: DraftRow;
}

interface UseGridSelectionStateParams {
	gridSelection: SheetsSelection | undefined;
	combinedRows: any[];
	draftRowsTable?: DraftRowsTableState;
}

export function useGridSelectionState({ gridSelection, combinedRows, draftRowsTable }: UseGridSelectionStateParams) {
	const selectedRowIndices = useMemo(() => {
		if (!gridSelection) return [] as number[];
		return gridSelection.rows.toArray();
	}, [gridSelection]);

	const selectedRowCount = selectedRowIndices.length;

	const selectedDraftRowEntries = useMemo(() => {
		if (!draftRowsTable || selectedRowIndices.length === 0) return [] as DraftRowEntry[];

		return selectedRowIndices
			.map((rowIndex) => getDraftMeta(combinedRows[rowIndex]))
			.filter((meta): meta is DraftMeta => Boolean(meta?.draftRowId))
			.map((meta) => {
				const draftRow = draftRowsTable.map[meta.draftRowId];
				return draftRow ? { draftRowId: meta.draftRowId, draftRow } : null;
			})
			.filter((entry): entry is DraftRowEntry => entry !== null);
	}, [draftRowsTable, selectedRowIndices, combinedRows]);

	const hasDraftSelection = selectedDraftRowEntries.length > 0;

	return {
		selectedRowIndices,
		selectedRowCount,
		selectedDraftRowEntries,
		hasDraftSelection,
	};
}

import { useCallback, useMemo, useReducer } from 'react';

import { emptySheetsSelection, moveActive, selectCell } from '../../selection/selection-model';
import type { SheetsSelection } from '../../selection/selection-model';

// Centralized grid state interface. Filter, sort and search state lives in
// `useSheetsView` (grid/view-state), which validates it against the table model.
export interface GridState {
	// Pagination state
	pageIndex: number;

	// Column state
	columnWidths: Map<string, number>;

	// Selection state (native SheetsSelection — glide is only a derived projection now).
	// Field name kept as `gridSelection` to minimize consumer churn during the port.
	gridSelection: SheetsSelection | undefined;
}

// Action types for state updates
export type GridAction =
	| { type: 'SET_PAGE_INDEX'; payload: number }
	| { type: 'RESIZE_COLUMN'; payload: { id: string; width: number } }
	| { type: 'SET_GRID_SELECTION'; payload: SheetsSelection | undefined }
	| { type: 'SET_ACTIVE_CELL'; payload: { col: number; row: number } }
	| { type: 'MOVE_ACTIVE'; payload: { dCol: number; dRow: number; colCount: number; rowCount: number } }
	| { type: 'RESET_PAGE_IF_NEEDED'; payload: { totalPages: number } };

// Initial state factory
function createInitialGridState(): GridState {
	return {
		pageIndex: 0,
		columnWidths: new Map(),
		gridSelection: undefined,
	};
}

// State reducer with type-safe action handling
function gridStateReducer(state: GridState, action: GridAction): GridState {
	switch (action.type) {
		case 'SET_PAGE_INDEX':
			return {
				...state,
				pageIndex: action.payload,
			};

		case 'RESIZE_COLUMN': {
			const newColumnWidths = new Map(state.columnWidths);
			newColumnWidths.set(action.payload.id, action.payload.width);
			return {
				...state,
				columnWidths: newColumnWidths,
			};
		}

		case 'SET_GRID_SELECTION':
			return {
				...state,
				gridSelection: action.payload,
			};

		case 'SET_ACTIVE_CELL': {
			const { col, row } = action.payload;
			return {
				...state,
				gridSelection: selectCell(state.gridSelection ?? emptySheetsSelection, col, row),
			};
		}

		case 'MOVE_ACTIVE': {
			const { dCol, dRow, colCount, rowCount } = action.payload;
			return {
				...state,
				gridSelection: moveActive(state.gridSelection ?? emptySheetsSelection, dCol, dRow, colCount, rowCount),
			};
		}

		case 'RESET_PAGE_IF_NEEDED': {
			const { totalPages } = action.payload;
			if (state.pageIndex >= totalPages) {
				return {
					...state,
					pageIndex: Math.max(0, totalPages - 1),
				};
			}
			return state;
		}

		default:
			return state;
	}
}

// Custom hook for grid state management
export function useGridState() {
	const [state, dispatch] = useReducer(gridStateReducer, undefined, createInitialGridState);

	const setPageIndex = useCallback((pageIndex: number) => {
		dispatch({ type: 'SET_PAGE_INDEX', payload: pageIndex });
	}, []);

	const resizeColumn = useCallback((id: string, width: number) => {
		dispatch({ type: 'RESIZE_COLUMN', payload: { id, width } });
	}, []);

	const setGridSelection = useCallback((selection: SheetsSelection | undefined) => {
		dispatch({ type: 'SET_GRID_SELECTION', payload: selection });
	}, []);

	const setActiveCell = useCallback((col: number, row: number) => {
		dispatch({ type: 'SET_ACTIVE_CELL', payload: { col, row } });
	}, []);

	const moveActiveCell = useCallback((dCol: number, dRow: number, colCount: number, rowCount: number) => {
		dispatch({ type: 'MOVE_ACTIVE', payload: { dCol, dRow, colCount, rowCount } });
	}, []);

	const resetPageIfNeeded = useCallback((totalPages: number) => {
		dispatch({ type: 'RESET_PAGE_IF_NEEDED', payload: { totalPages } });
	}, []);

	// Stable object identity (avoid prop/effect churn in consumers)
	const actions = useMemo(
		() => ({
			setPageIndex,
			resizeColumn,
			setGridSelection,
			setActiveCell,
			moveActiveCell,
			resetPageIfNeeded,
		}),
		[
			setPageIndex,
			resizeColumn,
			setGridSelection,
			setActiveCell,
			moveActiveCell,
			resetPageIfNeeded,
		],
	);

	return {
		state,
		actions,
	};
}

/**
 * Hook for integrating infinite scroll with the data grid
 * Wraps useSheetsInfiniteTable and provides grid-specific utilities
 */
import { useCallback, useMemo } from 'react';

import type { MetaField, MetaQuery, TableModel } from '@constructive-io/data';

import { useSheetsMeta } from '../../hooks/use-sheets-meta';
import { useSheetsInfiniteTable, type UseInfiniteTableOptions } from '../../hooks/use-sheets-infinite-table';

import { useTableModel } from '../../hooks/use-table-model';
import { gridRelationFieldNames } from '../../relations/relation-columns';
import { gridRelationSelection } from '../../hooks/list-query';
import { normalizeServerRow } from '../sheets.utils';
import { buildFieldMetaMap, findTableMeta } from './use-load-grid';

type RowRecord = Record<string, unknown>;

/** Native inclusive row window — the DOM grid's visible-range shape (no glide Rectangle). */
export interface VisibleRowRange {
	startIndex: number;
	endIndex: number;
}

type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;

export interface UseInfiniteGridDataOptions extends Omit<UseInfiniteTableOptions, 'select'> {
	tableName: string;
	/** Relation fields to fetch, for example the ones the view shows. Omitted: every relation the grid shows. */
	relations?: readonly string[];
}

export interface UseInfiniteGridDataResult {
	/** Get row at index, returns null if not loaded */
	getRowAtIndex: (index: number) => RowRecord | null;
	/** Total count of rows */
	totalCount: number;
	/** Check if row is loaded */
	isRowLoaded: (rowIndex: number) => boolean;
	/** Prefetch the rows in an inclusive visible window (native range, not a glide Rectangle). */
	onVisibleRegionChanged: (range: VisibleRowRange) => void;
	/** Whether data is loading */
	isLoading: boolean;
	/** True while a page request for the current options is in flight, also while placeholder rows from the previous options show */
	isFetching: boolean;
	/** Whether initial data has been fetched */
	hasInitialData: boolean;
	/** Error if any */
	error: Error | null;
	/** Invalidate and refetch all data */
	invalidate: () => void;
	/**
	 * Optimistically update a single row in the cache without refetching.
	 * Used after successful cell edits to avoid full grid refresh.
	 * @param rowIndex The index of the row to update
	 * @param patch Partial row data to merge with existing row
	 * @returns true if the row was found and updated, false on a cache miss
	 */
	updateRowAtIndex: (rowIndex: number, patch: Partial<RowRecord>) => boolean;
	/** Table metadata */
	tableMeta: MetaTable | null;
	/** The table model, or null while it loads. */
	tableModel: TableModel | null;
	/** Field metadata map */
	fieldMetaMap: Map<string, MetaField>;
	/** All relation field names */
	allRelationFields: string[];
	/** Page size */
	pageSize: number;
}

/**
 * Hook that provides infinite scroll data loading for the grid
 */
export function useInfiniteGridData({
	tableName,
	pageSize = 100,
	orderBy,
	where,
	columns,
	relations,
	enabled = true,
}: UseInfiniteGridDataOptions): UseInfiniteGridDataResult {
	// Get metadata
	const { data: meta, error: metaError } = useSheetsMeta({ enabled });

	const tableMeta = useMemo<MetaTable | null>(() => findTableMeta(meta, tableName), [meta, tableName]);

	// `_meta` fields by name, for quick lookup
	const fieldMetaMap = useMemo(() => {
		const fields = (tableMeta?.fields as MetaField[]) || [];
		return buildFieldMetaMap(fields);
	}, [tableMeta]);

	// The relations the grid shows, from the table model (the same cache entry the pages use).
	const { model: relationModel } = useTableModel(tableName, { enabled });
	const allRelationFields = useMemo<string[]>(() => gridRelationFieldNames(relationModel), [relationModel]);

	const relationFieldNames = useMemo(() => new Set(allRelationFields), [allRelationFields]);

	// The stable options key compares options by content, so a new `relations` array with the same fields reuses the pages.
	const fieldSelection = useMemo(() => gridRelationSelection(allRelationFields, relations), [allRelationFields, relations]);

	// Use the infinite table hook
	const infiniteTable = useSheetsInfiniteTable<RowRecord>(tableName, {
		pageSize,
		orderBy,
		where,
		columns,
		select: fieldSelection,
		enabled,
	});

	// One normalized row per server row object. A server row is never changed in place (an
	// optimistic update writes a new row object), so a row read twice is the same object: the
	// cells keep their memoized output and the normalization runs once per row, not per read.
	const normalizedRows = useMemo(() => new WeakMap<RowRecord, RowRecord>(), [relationFieldNames]);
	const readRow = infiniteTable.getRowAtIndex;
	const getRowAtIndex = useCallback(
		(rowIndex: number): RowRecord | null => {
			const rawRow = readRow(rowIndex);
			if (rawRow === null) return null;
			let row = normalizedRows.get(rawRow);
			if (!row) {
				row = normalizeServerRow(rawRow, relationFieldNames);
				normalizedRows.set(rawRow, row);
			}
			return row;
		},
		[readRow, normalizedRows, relationFieldNames],
	);

	// Prefetch rows for an inclusive visible window (native range).
	const ensureRowsLoaded = infiniteTable.ensureRowsLoaded;
	const onVisibleRegionChanged = useCallback(
		(range: VisibleRowRange) => {
			// Add buffer for smoother scrolling
			const buffer = Math.ceil(pageSize / 2);
			ensureRowsLoaded(Math.max(0, range.startIndex - buffer), range.endIndex + buffer);
		},
		[ensureRowsLoaded, pageSize],
	);

	return useMemo(
		() => ({
			getRowAtIndex,
			totalCount: infiniteTable.totalCount,
			isRowLoaded: infiniteTable.isRowLoaded,
			onVisibleRegionChanged,
			isLoading: infiniteTable.isLoading,
			isFetching: infiniteTable.isFetching,
			hasInitialData: infiniteTable.hasInitialData,
			error: metaError ?? infiniteTable.error,
			invalidate: infiniteTable.invalidate,
			// Optimistically update a single row without refetching; false on a cache miss so callers refetch.
			updateRowAtIndex: infiniteTable.updateRowAtIndex,
			tableMeta,
			tableModel: infiniteTable.model,
			fieldMetaMap,
			allRelationFields,
			pageSize,
		}),
		[getRowAtIndex, infiniteTable, onVisibleRegionChanged, metaError, tableMeta, fieldMetaMap, allRelationFields, pageSize],
	);
}

import { useMemo } from 'react';
import type { ReactNode } from 'react';

import { assessTableWriteCapability, findMetaTable, getRowIdentityDefinition, metaTablesOf } from '@constructive-io/data';
import type {
	FieldSelection,
	MetaField,
	MetaQuery,
	TableModel,
	TableWriteCapability,
} from '@constructive-io/data';

import { useSheetsMeta } from '../../hooks/use-sheets-meta';
import { useSheetsTable, type UseTableResult } from '../../hooks/use-sheets-table';
import { useTableModel } from '../../hooks/use-table-model';
import { gridRelationSelection } from '../../hooks/list-query';
import { gridRelationFieldNames } from '../../relations/relation-columns';
import { createColumnSchemaFromMeta } from '../../cell-types/type-mapping';
import type { TableSchema, ColumnSchema } from '../../cell-types/types';
import { resolveSheetsRowIdentity } from '../../row-identity';

type MetaTable = NonNullable<NonNullable<NonNullable<MetaQuery['_meta']>['tables']>[number]>;
type RowRecord = Record<string, unknown>;
type TableOperations = Pick<UseTableResult<RowRecord>, 'update' | 'delete'>;
type CreatedRow = Record<string, unknown>;

// Data loading context type
export interface DataLoadingContextValue {
	// Table data
	data: RowRecord[];
	totalCount: number;
	// Loading states
	isLoading: boolean;
	/** True while a rows request for the current options is in flight, also while the previous rows are still shown. */
	isFetching: boolean;
	isError: boolean;
	error: Error | null;
	// CRUD operations
	update: TableOperations['update'];
	create: (data: Record<string, unknown>) => Promise<{ createdRow?: CreatedRow | null }>;
	delete: TableOperations['delete'];
	// Refetch the table query (used by the error-state retry)
	refetch: () => Promise<unknown>;
	// Meta information
	meta: MetaQuery | undefined;
	tableMeta: MetaTable | null;
	/** The table model: kinds, options, write flags, relations, sort and filter names. Null while it loads. */
	tableModel: TableModel | null;
	writeCapability: TableWriteCapability | null;
	tableSchema: TableSchema | null;
	fieldMetaMap: Map<string, MetaField>;
	allRelationFields: string[];
}

// Data loading hook configuration
export interface UseDataLoadingConfig {
	tableName: string;
	enabled?: boolean;
	queryOptions: {
		limit?: number;
		offset?: number;
		orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
		/** A filter in the server's filter input shape (any operator the model reports, relation and search fields included). */
		where?: Readonly<Record<string, unknown>>;
		/** Columns to fetch (the primary key and relation keys are always added). Omitted: every readable column. */
		columns?: readonly string[];
		/** Relation fields to fetch, for example the ones the view shows. Omitted: every relation the grid shows. */
		relations?: readonly string[];
	};
}

/**
 * `_meta` fields by name. Cell routing reads the column model; this map stays for
 * consumer cell-type `match()` (`pgType`, `subtype`), legacy relation routing and
 * draft column order.
 */
export function buildFieldMetaMap(fields: readonly (MetaField | null)[] | null | undefined): Map<string, MetaField> {
	const map = new Map<string, MetaField>();
	for (const field of fields ?? []) {
		if (field?.name) map.set(field.name, field);
	}
	return map;
}

// Main data loading hook
export function useDataLoading({
	tableName,
	enabled = true,
	queryOptions,
}: UseDataLoadingConfig) {
	// Meta data for table information
	const { data: meta, isLoading: isMetaLoading, error: metaError } = useSheetsMeta({ enabled });

	const tableMeta = useMemo<MetaTable | null>(() => findTableMeta(meta, tableName), [meta, tableName]);

	// Table schema for form integration
	const tableSchema = useMemo<TableSchema | null>(() => buildTableSchema(tableMeta), [tableMeta]);
	const writeCapability = useMemo<TableWriteCapability | null>(
		() => tableMeta ? assessTableWriteCapability(tableMeta) : null,
		[tableMeta],
	);

	// `_meta` fields by name, for quick lookup
	const fieldMetaMap = useMemo(() => {
		const fields = (tableMeta?.fields as MetaField[]) || [];
		return buildFieldMetaMap(fields);
	}, [tableMeta]);

	// The relations the grid shows, from the table model (the same cache entry the rows query uses).
	const { model: relationModel } = useTableModel(tableName);
	const allRelationFields = useMemo(() => gridRelationFieldNames(relationModel), [relationModel]);

	// Query keys compare options by content, so a new `relations` array with the same fields reuses the cache.
	const { relations: requestedRelations, ...listOptions } = queryOptions;
	const relationSelection = useMemo<FieldSelection>(
		() => gridRelationSelection(allRelationFields, requestedRelations),
		[allRelationFields, requestedRelations],
	);

	const tableData = useSheetsTable<RowRecord>(tableName, {
		...listOptions,
		// Leverage field selection to include relation fields when requested
		select: relationSelection,
		enabled,
	});
	const {
		data = [],
		totalCount,
		update: updateRow,
		create: createRow,
		delete: deleteRow,
		isLoading: isTableLoading,
		isFetching,
		error: tableError,
		refetch,
		model: tableModel,
	} = tableData;

	const create: DataLoadingContextValue['create'] = async (payload) => {
		const result = await createRow(payload);
		const createdRow = result?.createdRow;
		if (!createdRow || typeof createdRow !== 'object' || !tableMeta) {
			throw new Error(`Create mutation for '${tableName}' did not return a row identity.`);
		}
		const identity = resolveSheetsRowIdentity(tableMeta, createdRow);
		if (identity.status !== 'identified') {
			throw new Error(`Create mutation for '${tableName}' returned an incomplete primary-key identity.`);
		}

		return { createdRow: createdRow as CreatedRow };
	};

	// Combined loading and error states
	const isLoading = isMetaLoading || isTableLoading;
	const isError = !!metaError || !!tableError;
	const error = (metaError as Error | null) || (tableError as Error | null) || null;

	const contextValue: DataLoadingContextValue = useMemo(
		() => ({
			data,
			totalCount,
			isLoading,
			isFetching,
			isError,
			error,
			update: updateRow,
			create,
			delete: deleteRow,
			refetch,
			meta,
			tableMeta,
			tableModel,
			writeCapability,
			tableSchema,
			fieldMetaMap,
			allRelationFields,
		}),
		[
			data,
			totalCount,
			isLoading,
			isFetching,
			isError,
			error,
			updateRow,
			create,
			deleteRow,
			refetch,
			meta,
			tableMeta,
			tableModel,
			writeCapability,
			tableSchema,
			fieldMetaMap,
			allRelationFields,
		],
	);

	return {
		contextValue,
		Provider: ({ children }: { children: ReactNode }) => children,
	};
}

/** The `_meta` entry for a host table reference (name or `TableModel.key`), or null when unknown or ambiguous. */
export function findTableMeta(meta: MetaQuery | undefined, tableRef: string): MetaTable | null {
	if (!meta) return null;
	try {
		return findMetaTable(metaTablesOf(meta), tableRef);
	} catch {
		return null;
	}
}

function buildTableSchema(metaTable: MetaTable | null): TableSchema | null {
	if (!metaTable) return null;

	const columns: ColumnSchema[] = [];
	for (const field of metaTable.fields ?? []) {
		if (!field) continue;
		columns.push(createColumnSchemaFromMeta(field));
	}

	const identity = getRowIdentityDefinition(metaTable);
	const primaryKeyFields = identity.status === 'keyed'
		? identity.fields.map((field) => field.fieldName)
		: [];

	const inflection = metaTable.inflection;

	const metadata: TableSchema['metadata'] = {
		label: metaTable.name ?? undefined,
		description: inflection?.tableType ?? inflection?.allRows ?? undefined,
		primaryKey: primaryKeyFields.length > 0 ? primaryKeyFields : undefined,
	};

	return {
		id: metaTable.name ?? 'unknown-table',
		name: metaTable.name ?? 'unknown-table',
		columns,
		metadata,
	};
}

// Convenience hooks for accessing specific parts of the context
export function useTableData(): null {
	return null;
}
export function useTableOperations(): null {
	return null;
}
export function useTableMeta(): null {
	return null;
}

import { useCallback, useEffect, useMemo, useState } from 'react';

// Data pagination context type
export interface DataPaginationContextValue {
	// Pagination state
	pageIndex: number;
	pageSize: number;
	totalCount: number;
	totalPages: number;

	// Computed values
	hasNextPage: boolean;
	hasPreviousPage: boolean;
	startIndex: number;
	endIndex: number;

	// Actions
	setPageIndex: (index: number) => void;
	setPageSize: (size: number) => void;
	goToNextPage: () => void;
	goToPreviousPage: () => void;
	goToFirstPage: () => void;
	goToLastPage: () => void;
}

// Data pagination hook configuration
export interface UseDataPaginationConfig {
	initialPageSize?: number;
	initialPageIndex?: number;
	totalCount?: number;
	onPageChange?: (pageIndex: number, pageSize: number) => void;
}

// Main data pagination hook — uses local state instead of global Zustand store
export function useDataPagination({
	initialPageSize = 100,
	initialPageIndex = 0,
	totalCount = 0,
	onPageChange,
}: UseDataPaginationConfig) {
	const [pageIndex, setPageIndexState] = useState(initialPageIndex);
	const [pageSize, setPageSizeState] = useState(initialPageSize);

	// Compute pagination values
	const totalPages = useMemo(() => Math.max(1, Math.ceil(totalCount / pageSize)), [totalCount, pageSize]);
	const hasNextPage = useMemo(() => pageIndex < totalPages - 1, [pageIndex, totalPages]);
	const hasPreviousPage = useMemo(() => pageIndex > 0, [pageIndex]);
	const startIndex = useMemo(() => pageIndex * pageSize + 1, [pageIndex, pageSize]);
	const endIndex = useMemo(() => Math.min((pageIndex + 1) * pageSize, totalCount), [pageIndex, pageSize, totalCount]);

	useEffect(() => {
		if (pageSize !== initialPageSize) {
			setPageSizeState(initialPageSize);
		}
	}, [initialPageSize]); // eslint-disable-line react-hooks/exhaustive-deps

	useEffect(() => {
		if (pageIndex !== initialPageIndex) {
			setPageIndexState(initialPageIndex);
		}
	}, [initialPageIndex]); // eslint-disable-line react-hooks/exhaustive-deps

	// Auto-adjust page index when total pages changes
	useEffect(() => {
		if (pageIndex >= totalPages && totalPages > 0) {
			setPageIndexState(Math.max(0, totalPages - 1));
		}
	}, [pageIndex, totalPages]);

	// Page index setter with callback
	const setPageIndex = useCallback(
		(index: number) => {
			const clampedIndex = Math.max(0, Math.min(index, totalPages - 1));
			setPageIndexState(clampedIndex);
			onPageChange?.(clampedIndex, pageSize);
		},
		[totalPages, pageSize, onPageChange],
	);

	// Page size setter with callback and reset to first page
	const setPageSize = useCallback(
		(size: number) => {
			setPageSizeState(size);
			setPageIndexState(0);
			onPageChange?.(0, size);
		},
		[onPageChange],
	);

	// Navigation actions
	const goToNextPage = useCallback(() => {
		if (hasNextPage) {
			setPageIndex(pageIndex + 1);
		}
	}, [hasNextPage, pageIndex, setPageIndex]);

	const goToPreviousPage = useCallback(() => {
		if (hasPreviousPage) {
			setPageIndex(pageIndex - 1);
		}
	}, [hasPreviousPage, pageIndex, setPageIndex]);

	const goToFirstPage = useCallback(() => {
		setPageIndex(0);
	}, [setPageIndex]);

	const goToLastPage = useCallback(() => {
		setPageIndex(totalPages - 1);
	}, [totalPages, setPageIndex]);

	const contextValue: DataPaginationContextValue = useMemo(
		() => ({
			pageIndex,
			pageSize,
			totalCount,
			totalPages,
			hasNextPage,
			hasPreviousPage,
			startIndex,
			endIndex,
			setPageIndex,
			setPageSize,
			goToNextPage,
			goToPreviousPage,
			goToFirstPage,
			goToLastPage,
		}),
		[
			pageIndex,
			pageSize,
			totalCount,
			totalPages,
			hasNextPage,
			hasPreviousPage,
			startIndex,
			endIndex,
			setPageIndex,
			setPageSize,
			goToNextPage,
			goToPreviousPage,
			goToFirstPage,
			goToLastPage,
		],
	);

	return {
		contextValue,
		Provider: ({ children }: { children: any }) => children,
	};
}

// Convenience hooks for accessing specific parts of the context
export function usePaginationState() {
	// Placeholder — real values come from the contextValue returned by useDataPagination
	return { pageIndex: 0, pageSize: 100 };
}

export function usePaginationActions() {
	// Placeholder — real actions come from the contextValue
	return {
		setPageIndex: (_index: number) => {},
		setPageSize: (_size: number) => {},
		goToNextPage: () => {},
		goToPreviousPage: () => {},
		goToFirstPage: () => {},
		goToLastPage: () => {},
	};
}

import { useCallback, useEffect, useRef } from 'react';

/**
 * Report a pointer press outside one part of the React tree.
 *
 * "Inside" follows the React tree, not the DOM: React events bubble out of portals to
 * the component that rendered them, so a press in a portalled surface the part owns (an
 * editor, popover, menu, dialog or panel) counts as inside. Spread the returned handler
 * on the part's root element. `onPressOutside` runs only while `active` is true.
 *
 * The part's capture handler marks the press itself, and the document's bubble listener
 * reads that mark. That holds wherever React listens: under a host that hydrates the whole
 * document (Next.js), React's own document listeners run before any added later, so a
 * flag reset by a document capture listener would mark every press as outside.
 */
export function usePressOutside(active: boolean, onPressOutside: () => void): { onPointerDownCapture: (event: { nativeEvent: Event }) => void } {
	const insidePresses = useRef(new WeakSet<Event>());
	const onPressOutsideRef = useRef(onPressOutside);
	onPressOutsideRef.current = onPressOutside;

	useEffect(() => {
		if (!active) return;
		// Bubble phase: every capture handler, React's included, has run for this press.
		const finish = (event: PointerEvent) => {
			if (!insidePresses.current.has(event)) onPressOutsideRef.current();
		};
		document.addEventListener('pointerdown', finish);
		return () => document.removeEventListener('pointerdown', finish);
	}, [active]);

	const onPointerDownCapture = useCallback((event: { nativeEvent: Event }) => {
		insidePresses.current.add(event.nativeEvent);
	}, []);
	return { onPointerDownCapture };
}

// Fresh data when the user comes back. A grid left open in a background tab keeps the rows
// and the table's shape it last read; when the page is shown again (visible, focused or back
// online) after a real absence, the grid reads them again. A quick tab switch does nothing, and
// nothing is refetched under an open editor or a save in flight: that waits until they finish.
import { useEffect, useRef, useState } from 'react';

/** How long the page must be away before coming back refreshes it. */
export const RETURN_REFRESH_AFTER_MS = 30_000;

export interface RefreshOnReturnOptions {
	/** Read the data again. */
	refresh: () => void;
	/** An editor is open or a save is in flight: the refresh waits for it. */
	busy: boolean;
	afterMs?: number;
}

export function useRefreshOnReturn({ refresh, busy, afterMs = RETURN_REFRESH_AFTER_MS }: RefreshOnReturnOptions): void {
	const awaySince = useRef<number | null>(null);
	const [due, setDue] = useState(false);

	useEffect(() => {
		const leave = () => {
			if (awaySince.current === null) awaySince.current = Date.now();
		};
		const back = () => {
			if (document.visibilityState === 'hidden') return;
			const since = awaySince.current;
			awaySince.current = null;
			if (since !== null && Date.now() - since >= afterMs) setDue(true);
		};
		const onVisibility = () => (document.visibilityState === 'hidden' ? leave() : back());
		window.addEventListener('blur', leave);
		window.addEventListener('offline', leave);
		window.addEventListener('focus', back);
		window.addEventListener('online', back);
		document.addEventListener('visibilitychange', onVisibility);
		return () => {
			window.removeEventListener('blur', leave);
			window.removeEventListener('offline', leave);
			window.removeEventListener('focus', back);
			window.removeEventListener('online', back);
			document.removeEventListener('visibilitychange', onVisibility);
		};
	}, [afterMs]);

	const refreshRef = useRef(refresh);
	refreshRef.current = refresh;
	useEffect(() => {
		if (!due || busy) return;
		setDue(false);
		refreshRef.current();
	}, [due, busy]);
}

/**
 * useUndoRedo — a tiny two-stack history for grid mutations.
 *
 * Each {@link HistoryEntry} carries its own inverse: `undo` reverts the change,
 * `redo` re-applies it (both may be async — a server mutation). `record` pushes a
 * new entry onto the undo stack and CLEARS the redo stack (a fresh edit forks the
 * timeline). `undo`/`redo` move the top entry across the two stacks, running the
 * matching thunk. A thunk that throws did not change anything: the entry goes back
 * where it was, under any edit recorded meanwhile, so the step can be tried again (the
 * entry reports its own failure). A stack cleared or forked since has no place for it.
 * Steps run one at a time: one asked for while another runs (a held Mod+Z against a
 * slow server) starts when it ends, so writes reach the server in the order asked. An
 * edit or a clear cancels the steps asked for before it that have not started.
 *
 * The stacks live in refs so the handler identities (`undo`/`redo`/`record`) stay
 * STABLE across renders — keydown wiring binds them once. `canUndo`/`canRedo` are
 * reactive (state) so chrome can disable buttons. Depth is capped to bound memory.
 */
import { useCallback, useRef, useState } from 'react';

/** One reversible step: a label plus its undo / redo thunks (throw when nothing changed). */
export interface HistoryEntry {
	label: string;
	undo: () => Promise<void> | void;
	redo: () => Promise<void> | void;
}

export interface UseUndoRedoResult {
	/** Push a new entry; clears the redo stack. */
	record: (entry: HistoryEntry) => void;
	/** Pop the top undo entry, run its `undo`, push it to the redo stack. No-op when empty. */
	undo: () => Promise<void>;
	/** Pop the top redo entry, run its `redo`, push it to the undo stack. No-op when empty. */
	redo: () => Promise<void>;
	/** True when the undo stack is non-empty. */
	canUndo: boolean;
	/** True when the redo stack is non-empty. */
	canRedo: boolean;
	/** Drop all history. */
	clear: () => void;
}

const DEFAULT_MAX_DEPTH = 100;

export function useUndoRedo(maxDepth: number = DEFAULT_MAX_DEPTH): UseUndoRedoResult {
	const undoStack = useRef<HistoryEntry[]>([]);
	const redoStack = useRef<HistoryEntry[]>([]);
	// Moves on at every edit and clear: a step asked for before one of them does not run after it.
	const generation = useRef(0);
	const [canUndo, setCanUndo] = useState(false);
	const [canRedo, setCanRedo] = useState(false);

	const sync = useCallback(() => {
		setCanUndo(undoStack.current.length > 0);
		setCanRedo(redoStack.current.length > 0);
	}, []);

	const record = useCallback(
		(entry: HistoryEntry) => {
			undoStack.current.push(entry);
			if (undoStack.current.length > maxDepth) undoStack.current.shift();
			redoStack.current = [];
			generation.current += 1;
			sync();
		},
		[maxDepth, sync],
	);

	// The step running now; the next one waits for it. A step never rejects.
	const running = useRef<Promise<void>>(Promise.resolve());

	// Move the top entry from one stack to the other and run it; it moves back if it throws.
	const step = useCallback(
		(from: { current: HistoryEntry[] }, to: { current: HistoryEntry[] }, run: (entry: HistoryEntry) => Promise<void> | void) => {
			const asked = generation.current;
			const next = running.current.then(async () => {
				if (generation.current !== asked) return;
				const source = from.current;
				const entry = source.pop();
				if (!entry) return;
				const place = source.length;
				to.current.push(entry);
				sync();
				try {
					await run(entry);
				} catch {
					// Nothing changed: the entry leaves the other stack and goes back to its place,
					// under any edit recorded meanwhile. A stack replaced since (a clear, or the redo
					// stack an edit forked) has no place for it, so it is dropped.
					const index = to.current.lastIndexOf(entry);
					if (index >= 0) to.current.splice(index, 1);
					if (from.current === source) source.splice(Math.min(place, source.length), 0, entry);
					sync();
				}
			});
			running.current = next;
			return next;
		},
		[sync],
	);
	const undo = useCallback(() => step(undoStack, redoStack, (entry) => entry.undo()), [step]);
	const redo = useCallback(() => step(redoStack, undoStack, (entry) => entry.redo()), [step]);

	const clear = useCallback(() => {
		undoStack.current = [];
		redoStack.current = [];
		generation.current += 1;
		sync();
	}, [sync]);

	return { record, undo, redo, canUndo, canRedo, clear };
}

/**
 * Class names shared by the grid's own popovers and menus (toolbar popovers, the
 * header menu, the context menu).
 *
 * They open and close without motion: people open them many times a session, several
 * from a shortcut, so an entrance animation only makes them wait
 * (https://craft.gustavofior.com/hover-restraint).
 */
export const INSTANT_POPUP = 'transition-none';

/** The toolbar popovers (views, fields, sort, filters) share one inset, so their titles line up. */
export const TOOLBAR_POPOVER = `p-4 ${INSTANT_POPUP}`;

// The overlay editor element for the active cell, with its placement.
import type { TableModel } from '@constructive-io/data';

import type { CellTypeRegistry } from '../../cell-types/cell-type-registry';
import type { SheetsCellResolution } from '../../grid-dom/use-sheets-content';
import { resolveEditIntent } from '../../grid-dom/editors/edit-intent';
import type { useOverlayController } from '../../grid-dom/overlay/use-overlay-controller';
import { computeOverlayGeometry } from '../editors/overlay-viewport-guard';
import { getDraftMeta, type SheetsRow } from '../row-model';
import type { DraftSubmitResult } from '../draft-types';

// Overlay flip-geometry knobs — MUST match the OverlayManager's private constants so
// the geometry we hand the editor via EditorProps.overlay matches where it's placed.
const OVERLAY_MARGIN_PX = 12;
const OVERLAY_MIN_BELOW_PX = 320;

type OverlayController = ReturnType<typeof useOverlayController>;
type ActiveOverlay = NonNullable<OverlayController['active']>;
type MediaDraft = NonNullable<ActiveOverlay['mediaDraft']>;

export interface ActiveEditorInput {
	active: OverlayController['active'];
	mediaDraft: MediaDraft | undefined;
	activeMediaDraft: MediaDraft | undefined;
	getSheetsCellContent: (rowIndex: number, colKey: string) => SheetsCellResolution;
	getEditorComponent: CellTypeRegistry['getEditorComponent'];
	combinedRows: SheetsRow[];
	getRowId: (row: SheetsRow | null | undefined, index: number) => string;
	tableName: string;
	tableModel: TableModel | null;
	commitBulkOrSingle: (rowIndex: number, colKey: string, value: unknown) => void;
	overlayClose: () => void;
	commitCellPatch: (rowIndex: number, patch: Record<string, unknown>) => void;
	submitDraftRow: (draftRowId: string) => Promise<DraftSubmitResult>;
	invalidateData: () => void;
}

// Resolve the active editor + its EditorProps. Computed in render (cheap, only when
// an overlay is open) — the cell resolution, value, native editor and flip geometry
// all derive from overlay.active, so no effect/state mirror is needed.
export function activeEditorElement({
	active,
	mediaDraft,
	activeMediaDraft,
	getSheetsCellContent,
	getEditorComponent,
	combinedRows,
	getRowId,
	tableName,
	tableModel,
	commitBulkOrSingle,
	overlayClose,
	commitCellPatch,
	submitDraftRow,
	invalidateData,
}: ActiveEditorInput) {
	if (!active || (mediaDraft && !activeMediaDraft)) return null;
	const resolution = activeMediaDraft?.resolution ?? getSheetsCellContent(active.rowIndex, active.colKey);
	// Resolve the editor through the SAME edit-intent resolver the activation branch
	// used (typeKey-driven, consumer-override aware). Only `overlay` intents ever open
	// here (openEditor short-circuits inline-toggle/none), but resolving again keeps a
	// single source of truth — and guards against a non-overlay intent slipping through.
	const intent = resolveEditIntent(resolution.typeKey, { readonly: resolution.cell.readonly }, getEditorComponent);
	if (intent.mode !== 'overlay') return null;
	const Editor = intent.editor;
	const row = combinedRows[active.rowIndex];
	const rowValue = activeMediaDraft ? activeMediaDraft.value : row?.[active.colKey];
	const geom = computeOverlayGeometry(
		typeof window !== 'undefined' ? window.innerHeight : 800,
		active.anchorRect.top,
		active.anchorRect.height,
		OVERLAY_MARGIN_PX,
		OVERLAY_MIN_BELOW_PX,
	);
	return {
		presetClass: Editor.overlayPresetClass,
		// Commit-on-click-away (Stage B): editors that own an onBlur→onCommit advertise it
		// so the OverlayManager dismisses by blurring (commit) instead of cancelling.
		dismissMode: Editor.commitsOnBlur ? ('commit' as const) : ('cancel' as const),
		element: (
			<Editor
				value={rowValue}
				cell={resolution.cell}
				colKey={active.colKey}
				rowId={activeMediaDraft?.rowId ?? getRowId(row, active.rowIndex)}
				rowIdentifier={resolution.rowIdentifier}
				row={row ?? null}
				rowIndex={active.rowIndex}
				tableName={tableName}
				fieldMeta={resolution.fieldMeta}
				relationInfo={resolution.relationInfo}
				column={resolution.column ?? null}
				relation={resolution.relation ?? null}
				table={tableModel}
				readOnlyReason={resolution.readOnlyReason ?? null}
				initialText={active.initialText}
				onCommit={(next) => {
					commitBulkOrSingle(active.rowIndex, active.colKey, next);
					overlayClose();
				}}
				onCommitPatch={(patch) => {
					if (!activeMediaDraft || getDraftMeta(row)?.draftRowId === activeMediaDraft.rowId) {
						commitCellPatch(active.rowIndex, patch);
					}
					overlayClose();
				}}
				onSubmitDraftRow={submitDraftRow}
				onInvalidateData={invalidateData}
				onCancel={overlayClose}
				overlay={{ maxHeight: geom.maxHeight, flipped: geom.shouldFlip }}
			/>
		),
	};
}

