// "Rows could not be loaded": overlays the empty body when the rows request fails after the
// table's model loaded. The toolbar stays above it, so a search or filter that the server
// refuses can be changed or cleared here; the server's own text stays under "Show details".
import { RiErrorWarningLine, RiFilterOffLine, RiRefreshLine } from '@remixicon/react';

import { Button } from '@/components/ui/button';

export interface SheetsRowsErrorProps {
	error: unknown;
	/** Filter conditions in the view. */
	activeFilterCount: number;
	/** A search narrows the rows. */
	searching: boolean;
	/** Clear the filters and the search. */
	onClear: () => void;
	/** Request the rows again. */
	onRetry: () => void;
	/** A host's own content for the panel (`slots.error`); replaces the default panel. */
	children?: React.ReactNode;
}

function serverText(error: unknown): string | null {
	if (error instanceof Error) return error.message || null;
	return typeof error === 'string' && error ? error : null;
}

function summaryOf(activeFilterCount: number, searching: boolean): string {
	if (searching && activeFilterCount > 0) return 'The search and the filters could not be applied.';
	if (searching) return 'The search could not be applied.';
	if (activeFilterCount > 0) return `The ${activeFilterCount === 1 ? 'filter' : 'filters'} could not be applied.`;
	return 'The rows of this table could not be loaded.';
}

export function SheetsRowsError({ error, activeFilterCount, searching, onClear, onRetry, children }: SheetsRowsErrorProps) {
	const narrowed = searching || activeFilterCount > 0;
	const details = serverText(error);
	return (
		<div
			data-part-id='sheets-rows-error'
			className='bg-background/80 absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-center'
		>
			{children ?? (
				<>
					<RiErrorWarningLine className='text-destructive h-8 w-8' aria-hidden='true' />
					<div className='space-y-1' role='alert'>
						<p className='text-foreground text-sm font-medium'>Rows could not be loaded</p>
						<p className='text-muted-foreground max-w-md text-sm'>{summaryOf(activeFilterCount, searching)}</p>
					</div>
					<div className='flex items-center gap-2'>
						{narrowed && (
							<Button variant='outline' size='sm' onClick={onClear}>
								<RiFilterOffLine className='h-4 w-4' aria-hidden='true' />
								<span>{activeFilterCount === 0 ? 'Clear search' : searching ? 'Clear filters and search' : 'Clear filters'}</span>
							</Button>
						)}
						<Button variant={narrowed ? 'ghost' : 'outline'} size='sm' onClick={onRetry}>
							<RiRefreshLine className='h-4 w-4' aria-hidden='true' />
							<span>Try again</span>
						</Button>
					</div>
					{details && (
						<details className='text-muted-foreground max-w-md text-xs'>
							<summary className='hover:text-foreground cursor-pointer select-none'>Show details</summary>
							<p className='mt-1 [overflow-wrap:anywhere]'>{details}</p>
						</details>
					)}
				</>
			)}
		</div>
	);
}

// The ONE event -> command pipeline of the grid: the command registry, the keymap and
// the interceptor chain, latched so the public `dispatch` stays referentially stable.
import { useCallback, useMemo, useRef } from 'react';

import type { GridCommandContext } from '../../commands/context';
import { makeDispatch, tailObserver, type Dispatch, type Interceptor } from '../../commands/dispatch';
import { DEFAULT_KEYMAP, type Binding } from '../../commands/keymap';
import { createGridCommandRegistry } from '../../commands/registry';
import type { GridCommandRegistry } from '../../commands/types';
import type { DataGridProps } from '../sheets.types';

export function useGridCommandPipeline({
	commands,
	keymap,
	interceptors,
	onCommand,
}: Pick<DataGridProps, 'commands' | 'keymap' | 'interceptors' | 'onCommand'>) {
	// ============== EVENT->COMMAND DISPATCH (P4 Phase 1) ==============
	// ONE interceptable pipeline: every grid event resolves to a named command and runs
	// through `dispatch`. The registry + keymap are latched (so a Phase 2 consumer override
	// is a ref swap, not a new dispatch identity); `ctxRef.current` is the assembled
	// GridCommandContext, repointed each render below (mirrors the openEditor ref-latch).
	// `dispatch` is useCallback([]) reading the refs, so it stays referentially STABLE — the
	// per-cell memo gates on the pointer callbacks that close over it, so it must never churn.
	// PUBLIC CUSTOMIZATION SEAM (P4 Phase 2): registry / keymap / interceptors derive from the
	// consumer props but rebuild ONLY when the prop IDENTITY changes (useMemo), so omitting them
	// is identical to the defaults. Each is latched into a ref so the keydown handler + dispatch
	// read the latest without re-creating. The PUBLIC `dispatch` callback stays referentially
	// STABLE (reads dispatchRef.current), so the per-cell memo never churns; dispatchRef itself is
	// rebuilt when the registry or interceptor list identity changes (additive, no identity leak).
	const registry = useMemo<GridCommandRegistry>(() => createGridCommandRegistry(commands), [commands]);
	// Consumer bindings scan FIRST (resolveKeyCommand is first-match-wins) so a rebind of a
	// built-in chord wins over the default; the defaults follow as the fallback set.
	const fullKeymap = useMemo<Binding[]>(() => [...(keymap ?? []), ...DEFAULT_KEYMAP], [keymap]);
	const keymapRef = useRef<Binding[]>(fullKeymap);
	keymapRef.current = fullKeymap;
	// Consumer interceptors are OUTERMOST (first-listed); the onCommand tail observer is appended
	// LAST so it sits innermost (after every consumer interceptor) and observes the real result.
	const chain = useMemo<Interceptor[]>(
		() => [...(interceptors ?? []), ...(onCommand ? [tailObserver(onCommand)] : [])],
		[interceptors, onCommand],
	);
	const ctxRef = useRef<GridCommandContext>(undefined as unknown as GridCommandContext);
	const dispatchRef = useRef<Dispatch>(undefined as unknown as Dispatch);
	dispatchRef.current = useMemo<Dispatch>(() => makeDispatch(registry, () => ctxRef.current, chain), [registry, chain]);
	const dispatch = useCallback<Dispatch>((command, native, payload) => dispatchRef.current(command, native, payload), []);

	// Enabled-state probe for the menu items: run the resolved command's `canRun` against the latched
	// context (same gate the dispatch core applies). A missing canRun means "always runnable".
	const isCommandEnabled = useCallback(
		(commandId: string, payload?: unknown) => {
			const cmd = registry.get(commandId);
			return cmd ? (cmd.canRun ? cmd.canRun(ctxRef.current, payload) : true) : false;
		},
		[registry],
	);

	return { registry, keymapRef, ctxRef, dispatch, isCommandEnabled };
}

// The right-click (and Shift+F10) context menu: its anchor state, and activating the
// pressed cell first when it sits outside the current selection.
import { useCallback, useState, type MutableRefObject } from 'react';

import type { Dispatch } from '../../commands/dispatch';
import type { SheetsSelection } from '../../selection/selection-model';
import type { ContextMenuState } from '../sheets.context-menu';

export function useGridContextMenu({
	selectionRef,
	dispatch,
}: {
	selectionRef: MutableRefObject<SheetsSelection | undefined>;
	dispatch: Dispatch;
}) {
	// ============== RIGHT-CLICK CONTEXT MENU (Stage B) ==============
	// A menu is just another EVENT SOURCE → dispatch. State is the pointer anchor (null = closed),
	// rendered ONCE at the grid level. `handleContextMenu` is STABLE (reads selectionRef + the stable
	// dispatch), so it never busts the per-cell memo. When the right-clicked cell sits OUTSIDE the
	// current active cell / selection range, we activate it first so the menu acts on the clicked cell.
	const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
	const handleContextMenu = useCallback(
		(col: number, row: number, clientX: number, clientY: number) => {
			const sel = selectionRef.current;
			const active = sel?.current?.cell;
			const range = sel?.current?.range;
			const inRange =
				!!range && col >= range.x && col < range.x + range.width && row >= range.y && row < range.y + range.height;
			const isActive = !!active && active[0] === col && active[1] === row;
			if (!isActive && !inRange) dispatch('cell.activate', undefined, { col, row });
			setContextMenu({ clientX, clientY });
		},
		[dispatch],
	);
	const closeContextMenu = useCallback(() => setContextMenu(null), []);

	return { contextMenu, setContextMenu, handleContextMenu, closeContextMenu };
}

// The grid's own CSV export (selected rows, else the loaded ones): the toolbar's
// "Export selected" button and `SheetsHandle.exportCsv()`.
import { useCallback } from 'react';

import { loadedRowsCsv } from '../../import-export/export-view';
import { downloadTextFile } from '../../import-export/files';
import type { SheetsSelection } from '../../selection/selection-model';
import type { SheetsRow } from '../row-model';
import type { DataGridProps } from '../sheets.types';
import type { SheetsShellBindings } from '../use-sheets';

export interface UseGridCsvExportInput {
	tableName: string;
	csvExport: DataGridProps['csvExport'];
	selection: SheetsSelection | undefined;
	combinedRows: SheetsRow[];
	shell: SheetsShellBindings;
}

export function useGridCsvExport({ tableName, csvExport, selection, combinedRows, shell }: UseGridCsvExportInput) {
	// Imperative getSelectedRows reads the SAME canonical RangeSet the canvas handle uses.
	const getSelectedRows = useCallback(
		(): Record<string, unknown>[] =>
			(selection?.rows.toArray() ?? []).map((i) => combinedRows[i]).filter(Boolean) as Record<string, unknown>[],
		[selection, combinedRows],
	);

	// Shared CSV export body — selected rows if any, else the loaded/filtered set. Reused by
	// the imperative SheetsHandle.exportCsv() and the toolbar Export button (handleExport).
	const defaultProtectFormulas = csvExport?.protectFormulas ?? false;
	const runCsvExport = useCallback(
		(opts?: { columns?: string[]; filename?: string; protectFormulas?: boolean }) => {
			const selected = getSelectedRows();
			const rows = selected.length ? selected : (shell.combinedRows as Record<string, unknown>[]);
			// The same copy format as the full-view export: choice labels, JSON for structured values, linked-record labels.
			const text = loadedRowsCsv(shell.tableModel, rows, opts?.columns ?? shell.columnKeys, {
				protectFormulas: opts?.protectFormulas ?? defaultProtectFormulas,
			});
			downloadTextFile(text, opts?.filename ?? 'export.csv');
		},
		[defaultProtectFormulas, getSelectedRows, shell.combinedRows, shell.columnKeys, shell.tableModel],
	);

	// Toolbar Export button — same path as the imperative SheetsHandle.exportCsv().
	const handleExport = useCallback(() => runCsvExport({ filename: `${tableName}.csv` }), [runCsvExport, tableName]);

	return { getSelectedRows, runCsvExport, handleExport, defaultProtectFormulas };
}

// Cell editing in the DOM grid: the overlay (portal) and inline editors, their activation
// by the single edit-intent resolver, the range-aware commit, and following the edited
// cell while the grid scrolls. Churning values are latched into refs so the callbacks the
// cell host memo-gates on stay referentially stable.
import { useCallback, useEffect, useMemo, useRef } from 'react';

import type { SheetsConfig, SheetsScopeKey } from '../../context/sheets-context';
import type { Dispatch } from '../../commands/dispatch';
import type { NavAbsolutePayload } from '../../commands/registry';
import type { InlineEditMove } from '../../grid-dom/inline-cell-editor';
import { nextToggleValue } from '../../cell-types/column-value';
import { resolveEditIntent } from '../../grid-dom/editors/edit-intent';
import { ImageEditorDom } from '../../grid-dom/editors/image-editor';
import { useDateEditorPreload } from '../../grid-dom/editors/use-date-editor-preload';
import { useOverlayController } from '../../grid-dom/overlay/use-overlay-controller';
import type { OpenEditor } from '../../grid-dom/sheets-cell-host';
import { bulkEditWrites } from '../../selection/fill';
import type { SheetsSelection } from '../../selection/selection-model';
import type { GridEditingCell } from '../../table/grid-viewport';
import type { SheetsColumnDescriptor } from '../../table/use-sheets-table-instance';
import { getDraftMeta, type SheetsRow } from '../row-model';
import type { SheetsShellBindings } from '../use-sheets';
import { reportReadOnlyCell } from '../write-feedback';

export interface UseGridEditingInput {
	tableName: string;
	shell: SheetsShellBindings;
	config: SheetsConfig;
	canUpload: boolean;
	scopeKey: SheetsScopeKey;
	combinedRows: SheetsRow[];
	selection: SheetsSelection | undefined;
	columns: SheetsColumnDescriptor[];
	dispatch: Dispatch;
}

export function useGridEditing({ tableName, shell, config, canUpload, scopeKey, combinedRows, selection, columns, dispatch }: UseGridEditingInput) {
	// ============== NATIVE OVERLAY EDITING (Phase 4, additive) ==============
	// Open/close state for the native React-portal overlay editor. The host measures
	// the activated cell's rect (only it knows the cell DOM node) and calls openEditor.
	const overlay = useOverlayController();
	const overlayOpen = overlay.open;
	const overlayClose = overlay.close;
	const overlayReanchor = overlay.reanchor;
	const mediaDraft = overlay.active?.mediaDraft;
	const activeMediaDraft = canUpload && mediaDraft?.scopeKey === scopeKey && mediaDraft?.tableName === tableName
		? mediaDraft
		: undefined;
	useEffect(() => {
		if (mediaDraft && !activeMediaDraft) overlayClose();
	}, [mediaDraft, activeMediaDraft, overlayClose]);

	// Inject the shell's native content resolver into the cell host (Phase 3): the
	// host renders the consumer component when registered, else the kind→view map.
	// openEditor is threaded so the cell wrapper can activate the overlay editor;
	// submitDraftRow is threaded so the draft-action cell's Button can submit (Stage 4).
	const getSheetsCellContent = shell.getSheetsCellContent;
	const submitDraftRow = shell.submitDraftRow;
	const commitCellValue = shell.commitCellValue;
	const getEditorComponent = shell.cellRegistry.getEditorComponent;
	// Load the date editor's code in idle time once rows show, when a column opens it.
	useDateEditorPreload({
		table: shell.tableModel,
		typeOverrides: config.fieldTypeOverrides,
		hasRows: combinedRows.length > 0,
		getEditorComponent,
	});
	// Undo/redo handlers (stable from useUndoRedo) — wired into the edit.undo / edit.redo commands.
	const undo = shell.undo;
	const redo = shell.redo;
	// Batched commit + observational emit — threaded into the command context (commitCells/emit).
	const commitCells = shell.commitCells;
	const emit = shell.emit;

	// REF-LATCH (perf): `openEditor` is a dep of `renderCell`, which the cell host
	// memo-gates on (prev.openEditor === next.openEditor). Closing over `combinedRows` /
	// `commitCellValue` / the resolver directly would give `openEditor` a NEW identity on
	// every data/draft change, busting the per-cell memo for the ENTIRE visible window.
	// Instead we latch each churning value into a ref kept current every render and read
	// `*Ref.current` inside the callback, so `openEditor` stays referentially STABLE while
	// still seeing the latest values. (`overlayOpen` is already stable — useCallback([]) —
	// so it stays a direct, guaranteed-stable dep.)
	const getSheetsCellContentRef = useRef(getSheetsCellContent);
	getSheetsCellContentRef.current = getSheetsCellContent;
	const getEditorComponentRef = useRef(getEditorComponent);
	getEditorComponentRef.current = getEditorComponent;
	const combinedRowsRef = useRef(combinedRows);
	combinedRowsRef.current = combinedRows;
	const commitCellValueRef = useRef(commitCellValue);
	commitCellValueRef.current = commitCellValue;
	const commitCellsRef = useRef(commitCells);
	commitCellsRef.current = commitCells;
	// Read the LATEST selection inside the keydown handler so a queued move can't resurrect a
	// stale active cell right after a sort/filter clear (the optionsKey effect resets selection).
	const selectionRef = useRef(selection);
	selectionRef.current = selection;

	// EDIT-INTENT BRANCH (Stage 2): activation routes through the SINGLE edit-intent
	// resolver off the resolved `typeKey` — NOT the broken `cell.meta?.cellType ?? 'text'`
	// lookup that mis-routed every non-text cell to TextEditor. The cell-host fires this
	// on double-click / Enter / F2 (it already no-ops readonly cells); here we branch
	// BEFORE opening any overlay:
	//   • inline-toggle (booleans): commit `!currentBool` in place, no overlay.
	//   • overlay: open the portal (the editorNode block resolves intent.editor).
	//   • none (readonly / non-editable): do nothing.
	const openEditorImpl = useCallback<OpenEditor>(
		(rowIndex, colKey, anchorRect, initialText) => {
			const resolution = getSheetsCellContentRef.current(rowIndex, colKey);
			const intent = resolveEditIntent(
				resolution.typeKey,
				{ readonly: resolution.cell.readonly },
				getEditorComponentRef.current,
			);
			if (intent.mode === 'none') {
				// A cell that cannot be changed says why, instead of silently ignoring the attempt.
				if (resolution.readOnlyReason) reportReadOnlyCell(colKey, resolution.readOnlyReason);
				return;
			}
			if (intent.mode === 'inline-toggle') {
				const current = (combinedRowsRef.current[rowIndex] as Record<string, unknown> | undefined)?.[colKey];
				commitCellValueRef.current(rowIndex, colKey, nextToggleValue(current));
				return;
			}
			// inline-edit (simple text/number): edit IN PLACE — same active-cell controller (so nav/
			// clipboard suppression + scroll commit-on-unmount are shared) but the cell host renders
			// the input and the portal is skipped (editorNode is null for a non-overlay intent).
			if (intent.mode === 'inline-edit') {
				overlayOpen({ rowIndex, colKey, anchorRect, initialText, mode: 'inline' });
				return;
			}
			const row = combinedRowsRef.current[rowIndex];
			const draft = intent.editor === ImageEditorDom ? getDraftMeta(row) : undefined;
			overlayOpen({
				rowIndex,
				colKey,
				anchorRect,
				initialText,
				mode: 'overlay',
				mediaDraft: draft ? {
					rowId: draft.draftRowId,
					tableName,
					scopeKey,
					value: row[colKey],
					resolution,
				} : undefined,
			});
		},
		[overlayOpen, tableName, scopeKey],
	);
	// The dblclick entrypoint threaded into the cell host: route through the ONE pipeline as
	// `editor.open`; the command body calls ctx.openEditorAt → openEditorImpl. STABLE (closes
	// over the stable `dispatch`), so it never busts the per-cell memo.
	const openEditor = useCallback<OpenEditor>(
		(rowIndex, colKey, anchorRect, initialText) =>
			dispatch('editor.open', undefined, { rowIndex, colKey, anchorRect, initialText }),
		[dispatch],
	);
	// ============== RANGE-AWARE BULK EDIT (Stage B) ==============
	// The editor's onCommit routes through here. When a MULTI-CELL range is selected AND the
	// active (edited) cell sits inside it, the committed value FANS OUT across the whole range
	// as ONE undo-aware batch (single optimistic patch + coalesced per-row mutations + one undo
	// entry — commitCells skips readonly/UUID internally and resolveServerPatch coerces the
	// string value PER target column). A single-cell selection (or none, or an active cell
	// outside the range) keeps the existing single-cell commit byte-for-byte. The LATEST range
	// is read off `selectionRef` so a queued sort/filter clear wins (same latch the keymap uses).
	const columnKeysRef = useRef(shell.columnKeys);
	columnKeysRef.current = shell.columnKeys;
	const commitBulkOrSingle = useCallback(
		(rowIndex: number, colKey: string, value: unknown) => {
			const range = selectionRef.current?.current?.range;
			const keys = columnKeysRef.current;
			const activeCol = keys.indexOf(colKey);
			const multiCell = !!range && range.width * range.height > 1;
			const inside =
				!!range &&
				activeCol >= 0 &&
				activeCol >= range.x &&
				activeCol < range.x + range.width &&
				rowIndex >= range.y &&
				rowIndex < range.y + range.height;
			if (multiCell && inside && range) {
				const writes = bulkEditWrites(range, value, keys);
				if (writes.length) void commitCellsRef.current(writes);
				return;
			}
			commitCellValueRef.current(rowIndex, colKey, value);
		},
		[],
	);

	// ============== INLINE (IN-CELL) EDIT WIRING ==============
	// Simple text/number types edit in place via the cell host's <input> instead of the portal.
	// They ride the SAME active-editor controller (`overlay`) tagged `mode: 'inline'`, so the only
	// extra wiring here is (a) telling the editing cell to render the input and (b) commit/cancel
	// routed through the existing value-commit pipeline. `editingCell` is the editing cell, undefined
	// during overlay editing; the viewport hands it to that cell's row only, so opening an editor
	// renders one row and overlay scroll-reanchors (they move `anchorRect` only) render none.
	const inlineActive = overlay.active?.mode === 'inline' ? overlay.active : null;
	const inlineRow = inlineActive?.rowIndex;
	const inlineColumn = inlineActive?.colKey;
	const inlineText = inlineActive?.initialText;
	const editingCell = useMemo<GridEditingCell | undefined>(
		() =>
			inlineRow !== undefined && inlineColumn !== undefined
				? { rowIndex: inlineRow, columnId: inlineColumn, initialText: inlineText }
				: undefined,
		[inlineRow, inlineColumn, inlineText],
	);
	// After Enter or Tab the cursor moves on, as in a spreadsheet: down, up, or along the row.
	const onInlineCommit = useCallback(
		(rowIndex: number, colKey: string, value: unknown, move?: InlineEditMove) => {
			commitBulkOrSingle(rowIndex, colKey, value);
			overlayClose();
			if (move === 'down') dispatch('cell.moveDown');
			else if (move === 'up') dispatch('cell.moveUp');
			else if (move) dispatch('cell.navAbsolute', undefined, { key: 'Tab', ctrlOrMeta: false, shift: move === 'left', pageRows: 0 } satisfies NavAbsolutePayload);
		},
		[commitBulkOrSingle, overlayClose, dispatch],
	);

	// Shared open-at-active-cell path (Enter / F2 / type-to-edit): resolve the active cell's
	// DOM node by its stable id, null-guarding the row (infinite-mode proxy rows can be null at
	// unloaded indices) + the colKey, then open the overlay. `initialText` seeds type-to-edit
	// (OVERWRITE). Returns true when an overlay was opened.
	const openEditorAtActiveCell = useCallback(
		(initialText?: string): boolean => {
			const cell = selectionRef.current?.current?.cell;
			if (!cell) return false;
			const [col, row] = cell;
			const rowData = combinedRowsRef.current[row];
			if (!rowData) return false;
			const colKey = columns[col]?.key;
			if (!colKey) return false;
			const node = document.getElementById(`sheets-cell-${row}-${col}`);
			if (!node) return false;
			// Open directly via the impl (NOT the dispatching `openEditor`) — this fn is itself the
			// body of the editor.openActive / editor.typeToEdit commands' canRun, so going through
			// dispatch again would double-route. Matches the original (which called openEditor directly).
			openEditorImpl(row, colKey, node.getBoundingClientRect(), initialText);
			return true;
		},
		[columns, openEditorImpl],
	);

	// FOLLOW-CELL-ON-SCROLL (Stage B): on viewport scroll, re-measure the active cell's DOM
	// node and re-anchor the overlay to it (cheap, passive — DOM read + a position state set)
	// instead of closing. If the node is GONE (the cell scrolled out of the virtual window and
	// unmounted), we COMMIT-AND-CLOSE rather than silently discard: blur the focused editor
	// element so a commit-on-blur editor (text/number) commits its in-progress value, then
	// close. (Backgrounded-tab rAF throttling is irrelevant — this runs straight off scroll.)
	const activeRef = useRef(overlay.active);
	activeRef.current = overlay.active;
	const columnsRef = useRef(columns);
	columnsRef.current = columns;
	const handleOverlayScroll = useCallback(() => {
		const a = activeRef.current;
		if (!a) return;
		if (a.mediaDraft && getDraftMeta(combinedRowsRef.current[a.rowIndex])?.draftRowId !== a.mediaDraft.rowId) return;
		// The cell DOM id is `sheets-cell-${rowIndex}-${columnIndex}` — map the stored colKey
		// back to its rendered column index (same ordering the cell host + activedescendant use).
		const colIndex = columnsRef.current.findIndex((c) => c.key === a.colKey);
		const node = colIndex >= 0 ? document.getElementById(`sheets-cell-${a.rowIndex}-${colIndex}`) : null;
		if (node) {
			// Inline edits live INSIDE the cell, so they ride the virtualized row natively (their
			// portalled multiline field and notice measure the cell on scroll themselves). Only
			// the portal overlay re-anchors to the cell here.
			if (a.mode !== 'inline') overlayReanchor(node.getBoundingClientRect());
			return;
		}
		// Cell unmounted (scrolled out of the virtual window) — commit any in-progress value
		// (commit-on-blur editors, incl. the inline input) then close.
		const focused = document.activeElement;
		if (focused instanceof HTMLElement) focused.blur();
		overlayClose();
	}, [overlayReanchor, overlayClose]);

	return {
		overlay,
		overlayClose,
		mediaDraft,
		activeMediaDraft,
		getSheetsCellContent,
		getEditorComponent,
		submitDraftRow,
		undo,
		redo,
		commitCells,
		emit,
		getSheetsCellContentRef,
		combinedRowsRef,
		selectionRef,
		columnsRef,
		openEditorImpl,
		openEditor,
		commitBulkOrSingle,
		editingCell,
		onInlineCommit,
		openEditorAtActiveCell,
		handleOverlayScroll,
	};
}

// Keys and the clipboard on the grid root: every chord resolves to a named command through
// the one dispatch pipeline; native copy, cut and paste events do too.
import { useCallback, useRef, type MutableRefObject } from 'react';
import type React from 'react';

import type { Dispatch } from '../../commands/dispatch';
import { resolveKeyBindings, type Binding } from '../../commands/keymap';
import type { NavAbsolutePayload } from '../../commands/registry';

// Rows moved per PageUp/PageDown when the scroll element's clientHeight can't be read
// (jsdom / detached). A sensible spreadsheet page span.
const FALLBACK_PAGE_ROWS = 10;

/** The absolute-nav keys whose command (`cell.navAbsolute`) needs the payload below. */
const ABSOLUTE_NAV_KEYS = new Set(['Tab', 'Home', 'End', 'PageUp', 'PageDown']);

/**
 * Build the dispatch payload for a key event. Only `cell.navAbsolute` (Tab/Home/End/Page*)
 * needs one — the funnel's old inline branch derived the page span from the scroll element's
 * clientHeight (e.currentTarget IS the scroll root), falling back to a constant under jsdom.
 * Arrows / extends / undo / redo / select-all / open read everything from the command context,
 * so they get `undefined`.
 */
function buildKeyPayload(e: React.KeyboardEvent, rowHeight: number): NavAbsolutePayload | undefined {
	if (!ABSOLUTE_NAV_KEYS.has(e.key)) return undefined;
	const clientHeight = (e.currentTarget as HTMLElement).clientHeight;
	const pageRows = clientHeight > 0 ? Math.max(1, Math.floor(clientHeight / rowHeight)) : FALLBACK_PAGE_ROWS;
	return { key: e.key, ctrlOrMeta: e.ctrlKey || e.metaKey, shift: e.shiftKey, pageRows };
}

export interface UseGridKeyboardInput {
	isOverlayOpen: boolean;
	dispatch: Dispatch;
	keymapRef: MutableRefObject<Binding[]>;
	rowHeightPx: number;
}

export function useGridKeyboard({ isOverlayOpen, dispatch, keymapRef, rowHeightPx }: UseGridKeyboardInput) {
	// Every grid key now resolves to a NAMED command through the ONE dispatch pipeline. The
	// keymap (first-match-wins) covers undo/redo/select-all/arrows/extend/abs-nav/open; an
	// UNRESOLVED key that is a single printable char (no ctrl/meta/alt) falls to the
	// `editor.typeToEdit` sentinel (also through dispatch, so it is interceptable). Any other
	// unresolved key is left untouched — NO dispatch, NO preventDefault — so it reaches the
	// browser. preventDefault lives in the dispatch CORE, gated on a resolved+runnable command.
	// Page span (PageUp / PageDown) follows the view's row height.
	const rowHeightRef = useRef(rowHeightPx);
	rowHeightRef.current = rowHeightPx;
	const handleGridKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Don't intercept while editing — the overlay editor owns its own keys.
			if (isOverlayOpen) return;
			// Every binding of the chord, in keymap order, until one runs (Escape: close the record
			// panel, else clear the selection).
			const bindings = resolveKeyBindings(e.nativeEvent, keymapRef.current);
			if (bindings.length > 0) {
				const payload = buildKeyPayload(e, rowHeightRef.current);
				let ran = false;
				let prevented = false;
				for (const binding of bindings) {
					const result = dispatch(binding.command, e.nativeEvent, payload);
					prevented ||= result.prevented;
					if (result.ran) {
						ran = true;
						break;
					}
				}
				// A claimed chord (Mod+R) never reaches the browser, even when its command did not run.
				if (!prevented && bindings.some((binding) => binding.claim)) e.preventDefault();
				// A printable chord whose command did not run (Shift+Space with no record panel) still types.
				if (ran || e.key.length !== 1 || e.ctrlKey || e.metaKey || e.altKey) return;
			}
			// Unresolved: only the printable-key sentinel routes through dispatch; everything
			// else falls through to the browser with no preventDefault.
			if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
				dispatch('editor.typeToEdit', e.nativeEvent, { char: e.key });
			}
		},
		[isOverlayOpen, dispatch],
	);

	// ============== NATIVE CLIPBOARD (Stage B) ==============
	// The grid root (role=grid, tabIndex=0) receives the browser's native copy/cut/paste events
	// when focused. We do NOT bind Ctrl/Cmd+C/X/V in the keymap — pressing them fires these native
	// events directly, so binding the keys too would double-handle. Each handler is SKIPPED while an
	// overlay editor is open (the editor owns its own clipboard) and routes through the ONE dispatch
	// pipeline as `clipboard.copy`/`cut`/`paste`, threading the native ClipboardData as the payload.
	// preventDefault happens in the dispatch core (so the browser does not also copy/paste).
	const handleCopy = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.copy', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);
	const handleCut = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.cut', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);
	const handlePaste = useCallback(
		(e: React.ClipboardEvent) => {
			if (isOverlayOpen) return;
			dispatch('clipboard.paste', e.nativeEvent, { clipboard: (e.nativeEvent as ClipboardEvent).clipboardData });
		},
		[isOverlayOpen, dispatch],
	);

	return { handleGridKeyDown, handleCopy, handleCut, handlePaste };
}

// The v9 table instance the DOM grid renders, mirrored from the shell: column
// descriptors, sizing and pinning. Rows are not in it: the viewport draws them by
// index from `combinedRows`, and the selection stays the shell's SheetsSelection.
import { useCallback, useMemo, useRef } from 'react';
import { functionalUpdate, type ColumnPinningState, type ColumnSizingState, type OnChangeFn } from '@tanstack/react-table';

import { useSheetsTableInstance, type SheetsColumnDescriptor } from '../../table/use-sheets-table-instance';
import { narrowColumnNames } from '../columns/column-layout';
import type { SheetsRow } from '../row-model';
import { DRAFT_ACTION_COLUMN_KEY } from '../sheets.constants';
import type { UseSheetsInternalResult } from '../use-sheets';

// Column sizing + pinning (Stage 2) are wired to the shell. Pinning is shell-DERIVED
// (frozenCount), never edited from the grid, so its onChange is a no-op.
const noop = () => {};

export function useGridTableState<TRow extends SheetsRow = SheetsRow>(s: UseSheetsInternalResult<TRow>) {
	const shell = s._shell;

	const columns = useMemo<SheetsColumnDescriptor[]>(
		() => s.columns.map((col) => ({ key: col.id, name: col.title, size: col.width })),
		[s.columns],
	);

	// ============== COLUMN SIZING + PINNING STATE MIRROR (Stage 2) ==============
	// Sizing: project the shell's columnWidths Map → v9 ColumnSizingState; a width committed
	// by the header drag-resize handle goes STRAIGHT to resizeColumn (the same setter the canvas
	// onColumnResize uses), so the Map stays the single source of truth and the table just mirrors.
	// Pinning: pin col0 ('id') exactly when the canvas freezes it (frozenCount), else nothing —
	// GridViewport's findStickyColumnIndex falls back to col0 anyway, so the sticky column is identical.
	const columnWidths = shell.columnWidths;
	const resizeColumn = shell.resizeColumn;
	const frozenCount = shell.frozenCount;
	const firstColumnKey = shell.columnKeys[0];

	const columnSizing = useMemo<Record<string, number>>(() => {
		const sizing: Record<string, number> = {};
		columnWidths.forEach((width, key) => {
			sizing[key] = width;
		});
		return sizing;
	}, [columnWidths]);

	// Columns that keep their width when the grid is wider than its columns: the ones the user
	// resized, and the draft-row action column. The viewport shares the spare width among the rest.
	const userWidths = shell.view.layout.layout.widths;
	const fixedWidthColumns = useMemo(
		() => new Set([...Object.keys(userWidths), ...columnWidths.keys(), DRAFT_ACTION_COLUMN_KEY]),
		[userWidths, columnWidths],
	);
	// Checkbox and number columns take spare width only when no other column can.
	const narrowColumns = useMemo(() => narrowColumnNames(shell.tableModel), [shell.tableModel]);

	const columnPinning = useMemo<ColumnPinningState>(
		() => ({ start: frozenCount > 0 && firstColumnKey ? [firstColumnKey] : [], end: [] }),
		[frozenCount, firstColumnKey],
	);

	const onColumnSizingChange = useCallback<OnChangeFn<ColumnSizingState>>(
		(updater) => {
			const next = functionalUpdate(updater, columnSizing);
			for (const key of Object.keys(next)) {
				if (next[key] !== columnSizing[key]) resizeColumn(key, next[key]);
			}
		},
		[columnSizing, resizeColumn],
	);

	// The rows the viewport draws by index, and their metadata-defined key (renamed/composite PKs).
	const combinedRows = shell.combinedRows;
	const getRowId = shell.getRowId;
	const selection = s.selection.gridSelection;
	const setSelection = s.selection.setGridSelection;
	// Active (keyboard cursor) cell `[col, row]`, threaded to the viewport for the focus ring +
	// aria-activedescendant. Derived in render (a plain read, no setState) per the no-setState-in-render rule.
	const activeCell = selection?.current?.cell;
	// The last active cell, where the cursor comes back after a clear (Escape, a press outside).
	const lastActiveCellRef = useRef<[number, number] | undefined>(undefined);
	if (activeCell) lastActiveCellRef.current = activeCell;

	const table = useSheetsTableInstance({
		columns,
		columnSizing,
		columnPinning,
		onColumnSizingChange,
		// Pinning is shell-derived (frozenCount), never edited from the grid → no writer needed.
		onColumnPinningChange: noop,
	});

	return {
		columns,
		table,
		resizeColumn,
		fixedWidthColumns,
		narrowColumns,
		combinedRows,
		getRowId,
		selection,
		setSelection,
		activeCell,
		lastActiveCellRef,
	};
}

// The leading checkbox / select-all column: its toggles write the canonical selection,
// and each row's open button opens the record panel, all through the command pipeline.
import { useCallback, useMemo, useRef } from 'react';

import type { TableModel } from '@constructive-io/data';

import type { Dispatch } from '../../commands/dispatch';
import { RangeSet } from '../../selection/range-set';
import { clear, emptySheetsSelection, selectRange, toggleRow, type SheetsSelection } from '../../selection/selection-model';
import type { RowMarker } from '../../table/grid-viewport';
import type { SheetsRow } from '../row-model';

export interface UseRowMarkerInput {
	combinedRows: SheetsRow[];
	selection: SheetsSelection | undefined;
	setSelection: (selection: SheetsSelection | undefined) => void;
	tableModel: TableModel | null;
	dispatch: Dispatch;
}

export function useRowMarker({ combinedRows, selection, setSelection, tableModel, dispatch }: UseRowMarkerInput) {
	// ============== LEADING CHECKBOX / SELECT-ALL COLUMN (drives the canonical RangeSet) ==============
	// The DOM grid has no canvas rowMarkers, so the GridViewport paints a sticky checkbox column whose
	// toggles write the canonical SheetsSelection directly (the rowSelection mirror above derives FROM
	// it). selectRange/toggleRow/clear are the same pure helpers the canvas projection round-trips, so
	// shift-range and ctrl-toggle behave identically. `shiftAnchorRef` records the last-toggled index so
	// a subsequent shift-click selects the contiguous block — caller-owned, matching selectRange's contract.
	const rowCount = combinedRows.length;
	const shiftAnchorRef = useRef<number | null>(null);
	// Latch selection + rowCount so the STABLE toggle impls (ctx methods) read the latest values
	// without re-creating, while rowMarker's handlers dispatch the named commands through `dispatch`.
	const rowMarkerSelectionRef = useRef(selection);
	rowMarkerSelectionRef.current = selection;
	const rowCountRef = useRef(rowCount);
	rowCountRef.current = rowCount;
	// Verbatim toggle bodies, lifted from the previous inline rowMarker handlers — the rowMarker
	// dispatches `rowmarker.toggleRow` / `rowmarker.toggleAll`, whose commands call these.
	const toggleRowImpl = useCallback((index: number, shiftKey: boolean) => {
		const sel = rowMarkerSelectionRef.current ?? emptySheetsSelection;
		const anchor = shiftAnchorRef.current;
		const next = shiftKey && anchor !== null ? selectRange(sel, anchor, index) : toggleRow(sel, index);
		shiftAnchorRef.current = index;
		setSelection(next);
	}, [setSelection]);
	const toggleAllImpl = useCallback(() => {
		const sel = rowMarkerSelectionRef.current ?? emptySheetsSelection;
		const rc = rowCountRef.current;
		const allSelected = rc > 0 && sel.rows.length === rc;
		shiftAnchorRef.current = null;
		setSelection(
			allSelected || rc === 0
				? clear(sel)
				: { current: { cell: [0, 0] }, rows: RangeSet.fromSingleSelection([0, rc]), columns: RangeSet.empty() },
		);
	}, [setSelection]);
	// Records open one by one only on a table with a primary key (the record panel needs it).
	const canOpenRecords = (tableModel?.primaryKey.length ?? 0) > 0;
	// Built from the selected ROWS only: a cursor move keeps them (the selection model copies the
	// same RangeSet), so the marker, and every grid row it is handed to, stays as it was.
	const selectedRows = (selection ?? emptySheetsSelection).rows;
	const rowMarker = useMemo<RowMarker>(() => {
		const selectedCount = selectedRows.length;
		const allSelected = rowCount > 0 && selectedCount === rowCount;
		return {
			isSelected: (index) => selectedRows.hasIndex(index),
			// The row's open button runs `record.open` through the same pipeline as the key and the menu.
			onExpandRow: canOpenRecords ? (index) => dispatch('record.open', undefined, { rowIndex: index }) : undefined,
			// Toggle handlers route through the ONE dispatch pipeline (rowmarker.toggleRow /
			// rowmarker.toggleAll); the command bodies call toggleRowImpl / toggleAllImpl (the
			// verbatim selectRange/toggleRow/clear logic lifted above).
			onToggleRow: (index, shiftKey) => dispatch('rowmarker.toggleRow', undefined, { rowIndex: index, shift: shiftKey }),
			allSelected,
			someSelected: selectedCount > 0 && !allSelected,
			onToggleAll: () => dispatch('rowmarker.toggleAll'),
		};
	}, [selectedRows, rowCount, dispatch, canOpenRecords]);

	return { rowMarker, toggleRowImpl, toggleAllImpl, canOpenRecords };
}

// Typed row + draft-metadata model for the sheets grid.
//
// Draft metadata is attached to a row under a non-enumerable Symbol key so it
// never collides with real column data and stays invisible to JSON.stringify
// and key enumeration. NOTE: exactly like the previous non-enumerable string
// markers (`__isDraft` etc.), this metadata does NOT survive an object spread
// (`{ ...row }`) — callers must thread the row reference through rather than a
// shallow copy.
import type { DraftRow } from '../store/draft-rows-slice';

/** A grid row: arbitrary column values keyed by field name, plus an optional id. */
export type SheetsRow = Record<string, unknown> & { id?: string | number };

/** Client-side draft metadata carried by a not-yet-persisted row. */
export interface DraftMeta {
	readonly isDraft: true;
	readonly draftRowId: string;
	readonly status: DraftRow['status'];
	readonly errors: Record<string, string> | null;
}

const DRAFT_META: unique symbol = Symbol('sheets.draftMeta');

/** A row that may carry draft metadata under the (non-enumerable) Symbol key. */
export type RowWithDraft<TRow extends SheetsRow = SheetsRow> = TRow & { readonly [DRAFT_META]?: DraftMeta };

/** Attach draft metadata to a row in place (non-enumerable). Returns the same row, typed. */
export function attachDraftMeta<TRow extends SheetsRow>(row: TRow, meta: DraftMeta): RowWithDraft<TRow> {
	Object.defineProperty(row, DRAFT_META, { value: meta, enumerable: false, configurable: true });
	return row as RowWithDraft<TRow>;
}

/** Read draft metadata, or undefined for a normal (server) row. */
export function getDraftMeta(row: SheetsRow | null | undefined): DraftMeta | undefined {
	return row ? (row as RowWithDraft)[DRAFT_META] : undefined;
}

/** True when the row is a client-side draft. */
export function isDraftRow(row: SheetsRow | null | undefined): boolean {
	return getDraftMeta(row)?.isDraft === true;
}

// What removing rows does. A saved row is deleted for good; a new row that was never saved is
// only discarded, which the table's delete permission does not govern. One plan drives the
// toolbar's Delete, the context menu's item and the words of the confirm, so they agree.
import type { SheetsSelection } from '../selection/selection-model';
import { getDraftMeta, type SheetsRow } from './row-model';

export interface RowRemoval {
	/** The row indexes to remove. */
	rows: readonly number[];
	/** Saved rows among them: deleted on the server. */
	saved: number;
	/** New rows among them: discarded. */
	unsaved: number;
	/** Why these rows cannot be removed, or null. */
	blockedReason: string | null;
}

export interface RowRemovalAccess {
	/** The table lets saved rows be deleted. */
	canDeleteSaved: boolean;
	/** Why the table's records cannot be changed, when it says. */
	readOnlyReason?: string | null;
}

/**
 * The rows an action on "the row" means: the selected rows, else the rows under the cursor's
 * range or cell. A range is cut to the `rowCount` rows there are (Select all spans every row).
 */
export function rowsUnderSelection(selection: SheetsSelection | null | undefined, rowCount: number): number[] {
	if (!selection) return [];
	const selected = selection.rows.toArray();
	if (selected.length > 0) return selected;
	const range = selection.current?.range;
	if (range && range.height > 0) {
		const end = Math.min(range.y + range.height, rowCount);
		return Array.from({ length: Math.max(0, end - range.y) }, (_, offset) => range.y + offset);
	}
	const cell = selection.current?.cell;
	return cell ? [cell[1]] : [];
}

export function planRowRemoval(rows: readonly number[], data: readonly unknown[], access: RowRemovalAccess): RowRemoval {
	const present = rows.filter((row) => row >= 0 && row < data.length);
	const unsaved = present.filter((row) => getDraftMeta(data[row] as SheetsRow)?.isDraft).length;
	const saved = present.length - unsaved;
	const blockedReason =
		present.length === 0
			? 'Select the rows to delete.'
			: saved > 0 && !access.canDeleteSaved
				? access.readOnlyReason ?? 'Saved rows in this table cannot be deleted.'
				: null;
	return { rows: present, saved, unsaved, blockedReason };
}

const count = (n: number, noun: string) => `${n.toLocaleString()} ${noun}${n === 1 ? '' : 's'}`;

/** The action's name: "Delete row", "Delete 3 rows", "Discard new row". */
export function rowRemovalLabel(plan: RowRemoval): string {
	const total = plan.rows.length;
	if (plan.saved === 0 && plan.unsaved > 0) return plan.unsaved === 1 ? 'Discard new row' : `Discard ${count(plan.unsaved, 'new row')}`;
	return total > 1 ? `Delete ${count(total, 'row')}` : 'Delete row';
}

/** The confirm's words: a saved row is gone for good, a new row only loses what was typed. */
export function rowRemovalConfirm(plan: RowRemoval): { title: string; description: string; action: string } {
	const { saved, unsaved } = plan;
	if (saved === 0) {
		return {
			title: unsaved === 1 ? 'Discard new row?' : `Discard ${count(unsaved, 'new row')}?`,
			description: unsaved === 1 ? 'This row is not saved yet. What you typed in it will be lost.' : 'These rows are not saved yet. What you typed in them will be lost.',
			action: 'Discard',
		};
	}
	const deleted = `This will permanently delete ${count(saved, 'row')}`;
	return {
		title: `Delete ${count(saved + unsaved, 'row')}?`,
		description: unsaved > 0 ? `${deleted} and discard ${count(unsaved, 'new row')} that ${unsaved === 1 ? 'is' : 'are'} not saved yet. This cannot be undone.` : `${deleted}. This cannot be undone.`,
		action: 'Delete',
	};
}

/**
 * The toolbar search box. It searches what the table model allows (see
 * `searchPlanOf`) and says which columns that covers. Typing commits after a
 * pause; Escape clears the search.
 */
import { useId } from 'react';
import { RiCloseLine, RiSearch2Line } from '@remixicon/react';

import { Input } from '@/components/ui/input';

import { useCommittedText } from '../filters/use-committed-text';
import { searchedColumns, type SearchPlan } from '../view-state/search-plan';

export interface SearchBoxProps {
	plan: SearchPlan | null;
	value: string;
	onChange: (value: string) => void;
	columnLabel: (name: string) => string;
	inputRef: React.MutableRefObject<HTMLInputElement | null>;
	/** Whether the table model has loaded; before that the box waits. */
	ready: boolean;
}

/** The sentence that says what a search covers. */
export function searchScopeText(plan: SearchPlan, columnLabel: (name: string) => string): string {
	const names = searchedColumns(plan).map(columnLabel);
	if (plan.mode === 'unified') {
		return names.length > 0 ? `Searches the table's search fields: ${names.join(', ')}` : "Searches the table's search fields";
	}
	return `Searches ${names.join(', ')}`;
}

export function SearchBox({ plan, value, onChange, columnLabel, inputRef, ready }: SearchBoxProps) {
	const { text, change, flush, commitNow } = useCommittedText(value, onChange);
	const scopeId = useId();
	const disabledReason = !ready ? 'Search is available once the table has loaded.' : plan ? null : 'This table cannot be searched.';
	const scope = plan ? searchScopeText(plan, columnLabel) : disabledReason ?? '';
	const names = plan ? searchedColumns(plan).map(columnLabel) : [];
	const placeholder = names.length > 0 && names.length <= 3 ? `Search ${names.join(', ')}` : 'Search';

	return (
		<div data-part-id='sheets-search' className='relative flex items-center' title={scope}>
			{/* Above the input: the input's own background would otherwise cover it. */}
			<RiSearch2Line className='text-muted-foreground/70 pointer-events-none absolute left-2 z-10 size-4' aria-hidden='true' />
			<Input
				ref={inputRef}
				type='search'
				aria-label='Search rows'
				aria-describedby={scopeId}
				className='w-52 ps-6 pe-6 @max-[52rem]/sheets-toolbar:w-40'
				placeholder={placeholder}
				disabled={Boolean(disabledReason)}
				value={text}
				onChange={(event) => change(event.target.value)}
				onBlur={flush}
				onKeyDown={(event) => {
					if (event.key === 'Enter') flush();
					if (event.key === 'Escape' && text !== '') {
						event.preventDefault();
						event.stopPropagation();
						commitNow('');
					}
				}}
			/>
			<span id={scopeId} className='sr-only'>
				{scope}
			</span>
			{text !== '' && (
				<button
					type='button'
					className='text-muted-foreground hover:text-foreground absolute right-1.5 z-10 rounded p-0.5'
					aria-label='Clear search'
					onClick={() => {
						commitNow('');
						inputRef.current?.focus();
					}}
				>
					<RiCloseLine className='size-4' aria-hidden='true' />
				</button>
			)}
		</div>
	);
}

/**
 * The right-click CONTEXT MENU (Stage B) — the showcase of the command layer: a menu is just
 * another EVENT SOURCE that resolves to named commands and runs through the SAME `dispatch`
 * pipeline as keys / clicks. Rendered ONCE at the grid level (never per-cell, so the per-cell
 * memo is untouched); the cell host calls `open(col, row, clientX, clientY)` on `onContextMenu`.
 *
 * Anchoring: Base UI's Menu anchors to its Trigger. We render a 0×0 FIXED trigger at the pointer
 * coordinates and toggle the controlled `open`, so the popup floats at the right-clicked cell.
 *
 * The ITEM MODEL is a pure builder (`buildContextMenuItems`) so the action→command mapping +
 * disabled gating is unit-testable WITHOUT the Base-UI popup (which needs a real layout env). The
 * component maps the model to <DropdownMenuItem>s. "Delete row(s)" is the one destructive action —
 * its `run` requests the SAME AlertDialog confirm the toolbar Delete uses.
 */
import { useState, type ReactNode } from 'react';
import {
	RiAddLine,
	RiClipboardLine,
	RiExpandDiagonalLine,
	RiDeleteBin6Line,
	RiEraserLine,
	RiExternalLinkLine,
	RiFileCopyLine,
	RiScissorsLine,
	RiSortAsc,
	RiSortDesc,
} from '@remixicon/react';

import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuShortcut,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

import { INSTANT_POPUP } from './popup-classes';
import { rowRemovalConfirm, rowRemovalLabel, type RowRemoval } from './row-removal';

/** Where the menu is anchored + the cell it acts on. `null` = closed. */
export interface ContextMenuState {
	clientX: number;
	clientY: number;
}

/** One row of the menu (or a separator). `run` fires on click; `disabled` greys it out. */
export interface ContextMenuItem {
	key: string;
	separator?: boolean;
	label?: string;
	icon?: ReactNode;
	shortcut?: string;
	destructive?: boolean;
	disabled?: boolean;
	/** Why the item is disabled, shown on hover. */
	reason?: string;
	run?: () => void;
}

export interface BuildContextMenuItemsArgs {
	/** Dispatch a command id through the grid's stable dispatch pipeline. */
	onAction: (commandId: string) => void;
	/** True when the command's `canRun` passes against the latched context. */
	isEnabled: (commandId: string) => boolean;
	/** Why a command cannot run here, or null; shown on its disabled item. */
	reasonFor?: (commandId: string) => string | null;
	/** Append a draft row (the toolbar Add-row path). */
	onAddRow: () => void;
	/** Open the destructive delete confirm (the AlertDialog). */
	requestDelete: () => void;
	/** What removing the rows under the menu does: gates Delete and names it. */
	removal: RowRemoval;
	canAddRows?: boolean;
	/** Offer "Open record" (the grid has a record panel). */
	canOpenRecords?: boolean;
}

/**
 * Pure menu model — the single source of truth for the items, their command mapping, and their
 * disabled state. Tested directly (no DOM). Clipboard / clear items dispatch their command id via
 * `onAction` and are disabled when `isEnabled(id)` is false; Add row / Delete use dedicated paths.
 */
export function buildContextMenuItems({
	onAction,
	isEnabled,
	reasonFor,
	onAddRow,
	requestDelete,
	removal,
	canAddRows = true,
	canOpenRecords = false,
}: BuildContextMenuItemsArgs): ContextMenuItem[] {
	const cmd = (key: string, commandId: string, label: string, icon: ReactNode, shortcut?: string): ContextMenuItem => {
		const disabled = !isEnabled(commandId);
		const reason = disabled ? reasonFor?.(commandId) ?? undefined : undefined;
		return { key, label, icon, shortcut, disabled, ...(reason ? { reason } : {}), run: () => onAction(commandId) };
	};
	// "Open link" shows only for a cell that holds an email or a web address.
	const open: ContextMenuItem[] = [
		...(isEnabled('cell.openLink') ? [cmd('open-link', 'cell.openLink', 'Open link', <RiExternalLinkLine className='size-4' aria-hidden='true' />)] : []),
		...(canOpenRecords ? [cmd('open-record', 'record.open', 'Open record', <RiExpandDiagonalLine className='size-4' aria-hidden='true' />)] : []),
	];
	return [
		...(open.length > 0 ? [...open, { key: 'sep-open', separator: true }] : []),
		cmd('copy', 'clipboard.copy', 'Copy', <RiFileCopyLine className='size-4' aria-hidden='true' />, '⌘C'),
		cmd('cut', 'clipboard.cut', 'Cut', <RiScissorsLine className='size-4' aria-hidden='true' />, '⌘X'),
		cmd('paste', 'clipboard.paste', 'Paste', <RiClipboardLine className='size-4' aria-hidden='true' />, '⌘V'),
		cmd('clear', 'cell.clear', 'Clear', <RiEraserLine className='size-4' aria-hidden='true' />),
		{ key: 'sep-view', separator: true },
		cmd('sort-asc', 'view.sortAscending', 'Sort ascending', <RiSortAsc className='size-4' aria-hidden='true' />),
		cmd('sort-desc', 'view.sortDescending', 'Sort descending', <RiSortDesc className='size-4' aria-hidden='true' />),
		{ key: 'sep', separator: true },
		{
			key: 'add-row',
			label: 'Add row',
			icon: <RiAddLine className='size-4' aria-hidden='true' />,
			disabled: !canAddRows,
			run: onAddRow,
		},
		{
			key: 'delete-rows',
			label: rowRemovalLabel(removal),
			icon: <RiDeleteBin6Line className='size-4' aria-hidden='true' />,
			destructive: true,
			disabled: removal.blockedReason !== null,
			...(removal.blockedReason ? { reason: removal.blockedReason } : {}),
			run: requestDelete,
		},
	];
}

export interface SheetsContextMenuProps {
	/** Open anchor + position; `null` keeps the menu closed. */
	state: ContextMenuState | null;
	/** Close the menu (clears `state`). */
	onClose: () => void;
	/** Dispatch a command id through the grid's stable dispatch pipeline. */
	onAction: (commandId: string) => void;
	/** True when the command's `canRun` passes against the latched context. */
	isEnabled: (commandId: string) => boolean;
	/** Why a command cannot run here, or null; shown on its disabled item. */
	reasonFor?: (commandId: string) => string | null;
	/** Append a draft row (the toolbar Add-row path). */
	onAddRow: () => void;
	/** Remove these rows (a saved row is deleted, a new row discarded) — guarded by the AlertDialog. */
	onDeleteRows: (rows: readonly number[]) => void;
	/** What removing the rows under the menu does (the selected rows, else the cursor's). */
	removal: RowRemoval;
	canAddRows?: boolean;
	/** Offer "Open record" (the grid has a record panel). */
	canOpenRecords?: boolean;
}

export function SheetsContextMenu({
	state,
	onClose,
	onAction,
	isEnabled,
	reasonFor,
	onAddRow,
	onDeleteRows,
	removal,
	canAddRows = true,
	canOpenRecords = false,
}: SheetsContextMenuProps) {
	// The confirm keeps the rows it was opened for: the menu closes, and the cursor may move, first.
	// The plan outlives `confirmOpen` so the words stay put while the dialog animates out.
	const [confirmOpen, setConfirmOpen] = useState(false);
	const [confirming, setConfirming] = useState<RowRemoval | null>(null);
	const confirm = confirming ? rowRemovalConfirm(confirming) : null;
	const open = state !== null;

	const items = buildContextMenuItems({
		onAction,
		isEnabled,
		reasonFor,
		onAddRow,
		requestDelete: () => {
			setConfirming(removal);
			setConfirmOpen(true);
		},
		removal,
		canAddRows,
		canOpenRecords,
	});

	return (
		<>
			<DropdownMenu open={open} onOpenChange={(next) => !next && onClose()}>
				{/* 0×0 fixed anchor at the pointer — the menu floats from here. */}
				<DropdownMenuTrigger
					aria-hidden
					tabIndex={-1}
					style={{
						position: 'fixed',
						left: state?.clientX ?? 0,
						top: state?.clientY ?? 0,
						width: 0,
						height: 0,
					}}
				/>
				<DropdownMenuContent align='start' className={INSTANT_POPUP}>
					{items.map((item) =>
						item.separator ? (
							<DropdownMenuSeparator key={item.key} />
						) : (
							<DropdownMenuItem
								key={item.key}
								variant={item.destructive ? 'destructive' : 'default'}
								disabled={item.disabled}
								title={item.reason}
								onClick={() => {
									// Run then close — a menu pick is a one-shot (the popup dismisses).
									item.run?.();
									onClose();
								}}
							>
								{item.icon}
								{item.label}
								{item.shortcut && <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>}
							</DropdownMenuItem>
						),
					)}
				</DropdownMenuContent>
			</DropdownMenu>

			{/* Destructive confirm — mirrors the toolbar Delete AlertDialog. Driven open after the
			    menu closes so the two overlays never fight for focus. */}
			<AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>{confirm?.title}</AlertDialogTitle>
						<AlertDialogDescription>{confirm?.description}</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel>Cancel</AlertDialogCancel>
						<AlertDialogAction
							className='bg-destructive text-white hover:bg-destructive/90'
							onClick={() => {
								if (confirming) onDeleteRows(confirming.rows);
								setConfirmOpen(false);
							}}
						>
							{confirm?.action}
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</>
	);
}

/**
 * The grid toolbar, in two groups:
 *   - the view, on the left: the saved view, Fields, Filters and Sort (quiet until they
 *     change the view, then tinted with how much they change), and search;
 *   - the actions, on the right: the data tools (import, export of the view) and New
 *     record, or, while rows are selected, what acts on them; then Add row, the one
 *     filled button, which never moves.
 * Labels fold into their icons on a narrow toolbar, so both groups keep one line; every
 * action stays one click away.
 * Everything about filters, sort and search comes from the view bindings (see
 * `useSheetsView`), which only offer what the table model has.
 *
 * Each group is memoized on what it shows: a cursor move (a new selection object, new
 * shell handlers) renders neither.
 */
import { memo, useLayoutEffect, useMemo, useRef } from 'react';
import {
	RiAddLine,
	RiArrowUpDownLine,
	RiCloseLine,
	RiDeleteBin6Line,
	RiDownloadLine,
	RiFileAddLine,
	RiFilter3Line,
	RiLockLine,
} from '@remixicon/react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
	AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Separator } from '@/components/ui/separator';

import type { SheetsSelection } from '../selection/selection-model';
import { cn } from '../utils/cn';
import { FieldsControl } from './columns/fields-control';
import { FilterBuilder } from './filters/filter-builder';
import { TOOLBAR_POPOVER } from './popup-classes';
import { SearchBox } from './search/search-box';
import { SortControl } from './sort/sort-control';
import { ToolbarLabel, ViewToggleButton } from './toolbar/toolbar-button';
import { filterConditionsOf } from './view-state/view-state';
import type { SheetsViewBindings } from './view-state/use-sheets-view';
import type { SavedViewsBindings } from './views/use-saved-views';
import { ViewSwitcher } from './views/view-switcher';
import { rowRemovalConfirm, type RowRemoval } from './row-removal';

export interface SheetsControlsProps {
	/** Filter, sort and search bindings. */
	view: SheetsViewBindings;
	/** Grid columns, in display order. */
	columnKeys: readonly string[];
	showSelection: boolean;
	gridSelection: SheetsSelection | null;
	setGridSelection: (selection: SheetsSelection | null) => void;
	deleteSelected: () => void;
	onAddRow?: () => void;
	/** Download the selected rows as CSV; offered only while rows are selected. */
	onExport?: () => void;
	canDelete?: boolean;
	/** What deleting the selected rows does (saved rows deleted, new rows discarded); refines `canDelete`. */
	selectionRemoval?: RowRemoval;
	readOnlyReason?: string | null;
	/** Saved views of the table. Omit to hide the view switcher. */
	savedViews?: SavedViewsBindings;
	/** More toolbar actions (import, export of the whole view), placed before New record. */
	tools?: React.ReactNode;
	/** Open the record panel's new-record form; `disabledReason` says why it cannot open. Omit to hide. */
	newRecord?: { open: () => void; disabledReason: string | null };
}

const DIVIDER = 'mx-1.5 data-[orientation=vertical]:h-4';

export function SheetsControls(props: SheetsControlsProps) {
	const {
		view,
		columnKeys,
		showSelection,
		gridSelection,
		setGridSelection,
		deleteSelected,
		onAddRow,
		onExport,
		canDelete = true,
		selectionRemoval,
		readOnlyReason = null,
		savedViews,
		tools,
		newRecord,
	} = props;
	const selectedRowCount = gridSelection?.rows.length ?? 0;

	// The shell rebuilds these handlers on every selection change, a cursor move included. Read
	// through a latch, the memoized action group keeps its props until what it shows changes.
	const latest = useRef({ setGridSelection, deleteSelected, onAddRow, onExport, openNewRecord: newRecord?.open });
	useLayoutEffect(() => {
		latest.current = { setGridSelection, deleteSelected, onAddRow, onExport, openNewRecord: newRecord?.open };
	});
	const hasAddRow = Boolean(onAddRow);
	const hasExport = Boolean(onExport);
	const hasNewRecord = Boolean(newRecord);
	const handlers = useMemo(
		() => ({
			clearSelection: () => latest.current.setGridSelection(null),
			deleteSelected: () => latest.current.deleteSelected(),
			addRow: hasAddRow ? () => latest.current.onAddRow?.() : undefined,
			exportSelected: hasExport ? () => latest.current.onExport?.() : undefined,
			openNewRecord: hasNewRecord ? () => latest.current.openNewRecord?.() : undefined,
		}),
		[hasAddRow, hasExport, hasNewRecord],
	);

	return (
		<div
			data-part-id='sheets-controls'
			className='@container/sheets-toolbar flex shrink-0 flex-wrap items-center justify-between gap-x-4 gap-y-2 py-4'
		>
			<ViewGroup view={view} columnKeys={columnKeys} savedViews={savedViews} readOnlyReason={readOnlyReason} canAdd={hasAddRow} />
			<ActionGroup
				selectedRowCount={selectedRowCount}
				showDelete={showSelection}
				canDelete={canDelete}
				removal={selectionRemoval ?? null}
				readOnlyReason={readOnlyReason}
				newRecordDisabledReason={newRecord?.disabledReason ?? null}
				tools={tools}
				{...handlers}
			/>
		</div>
	);
}

interface ViewGroupProps {
	view: SheetsViewBindings;
	columnKeys: readonly string[];
	savedViews: SavedViewsBindings | undefined;
	readOnlyReason: string | null;
	/** Add row is offered, so the badge says what still works. */
	canAdd: boolean;
}

/** What the grid shows: the saved view, Fields, Filters, Sort and search. */
const ViewGroup = memo(function ViewGroup({ view, columnKeys, savedViews, readOnlyReason, canAdd }: ViewGroupProps) {
	const conditionCount = useMemo(() => filterConditionsOf(view.state.filters).length, [view.state.filters]);
	const waiting = conditionCount - view.appliedCount;
	const sortCount = view.state.sort.length;

	return (
		<div role='group' aria-label='View' className='flex min-w-0 flex-wrap items-center gap-1'>
			{savedViews && <ViewSwitcher views={savedViews} />}
			{readOnlyReason && <AccessBadge reason={readOnlyReason} canAdd={canAdd} />}
			{savedViews && <Separator orientation='vertical' className={DIVIDER} />}

			<FieldsControl layout={view.layout} columnLabel={view.columnLabel} ready={view.model !== null} />

			<Popover open={view.filtersOpen} onOpenChange={view.setFiltersOpen}>
				<PopoverTrigger asChild>
					<ViewToggleButton
						icon={RiFilter3Line}
						label='Filters'
						count={view.appliedCount}
						aria-label={view.appliedCount > 0 ? `Filters (${view.appliedCount} applied)` : 'Filters'}
					/>
				</PopoverTrigger>
				<PopoverContent className={cn('max-h-[32rem] w-auto min-w-[28rem] overflow-auto', TOOLBAR_POPOVER)} align='start'>
					<div className='grid gap-4'>
						<h4 className='leading-none font-medium'>Filters</h4>
						<FilterBuilder
							model={view.model}
							filters={view.state.filters}
							onChange={view.setFilters}
							conditions={view.conditions}
							columnLabel={view.columnLabel}
							relatedModel={view.relatedModel}
						/>
						<div className='flex items-center justify-between gap-2 border-t pt-2'>
							<p className='text-muted-foreground text-xs' aria-live='polite'>
								{waiting > 0
									? `${waiting} ${waiting === 1 ? 'condition is' : 'conditions are'} not applied until complete.`
									: ''}
							</p>
							<Button variant='ghost' size='sm' onClick={view.clearFilters} disabled={conditionCount === 0}>
								Clear all
							</Button>
						</div>
					</div>
				</PopoverContent>
			</Popover>

			<Popover open={view.sortOpen} onOpenChange={view.setSortOpen}>
				<PopoverTrigger asChild>
					<ViewToggleButton
						icon={RiArrowUpDownLine}
						label='Sort'
						count={sortCount}
						aria-label={sortCount > 0 ? `Sort (${sortCount} keys)` : 'Sort'}
					/>
				</PopoverTrigger>
				<PopoverContent className={cn('w-auto min-w-[24rem]', TOOLBAR_POPOVER)} align='start'>
					<div className='grid gap-3'>
						<h4 className='leading-none font-medium'>Sort</h4>
						<SortControl
							model={view.model}
							sort={view.state.sort}
							onChange={view.setSort}
							columnKeys={columnKeys}
							columnLabel={view.columnLabel}
						/>
					</div>
				</PopoverContent>
			</Popover>

			<div className='ms-2'>
				<SearchBox
					plan={view.searchPlan}
					value={view.state.search}
					onChange={view.setSearch}
					columnLabel={view.columnLabel}
					inputRef={view.searchInputRef}
					ready={view.model !== null}
				/>
			</div>
		</div>
	);
});

/**
 * Why rows cannot be changed. A table that still takes new rows reads "Add only", so the
 * badge does not contradict Add row; the full reason is its title.
 */
function AccessBadge({ reason, canAdd }: { reason: string; canAdd: boolean }) {
	return (
		<span
			className='border-border bg-muted text-muted-foreground ms-1 inline-flex h-6 items-center gap-1 rounded-md border px-2 text-xs'
			role='status'
			title={canAdd ? `${reason} New rows can still be added.` : reason}
		>
			<RiLockLine className='size-3.5' aria-hidden='true' />
			{canAdd ? 'Add only' : 'Read-only'}
		</span>
	);
}

interface ActionGroupProps {
	selectedRowCount: number;
	/** Delete is offered with the row checkboxes (`showSelection`). */
	showDelete: boolean;
	canDelete: boolean;
	removal: RowRemoval | null;
	readOnlyReason: string | null;
	newRecordDisabledReason: string | null;
	tools: React.ReactNode;
	clearSelection: () => void;
	deleteSelected: () => void;
	addRow: (() => void) | undefined;
	exportSelected: (() => void) | undefined;
	openNewRecord: (() => void) | undefined;
}

/** What acts on rows: the data tools and New record, or the selected rows' own actions; then Add row. */
const ActionGroup = memo(function ActionGroup({
	selectedRowCount,
	showDelete,
	canDelete,
	removal,
	readOnlyReason,
	newRecordDisabledReason,
	tools,
	clearSelection,
	deleteSelected,
	addRow,
	exportSelected,
	openNewRecord,
}: ActionGroupProps) {
	const selecting = selectedRowCount > 0;
	const reduceMotion = useReducedMotion();
	const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, filter: 'blur(4px)' };
	const transition = reduceMotion ? { duration: 0 } : ({ type: 'spring', duration: 0.3, bounce: 0 } as const);
	// What sits before Add row: the selection's actions while rows are selected, else the tools
	// and New record (the two create actions sit together, after the divider).
	const context = selecting ? (
		<>
			<SelectionActions
				count={selectedRowCount}
				canDelete={canDelete}
				removal={removal}
				readOnlyReason={readOnlyReason}
				onClear={clearSelection}
				onDelete={showDelete ? deleteSelected : undefined}
				onExport={exportSelected}
			/>
			{addRow && <Separator orientation='vertical' className={DIVIDER} />}
		</>
	) : tools || openNewRecord ? (
		<>
			{tools}
			{tools && (openNewRecord || addRow) && <Separator orientation='vertical' className={DIVIDER} />}
			{openNewRecord && (
				// The wrapper carries the reason: a disabled button takes no pointer events.
				<span className='inline-flex' title={newRecordDisabledReason ?? 'Fill in a new record in a form.'}>
					<Button
						variant='outline'
						size='sm'
						aria-label='New record'
						aria-description={newRecordDisabledReason ?? undefined}
						disabled={newRecordDisabledReason !== null}
						onClick={openNewRecord}
					>
						<RiFileAddLine className='size-4' aria-hidden='true' />
						<ToolbarLabel fold='create'>New record</ToolbarLabel>
					</Button>
				</span>
			)}
		</>
	) : null;
	return (
		// `ms-auto` keeps the group, and Add row, at the right edge when a narrow toolbar wraps it.
		<div role='group' aria-label='Actions' className='ms-auto flex items-center gap-1'>
			<AnimatePresence initial={false} mode='popLayout'>
				{context && (
					<motion.div
						key={selecting ? 'selection' : 'tools'}
						className='flex items-center gap-1'
						initial={hidden}
						animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
						exit={hidden}
						transition={transition}
					>
						{context}
					</motion.div>
				)}
			</AnimatePresence>
			{addRow && (
				<Button size='sm' aria-label='Add row' onClick={addRow}>
					<RiAddLine className='size-4' aria-hidden='true' />
					<ToolbarLabel fold='primary'>Add row</ToolbarLabel>
				</Button>
			)}
		</div>
	);
});

interface SelectionActionsProps {
	count: number;
	canDelete: boolean;
	removal: RowRemoval | null;
	readOnlyReason: string | null;
	onClear: () => void;
	/** Omitted: no Delete (the grid shows no row checkboxes). */
	onDelete: (() => void) | undefined;
	onExport: (() => void) | undefined;
}

/** The selected rows' own actions, shown only while rows are selected. */
function SelectionActions({ count, canDelete, removal, readOnlyReason, onClear, onDelete, onExport }: SelectionActionsProps) {
	const rows = `${count.toLocaleString()} ${count === 1 ? 'row' : 'rows'}`;
	// With the plan, a new row is discarded even where saved rows cannot be deleted.
	const blockedReason = removal ? removal.blockedReason : canDelete ? null : readOnlyReason ?? 'Delete is unavailable for this table.';
	const confirm = removal
		? rowRemovalConfirm(removal)
		: { title: `Delete ${rows}?`, description: `This will permanently delete ${rows}. This cannot be undone.`, action: 'Delete' };
	return (
		<div
			role='group'
			aria-label='Selected rows'
			data-part-id='sheets-selection-actions'
			// The toolbar's 32px line: 28px buttons in 2px padding. Concentric: 8px corners in a 10px group.
			className='bg-primary/10 flex h-8 items-center gap-0.5 rounded-lg p-0.5 ps-2.5'
		>
			<span className='text-foreground me-1 text-sm font-medium tabular-nums' aria-live='polite'>
				{count.toLocaleString()} selected
			</span>
			{onExport && (
				<Button variant='ghost' size='icon-xs' aria-label='Export selected rows' title='Export selected rows as CSV' onClick={onExport}>
					<RiDownloadLine className='size-4' aria-hidden='true' />
				</Button>
			)}
			{onDelete && (
				<AlertDialog>
					{/* The wrapper carries the reason: a disabled button takes no pointer events. */}
					<span className='inline-flex' title={blockedReason ?? undefined}>
						<AlertDialogTrigger asChild>
							<Button
								variant='ghost'
								size='xs'
								aria-label='Delete selected rows'
								aria-description={blockedReason ?? undefined}
								disabled={blockedReason !== null}
								className='text-destructive hover:bg-destructive/10 hover:text-destructive px-2 text-sm'
							>
								<RiDeleteBin6Line className='size-4' aria-hidden='true' />
								<ToolbarLabel fold='view'>Delete</ToolbarLabel>
							</Button>
						</AlertDialogTrigger>
					</span>
					<AlertDialogContent>
						<AlertDialogHeader>
							<AlertDialogTitle>{confirm.title}</AlertDialogTitle>
							<AlertDialogDescription>{confirm.description}</AlertDialogDescription>
						</AlertDialogHeader>
						<AlertDialogFooter>
							<AlertDialogCancel>Cancel</AlertDialogCancel>
							<AlertDialogAction className='bg-destructive hover:bg-destructive/90 text-white' onClick={onDelete}>
								{confirm.action}
							</AlertDialogAction>
						</AlertDialogFooter>
					</AlertDialogContent>
				</AlertDialog>
			)}
			<Button variant='ghost' size='icon-xs' aria-label='Clear selection' title='Clear selection' onClick={onClear}>
				<RiCloseLine className='size-4' aria-hidden='true' />
			</Button>
		</div>
	);
}

/**
 * Formatter utilities for grid cell previews
 * - Keep these pure so they are easy to test
 */

export function compactJsonPreview(value: unknown, maxLen = 80): string {
	try {
		const s = typeof value === 'string' ? value : JSON.stringify(value);
		if (s.length <= maxLen) return s;
		return s.slice(0, maxLen - 1) + '\u2026';
	} catch {
		const s = String(value);
		return s.length > maxLen ? s.slice(0, maxLen - 1) + '\u2026' : s;
	}
}

export function formatArrayPreview(arr: unknown[], max = 3): string {
	const items = arr
		.slice(0, max)
		.map((v) => (typeof v === 'object' && v !== null ? compactJsonPreview(v, 20) : String(v)));
	const more = arr.length > max ? ` +${arr.length - max}` : '';
	return items.join(', ') + more;
}

export function formatImagePreview(val: unknown): string {
	if (!val) return '';
	if (typeof val === 'string') return val.split('/').pop() || val;
	if (typeof val === 'object' && val !== null) {
		const rec = val as Record<string, unknown>;
		const url = (rec.url as string) || '';
		const filename = (rec.filename as string) || url.split('/').pop() || 'image';
		return filename;
	}
	return String(val);
}

