const NO_ROWS_TO_REMOVE: RowRemoval = { rows: [], saved: 0, unsaved: 0, blockedReason: 'Select the rows to delete.' };

function SheetsInnerComponent<TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow>,
	ref: React.ForwardedRef<SheetsHandle>,
) {
	// The native TanStack DOM grid is the only render path (the canvas <DataEditor>
	// branch was removed at the glide cutover).
	// A host read-only grid applies to every table model read inside it (see `SheetsReadOnlyProvider`).
	return (
		<SheetsReadOnlyProvider readOnly={props.readOnly}>
			<FeedbackProvider>
				<SheetsDomInner {...props} forwardedRef={ref} />
			</FeedbackProvider>
		</SheetsReadOnlyProvider>
	);
}

// forwardRef erases the component's own generic parameter; the cast restores a
// generic call signature so `Sheets<MyRow>` keeps inferring TRow. This is the
// single allowed `as` cast for Unit A (well-known generic-forwardRef pattern).
export const Sheets = forwardRef(SheetsInnerComponent) as <TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow> & { ref?: React.Ref<SheetsHandle> },
) => React.ReactElement;

// ============================================================================
// The (only) render path. Reuses the useSheets hook for data/state, feeds its
// bindings into the v9 table instance + GridViewport, and renders native DOM
// cells via SheetsCellHost. Surfaces the same load states (error / loading /
// empty + consumer slots) the removed canvas branch owned.
// ============================================================================

function SheetsDomInner<TRow extends SheetsRow = SheetsRow>({
	forwardedRef,
	...props
}: DataGridProps<TRow> & { forwardedRef?: React.ForwardedRef<SheetsHandle> }) {
	const {
		tableName,
		className,
		pageSize = 100,
		showSelection = true,
		showPagination = true,
		infiniteScroll = false,
		slots,
	} = props;
	const s = useSheets<TRow>(props);
	const shell = s._shell;

	const { config, canUpload, scopeKey } = useSheetsContext();

	const viewportRef = useRef<GridViewportHandle>(null);

	// ============== EVENT->COMMAND DISPATCH (P4 Phase 1) ==============
	// ONE interceptable pipeline: every grid event resolves to a named command and runs
	// through the stable `dispatch` (see render/use-grid-command-pipeline). `ctxRef.current`
	// is the assembled GridCommandContext, repointed each render below.
	const { keymapRef, ctxRef, dispatch, isCommandEnabled } = useGridCommandPipeline(props);

	// ============== TABLE INSTANCE + STATE MIRRORS (Stage 2, Phase 6) ==============
	// Column descriptors, sizing and pinning, and the row selection in both directions
	// (see render/use-grid-table-state); the native SheetsSelection stays canonical.
	const {
		columns,
		table,
		resizeColumn,
		fixedWidthColumns,
		narrowColumns,
		combinedRows,
		getRowId,
		selection,
		setSelection,
		activeCell,
		lastActiveCellRef,
	} = useGridTableState(s);

	// ============== LEADING CHECKBOX / SELECT-ALL COLUMN (drives the canonical RangeSet) ==============
	const { rowMarker, toggleRowImpl, toggleAllImpl, canOpenRecords } = useRowMarker({
		combinedRows,
		selection,
		setSelection,
		tableModel: shell.tableModel,
		dispatch,
	});

	// Selected rows, and the grid's own CSV export (toolbar "Export selected" + SheetsHandle.exportCsv()).
	const { getSelectedRows, runCsvExport, handleExport, defaultProtectFormulas } = useGridCsvExport({
		tableName,
		csvExport: props.csvExport,
		selection,
		combinedRows,
		shell,
	});

	// ============== RECORD PANEL ==============
	// One record in a side panel (record/): opened from a row, the keyboard, the context menu,
	// the host (`recordId`) or a linked-record chip; it hands focus back to the grid on close.
	const recordPanel = useGridRecordPanel({
		tableModel: shell.tableModel,
		rows: shell.combinedRows,
		serverRowCount: shell.serverRowCount,
		recordId: props.recordId,
		onRecordOpenChange: props.onRecordOpenChange,
	});
	const sheetsContainerRef = useRef<HTMLDivElement | null>(null);

	useImperativeHandle(
		forwardedRef,
		(): SheetsHandle => ({
			scrollToRow: (index) => viewportRef.current?.scrollToIndex(index),
			submitDrafts: () => s.draft.submitDrafts(),
			refetch: () => s.refetch(),
			getSelectedRows,
			exportCsv: (opts) => runCsvExport(opts),
			openRecord: (recordId) => recordPanel.openRecordById(recordId),
			openNewRecord: () => recordPanel.openNewRecord(),
			closeRecord: () => recordPanel.controller.close(),
		}),
		[s.draft.submitDrafts, s.refetch, getSelectedRows, runCsvExport, recordPanel],
	);

	// ============== SCROLL + SELECTION RESET ON SORT/FILTER CHANGE ==============
	// When sort or filter changes the infinite query re-keys and the row set is a different,
	// index-based window — so any held selection/active-cell now points at the wrong rows.
	// Per the locked decision we CLEAR selection + active cell and scroll back to the top.
	// Keyed precisely on the same sort+filter inputs the query derives its where/orderBy from,
	// so it fires only on a real sort/filter transition (not on data refetch or draft edits).
	const optionsKey = shell.viewSignature;
	const didMountResetRef = useRef(false);
	useEffect(() => {
		if (!didMountResetRef.current) {
			didMountResetRef.current = true;
			return;
		}
		setSelection(emptySheetsSelection);
		viewportRef.current?.scrollToIndex(0);
	}, [optionsKey, setSelection]);

	// ============== NATIVE OVERLAY + INLINE EDITING (Phase 4, Stage B) ==============
	// The overlay and inline editors, activation through the edit-intent resolver, the
	// range-aware commit and following the edited cell on scroll (see render/use-grid-editing).
	// The refs it returns are the latches the command context reads.
	const {
		overlay,
		overlayClose,
		mediaDraft,
		activeMediaDraft,
		getSheetsCellContent,
		getEditorComponent,
		submitDraftRow,
		undo,
		redo,
		commitCells,
		emit,
		getSheetsCellContentRef,
		combinedRowsRef,
		selectionRef,
		columnsRef,
		openEditorImpl,
		openEditor,
		commitBulkOrSingle,
		editingCell,
		onInlineCommit,
		openEditorAtActiveCell,
		handleOverlayScroll,
	} = useGridEditing({ tableName, shell, config, canUpload, scopeKey, combinedRows, selection, columns, dispatch });

	// ============== FRESH DATA ON RETURN ==============
	// Coming back to the page after a while reads the table's shape (`_meta`, so new columns
	// appear) and the loaded rows again; the cursor, the scroll and unsaved new rows stay.
	const refreshOnReturn = s.refreshFromServer;

	// ============== DRAFT ROWS: ADD ROW, CURSOR AND SAVE GUIDANCE ==============
	// After Add row, and after a Save that still lacks required fields, the cursor lands on the
	// draft's first cell to fill (see draft-guidance), in view, with the grid focused so typing
	// fills it. Save on an incomplete draft also says what is missing.
	const placeDraftCursor = useCallback(
		(rowIndex: number, gaps: readonly DraftFieldGap[]) => {
			const keys = columnsRef.current.map((column) => column.key);
			const canFill = (key: string) =>
				key !== DRAFT_ACTION_COLUMN_KEY && !getSheetsCellContentRef.current(rowIndex, key).cell.readonly;
			const key = draftColumnToFill(keys, gaps, canFill);
			const col = key ? keys.indexOf(key) : 0;
			// Focus first: focusing the grid resumes its last cursor, which this then replaces.
			viewportRef.current?.focus();
			viewportRef.current?.scrollToCell(col, rowIndex);
			dispatch('cell.activate', undefined, { col, row: rowIndex });
		},
		[columnsRef, getSheetsCellContentRef, dispatch],
	);

	// appendRow resolves to the draft's index (an existing unsaved draft's, or undefined when the
	// model isn't ready). The draft reaches the rows a render later, so the cursor waits for it.
	// Threaded into <SheetsControls onAddRow=…> so the toolbar renders an Add-row button.
	const appendRow = s.draft.appendRow;
	const [pendingDraftRow, setPendingDraftRow] = useState<number | null>(null);
	const handleAddRow = useCallback(() => {
		void appendRow().then((index) => {
			if (index === undefined) return;
			viewportRef.current?.scrollToIndex(index);
			setPendingDraftRow(index);
		});
	}, [appendRow]);
	useEffect(() => {
		if (pendingDraftRow === null) return;
		const row = shell.combinedRows[pendingDraftRow];
		if (!getDraftMeta(row)) return;
		setPendingDraftRow(null);
		placeDraftCursor(pendingDraftRow, shell.tableModel ? missingDraftFields(row as Record<string, unknown>, shell.tableModel) : []);
	}, [pendingDraftRow, shell.combinedRows, shell.tableModel, placeDraftCursor]);

	// The row's Save: an incomplete draft says what it needs and takes the cursor there. Stable,
	// so the grid rows memoized on the render callback keep their identity.
	const draftSaveRef = useRef({ submitDraftRow, placeDraftCursor });
	draftSaveRef.current = { submitDraftRow, placeDraftCursor };
	const submitDraftRowGuided = useCallback(
		async (draftRowId: string) => {
			const result = await draftSaveRef.current.submitDraftRow(draftRowId);
			if (result.missing?.length) {
				reportIncompleteDraft(incompleteDraftMessage(result.missing));
				const rows = combinedRowsRef.current;
				let rowIndex = rows.length - 1;
				while (rowIndex >= 0 && getDraftMeta(rows[rowIndex] as SheetsRow | null)?.draftRowId !== draftRowId) rowIndex -= 1;
				if (rowIndex >= 0) draftSaveRef.current.placeDraftCursor(rowIndex, result.missing);
			}
			return result;
		},
		[combinedRowsRef],
	);

	// ============== CELL-RANGE SELECTION (Stage B) ==============
	// `anchorRef` holds the FIXED corner a contiguous range extends FROM. A plain activate
	// (click / non-shift Arrow) resets it to the new active cell; a shift extend keeps it put.
	// It is the caller-owned anchor `extendRangeToCell` expects (the model stays a pure value).
	const anchorRef = useRef<[number, number] | null>(null);
	const setSelectionRange = s.selection.setGridSelection;
	// Extend the contiguous range from the latched anchor to `[col, row]`. Reads the LATEST
	// selection (post-sort-clear safe) and falls back to the target as anchor when none latched.
	const extendToCell = useCallback(
		(col: number, row: number) => {
			const sel = selectionRef.current ?? emptySheetsSelection;
			const anchor = anchorRef.current ?? sel.current?.cell ?? [col, row];
			anchorRef.current = anchor;
			setSelectionRange(extendRangeToCell(sel, col, row, anchor[0], anchor[1]));
		},
		[setSelectionRange],
	);
	// Click-to-activate: park the active cell on the clicked cell. Stable (the shell's
	// setActiveCell is a stable useCallback), so it never busts the per-cell memo. Shift-click
	// EXTENDS the range from the latched anchor; a plain click activates AND resets the anchor.
	const setActiveCell = s.selection.setActiveCell;
	const handleActivateCell = useCallback(
		(col: number, row: number, shiftKey?: boolean) =>
			dispatch(shiftKey ? 'cell.extendToClicked' : 'cell.activate', undefined, { col, row }),
		[dispatch],
	);

	// ============== RIGHT-CLICK CONTEXT MENU (Stage B) ==============
	// A menu is just another EVENT SOURCE → dispatch, rendered ONCE at the grid level.
	const { contextMenu, setContextMenu, handleContextMenu, closeContextMenu } = useGridContextMenu({ selectionRef, dispatch });

	// What Delete does to the selected rows (toolbar) and to the rows under the menu (the selected
	// rows, else the cursor's). The menu's plan is read only while it is open.
	const removalAccess = useMemo(
		() => ({ canDeleteSaved: shell.canDelete, readOnlyReason: shell.readOnlyReason }),
		[shell.canDelete, shell.readOnlyReason],
	);
	const selectionRemoval = useMemo(
		() => planRowRemoval(selection?.rows.toArray() ?? [], combinedRows, removalAccess),
		[selection?.rows, combinedRows, removalAccess],
	);
	const menuRemoval: RowRemoval = useMemo(
		() => (contextMenu ? planRowRemoval(rowsUnderSelection(selection, combinedRows.length), combinedRows, removalAccess) : NO_ROWS_TO_REMOVE),
		[contextMenu, selection, combinedRows, removalAccess],
	);

	// Stable across cursor moves and editor opens: the viewport hands each row its own active,
	// selected and editing state, so only the rows those touch render again.
	const renderCell = useCallback<RenderCell>(
		(ctx) => (
			<SheetsCellHost
				ctx={ctx}
				getSheetsCellContent={getSheetsCellContent}
				openEditor={openEditor}
				onInlineCommit={onInlineCommit}
				onInlineCancel={overlayClose}
				onActivateCell={handleActivateCell}
				onContextMenu={handleContextMenu}
				onSubmitDraftRow={submitDraftRowGuided}
			/>
		),
		[onInlineCommit, overlayClose, getSheetsCellContent, openEditor, handleActivateCell, handleContextMenu, submitDraftRowGuided],
	);

	// ============== SPREADSHEET KEYBOARD NAV (grid root owns keys) ==============
	// The grid root (role=grid, tabIndex=0, aria-activedescendant) owns spreadsheet keys.
	// Arrows move the active cell (clamped); Enter/F2 open the overlay at the active cell.
	// IGNORE keydowns while an overlay editor is open so nav doesn't fight editing. The
	// active cell + col/row counts are read LATEST (refs) so a post-sort/filter clear wins.
	const moveActiveCell = s.selection.moveActive;
	const isOverlayOpen = overlay.isOpen;

	// Every grid key and the native copy / cut / paste events resolve to NAMED commands
	// through the ONE dispatch pipeline (see render/use-grid-keyboard).
	const { handleGridKeyDown, handleCopy, handleCut, handlePaste } = useGridKeyboard({
		isOverlayOpen,
		dispatch,
		keymapRef,
		rowHeightPx: shell.rowHeightPx,
	});

	// Dismissing the cursor: a press outside the grid (and outside its own toolbar, editors,
	// popovers, menus, dialogs and record panel) clears the active cell and range. Keyboard focus
	// on a grid with no active cell brings the cursor back.
	// A press on the grid's own empty space (below the rows, past the last column) clears it too.
	const clearCursor = useCallback(() => dispatch('selection.clear', undefined, { whole: true }), [dispatch]);
	const pressOutside = usePressOutside(activeCell != null, clearCursor);
	const handleGridFocus = useCallback(() => dispatch('cell.resume'), [dispatch]);

	// The status bar's count waits for the current view's first count (filter and search decide it).
	const viewRowCount = useViewRowCount(
		shell.totalCount,
		`${tableName}|${JSON.stringify(shell.viewQuery.where ?? null)}`,
		s.hasCompletedInitialLoad && !shell.isFetchingRows,
	);

	// The active overlay editor and its placement, computed in render (see render/active-editor).
	const active = overlay.active;
	const editorNode = activeEditorElement({
		active,
		mediaDraft,
		activeMediaDraft,
		getSheetsCellContent,
		getEditorComponent,
		combinedRows,
		getRowId,
		tableName: props.tableName,
		tableModel: shell.tableModel,
		commitBulkOrSingle,
		overlayClose,
		commitCellPatch: shell.commitCellPatch,
		submitDraftRow: shell.submitDraftRow,
		invalidateData: shell.invalidateData,
	});

	// INFINITE SCROLL: the virtualizer COUNT is left to its default (`rows.length`) — in
	// infinite mode `combinedRows` IS the full-length proxy (`serverRowCount + drafts`, null-backing
	// unloaded indices), so `rows.length` already spans every lazy row AND includes drafts; forcing
	// `count = totalCount` would drop the appended draft rows. We only wire the prefetch handler:
	// the viewport's overscan-inclusive {startIndex,endIndex} window IS the native range the shell
	// prefetches against (handleVisibleRegionChanged no-ops when paginated + clamps to the server
	// row count, but we still attach only in infinite mode, matching the prior paginated omission).
	const onVisibleRegionChanged = shell.onVisibleRegionChanged;
	const onVisibleRangeChange = useCallback(
		(range: VisibleRange) => {
			onVisibleRegionChanged(range);
		},
		[onVisibleRegionChanged],
	);

	// Filter, sort and search bindings (useSheetsView). Latched so the command context and the
	// view command target read the latest without re-creating.
	const viewRef = useRef(shell.view);
	viewRef.current = shell.view;
	const hasToolbarRef = useRef(!slots?.toolbar);
	hasToolbarRef.current = !slots?.toolbar;
	const savedViewsRef = useRef(shell.savedViews);
	savedViewsRef.current = shell.savedViews;
	const viewCommandTarget = useMemo(
		() => createViewCommandTarget(() => viewRef.current, () => hasToolbarRef.current, () => savedViewsRef.current),
		[],
	);
	// Each header's menu runs column commands through the ONE pipeline, with the column as payload.
	const renderHeaderMenu = useCallback(
		(colKey: string) => (
			<ColumnHeaderMenu
				colKey={colKey}
				view={shell.view}
				run={(commandId, payload) => dispatch(commandId, undefined, payload)}
				canRun={isCommandEnabled}
			/>
		),
		[shell.view, dispatch, isCommandEnabled],
	);
	// Why a context-menu view item (sort by this column) is disabled, read off the active cell.
	const openRecordReasonRef = useRef(recordPanel.openRecordReason);
	openRecordReasonRef.current = recordPanel.openRecordReason;
	const commandReason = useCallback((commandId: string) => {
		const cell = selectionRef.current?.current?.cell;
		if (commandId === 'record.open') return cell ? openRecordReasonRef.current(cell[1]) : null;
		return viewCommandReason(viewRef.current, commandId, cell ? columnsRef.current[cell[0]]?.key ?? null : null);
	}, []);
	// Header click routes through the ONE pipeline as `header.sortToggle` (Shift+click adds the
	// column to the sort); the command body calls ctx.sortToggle(colKey, additive).
	const onHeaderClick = useCallback(
		(colKey: string, additive: boolean) => dispatch('header.sortToggle', undefined, { colKey, additive }),
		[dispatch],
	);

	// Fill-handle drag release routes through the ONE pipeline as `fill.drag`; the command extends
	// the source band toward `target`, replicates the source values, and widens the selection.
	const handleFillDrag = useCallback(
		(sourceRange: SelectionRect, target: [number, number]) => dispatch('fill.drag', undefined, { from: sourceRange, to: target }),
		[dispatch],
	);

	// ============== ASSEMBLE + LATCH THE GRID COMMAND CONTEXT ==============
	// ONE object the commands run against: live GETTERS read the existing refs/derived render
	// values; methods are the EXISTING stable callbacks wrapped VERBATIM (no dispatcher is
	// reinvented). Rebuilt each render (cheap) and REPOINTED into `ctxRef` so `dispatch`
	// (stable, reads ctxRef.current) always sees the latest values — mirrors the openEditor
	// ref-latch. The pointer callbacks threaded into renderCell close over `dispatch`, not this,
	// so the per-cell memo is unaffected.
	ctxRef.current = {
		get rowCount() {
			return combinedRowsRef.current.length;
		},
		get colCount() {
			return columnsRef.current.length;
		},
		get activeCell() {
			return selectionRef.current?.current?.cell;
		},
		get resumeCell() {
			const last = lastActiveCellRef.current;
			return last && last[0] < columnsRef.current.length && last[1] < combinedRowsRef.current.length ? last : undefined;
		},
		get selection() {
			return selectionRef.current;
		},
		get combinedRows() {
			return combinedRowsRef.current;
		},
		get columnKeys() {
			return columnsRef.current.map((c) => c.key);
		},
		getAnchor: () => anchorRef.current,
		setAnchor: (anchor) => {
			anchorRef.current = anchor;
		},
		setActiveCell,
		moveActiveCell,
		extendToCell,
		setSelection: setSelectionRange,
		commitCells,
		openEditorAtActive: openEditorAtActiveCell,
		openEditorAt: openEditorImpl,
		undo,
		redo,
		scrollToCell: (col, row) => viewportRef.current?.scrollToCell(col, row),
		sortToggle: (colKey, additive) => viewRef.current.toggleSort(colKey, additive === true),
		toggleRow: toggleRowImpl,
		toggleAll: toggleAllImpl,
		getCellsInRange: (rect: SelectionRect): CellMatrix => {
			const r = extractCellsInRange(rect, combinedRowsRef.current, columnsRef.current.map((c) => c.key), (value, _row, colKey) =>
				cellCopyText(shell.tableModel, colKey, value),
			);
			return { cols: r.cols, rows: r.rows, values: r.values };
		},
		toTSV: (values) => serializeTSV(values),
		emit,
		view: viewCommandTarget,
		record: canOpenRecords
			? {
				canOpen: (rowIndex) => recordPanel.openRecordReason(rowIndex) === null,
				open: (rowIndex) => {
					recordPanel.openRecordAt(rowIndex);
				},
				isOpen: () => recordPanel.controller.current !== null,
				close: () => recordPanel.controller.close(),
			}
			: undefined,
		newRecord: {
			canCreate: () => Boolean(shell.tableModel?.operations.create),
			open: () => {
				recordPanel.openNewRecord();
			},
		},
		// The address an email or web-address cell opens, by the same rule as the link in the cell.
		link: {
			hrefAt: (col, row) => {
				const colKey = columnsRef.current[col]?.key;
				return colKey && combinedRowsRef.current[row] ? uriCellHref(getSheetsCellContentRef.current(row, colKey).cell) : null;
			},
			open: openUriCellLink,
		},
		// From the keyboard (Shift+F10, the menu key): the menu opens under the cell.
		contextMenu: {
			open: (col, row) => {
				const rect = document.getElementById(`sheets-cell-${row}-${col}`)?.getBoundingClientRect();
				if (rect) setContextMenu({ clientX: rect.left, clientY: rect.bottom });
			},
		},
	} satisfies GridCommandContext;

	// The record panel renders beside the grid and also over the empty state, so a new record
	// can be filled in on an empty table.
	const recordPanelElement = (
		<RecordPanel
			controller={recordPanel.controller}
			registry={shell.cellRegistry}
			typeOverrides={config.fieldTypeOverrides}
			mediaReason={canUpload ? null : 'Uploads need a storage endpoint'}
			navigationFor={recordPanel.navigationFor}
			onGridInvalidate={shell.invalidateData}
			onOpenTable={props.onOpenTable ?? null}
			returnFocus={() => sheetsContainerRef.current?.querySelector<HTMLElement>('[role="grid"]') ?? null}
			RelationSection={RelationSection}
		/>
	);

	// The toolbar's data tools, rebuilt only when what they read changes, so the toolbar's
	// memoized action group skips the renders a cursor move or an edit causes.
	const exportWhere = shell.viewQuery.where;
	const exportOrderBy = shell.viewQuery.orderBy;
	const exportColumns = shell.view.layout.visibleKeys;
	const toolbarTools = useMemo(
		() => (
			<>
				<ImportRecordsControl model={shell.tableModel} tableLabel={tableName} />
				<ExportViewControl
					model={shell.tableModel}
					where={exportWhere}
					orderBy={exportOrderBy}
					columns={exportColumns}
					filename={`${tableName}.csv`}
					protectFormulas={defaultProtectFormulas}
				/>
			</>
		),
		[shell.tableModel, tableName, exportWhere, exportOrderBy, exportColumns, defaultProtectFormulas],
	);

	// ============== LOAD STATES ==============
	// Surface real error/empty/loading states instead of a blank grid (moved here from
	// the removed canvas branch). A failure with no rows to show (no server rows AND no
	// drafts) is full-screen only while the table's model is missing: once the model loaded,
	// the toolbar stays and the failure overlays the body, so a search or filter the server
	// refuses can be cleared. Background-refetch errors keep the populated grid mounted and
	// surface via the `load:error` onEvent emission instead.
	const retryRows = () => s.refetch();
	const rowsError = !activeMediaDraft && s.dataError && shell.combinedRows.length === 0 ? s.dataError : null;
	if (rowsError && !shell.tableModel) {
		if (slots?.error) {
			return <>{slots.error({ error: rowsError, retry: retryRows })}</>;
		}
		return <SheetsErrorState error={rowsError} onRetry={retryRows} tableName={tableName} />;
	}

	// Initial load only; same-scope refetches retain their current query data.
	if (!activeMediaDraft && !rowsError && s.isInitialLoading) {
		if (slots?.loading) return <>{slots.loading}</>;
		return <SheetsLoadingState />;
	}

	// Loaded successfully but no server rows and nothing drafted yet (and no active filter). A host's
	// empty slot replaces the grid; the default keeps the toolbar and overlays the body (below), so
	// Import and New record stay where an empty table needs them most.
	const isEmptyTable = !activeMediaDraft && !rowsError && s.isEmpty;
	if (isEmptyTable && slots?.empty) {
		return <>{typeof slots.empty === 'function' ? slots.empty({ tableName }) : slots.empty}</>;
	}

	// Filtered-empty: the server returned 0 rows while a filter is active (so `isEmpty` above is
	// false — it requires no filter). Without this the body renders blank under the header and looks
	// broken; instead we keep the toolbar/filter bar mounted and overlay a "No matching rows" panel
	// with a one-click clear back to the unfiltered set.
	const activeFilterCount = shell.filterConditionCount;
	const searching = shell.view.state.search.trim() !== '';
	const isFilteredEmpty = !rowsError && shell.serverRowCount === 0 && shell.draftRowCount === 0 && (activeFilterCount > 0 || searching);
	const clearFiltersAndSearch = () => {
		shell.view.clearFilters();
		shell.view.setSearch('');
	};

	return (
		<SheetsErrorBoundary onError={config.onError}>
			<SheetsHistoryContext.Provider value={shell.recordHistory}>
			{/* Layout-neutral root: a press under it (portals included) is a press inside the grid. */}
			<div data-part-id='sheets-root' style={{ display: 'contents' }} onPointerDownCapture={pressOutside.onPointerDownCapture}>
			{/* Controls — consumer toolbar slot replaces the default <SheetsControls> block. */}
			<div data-part-id='sheets-controls-container'>
				{slots?.toolbar ? (
					<>{typeof slots.toolbar === 'function' ? slots.toolbar({ tableName }) : slots.toolbar}</>
				) : (
					<SheetsControls
						view={shell.view}
						columnKeys={shell.columnKeys}
						showSelection={showSelection}
						gridSelection={s.selection.gridSelection ?? null}
						setGridSelection={shell.setGridSelectionForControls}
						deleteSelected={s.draft.deleteSelected}
						onAddRow={shell.canCreate ? handleAddRow : undefined}
						canDelete={shell.canDelete}
						selectionRemoval={selectionRemoval}
						readOnlyReason={shell.readOnlyReason}
						onExport={handleExport}
						savedViews={shell.savedViews}
						newRecord={
							ctxRef.current.newRecord
								? { open: () => dispatch('record.new'), disabledReason: viewCommandReason(shell.view, 'record.new', null) }
								: undefined
						}
						tools={toolbarTools}
					/>
				)}
				<ModelIssuesNotice
					model={shell.tableModel}
					dropped={[...shell.view.dropped, ...shell.savedViews.activeDropped]}
					columnLabel={shell.view.columnLabel}
				/>
			</div>

			<div
				ref={sheetsContainerRef}
				data-part-id='sheets-container'
				role='region'
				aria-label={`${tableName} table`}
				className={cn('bg-background relative isolate flex h-full min-h-0 flex-1 flex-col overflow-hidden rounded-lg border', className)}
			>
				{/* The scroll area and what floats over it; the status bar below stays outside the scroll. */}
				<div className='relative min-h-0 flex-1'>
					{/* Relation chips in the active cell open their record in the panel. */}
					<SheetsOpenRecordContext.Provider value={recordPanel.openLinkedRecord}>
					<GridViewport
						table={table}
						rows={combinedRows}
						getRowId={getRowId}
						renderCell={renderCell}
						editingCell={editingCell}
						handleRef={viewportRef}
						onScroll={handleOverlayScroll}
						sort={shell.view.state.sort}
						onHeaderClick={onHeaderClick}
						getUnsortableReason={shell.view.unsortableReason}
						onResize={resizeColumn}
						frozenCount={shell.frozenCount}
						rowHeight={shell.rowHeightPx}
						onColumnMove={shell.view.layout.moveBeside}
						renderHeaderMenu={renderHeaderMenu}
						onVisibleRangeChange={infiniteScroll ? onVisibleRangeChange : undefined}
						rowMarker={showSelection ? rowMarker : undefined}
						activeCell={activeCell}
						activeRange={s.selection.gridSelection?.current?.range}
						onGridKeyDown={handleGridKeyDown}
						onGridFocus={handleGridFocus}
						onCopy={handleCopy}
						onCut={handleCut}
						onPaste={handlePaste}
						onFillDrag={handleFillDrag}
						fixedWidthColumns={fixedWidthColumns}
						narrowColumns={narrowColumns}
						onPressEmpty={clearCursor}
						activeDescendantId={activeCell ? `sheets-cell-${activeCell[1]}-${activeCell[0]}` : undefined}
					/>
					</SheetsOpenRecordContext.Provider>

					{/* An empty table: the toolbar stays above, with Add row and Import here too. */}
					{isEmptyTable && (
						<SheetsEmptyOverlay
							tableName={tableName}
							readOnlyReason={shell.readOnlyReason}
							onAddRow={shell.canCreate ? () => void s.draft.appendRow() : undefined}
							importModel={shell.canCreate ? shell.tableModel : null}
						/>
					)}

					{/* Filtered-empty panel — overlays the empty body while the filter bar stays visible above. */}
					{isFilteredEmpty && (
						<SheetsFilteredEmpty activeFilterCount={activeFilterCount} searching={searching} onClear={clearFiltersAndSearch} />
					)}

					{/* Rows failed to load: the toolbar stays usable above this panel. */}
					{rowsError && (
						<SheetsRowsError
							error={rowsError}
							activeFilterCount={activeFilterCount}
							searching={searching}
							onClear={clearFiltersAndSearch}
							onRetry={retryRows}
						>
							{slots?.error?.({ error: rowsError, retry: retryRows })}
						</SheetsRowsError>
					)}

					{/* Failed writes keep their full messages here until dismissed; the save status is in the bar. */}
					<div className='pointer-events-none absolute bottom-4 left-1/2 z-10 flex -translate-x-1/2 flex-col items-center gap-2'>
						<WriteErrorStack />
					</div>
				</div>

				<SheetsStatusBar
					total={viewRowCount}
					filtered={shell.view.appliedCount > 0 || searching}
					updating={shell.isFetchingRows}
				>
					<SaveStatus />
					<RefreshOnReturn refresh={refreshOnReturn} editorOpen={overlay.isOpen || editingCell != null} />
				</SheetsStatusBar>
			</div>

			{/* Pagination — hidden in infinite scroll mode (canvas parity). */}
			{showPagination && !infiniteScroll && s.pagination.pageCount > 1 && (
				<SheetsPagination
					pageIndex={s.pagination.pageIndex}
					pageSize={pageSize}
					totalCount={shell.totalCount}
					totalPages={s.pagination.pageCount}
					setPageIndex={s.pagination.setPageIndex}
				/>
			)}

			<OverlayManager
				open={overlay.isOpen && editorNode != null}
				anchorRect={active?.anchorRect ?? null}
				presetClass={editorNode?.presetClass}
				dismissMode={editorNode?.dismissMode}
				onCancel={overlayClose}
			>
				<SheetsOpenTableContext.Provider value={props.onOpenTable ?? null}>
					<SheetsOpenRecordContext.Provider value={recordPanel.openLinkedRecord}>{editorNode?.element}</SheetsOpenRecordContext.Provider>
				</SheetsOpenTableContext.Provider>
			</OverlayManager>

			{/* Right-click context menu — items dispatch through the SAME pipeline as keys/clicks
			    (clipboard.* with no native event take the navigator.clipboard fallback). Rendered once. */}
			<SheetsContextMenu
				state={contextMenu}
				onClose={closeContextMenu}
				onAction={(commandId) => dispatch(commandId)}
				isEnabled={isCommandEnabled}
				reasonFor={commandReason}
				onAddRow={handleAddRow}
				onDeleteRows={s.draft.deleteRows}
				removal={menuRemoval}
				canAddRows={shell.canCreate}
				canOpenRecords={Boolean(ctxRef.current.record)}
			/>

			{recordPanelElement}
			</div>
			</SheetsHistoryContext.Provider>
		</SheetsErrorBoundary>
	);
}

// Public props alias — generic over the consumer's row type (default SheetsRow keeps
// existing untyped callers compiling). Carries DataGridProps' TRow through.
export type SheetsProps<TRow extends SheetsRow = SheetsRow> = DataGridProps<TRow>;

/**
 * Refreshes the grid when the page comes back after a while, once no editor is open and no
 * save is in flight. A leaf of its own, so following the save status never renders the grid.
 */
function RefreshOnReturn({ refresh, editorOpen }: { refresh: () => void; editorOpen: boolean }): null {
	const saving = useOperationFeedback()?.status === 'pending';
	useRefreshOnReturn({ refresh, busy: saving || editorOpen });
	return null;
}

import type { SheetsRow } from './row-model';
import type { CellTypeDefinition } from '../cell-types/define-cell-type';
import type { CellSlots } from '../cell-model/cell-slots';
// SheetsThemeInput is owned + exported by Unit B (./sheets.theme). Imported as a type
// only; if Unit B's change has not landed yet this import is the single expected
// cross-unit transient error — both units typecheck once they land together.
import type { SheetsThemeInput } from './sheets.theme';
import type { GridCommand, Binding, Interceptor, DispatchEvent, CommandResult } from '../commands';
import type { SheetsRowIdentifier } from '../row-identity';
import type { SheetsOpenTableHandler } from '../relations/relation-navigation';
import type { SheetsViewProps } from './view-state/use-sheets-view';

export interface DataGridRow {
	id: string;
	[key: string]: any;
}

// =============================================================================
// Public component API — events, render slots, imperative handle
// =============================================================================

/**
 * Lifecycle/interaction event emitted by {@link Sheets} via the optional
 * `onEvent` prop. Purely observational: firing an event never changes grid
 * behavior, so consumers can wire analytics/telemetry without side effects.
 */
export interface SheetsEvent {
	type:
		| 'load:success'
		| 'load:error'
		| 'cell:edit'
		| 'row:create'
		| 'row:delete'
		| 'filter:apply'
		| 'sort:change'
		| 'search:change'
		| 'page:change';
	/** The table the event originated from. */
	tableName: string;
	/** Epoch ms (`Date.now()`) when the event fired. */
	at: number;
	/** Event-specific extra context (ids, values, error, page index, …). */
	meta?: Record<string, unknown>;
}

/** Context passed to the `toolbar` slot when supplied as a render function. */
export interface SheetsToolbarSlotContext {
	tableName: string;
}

/**
 * Render-slot overrides. Each provided slot replaces the corresponding default
 * (the Phase-0 SheetsErrorState / SheetsEmptyState / SheetsLoadingState stay as
 * fallbacks when a slot is omitted). All slots are optional and additive.
 */
export interface SheetsSlots {
	/** Replaces (precedes) the default <SheetsControls> toolbar block. */
	toolbar?: React.ReactNode | ((ctx: SheetsToolbarSlotContext) => React.ReactNode);
	/** Replaces the default full-screen empty state. */
	empty?: React.ReactNode | ((ctx: { tableName: string }) => React.ReactNode);
	/**
	 * Replaces the default error panel: full-screen while the table's model is missing, and over
	 * the grid body (toolbar kept) when only the rows failed to load.
	 */
	error?: (ctx: { error: unknown; retry: () => void }) => React.ReactNode;
	/** Replaces the default full-screen loading state. */
	loading?: React.ReactNode;
}

/**
 * Alias kept in sync with {@link SheetsSlots}. The `slots` prop is typed with
 * this name to match the shared Phase-4 contract; `SheetsSlots` is the exported
 * public name.
 */
export type SheetsSlotsInput = SheetsSlots;

/**
 * Imperative handle exposed through a `ref` on {@link Sheets}. Lets host apps
 * drive the grid (scroll, submit drafts, refetch, read selection, export CSV)
 * without reaching into internals.
 */
export interface SheetsHandle {
	/** Scroll the viewport so the row at `index` is visible. */
	scrollToRow(index: number): void;
	/** Submit all pending draft rows (awaits the in-flight submission). */
	submitDrafts(): Promise<void>;
	/** Refetch the underlying table data (mode-aware: infinite vs paginated). */
	refetch(): void;
	/** Return the currently selected rows (empty array when nothing selected). */
	getSelectedRows(): Record<string, unknown>[];
	/**
	 * Download the selected rows (or all rows when none selected) as CSV.
	 * `protectFormulas` overrides the grid's `csvExport.protectFormulas` for this download.
	 */
	exportCsv(opts?: { columns?: string[]; filename?: string; protectFormulas?: boolean }): void;
	/** Open a record of this table in the record panel. False when the identifier does not name a record. */
	openRecord(recordId: SheetsRowIdentifier): boolean;
	/** Open the record panel on a new record. False when the table does not allow new records. */
	openNewRecord(): boolean;
	/** Close the record panel. */
	closeRecord(): void;
}

export interface DataGridColumnMeta {
	fieldName: string;
	fieldType: {
		gqlType: string;
		pgType?: string | null;
		pgAlias?: string | null;
	};
}

/**
 * `filters` / `sort` / `search` (each with its change callback) let a host own
 * the view state, for example to persist it as a saved view. Each one omitted is
 * owned by the grid. The grid checks every given state against the table model
 * and leaves out what the model no longer supports (see `validateSheetsViewState`).
 */
export interface DataGridProps<TRow extends SheetsRow = SheetsRow> extends SheetsViewProps {
	tableName: string;
	/**
	 * Make the grid read-only for this host: `true`, or the reason to show. Every cell,
	 * paste and fill, Add row, New record, Import, Delete, every link and the record panel's
	 * fields refuse writes and show the reason; viewing, sorting, filtering, search and
	 * export stay. `true` shows "This table is read-only here."
	 */
	readOnly?: boolean | string;
	className?: string;
	pageSize?: number;
	showSelection?: boolean;
	showPagination?: boolean;
	onRowSelect?: (selectedRows: TRow[]) => void;
	onCellEdit?: (id: SheetsRowIdentifier, field: string, value: unknown) => void;
	// Relation rendering options
	relationChipLimit?: number;
	relationLabelMaxLength?: number;
	/**
	 * Enable infinite scroll mode with cursor-based pagination.
	 * When enabled:
	 * - Rows are loaded on-demand as user scrolls
	 * - Traditional pagination UI is hidden
	 * - Uses hybrid cursor/offset pagination for optimal performance
	 * @default false
	 */
	infiniteScroll?: boolean;
	/** Per-instance cell types merged over provider plugins. */
	cellTypes?: CellTypeDefinition<any>[];
	/** Consumer cell-component overrides keyed by cell typeKey. */
	cellSlots?: CellSlots;
	/**
	 * Optional observational event callback. Fired on load success/error, cell
	 * edits, row create/delete, filter apply, sort change, and page change.
	 * Omitting it leaves behavior unchanged.
	 */
	onEvent?: (e: SheetsEvent) => void;
	/**
	 * Called when the user asks to see another table, for example the table that
	 * stores links needing more fields than the link editor can fill. The grid
	 * does not navigate; omit it and the editor offers no such action.
	 */
	onOpenTable?: SheetsOpenTableHandler;
	/**
	 * CSV export settings. `protectFormulas`: text that starts with =, +, -, @, a tab or
	 * a carriage return is written with a leading apostrophe, so a spreadsheet app does not
	 * run it as a formula (numbers are not changed). Off by default. It applies to
	 * "Export selected" and `SheetsHandle.exportCsv`, and is the starting choice of the
	 * checkbox in the "Export view" dialog.
	 */
	csvExport?: { protectFormulas?: boolean };
	/**
	 * The record open in the record panel, for deep links: an identifier of a record of
	 * this table, or null for closed. Omit it to let the grid own the panel state.
	 */
	recordId?: SheetsRowIdentifier | null;
	/** Called whenever the user opens, moves to or closes a record of this table in the record panel. */
	onRecordOpenChange?: (recordId: SheetsRowIdentifier | null) => void;
	/**
	 * Optional render-slot overrides for the toolbar / empty / error / loading
	 * regions. Any omitted slot falls back to the built-in default.
	 */
	slots?: SheetsSlotsInput;
	/**
	 * Override or extend the grid command set: a command with a matching id REPLACES
	 * the built-in body, a new id ADDS a command. Omitting it = the default set.
	 */
	commands?: GridCommand[];
	/**
	 * Extra / override key bindings, scanned BEFORE the defaults, so a rebind of a
	 * built-in chord wins. When several bindings match a key, they are tried in order
	 * and the first whose command can run wins. Omitting it = the default keymap.
	 */
	keymap?: Binding[];
	/**
	 * Interceptors wrapping every dispatch (observe / veto / transform). Listed FIRST
	 * = OUTERMOST; the consumer list runs outside the `onCommand` tail observer.
	 */
	interceptors?: Interceptor[];
	/**
	 * Observe every dispatch and its result (sugar for an innermost tail-observer
	 * interceptor — runs after all consumer interceptors, never alters behavior).
	 */
	onCommand?: (ev: DispatchEvent, result: CommandResult) => void;
	/** Optional theme token overrides (per light/dark mode) or a Glide-theme function. */
	theme?: SheetsThemeInput;
	/** Optional explicit theme mode; defaults to following the document `dark` class. */
	themeMode?: 'light' | 'dark' | 'system';
	/**
	 * @internal Render-path switch for the TanStack DOM port spike. `'dom'`
	 * renders the native DOM grid; anything else (default) renders the canvas
	 * `<DataEditor>`. Double-underscore = internal/undocumented; NOT a public API.
	 */
	__impl?: 'canvas' | 'dom';
}

import { CellRegistry } from '../cell-types/cell-registry';
import type { MetaField, TableModel } from '@constructive-io/data';
import { mapToFrontendCellType } from '../cell-types/type-mapping';
import { DEFAULT_COLUMN_WIDTH, defaultWidthForCellType } from '../cell-types/column-width';
import type { RelationInfo } from '../store/relation-info-slice';
import { fieldLabel } from '../cell-types/field-label';

import type { FieldMetadata } from '../cell-types/cell-type-resolver';
import { compactJsonPreview } from './sheets.formatters';

export function formatColumnHeader(fieldName: string): string {
	return fieldName
		.replace(/([A-Z])/g, ' $1')
		.replace(/^./, (str) => str.toUpperCase())
		.replace(/_/g, ' ')
		.trim();
}

/** Default column width from raw field metadata: a registered width, else the cell type's default (long numbers are wider). */
export function getColumnWidthByMeta(field: FieldMetadata): number {
	const t = field.type;
	if (!t) return DEFAULT_COLUMN_WIDTH;
	const cellType = mapToFrontendCellType({
		gqlType: t.gqlType,
		isArray: !!t.isArray,
		pgType: t.pgType,
		subtype: t.subtype ?? null,
	});
	const entry = CellRegistry.get(cellType);
	return entry?.metadata?.width ?? defaultWidthForCellType(cellType);
}

export function mapFromFieldMetaMap(fieldMetaMap: Map<string, MetaField>): Record<string, MetaField | undefined> {
	const record: Record<string, MetaField | undefined> = {};
	fieldMetaMap.forEach((value, key) => {
		record[key] = value;
	});
	return record;
}

export function mapFromRelationInfoMap(
	relationInfoMap: Map<string, RelationInfo | undefined>,
): Record<string, RelationInfo | undefined> {
	const record: Record<string, RelationInfo | undefined> = {};
	relationInfoMap.forEach((value, key) => {
		record[key] = value;
	});
	return record;
}

function unwrapConnectionNode(entry: unknown): unknown {
	if (!entry || typeof entry !== 'object') return entry;

	const record = entry as Record<string, unknown>;
	if ('node' in record && record.node !== undefined) {
		return unwrapConnectionNode(record.node);
	}
	return entry;
}

export function unwrapRelationValue<T = unknown>(value: T): T {
	if (Array.isArray(value)) {
		return value.map((entry) => unwrapRelationValue(entry)) as unknown as T;
	}

	if (value && typeof value === 'object') {
		const record = value as Record<string, unknown>;

		if (Array.isArray(record.nodes)) {
			return record.nodes.map((entry) => unwrapRelationValue(entry)) as unknown as T;
		}

		if (Array.isArray(record.edges)) {
			return record.edges.map((edge) => unwrapRelationValue(unwrapConnectionNode(edge))) as unknown as T;
		}

		if ('node' in record && record.node !== undefined) {
			return unwrapRelationValue(record.node) as unknown as T;
		}
	}

	return value;
}

export function normalizeServerRow(row: Record<string, unknown>, relationFields: Set<string>): Record<string, unknown> {
	if (!row || typeof row !== 'object') {
		return row;
	}

	const next: Record<string, unknown> = { ...row };
	relationFields.forEach((fieldName) => {
		next[fieldName] = unwrapRelationValue(next[fieldName]);
	});
	return next;
}

/** A draft cell holds no value yet: nothing was typed, or the column was cleared. */
function isMissing(value: unknown): boolean {
	return value === null || value === undefined || value === '';
}

/**
 * Required-field check for a draft row, from the table model: a column the create
 * input requires (`write.requiredOnCreate`, so it has no default) must have a value.
 * A key column is checked like any other; nothing is exempt by its name.
 */
export function validateDraftRowRequiredFields(
	values: Readonly<Record<string, unknown>>,
	model: TableModel,
): Record<string, string> {
	const errors: Record<string, string> = {};
	for (const column of model.columns) {
		if (!column.write.create || !column.write.requiredOnCreate) continue;
		if (isMissing(values[column.name])) errors[column.name] = `${fieldLabel(column.name)} is required`;
	}
	return errors;
}

/** A foreign-key value the relation editor stored as a record or a list of records, reduced to its key. */
function normalizeForeignKeyValue(input: unknown): unknown {
	const extractId = (candidate: unknown): string | number | null => {
		if (candidate === null || candidate === undefined) return null;
		if (typeof candidate === 'object') {
			const id = (candidate as Record<string, unknown>).id;
			return typeof id === 'string' || typeof id === 'number' ? id : null;
		}
		return typeof candidate === 'string' || typeof candidate === 'number' ? candidate : null;
	};
	if (input === undefined || input === null) return undefined;
	if (Array.isArray(input)) {
		return input.map((entry) => extractId(entry)).filter((entry): entry is string | number => entry !== null);
	}
	return extractId(input) ?? undefined;
}

/**
 * The create values of a draft row, from the table model: only columns the create
 * input accepts, and only the ones the user set (a cleared cell sends its explicit
 * null or ''), so the database supplies its defaults for the untouched rest. A key
 * with no default is sent like any other column. Values were already parsed by the
 * column rules when they were entered.
 */
export function prepareDraftSubmissionPayload(
	values: Readonly<Record<string, unknown>>,
	model: TableModel,
	relationInfoByKey?: Record<string, RelationInfo | undefined>,
): Record<string, unknown> {
	const payload: Record<string, unknown> = {};
	for (const column of model.columns) {
		if (!column.write.create) continue;
		let value = values[column.name];
		if (value === undefined) continue;
		if (value !== null && relationInfoByKey?.[column.name]?.foreignKeyField === column.name) {
			value = normalizeForeignKeyValue(value);
			if (value === undefined) continue;
		}
		payload[column.name] = value;
	}
	return payload;
}

export function prepareDraftRelationValue(
	rawValue: unknown,
	relationInfo: RelationInfo,
): {
	relationData: unknown;
	foreignKeyUpdates?: Record<string, unknown>;
	relationReferences?: unknown;
} {
	let value = rawValue;

	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (!trimmed) {
			value = null;
		} else {
			try {
				value = JSON.parse(trimmed);
			} catch {
				value = trimmed;
			}
		}
	}

	const isListRelation = relationInfo.kind === 'hasMany' || relationInfo.kind === 'manyToMany';

	if (isListRelation) {
		const entries = Array.isArray(value) ? value : value == null ? [] : [value];
		const normalized = entries
			.map(normalizeRelationEntry)
			.filter((entry): entry is RelationNormalization => entry !== null);

		const relationData = normalized.map((entry) => entry.value);
		const relationReferences = normalized.map((entry) => entry.reference ?? null);

		const fkField = relationInfo.foreignKeyField;
		const foreignKeyUpdates = fkField
			? {
					[fkField]: normalized.map((entry) => (entry.reference === undefined ? null : entry.reference)),
				}
			: undefined;

		return {
			relationData,
			foreignKeyUpdates,
			relationReferences,
		};
	}

	const normalizedEntry = normalizeRelationEntry(Array.isArray(value) ? (value[0] ?? null) : value);

	const relationData = normalizedEntry?.value ?? null;
	const relationReference = normalizedEntry?.reference ?? null;

	const fkField = relationInfo.foreignKeyField;
	const foreignKeyUpdates = fkField
		? {
				[fkField]: normalizedEntry?.reference ?? null,
			}
		: undefined;

	return {
		relationData,
		foreignKeyUpdates,
		relationReferences: relationReference,
	};
}

type RelationNormalization = {
	value: unknown;
	reference: string | number | null | undefined;
};

function normalizeRelationEntry(entry: unknown): RelationNormalization | null {
	if (entry === null || entry === undefined || entry === '') {
		return null;
	}

	if (Array.isArray(entry)) {
		return normalizeRelationEntry(entry[0]);
	}

	if (typeof entry === 'object') {
		const record = entry as Record<string, unknown>;
		const id = record.id;
		return {
			value: record,
			reference: typeof id === 'string' || typeof id === 'number' ? (id as string | number) : null,
		};
	}

	if (typeof entry === 'string' || typeof entry === 'number') {
		return {
			value: entry,
			reference: entry,
		};
	}

	return null;
}

// Infer cell type from data content when location/metadata is not available
export function inferCellTypeFromData(data: string): string | undefined {
	if (!data || typeof data !== 'string') return undefined;

	try {
		const parsed = JSON.parse(data);

		// Check for geometry data patterns (wrapped format with geojson property)
		if (parsed && typeof parsed === 'object' && parsed.geojson) {
			// This is the wrapped geometry format: {"geojson": {...}, "srid": ..., "x": ..., "y": ...}
			// But sometimes it might only have the geojson property
			if (parsed.geojson.type === 'Point') {
				return 'geometry-point';
			} else if (parsed.geojson.type === 'GeometryCollection') {
				return 'geometry-collection';
			} else {
				return 'geometry';
			}
		}

		// Check for raw GeoJSON (direct GeoJSON object)
		if (parsed && typeof parsed === 'object' && parsed.type && parsed.coordinates) {
			const validGeoJSONTypes = [
				'Point',
				'LineString',
				'Polygon',
				'MultiPoint',
				'MultiLineString',
				'MultiPolygon',
				'GeometryCollection',
			];
			if (validGeoJSONTypes.includes(parsed.type)) {
				if (parsed.type === 'Point') {
					return 'geometry-point';
				} else if (parsed.type === 'GeometryCollection') {
					return 'geometry-collection';
				} else {
					return 'geometry';
				}
			}
		}

		// Check for array data
		if (Array.isArray(parsed)) {
			return 'array';
		}

		// Check for interval data (objects with days/hours/minutes/seconds properties)
		if (
			parsed &&
			typeof parsed === 'object' &&
			(parsed.days !== undefined ||
				parsed.hours !== undefined ||
				parsed.minutes !== undefined ||
				parsed.seconds !== undefined)
		) {
			return 'interval';
		}

		// Check for image data (objects with url/src/href/path properties)
		if (parsed && typeof parsed === 'object' && (parsed.url || parsed.src || parsed.href || parsed.path)) {
			return 'image';
		}

		// Check for date strings (ISO format)
		if (typeof parsed === 'string' && /^\d{4}-\d{2}-\d{2}/.test(parsed)) {
			if (parsed.includes('T')) {
				return 'datetime';
			} else {
				return 'date';
			}
		}

		// Generic JSON object
		return 'json';
	} catch {
		// Not valid JSON, could be other data types

		// Check for date strings
		if (/^\d{4}-\d{2}-\d{2}/.test(data)) {
			if (data.includes('T')) {
				return 'datetime';
			} else {
				return 'date';
			}
		}

		// Check for time strings
		if (/^\d{2}:\d{2}/.test(data)) {
			return 'time';
		}

		return undefined;
	}
}

// Utility functions for array previews
export function formatArrayPreview(arr: any[]): string {
	const max = 3;
	const items = arr.slice(0, max).map((v) => (typeof v === 'object' ? compactJsonPreview(v, 20) : String(v)));
	const more = arr.length > max ? ` +${arr.length - max}` : '';
	return items.join(', ') + more;
}


// Row operations
export async function handleRowAppend(
	createFunction: (data: any) => Promise<any>,
): Promise<'top' | 'bottom' | number | undefined> {
	const { createdRow } = await createFunction({});
	if (createdRow) {
		return 'bottom';
	}
	return undefined;
}

// Type-safe column resize handler
export function createColumnResizeHandler(resizeColumn: (id: string, width: number) => void) {
	return (column: { id?: string }, newSize: number) => {
		if (column.id) {
			resizeColumn(column.id, newSize);
		}
	};
}

/**
 * The toolbar sort control: lists the sort keys in priority order and lets the
 * user change a direction, reorder, remove, or add a key. Only columns the
 * table model can sort by are offered.
 */
import { RiArrowDownLine, RiArrowUpLine, RiCloseLine } from '@remixicon/react';

import type { ColumnModel, TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

import { moveSortKey, setSortDirection } from '../view-state/view-state';
import type { SheetsSortDirection, SheetsSortKey } from '../view-state/view-state.types';

/** Words for the two directions of a column, by what its values are. */
export function sortDirectionLabels(column: ColumnModel | undefined): Record<SheetsSortDirection, string> {
	if (column && !column.value.isArray) {
		switch (column.value.kind) {
			case 'integer':
			case 'bigint':
			case 'decimal':
			case 'float':
				return { asc: '1 → 9', desc: '9 → 1' };
			case 'date':
			case 'datetime':
				return { asc: 'Oldest first', desc: 'Newest first' };
			case 'time':
				return { asc: 'Earliest first', desc: 'Latest first' };
			case 'boolean':
				return { asc: 'False first', desc: 'True first' };
			case 'enum':
				return { asc: 'First → last option', desc: 'Last → first option' };
			case 'text':
				return { asc: 'A → Z', desc: 'Z → A' };
		}
	}
	return { asc: 'Ascending', desc: 'Descending' };
}

export interface SortControlProps {
	model: TableModel | null;
	sort: readonly SheetsSortKey[];
	onChange: (sort: readonly SheetsSortKey[]) => void;
	/** Grid columns, in display order. */
	columnKeys: readonly string[];
	columnLabel: (name: string) => string;
}

export function SortControl({ model, sort, onChange, columnKeys, columnLabel }: SortControlProps) {
	if (!model) return <p className='text-muted-foreground text-sm'>Sorting is available once the table has loaded.</p>;
	const columnOf = (name: string) => model.columns.find((column) => column.name === name);
	const sortable = columnKeys.filter((key) => columnOf(key)?.sort);
	const available = sortable.filter((key) => !sort.some((entry) => entry.column === key));

	return (
		<div className='grid gap-3' data-part-id='sheets-sort-control'>
			{sort.length === 0 ? (
				<p className='text-muted-foreground text-sm'>Rows are not sorted.</p>
			) : (
				<ol className='grid gap-2' aria-label='Sort order'>
					{sort.map((entry, index) => {
						const label = columnLabel(entry.column);
						const directions = sortDirectionLabels(columnOf(entry.column));
						return (
							<li key={entry.column} className='flex items-center gap-2' data-part-id='sheets-sort-key'>
								<span className='text-muted-foreground w-4 text-right text-xs tabular-nums'>{index + 1}</span>
								<span className='w-[9rem] truncate text-sm' title={entry.column}>
									{label}
								</span>
								<Select
									value={entry.direction}
									onValueChange={(direction) => onChange(setSortDirection(sort, entry.column, direction as SheetsSortDirection))}
								>
									<SelectTrigger size='sm' className='w-[9.5rem]' aria-label={`Direction for ${label}`}>
										<SelectValue />
									</SelectTrigger>
									<SelectContent>
										<SelectItem value='asc'>{directions.asc}</SelectItem>
										<SelectItem value='desc'>{directions.desc}</SelectItem>
									</SelectContent>
								</Select>
								<Button
									variant='ghost'
									size='icon-xs'
									aria-label={`Move ${label} up`}
									disabled={index === 0}
									onClick={() => onChange(moveSortKey(sort, index, index - 1))}
								>
									<RiArrowUpLine aria-hidden='true' />
								</Button>
								<Button
									variant='ghost'
									size='icon-xs'
									aria-label={`Move ${label} down`}
									disabled={index === sort.length - 1}
									onClick={() => onChange(moveSortKey(sort, index, index + 1))}
								>
									<RiArrowDownLine aria-hidden='true' />
								</Button>
								<Button
									variant='ghost'
									size='icon-xs'
									aria-label={`Remove sort by ${label}`}
									onClick={() => onChange(sort.filter((candidate) => candidate.column !== entry.column))}
								>
									<RiCloseLine aria-hidden='true' />
								</Button>
							</li>
						);
					})}
				</ol>
			)}
			<div className='flex items-center gap-2 border-t pt-2'>
				{available.length > 0 ? (
					<Select value={null} onValueChange={(column) => onChange([...sort, { column, direction: 'asc' }])}>
						<SelectTrigger size='sm' className='w-[12rem]' aria-label='Add a sort'>
							<SelectValue placeholder='Add a sort' />
						</SelectTrigger>
						<SelectContent>
							{available.map((key) => (
								<SelectItem key={key} value={key} title={key}>
									{columnLabel(key)}
								</SelectItem>
							))}
						</SelectContent>
					</Select>
				) : (
					<p className='text-muted-foreground text-xs'>
						{sortable.length === 0 ? 'No column of this table can be sorted.' : 'Every sortable column is in the sort.'}
					</p>
				)}
				{sort.length > 0 && (
					<Button variant='ghost' size='xs' className='ml-auto' onClick={() => onChange([])}>
						Clear sort
					</Button>
				)}
			</div>
		</div>
	);
}

// Whether table lists show system tables: the tables a platform module made and keeps (sessions,
// memberships, limits, storage). Off by default. The browser remembers the choice, and every list
// on the page follows the one setting (a sidebar and a narrow-screen picker stay in step).
import { useSyncExternalStore } from 'react';

const STORAGE_KEY = 'constructive:sheets:show-system-tables';

const listeners = new Set<() => void>();
// Where the choice lives when the browser keeps no storage (a private window, blocked site data).
let unsaved: boolean | null = null;

function readShown(): boolean {
	try {
		const stored = window.localStorage.getItem(STORAGE_KEY);
		if (stored !== null) return stored === 'true';
	} catch {
		// No storage: the in-memory choice stands.
	}
	return unsaved ?? false;
}

function writeShown(show: boolean): void {
	unsaved = show;
	try {
		window.localStorage.setItem(STORAGE_KEY, String(show));
	} catch {
		// No storage: the choice lasts for this page.
	}
	for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
	listeners.add(listener);
	// Another tab changed it.
	const onStorage = (event: StorageEvent) => {
		if (event.key === STORAGE_KEY) listener();
	};
	window.addEventListener('storage', onStorage);
	return () => {
		listeners.delete(listener);
		window.removeEventListener('storage', onStorage);
	};
}

/** Whether system tables show in table lists, and the setter every list on the page follows. */
export function useShowSystemTables(): [boolean, (show: boolean) => void] {
	const shown = useSyncExternalStore(subscribe, readShown, () => false);
	return [shown, writeShown];
}

/**
 * The tables a list shows: the owner's, and the system tables only while they are shown. The open
 * table always stays, so a system table opened by a link or an address is never missing from the list.
 */
export function visibleTables<T extends { system?: boolean }>(
	tables: readonly T[],
	showSystem: boolean,
	isOpen: (table: T) => boolean,
): T[] {
	return tables.filter((table) => !table.system || showSystem || isOpen(table));
}

// Buttons of the grid toolbar.
//
// The toolbar is a size container (`@container/sheets-toolbar`). Labels fold into
// their icon only inside a narrow toolbar (`@max-*` variants), so a control rendered
// anywhere else keeps its label, and the accessible name never folds.
import type { ComponentProps, ComponentType, ReactNode } from 'react';

import { Button } from '@/components/ui/button';

import { cn } from '../../utils/cn';

type IconComponent = ComponentType<{ className?: string; 'aria-hidden'?: boolean | 'true' | 'false' }>;

/**
 * When a label folds into its icon, by how much the toolbar's two groups need the room:
 * the data tools first (below 72rem), then Fields, Filters, Sort and Delete (below 58rem),
 * then New record (below 48rem), then Add row (below 44rem). Measured on the toolbar's
 * own width, so both groups keep one line from about 38rem.
 */
export type ToolbarFold = 'tools' | 'view' | 'create' | 'primary';

// Literal class names, so Tailwind sees every variant it must generate.
const FOLDED: Record<ToolbarFold, string> = {
	tools: '@max-6xl/sheets-toolbar:hidden',
	view: '@max-[58rem]/sheets-toolbar:hidden',
	create: '@max-[48rem]/sheets-toolbar:hidden',
	primary: '@max-[44rem]/sheets-toolbar:hidden',
};

/**
 * A label that folds into its button's icon on a narrow toolbar. A folded label leaves the
 * accessibility tree, so its button needs an `aria-label`.
 */
export function ToolbarLabel({ children, fold }: { children: ReactNode; fold: ToolbarFold }) {
	return <span className={FOLDED[fold]}>{children}</span>;
}

export interface ViewToggleButtonProps extends Omit<ComponentProps<typeof Button>, 'children'> {
	icon: IconComponent;
	label: string;
	/** How much the control changes the view (filters applied, sort keys, hidden fields); 0 for nothing. */
	count?: number;
	/** Word after the count, folded with the label, e.g. "hidden". */
	countLabel?: string;
}

/**
 * Fields, Filters and Sort. Quiet while they leave the view as it is; once they change
 * it they take the accent tint and show by how much, so the view's state reads at a glance.
 */
export function ViewToggleButton({ icon: Icon, label, count = 0, countLabel, className, ...props }: ViewToggleButtonProps) {
	const active = count > 0;
	return (
		<Button
			variant='ghost'
			size='sm'
			data-active={active || undefined}
			className={cn(
				'text-muted-foreground hover:text-foreground',
				active && 'bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary',
				className,
			)}
			{...props}
		>
			<Icon className='size-4' aria-hidden='true' />
			<ToolbarLabel fold='view'>{label}</ToolbarLabel>
			{active && (
				<span className='tabular-nums'>
					{count.toLocaleString()}
					{countLabel && <ToolbarLabel fold='view'>{` ${countLabel}`}</ToolbarLabel>}
				</span>
			)}
		</Button>
	);
}

export interface ToolButtonProps extends Omit<ComponentProps<typeof Button>, 'children'> {
	icon: IconComponent;
	label: string;
}

/** A quiet data tool (import, export of the view): icon and label, the label folding first. */
export function ToolButton({ icon: Icon, label, className, ...props }: ToolButtonProps) {
	return (
		// A folded label leaves the accessibility tree too, so the name is set on the button.
		<Button variant='ghost' size='sm' aria-label={label} className={cn('text-muted-foreground hover:text-foreground', className)} {...props}>
			<Icon className='size-4' aria-hidden='true' />
			<ToolbarLabel fold='tools'>{label}</ToolbarLabel>
		</Button>
	);
}

/**
 * useSheets — headless grid assembly hook.
 *
 * Computes the data/state bindings the default {@link Sheets} component renders
 * with the native TanStack DOM grid: columns, the native cell-content resolver,
 * value-commit helpers, and the draft / selection / pagination APIs. The built-in
 * {@link Sheets} component is a thin consumer of this hook.
 *
 * The STABLE headless surface is {@link UseSheetsResult}. A handful of additional
 * fields under the `_shell` group are returned only so the built-in `<Sheets>`
 * chrome (toolbar, pagination, dock) can render; they are intentionally NOT part
 * of the supported headless contract and may change.
 */
import { useCallback, useEffect, useMemo } from 'react';

import { createSheetsCell } from '../cell-model/create-sheets-cell';
import { compileSlots } from '../cell-model/cell-slots';
import { createCellTypeRegistry } from '../cell-types/cell-type-registry';
import { useSheetsContext } from '../context/sheets-context';
import { useSheetsMeta } from '../hooks/use-sheets-meta';
import type { SheetsSelection } from '../selection/selection-model';
import { useSheetsCellContent } from './assembly/use-sheets-cell-content';
import { useSheetsColumns } from './assembly/use-sheets-columns';
import { useSheetsData } from './assembly/use-sheets-data';
import { useDraftColumnMeta, useSheetsDraftActions } from './assembly/use-sheets-drafts';
import { useLoadEvents, useSheetsEmit, useViewChangeEvents } from './assembly/use-sheets-events';
import { useSheetsRows } from './assembly/use-sheets-rows';
import { useSheetsViewQuery } from './assembly/use-sheets-view-query';
import { useSheetsWrites } from './assembly/use-sheets-writes';
import type { UseSheetsInternalResult } from './assembly/use-sheets.types';
import { useFeedback } from './feedback';
import type { VisibleRowRange } from './hooks/use-infinite-grid-data';
import { useGridState } from './hooks/use-grid-state';
import type { SheetsRow } from './row-model';
import type { DataGridProps } from './sheets.types';
import { filterConditionsOf } from './view-state/view-state';

export type {
	SheetsDraftBindings,
	SheetsSelectionBindings,
	SheetsPaginationBindings,
	UseSheetsResult,
	SheetsShellBindings,
	UseSheetsInternalResult,
} from './assembly/use-sheets.types';

/**
 * Headless grid hook — returns the data/state bindings the built-in {@link Sheets}
 * component renders with the native DOM grid.
 *
 * Preconditions:
 * - You MUST render inside a `<FeedbackProvider>` (exported from this package) —
 *   the hook uses the bulk-operation feedback context and throws without it.
 *
 * NOTE: the generic `TRow` flows through {@link DataGridProps}'s row callbacks
 * (e.g. `onRowSelect`). It does not retype the cell bindings, which operate on
 * the dynamic schema-derived row shape.
 */
export function useSheets<TRow extends SheetsRow = SheetsRow>(
	props: DataGridProps<TRow>,
): UseSheetsInternalResult<TRow> {
	const {
		tableName,
		pageSize = 100,
		onRowSelect,
		onCellEdit,
		relationChipLimit,
		relationLabelMaxLength,
		infiniteScroll = false,
		cellTypes,
		cellSlots,
		onEvent,
	} = props;

	// Get feedback context for bulk operation status indicators and failed writes
	const feedback = useFeedback();
	const { clearOperationFeedback, clearWriteErrors } = feedback;

	// Observational onEvent emitter (see assembly/use-sheets-events).
	const emit = useSheetsEmit(tableName, onEvent);

	const { config, canUpload, scopeKey } = useSheetsContext();

	// Per-instance cell-type registry: consumer overrides (provider plugins, then
	// per-instance cellTypes) layered over the built-in native engine. With no consumer
	// cell types this delegates 1:1 to createSheetsCell.
	const cellRegistry = useMemo(
		() =>
			createCellTypeRegistry(
				// Compiled cell-component slots go LAST so they win over plugins + cellTypes.
				[...(config.plugins ?? []).flatMap((p) => p.cellTypes), ...(cellTypes ?? []), ...compileSlots(cellSlots)],
				{
					// Native display builtin: the SheetsCell dispatcher.
					toSheetsCell: (value, ctx) => createSheetsCell(value, ctx.metadata),
				},
			),
		[config.plugins, cellTypes, cellSlots],
	);

	const tableKey = useMemo(() => {
		if (config.databaseId) return `${config.databaseId}::${tableName}`;
		return `default::${tableName}`;
	}, [config.databaseId, tableName]);

	// Clear stale operation feedback and failed writes when switching tables
	useEffect(() => {
		clearOperationFeedback();
		clearWriteErrors();
	}, [tableName, clearOperationFeedback, clearWriteErrors]);

	// Centralized state management
	const { state: gridState, actions: gridActions } = useGridState();

	const { data: filterMeta, refetch: refetchMeta } = useSheetsMeta();

	// ============== FILTERS / SORT / SEARCH → LIST VARIABLES ==============
	const {
		columnLabel,
		view,
		effectiveWhere,
		orderByClause,
		viewSignature,
		viewQuery,
		fetchColumns,
		fetchRelations,
		savedViews,
	} = useSheetsViewQuery({ tableName, props, config, scopeKey, infiniteScroll, gridActions });

	// ============== ROWS SOURCE (infinite or paginated), CAPABILITIES, ROW IDENTITY ==============
	const {
		infiniteGridData,
		dataLoadingResult,
		serverData,
		totalCount,
		tableModel,
		fieldMetaMap,
		allRelationFields,
		hasCompletedInitialLoad,
		dataError,
		isInitialLoading,
		isFetchingRows,
		canCreate,
		canUpdate,
		canDelete,
		primaryKeyFields,
		readOnlyReason,
		getRowIdentifier,
		getRowId,
	} = useSheetsData({ tableName, pageSize, infiniteScroll, orderByClause, effectiveWhere, fetchColumns, fetchRelations, gridState });
	useLoadEvents({ dataError, hasCompletedInitialLoad, totalCount, emit });

	// ============== ROWS (server rows + drafts) ==============
	const {
		update,
		create,
		deleteRow,
		normalizedServerData,
		draftRowsTable,
		draftRows,
		hasDraftRows,
		createDraftRow,
		updateDraftCell,
		removeDraftRow,
		syncDraftRowsWithMeta,
		setDraftRowStatus,
		serverRowCount,
		combinedRows,
	} = useSheetsRows({
		tableKey,
		infiniteScroll,
		infiniteGridData,
		dataLoadingResult,
		serverData,
		totalCount,
		allRelationFields,
		hasCompletedInitialLoad,
	});

	// ============== COLUMNS ==============
	const { fieldMetaByKey, allColumnKeys, columnKeys, gridColumnKeys, columns, frozenCount, resizeColumn } = useSheetsColumns({
		tableName,
		infiniteScroll,
		infiniteGridData,
		normalizedServerData,
		combinedRows,
		fieldMetaMap,
		tableModel,
		view,
		hasDraftRows,
		gridState,
		gridActions,
	});

	// Pagination helpers
	const totalPages = Math.max(1, Math.ceil((totalCount || 0) / pageSize));
	useEffect(() => {
		gridActions.resetPageIfNeeded(totalPages);
	}, [totalPages, gridActions]);


	// Handle row selection
	useEffect(() => {
		if (!onRowSelect || !gridState.gridSelection) return;
		const selectedIndices = gridState.gridSelection.rows.toArray();
		const selected = selectedIndices.map((i: number) => combinedRows[i]).filter(Boolean);
		// The grid's rows ARE the consumer's row type, so widen SheetsRow[] -> TRow[].
		onRowSelect(selected as TRow[]);
	}, [gridState.gridSelection, combinedRows, onRowSelect]);

	// ============== CELL CONTENT ==============
	const { relationInfoByField, relationInfoObject, getSheetsCellContent } = useSheetsCellContent({
		tableName,
		tableModel,
		combinedRows,
		gridColumnKeys,
		fieldMetaMap,
		cellRegistry,
		relationChipLimit,
		relationLabelMaxLength,
		filterMeta,
		canCreate,
		canUpdate,
		primaryKeyFields,
		getRowIdentifier,
		canUpload,
		config,
	});

	// ============== DRAFT COLUMN METADATA ==============
	const { effectiveColumnOrder, metaSignature } = useDraftColumnMeta({
		tableKey,
		allColumnKeys,
		fieldMetaByKey,
		relationInfoObject,
		syncDraftRowsWithMeta,
	});

	// ============== WRITES ==============
	const { operationFeedback, deleteRows, deleteSelected, commitCells, commitCellValue, commitCellPatch, invalidateData, history } = useSheetsWrites({
		tableName,
		tableKey,
		config,
		feedback,
		emit,
		infiniteScroll,
		infiniteGridData,
		tableModel,
		combinedRows,
		fieldMetaMap,
		relationInfoByField,
		getSheetsCellContent,
		getRowIdentifier,
		primaryKeyFields,
		canUpdate,
		canDelete,
		update,
		deleteRow,
		updateDraftCell,
		removeDraftRow,
		gridState,
		gridActions,
		columnLabel,
		onCellEdit,
	});

	// ============== DRAFT ROWS: ADD + SUBMIT ==============
	const {
		handleRowAppended,
		selectedRowCount,
		isSubmittingDrafts,
		submitDraftButtonDisabled,
		submitDraftLabel,
		handleSubmitDraftRows,
		handleSubmitDraftRowForEditor,
	} = useSheetsDraftActions({
		tableKey,
		tableModel,
		canCreate,
		emit,
		infiniteScroll,
		infiniteGridData,
		combinedRows,
		serverRowCount,
		draftRows,
		draftRowsTable,
		createDraftRow,
		removeDraftRow,
		setDraftRowStatus,
		create,
		effectiveColumnOrder,
		fieldMetaByKey,
		relationInfoObject,
		metaSignature,
		gridState,
		gridActions,
		operationFeedback,
	});

	// Observational sort:change / filter:apply / search:change events.
	useViewChangeEvents({ view, effectiveWhere, emit });

	// ============== INFINITE SCROLL: onVisibleRegionChanged handler ==============
	// Translate the DOM viewport's inclusive {startIndex,endIndex} window into the
	// prefetch range the infinite source loads (clamped to the server row count).
	const handleVisibleRegionChanged = useCallback(
		(range: VisibleRowRange) => {
			if (!infiniteScroll) return;
			if (serverRowCount <= 0) return;

			const start = Math.max(0, Math.min(range.startIndex, serverRowCount - 1));
			const end = Math.max(start, Math.min(range.endIndex, serverRowCount - 1));
			infiniteGridData.onVisibleRegionChanged({ startIndex: start, endIndex: end });
		},
		[infiniteScroll, infiniteGridData, serverRowCount],
	);

	const setGridSelectionForControls = useCallback(
		(selection: SheetsSelection | null) => {
			gridActions.setGridSelection(selection ?? undefined);
		},
		[gridActions],
	);

	const filterConditionCount = useMemo(() => filterConditionsOf(view.state.filters).length, [view.state.filters]);

	// Unified, mode-aware refetch. Shared by the load-state retry path and the
	// imperative handle in the Sheets shell.
	const refetch = useCallback(() => {
		if (infiniteScroll) {
			infiniteGridData.invalidate();
		} else {
			void dataLoadingResult.contextValue.refetch?.();
		}
	}, [infiniteScroll, infiniteGridData, dataLoadingResult.contextValue]);

	// Read the table's shape (`_meta`: a new meta version builds a new model, so new columns
	// appear) and its rows again, as when the user comes back to a page left open.
	const refreshFromServer = useCallback(() => {
		void refetchMeta();
		refetch();
	}, [refetchMeta, refetch]);

	// Pagination setter that mirrors the default chrome behavior (emit page:change).
	const setPageIndex = useCallback(
		(updater: number | ((prev: number) => number)) => {
			const next = typeof updater === 'function' ? updater(gridState.pageIndex) : updater;
			gridActions.setPageIndex(next);
			emit('page:change', { pageIndex: next });
		},
		[gridActions, gridState.pageIndex, emit],
	);

	// Loaded successfully but no server rows and nothing drafted yet, with no filter or search.
	const isEmpty =
		hasCompletedInitialLoad &&
		serverRowCount === 0 &&
		draftRows.length === 0 &&
		filterConditionCount === 0 &&
		view.state.search.trim() === '';

	return {
		// -- Stable headless surface (see UseSheetsResult) --
		columns,
		rowCount: combinedRows.length,
		draft: {
			hasDrafts: hasDraftRows,
			appendRow: handleRowAppended,
			submitDrafts: handleSubmitDraftRows,
			deleteSelected,
			deleteRows,
		},
		selection: {
			gridSelection: gridState.gridSelection,
			setGridSelection: gridActions.setGridSelection,
			setActiveCell: gridActions.setActiveCell,
			moveActive: gridActions.moveActiveCell,
		},
		pagination: {
			pageIndex: gridState.pageIndex,
			pageCount: totalPages,
			setPageIndex,
		},
		isInitialLoading,
		dataError,
		hasCompletedInitialLoad,
		isEmpty,
		refetch,
		refreshFromServer,

		// -- Internal chrome bindings (not a stable API) --
		_shell: {
			combinedRows,
			columnKeys,
			totalCount,
			serverRowCount,
			draftRowCount: draftRows.length,
			infiniteScroll,
			view,
			savedViews,
			filterConditionCount,
			viewQuery,
			isFetchingRows,
			setGridSelectionForControls,
			onVisibleRegionChanged: handleVisibleRegionChanged,
			viewSignature,
			columnWidths: gridState.columnWidths,
			resizeColumn,
			frozenCount,
			rowHeightPx: view.layout.rowHeightPx,
			selectedRowCount,
			canCreate,
			canUpdate,
			canDelete,
			readOnlyReason,
			tableModel,
			getRowId,
			isSubmittingDrafts,
			submitDraftButtonDisabled,
			submitDraftLabel,
			getSheetsCellContent,
			cellRegistry,
			commitCellValue,
			commitCells,
			commitCellPatch,
			submitDraftRow: handleSubmitDraftRowForEditor,
			invalidateData,
			undo: history.undo,
			redo: history.redo,
			canUndo: history.canUndo,
			canRedo: history.canRedo,
			recordHistory: history.record,
			emit,
		},
	};
}

import { useLayoutEffect, useState } from 'react';

/**
 * The row count to show for the current view, or null until the first count for
 * that view has arrived.
 *
 * When the filter or the search changes, the data layer reports a placeholder
 * until the server answers: 0, or the count of the view before. Showing it would
 * flash "0 rows" or a wrong number. The count is ready once the view has data and
 * nothing is fetching (before its first request starts, a view has no data and is
 * not fetching either). After that, a refetch (after a save) keeps the count on screen.
 *
 * `viewKey` names what the count depends on (the table, the filter and the search),
 * so a new sort or page does not hide it.
 */
export function useViewRowCount(total: number, viewKey: string, ready: boolean): number | null {
	const [countedKey, setCountedKey] = useState<string | null>(null);
	// A layout effect: the count appears in the same frame the fetch settles.
	useLayoutEffect(() => {
		if (ready && countedKey !== viewKey) setCountedKey(viewKey);
	}, [ready, viewKey, countedKey]);
	return countedKey === viewKey ? total : null;
}

/**
 * The list variables for a view state: the filter (conditions and search,
 * combined with `and`) and the sort, built only from the table model.
 */
import type { SortSpec, TableKey, TableModel } from '@constructive-io/data';

import { filterOperatorOptions, findOperatorOption } from '../filter-operators';
import { encodeFilterValue, type FilterValueResult } from '../filters/filter-value';
import { relationConditionWhere } from '../filters/relation-filters';
import { searchPlanOf, searchWhere } from './search-plan';
import type { SheetsColumnCondition, SheetsFilterNode, SheetsViewState } from './view-state.types';

type Where = Record<string, unknown>;

/** A part of the filter and the conditions in it, so a part left out takes its conditions with it. */
interface Part {
	where: Where;
	ids: readonly string[];
}

const NOT_COMBINED = 'This table cannot combine this condition with the others, so it is not applied.';
const NOT_COMBINED_WITH_SEARCH = 'This table cannot combine this condition with the search, so it is not applied.';

/** Whether a condition is part of the filter, and why not. */
export type ConditionStatus =
	| { status: 'applied' }
	| { status: 'incomplete' }
	| { status: 'invalid'; message: string };

export interface ViewQuery {
	/** The filter input value, or undefined for no filter. */
	where: Where | undefined;
	/** The sort, first key first, or undefined for none. */
	orderBy: SortSpec[] | undefined;
	/** Status of every condition, by condition id. */
	conditions: ReadonlyMap<string, ConditionStatus>;
	/** Number of conditions in the filter. */
	appliedCount: number;
	/** Related tables whose models some condition still needs. */
	waitingFor: readonly TableKey[];
}

export type RelatedModelLookup = (key: TableKey) => TableModel | null;

interface BuildContext {
	model: TableModel;
	related: RelatedModelLookup;
	conditions: Map<string, ConditionStatus>;
	waitingFor: Set<TableKey>;
}

function columnConditionResult(model: TableModel, condition: SheetsColumnCondition): { result: FilterValueResult; field: string | null } {
	const column = model.columns.find((candidate) => candidate.name === condition.column);
	if (!column?.filter) return { result: { status: 'invalid', message: 'This column cannot be filtered.' }, field: null };
	const option = findOperatorOption(filterOperatorOptions(column), condition.operator, condition.value);
	if (!option) return { result: { status: 'invalid', message: 'This condition is not available for the column.' }, field: null };
	return { result: encodeFilterValue(option.control, condition.value, option.fixedValue), field: column.filter.field };
}

function record(ctx: BuildContext, id: string, result: FilterValueResult): void {
	ctx.conditions.set(id, result.status === 'ready' ? { status: 'applied' } : result);
}

/** Mark the conditions of parts the filter leaves out, so none of them counts as applied. */
function leaveOut(ctx: BuildContext, parts: readonly Part[], message: string): void {
	for (const part of parts) for (const id of part.ids) ctx.conditions.set(id, { status: 'invalid', message });
}

/** Combine filter parts with a logical operator the filter input has, or null when they cannot be combined. */
function combine(model: TableModel, logic: 'and' | 'or', parts: readonly Part[]): Part | null {
	if (parts.length === 0) return null;
	if (parts.length === 1) return parts[0]!;
	const ids = parts.flatMap((part) => part.ids);
	if (model.operations.list?.logicalOperators.includes(logic)) return { where: { [logic]: parts.map((part) => part.where) }, ids };
	// Without an `and` field the parts still combine as one object when their fields differ.
	if (logic === 'and') {
		const merged: Where = {};
		for (const part of parts) {
			for (const key of Object.keys(part.where)) if (key in merged) return null;
			Object.assign(merged, part.where);
		}
		return { where: merged, ids };
	}
	return null;
}

function nodePart(ctx: BuildContext, node: SheetsFilterNode): Part | null {
	if (node.kind === 'group') {
		const parts = node.children.map((child) => nodePart(ctx, child)).filter((part): part is Part => part !== null);
		const combined = combine(ctx.model, node.logic, parts);
		if (!combined) leaveOut(ctx, parts, NOT_COMBINED);
		return combined;
	}
	if (node.kind === 'column') {
		const { result, field } = columnConditionResult(ctx.model, node);
		record(ctx, node.id, result);
		return result.status === 'ready' && field ? { where: { [field]: { [node.operator]: result.value } }, ids: [node.id] } : null;
	}
	const relation = ctx.model.relations.find((candidate) => candidate.fieldName === node.relation);
	if (!relation) {
		record(ctx, node.id, { status: 'invalid', message: 'This relation no longer exists.' });
		return null;
	}
	const related = relation.targetKey ? ctx.related(relation.targetKey) : null;
	const { result, waitingFor } = relationConditionWhere(relation, node, related);
	if (waitingFor) ctx.waitingFor.add(waitingFor);
	record(ctx, node.id, result);
	return result.status === 'ready' ? { where: result.value as Where, ids: [node.id] } : null;
}

/**
 * The list variables for a state the model supports (see
 * `validateSheetsViewState`). Conditions that are incomplete or invalid, or
 * that the filter input cannot combine, are left out of the filter and
 * reported in `conditions`, so `appliedCount` counts only what filters.
 */
export function buildViewQuery(state: SheetsViewState, model: TableModel, related: RelatedModelLookup = () => null): ViewQuery {
	const ctx: BuildContext = { model, related, conditions: new Map(), waitingFor: new Set() };
	const filter = nodePart(ctx, state.filters);
	const plan = searchPlanOf(model);
	const searchText = plan ? searchWhere(plan, state.search) : null;
	const search: Part | null = searchText ? { where: searchText, ids: [] } : null;
	let combined = combine(model, 'and', [filter, search].filter((part): part is Part => part !== null));
	if (!combined && filter && search) {
		// The search the user typed stays; the conditions it cannot be combined with say so.
		leaveOut(ctx, [filter], NOT_COMBINED_WITH_SEARCH);
		combined = search;
	}
	const where = combined?.where;
	const orderBy = state.sort.length > 0 ? state.sort.map((key) => ({ field: key.column, direction: key.direction })) : undefined;
	let appliedCount = 0;
	for (const status of ctx.conditions.values()) if (status.status === 'applied') appliedCount += 1;
	return { where, orderBy, conditions: ctx.conditions, appliedCount, waitingFor: [...ctx.waitingFor] };
}

/**
 * What the toolbar search box searches, from the table model.
 *
 * A table with a combined search field searches through it. Otherwise the
 * search matches every text column that really has a case-insensitive contains
 * operator, combined with `or`; without `or` it matches the first such column.
 */
import type { ColumnModel, TableModel } from '@constructive-io/data';

const CONTAINS = 'includesInsensitive';
const SEARCH_INDEX_KINDS: ReadonlySet<string> = new Set(['fulltext', 'vector']);

export type SearchPlan =
	| {
			mode: 'unified';
			/** Filter input field that takes the search text. */
			field: string;
			/** Columns the table's search covers, when the server names them. */
			columns: readonly string[];
	  }
	| {
			mode: 'columns';
			/** Columns matched with a case-insensitive contains, in table order. */
			columns: readonly { name: string; field: string }[];
	  };

function containsField(column: ColumnModel): string | null {
	if (!column.readable || column.value.kind !== 'text' || column.value.isArray || !column.filter) return null;
	const operator = column.filter.operators.find((candidate) => candidate.name === CONTAINS);
	return operator && operator.input.shape === 'scalar' && !operator.input.isList ? column.filter.field : null;
}

/** The search plan of a table, or null when nothing can be searched. */
export function searchPlanOf(model: TableModel | null): SearchPlan | null {
	if (!model?.operations.list?.filter) return null;
	if (model.search?.unifiedSearchField) {
		// A search index column (full-text or vector) is how the search works, not text a person reads.
		const named = model.search.columns
			.map((column) => column.name)
			.filter((name) => {
				const column = model.columns.find((candidate) => candidate.name === name);
				return Boolean(column) && !SEARCH_INDEX_KINDS.has(column!.value.kind);
			});
		return { mode: 'unified', field: model.search.unifiedSearchField, columns: named };
	}
	const columns = model.columns.flatMap((column) => {
		const field = containsField(column);
		return field ? [{ name: column.name, field }] : [];
	});
	if (columns.length === 0) return null;
	const canOr = model.operations.list.logicalOperators.includes('or');
	return { mode: 'columns', columns: canOr ? columns : columns.slice(0, 1) };
}

/** The columns a plan searches, by name. Empty for a combined search the server does not describe. */
export function searchedColumns(plan: SearchPlan): readonly string[] {
	return plan.mode === 'unified' ? plan.columns : plan.columns.map((column) => column.name);
}

/** The filter for search text, or null for empty text. */
export function searchWhere(plan: SearchPlan, text: string): Record<string, unknown> | null {
	const term = text.trim();
	if (term === '') return null;
	if (plan.mode === 'unified') return { [plan.field]: term };
	const parts = plan.columns.map((column) => ({ [column.field]: { [CONTAINS]: term } }));
	return parts.length === 1 ? parts[0]! : { or: parts };
}

/**
 * The grid's filter, sort, search and column layout: uncontrolled by default,
 * or owned by the host through the `filters` / `sort` / `search` / `columns`
 * props. Every state is
 * validated against the table model before it builds list variables. Text
 * controls commit after a pause in typing (see `useCommittedText`), so every
 * state change here is a settled one and applies at once.
 *
 * Related tables' models (for "linked record contains") load only while the
 * filter builder is open or such a condition exists.
 */
import { useCallback, useMemo, useRef, useState } from 'react';

import type { SortSpec, TableKey, TableModel } from '@constructive-io/data';

import { useTableModels } from '../../hooks/use-table-model';
import { gridColumnKeys } from '../../relations/relation-columns';
import { createColumnLayout } from '../columns/column-layout';
import { useColumnLayout, type ColumnLayoutBindings } from '../columns/use-column-layout';
import { filterFieldsOf, newCondition } from '../filters/filter-fields';
import { buildViewQuery, type ConditionStatus } from './build-view-query';
import { searchPlanOf, type SearchPlan } from './search-plan';
import { validateSheetsViewState } from './validate-view-state';
import { createFilterGroup, cycleSort, filterConditionsOf } from './view-state';
import {
	SHEETS_VIEW_STATE_VERSION,
	type SheetsColumnLayout,
	type SheetsFilterGroup,
	type SheetsSortKey,
	type SheetsViewState,
	type SheetsViewStateDrop,
} from './view-state.types';

const NO_SORT: readonly SheetsSortKey[] = [];

export interface SheetsViewProps {
	/** Controlled filters. Omit to let the grid own them. */
	filters?: SheetsFilterGroup;
	onFiltersChange?: (filters: SheetsFilterGroup) => void;
	/** Controlled sort, first key first. Omit to let the grid own it. */
	sort?: readonly SheetsSortKey[];
	onSortChange?: (sort: readonly SheetsSortKey[]) => void;
	/** Controlled search text. Omit to let the grid own it. */
	search?: string;
	onSearchChange?: (search: string) => void;
	/** Controlled column layout (order, hidden, frozen count, widths, row height). Omit to let the grid own it. */
	columns?: SheetsColumnLayout;
	onColumnsChange?: (columns: SheetsColumnLayout) => void;
}

export interface UseSheetsViewOptions extends SheetsViewProps {
	model: TableModel | null;
	/** Column or relation title, for messages and controls. */
	columnLabel: (name: string) => string;
}

/** The view bindings the toolbar, the header and the commands use. */
export interface SheetsViewBindings {
	/** The state in use, valid for the current model. */
	state: SheetsViewState;
	model: TableModel | null;
	/** Parts of the given state the model does not support. */
	dropped: readonly SheetsViewStateDrop[];
	/** Status of every condition, by condition id. */
	conditions: ReadonlyMap<string, ConditionStatus>;
	/** Conditions that are part of the filter. */
	appliedCount: number;
	/** What the search box searches, or null when the table cannot be searched. */
	searchPlan: SearchPlan | null;
	columnLabel: (name: string) => string;
	/** A related table's model, once loaded. */
	relatedModel: (key: TableKey) => TableModel | null;
	setFilters: (filters: SheetsFilterGroup) => void;
	clearFilters: () => void;
	setSort: (sort: readonly SheetsSortKey[]) => void;
	/** Header click: cycle one column, or with `additive` add it to the sort. */
	toggleSort: (column: string, additive: boolean) => void;
	setSearch: (search: string) => void;
	setColumns: (columns: SheetsColumnLayout) => void;
	/** Replace filters, sort, search and layout at once (a saved view). */
	applyState: (state: SheetsViewState) => void;
	/** Open the filters with a new condition on a column or relation; false when no condition could be added. */
	filterBy: (column: string) => boolean;
	/** Column layout and its actions. */
	layout: ColumnLayoutBindings;
	/** Why a grid column cannot be sorted, or null when it can. Empty text for a column the grid adds itself. */
	unsortableReason: (column: string) => string | null;
	filtersOpen: boolean;
	setFiltersOpen: (open: boolean) => void;
	sortOpen: boolean;
	setSortOpen: (open: boolean) => void;
	/** Attach to the search input so `focusSearch` can reach it. */
	searchInputRef: React.MutableRefObject<HTMLInputElement | null>;
	/** Focus the search box; false when there is none. */
	focusSearch: () => boolean;
}

export interface UseSheetsViewResult {
	view: SheetsViewBindings;
	/** List filter. */
	where: Record<string, unknown> | undefined;
	/** List sort. */
	orderBy: SortSpec[] | undefined;
	/** Changes exactly when the rows the grid shows can change. */
	querySignature: string;
}

function unsortableReasonFor(model: TableModel | null, column: string): string | null {
	if (!model) return 'Sorting is available once the table has loaded.';
	const columnModel = model.columns.find((candidate) => candidate.name === column);
	if (columnModel?.sort) return null;
	if (columnModel) {
		const issue = model.issues.find((candidate) => candidate.code === 'COLUMN_UNSORTABLE' && candidate.target === column);
		return issue?.message ?? 'This column cannot be sorted.';
	}
	if (model.relations.some((relation) => relation.fieldName === column)) return 'Linked records cannot be sorted.';
	// A column the grid adds itself (the draft actions) is not sortable and needs no explanation.
	return '';
}

/** Related tables the filters need: every relation target while the builder is open, else the targets of label conditions. */
function relatedTargets(model: TableModel | null, filters: SheetsFilterGroup, builderOpen: boolean): string[] {
	if (!model) return [];
	const filterable = model.relations.filter((relation) => relation.targetKey && relation.filter?.recordFilterType);
	if (builderOpen) return [...new Set(filterable.map((relation) => relation.targetKey!))];
	const named = new Set(
		filterConditionsOf(filters).flatMap((condition) =>
			condition.kind === 'relation' && condition.test === 'labelContains' ? [condition.relation] : [],
		),
	);
	return [...new Set(filterable.filter((relation) => named.has(relation.fieldName)).map((relation) => relation.targetKey!))];
}

export function useSheetsView(options: UseSheetsViewOptions): UseSheetsViewResult {
	const { model, columnLabel } = options;

	const [ownFilters, setOwnFilters] = useState<SheetsFilterGroup>(() => createFilterGroup());
	const [ownSort, setOwnSort] = useState<readonly SheetsSortKey[]>(NO_SORT);
	const [ownSearch, setOwnSearch] = useState('');
	const [ownColumns, setOwnColumns] = useState<SheetsColumnLayout>(createColumnLayout);
	const [filtersOpen, setFiltersOpen] = useState(false);
	const [sortOpen, setSortOpen] = useState(false);
	const searchInputRef = useRef<HTMLInputElement | null>(null);

	const filters = options.filters ?? ownFilters;
	const sort = options.sort ?? ownSort;
	const search = options.search ?? ownSearch;
	const columns = options.columns ?? ownColumns;
	const available = useMemo(() => (model ? gridColumnKeys(model) : []), [model]);

	const { models: relatedModels } = useTableModels(relatedTargets(model, filters, filtersOpen));
	const relatedModel = useCallback((key: TableKey) => relatedModels.get(key) ?? null, [relatedModels]);

	// Callbacks are latched so a host passing inline functions does not churn the setters.
	const callbacks = useRef(options);
	callbacks.current = options;

	const { state, dropped } = useMemo(() => {
		const raw: SheetsViewState = { version: SHEETS_VIEW_STATE_VERSION, filters, sort, search, columns };
		return model ? validateSheetsViewState(raw, model, { label: columnLabel }) : { state: raw, dropped: [] };
	}, [filters, sort, search, columns, model, columnLabel]);

	const setFilters = useCallback((next: SheetsFilterGroup) => {
		if (callbacks.current.filters === undefined) setOwnFilters(next);
		callbacks.current.onFiltersChange?.(next);
	}, []);
	const setSort = useCallback((next: readonly SheetsSortKey[]) => {
		if (callbacks.current.sort === undefined) setOwnSort(next);
		callbacks.current.onSortChange?.(next);
	}, []);
	const setSearch = useCallback((next: string) => {
		if (callbacks.current.search === undefined) setOwnSearch(next);
		callbacks.current.onSearchChange?.(next);
	}, []);
	const setColumns = useCallback((next: SheetsColumnLayout) => {
		if (callbacks.current.columns === undefined) setOwnColumns(next);
		callbacks.current.onColumnsChange?.(next);
	}, []);
	const applyState = useCallback(
		(next: SheetsViewState) => {
			setFilters(next.filters);
			setSort(next.sort);
			setSearch(next.search);
			setColumns(next.columns);
		},
		[setFilters, setSort, setSearch, setColumns],
	);

	// Header clicks build on the state in use, so a dropped sort key is not revived.
	const stateRef = useRef(state);
	stateRef.current = state;
	const toggleSort = useCallback(
		(column: string, additive: boolean) => setSort(cycleSort(stateRef.current.sort, column, additive)),
		[setSort],
	);
	const clearFilters = useCallback(() => setFilters(createFilterGroup()), [setFilters]);
	const filterBy = useCallback(
		(column: string) => {
			const field = filterFieldsOf(model, columnLabel).find((candidate) => candidate.name === column);
			const related = field?.kind === 'relation' && field.relation.targetKey ? relatedModels.get(field.relation.targetKey) ?? null : null;
			const condition = field ? newCondition(field, related) : null;
			if (condition) {
				const current = stateRef.current.filters;
				setFilters({ ...current, children: [...current.children, condition] });
			}
			setFiltersOpen(true);
			return condition !== null;
		},
		[model, columnLabel, relatedModels, setFilters],
	);
	const layout = useColumnLayout({ layout: state.columns, setLayout: setColumns, available });

	const query = useMemo(
		() => (model ? buildViewQuery(state, model, relatedModel) : null),
		[state, model, relatedModel],
	);
	// Keyed by content, so an unchanged filter keeps its identity across renders.
	const whereKey = JSON.stringify(query?.where ?? null);
	const where = useMemo(() => (JSON.parse(whereKey) as Record<string, unknown> | null) ?? undefined, [whereKey]);
	const orderByKey = JSON.stringify(query?.orderBy ?? null);
	const orderBy = useMemo(() => (JSON.parse(orderByKey) as SortSpec[] | null) ?? undefined, [orderByKey]);

	const unsortableReason = useCallback((column: string) => unsortableReasonFor(model, column), [model]);
	const focusSearch = useCallback(() => {
		const input = searchInputRef.current;
		if (!input) return false;
		input.focus();
		input.select();
		return true;
	}, []);

	const view = useMemo<SheetsViewBindings>(
		() => ({
			state,
			model,
			dropped,
			conditions: query?.conditions ?? new Map(),
			appliedCount: query?.appliedCount ?? 0,
			searchPlan: searchPlanOf(model),
			columnLabel,
			relatedModel,
			setFilters,
			clearFilters,
			setSort,
			toggleSort,
			setSearch,
			setColumns,
			applyState,
			filterBy,
			layout,
			unsortableReason,
			filtersOpen,
			setFiltersOpen,
			sortOpen,
			setSortOpen,
			searchInputRef,
			focusSearch,
		}),
		[
			state,
			model,
			dropped,
			query,
			columnLabel,
			relatedModel,
			setFilters,
			clearFilters,
			setSort,
			toggleSort,
			setSearch,
			setColumns,
			applyState,
			filterBy,
			layout,
			unsortableReason,
			filtersOpen,
			sortOpen,
			focusSearch,
		],
	);

	return { view, where, orderBy, querySignature: `${whereKey}|${orderByKey}` };
}

/**
 * Check a stored view state against the current table model.
 *
 * Pure: returns a state that only names columns, operators, options and
 * relations the model has, and a list of what it dropped and why. Use it to load
 * a saved view; the grid also runs it on every state it receives, so a stale
 * state never reaches the server. A version 1 state (before the column layout)
 * loads with the default layout.
 */
import type { ColumnModel, TableModel } from '@constructive-io/data';

import { gridColumnKeys } from '../../relations/relation-columns';
import { ROW_HEIGHTS, clampColumnWidth, createColumnLayout } from '../columns/column-layout';
import { filterOperatorLabel, filterOperatorOptions, findOperatorOption, humanizeOperatorName } from '../filter-operators';
import { relationFilterTests } from '../filters/relation-filters';
import { searchPlanOf } from './search-plan';
import { createFilterNodeId } from './view-state';
import {
	SHEETS_VIEW_STATE_VERSION,
	type SheetsColumnCondition,
	type SheetsColumnLayout,
	type SheetsRowHeight,
	type SheetsFilterGroup,
	type SheetsFilterNode,
	type SheetsFilterValue,
	type SheetsRelationCondition,
	type SheetsSortKey,
	type SheetsViewState,
	type SheetsViewStateDrop,
	type SheetsViewStateValidation,
} from './view-state.types';

type UnknownRecord = Record<string, unknown>;

const isRecord = (value: unknown): value is UnknownRecord => Boolean(value) && typeof value === 'object' && !Array.isArray(value);

interface Context {
	model: TableModel;
	dropped: SheetsViewStateDrop[];
	ids: Set<string>;
	label: (name: string) => string;
}

function uniqueId(ctx: Context, candidate: unknown): string {
	let id = typeof candidate === 'string' && candidate !== '' ? candidate : createFilterNodeId();
	while (ctx.ids.has(id)) id = createFilterNodeId();
	ctx.ids.add(id);
	return id;
}

function drop(ctx: Context, entry: SheetsViewStateDrop): null {
	ctx.dropped.push(entry);
	return null;
}

function parseValue(value: unknown): SheetsFilterValue | undefined {
	if (value === null) return null;
	if (typeof value === 'string' || typeof value === 'boolean') return value;
	if (Array.isArray(value)) return value.every((item) => typeof item === 'string') ? (value as string[]) : undefined;
	if (isRecord(value)) {
		return Object.values(value).every((item) => typeof item === 'string') ? (value as Record<string, string>) : undefined;
	}
	return undefined;
}

/** Keep only the option values the column still has; null when none remain. */
function keepKnownOptions(
	ctx: Context,
	column: ColumnModel,
	options: readonly { value: string }[],
	value: SheetsFilterValue,
): SheetsFilterValue | null {
	const known = new Set(options.map((option) => option.value));
	const name = ctx.label(column.name);
	if (typeof value === 'string') {
		if (value === '' || known.has(value)) return value;
		return drop(ctx, {
			part: 'filters',
			target: column.name,
			reason: 'unknown-option',
			message: `A filter on "${name}" was removed because "${value}" is no longer one of its options.`,
		});
	}
	if (Array.isArray(value)) {
		const kept = value.filter((item) => known.has(item));
		const missing = value.filter((item) => !known.has(item));
		if (missing.length === 0) return value;
		ctx.dropped.push({
			part: 'filters',
			target: column.name,
			reason: 'unknown-option',
			message:
				kept.length > 0
					? `A filter on "${name}" no longer matches ${missing.map((item) => `"${item}"`).join(', ')}: those options were removed.`
					: `A filter on "${name}" was removed because none of its options exist any more.`,
		});
		return kept.length > 0 ? kept : null;
	}
	return value;
}

function parseColumnCondition(ctx: Context, input: UnknownRecord): SheetsColumnCondition | null {
	const name = typeof input.column === 'string' ? input.column : null;
	const operator = typeof input.operator === 'string' ? input.operator : null;
	const value = parseValue(input.value);
	if (!name || !operator || value === undefined) {
		return drop(ctx, { part: 'filters', target: name, reason: 'invalid-shape', message: 'A filter condition could not be read and was removed.' });
	}
	const column = ctx.model.columns.find((candidate) => candidate.name === name);
	if (!column) {
		return drop(ctx, {
			part: 'filters',
			target: name,
			reason: 'unknown-column',
			message: `A filter on "${ctx.label(name)}" was removed because the column no longer exists.`,
		});
	}
	if (!column.readable || !column.filter) {
		return drop(ctx, {
			part: 'filters',
			target: name,
			reason: 'column-not-filterable',
			message: `A filter on "${ctx.label(name)}" was removed because the column can no longer be filtered.`,
		});
	}
	const option = findOperatorOption(filterOperatorOptions(column), operator, value);
	if (!option || option.control.kind === 'unsupported') {
		const operatorName = column.filter.operators.some((candidate) => candidate.name === operator)
			? filterOperatorLabel(column, operator)
			: humanizeOperatorName(operator);
		return drop(ctx, {
			part: 'filters',
			target: name,
			reason: 'unknown-operator',
			message: `A filter on "${ctx.label(name)}" was removed because "${operatorName}" is no longer available for it.`,
		});
	}
	const control = option.control.kind === 'multi' ? option.control.item : option.control;
	const kept = control.kind === 'choice' ? keepKnownOptions(ctx, column, control.options, value) : value;
	if (kept === null && value !== null) return null;
	return { kind: 'column', id: uniqueId(ctx, input.id), column: name, operator, value: kept };
}

function parseRelationCondition(ctx: Context, input: UnknownRecord): SheetsRelationCondition | null {
	const name = typeof input.relation === 'string' ? input.relation : null;
	const test = input.test === 'any' || input.test === 'none' || input.test === 'labelContains' ? input.test : null;
	const value = input.value === null || input.value === undefined ? null : typeof input.value === 'string' ? input.value : undefined;
	if (!name || !test || value === undefined) {
		return drop(ctx, { part: 'filters', target: name, reason: 'invalid-shape', message: 'A filter condition could not be read and was removed.' });
	}
	const relation = ctx.model.relations.find((candidate) => candidate.fieldName === name);
	if (!relation) {
		return drop(ctx, {
			part: 'filters',
			target: name,
			reason: 'unknown-relation',
			message: `A filter on "${ctx.label(name)}" was removed because the linked field no longer exists.`,
		});
	}
	// The label test also needs the related model, which the grid checks when it builds the filter.
	const available = relationFilterTests(relation, null).find((entry) => entry.test === test);
	const unavailable = test === 'labelContains' ? !relation.filter?.recordFilterType : Boolean(available?.reason);
	if (unavailable) {
		return drop(ctx, {
			part: 'filters',
			target: name,
			reason: 'relation-test-unavailable',
			message: `A filter on "${ctx.label(name)}" was removed because that test is no longer available for it.`,
		});
	}
	return { kind: 'relation', id: uniqueId(ctx, input.id), relation: name, test, value: test === 'labelContains' ? value ?? '' : null };
}

function parseGroup(ctx: Context, input: unknown, root: boolean): SheetsFilterGroup | null {
	if (!isRecord(input) || input.kind !== 'group' || !Array.isArray(input.children)) {
		if (!root || input !== undefined) {
			drop(ctx, { part: 'filters', target: null, reason: 'invalid-shape', message: 'A group of filters could not be read and was removed.' });
		}
		return null;
	}
	const logic = input.logic === 'or' ? 'or' : 'and';
	const children = input.children
		.map((child): SheetsFilterNode | null => {
			if (!isRecord(child)) return drop(ctx, { part: 'filters', target: null, reason: 'invalid-shape', message: 'A filter condition could not be read and was removed.' });
			if (child.kind === 'group') return parseGroup(ctx, child, false);
			if (child.kind === 'relation') return parseRelationCondition(ctx, child);
			return parseColumnCondition(ctx, child);
		})
		.filter((child): child is SheetsFilterNode => child !== null);
	const operators = ctx.model.operations.list?.logicalOperators ?? [];
	if (children.length > 1 && logic === 'or' && !operators.includes('or')) {
		drop(ctx, {
			part: 'filters',
			target: null,
			reason: 'invalid-shape',
			message: 'A group matching any of its conditions was removed because this table cannot combine filters that way.',
		});
		return null;
	}
	return { kind: 'group', id: uniqueId(ctx, input.id), logic, children };
}

function parseSort(ctx: Context, input: unknown): SheetsSortKey[] {
	if (input === undefined) return [];
	if (!Array.isArray(input)) {
		drop(ctx, { part: 'sort', target: null, reason: 'invalid-shape', message: 'The sort could not be read and was removed.' });
		return [];
	}
	const keys: SheetsSortKey[] = [];
	for (const entry of input) {
		const name = isRecord(entry) && typeof entry.column === 'string' ? entry.column : null;
		const direction = isRecord(entry) && (entry.direction === 'asc' || entry.direction === 'desc') ? entry.direction : null;
		if (!name || !direction) {
			drop(ctx, { part: 'sort', target: name, reason: 'invalid-shape', message: 'A sort could not be read and was removed.' });
			continue;
		}
		const column = ctx.model.columns.find((candidate) => candidate.name === name);
		if (!column) {
			drop(ctx, { part: 'sort', target: name, reason: 'unknown-column', message: `The sort by "${ctx.label(name)}" was removed because the column no longer exists.` });
			continue;
		}
		if (!column.sort) {
			drop(ctx, { part: 'sort', target: name, reason: 'column-not-sortable', message: `The sort by "${ctx.label(name)}" was removed because the column can no longer be sorted.` });
			continue;
		}
		if (keys.some((key) => key.column === name)) {
			drop(ctx, { part: 'sort', target: name, reason: 'duplicate-sort', message: `A second sort by "${ctx.label(name)}" was removed.` });
			continue;
		}
		keys.push({ column: name, direction });
	}
	return keys;
}

function parseSearch(ctx: Context, input: unknown): string {
	if (input === undefined || input === null) return '';
	if (typeof input !== 'string') {
		drop(ctx, { part: 'search', target: null, reason: 'invalid-shape', message: 'The search could not be read and was removed.' });
		return '';
	}
	if (input.trim() !== '' && !searchPlanOf(ctx.model)) {
		drop(ctx, { part: 'search', target: null, reason: 'search-unavailable', message: 'The search was removed because this table cannot be searched.' });
		return '';
	}
	return input;
}

/** Keep the keys the grid has, reporting each missing key once. */
function knownKeys(ctx: Context, input: unknown, available: ReadonlySet<string>, reported: Set<string>): string[] {
	if (!Array.isArray(input)) return [];
	const keys: string[] = [];
	for (const entry of input) {
		if (typeof entry !== 'string' || keys.includes(entry)) continue;
		if (available.has(entry)) {
			keys.push(entry);
			continue;
		}
		if (reported.has(entry)) continue;
		reported.add(entry);
		drop(ctx, {
			part: 'columns',
			target: entry,
			reason: 'unknown-column',
			message: `"${ctx.label(entry)}" was removed from the field layout because the column no longer exists.`,
		});
	}
	return keys;
}

function parseColumns(ctx: Context, input: unknown): SheetsColumnLayout {
	const defaults = createColumnLayout();
	if (input === undefined) return defaults;
	if (!isRecord(input)) {
		drop(ctx, { part: 'columns', target: null, reason: 'invalid-shape', message: 'The field layout could not be read and was reset.' });
		return defaults;
	}
	const available = new Set(gridColumnKeys(ctx.model));
	const reported = new Set<string>();
	const order = knownKeys(ctx, input.order, available, reported);
	const hidden = knownKeys(ctx, input.hidden, available, reported);
	const widths: Record<string, number> = {};
	if (isRecord(input.widths)) {
		for (const [key, width] of Object.entries(input.widths)) {
			if (typeof width !== 'number' || !Number.isFinite(width)) continue;
			if (available.has(key)) widths[key] = clampColumnWidth(width);
			else knownKeys(ctx, [key], available, reported);
		}
	}
	const frozen = input.frozenCount;
	const frozenCount = typeof frozen === 'number' && Number.isInteger(frozen) && frozen >= 0 ? frozen : defaults.frozenCount;
	const rowHeight = ROW_HEIGHTS.includes(input.rowHeight as SheetsRowHeight) ? (input.rowHeight as SheetsRowHeight) : defaults.rowHeight;
	if ((input.frozenCount !== undefined && frozenCount !== frozen) || (input.rowHeight !== undefined && rowHeight !== input.rowHeight)) {
		drop(ctx, { part: 'columns', target: null, reason: 'invalid-shape', message: 'Part of the field layout could not be read and was reset.' });
	}
	// At least one column always shows.
	const shown = [...available].filter((key) => !hidden.includes(key));
	return { order, hidden: shown.length > 0 ? hidden : hidden.slice(1), frozenCount, widths, rowHeight };
}

export interface ValidateSheetsViewStateOptions {
	/** Column or relation title for messages; defaults to the field name. */
	label?: (name: string) => string;
}

/**
 * A state the model supports, from any stored value. Unknown columns,
 * operators, options and relations are dropped and reported; an unreadable
 * value becomes the empty state.
 */
export function validateSheetsViewState(
	input: unknown,
	model: TableModel,
	options: ValidateSheetsViewStateOptions = {},
): SheetsViewStateValidation {
	const ctx: Context = { model, dropped: [], ids: new Set(), label: options.label ?? ((name) => name) };
	const source = isRecord(input) ? input : {};
	if (input !== undefined && input !== null && !isRecord(input)) {
		drop(ctx, { part: 'filters', target: null, reason: 'invalid-shape', message: 'The saved view could not be read and was reset.' });
	}
	const filters = parseGroup(ctx, source.filters, true) ?? { kind: 'group', id: uniqueId(ctx, null), logic: 'and', children: [] };
	const state: SheetsViewState = {
		version: SHEETS_VIEW_STATE_VERSION,
		filters,
		sort: parseSort(ctx, source.sort),
		search: parseSearch(ctx, source.search),
		// Version 1 had no layout: it loads with the default one.
		columns: parseColumns(ctx, source.columns),
	};
	return { state, dropped: ctx.dropped };
}

import type { GridViewCommandTarget } from '../../commands/context';
import { filterFieldsOf } from '../filters/filter-fields';
import type { SavedViewsBindings } from '../views/use-saved-views';
import type { SheetsViewBindings } from './use-sheets-view';
import { filterConditionsOf } from './view-state';

function isFilterable(view: SheetsViewBindings, colKey: string): boolean {
	return filterFieldsOf(view.model, view.columnLabel).some((field) => field.name === colKey);
}

/**
 * The view actions the grid commands run, over the latest view and saved-view
 * bindings. The getters are read on every access, so the target can be created
 * once. `hasToolbar` is false while a host toolbar slot replaces the built-in
 * one, so the commands that open its popovers do not claim their keys.
 */
export function createViewCommandTarget(
	getView: () => SheetsViewBindings,
	hasToolbar: () => boolean,
	getSavedViews: () => SavedViewsBindings,
): GridViewCommandTarget {
	return {
		// A host toolbar slot may leave out the search box; then Mod+F stays the browser's find.
		get canSearch() {
			const view = getView();
			return view.searchPlan !== null && view.searchInputRef.current !== null;
		},
		get hasSearch() {
			return getView().state.search.trim() !== '';
		},
		get canFilter() {
			const view = getView();
			return hasToolbar() && filterFieldsOf(view.model, view.columnLabel).length > 0;
		},
		get hasFilters() {
			return filterConditionsOf(getView().state.filters).length > 0;
		},
		get canSortAny() {
			return hasToolbar() && (getView().model?.columns.some((column) => column.sort) ?? false);
		},
		get hasSort() {
			return getView().state.sort.length > 0;
		},
		canSort: (colKey) => getView().unsortableReason(colKey) === null,
		focusSearch: () => getView().focusSearch(),
		clearSearch: () => getView().setSearch(''),
		openFilters: () => getView().setFiltersOpen(true),
		clearFilters: () => getView().clearFilters(),
		openSort: () => getView().setSortOpen(true),
		clearSort: () => getView().setSort([]),
		sortBy: (colKey, direction) => getView().setSort([{ column: colKey, direction }]),

		canFilterBy: (colKey) => hasToolbar() && isFilterable(getView(), colKey),
		filterBy: (colKey) => {
			getView().filterBy(colKey);
		},
		canHide: (colKey) => {
			const { layout } = getView();
			return layout.visibleKeys.includes(colKey) && layout.hideReason(colKey) === null;
		},
		hide: (colKey) => getView().layout.setHidden(colKey, true),
		canMove: (colKey, step) => {
			const { visibleKeys } = getView().layout;
			const at = visibleKeys.indexOf(colKey);
			return at !== -1 && visibleKeys[at + step] !== undefined;
		},
		move: (colKey, step) => {
			getView().layout.moveStep(colKey, step);
		},
		get frozenCount() {
			return getView().layout.frozenCount;
		},
		freezeUpTo: (colKey) => getView().layout.freezeUpTo(colKey),
		unfreeze: () => getView().layout.unfreeze(),
		openColumnMenu: (colKey) => getView().layout.setMenuColumn(colKey),
		get canOpenFields() {
			return hasToolbar() && getView().layout.orderedKeys.length > 0;
		},
		openFields: () => getView().layout.setFieldsOpen(true),
		get canOpenViews() {
			return hasToolbar() && getSavedViews().status !== 'loading';
		},
		openViews: () => getSavedViews().setOpen(true),
		get canSaveView() {
			const saved = getSavedViews();
			return saved.dirty && !saved.busy;
		},
		saveView: () => {
			void getSavedViews().save();
		},
	};
}

/**
 * Why a view or column command cannot run on a column, or null, for the menu
 * item that offers it (the context menu, the header menu).
 */
export function viewCommandReason(view: SheetsViewBindings, commandId: string, column: string | null): string | null {
	switch (commandId) {
		case 'view.sortAscending':
		case 'view.sortDescending':
			if (!column) return 'Select a cell in the column to sort by.';
			return view.unsortableReason(column) || null;
		case 'view.filterByColumn':
			return column && !isFilterable(view, column) ? 'This field cannot be filtered.' : null;
		case 'column.hide':
			return column ? view.layout.hideReason(column) : null;
		case 'column.moveLeft':
			return column && view.layout.visibleKeys[0] === column ? 'This field is already first.' : null;
		case 'column.moveRight':
			return column && view.layout.visibleKeys.at(-1) === column ? 'This field is already last.' : null;
		case 'record.new':
			if (!view.model) return 'New records are available once the table has loaded.';
			if (view.model.operations.create) return null;
			return (
				view.model.issues.find((issue) => issue.code === 'CREATE_UNAVAILABLE')?.message ?? 'Records cannot be added to this table.'
			);
		default:
			return null;
	}
}

import { createColumnLayout } from '../columns/column-layout';
import {
	SHEETS_VIEW_STATE_VERSION,
	type SheetsFilterCondition,
	type SheetsFilterGroup,
	type SheetsFilterLogic,
	type SheetsFilterNode,
	type SheetsSortDirection,
	type SheetsSortKey,
	type SheetsViewState,
} from './view-state.types';

/** Deepest nesting the filter builder offers (the root group is depth 0). */
export const MAX_FILTER_DEPTH = 3;

let nextNodeId = 0;

/** A node id unique within this page. */
export function createFilterNodeId(): string {
	nextNodeId += 1;
	return `f${Date.now().toString(36)}${nextNodeId.toString(36)}`;
}

export function createFilterGroup(logic: SheetsFilterLogic = 'and', children: readonly SheetsFilterNode[] = []): SheetsFilterGroup {
	return { kind: 'group', id: createFilterNodeId(), logic, children };
}

/** The state with no filter, no sort, no search, and every column shown in the table's order. */
export function createSheetsViewState(): SheetsViewState {
	return { version: SHEETS_VIEW_STATE_VERSION, filters: createFilterGroup(), sort: [], search: '', columns: createColumnLayout() };
}

/** Every condition in a group, depth first. */
export function filterConditionsOf(node: SheetsFilterNode): SheetsFilterCondition[] {
	if (node.kind !== 'group') return [node];
	return node.children.flatMap(filterConditionsOf);
}

/** Replace the node with `id` anywhere in the tree. */
export function replaceFilterNode(group: SheetsFilterGroup, id: string, next: SheetsFilterNode): SheetsFilterGroup {
	return {
		...group,
		children: group.children.map((child) => {
			if (child.id === id) return next;
			return child.kind === 'group' ? replaceFilterNode(child, id, next) : child;
		}),
	};
}

/** Remove the node with `id` anywhere in the tree. */
export function removeFilterNode(group: SheetsFilterGroup, id: string): SheetsFilterGroup {
	return {
		...group,
		children: group.children
			.filter((child) => child.id !== id)
			.map((child) => (child.kind === 'group' ? removeFilterNode(child, id) : child)),
	};
}

/**
 * The sort after a header click. A plain click cycles that column alone
 * (ascending, descending, none) and replaces any other key. An additive click
 * (Shift) adds the column as the last key, flips it, or removes it, and keeps
 * the other keys.
 */
export function cycleSort(sort: readonly SheetsSortKey[], column: string, additive: boolean): SheetsSortKey[] {
	const current = sort.find((key) => key.column === column);
	const next: SheetsSortDirection | null = !current ? 'asc' : current.direction === 'asc' ? 'desc' : null;
	if (!additive) return next ? [{ column, direction: next }] : [];
	if (!current) return [...sort, { column, direction: 'asc' }];
	return next
		? sort.map((key) => (key.column === column ? { column, direction: next } : key))
		: sort.filter((key) => key.column !== column);
}

/** The sort with `column` set to `direction`, kept in place or added last. */
export function setSortDirection(
	sort: readonly SheetsSortKey[],
	column: string,
	direction: SheetsSortDirection,
): SheetsSortKey[] {
	return sort.some((key) => key.column === column)
		? sort.map((key) => (key.column === column ? { column, direction } : key))
		: [...sort, { column, direction }];
}

/** The sort with the key at `from` moved to `to`. */
export function moveSortKey(sort: readonly SheetsSortKey[], from: number, to: number): SheetsSortKey[] {
	if (from === to || from < 0 || to < 0 || from >= sort.length || to >= sort.length) return [...sort];
	const next = [...sort];
	const [moved] = next.splice(from, 1);
	next.splice(to, 0, moved!);
	return next;
}

function withoutIds(node: SheetsFilterNode): unknown {
	if (node.kind !== 'group') {
		const { id: _id, ...rest } = node;
		return rest;
	}
	return { kind: node.kind, logic: node.logic, children: node.children.map(withoutIds) };
}

/**
 * A text form of a state that two states with the same meaning share (filter
 * node ids, key order and width order do not count). A saved view has unsaved
 * changes exactly when this differs from the stored state's.
 */
export function viewStateSignature(state: SheetsViewState): string {
	const widths = Object.entries(state.columns.widths).sort(([left], [right]) => left.localeCompare(right));
	return JSON.stringify({
		filters: withoutIds(state.filters),
		sort: state.sort,
		search: state.search,
		columns: { ...state.columns, hidden: [...state.columns.hidden].sort(), widths },
	});
}

/**
 * The filter, sort, search and column layout of one grid, as one serializable
 * value.
 *
 * Columns and relations are named by their field name in the table model, so a
 * host can store the value (a saved view) and load it later. Load a stored value
 * through `validateSheetsViewState`: it drops every part the current model no
 * longer supports and says what it dropped, and it upgrades a version 1 value
 * (no column layout) to the current version.
 */

/** Version of the state shape. Version 2 added `columns`. */
export const SHEETS_VIEW_STATE_VERSION = 2;

/** How the children of a filter group combine. */
export type SheetsFilterLogic = 'and' | 'or';

/**
 * A filter value as the user entered it: text (exact decimal text for big
 * numbers, ISO text for dates, times and timestamps), a boolean, a list of
 * values for list operators, field values for an operator that takes an object,
 * or null for an operator without a value.
 */
export type SheetsFilterValue = string | boolean | readonly string[] | Readonly<Record<string, string>> | null;

/** A condition on one column. */
export interface SheetsColumnCondition {
	kind: 'column';
	/** Stable id within the state. */
	id: string;
	/** Column field name. */
	column: string;
	/** Operator name the column's filter really has, for example `includesInsensitive`. */
	operator: string;
	value: SheetsFilterValue;
}

/** What a relation condition tests. */
export type SheetsRelationTest = 'any' | 'none' | 'labelContains';

/** A condition on one relation. */
export interface SheetsRelationCondition {
	kind: 'relation';
	/** Stable id within the state. */
	id: string;
	/** Relation field name. */
	relation: string;
	/** `any`: has a linked record; `none`: has no linked record; `labelContains`: a linked record's label contains `value`. */
	test: SheetsRelationTest;
	/** Text for `labelContains`, otherwise null. */
	value: string | null;
}

export type SheetsFilterCondition = SheetsColumnCondition | SheetsRelationCondition;

/** A group of conditions and groups. */
export interface SheetsFilterGroup {
	kind: 'group';
	/** Stable id within the state. */
	id: string;
	logic: SheetsFilterLogic;
	children: readonly SheetsFilterNode[];
}

export type SheetsFilterNode = SheetsFilterGroup | SheetsFilterCondition;

export type SheetsSortDirection = 'asc' | 'desc';

/** One sort key. The first key in a list sorts first. */
export interface SheetsSortKey {
	/** Column field name. */
	column: string;
	direction: SheetsSortDirection;
}

/** Row heights the grid offers. */
export type SheetsRowHeight = 'short' | 'medium' | 'tall' | 'extraTall';

/** Which columns show, in what order, how wide, how many stay in place, and how tall rows are. */
export interface SheetsColumnLayout {
	/**
	 * Grid column keys (column and relation field names) in display order. Keys
	 * the table has but this list does not name follow, in the table's order, so a
	 * new column shows up at the end.
	 */
	order: readonly string[];
	/** Grid column keys that are hidden. */
	hidden: readonly string[];
	/** How many leading visible columns stay in place while the grid scrolls sideways. */
	frozenCount: number;
	/** Column widths in pixels, by grid column key. A column without an entry keeps its default width. */
	widths: Readonly<Record<string, number>>;
	rowHeight: SheetsRowHeight;
}

/** Filter, sort, search and column layout of one grid. */
export interface SheetsViewState {
	version: typeof SHEETS_VIEW_STATE_VERSION;
	filters: SheetsFilterGroup;
	sort: readonly SheetsSortKey[];
	/** Search text; empty for no search. */
	search: string;
	columns: SheetsColumnLayout;
}

/** Why the validator dropped part of a state. */
export type SheetsViewStateDropReason =
	| 'invalid-shape'
	| 'unknown-column'
	| 'column-not-filterable'
	| 'unknown-operator'
	| 'unknown-option'
	| 'unknown-relation'
	| 'relation-test-unavailable'
	| 'column-not-sortable'
	| 'duplicate-sort'
	| 'search-unavailable';

/** One part of a state that the current model does not support. */
export interface SheetsViewStateDrop {
	/** Which part of the state. */
	part: 'filters' | 'sort' | 'search' | 'columns';
	/** Column or relation the dropped part named, or null. */
	target: string | null;
	reason: SheetsViewStateDropReason;
	/** Human-readable explanation, safe to show to the user. */
	message: string;
}

/** A state the model supports, and what was dropped to get it. */
export interface SheetsViewStateValidation {
	state: SheetsViewState;
	dropped: readonly SheetsViewStateDrop[];
}

/**
 * Saved views of one table: list, select, create, save, discard, rename,
 * duplicate, delete. Every stored state is validated against the current
 * table model before it is used, and what was dropped is kept for the notice.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';

import type { TableModel } from '@constructive-io/data';

import { validateSheetsViewState } from '../view-state/validate-view-state';
import { createSheetsViewState, viewStateSignature } from '../view-state/view-state';
import type { SheetsViewState, SheetsViewStateDrop } from '../view-state/view-state.types';
import { copyViewName, MAX_VIEW_NAME_LENGTH } from './view-names';
import { viewScopeKey, type SheetsStoredView, type SheetsViewStorage, type SheetsViewStorageScope } from './view-storage';

/** A saved view, checked against the current model. */
export interface SavedView {
	id: string;
	name: string;
	/** The stored state as the current model supports it. */
	state: SheetsViewState;
	/** What the model no longer supports, as messages for the user. */
	dropped: readonly SheetsViewStateDrop[];
	updatedAt: string;
}

export interface SavedViewsBindings {
	/** 'loading' until the stored views and the table model are both there. */
	status: 'loading' | 'ready' | 'error';
	/** Why the views could not be loaded or the last change failed, or null. */
	error: string | null;
	views: readonly SavedView[];
	/** The view in use, or null for the default view (nothing saved). */
	activeView: SavedView | null;
	/** The grid differs from the active view as saved. Always false for the default view. */
	dirty: boolean;
	/** True while a change is being written. */
	busy: boolean;
	/** Messages about parts of the active view the model dropped when it loaded. */
	activeDropped: readonly SheetsViewStateDrop[];
	/** Switch to a view, or with null to the default view (no filter, sort or search, every field shown). Unsaved changes are discarded. */
	select: (viewId: string | null) => Promise<boolean>;
	/** Save the grid as a new view and switch to it. */
	create: (name: string) => Promise<boolean>;
	/** Save the grid into the active view. */
	save: () => Promise<boolean>;
	/** Go back to the active view as saved. */
	discard: () => void;
	rename: (viewId: string, name: string) => Promise<boolean>;
	/** Copy a view under a new name and switch to the copy. */
	duplicate: (viewId: string) => Promise<boolean>;
	remove: (viewId: string) => Promise<boolean>;
	/** Load the views again after an error. */
	retry: () => void;
	/** Why a name cannot be used, or null. */
	nameProblem: (name: string, exceptViewId?: string) => string | null;
	open: boolean;
	setOpen: (open: boolean) => void;
}

export interface UseSavedViewsOptions {
	storage: SheetsViewStorage;
	/** Null until the table model has loaded. */
	scope: SheetsViewStorageScope | null;
	model: TableModel | null;
	/** The grid's state in use. */
	current: SheetsViewState;
	/** Replace the grid's state. */
	apply: (state: SheetsViewState) => void;
	/** Column titles for drop messages. */
	label: (name: string) => string;
}

function newViewId(): string {
	const random = typeof crypto !== 'undefined' && 'randomUUID' in crypto ? crypto.randomUUID() : Math.random().toString(36).slice(2);
	return `view-${random}`;
}

function messageOf(error: unknown): string {
	return error instanceof Error && error.message ? error.message : 'The storage did not answer.';
}

export function useSavedViews({ storage, scope, model, current, apply, label }: UseSavedViewsOptions): SavedViewsBindings {
	const queryClient = useQueryClient();
	const scopeId = scope ? viewScopeKey(scope) : null;
	const queryKey = useMemo(() => ['constructive-sheets', 'saved-views', scopeId] as const, [scopeId]);
	const [open, setOpen] = useState(false);
	const [busy, setBusy] = useState(false);
	const [changeError, setChangeError] = useState<string | null>(null);

	const query = useQuery({
		queryKey,
		enabled: scope !== null,
		retry: false,
		queryFn: async () => {
			const [stored, activeViewId] = await Promise.all([
				storage.list(scope!),
				storage.getActiveViewId ? storage.getActiveViewId(scope!) : Promise.resolve(null),
			]);
			return { stored: [...stored], activeViewId };
		},
	});

	const views = useMemo<SavedView[]>(() => {
		if (!model || !query.data) return [];
		return query.data.stored.map((entry) => {
			const { state, dropped } = validateSheetsViewState(entry.state, model, { label });
			return { id: entry.id, name: entry.name, state, dropped, updatedAt: entry.updatedAt };
		});
	}, [model, query.data, label]);

	const activeViewId = query.data?.activeViewId ?? null;
	const activeView = views.find((view) => view.id === activeViewId) ?? null;
	const currentSignature = viewStateSignature(current);
	const dirty = activeView !== null && viewStateSignature(activeView.state) !== currentSignature;

	// Restore the last selected view once per table, as soon as views and model are both there.
	const restoredScope = useRef<string | null>(null);
	useEffect(() => {
		if (!scopeId || !model || !query.data || restoredScope.current === scopeId) return;
		restoredScope.current = scopeId;
		if (activeView) apply(activeView.state);
	}, [scopeId, model, query.data, activeView, apply]);

	const latest = useRef({ current, views, activeView });
	latest.current = { current, views, activeView };

	type Cached = { stored: SheetsStoredView[]; activeViewId: string | null };
	const updateCache = useCallback(
		(update: (cached: Cached) => Cached) => {
			queryClient.setQueryData<Cached>(queryKey, (cached) => update(cached ?? { stored: [], activeViewId: null }));
		},
		[queryClient, queryKey],
	);

	/** Run one storage change; on failure keep the message and report false. */
	const change = useCallback(async (work: () => Promise<void>): Promise<boolean> => {
		setBusy(true);
		setChangeError(null);
		try {
			await work();
			return true;
		} catch (error) {
			setChangeError(messageOf(error));
			return false;
		} finally {
			setBusy(false);
		}
	}, []);

	const setActive = useCallback(
		async (viewId: string | null) => {
			if (!scope) return;
			if (storage.setActiveViewId) await storage.setActiveViewId(scope, viewId);
			updateCache((cached) => ({ ...cached, activeViewId: viewId }));
		},
		[scope, storage, updateCache],
	);

	const writeView = useCallback(
		async (view: SheetsStoredView) => {
			if (!scope) throw new Error('Saved views are available once the table has loaded.');
			await storage.save(scope, view);
			updateCache((cached) => {
				const at = cached.stored.findIndex((entry) => entry.id === view.id);
				const stored = at === -1 ? [...cached.stored, view] : cached.stored.map((entry) => (entry.id === view.id ? view : entry));
				return { ...cached, stored };
			});
		},
		[scope, storage, updateCache],
	);

	const nameProblem = useCallback((name: string, exceptViewId?: string) => {
		const trimmed = name.trim();
		if (trimmed === '') return 'Enter a name.';
		if (trimmed.length > MAX_VIEW_NAME_LENGTH) return `Use at most ${MAX_VIEW_NAME_LENGTH} characters.`;
		const taken = latest.current.views.some((view) => view.id !== exceptViewId && view.name.toLowerCase() === trimmed.toLowerCase());
		return taken ? 'A view with this name already exists.' : null;
	}, []);

	const select = useCallback(
		(viewId: string | null) =>
			change(async () => {
				const target = viewId === null ? null : latest.current.views.find((view) => view.id === viewId);
				if (viewId !== null && !target) throw new Error('That view no longer exists.');
				await setActive(viewId);
				apply(target ? target.state : createSheetsViewState());
			}),
		[change, setActive, apply],
	);

	const create = useCallback(
		(name: string) =>
			change(async () => {
				const problem = nameProblem(name);
				if (problem) throw new Error(problem);
				const view: SheetsStoredView = {
					id: newViewId(),
					name: name.trim(),
					state: latest.current.current,
					updatedAt: new Date().toISOString(),
				};
				await writeView(view);
				await setActive(view.id);
			}),
		[change, nameProblem, writeView, setActive],
	);

	const save = useCallback(
		() =>
			change(async () => {
				const active = latest.current.activeView;
				if (!active) throw new Error('Choose a view to save into, or save as a new view.');
				await writeView({ id: active.id, name: active.name, state: latest.current.current, updatedAt: new Date().toISOString() });
			}),
		[change, writeView],
	);

	const discard = useCallback(() => {
		const active = latest.current.activeView;
		if (active) apply(active.state);
	}, [apply]);

	const rename = useCallback(
		(viewId: string, name: string) =>
			change(async () => {
				const target = latest.current.views.find((view) => view.id === viewId);
				if (!target) throw new Error('That view no longer exists.');
				const problem = nameProblem(name, viewId);
				if (problem) throw new Error(problem);
				await writeView({ id: target.id, name: name.trim(), state: target.state, updatedAt: new Date().toISOString() });
			}),
		[change, nameProblem, writeView],
	);

	const duplicate = useCallback(
		(viewId: string) =>
			change(async () => {
				const target = latest.current.views.find((view) => view.id === viewId);
				if (!target) throw new Error('That view no longer exists.');
				const name = copyViewName(target.name, (candidate) => nameProblem(candidate) !== null);
				// The active view copies the grid as it is now (unsaved changes included).
				const state = latest.current.activeView?.id === viewId ? latest.current.current : target.state;
				const copy: SheetsStoredView = { id: newViewId(), name, state, updatedAt: new Date().toISOString() };
				await writeView(copy);
				await setActive(copy.id);
				apply(state);
			}),
		[change, nameProblem, writeView, setActive, apply],
	);

	const remove = useCallback(
		(viewId: string) =>
			change(async () => {
				if (!scope) return;
				await storage.remove(scope, viewId);
				updateCache((cached) => ({
					stored: cached.stored.filter((entry) => entry.id !== viewId),
					activeViewId: cached.activeViewId === viewId ? null : cached.activeViewId,
				}));
				if (latest.current.activeView?.id === viewId) await setActive(null);
			}),
		[change, scope, storage, updateCache, setActive],
	);

	const { refetch } = query;
	const retry = useCallback(() => {
		setChangeError(null);
		void refetch();
	}, [refetch]);

	const status: SavedViewsBindings['status'] = query.isError ? 'error' : query.data && model ? 'ready' : 'loading';
	const error = query.isError ? `Saved views could not be loaded. ${messageOf(query.error)}` : changeError;

	return useMemo<SavedViewsBindings>(
		() => ({
			status,
			error,
			views,
			activeView,
			dirty,
			busy,
			activeDropped: activeView?.dropped ?? [],
			select,
			create,
			save,
			discard,
			rename,
			duplicate,
			remove,
			retry,
			nameProblem,
			open,
			setOpen,
		}),
		[status, error, views, activeView, dirty, busy, select, create, save, discard, rename, duplicate, remove, retry, nameProblem, open],
	);
}

/** The most characters a saved view's name may have. */
export const MAX_VIEW_NAME_LENGTH = 80;

/**
 * The name for a copy of a view: "<name> copy", then "<name> copy 2", "<name> copy 3"…
 * while `isTaken` says a name is in use. The name is cut short when the suffix would not
 * fit, so every candidate is a valid name and the search always ends.
 */
export function copyViewName(name: string, isTaken: (candidate: string) => boolean): string {
	for (let n = 1; ; n += 1) {
		const suffix = n === 1 ? ' copy' : ` copy ${n}`;
		const candidate = `${name.trim().slice(0, MAX_VIEW_NAME_LENGTH - suffix.length).trimEnd()}${suffix}`;
		if (!isTaken(candidate)) return candidate;
	}
}

/**
 * Where saved views are kept.
 *
 * A host passes its own `SheetsViewStorage` as `SheetsConfig.views` (server
 * storage, for example); otherwise the grid keeps views in this browser's
 * local storage, keyed by endpoint, database, identity and table. A stored
 * state is never trusted: the grid validates it against the current table model
 * when it loads (see `validateSheetsViewState`).
 */

/** Which table's views, for whom. */
export interface SheetsViewStorageScope {
	endpoint: string;
	databaseId: string | null;
	/** The signed-in identity the host reports, or null. */
	identityKey: string | null;
	/** `TableModel.key` of the table. */
	tableKey: string;
}

/** One saved view as stored. */
export interface SheetsStoredView {
	id: string;
	name: string;
	/** A `SheetsViewState` when it was saved; validated against the model on load. */
	state: unknown;
	/** ISO timestamp of the last save. */
	updatedAt: string;
}

export interface SheetsViewStorage {
	/** Every saved view of one table. */
	list(scope: SheetsViewStorageScope): Promise<readonly SheetsStoredView[]>;
	/** Create or replace a view by id. */
	save(scope: SheetsViewStorageScope, view: SheetsStoredView): Promise<void>;
	/** Delete a view by id. */
	remove(scope: SheetsViewStorageScope, viewId: string): Promise<void>;
	/** The view last selected for this table, or null. Optional: without it no view is restored on load. */
	getActiveViewId?(scope: SheetsViewStorageScope): Promise<string | null>;
	setActiveViewId?(scope: SheetsViewStorageScope, viewId: string | null): Promise<void>;
}

/** Text that identifies a scope, for storage keys and cache keys. */
export function viewScopeKey(scope: SheetsViewStorageScope): string {
	return JSON.stringify([scope.endpoint, scope.databaseId, scope.identityKey, scope.tableKey]);
}

interface StoredTable {
	views: SheetsStoredView[];
	activeViewId: string | null;
}

/** The part of `Storage` this module uses (local storage, or a test double). */
export interface KeyValueStore {
	getItem(key: string): string | null;
	setItem(key: string, value: string): void;
}

const KEY_PREFIX = 'constructive-sheets:views:';

function isStoredView(value: unknown): value is SheetsStoredView {
	if (!value || typeof value !== 'object') return false;
	const view = value as Record<string, unknown>;
	return typeof view.id === 'string' && typeof view.name === 'string' && typeof view.updatedAt === 'string';
}

/**
 * Views in a key-value store, one entry per table scope. Entries that cannot be
 * read are skipped, so one bad entry never loses the others.
 */
export function createKeyValueViewStorage(store: KeyValueStore): SheetsViewStorage {
	const read = (scope: SheetsViewStorageScope): StoredTable => {
		const raw = store.getItem(KEY_PREFIX + viewScopeKey(scope));
		if (!raw) return { views: [], activeViewId: null };
		let parsed: unknown;
		try {
			parsed = JSON.parse(raw);
		} catch {
			return { views: [], activeViewId: null };
		}
		const table = parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : {};
		return {
			views: Array.isArray(table.views) ? table.views.filter(isStoredView) : [],
			activeViewId: typeof table.activeViewId === 'string' ? table.activeViewId : null,
		};
	};
	const write = (scope: SheetsViewStorageScope, table: StoredTable) => {
		store.setItem(KEY_PREFIX + viewScopeKey(scope), JSON.stringify(table));
	};
	return {
		async list(scope) {
			return read(scope).views;
		},
		async save(scope, view) {
			const table = read(scope);
			const at = table.views.findIndex((candidate) => candidate.id === view.id);
			const views = at === -1 ? [...table.views, view] : table.views.map((candidate) => (candidate.id === view.id ? view : candidate));
			write(scope, { ...table, views });
		},
		async remove(scope, viewId) {
			const table = read(scope);
			write(scope, {
				views: table.views.filter((candidate) => candidate.id !== viewId),
				activeViewId: table.activeViewId === viewId ? null : table.activeViewId,
			});
		},
		async getActiveViewId(scope) {
			return read(scope).activeViewId;
		},
		async setActiveViewId(scope, viewId) {
			write(scope, { ...read(scope), activeViewId: viewId });
		},
	};
}

/** Views kept in memory for this page only (no browser storage, or tests). */
export function createMemoryViewStorage(): SheetsViewStorage {
	const entries = new Map<string, string>();
	return createKeyValueViewStorage({
		getItem: (key) => entries.get(key) ?? null,
		setItem: (key, value) => void entries.set(key, value),
	});
}

let browserStorage: SheetsViewStorage | null = null;

/**
 * The default storage: this browser's local storage. Where local storage is
 * missing or refuses access, views are kept for this page only.
 */
export function defaultViewStorage(): SheetsViewStorage {
	if (browserStorage) return browserStorage;
	let local: Storage | null = null;
	try {
		local = typeof window !== 'undefined' ? window.localStorage : null;
	} catch {
		local = null;
	}
	browserStorage = local ? createKeyValueViewStorage(local) : createMemoryViewStorage();
	return browserStorage;
}

/**
 * The toolbar view switcher: the current view's name with an "unsaved changes"
 * marker, and a popover to switch views, save, discard, save as a new view,
 * rename, duplicate and delete. Switching away from unsaved changes asks first.
 */
import { useState } from 'react';
import { RiArrowDownSLine, RiDeleteBinLine, RiFileCopyLine, RiPencilLine, RiTableLine } from '@remixicon/react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';

import { cn } from '../../utils/cn';
import { TOOLBAR_POPOVER } from '../popup-classes';
import type { SavedViewsBindings } from './use-saved-views';

export const DEFAULT_VIEW_NAME = 'Default view';

type Pending =
	| { kind: 'create' }
	| { kind: 'rename'; viewId: string }
	| { kind: 'delete'; viewId: string }
	| { kind: 'switch'; viewId: string | null };

function NameForm({
	initial,
	submitLabel,
	problem,
	busy,
	onSubmit,
	onCancel,
	label,
}: {
	initial: string;
	submitLabel: string;
	problem: (name: string) => string | null;
	busy: boolean;
	onSubmit: (name: string) => void;
	onCancel: () => void;
	label: string;
}) {
	const [name, setName] = useState(initial);
	const [touched, setTouched] = useState(false);
	const error = touched ? problem(name) : null;
	const submit = () => {
		setTouched(true);
		if (!problem(name)) onSubmit(name);
	};
	return (
		<form
			className='grid gap-1.5'
			onSubmit={(event) => {
				event.preventDefault();
				submit();
			}}
		>
			<div className='flex items-center gap-2'>
				<Input
					size='sm'
					autoFocus
					aria-label={label}
					aria-invalid={error ? true : undefined}
					value={name}
					maxLength={120}
					onChange={(event) => setName(event.target.value)}
					onKeyDown={(event) => {
						if (event.key === 'Escape') {
							event.preventDefault();
							event.stopPropagation();
							onCancel();
						}
					}}
				/>
				<Button type='submit' size='xs' disabled={busy}>
					{submitLabel}
				</Button>
				<Button type='button' variant='ghost' size='xs' onClick={onCancel}>
					Cancel
				</Button>
			</div>
			{error && (
				<p className='text-destructive text-xs' role='alert'>
					{error}
				</p>
			)}
		</form>
	);
}

export interface ViewSwitcherProps {
	views: SavedViewsBindings;
}

export function ViewSwitcher({ views }: ViewSwitcherProps) {
	const [pending, setPending] = useState<Pending | null>(null);
	const active = views.activeView;
	const name = active?.name ?? DEFAULT_VIEW_NAME;
	const nameOf = (viewId: string | null) => (viewId === null ? DEFAULT_VIEW_NAME : views.views.find((view) => view.id === viewId)?.name ?? '');

	const close = () => setPending(null);
	const choose = (viewId: string | null) => {
		if (viewId === (active?.id ?? null)) return;
		if (views.dirty) {
			setPending({ kind: 'switch', viewId });
			return;
		}
		void views.select(viewId);
	};

	return (
		<Popover
			open={views.open}
			onOpenChange={(open) => {
				views.setOpen(open);
				if (!open) close();
			}}
		>
			<PopoverTrigger asChild>
				<Button
					variant='ghost'
					size='sm'
					aria-label={`View: ${name}${views.dirty ? ' (unsaved changes)' : ''}`}
					data-part-id='sheets-view-switcher'
					className='font-medium'
				>
					<RiTableLine className='text-muted-foreground size-4' aria-hidden='true' />
					<span className='max-w-[12rem] truncate' title={name}>
						{name}
					</span>
					{views.dirty && (
						<span className='text-muted-foreground inline-flex items-center gap-1 text-xs font-normal' data-part-id='sheets-view-dirty'>
							<span className='bg-primary size-1.5 rounded-full' aria-hidden='true' />
							Edited
						</span>
					)}
					<RiArrowDownSLine className='text-muted-foreground -me-1 size-4' aria-hidden='true' />
				</Button>
			</PopoverTrigger>
			<PopoverContent className={cn('w-[22rem]', TOOLBAR_POPOVER)} align='start'>
				<div className='grid gap-3' data-part-id='sheets-view-list'>
					<h4 className='leading-none font-medium'>Views</h4>

					{views.status === 'loading' && <p className='text-muted-foreground text-sm'>Loading views…</p>}
					{views.status === 'error' && (
						<div className='grid gap-2' role='alert'>
							<p className='text-destructive text-sm'>{views.error}</p>
							<Button variant='outline' size='xs' className='justify-self-start' onClick={views.retry}>
								Retry
							</Button>
						</div>
					)}

					{views.status === 'ready' && (
						<ul aria-label='Saved views' className='grid max-h-72 gap-0.5 overflow-auto'>
							{[{ id: null as string | null, name: DEFAULT_VIEW_NAME }, ...views.views].map((view) => {
								const selected = view.id === (active?.id ?? null);
								const editing = view.id !== null && pending?.kind === 'rename' && pending.viewId === view.id;
								const deleting = view.id !== null && pending?.kind === 'delete' && pending.viewId === view.id;
								return (
									<li key={view.id ?? 'default'} data-part-id='sheets-view' className='grid gap-1'>
										{editing ? (
											<NameForm
												initial={view.name}
												submitLabel='Rename'
												label={`New name for ${view.name}`}
												busy={views.busy}
												problem={(next) => views.nameProblem(next, view.id ?? undefined)}
												onCancel={close}
												onSubmit={(next) => {
													void views.rename(view.id!, next).then((ok) => ok && close());
												}}
											/>
										) : (
											<div className={cn('flex items-center gap-1 rounded px-2', selected ? 'bg-muted' : 'hover:bg-muted/60')}>
												<button
													type='button'
													aria-current={selected ? 'true' : undefined}
													className='min-w-0 flex-1 truncate py-1 text-left text-sm'
													title={view.name}
													onClick={() => choose(view.id)}
												>
													{view.name}
												</button>
												{view.id !== null && (
													<>
														<Button variant='ghost' size='icon-xs' aria-label={`Rename ${view.name}`} onClick={() => setPending({ kind: 'rename', viewId: view.id! })}>
															<RiPencilLine aria-hidden='true' />
														</Button>
														<Button
															variant='ghost'
															size='icon-xs'
															aria-label={`Duplicate ${view.name}`}
															disabled={views.busy}
															onClick={() => void views.duplicate(view.id!)}
														>
															<RiFileCopyLine aria-hidden='true' />
														</Button>
														<Button variant='ghost' size='icon-xs' aria-label={`Delete ${view.name}`} onClick={() => setPending({ kind: 'delete', viewId: view.id! })}>
															<RiDeleteBinLine aria-hidden='true' />
														</Button>
													</>
												)}
											</div>
										)}
										{deleting && (
											<div className='flex items-center gap-2 px-2 text-sm' role='alert'>
												<span className='min-w-0 flex-1'>Delete “{view.name}”? This cannot be undone.</span>
												<Button
													variant='destructive-outline'
													size='xs'
													disabled={views.busy}
													onClick={() => void views.remove(view.id!).then((ok) => ok && close())}
												>
													Delete
												</Button>
												<Button variant='ghost' size='xs' onClick={close}>
													Cancel
												</Button>
											</div>
										)}
									</li>
								);
							})}
						</ul>
					)}

					{pending?.kind === 'switch' && (
						<div className='grid gap-2 rounded border p-2 text-sm' role='alert'>
							<p>“{name}” has unsaved changes. Switching to “{nameOf(pending.viewId)}” discards them.</p>
							<div className='flex flex-wrap gap-2'>
								<Button
									size='xs'
									disabled={views.busy}
									onClick={() => void views.save().then((ok) => ok && views.select(pending.viewId)).then(() => close())}
								>
									Save and switch
								</Button>
								<Button variant='outline' size='xs' disabled={views.busy} onClick={() => void views.select(pending.viewId).then(() => close())}>
									Discard and switch
								</Button>
								<Button variant='ghost' size='xs' onClick={close}>
									Cancel
								</Button>
							</div>
						</div>
					)}

					{views.status === 'ready' && views.views.length === 0 && pending?.kind !== 'create' && (
						<p className='text-muted-foreground text-xs'>No saved views yet. Save the current filters, sort, search and fields as a view.</p>
					)}

					{views.error && views.status !== 'error' && (
						<p className='text-destructive text-xs' role='alert'>
							{views.error}
						</p>
					)}

					{views.status === 'ready' && (
						<div className='grid gap-2 border-t pt-2'>
							{views.dirty && (
								<div className='flex items-center gap-2'>
									<Button size='xs' disabled={views.busy} onClick={() => void views.save()}>
										Save view
									</Button>
									<Button variant='ghost' size='xs' disabled={views.busy} onClick={views.discard}>
										Discard changes
									</Button>
								</div>
							)}
							{pending?.kind === 'create' ? (
								<NameForm
									initial=''
									submitLabel='Save'
									label='Name of the new view'
									busy={views.busy}
									problem={(next) => views.nameProblem(next)}
									onCancel={close}
									onSubmit={(next) => {
										void views.create(next).then((ok) => ok && close());
									}}
								/>
							) : (
								<Button variant='ghost' size='xs' className='justify-self-start' onClick={() => setPending({ kind: 'create' })}>
									Save as new view…
								</Button>
							)}
						</div>
					)}
				</div>
			</PopoverContent>
		</Popover>
	);
}

// What the user sees when a write does not happen: a value that does not fit its
// column, a cell that cannot be changed, or a save the server refused. Every message
// is plain product language; the reasons come from the table model or the value
// rules, never from a backend type name.

import { toast } from '@/components/ui/toast';

import { fieldLabel } from '../cell-types/field-label';

/** One cell write the grid refused before sending it. */
export interface RejectedWrite {
	rowIndex: number;
	colKey: string;
	reason: string;
}

/**
 * Report writes that were skipped because the value did not fit or the cell is read
 * only. One write names its field and reason; several are counted and grouped by
 * field and reason, so a paste into the wrong column says how much was left out and why.
 */
export function reportRejectedWrites(rejected: readonly RejectedWrite[], total: number): void {
	if (rejected.length === 0) return;
	if (rejected.length === 1 && total <= 1) {
		const [only] = rejected;
		toast.error({ message: `${fieldLabel(only.colKey)} was not changed`, description: only.reason });
		return;
	}
	const groups = new Map<string, { colKey: string; reason: string; count: number }>();
	for (const entry of rejected) {
		const key = `${entry.colKey}\u0000${entry.reason}`;
		const group = groups.get(key);
		if (group) group.count += 1;
		else groups.set(key, { colKey: entry.colKey, reason: entry.reason, count: 1 });
	}
	const lines = [...groups.values()].map(
		(group) => `${fieldLabel(group.colKey)} (${group.count} ${group.count === 1 ? 'cell' : 'cells'}): ${group.reason}`,
	);
	const skipped = rejected.length;
	toast.warning({
		// The verb agrees with the cells left alone: "1 of 3 cells was not changed".
		message: `${skipped} of ${total} ${total === 1 ? 'cell' : 'cells'} ${skipped === 1 ? 'was' : 'were'} not changed`,
		description: lines.join('\n'),
	});
}

/** Tell the user why a cell they tried to edit cannot be changed. */
export function reportReadOnlyCell(colKey: string, reason: string): void {
	toast.info({ message: `${fieldLabel(colKey)} cannot be changed`, description: reason });
}

/** Tell the user why a new row was not saved: the fields it still needs. */
export function reportIncompleteDraft(message: string): void {
	toast.warning({ message });
}

import type { FieldSelection, SimpleFieldSelection, SortSpec } from '@constructive-io/data';

import type { AdapterListQuery } from '../adapter/sheets-adapter';

/**
 * Relations a legacy `FieldSelection` asks for. The `full` preset selects every
 * readable relation, the other presets none; `includeRelations` and truthy
 * `include` entries name relation fields.
 */
export function relationsFromSelection(select: FieldSelection | undefined): AdapterListQuery['relations'] {
	if (select === 'full') return 'all';
	if (!select || typeof select === 'string') return 'none';
	const selection = select as SimpleFieldSelection;
	const fields = new Set<string>(selection.includeRelations ?? []);
	for (const [field, value] of Object.entries(selection.include ?? {})) if (value) fields.add(field);
	return fields.size > 0 ? [...fields] : 'none';
}

/**
 * The field selection of the grid's relations: the `requested` ones among those the
 * grid shows, or every one it shows when `requested` is omitted.
 */
export function gridRelationSelection(shown: readonly string[], requested: readonly string[] | undefined): FieldSelection {
	const fields = requested ? shown.filter((field) => requested.includes(field)) : shown;
	// The `all` preset selects no relation.
	return fields.length > 0 ? { includeRelations: [...fields] } : 'all';
}

/** The sort the hooks accept, as the adapter takes it. */
export function sortSpecs(
	orderBy: ReadonlyArray<{ field: string; direction: 'asc' | 'desc' }> | undefined,
): readonly SortSpec[] | undefined {
	return orderBy && orderBy.length > 0 ? orderBy.map(({ field, direction }) => ({ field, direction })) : undefined;
}

/** A filter object as the adapter takes it; empty filters are dropped. */
export function whereFilter(where: unknown): Readonly<Record<string, unknown>> | undefined {
	if (!where || typeof where !== 'object') return undefined;
	return Object.keys(where).length > 0 ? (where as Readonly<Record<string, unknown>>) : undefined;
}

import type { SheetsScopeKey } from '../context/sheets-context';

export function isSheetsScopeKey(value: unknown): value is SheetsScopeKey {
	if (!value || typeof value !== 'object') return false;
	const candidate = value as Record<string, unknown>;
	return 'databaseId' in candidate && 'endpoint' in candidate && 'identityKey' in candidate;
}

export function reuseSheetsPlaceholderData<T>(
	previousData: T | undefined,
	previousQueryKey: readonly unknown[] | undefined,
	currentScope: SheetsScopeKey,
): T | undefined {
	const previousScope = previousQueryKey?.[1];
	if (!isSheetsScopeKey(previousScope)) return undefined;
	if (previousScope.databaseId !== currentScope.databaseId) return undefined;
	if (previousScope.endpoint !== currentScope.endpoint) return undefined;
	if (previousScope.identityKey !== currentScope.identityKey) return undefined;
	return previousData;
}

/**
 * Cache-key segments for a table reference. A `TableModel.key`
 * (`schema.Name`) becomes `[Name, schema]`, a bare name `[Name]`. Tables in
 * different schemas get different entries, and a key built from a bare name is
 * a prefix of every schema's entry, so invalidating by name still reaches them.
 */
export function tableKeySegments(tableRef: string): readonly string[] {
	const dot = tableRef.lastIndexOf('.');
	return dot === -1 ? [tableRef] : [tableRef.slice(dot + 1), tableRef.slice(0, dot)];
}

export const sheetsQueryKeys = {
	root: ['sheets'] as const,
	scope: (scope: SheetsScopeKey) => ['sheets', scope] as const,
	meta: (scope: SheetsScopeKey) => [...sheetsQueryKeys.scope(scope), 'meta'] as const,
	/** One table model, per `_meta` version and display override. */
	tableModel: (scope: SheetsScopeKey, tableKey: string, metaVersion: number, displayKey: string | null) =>
		[...sheetsQueryKeys.scope(scope), 'table-model', ...tableKeySegments(tableKey), metaVersion, displayKey] as const,
	mediaUrl: (scope: SheetsScopeKey, endpoint: string | undefined, id: string | null) =>
		[...sheetsQueryKeys.scope(scope), 'media-url', endpoint, id] as const,
	relations: (scope: SheetsScopeKey, tableName: string) =>
		[...sheetsQueryKeys.scope(scope), 'relations', ...tableKeySegments(tableName)] as const,
	table: (scope: SheetsScopeKey, tableRef: string) =>
		[...sheetsQueryKeys.scope(scope), 'table', ...tableKeySegments(tableRef)] as const,
	tableRows: (scope: SheetsScopeKey, tableRef: string, options?: unknown) =>
		[...sheetsQueryKeys.table(scope, tableRef), 'rows', options] as const,
	tableRow: (scope: SheetsScopeKey, tableRef: string, id: unknown) =>
		[...sheetsQueryKeys.table(scope, tableRef), 'row', id] as const,
	tableCount: (scope: SheetsScopeKey, tableRef: string, where?: Readonly<Record<string, unknown>> | null) =>
		[...sheetsQueryKeys.table(scope, tableRef), 'count', where] as const,
	infiniteTable: (scope: SheetsScopeKey, tableRef: string) =>
		[...sheetsQueryKeys.scope(scope), 'infinite-table', ...tableKeySegments(tableRef)] as const,
	infiniteTablePage: (scope: SheetsScopeKey, tableRef: string, pageIndex: number, options: unknown) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableRef), 'page', pageIndex, options] as const,
	infiniteTableTotalCount: (scope: SheetsScopeKey, tableRef: string, where?: Readonly<Record<string, unknown>>) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableRef), 'totalCount', where] as const,
	cursorTable: (scope: SheetsScopeKey, tableRef: string, options?: unknown) =>
		[...sheetsQueryKeys.scope(scope), 'cursor-table', ...tableKeySegments(tableRef), options] as const,
} as const;

/**
 * Mutation keys. Every mutation a Sheets hook creates sits under its table's
 * query key, `[...table(scope, tableRef), 'mutation', operation, ...detail]`, so
 * `useIsMutating({ mutationKey: sheetsMutationKeys.table(scope, ref) })` counts
 * every write in flight on that table.
 */
export const sheetsMutationKeys = {
	/** Every mutation of a table, or one operation of it when `operation` is given. */
	table: (scope: SheetsScopeKey, tableRef: string, operation?: string, ...detail: readonly unknown[]) =>
		operation === undefined
			? ([...sheetsQueryKeys.table(scope, tableRef), 'mutation'] as const)
			: ([...sheetsQueryKeys.table(scope, tableRef), 'mutation', operation, ...detail] as const),
} as const;

/**
 * Grid columns from the table model: which columns and relation fields show,
 * in what order, with what header. See `relations/relation-columns.ts` for
 * the rule. Columns never come from the keys of a loaded row, so values that
 * ride beside a row (relation totals, cell errors) can never become columns.
 * Headers are readable labels (`fieldLabel`); `id` stays the raw field name for
 * saved views, commands and `data-col-key`. The value type belongs to the
 * header's icon or tooltip, not to the label.
 */
import { useCallback, useMemo } from 'react';

import { isImageField, type FieldMetadata } from '../cell-types/cell-type-resolver';
import { fieldLabel, relationLabelIn } from '../cell-types/field-label';
import { getColumnWidthByMeta } from '../grid/sheets.utils';
import { gridColumnKeys } from '../relations/relation-columns';

import { useRelationMetadataCache, type RelationMetadata } from './use-relation-metadata-cache';

type RelationKind = 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';

/** Native column descriptor — key/title/width, mappable 1:1 to {@link SheetsColumnDescriptor}. */
export interface RelationGridColumn {
	id: string;
	title: string;
	width: number;
}

/**
 * Relation-aware column info with simple error handling
 */
export interface RelationColumnInfo {
	columns: RelationGridColumn[];
	columnKeys: string[];
	relationMetadata: Record<string, RelationMetadata>;
	metaFields?: FieldMetadata[];
	hasRelationErrors: boolean;
	relationCount: number;
	// Helper functions (backward compatible)
	isImageField: (fieldMeta: FieldMetadata | undefined, fieldName?: string) => boolean;
	findImageColumnKey: (columnKeys: string[], fieldMetaMap: Map<string, unknown>, currentColKey?: string) => string;
	getRelationKind: (fieldName: string) => RelationKind | null;
	isRelationField: (fieldName: string) => boolean;
	invalidateRelationCache: () => Promise<void>;
	// For backward compatibility
	relationTypeByField: Map<string, RelationKind>;
}

const SINGLE_RELATION_WIDTH = 160;
const LIST_RELATION_WIDTH = 220;
const DEFAULT_WIDTH = 150;

/**
 * Create data grid columns with relation metadata baked in.
 *
 * @param tableName - table name or `TableModel.key`.
 * @param _rows - ignored; columns come from the table model, not from loaded rows.
 */
export function useRelationColumns(tableName?: string, _rows?: unknown[]): RelationColumnInfo {
	const { model, relationMetadata, tableRelations, cacheState, getRelationKind, isRelationField, invalidateRelationCache } =
		useRelationMetadataCache(tableName);

	const metaFields = useMemo<FieldMetadata[] | undefined>(() => {
		return tableRelations?.fields.map((field) => ({
			name: field.name,
			type: field.type,
		}));
	}, [tableRelations]);

	const metaFieldByName = useMemo(() => {
		const map = new Map<string, FieldMetadata>();
		for (const field of metaFields ?? []) {
			if (field?.name) map.set(field.name, field);
		}
		return map;
	}, [metaFields]);

	const columnKeys = useMemo<string[]>(() => (model ? gridColumnKeys(model) : []), [model]);

	const relationMetadataMap = useMemo(() => {
		const map: Record<string, RelationMetadata> = {};
		relationMetadata.forEach((rel) => {
			map[rel.fieldName] = rel;
		});
		return map;
	}, [relationMetadata]);

	const columns: RelationGridColumn[] = useMemo(() => {
		const relationByField = new Map((model?.relations ?? []).map((relation) => [relation.fieldName, relation]));
		return columnKeys.map((fieldName) => {
			const relation = relationByField.get(fieldName);
			const metaField = metaFieldByName.get(fieldName);
			const width = relation
				? relation.kind === 'hasMany' || relation.kind === 'manyToMany'
					? LIST_RELATION_WIDTH
					: SINGLE_RELATION_WIDTH
				: metaField
					? getColumnWidthByMeta(metaField)
					: DEFAULT_WIDTH;
			return { id: fieldName, title: relation ? relationLabelIn(model, relation) : fieldLabel(fieldName), width } satisfies RelationGridColumn;
		});
	}, [columnKeys, metaFieldByName, model]);

	// Helper function using centralized image field detection
	const checkIsImageField = useCallback((fieldMeta: FieldMetadata | undefined, fieldName?: string): boolean => {
		return isImageField(fieldMeta, fieldName);
	}, []);

	// The column key of an image cell: the current column when it holds images, else the first image column.
	const findImageColumnKey = useCallback(
		(keys: string[], fieldMetaMap: Map<string, unknown>, currentColKey?: string): string => {
			if (currentColKey && fieldMetaMap.has(currentColKey)) {
				const fieldMeta = fieldMetaMap.get(currentColKey) as FieldMetadata | undefined;
				if (checkIsImageField(fieldMeta, currentColKey)) return currentColKey;
			}
			for (const key of keys) {
				const fieldMeta = fieldMetaMap.get(key) as FieldMetadata | undefined;
				if (fieldMeta && checkIsImageField(fieldMeta, key)) return key;
			}
			return currentColKey || keys[0] || '';
		},
		[checkIsImageField],
	);

	// Create backward compatibility map
	const relationTypeByField = useMemo(() => {
		const map = new Map<string, RelationKind>();
		Object.entries(relationMetadataMap).forEach(([fieldName, info]) => {
			map.set(fieldName, info.relationKind);
		});
		return map;
	}, [relationMetadataMap]);

	return {
		columns,
		columnKeys,
		relationMetadata: relationMetadataMap,
		metaFields,
		hasRelationErrors: cacheState.isError,
		relationCount: cacheState.relationCount,
		isImageField: checkIsImageField,
		findImageColumnKey,
		getRelationKind,
		isRelationField,
		invalidateRelationCache,
		relationTypeByField, // For backward compatibility
	};
}

/**
 * Drop-in replacement for the original useDataGridColumns hook
 * Maintains complete backward compatibility while providing improvements
 */
export function useDataGridColumns(tableName?: string, rows: unknown[] = []) {
	const enhanced = useRelationColumns(tableName, rows);

	// Return exact same interface as original for backward compatibility
	return {
		columns: enhanced.columns,
		columnKeys: enhanced.columnKeys,
		metaFields: enhanced.metaFields,
		isImageField: enhanced.isImageField,
		findImageColumnKey: enhanced.findImageColumnKey,
		relationTypeByField: enhanced.relationTypeByField,
		// Add new enhanced features for those who want them
		relationMetadata: enhanced.relationMetadata,
		hasRelationErrors: enhanced.hasRelationErrors,
		relationCount: enhanced.relationCount,
		getRelationKind: enhanced.getRelationKind,
		isRelationField: enhanced.isRelationField,
		invalidateRelationCache: enhanced.invalidateRelationCache,
	};
}

/**
 * Relation metadata for a table's columns, read from the table model.
 *
 * Keys come from the model (proven key pairs), never from table-name guesses.
 * The entries follow the grid's column rule (`gridRelations`), so they are
 * rebuilt whenever the model is (a `_meta` refetch builds a new model).
 */
import { useCallback, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';

import { cleanTable, type CleanTable, type TableModel } from '@constructive-io/data';
import { useSheetsContext } from '../context/sheets-context';
import { gridRelations } from '../relations/relation-columns';
import { sheetsQueryKeys, tableKeySegments } from './query-keys';
import { useTableModel } from './use-table-model';

export type RelationMetadataSource = 'relation' | 'foreignKey';

export interface RelationMetadata {
	tableName: string;
	fieldName: string;
	relationKind: 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';
	targetTable: string;
	isOptional: boolean;
	foreignKeyFields: string[];
	/** Headline relation field name when this metadata originates from a foreign key */
	relationFieldName?: string | null;
	/** Primary foreign key field associated with the relation */
	foreignKeyField?: string;
	/** Indicates whether the metadata entry is for the relation field or the FK column */
	sourceField: RelationMetadataSource;
	junctionTable?: string;
	displayName?: string;
}

/**
 * Simple error state tracking
 */
export interface RelationCacheState {
	isLoading: boolean;
	isError: boolean;
	error: Error | null;
	hasData: boolean;
	relationCount: number;
}

export interface RelationMetadataSet {
	relationFields: RelationMetadata[];
	foreignKeyFields: RelationMetadata[];
}

const NO_RELATIONS: RelationMetadataSet = { relationFields: [], foreignKeyFields: [] };

/** Relation and foreign-key column entries for one model. */
function relationMetadataOf(model: TableModel, tableName: string): RelationMetadataSet {
	const relationFields: RelationMetadata[] = [];
	const foreignKeyFields: RelationMetadata[] = [];

	for (const relation of gridRelations(model)) {
		const base = { tableName, relationKind: relation.kind, targetTable: relation.targetName, sourceField: 'relation' as const };
		if (relation.kind === 'belongsTo') {
			const keys = relation.keys.map((pair) => pair.local);
			relationFields.push({
				...base,
				fieldName: relation.fieldName,
				isOptional: relation.unlinkable,
				foreignKeyFields: keys,
				relationFieldName: relation.fieldName,
				foreignKeyField: keys[0],
			});
			for (const key of keys) {
				foreignKeyFields.push({
					...base,
					fieldName: key,
					isOptional: relation.unlinkable,
					foreignKeyFields: keys,
					relationFieldName: relation.fieldName,
					foreignKeyField: key,
					sourceField: 'foreignKey',
				});
			}
		} else if (relation.kind === 'manyToMany') {
			relationFields.push({
				...base,
				fieldName: relation.fieldName,
				isOptional: relation.unlinkable,
				foreignKeyFields: [],
				relationFieldName: relation.fieldName,
				junctionTable: relation.junction?.tableName,
			});
		} else {
			relationFields.push({
				...base,
				fieldName: relation.fieldName,
				isOptional: relation.unlinkable,
				foreignKeyFields: relation.keys.map((pair) => pair.local),
				relationFieldName: relation.fieldName,
				foreignKeyField: relation.keys[0]?.remote,
			});
		}
	}
	return { relationFields, foreignKeyFields };
}

/**
 * Cache and expose relation metadata for a table
 */
export function useRelationMetadataCache(tableName?: string) {
	const queryClient = useQueryClient();
	const { scopeKey } = useSheetsContext();
	const { model, metaTable, tableKey, isLoading, error } = useTableModel(tableName);

	const tableRelations = useMemo<CleanTable | null>(() => (metaTable ? cleanTable(metaTable) : null), [metaTable]);
	const { relationFields, foreignKeyFields } = useMemo(
		() => (model ? relationMetadataOf(model, tableName ?? model.name) : NO_RELATIONS),
		[model, tableName],
	);

	const relationMetadata = useMemo(() => relationFields.concat(foreignKeyFields), [relationFields, foreignKeyFields]);

	const relationMap = useMemo(() => {
		const map = new Map<string, RelationMetadata>();
		relationFields.forEach((rel) => {
			map.set(rel.fieldName, rel);
		});
		foreignKeyFields.forEach((rel) => {
			map.set(rel.fieldName, rel);
		});
		return map;
	}, [relationFields, foreignKeyFields]);

	// Rebuild the table model (and with it this metadata) from fresh types.
	const invalidateRelationCache = useCallback(async () => {
		if (!tableKey) return;
		await queryClient.invalidateQueries({
			queryKey: [...sheetsQueryKeys.scope(scopeKey), 'table-model', ...tableKeySegments(tableKey)],
		});
	}, [queryClient, scopeKey, tableKey]);

	// Get relation info for a specific field
	const getRelationInfo = useCallback(
		(fieldName: string): RelationMetadata | null => {
			return relationMap.get(fieldName) || null;
		},
		[relationMap],
	);

	// Check if field is a relation
	const isRelationField = useCallback(
		(fieldName: string): boolean => {
			return relationMap.has(fieldName);
		},
		[relationMap],
	);

	// Get relation kind for backward compatibility
	const getRelationKind = useCallback(
		(fieldName: string): 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany' | null => {
			const relation = relationMap.get(fieldName);
			return relation?.relationKind || null;
		},
		[relationMap],
	);

	const cacheState: RelationCacheState = useMemo(
		() => ({
			isLoading,
			isError: Boolean(error),
			error,
			hasData: relationMetadata.length > 0,
			relationCount: relationMetadata.length,
		}),
		[isLoading, error, relationMetadata.length],
	);

	return {
		// Data
		model,
		relationMetadata,
		relationFields,
		foreignKeyFields,
		relationMap,
		tableRelations,

		// State
		cacheState,
		isLoading,
		isError: Boolean(error),
		error,

		// Utilities
		getRelationInfo,
		isRelationField,
		getRelationKind,
		invalidateRelationCache,
	};
}

/**
 * Infinite scroll table hook with hybrid cursor-based pagination
 *
 * Uses a hybrid pagination strategy:
 * - Page 0: Offset-based (`first: N`) to get initial data + endCursor
 * - Page N+1: Cursor-based (`first: N, after: endCursor`) for efficient deep pagination
 *
 * This leverages PostGraphile's Relay Connection spec for optimal performance on large datasets.
 *
 * Data Persistence:
 * - Uses React Query cache as the source of truth for page data
 * - Data survives component unmount/remount and route changes
 * - Only clears when table name or query options actually change (deep comparison)
 *
 * Ported from apps/admin use-infinite-table.ts with context injection.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useQueries, useQueryClient } from '@tanstack/react-query';

import { useSheetsContext } from '../context/sheets-context';
import type { SheetsScopeKey } from '../context/sheets-context';

import { type MutationOptions, type PageInfo, type TableModel } from '@constructive-io/data';
import type { FieldSelection } from '@constructive-io/data';
import { reuseSheetsPlaceholderData } from './query-keys';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { sheetsQueryKeys } from './query-keys';
import { relationsFromSelection, sortSpecs, whereFilter } from './list-query';
import { useTableModel } from './use-table-model';

type RowRecord = Record<string, unknown>;

/** Data for a single loaded page */
export interface PageData<T = RowRecord> {
	rows: T[];
	pageInfo: PageInfo;
	pageIndex: number;
	totalCount?: number;
}

/** Options for the infinite table hook */
export interface UseInfiniteTableOptions {
	/** Page size for fetching */
	pageSize?: number;
	/** Order by clauses */
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
	/** A filter in the server's filter input shape (any operator the model reports, relation and search fields included). */
	where?: Readonly<Record<string, unknown>>;
	/** Columns to fetch (the primary key and relation keys are always added). Omitted: every readable column. */
	columns?: readonly string[];
	/** Field selection preset or custom selection */
	select?: FieldSelection;
	/** Enable/disable the hook */
	enabled?: boolean;
	/** Mutation options for CRUD operations */
	mutationOptions?: MutationOptions;
}

/** Result from the infinite table hook */
export interface UseInfiniteTableResult<T = RowRecord> {
	/** Get row at a specific index, returns null if not loaded */
	getRowAtIndex: (index: number) => T | null;
	/** Total count of rows in the table */
	totalCount: number;
	/** Check if a specific row index is loaded */
	isRowLoaded: (rowIndex: number) => boolean;
	/** Check if a specific page is currently loading */
	isPageLoading: (pageIndex: number) => boolean;
	/** Ensure rows in a range are loaded (call from onVisibleRegionChanged) */
	ensureRowsLoaded: (startRow: number, endRow: number) => void;
	/** All loaded pages */
	loadedPages: Map<number, PageData<T>>;
	/** Page size */
	pageSize: number;
	/** Overall loading state (true if any page is loading) */
	isLoading: boolean;
	/** True while a page request for the current options is in flight, also while placeholder rows from the previous options show */
	isFetching: boolean;
	/** Whether initial data has been loaded */
	hasInitialData: boolean;
	/** Error from the most recent failed fetch, or why the table model is unavailable */
	error: Error | null;
	/** The table model, or null while it loads or when it failed */
	model: TableModel | null;
	/** Invalidate all pages and refetch */
	invalidate: () => void;
	/** Reset to initial state (clears all pages, refetches page 0) */
	reset: () => void;
	/**
	 * Optimistically update a single row in the page cache without refetching.
	 * @param rowIndex The absolute row index
	 * @param patch Partial row data to merge with existing row
	 * @returns true if the row was found and updated, false otherwise
	 */
	updateRowAtIndex: (rowIndex: number, patch: Partial<T>) => boolean;
}

/** Query key factory for infinite table pages */
const sheetsInfiniteTableKeys = {
	all: (scope: SheetsScopeKey, tableName: string) => sheetsQueryKeys.infiniteTable(scope, tableName),
	page: (scope: SheetsScopeKey, tableName: string, pageIndex: number, optionsKey: string) =>
		[...sheetsQueryKeys.infiniteTable(scope, tableName), 'page', pageIndex, optionsKey] as const,
	totalCount: (scope: SheetsScopeKey, tableName: string, where?: Readonly<Record<string, unknown>>) =>
		sheetsQueryKeys.infiniteTableTotalCount(scope, tableName, where),
};

/**
 * Create a stable JSON key from options for deep comparison.
 * This ensures the key only changes when the actual values change, not object references.
 */
function createStableOptionsKey(options: {
	pageSize: number;
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
	where?: Readonly<Record<string, unknown>>;
	fieldSelection?: FieldSelection;
	columns?: readonly string[];
}): string {
	return JSON.stringify({
		columns: options.columns ?? null,
		pageSize: options.pageSize,
		orderBy: options.orderBy ?? null,
		where: options.where ?? null,
		fieldSelection: options.fieldSelection ?? null,
	});
}

/**
 * Hook for infinite scroll table with hybrid cursor-based pagination.
 * Uses React Query cache as the source of truth for data persistence.
 */
export function useSheetsInfiniteTable<T extends RowRecord = RowRecord>(
	tableName: string,
	options: UseInfiniteTableOptions = {},
): UseInfiniteTableResult<T> {
	const { pageSize = 100, orderBy, where, select: fieldSelection, columns, enabled = true } = options;

	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const {
		model: table,
		tableKey,
		error: modelError,
		refetch: refetchModel,
		isLoading: isModelLoading,
	} = useTableModel(tableName, { enabled });
	// Cache entries are keyed by `TableModel.key`; the bare name is only a fallback before `_meta` loads.
	const cacheRef = tableKey ?? tableName;
	const adapter = useSheetsAdapter();

	// Create stable options key using JSON serialization for deep comparison
	const stableOptionsKey = useMemo(
		() => createStableOptionsKey({ pageSize, orderBy, where, fieldSelection, columns }),
		[pageSize, orderBy, where, fieldSelection, columns],
	);

	// Track which pages we want to load
	const [requestedPages, setRequestedPages] = useState<Set<number>>(() => new Set([0]));

	// Cursor chain for cursor-based pagination (stored in ref for performance)
	const cursorChainRef = useRef<Map<number, string>>(new Map());
	const [cursorChainVersion, setCursorChainVersion] = useState(0);

	// Track latest total count from any page response
	const totalCountRef = useRef<number>(0);

	// Flag to defer cache invalidation to useEffect after synchronous reset
	const needsInvalidationRef = useRef(false);

	// Generation counter: incremented on every table/options reset. queryFn closures capture
	// the current generation and skip cursor writes if stale. This prevents in-flight queries
	// from a previous table/options context from poisoning cursorChainRef after a reset.
	// (PostGraphile v5 cursors include a digest hash scoped to table + ORDER BY, so a cursor
	// from one query context will be rejected by a different query context.)
	const generationRef = useRef(0);

	// Track previous stable key to detect actual changes
	const prevStableKeyRef = useRef<string>(stableOptionsKey);
	const prevTableNameRef = useRef<string>(tableName);

	// Synchronous render-time reset: clear cursors and state BEFORE pageQueries useMemo reads them.
	// This follows the React 18+ "storing information from previous renders" pattern where setState
	// during render causes React to discard the current render and retry with updated state.
	// On retry, the condition is false (refs already updated) so no infinite loop occurs.
	const tableChanged = prevTableNameRef.current !== tableName;
	const optionsChanged = prevStableKeyRef.current !== stableOptionsKey;

	if (tableChanged || optionsChanged) {
		// Clear cursors synchronously — must happen before pageQueries useMemo
		cursorChainRef.current.clear();
		totalCountRef.current = 0;

		// Bump generation so in-flight queryFn closures from the old context
		// will skip writing their stale cursors into cursorChainRef
		generationRef.current += 1;

		// Update tracking refs so condition is false on retry render
		prevTableNameRef.current = tableName;
		prevStableKeyRef.current = stableOptionsKey;

		// Flag cache invalidation for the subsequent useEffect
		needsInvalidationRef.current = true;

		// Trigger state update — React discards current render and retries
		setCursorChainVersion(0);
		setRequestedPages(new Set([0]));
	}

	// Cache invalidation is a side effect and must stay in useEffect
	useEffect(() => {
		if (needsInvalidationRef.current) {
			needsInvalidationRef.current = false;
			queryClient.invalidateQueries({
				queryKey: sheetsInfiniteTableKeys.all(scopeKey, cacheRef),
			});
		}
	}, [cacheRef, stableOptionsKey, queryClient, scopeKey]);

	// Page data straight from the React Query cache, so an optimistic `setQueryData` reads back at
	// once. Each page's query hash is computed once: a row read is O(1), never a key hash.
	const pageHashes = useMemo(() => new Map<number, string>(), [scopeKey, cacheRef, stableOptionsKey]);
	const getPageDataFromCache = useCallback(
		(pageIndex: number): PageData<T> | undefined => {
			let hash = pageHashes.get(pageIndex);
			if (hash === undefined) {
				const queryKey = sheetsInfiniteTableKeys.page(scopeKey, cacheRef, pageIndex, stableOptionsKey);
				hash = queryClient.defaultQueryOptions({ queryKey }).queryHash;
				pageHashes.set(pageIndex, hash);
			}
			return queryClient.getQueryCache().get<PageData<T>>(hash)?.state.data;
		},
		[queryClient, pageHashes, scopeKey, cacheRef, stableOptionsKey],
	);

	// Create query options for each requested page
	const pageQueries = useMemo(() => {
		if (!table || !enabled) return [];
		// Force recompute when cursor chain advances
		void cursorChainVersion;

		// Capture generation at useMemo time — queryFn closures use this to detect
		// if the query context has changed (table/options reset) before they write cursors
		const queryGeneration = generationRef.current;

		return Array.from(requestedPages).map((pageIndex) => {
			// Determine pagination strategy
			const isFirstPage = pageIndex === 0;
			const previousCursor = pageIndex > 0 ? cursorChainRef.current.get(pageIndex - 1) : undefined;
			// Pages:
			// - 0: always fetch
			// - 1: wait for cursor from page 0 (prefer cursor-based)
			// - 2+: allow offset fallback (supports scrollbar jumps without loading all intermediate pages)
			const canUseOffsetFallback = pageIndex >= 2;
			const canFetch = isFirstPage || previousCursor !== undefined || canUseOffsetFallback;

			return {
				queryKey: sheetsInfiniteTableKeys.page(scopeKey, cacheRef, pageIndex, stableOptionsKey),
				queryFn: async ({ signal }: { signal: AbortSignal }): Promise<PageData<T>> => {
					// Prefer cursor-based pagination when possible; allow offset fallback for deep jumps.
					// The connection's page info is always selected, so the cursor chain works on every page.
					const after = !isFirstPage && previousCursor ? previousCursor : undefined;
					const offset = !isFirstPage && !previousCursor && canUseOffsetFallback ? pageIndex * pageSize : undefined;
					// The total belongs to the scope (filter, sort, page size), so only its first page counts
					// it. Creates and deletes invalidate every page, which counts again.
					const countsTotal = isFirstPage;

					const res = await adapter.listRows<T>(
						{ model: table, tableName },
						{
							limit: pageSize,
							after,
							offset,
							where: whereFilter(where),
							orderBy: sortSpecs(orderBy),
							relations: relationsFromSelection(fieldSelection),
							columns,
							includeTotalCount: countsTotal,
							signal,
						},
						execute,
					);

					const rows = res.rows;
					// The adapter's AdapterPageInfo marks booleans optional; the underlying
					// PostGraphile connection always populates them (the doc selects all four),
					// so this narrows to PageInfo exactly as the inline connection cast did.
					const pageInfo: PageInfo = (res.pageInfo as PageInfo | undefined) || {
						hasNextPage: false,
						hasPreviousPage: false,
						endCursor: null,
						startCursor: null,
					};

					// Guard: only write refs if this queryFn's generation matches the current one.
					// In-flight queries from a previous table/options context will have a stale
					// generation and their writes are silently discarded.
					const isCurrentGeneration = queryGeneration === generationRef.current;

					// Update total count ref
					if (countsTotal && isCurrentGeneration) {
						totalCountRef.current = res.totalCount;
					}

					// Store cursor for next page (and bump version so dependent pages can enable)
					if (pageInfo.endCursor && isCurrentGeneration) {
						const prev = cursorChainRef.current.get(pageIndex);
						if (prev !== pageInfo.endCursor) {
							cursorChainRef.current.set(pageIndex, pageInfo.endCursor);
							setCursorChainVersion((v) => v + 1);
						}
					}

					const pageData: PageData<T> = {
						rows,
						pageInfo,
						pageIndex,
						totalCount: countsTotal ? res.totalCount : undefined,
					};

					return pageData;
				},
				enabled: enabled && !!table && canFetch,
				// Reuse a page across sort/filter/page-size key changes only while the
				// endpoint, database, and authenticated identity remain unchanged.
				placeholderData: (
					previousData: PageData<T> | undefined,
					previousQuery: { queryKey: readonly unknown[] } | undefined,
				) =>
					reuseSheetsPlaceholderData(previousData, previousQuery?.queryKey, scopeKey),
				staleTime: 5 * 60 * 1000, // 5 minutes
				gcTime: 10 * 60 * 1000, // 10 minutes
			};
		});
		}, [
			table,
			tableName,
			cacheRef,
			enabled,
			scopeKey,
			queryClient,
			execute,
			adapter,
			requestedPages,
			stableOptionsKey,
			pageSize,
		orderBy,
		where,
		fieldSelection,
		cursorChainVersion,
	]);

	// Execute all page queries
	const queryResults = useQueries({ queries: pageQueries });

	// Sync cursor chain from React Query cache on mount/rehydration
	// This restores cursors for pages that were cached but cursor chain was lost.
	// Guarded by generation to avoid restoring stale cursors during a reset transition.
	useEffect(() => {
		if (!enabled || !table) return;

		const gen = generationRef.current;

		// Check React Query cache for existing page data and restore cursors
		for (let i = 0; i < 100; i++) {
			// Bail if generation changed (a reset happened while this effect was running)
			if (gen !== generationRef.current) break;

			// Check up to 100 pages
			const cachedData = getPageDataFromCache(i);
			if (cachedData?.pageInfo?.endCursor && !cursorChainRef.current.has(i)) {
				cursorChainRef.current.set(i, cachedData.pageInfo.endCursor);
			}
			if (cachedData?.totalCount !== undefined) {
				totalCountRef.current = cachedData.totalCount;
			}
			if (!cachedData) break; // Stop at first missing page
		}
	}, [enabled, table, getPageDataFromCache]);

	// Compute loading states. Until the table model resolves no page query exists, so loading
	// covers the model too; otherwise the grid paints empty before its loading placeholder.
	const isLoading = isModelLoading || queryResults.some((result) => result.isLoading);
	const isFetching = queryResults.some((result) => result.isFetching);

	// The requested pages' results by page index. `useQueries` returns new result objects on every
	// render, so this map, and every read built on it, changes only when a page's data, loading
	// state or error changes. A render that changes no page (a cursor move, a typed key) keeps the
	// row reads below, and the row array built on them, as they were.
	const pagesKey = queryResults.map((result) => `${dataIdOf(result.data)}${result.isLoading ? 'L' : ''}${result.error ? 'E' : ''}`).join(',');
	const pages = useMemo(() => {
		const byPage = new Map<number, (typeof queryResults)[number]>();
		Array.from(requestedPages).forEach((pageIndex, index) => {
			const result = queryResults[index];
			if (result) byPage.set(pageIndex, result);
		});
		return byPage;
		// eslint-disable-next-line react-hooks/exhaustive-deps -- `pagesKey` covers every result's data, loading state and error
	}, [requestedPages, pagesKey]);

	// The page holding a row: the cache first (it already holds an optimistic update), else the result.
	const pageOf = useCallback(
		(pageIndex: number): PageData<T> | undefined => getPageDataFromCache(pageIndex) ?? pages.get(pageIndex)?.data,
		[getPageDataFromCache, pages],
	);

	// Check if we have initial data - either from current query or from cache
	const hasInitialData = useMemo(() => pageOf(0) !== undefined, [pageOf]);

	const error = queryResults.find((result) => result.error)?.error ?? (enabled ? modelError : null);

	const getRowAtIndex = useCallback(
		(rowIndex: number): T | null => pageOf(Math.floor(rowIndex / pageSize))?.rows[rowIndex % pageSize] ?? null,
		[pageSize, pageOf],
	);

	const isRowLoaded = useCallback(
		(rowIndex: number): boolean => {
			const page = pageOf(Math.floor(rowIndex / pageSize));
			return page !== undefined && rowIndex % pageSize < page.rows.length;
		},
		[pageSize, pageOf],
	);

	const isPageLoading = useCallback((pageIndex: number): boolean => pages.get(pageIndex)?.isLoading ?? false, [pages]);

	// Ensure rows in range are loaded
	const ensureRowsLoaded = useCallback(
		(startRow: number, endRow: number) => {
			const startPage = Math.floor(Math.max(0, startRow) / pageSize);
			const endPage = Math.floor(Math.max(0, endRow - 1) / pageSize);

			const minPage = Math.max(0, startPage);
			const maxPage = endPage;

			setRequestedPages((prev) => {
				const next = new Set(prev);
				let changed = false;

				const maxPossiblePage =
					totalCountRef.current > 0 ? Math.max(0, Math.ceil(totalCountRef.current / pageSize) - 1) : null;
				const cappedMaxPage = maxPossiblePage === null ? maxPage : Math.min(maxPage, maxPossiblePage);

				for (let page = minPage; page <= cappedMaxPage; page++) {
					if (!next.has(page)) {
						next.add(page);
						changed = true;
					}
				}

				return changed ? next : prev;
			});
		},
		[pageSize],
	);

	// Build loadedPages map from React Query cache for backward compatibility
	const loadedPages = useMemo(() => {
		const map = new Map<number, PageData<T>>();
		for (const [pageIndex, result] of pages) if (result.data) map.set(pageIndex, result.data);
		return map;
	}, [pages]);

	// Compute total count from query results or ref
	const totalCount = useMemo(() => {
		for (const result of pages.values()) {
			if (result.data?.totalCount !== undefined) return result.data.totalCount;
		}
		return totalCountRef.current;
	}, [pages]);

	// Invalidate all pages
	const invalidate = useCallback(() => {
		// A table whose model failed has no pages yet: load the model again; its pages follow.
		if (!table) {
			void refetchModel();
			return;
		}
		// Clear cursor chain and bump generation to discard in-flight stale cursors
		cursorChainRef.current.clear();
		totalCountRef.current = 0;
		generationRef.current += 1;
		setCursorChainVersion(0);

		// Reset to page 0
		setRequestedPages(new Set([0]));

		// Invalidate React Query cache
		queryClient.invalidateQueries({ queryKey: sheetsInfiniteTableKeys.all(scopeKey, cacheRef) });
	}, [queryClient, scopeKey, cacheRef, table, refetchModel]);

	// Reset to initial state
	const reset = useCallback(() => {
		invalidate();
	}, [invalidate]);

	// Optimistically update a single row in the React Query cache
	const updateRowAtIndex = useCallback(
		(rowIndex: number, patch: Partial<T>): boolean => {
			const pageIndex = Math.floor(rowIndex / pageSize);
			const rowIndexInPage = rowIndex % pageSize;

			const queryKey = sheetsInfiniteTableKeys.page(scopeKey, cacheRef, pageIndex, stableOptionsKey);
			const cachedData = queryClient.getQueryData<PageData<T>>(queryKey);

			if (!cachedData || !cachedData.rows[rowIndexInPage]) {
				return false;
			}

			// Update the cache optimistically
			queryClient.setQueryData<PageData<T>>(queryKey, (old) => {
				if (!old) return old;

				const newRows = [...old.rows];
				newRows[rowIndexInPage] = { ...newRows[rowIndexInPage], ...patch } as T;

				return {
					...old,
					rows: newRows,
				};
			});

			return true;
		},
		[pageSize, queryClient, scopeKey, cacheRef, stableOptionsKey],
	);

	// One object per change of what it holds, so memoized consumers keep theirs across other renders.
	return useMemo(
		() => ({
			getRowAtIndex,
			totalCount,
			isRowLoaded,
			isPageLoading,
			ensureRowsLoaded,
			loadedPages,
			pageSize,
			isLoading,
			isFetching,
			hasInitialData,
			error: error as Error | null,
			model: table,
			invalidate,
			reset,
			updateRowAtIndex,
		}),
		[getRowAtIndex, totalCount, isRowLoaded, isPageLoading, ensureRowsLoaded, loadedPages, pageSize, isLoading, isFetching, hasInitialData, error, table, invalidate, reset, updateRowAtIndex],
	);
}

const dataIds = new WeakMap<object, number>();
let lastDataId = 0;

/** A number per data object, the same for the object's lifetime: its identity, usable in a key. */
function dataIdOf(data: unknown): number {
	if (data === null || typeof data !== 'object') return 0;
	let id = dataIds.get(data);
	if (id === undefined) {
		lastDataId += 1;
		id = lastDataId;
		dataIds.set(data, id);
	}
	return id;
}

/**
 * Export query keys for external cache management
 */
export { sheetsInfiniteTableKeys };

// Preview URLs for stored files.
//
// A projection with a durable public `url` is shown as is. Otherwise the file
// id is resolved to a signed download URL, batched across the visible cells
// (one request per 100 ids), and cached in the authenticated query cache. A
// signed URL never enters a cell value: it expires.
//
// The caller passes the column's URL resolver (`ColumnStorage.resolveUrls`,
// built from the storage-side files table model). Without one, the fallback
// shape discovery resolves the id on the storage endpoint.

import { useCallback, useMemo, useRef, useState } from 'react';
import { skipToken, useQuery } from '@tanstack/react-query';

import { useSheetsContext, type SheetsScopeKey, type SheetsStorageTransport } from '../context/sheets-context';
import { fetchMediaDownloadUrls } from '../context/sheets-upload-presigned';
import { storedFilesOf } from '../utils/file.utils';
import { sheetsQueryKeys } from './query-keys';

const MAX_BATCH_SIZE = 100;
const REFRESH_INTERVAL = 50 * 60 * 1000;
// A file with no signed URL stays unresolved for a while, so remounts and focus
// don't send the same lookup again on every scroll pass.
const UNRESOLVED_STALE_TIME = 60 * 1000;
// A file can have no URL yet because the storage service confirms an upload in the
// background. Such a file is looked up again on a short backoff, then left alone, so
// a fresh upload shows its preview once confirmed and a file the reader cannot see
// costs only these few batched lookups.
const UNRESOLVED_RETRY_DELAYS = [2_000, 4_000, 8_000, 16_000, 30_000];

/** Resolves download URLs for file ids; ids without a URL have no entry. */
export type ResolveDownloadUrls = (ids: readonly string[]) => Promise<Map<string, string>>;

export interface MediaUrlResolver {
	/** Identity of the resolver (the files table it reads), for batching and caching. */
	key: string;
	resolve: ResolveDownloadUrls;
}

interface PendingLookup {
	id: string;
	signal: AbortSignal;
	resolve: (url: string | null) => void;
	reject: (error: unknown) => void;
}

type MediaLoader = (id: string, signal: AbortSignal) => Promise<string | null>;
/** One batching loader per scope and resolver; the fallback discovery has one per storage transport. */
const loaders = new WeakMap<SheetsScopeKey, Map<string, MediaLoader>>();
const fallbackLoaders = new WeakMap<SheetsStorageTransport, WeakMap<SheetsScopeKey, MediaLoader>>();

function createMediaLoader(resolve: (getActiveIds: () => readonly string[]) => Promise<Map<string, string>>): MediaLoader {
	let pending: PendingLookup[] = [];

	async function fetchBatch(requests: PendingLookup[]) {
		// Read the active ids late so a canceled scope cannot send a lookup through
		// an executor whose auth has since changed.
		const getActiveIds = () => [...new Set(requests.filter(({ signal }) => !signal.aborted).map(({ id }) => id))];
		try {
			const urls = getActiveIds().length ? await resolve(getActiveIds) : null;
			for (const request of requests) {
				request.resolve(request.signal.aborted ? null : urls?.get(request.id) ?? null);
			}
		} catch (error) {
			for (const request of requests) request.reject(error);
		}
	}

	function flush() {
		const requests = pending;
		pending = [];
		for (let start = 0; start < requests.length; start += MAX_BATCH_SIZE) {
			void fetchBatch(requests.slice(start, start + MAX_BATCH_SIZE));
		}
	}

	return (id, signal) => new Promise((resolve, reject) => {
		if (pending.length === 0) queueMicrotask(flush);
		pending.push({ id, signal, resolve, reject });
	});
}

const FALLBACK_KEY = 'discovery';

function getMediaLoader(scopeKey: SheetsScopeKey, resolver: MediaUrlResolver): MediaLoader {
	let byResolver = loaders.get(scopeKey);
	if (!byResolver) {
		byResolver = new Map();
		loaders.set(scopeKey, byResolver);
	}
	let load = byResolver.get(resolver.key);
	if (!load) {
		load = createMediaLoader((getActiveIds) => resolver.resolve(getActiveIds()));
		byResolver.set(resolver.key, load);
	}
	return load;
}

function getFallbackLoader(storage: SheetsStorageTransport, scopeKey: SheetsScopeKey): MediaLoader {
	let scopes = fallbackLoaders.get(storage);
	if (!scopes) {
		scopes = new WeakMap();
		fallbackLoaders.set(storage, scopes);
	}
	let load = scopes.get(scopeKey);
	if (!load) {
		load = createMediaLoader((getActiveIds) => fetchMediaDownloadUrls(storage, getActiveIds));
		scopes.set(scopeKey, load);
	}
	return load;
}

export interface UseSheetsMediaUrlOptions {
	/** Resolve a preview at all. False for a file that is not an image. Default true. */
	previewImage?: boolean;
	/** The column's URL resolver. Null means previews cannot be signed; undefined uses the fallback discovery. */
	resolver?: MediaUrlResolver | null;
}

/**
 * Preview URL for one stored file (a projection or a link). Keeps signed URLs
 * in the authenticated preview cache, separate from cell values.
 */
export function useSheetsMediaUrl(value: unknown, options: UseSheetsMediaUrlOptions = {}) {
	const { previewImage = true, resolver } = options;
	const { storage, scopeKey } = useSheetsContext();
	const file = storedFilesOf(value)[0] ?? null;
	const durableUrl = file?.url ?? null;
	const id = file?.id ?? null;
	const endpoint = storage?.endpoint;
	const resolverKey = resolver === undefined ? FALLBACK_KEY : resolver?.key ?? null;
	const resource = useMemo(() => ({ scopeKey, endpoint, id, resolverKey }), [scopeKey, endpoint, id, resolverKey]);
	const load = !id || !previewImage || durableUrl
		? null
		: resolver
			? getMediaLoader(scopeKey, resolver)
			: resolver === undefined && storage ? getFallbackLoader(storage, scopeKey) : null;

	const query = useQuery({
		queryKey: [...sheetsQueryKeys.mediaUrl(scopeKey, endpoint, id), resolverKey],
		queryFn: load ? ({ signal }) => load(id!, signal) : skipToken,
		staleTime: (query) => query.state.data ? REFRESH_INTERVAL : UNRESOLVED_STALE_TIME,
		gcTime: REFRESH_INTERVAL,
		refetchInterval: (query) => {
			if (query.state.status !== 'success') return false;
			if (query.state.data) return REFRESH_INTERVAL;
			// `dataUpdateCount` counts the finished lookups: the first one, then each retry.
			return UNRESOLVED_RETRY_DELAYS[query.state.dataUpdateCount - 1] ?? false;
		},
		refetchOnWindowFocus: true,
		retry: false,
	});
	const signedUrl = previewImage && !durableUrl && !query.isPlaceholderData ? query.data ?? null : null;
	const [failed, setFailed] = useState<{ resource: typeof resource; url: string } | null>(null);
	const retried = useRef<typeof resource | null>(null);
	const { refetch } = query;

	const onImageError = useCallback(() => {
		if (!signedUrl) return;
		setFailed({ resource, url: signedUrl });
		if (retried.current === resource) return;
		retried.current = resource;
		void refetch({ cancelRefetch: false });
	}, [refetch, resource, signedUrl]);

	const onImageLoad = useCallback(() => {
		if (retried.current !== resource) return;
		retried.current = null;
		setFailed(null);
	}, [resource]);

	const url = durableUrl ?? (failed?.resource === resource && failed.url === signedUrl ? null : signedUrl);
	return { url, durableUrl, id, isLoading: query.isFetching && !url, onImageError, onImageLoad };
}

// src/hooks/use-sheets-meta.ts
import { useQuery, type UseQueryResult } from '@tanstack/react-query';

import type { MetaQuery } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext, type SheetsScopeKey } from '../context/sheets-context';
import { sheetsQueryKeys } from './query-keys';

export const metaKey = (scope: SheetsScopeKey) => sheetsQueryKeys.meta(scope);

export interface UseMetaOptions {
	enabled?: boolean;
}

export function useSheetsMeta(options: UseMetaOptions = {}): UseQueryResult<MetaQuery, Error> {
	const { enabled = true } = options;
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	return useQuery<MetaQuery, Error>({
		queryKey: metaKey(scopeKey),
		queryFn: () => adapter.fetchMeta(execute),
		staleTime: 5 * 60 * 1000, // 5 min - finite so invalidation + remount triggers refetch
		gcTime: 30 * 60 * 1000, // 30 min - survive long schema-editing sessions
		refetchOnMount: true, // Respect staleTime and refetch stale metadata on mount
		enabled,
	});
}

/**
 * Cursor-based paginated table hook for "load more" patterns.
 *
 * Uses TanStack Query v5 `useInfiniteQuery` with PostGraphile Relay Connection
 * cursor pagination (first/after + pageInfo).
 *
 * Designed for sequential "load more" use cases (e.g., relation picker overlays).
 * For non-sequential virtual grid scrolling, see `useSheetsInfiniteTable`.
 */
import { useMemo } from 'react';
import { useInfiniteQuery } from '@tanstack/react-query';

import { useSheetsContext } from '../context/sheets-context';

import type { FieldSelection, PageInfo } from '@constructive-io/data';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { sheetsQueryKeys } from './query-keys';
import { relationsFromSelection, sortSpecs, whereFilter } from './list-query';
import { useTableModel } from './use-table-model';

type RowRecord = Record<string, unknown>;

export interface UseSheetsTableCursorOptions {
	enabled?: boolean;
	select?: FieldSelection;
	pageSize?: number;
	/** A filter in the server's filter input shape. */
	where?: Readonly<Record<string, unknown>>;
	/** Columns to fetch (the primary key and relation keys are always added). Omitted: every readable column. */
	columns?: readonly string[];
	orderBy?: Array<{ field: string; direction: 'asc' | 'desc' }>;
}

export interface UseSheetsTableCursorResult<TData extends RowRecord = RowRecord> {
	data: TData[];
	totalCount: number;
	isLoading: boolean;
	isFetchingNextPage: boolean;
	hasNextPage: boolean;
	fetchNextPage: () => void;
	error: Error | null;
}

interface CursorPage<TData = RowRecord> {
	rows: TData[];
	totalCount: number;
	pageInfo: PageInfo;
}

export function useSheetsTableCursor<TData extends RowRecord = RowRecord>(
	tableName: string,
	options: UseSheetsTableCursorOptions = {},
): UseSheetsTableCursorResult<TData> {
	const { enabled = true, select: fieldSelection, pageSize = 20, where, orderBy, columns } = options;
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const { model: table, tableKey, error: modelError } = useTableModel(tableName, { enabled });
	// Cache entries are keyed by `TableModel.key`; the bare name is only a fallback before `_meta` loads.
	const cacheRef = tableKey ?? tableName;

	// Stable options key for query cache (excludes enabled/pageSize which don't affect data identity)
	const stableOptions = useMemo(
		() => ({ fieldSelection, where, orderBy, columns }),
		[fieldSelection, where, orderBy, columns],
	);

	const {
		data,
		isLoading,
		isFetchingNextPage,
		hasNextPage,
		fetchNextPage,
		error,
	} = useInfiniteQuery<CursorPage<TData>, Error>({
		queryKey: sheetsQueryKeys.cursorTable(scopeKey, cacheRef, stableOptions),
		queryFn: async ({ pageParam, signal }) => {
			if (!table) throw modelError ?? new Error(`Table '${tableName}' not found`);
			const cursor = pageParam as string | undefined;
			const res = await adapter.listRows<TData>(
				{ model: table, tableName },
				{
					limit: pageSize,
					after: cursor,
					where: whereFilter(where),
					orderBy: sortSpecs(orderBy),
					relations: relationsFromSelection(fieldSelection),
					columns,
					signal,
				},
				execute,
			);

			// The adapter's AdapterPageInfo marks booleans optional; the underlying
			// PostGraphile connection always populates them, so this narrows to PageInfo
			// exactly as the inline connection cast did. The fallback default mirrors the
			// prior direct-array branch byte-for-byte.
			const pageInfo: PageInfo = (res.pageInfo as PageInfo | undefined) ?? {
				hasNextPage: false,
				hasPreviousPage: false,
			};

			return {
				rows: res.rows,
				totalCount: res.totalCount,
				pageInfo,
			};
		},
		initialPageParam: undefined as string | undefined,
		getNextPageParam: (lastPage) =>
			lastPage.pageInfo.hasNextPage && lastPage.pageInfo.endCursor
				? lastPage.pageInfo.endCursor
				: undefined,
		enabled: enabled && !!table,
		staleTime: 5 * 60 * 1000,
	});

	const flatData = useMemo<TData[]>(
		() => data?.pages.flatMap((page) => page.rows) ?? [],
		[data],
	);

	const totalCount = useMemo(
		() => data?.pages[data.pages.length - 1]?.totalCount ?? 0,
		[data],
	);

	return {
		data: flatData,
		totalCount,
		isLoading,
		isFetchingNextPage,
		hasNextPage: hasNextPage ?? false,
		fetchNextPage,
		error: error ?? (enabled ? modelError : null),
	};
}

/**
 * Unified hooks system for table operations
 * Consolidates all table operations into a single, powerful hook
 *
 * Ported from apps/admin use-table.ts with context injection. Every document
 * is built from the table model (see `useTableModel`).
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
import { partialResultOf } from '../context/sheets-execute';
import type { SheetsScopeKey } from '../context/sheets-context';

import { buildFindOneDocument, createError, type TableModel } from '@constructive-io/data';
import type { FieldSelection, MutationOptions, QueryOptions } from '@constructive-io/data';
import { reuseSheetsPlaceholderData, sheetsMutationKeys, sheetsQueryKeys } from './query-keys';
import { relationsFromSelection, sortSpecs, whereFilter } from './list-query';
import { useTableModel } from './use-table-model';
import {
	resolveSheetsIdentifier,
	resolveSheetsRowIdentity,
	sheetsIdentifierCacheKey,
	sheetsIdentifierToRowKey,
	type SheetsRowIdentifier,
} from '../row-identity';

type RowRecord = Record<string, unknown>;
type DeleteIdentifier = SheetsRowIdentifier;

/**
 * Unified table hook options
 */
export interface UseTableOptions extends Omit<QueryOptions, 'where'> {
	/** A filter in the server's filter input shape (any operator the model reports, relation and search fields included). */
	where?: Readonly<Record<string, unknown>>;
	/** Columns to fetch (the primary key and relation keys are always added). Omitted: every readable column. */
	columns?: readonly string[];
	/** Enable/disable automatic data fetching */
	enabled?: boolean;
	/** Field selection for queries: `includeRelations` (or the `full` preset) chooses the relations to select. */
	select?: FieldSelection;
	/** Mutation options */
	mutationOptions?: MutationOptions;
}

/**
 * Unified table hook result
 */
export interface UseTableResult<TData extends RowRecord = RowRecord> {
	// Data
	data: TData[];
	totalCount: number;
	isLoading: boolean;
	/** True while a request for the current options is in flight, also while the previous rows are still shown. */
	isFetching: boolean;
	error: Error | null;

	/** The table model, or null while it loads or when it failed. */
	model: TableModel | null;

	// Single row operations
	findOne: (id: SheetsRowIdentifier) => Promise<TData | null>;

	// Mutations
	create: (data: RowRecord) => Promise<{ createdRow: TData | null }>;
	update: (id: SheetsRowIdentifier, patch: RowRecord) => Promise<{ updatedRow: TData | null }>;
	delete: (id: DeleteIdentifier) => Promise<{ deletedId: DeleteIdentifier }>;

	// Mutation states
	isCreating: boolean;
	isUpdating: boolean;
	isDeleting: boolean;

	// Mutation errors
	createError: Error | null;
	updateError: Error | null;
	deleteError: Error | null;

	// Utilities
	refetch: () => Promise<unknown>;
	invalidate: () => void;
}

/**
 * Generate query keys for consistent cache management. `tableRef` is a
 * `TableModel.key` or a table name.
 */
export const sheetsTableQueryKeys = {
	scope: (scope: SheetsScopeKey) => sheetsQueryKeys.scope(scope),
	table: (scope: SheetsScopeKey, tableRef: string) => sheetsQueryKeys.table(scope, tableRef),
	tableRows: (scope: SheetsScopeKey, tableRef: string, options?: unknown) =>
		sheetsQueryKeys.tableRows(scope, tableRef, options),
	tableRow: (scope: SheetsScopeKey, tableRef: string, id: unknown) =>
		sheetsQueryKeys.tableRow(scope, tableRef, id),
	tableCount: (scope: SheetsScopeKey, tableRef: string, where?: Readonly<Record<string, unknown>>) =>
		sheetsQueryKeys.tableCount(scope, tableRef, where),
};

/**
 * Main unified table hook
 * Returns all table operations in a single hook
 */
export function useSheetsTable<TData extends RowRecord = RowRecord>(
	tableName: string,
	options: UseTableOptions = {},
): UseTableResult<TData> {
	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const {
		model,
		tableKey,
		metaTable: tableMeta,
		isLoading: isModelLoading,
		error: modelError,
		refetch: refetchModel,
	} = useTableModel(tableName);
	// Cache entries are keyed by `TableModel.key`; the bare name is only a fallback before `_meta` loads.
	const cacheRef = tableKey ?? tableName;

	const requireModel = (): TableModel => {
		if (model) return model;
		throw modelError ?? createError.notFound(`Table '${tableName}' not found`);
	};

	const resolveIdentifier = (identifier: SheetsRowIdentifier): SheetsRowIdentifier => {
		if (!tableMeta) throw createError.notFound(`Table '${tableName}' not found`);
		const resolution = resolveSheetsIdentifier(tableMeta, identifier);
		if (resolution.status !== 'identified') {
			throw createError.badRequest(`Cannot resolve a primary-key identity for table '${tableName}'.`);
		}
		return resolution.identifier;
	};

	const rowCacheKey = (row: RowRecord | null | undefined): string | number | null => {
		if (!tableMeta || !row) return null;
		const resolution = resolveSheetsRowIdentity(tableMeta, row);
		if (resolution.status !== 'identified') return null;
		return typeof resolution.identifier === 'object' ? resolution.key : resolution.identifier;
	};

	// Extract options
	const { enabled = true, select: fieldSelection, mutationOptions = {}, ...queryOptions } = options;

	// Update query options with field selection
	const finalQueryOptions = {
		...queryOptions,
		fieldSelection,
	};

	// Data fetching with error handling
	const {
		data,
		isLoading: isRowsLoading,
		isFetching,
		error: rowsError,
		refetch,
	} = useQuery<{ rows: TData[]; totalCount: number }>({
		queryKey: sheetsTableQueryKeys.tableRows(scopeKey, cacheRef, finalQueryOptions),
		queryFn: async ({ signal }) => {
			const where = whereFilter(finalQueryOptions.where);
			// The total depends on the filter only, so turning a page or re-sorting reuses it.
			// Creates, updates and deletes invalidate it with the rest of the table.
			const countKey = sheetsTableQueryKeys.tableCount(scopeKey, cacheRef, where);
			const known = queryClient.getQueryState<number>(countKey);
			const knownCount = known?.status === 'success' && !known.isInvalidated ? known.data : undefined;
			const { rows, totalCount } = await adapter.listRows<TData>(
				{ model: requireModel(), tableName },
				{
					where,
					orderBy: sortSpecs(finalQueryOptions.orderBy),
					limit: finalQueryOptions.limit ?? finalQueryOptions.first,
					offset: finalQueryOptions.offset,
					after: finalQueryOptions.after,
					relations: relationsFromSelection(fieldSelection),
					columns: finalQueryOptions.columns,
					includeTotalCount: knownCount === undefined,
					signal,
				},
				execute,
			);
			if (knownCount !== undefined) return { rows, totalCount: knownCount };
			queryClient.setQueryData(countKey, totalCount);
			return { rows, totalCount };
		},
		enabled: enabled && !!model,
		placeholderData: (previousData, previousQuery) =>
			reuseSheetsPlaceholderData(previousData, previousQuery?.queryKey, scopeKey),
		staleTime: 5 * 60 * 1000, // 5 minutes
	});

	const rowsData = data?.rows ?? [];
	const totalCount = data?.totalCount ?? 0;

	// Create mutation with error handling
	const createMutation = useMutation<
		{ createdRow: TData | null; __rawResult: Record<string, unknown> },
		Error,
		RowRecord
	>({
		mutationKey: sheetsMutationKeys.table(scopeKey, cacheRef, 'create'),
		mutationFn: async (data: RowRecord) => {
			const createdRow = await adapter.createRow<TData>({ model: requireModel(), tableName }, data, execute, mutationOptions);
			return { createdRow, __rawResult: {} };
		},
		onSuccess: ({ createdRow }: { createdRow: TData | null; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, cacheRef) });

			// Cross-invalidate infinite scroll queries to ensure both modes stay in sync
			queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, cacheRef) });

			// Update individual row cache
			const createdRowKey = rowCacheKey(createdRow as RowRecord | null);
			if (createdRowKey !== null) {
				queryClient.setQueryData(sheetsTableQueryKeys.tableRow(scopeKey, cacheRef, createdRowKey), createdRow);
			}
		},
	});

	// Update mutation with error handling
	const updateMutation = useMutation<
		{ updatedRow: TData | null; __rawResult: Record<string, unknown> },
		Error,
		{ id: SheetsRowIdentifier; patch: RowRecord },
		{ previousRows: Array<[readonly unknown[], { rows: TData[]; totalCount: number } | undefined]> }
	>({
		mutationKey: sheetsMutationKeys.table(scopeKey, cacheRef, 'update'),
		mutationFn: async ({ id, patch }) => {
			const updatedRow = await adapter.updateRow<TData>(
				{ model: requireModel(), tableName },
				resolveIdentifier(id),
				patch,
				execute,
				mutationOptions,
			);
			return { updatedRow, __rawResult: {} };
		},
		// Optimistic patch: an inline cell edit must show the new value instantly,
		// not after the server round-trip + the onSuccess refetch round-trip. The
		// active rows cache is `{ rows, totalCount }` keyed by `tableRows(...options)`;
		// patch every cached `tableRows` variant that holds the row (the active query
		// key embeds `finalQueryOptions`, but other option permutations may be cached
		// too), matching the row by its primary-key identity.
		onMutate: async ({ id, patch }) => {
			const tablePrefix = sheetsTableQueryKeys.table(scopeKey, cacheRef);
			await queryClient.cancelQueries({ queryKey: tablePrefix });
			const targetKey = tableMeta ? sheetsIdentifierCacheKey(tableMeta, id) : null;

			const isRowsKey = (key: readonly unknown[]) => key[key.length - 2] === 'rows';
			const previousRows = queryClient
				.getQueriesData<{ rows: TData[]; totalCount: number }>({ queryKey: tablePrefix })
				.filter(([key]) => isRowsKey(key)) as Array<
				[readonly unknown[], { rows: TData[]; totalCount: number } | undefined]
			>;

			for (const [key] of previousRows) {
				queryClient.setQueryData<{ rows: TData[]; totalCount: number }>(key, (old) => {
					if (!old) return old;
					let changed = false;
					const rows = old.rows.map((row) => {
						if (targetKey !== null && rowCacheKey(row as RowRecord) === targetKey) {
							changed = true;
							return { ...(row as RowRecord), ...patch } as TData;
						}
						return row;
					});
					return changed ? { ...old, rows } : old;
				});
			}

			return { previousRows };
		},
		onError: (_err, _vars, ctx) => {
			// Roll the optimistic patch back to the snapshot on failure.
			ctx?.previousRows.forEach(([key, data]) => queryClient.setQueryData(key, data));
		},
		onSuccess: ({ updatedRow }: { updatedRow: TData | null; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, cacheRef) });

			// NOTE: deliberately NOT invalidating the infinite-scroll cache here.
			// An inline field update never changes row membership/ordering/count, so:
			//   - infinite mode reconciles via the caller's optimistic `updateRowAtIndex`
			//     (+ self-heal refetch on a cache miss) in use-sheets.ts;
			//   - paginated mode is covered by the `table` invalidation above.
			// A blanket `infiniteTable` invalidation would refetch EVERY loaded page
			// (the live-observed 2x refetch on each edit) and clobber the optimistic
			// patch on the active page. The create/delete mutations still
			// cross-invalidate the infinite cache since no per-cell optimistic patch
			// covers a membership change.

			// Update individual row cache
			const updatedRowKey = rowCacheKey(updatedRow as RowRecord | null);
			if (updatedRowKey !== null) {
				queryClient.setQueryData(sheetsTableQueryKeys.tableRow(scopeKey, cacheRef, updatedRowKey), updatedRow);
			}
		},
	});

	// Delete mutation with error handling
	const deleteMutation = useMutation<
		{ deletedId: DeleteIdentifier; __rawResult: Record<string, unknown> },
		Error,
		DeleteIdentifier
	>({
		mutationKey: sheetsMutationKeys.table(scopeKey, cacheRef, 'delete'),
		mutationFn: async (idOrPk) => {
			await adapter.deleteRow({ model: requireModel(), tableName }, resolveIdentifier(idOrPk), execute, mutationOptions);
			return { deletedId: idOrPk, __rawResult: {} };
		},
		onSuccess: ({ deletedId }: { deletedId: DeleteIdentifier; __rawResult: Record<string, unknown> }) => {
			// Invalidate all related queries for paginated mode
			queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, cacheRef) });

			// Cross-invalidate infinite scroll queries to ensure both modes stay in sync
			queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, cacheRef) });

			const deletedRowKey = tableMeta ? sheetsIdentifierCacheKey(tableMeta, deletedId) : null;
			if (deletedRowKey !== null) {
				queryClient.removeQueries({
					queryKey: sheetsTableQueryKeys.tableRow(scopeKey, cacheRef, deletedRowKey),
				});
			}
		},
	});

	// Read one row through the list field filtered by its primary key.
	const findOne = async (id: SheetsRowIdentifier): Promise<TData | null> => {
		const tableModel = requireModel();
		const document = buildFindOneDocument(tableModel, sheetsIdentifierToRowKey(tableModel, resolveIdentifier(id)), {
			relations: relationsFromSelection(fieldSelection),
		});
		try {
			return document.read(await execute(document.document, document.variables)) as TData | null;
		} catch (error) {
			// Like a list read: a record with a cell the API could not serve still loads, with that cell's error on it.
			const partial = partialResultOf(error);
			if (!partial) throw error;
			try {
				return document.read(partial.data, partial.errors) as TData | null;
			} catch {
				throw error;
			}
		}
	};

	// Invalidate function
	const invalidate = () => {
		queryClient.invalidateQueries({ queryKey: sheetsTableQueryKeys.table(scopeKey, cacheRef) });
	};

	return {
		// Data
		data: rowsData,
		totalCount,
		isLoading: (enabled && isModelLoading) || isRowsLoading,
		isFetching,
		error: rowsError ?? (enabled ? modelError : null),
		model,

		// Single row operations
		findOne,

		// Mutations
		create: (data: RowRecord) => createMutation.mutateAsync(data),
		update: (id: SheetsRowIdentifier, patch: RowRecord) => updateMutation.mutateAsync({ id, patch }),
		delete: (id: DeleteIdentifier) => deleteMutation.mutateAsync(id),

		// Mutation states
		isCreating: createMutation.isPending,
		isUpdating: updateMutation.isPending,
		isDeleting: deleteMutation.isPending,

		// Mutation errors
		createError: createMutation.error,
		updateError: updateMutation.error,
		deleteError: deleteMutation.error,

		// Utilities
		// A table whose model failed has no rows query to run: load the model again; the rows follow.
		refetch: () => (model ? refetch() : refetchModel()),
		invalidate,
	};
}

// React bindings for file columns: where a column uploads to (and why it
// cannot), and the cell write that waits out the server's file confirmation.
//
// The logic lives in `uploads/`; this file only wires it to the provider
// (storage transport, adapter, host upload config, query cache).

import { useCallback, useMemo } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import type { ColumnModel, TableModel } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext, type SheetsStorageTransport } from '../context/sheets-context';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import { isAbortError, type FileProjection, type UploadProgressEvent } from '../context/sheets-upload-presigned';
import { sheetsIdentifierToRowKey, type SheetsRowIdentifier } from '../row-identity';
import { loadColumnStorage, type ColumnStorage, type SendFile } from '../uploads/column-storage';
import { FILE_NOT_LIVE_CODE, fileWriteMessage, writeFileCell } from '../uploads/file-cell-write';
import { pendingWriteKey, setPendingFileWrite } from '../uploads/pending-file-writes';
import { processingPolicyOf, type ProcessingPolicy } from '../uploads/upload-config';
import { sheetsMutationKeys, sheetsQueryKeys } from './query-keys';
import { useTableModel } from './use-table-model';
import type { MediaUrlResolver } from './use-sheets-media-url';

export type UploadProgress = UploadProgressEvent;

/** The value a file cell stores after a write: a projection, a link, a list, or null. */
export type UploadResponse = unknown;

// ============================================================================
// Cell values
// ============================================================================

const LINK_WITHOUT_PUBLIC_URL =
	'This column stores a link to each file, so it needs a public bucket. The file was stored without a public address.';

/** The row key of a row, read with the table model's primary key; null when a key field is missing. */
export function rowKeyOfRow(table: TableModel, row: Readonly<Record<string, unknown>>): SheetsRowIdentifier | null {
	if (table.primaryKey.length === 0) return null;
	const values = table.primaryKey.map((field) => row[field]);
	if (values.some((value) => value === undefined || value === null)) return null;
	if (table.primaryKey.length === 1) {
		const [value] = values;
		return typeof value === 'string' || typeof value === 'number' ? value : null;
	}
	return Object.fromEntries(table.primaryKey.map((field, index) => [field, values[index]])) as SheetsRowIdentifier;
}

/** The element a column stores for one uploaded file. Throws when the column cannot hold it. */
export function cellElementFor(column: Pick<ColumnModel, 'value'>, projection: FileProjection, file?: File): unknown {
	if (column.value.file?.kind === 'attachment') {
		if (!projection.url) throw new Error(LINK_WITHOUT_PUBLIC_URL);
		return projection.url;
	}
	return projection.filename || !file ? projection : { ...projection, filename: file.name };
}

// ============================================================================
// Column storage
// ============================================================================

const transportIds = new WeakMap<SheetsStorageTransport, number>();
let nextTransportId = 1;

function transportId(storage: SheetsStorageTransport | undefined): number {
	if (!storage) return 0;
	let id = transportIds.get(storage);
	if (id === undefined) {
		id = nextTransportId;
		nextTransportId += 1;
		transportIds.set(storage, id);
	}
	return id;
}

export interface UseColumnStorageResult {
	storage: ColumnStorage | null;
	isLoading: boolean;
	error: Error | null;
}

/** Where a file column uploads to and how its previews are signed. Resolved once per column. */
export function useColumnStorage(table: TableModel | null | undefined, column: ColumnModel | null | undefined): UseColumnStorageResult {
	const { storage, scopeKey, config, executeUpload } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const injected = config.executeUpload ? executeUpload : undefined;
	const enabled = Boolean(table && column?.value.file);
	const query = useQuery<ColumnStorage, Error>({
		queryKey: [
			...sheetsQueryKeys.scope(scopeKey),
			'column-storage',
			transportId(storage),
			table?.key ?? '',
			column?.name ?? '',
			JSON.stringify(column?.value.file ?? null),
			JSON.stringify(config.upload ?? null),
			Boolean(injected),
		],
		queryFn: () => loadColumnStorage({
			storage,
			adapter,
			table: table!,
			column: column!,
			config: config.upload,
			databaseId: config.databaseId ?? null,
			executeUpload: injected,
		}),
		enabled,
		staleTime: Number.POSITIVE_INFINITY,
		gcTime: 30 * 60 * 1000,
		retry: 1,
		structuralSharing: false,
	});
	const loaded = query.data;
	const onError = config.onError;
	const tableName = table?.name;
	// Every failed upload (not a cancel) reaches the host's `onError` with source 'upload'.
	// The error names a file row the upload left, if any (`unfinishedUploadOf`).
	const reported = useMemo((): ColumnStorage | undefined => {
		if (!loaded || loaded.upload.status !== 'ready' || !onError) return loaded;
		const { send } = loaded.upload;
		const reportingSend: SendFile = async (file, options) => {
			try {
				return await send(file, options);
			} catch (error) {
				if (!isAbortError(error)) onError(error, { source: 'upload', tableName });
				throw error;
			}
		};
		return { ...loaded, upload: { status: 'ready', send: reportingSend } };
	}, [loaded, onError, tableName]);
	return { storage: enabled ? reported ?? null : null, isLoading: enabled && query.isPending, error: query.error ?? null };
}

export interface ColumnMediaResolver {
	/** The resolver for `useSheetsMediaUrl`: null when previews cannot be signed, undefined for the fallback discovery. */
	resolver: MediaUrlResolver | null | undefined;
	/** True while the column's storage is still resolving. */
	isLoading: boolean;
}

/** How a column's previews are signed. A cell without a column model uses the fallback discovery. */
export function useColumnMediaResolver(
	table: TableModel | null | undefined,
	column: ColumnModel | null | undefined,
): ColumnMediaResolver {
	const { storage, isLoading } = useColumnStorage(table, column);
	return useMemo((): ColumnMediaResolver => {
		if (!table || !column?.value.file) return { resolver: undefined, isLoading: false };
		if (!storage) return { resolver: null, isLoading };
		const resolve = storage.resolveUrls;
		return { resolver: resolve && storage.previewKey ? { key: storage.previewKey, resolve } : null, isLoading: false };
	}, [table, column, storage, isLoading]);
}

export type FileUploadState =
	| { status: 'loading' }
	| { status: 'ready'; send: SendFile }
	| { status: 'unavailable'; reason: string };

/** Why the cell cannot be written, from the table model, or null. */
export function fileWriteReason(table: TableModel | null | undefined, column: ColumnModel | null | undefined): string | null {
	if (table && !table.operations.update) {
		return table.issues.find((issue) => issue.scope === 'operation' && issue.target === 'update')?.message
			?? 'Records in this table cannot be changed.';
	}
	if (column && !column.write.update) return column.write.updateReason ?? 'This column cannot be changed.';
	return null;
}

/** Whether the column can take a new file now, and the uploader when it can. */
export function useFileUploadState(
	table: TableModel | null | undefined,
	column: ColumnModel | null | undefined,
	readOnlyReason?: string | null,
): FileUploadState {
	const { storage, isLoading, error } = useColumnStorage(table, column);
	const reason = readOnlyReason ?? fileWriteReason(table, column);
	if (reason) return { status: 'unavailable', reason };
	if (error) return { status: 'unavailable', reason: error.message || 'The storage service could not be reached.' };
	if (isLoading || !storage) return { status: 'loading' };
	return storage.upload;
}

// ============================================================================
// Cell writes
// ============================================================================

export interface FileCellWriteJob {
	table: TableModel;
	column: ColumnModel;
	/** Primary-key identity of the row. */
	rowKey: SheetsRowIdentifier;
	/** Grid row id, which keys the cell's pending state. */
	rowId: string;
	value: unknown;
	/** Called when the server first answers that the file is still processing. */
	onProcessing?: () => void;
	signal?: AbortSignal;
}

/**
 * Write a file cell. While the server confirms the file the cell shows
 * "Processing file…"; a failure stays on the cell with a retry, even when the
 * editor has closed, so an uploaded file is never dropped silently.
 */
export function useFileCellWriter(): (job: FileCellWriteJob) => Promise<unknown> {
	const { execute, scopeKey, config } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const queryClient = useQueryClient();
	const policy = processingPolicyOf(config.upload);

	return useCallback((job: FileCellWriteJob) => {
		const key = pendingWriteKey(job.table.key, job.rowId, job.column.name);
		const run = async (): Promise<unknown> => {
			setPendingFileWrite(scopeKey, key, null);
			try {
				const saved = await writeFileCell({
					adapter,
					execute,
					model: job.table,
					column: job.column,
					rowKey: job.rowKey,
					value: job.value,
					policy,
					signal: job.signal,
					onProcessing: () => {
						setPendingFileWrite(scopeKey, key, { status: 'processing' });
						job.onProcessing?.();
					},
				});
				setPendingFileWrite(scopeKey, key, null);
				void queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.table(scopeKey, job.table.name) });
				void queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, job.table.name) });
				return saved;
			} catch (error) {
				if (job.signal?.aborted) {
					setPendingFileWrite(scopeKey, key, null);
					throw error;
				}
				setPendingFileWrite(scopeKey, key, {
					status: 'failed',
					message: fileWriteMessage(error),
					retry: () => void run().catch((): undefined => undefined),
					dismiss: () => setPendingFileWrite(scopeKey, key, null),
				});
				throw error;
			}
		};
		return run();
	}, [adapter, execute, policy, queryClient, scopeKey]);
}

// ============================================================================
// One-call upload for single-file columns
// ============================================================================

export interface FieldUploadTarget {
	table: TableModel;
	/** Column name. */
	column: string;
	rowKey: SheetsRowIdentifier;
}

export interface FieldUploadTransport {
	/** Data executor for the cell write. */
	execute: SheetsExecuteFn;
	adapter: Pick<SheetsBackendAdapter, 'updateRow'>;
	/** Sends the file to storage (from `useColumnStorage(...).storage.upload`). */
	send: SendFile;
	policy?: ProcessingPolicy;
	onProgress?: (progress: UploadProgress) => void;
	onProcessing?: () => void;
	signal?: AbortSignal;
}

/**
 * Upload one file into a single-file column, or clear it with null, and write
 * the cell. A list column takes its whole list: write it with
 * {@link useFileCellWriter}.
 */
export async function executeFieldUpload(
	target: FieldUploadTarget,
	file: File | null,
	transport: FieldUploadTransport,
): Promise<UploadResponse> {
	const column = target.table.columns.find((candidate) => candidate.name === target.column);
	if (!column?.value.file) throw new Error(`"${target.column}" is not a file column of this table.`);
	if (column.value.file.multiple) throw new Error(`"${target.column}" holds several files; write the whole list.`);
	// A key that cannot address the row fails here, before anything is uploaded.
	const rowKey = sheetsIdentifierToRowKey(target.table, target.rowKey);
	const missing = target.table.primaryKey.filter((field) => rowKey[field] === undefined || rowKey[field] === null);
	if (missing.length > 0) throw new Error(`The row key has no value for ${missing.join(', ')}.`);
	const value = file
		? cellElementFor(column, await transport.send(file, { onProgress: transport.onProgress, signal: transport.signal }), file)
		: null;
	return writeFileCell({
		adapter: transport.adapter,
		execute: transport.execute,
		model: target.table,
		column,
		rowKey: target.rowKey,
		value,
		policy: transport.policy ?? processingPolicyOf(undefined),
		onProcessing: transport.onProcessing,
		signal: transport.signal,
	});
}

// ============================================================================
// Earlier hook, kept as a thin wrapper
// ============================================================================

/** @deprecated Options of {@link useSheetsFieldUpload}. */
export interface UseFieldUploadOptions {
	onProgress?: (progress: UploadProgress) => void;
	onSuccess?: (data: UploadResponse) => void;
	onError?: (error: Error) => void;
	/** Ignored, as before. */
	showToast?: boolean;
	/** Ignored, as before. */
	successMessage?: string;
	/** Ignored, as before. */
	successToastDelayMs?: number;
}

/**
 * @deprecated Use {@link useFileUploadState} with {@link useFileCellWriter}, or
 * {@link executeFieldUpload}. Uploads one file into a single-file column (or
 * clears it with null) through the model-driven path.
 */
export function useSheetsFieldUpload(
	tableName: string,
	fieldName: string,
	recordId: SheetsRowIdentifier | null,
	options: UseFieldUploadOptions = {},
) {
	const { scopeKey } = useSheetsContext();
	const { model: table } = useTableModel(tableName);
	const column = table?.columns.find((candidate) => candidate.name === fieldName) ?? null;
	const upload = useFileUploadState(table, column);
	const writeCell = useFileCellWriter();

	async function write(id: SheetsRowIdentifier, file: File | null): Promise<UploadResponse> {
		if (!table || !column) throw new Error(`Field '${fieldName}' not found in table '${tableName}'.`);
		let value: unknown = null;
		if (file) {
			if (upload.status !== 'ready') throw new Error(upload.status === 'unavailable' ? upload.reason : 'Storage is not ready yet.');
			const projection = await upload.send(file, { onProgress: options.onProgress, recordId: typeof id === 'object' ? undefined : id });
			value = cellElementFor(column, projection, file);
		}
		return writeCell({ table, column, rowKey: id, rowId: typeof id === 'object' ? JSON.stringify(id) : String(id), value });
	}

	const mutation = useMutation<UploadResponse, Error, File | null>({
		// Under the 'sheets' prefix and the table's entries, like every Sheets query and
		// mutation, so a host's global mutation handlers can tell Sheets' own writes apart.
		mutationKey: sheetsMutationKeys.table(scopeKey, table?.key ?? tableName, 'field-upload', fieldName),
		mutationFn: (file) => {
			if (recordId == null) throw new Error('Missing record context for upload');
			return write(recordId, file);
		},
		onSuccess: options.onSuccess,
		onError: options.onError,
	});

	const resolveRowIdentifier = (row: Readonly<Record<string, unknown>>) => (table ? rowKeyOfRow(table, row) : null);
	return { ...mutation, write, resolveRowIdentifier };
}

export { FILE_NOT_LIVE_CODE };

/**
 * The table model of one table: the single source of keys, column kinds and
 * options, write flags, relations, labels, sort and filter names for the grid.
 *
 * Accepts the host's bare table name or a `TableModel.key`. A name shared by
 * tables in several schemas is an error listing the keys. Each table resolves
 * lazily and fails alone: one table's error never blocks another table.
 *
 * Inside a read-only grid (`<Sheets readOnly>`), every model comes back without
 * create, update and delete, each refusal carrying the host's reason.
 */
import { useCallback, useMemo } from 'react';
import { useQueries, useQuery, type UseQueryOptions } from '@tanstack/react-query';

import {
	TableModelError,
	findMetaTable,
	metaTablesOf,
	tableKeyOf,
	type MetaQuery,
	type MetaschemaTable,
	type TableKey,
	type TableModel,
} from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import { useSheetsContext, type SheetsConfig, type SheetsScopeKey } from '../context/sheets-context';
import { readOnlyTableModel, useSheetsReadOnlyReason } from '../context/sheets-read-only';
import { sheetsQueryKeys } from './query-keys';
import { useSheetsMeta } from './use-sheets-meta';

export interface UseTableModelOptions {
	/** Resolve the model. Default true. */
	enabled?: boolean;
}

export interface UseTableModelResult {
	/** The model, or null while it loads or when it failed. */
	model: TableModel | null;
	/** `TableModel.key` of the requested table, or null until `_meta` has loaded or when the name is unknown. */
	tableKey: TableKey | null;
	/** The `_meta` entry of the table, or null. */
	metaTable: MetaschemaTable | null;
	/** True until the model is ready (or failed). */
	isLoading: boolean;
	/** Why the model is unavailable: `_meta` failed, the name is unknown or ambiguous, or this table failed. */
	error: Error | null;
	/** Load again what failed: `_meta` when it failed (the model follows), otherwise this table's model. */
	refetch: () => Promise<void>;
}

const metaVersions = new WeakMap<MetaQuery, number>();
let nextMetaVersion = 1;

/** A number per `_meta` result. An unchanged refetch keeps its object, so it keeps its version. */
function metaVersionOf(meta: MetaQuery): number {
	let version = metaVersions.get(meta);
	if (version === undefined) {
		version = nextMetaVersion;
		nextMetaVersion += 1;
		metaVersions.set(meta, version);
	}
	return version;
}

/** A model error is deterministic for this `_meta`; only a failed schema read is worth a retry. */
function isDeterministicModelError(error: Error): boolean {
	const code = (error as { code?: unknown }).code;
	return error instanceof TableModelError && code !== 'SCHEMA_UNAVAILABLE';
}

function locate(meta: MetaQuery | undefined, tableRef: string | null | undefined): { metaTable: ReturnType<typeof findMetaTable> | null; error: Error | null } {
	if (!meta || !tableRef) return { metaTable: null, error: null };
	try {
		return { metaTable: findMetaTable(metaTablesOf(meta), tableRef), error: null };
	} catch (error) {
		return { metaTable: null, error: error as Error };
	}
}

interface ModelQueryContext {
	scopeKey: SheetsScopeKey;
	meta: MetaQuery | undefined;
	adapter: SheetsBackendAdapter;
	execute: SheetsExecuteFn;
	displayFields: SheetsConfig['displayFields'];
	displayKey: string | null;
}

/** One table model query. `useTableModel` and `useTableModels` share it, so nothing is fetched twice. */
function tableModelQuery(
	context: ModelQueryContext,
	tableKey: TableKey | null,
	enabled: boolean,
): UseQueryOptions<TableModel, Error> {
	const { scopeKey, meta, adapter, execute, displayFields, displayKey } = context;
	return {
		queryKey: sheetsQueryKeys.tableModel(scopeKey, tableKey ?? '', meta ? metaVersionOf(meta) : 0, displayKey),
		queryFn: () => adapter.fetchTableModel(execute, meta!, tableKey!, { displayOverrides: displayFields }),
		enabled: enabled && Boolean(meta && tableKey),
		staleTime: Number.POSITIVE_INFINITY,
		gcTime: 30 * 60 * 1000,
		retry: (failureCount, error) => failureCount < 1 && !isDeterministicModelError(error),
	};
}

function useModelQueryContext(enabled: boolean) {
	const { execute, scopeKey, config } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const metaQuery = useSheetsMeta({ enabled });
	const readOnlyReason = useSheetsReadOnlyReason();
	const displayFields = config.displayFields;
	const displayKey = useMemo(() => (displayFields ? JSON.stringify(displayFields) : null), [displayFields]);
	const context: ModelQueryContext = { scopeKey, meta: metaQuery.data, adapter, execute, displayFields, displayKey };
	return { context, metaQuery, readOnlyReason };
}

/** The model as this grid may use it: read-only with the host's reason inside a read-only grid. */
function asSeen(model: TableModel, readOnlyReason: string | null): TableModel {
	return readOnlyReason ? readOnlyTableModel(model, readOnlyReason) : model;
}

export function useTableModel(
	tableRef: string | null | undefined,
	options: UseTableModelOptions = {},
): UseTableModelResult {
	const { enabled = true } = options;
	const active = enabled && Boolean(tableRef);
	const { context, metaQuery, readOnlyReason } = useModelQueryContext(active);
	const meta = metaQuery.data;

	const { metaTable, error: locateError } = useMemo(() => locate(meta, tableRef), [meta, tableRef]);
	const tableKey = metaTable ? tableKeyOf(metaTable) : null;
	const modelEnabled = active && Boolean(meta && tableKey);

	const query = useQuery<TableModel, Error>(tableModelQuery(context, tableKey, active));
	const { refetch: refetchMeta } = metaQuery;
	const { refetch: refetchModel } = query;
	const metaFailed = Boolean(metaQuery.error || locateError);
	const refetch = useCallback(async () => {
		if (metaFailed) await refetchMeta();
		else if (modelEnabled) await refetchModel();
	}, [metaFailed, modelEnabled, refetchMeta, refetchModel]);

	return {
		model: modelEnabled && query.data ? asSeen(query.data, readOnlyReason) : null,
		tableKey,
		metaTable,
		isLoading: active && (metaQuery.isPending || (modelEnabled && query.isPending)) && !metaQuery.error && !locateError,
		error: metaQuery.error ?? locateError ?? (modelEnabled ? query.error : null) ?? null,
		refetch,
	};
}

export interface UseTableModelsResult {
	/** The models that have loaded, by `TableModel.key`. A table that failed or is unknown is absent. */
	models: ReadonlyMap<TableKey, TableModel>;
	/** True while `_meta` or any of the models still loads. */
	isLoading: boolean;
}

/**
 * The models of a variable set of tables (names or keys), with the same cache
 * entries as `useTableModel`. Unknown or ambiguous names are skipped; use
 * `useTableModel` for one table's error.
 */
export function useTableModels(refs: readonly string[], options: UseTableModelOptions = {}): UseTableModelsResult {
	const { enabled = true } = options;
	const active = enabled && refs.length > 0;
	const { context, metaQuery, readOnlyReason } = useModelQueryContext(active);
	const meta = metaQuery.data;
	const refsKey = refs.join('\u0000');

	const tableKeys = useMemo(() => {
		const keys = new Set<TableKey>();
		for (const ref of refsKey ? refsKey.split('\u0000') : []) {
			const { metaTable } = locate(meta, ref);
			if (metaTable) keys.add(tableKeyOf(metaTable));
		}
		return [...keys];
	}, [meta, refsKey]);

	const results = useQueries({ queries: tableKeys.map((tableKey) => tableModelQuery(context, tableKey, active)) });
	// The map keeps its identity until a model changes, so effects that depend on it do not re-run each render.
	const signature = results.map((result) => result.dataUpdatedAt).join(',');
	const models = useMemo(
		() =>
			new Map(
				results.flatMap((result, position) =>
					result.data ? [[tableKeys[position]!, asSeen(result.data, readOnlyReason)] as const] : [],
				),
			),
		// eslint-disable-next-line react-hooks/exhaustive-deps
		[signature, tableKeys, readOnlyReason],
	);
	const isLoading = active && (metaQuery.isPending || results.some((result) => result.isPending)) && !metaQuery.error;
	return { models, isLoading };
}

// Delimited text (CSV, TSV and their semicolon or pipe variants), read and written.
//
// Reading follows RFC 4180 and what spreadsheets write: a field may be quoted, a
// quoted field may hold the delimiter, line breaks and doubled quotes, lines end
// in CRLF, LF or CR, and a leading byte-order mark is dropped. The delimiter is
// detected from the first lines when the caller does not name one.

export type Delimiter = ',' | '\t' | ';' | '|';

export const DELIMITERS: readonly Delimiter[] = ['\t', ',', ';', '|'];

/** One record of a delimited text. */
export interface DelimitedRecord {
	/** The record's row number as a spreadsheet app shows it: the first record is row 1, blank lines count. */
	row: number;
	fields: string[];
}

export interface DelimitedTable {
	delimiter: Delimiter;
	/** The first record. */
	header: string[];
	/** Every record after the header, blank lines left out. */
	records: DelimitedRecord[];
	/** The row of a quoted field that is never closed (it runs to the end of the text), or null. */
	unclosedQuoteRow: number | null;
}

const BOM = '\uFEFF';
/** Characters the delimiter detection reads. */
const DETECTION_SAMPLE = 8192;

function scan(text: string, delimiter: Delimiter): { records: DelimitedRecord[]; unclosedQuoteRow: number | null } {
	const source = text.startsWith(BOM) ? text.slice(1) : text;
	const records: DelimitedRecord[] = [];
	let fields: string[] = [];
	let field = '';
	let inQuotes = false;
	let row = 0;

	const endRecord = () => {
		fields.push(field);
		row += 1;
		// A blank line is no record, but it keeps its row number.
		if (fields.length > 1 || fields[0] !== '') records.push({ row, fields });
		fields = [];
		field = '';
	};

	for (let index = 0; index < source.length; index += 1) {
		const character = source[index]!;
		if (inQuotes) {
			if (character !== '"') field += character;
			else if (source[index + 1] === '"') {
				field += '"';
				index += 1;
			} else inQuotes = false;
			continue;
		}
		if (character === '"' && field === '') {
			inQuotes = true;
		} else if (character === delimiter) {
			fields.push(field);
			field = '';
		} else if (character === '\r' || character === '\n') {
			if (character === '\r' && source[index + 1] === '\n') index += 1;
			endRecord();
		} else {
			field += character;
		}
	}
	const unclosedQuoteRow = inQuotes ? row + 1 : null;
	if (field !== '' || fields.length > 0 || inQuotes) endRecord();
	return { records, unclosedQuoteRow };
}

/** The records of a delimited text, blank lines left out. */
export function parseDelimited(text: string, delimiter: Delimiter): DelimitedRecord[] {
	return scan(text, delimiter).records;
}

/**
 * The delimiter a text uses: the candidate that splits the first lines into the
 * same number of fields (more than one) most often. Tab wins a tie, then comma.
 */
export function detectDelimiter(text: string): Delimiter {
	const sample = text.slice(0, DETECTION_SAMPLE);
	let best: { delimiter: Delimiter; score: number } = { delimiter: ',', score: 0 };
	for (const delimiter of DELIMITERS) {
		const counts = parseDelimited(sample, delimiter).slice(0, 20).map((record) => record.fields.length);
		const frequency = new Map<number, number>();
		for (const count of counts) frequency.set(count, (frequency.get(count) ?? 0) + 1);
		let score = 0;
		for (const [count, times] of frequency) if (count > 1) score = Math.max(score, times * 100 + count);
		if (score > best.score) best = { delimiter, score };
	}
	return best.delimiter;
}

/** Read a delimited text into a header and records. */
export function readDelimitedTable(text: string, delimiter: Delimiter = detectDelimiter(text)): DelimitedTable {
	const { records, unclosedQuoteRow } = scan(text, delimiter);
	const [first, ...rest] = records;
	return { delimiter, header: first?.fields ?? [], records: rest, unclosedQuoteRow };
}

function quoteField(value: string, delimiter: Delimiter): string {
	return value.includes(delimiter) || /["\r\n]/.test(value) || value !== value.trim()
		? `"${value.replace(/"/g, '""')}"`
		: value;
}

/** Write records as delimited text with CRLF line ends, quoting only the fields that need it. */
export function writeDelimited(records: readonly (readonly string[])[], delimiter: Delimiter = ','): string {
	return records.map((record) => record.map((value) => quoteField(value, delimiter)).join(delimiter)).join('\r\n');
}

/** A CSV file body: a byte-order mark first, so spreadsheet apps read it as UTF-8. */
export function csvFileText(records: readonly (readonly string[])[]): string {
	return `${BOM}${writeDelimited(records, ',')}\r\n`;
}

// The "Export view" button: every row of the current view as CSV, with
// progress and cancel. Formula protection follows the host's choice, like the
// grid's selected-rows export, which stays separate.

import { useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';
import { RiDownloadLine } from '@remixicon/react';

import type { SortSpec, TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import {
	Dialog,
	DialogDescription,
	DialogFooter,
	DialogHeader,
	DialogPanel,
	DialogPopup,
	DialogTitle,
} from '@/components/ui/dialog';
import { Progress } from '@/components/ui/progress';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
import { ToolButton } from '../grid/toolbar/toolbar-button';
import { gridColumnKeys } from '../relations/relation-columns';
import { exportColumns, exportViewCsv, RELATION_PAGE_SIZE, type ExportViewResult } from './export-view';
import { downloadTextFile, safeFileName } from './files';

export interface ExportViewControlProps {
	/** The table, or null while it loads. */
	model: TableModel | null;
	/** The view's filter, search included. */
	where?: Readonly<Record<string, unknown>>;
	orderBy?: readonly SortSpec[];
	/** The view's column keys in order (column names and relation field names). Default: every grid column. */
	columns?: readonly string[];
	/** Download file name. Default: the table name with `.csv`. */
	filename?: string;
	/** Prefix text that starts like a spreadsheet formula with an apostrophe (see `formula-protection.ts`). Default false. */
	protectFormulas?: boolean;
}

type ExportState =
	| { status: 'idle' }
	| { status: 'running'; loaded: number; total: number | null }
	| { status: 'done'; result: ExportViewResult; filename: string }
	| { status: 'failed'; message: string };

function unavailableReasonOf(model: TableModel | null, columnCount: number): string | null {
	if (!model) return 'Export is available once the table has loaded.';
	if (!model.operations.list) return 'The rows of this table cannot be read.';
	if (columnCount === 0) return 'No column of this view can be exported.';
	return null;
}

function count(value: number, one: string, many = `${one}s`): string {
	return `${value.toLocaleString()} ${value === 1 ? one : many}`;
}

export function ExportViewControl({ model, where, orderBy, columns, filename, protectFormulas = false }: ExportViewControlProps) {
	const { execute } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const [state, setState] = useState<ExportState>({ status: 'idle' });
	const controllerRef = useRef<AbortController | null>(null);
	const reasonId = useId();

	useEffect(() => () => controllerRef.current?.abort(), []);

	const keys = useMemo(() => columns ?? (model ? gridColumnKeys(model) : []), [columns, model]);
	const columnCount = useMemo(() => (model ? exportColumns(model, keys).length : 0), [keys, model]);
	const unavailableReason = unavailableReasonOf(model, columnCount);

	const run = useCallback(async () => {
		if (!model) return;
		controllerRef.current?.abort();
		const controller = new AbortController();
		controllerRef.current = controller;
		setState({ status: 'running', loaded: 0, total: null });
		const name = filename ?? safeFileName(model.name, '.csv');
		try {
			const result = await exportViewCsv(
				{ adapter, execute, model },
				{ where, orderBy, columns: keys },
				{
					protectFormulas,
					signal: controller.signal,
					onProgress: ({ loaded, total }) => {
						if (!controller.signal.aborted) setState({ status: 'running', loaded, total });
					},
				},
			);
			if (controller.signal.aborted) return;
			downloadTextFile(result.text, name);
			setState({ status: 'done', result, filename: name });
		} catch (error) {
			if (controller.signal.aborted) return;
			const detail = error instanceof Error && error.message ? ` ${error.message}` : '';
			setState({ status: 'failed', message: `The rows could not be exported.${detail}` });
		}
	}, [adapter, execute, filename, keys, model, orderBy, protectFormulas, where]);

	const cancel = () => {
		controllerRef.current?.abort();
		setState({ status: 'idle' });
	};

	const notes =
		state.status === 'done'
			? [
					state.result.unreadableCells > 0
						? `${count(state.result.unreadableCells, 'value')} could not be read and ${state.result.unreadableCells === 1 ? 'is' : 'are'} left empty.`
						: null,
					state.result.truncatedLists > 0
						? `${count(state.result.truncatedLists, 'cell')} of linked-record lists hold only the first ${RELATION_PAGE_SIZE} records.`
						: null,
				].filter((note): note is string => Boolean(note))
			: [];

	return (
		<>
			<span title={unavailableReason ?? undefined} className='inline-flex'>
				<ToolButton
					icon={RiDownloadLine}
					label='Export view'
					aria-label='Export all rows of this view as CSV'
					title={unavailableReason ? undefined : 'Export all rows of this view as CSV'}
					disabled={Boolean(unavailableReason)}
					aria-describedby={unavailableReason ? reasonId : undefined}
					onClick={() => void run()}
				/>
				{unavailableReason && (
					<span id={reasonId} className='sr-only'>
						{unavailableReason}
					</span>
				)}
			</span>
			<Dialog
				open={state.status !== 'idle'}
				onOpenChange={(next) => {
					if (!next) cancel();
				}}
			>
				<DialogPopup>
					<DialogHeader>
						<DialogTitle>Export view</DialogTitle>
						<DialogDescription>Every row of this view, with its filter, search, sort and columns.</DialogDescription>
					</DialogHeader>
					<DialogPanel>
						{state.status === 'running' && (
							<div className='space-y-3'>
								<Progress value={state.total === null ? null : state.loaded} min={0} max={Math.max(state.total ?? 0, 1)} aria-label='Export progress' />
								<p role='status' aria-live='polite' className='text-sm tabular-nums'>
									{state.total === null
										? `${count(state.loaded, 'row')} read…`
										: `${state.loaded.toLocaleString()} of ${count(state.total, 'row')} read…`}
								</p>
							</div>
						)}
						{state.status === 'done' && (
							<div className='space-y-2 text-sm'>
								<p role='status'>
									{count(state.result.rowCount, 'row')} exported to {state.filename}.
								</p>
								{notes.map((note) => (
									<p key={note} className='text-muted-foreground'>
										{note}
									</p>
								))}
							</div>
						)}
						{state.status === 'failed' && (
							<p role='alert' className='text-destructive text-sm'>
								{state.message}
							</p>
						)}
					</DialogPanel>
					<DialogFooter>
						{state.status === 'running' && (
							<Button variant='outline' onClick={cancel}>
								Cancel
							</Button>
						)}
						{state.status === 'done' && (
							<Button variant='outline' onClick={() => downloadTextFile(state.result.text, state.filename)}>
								Download again
							</Button>
						)}
						{state.status === 'failed' && (
							<Button variant='outline' onClick={() => void run()}>
								Try again
							</Button>
						)}
						{state.status !== 'running' && <Button onClick={cancel}>Close</Button>}
					</DialogFooter>
				</DialogPopup>
			</Dialog>
		</>
	);
}

// A view's full result as CSV: every page, with the view's filter and sort, the
// view's columns in its order.
//
// Values use the grid's copy format (`formatColumnValue`), so an exported file
// imports back exactly: choices as their labels, structured values and lists as
// JSON. A linked record is written as its label; a list of linked records as a
// JSON list of labels. The header names each column as the grid does; the import
// matches a header by that label or by the field name. Only the requested columns
// are read from the server.

import { readCellError, readRelationTotalCount } from '@constructive-io/data';
import type { ColumnModel, RelationModel, SortSpec, TableModel } from '@constructive-io/data';

import { copyText, formatColumnValue } from '../cell-types/column-value';
import { fieldLabel, relationLabelIn } from '../cell-types/field-label';
import { relationRecordLabel } from '../relations/relation-label';
import { csvFileText } from './delimited-text';
import { isNumberColumn, protectFormulaText, type CsvExportOptions } from './formula-protection';
import { readAllRows, type RowSource } from './read-all-rows';

type RowRecord = Record<string, unknown>;

/** One column of a file: its key, the header it is written under, and what it holds. */
export type ExportColumn =
	| { kind: 'column'; key: string; label: string; column: ColumnModel }
	| { kind: 'relation'; key: string; label: string; relation: RelationModel };

export interface ExportViewQuery {
	/** The view's filter, search included. */
	where?: Readonly<Record<string, unknown>>;
	orderBy?: readonly SortSpec[];
	/** Column keys in the view's order: column names and relation field names. */
	columns: readonly string[];
}

export interface ExportViewResult {
	/** The CSV file body. */
	text: string;
	rowCount: number;
	/** Cells the server could not send; they are written empty. */
	unreadableCells: number;
	/** Cells of a list of linked records that hold only the first `RELATION_PAGE_SIZE` records. */
	truncatedLists: number;
}

/** Linked records written per list cell. */
export const RELATION_PAGE_SIZE = 100;

/** The columns of `keys` a file can hold, in order: readable columns and readable relations. Other keys are left out. */
export function exportColumns(model: TableModel, keys: readonly string[]): ExportColumn[] {
	const out: ExportColumn[] = [];
	for (const key of new Set(keys)) {
		const column = model.columns.find((candidate) => candidate.name === key);
		if (column) {
			if (column.readable) out.push({ kind: 'column', key, label: fieldLabel(column.name), column });
			continue;
		}
		const relation = model.relations.find((candidate) => candidate.fieldName === key);
		if (relation?.readable) out.push({ kind: 'relation', key, label: relationLabelIn(model, relation), relation });
	}
	return out;
}

function relationText(relation: RelationModel, value: unknown): string {
	if (Array.isArray(value)) return value.length ? JSON.stringify(value.map((record) => relationRecordLabel(relation, record))) : '';
	return value && typeof value === 'object' ? relationRecordLabel(relation, value as RowRecord) : '';
}

/**
 * Rows as a CSV file body, with the columns' labels as the header, and the cells that could not
 * be written in full. With `protectFormulas`, text cells that start like a formula get
 * a leading apostrophe; number columns and the header are never changed.
 */
export function rowsCsvText(
	columns: readonly ExportColumn[],
	rows: readonly RowRecord[],
	options: CsvExportOptions = {},
): Omit<ExportViewResult, 'rowCount'> {
	let unreadableCells = 0;
	let truncatedLists = 0;
	const protect = (text: string) => (options.protectFormulas ? protectFormulaText(text) : text);
	const records = rows.map((row) =>
		columns.map((entry) => {
			if (entry.kind === 'column') {
				if (readCellError(row, entry.column.name) !== null) {
					unreadableCells += 1;
					return '';
				}
				const text = formatColumnValue(entry.column, row[entry.column.name]);
				return isNumberColumn(entry.column) ? text : protect(text);
			}
			const value = row[entry.relation.fieldName];
			const total = readRelationTotalCount(row, entry.relation.fieldName);
			if (Array.isArray(value) && total !== null && total > value.length) truncatedLists += 1;
			return protect(relationText(entry.relation, value));
		}),
	);
	return { text: csvFileText([columns.map((entry) => entry.label), ...records]), unreadableCells, truncatedLists };
}

/**
 * Rows the grid holds (the selected rows, or the loaded ones) as a CSV file body.
 * With a model, its columns and relations in the copy format, and keys the grid adds
 * itself left out; before the model loads, every key as plain text.
 */
export function loadedRowsCsv(
	model: TableModel | null,
	rows: readonly RowRecord[],
	keys: readonly string[],
	options: CsvExportOptions = {},
): string {
	if (model) return rowsCsvText(exportColumns(model, keys), rows, options).text;
	// Without a model only a value that is text itself can be told apart from a number.
	const cell = (value: unknown, key: string) => {
		const text = copyText(null, key, value);
		return options.protectFormulas && typeof value === 'string' ? protectFormulaText(text) : text;
	};
	return csvFileText([keys, ...rows.map((row) => keys.map((key) => cell(row[key], key)))]);
}

/** Read every row of the view and write it as CSV. Throws the abort reason when `signal` aborts. */
export async function exportViewCsv(
	source: RowSource,
	query: ExportViewQuery,
	options: CsvExportOptions & {
		signal?: AbortSignal;
		onProgress?: (progress: { loaded: number; total: number | null }) => void;
	} = {},
): Promise<ExportViewResult> {
	const columns = exportColumns(source.model, query.columns);
	const rows = await readAllRows(
		source,
		{
			where: query.where,
			orderBy: query.orderBy,
			columns: columns.flatMap((entry) => (entry.kind === 'column' ? [entry.column.name] : [])),
			relations: columns.flatMap((entry) => (entry.kind === 'relation' ? [entry.relation.fieldName] : [])),
			relationPageSize: RELATION_PAGE_SIZE,
		},
		{ signal: options.signal, onPage: options.onProgress },
	);
	return { ...rowsCsvText(columns, rows, { protectFormulas: options.protectFormulas }), rowCount: rows.length };
}

// Files in and out of the browser: read a chosen file as text, save text as a
// download, and the import error report.

import { csvFileText } from './delimited-text';
import { protectFormulaText } from './formula-protection';
import type { ImportIssue } from './import-plan';

/** Shown when a file read as UTF-8 holds characters that could not be decoded. */
export const NOT_UTF8_WARNING =
	'Some characters of this file could not be read. Save the file as UTF-8 text (in a spreadsheet app, "CSV UTF-8") and choose it again.';

/** Read a chosen file as UTF-8 text. */
export async function readTextFile(file: Blob): Promise<string> {
	if (typeof file.text === 'function') return file.text();
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.onload = () => resolve(String(reader.result ?? ''));
		reader.onerror = () => reject(reader.error ?? new Error('The file could not be read.'));
		reader.readAsText(file);
	});
}

/** Save text as a file the browser downloads. */
export function downloadTextFile(text: string, filename: string, type = 'text/csv;charset=utf-8'): void {
	if (typeof document === 'undefined') return;
	const url = URL.createObjectURL(new Blob([text], { type }));
	const link = document.createElement('a');
	link.href = url;
	link.download = filename;
	link.rel = 'noopener';
	document.body.appendChild(link);
	link.click();
	link.remove();
	// Some browsers start the download after the click handler returns.
	setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** A file name from a table name and a suffix, with characters file systems refuse replaced. */
export function safeFileName(base: string, suffix: string): string {
	const cleaned = base.replace(/[\\/:*?"<>|]+/g, '-').trim() || 'records';
	return `${cleaned}${suffix}`;
}

export const NOT_SENT_REASON = 'Not imported: the import stopped before this row was sent.';

/**
 * The error report of an import as CSV: one line per problem, by row. Column names
 * come from the imported file and reasons can quote its values, so text that a
 * spreadsheet app would run as a formula is always protected. The report is read,
 * never imported back, so the apostrophe changes no data.
 */
export function importErrorReportText(issues: readonly ImportIssue[], notSent: readonly number[] = []): string {
	const all = [
		...issues,
		...notSent.map((row): ImportIssue => ({ row, column: '', columnIndex: null, reason: NOT_SENT_REASON })),
	].sort((left, right) => left.row - right.row || (left.columnIndex ?? -1) - (right.columnIndex ?? -1));
	return csvFileText([
		['Row', 'Column', 'Reason'],
		...all.map((issue) => [String(issue.row), protectFormulaText(issue.column), protectFormulaText(issue.reason)]),
	]);
}

// Protection against spreadsheet formulas in exported CSV ("CSV injection").
//
// A spreadsheet app opening a CSV file runs a cell that starts with `=`, `+`, `-`
// or `@` as a formula, and some apps also treat a leading tab or carriage return
// that way. With protection on, such a text value is written with a leading
// apostrophe, which the app shows as text and does not run. It is opt-in: the
// apostrophe changes the value, so a file meant to be imported back as data
// should be written without it.
//
// Only text is protected. A number stored as a number (a negative integer, or a
// big or exact decimal the server sends as a string) is written as is, so it
// stays a number in the spreadsheet.

import type { ColumnModel, ColumnValueKind } from '@constructive-io/data';

/** Characters that make a spreadsheet app treat a cell as a formula. */
const FORMULA_START = /^[=+\-@\t\r]/;

/** Kinds whose values are numbers, even when the server sends them as strings. */
const NUMBER_KINDS: ReadonlySet<ColumnValueKind> = new Set(['integer', 'bigint', 'decimal', 'float']);

/** Options every CSV export takes. */
export interface CsvExportOptions {
	/** Prefix text that starts like a formula with an apostrophe. Default false. */
	protectFormulas?: boolean;
}

/** The text with a leading apostrophe when a spreadsheet app would run it as a formula. */
export function protectFormulaText(text: string): string {
	return FORMULA_START.test(text) ? `'${text}` : text;
}

/** Whether a column holds numbers, which are never prefixed. */
export function isNumberColumn(column: ColumnModel): boolean {
	return NUMBER_KINDS.has(column.value.kind);
}

// From file records to the values of new records, each cell checked first.
//
// Every mapped cell passes the grid's own value parser (`parseColumnInput`), so
// a value the grid would refuse is refused here with the same reason. A blank
// cell leaves its field out, so the table's default applies; a blank cell of a
// required field is an error. A row with any error is not imported; it is
// listed in the error report with its spreadsheet row number.

import { parseColumnInput } from '../cell-types/column-value';
import type { DelimitedTable } from './delimited-text';
import type { ImportMapping, ImportTarget } from './import-targets';
import type { LinkResult } from './linked-records';

/** One problem of the import, as the error report lists it. */
export interface ImportIssue {
	/** Spreadsheet row number of the file (the header is row 1). */
	row: number;
	/** The file column, or '' for a problem of the whole row. */
	column: string;
	/** Index of the file column, or null for a problem of the whole row. */
	columnIndex: number | null;
	reason: string;
}

/** A file row, checked, before its linked records are looked up. */
export interface ImportRowDraft {
	row: number;
	values: Record<string, unknown>;
	/** Cells that name a linked record. */
	links: readonly { target: ImportTarget & { kind: 'relation' }; text: string; columnIndex: number }[];
	issues: ImportIssue[];
}

/** A row ready to be created. */
export interface ImportRow {
	row: number;
	values: Record<string, unknown>;
}

const REQUIRED_REASON = 'This field needs a value.';

/** The name of a file column in messages: its header, or its position when the header is blank. */
export function fileColumnName(header: readonly string[], index: number): string {
	const name = header[index]?.trim();
	return name ? name : `Column ${index + 1}`;
}

/** Check every mapped cell of every record. */
export function draftImportRows(
	table: DelimitedTable,
	mapping: ImportMapping,
	targets: readonly ImportTarget[],
): ImportRowDraft[] {
	const byKey = new Map(targets.map((target) => [target.key, target]));
	const required = new Set(
		targets.flatMap((target) => (target.kind === 'column' && target.column.write.requiredOnCreate ? [target.column.name] : [])),
	);
	const mapped = mapping.flatMap((key, index) => {
		const target = key ? byKey.get(key) : undefined;
		return target ? [{ index, target, column: fileColumnName(table.header, index) }] : [];
	});

	return table.records.map((record) => {
		const values: Record<string, unknown> = {};
		const links: ImportRowDraft['links'][number][] = [];
		const issues: ImportIssue[] = [];
		const issue = (columnIndex: number | null, column: string, reason: string) =>
			issues.push({ row: record.row, column, columnIndex, reason });

		const extra = record.fields.slice(table.header.length);
		if (extra.some((field) => field.trim() !== '')) {
			issue(null, '', `This row has ${record.fields.length} values, but the header has ${table.header.length} columns.`);
		}

		for (const { index, target, column } of mapped) {
			const text = record.fields[index] ?? '';
			if (target.kind === 'relation') {
				if (text.trim() !== '') links.push({ target, text, columnIndex: index });
				else if (target.relation.keys.some((pair) => required.has(pair.local))) issue(index, column, REQUIRED_REASON);
				continue;
			}
			if (text.trim() === '') {
				if (target.column.write.requiredOnCreate) issue(index, column, REQUIRED_REASON);
				continue;
			}
			const parsed = parseColumnInput(target.column, text, { fromText: true, creating: true });
			if (parsed.ok === false) issue(index, column, parsed.reason);
			else values[target.column.name] = parsed.value;
		}
		return { row: record.row, values, links, issues };
	});
}

/** The distinct cell texts that name a linked record, per relation target key. */
export function linkedTexts(drafts: readonly ImportRowDraft[]): Map<string, string[]> {
	const texts = new Map<string, Set<string>>();
	for (const draft of drafts) {
		if (draft.issues.length > 0) continue;
		for (const link of draft.links) {
			const set = texts.get(link.target.key) ?? new Set<string>();
			set.add(link.text);
			texts.set(link.target.key, set);
		}
	}
	return new Map([...texts].map(([key, set]) => [key, [...set]]));
}

/** Rows ready to create, and every problem, once the linked records are known (target key -> text -> result). */
export function finishImportRows(
	drafts: readonly ImportRowDraft[],
	header: readonly string[],
	links: ReadonlyMap<string, ReadonlyMap<string, LinkResult>>,
): { rows: ImportRow[]; issues: ImportIssue[] } {
	const rows: ImportRow[] = [];
	const issues: ImportIssue[] = [];
	for (const draft of drafts) {
		const rowIssues = [...draft.issues];
		const values = { ...draft.values };
		for (const link of draft.links) {
			const result = links.get(link.target.key)?.get(link.text);
			if (result?.ok) {
				Object.assign(values, result.values);
				continue;
			}
			// A row that already has a problem is not looked up; its other problems stand for it.
			if (!result && draft.issues.length > 0) continue;
			rowIssues.push({
				row: draft.row,
				column: fileColumnName(header, link.columnIndex),
				columnIndex: link.columnIndex,
				reason: result && result.ok === false ? result.reason : 'The linked record was not looked up.',
			});
		}
		if (rowIssues.length === 0) rows.push({ row: draft.row, values });
		else issues.push(...rowIssues);
	}
	return { rows, issues };
}

// The Import button and its dialog: file or pasted rows, column mapping, a
// checked preview, the import with progress and cancel, and the error report.

import { useId, useState } from 'react';
import { RiUploadLine } from '@remixicon/react';

import type { TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import {
	Dialog,
	DialogDescription,
	DialogFooter,
	DialogHeader,
	DialogPanel,
	DialogPopup,
	DialogTitle,
} from '@/components/ui/dialog';

import { ToolButton } from '../grid/toolbar/toolbar-button';
import { downloadTextFile, importErrorReportText, safeFileName } from './files';
import { DoneStep, MappingStep, ReviewStep, RunningStep, SourceStep } from './import-steps';
import { useImportRecords } from './use-import-records';

export interface ImportRecordsControlProps {
	/** The table to add records to, or null while it loads. */
	model: TableModel | null;
	/** Name used in the dialog title and the error report's file name. Default: the table name. */
	tableLabel?: string;
}

const DESCRIPTIONS = {
	source: 'Each row of the file becomes a new record.',
	mapping: 'Choose the field each column of the file fills. Columns set to "Do not import" are left out.',
	checking: 'Checking every row of the file.',
	review: 'Rows with problems are not imported. The error report lists them.',
	running: 'Adding records. Rows already sent still finish when you cancel.',
	done: 'The import has finished.',
} as const;

export function ImportRecordsControl({ model, tableLabel }: ImportRecordsControlProps) {
	const flow = useImportRecords(model);
	const [open, setOpen] = useState(false);
	const reasonId = useId();
	const { phase } = flow;
	const label = tableLabel ?? model?.name ?? 'records';
	const busy = phase.step === 'running' || phase.step === 'checking';
	// The first step has no actions of its own (the file and paste buttons sit in the step), so it has no footer band.
	const hasActions = phase.step !== 'source';

	const downloadReport = () => {
		if (phase.step === 'review') downloadTextFile(importErrorReportText(phase.issues), safeFileName(label, '-import-problems.csv'));
		if (phase.step === 'done') {
			const { result, issues } = phase;
			downloadTextFile(
				importErrorReportText([...issues, ...result.failures], result.notSent),
				safeFileName(label, '-import-errors.csv'),
			);
		}
	};
	const reportCount =
		phase.step === 'review'
			? phase.issues.length
			: phase.step === 'done'
				? phase.issues.length + phase.result.failures.length + phase.result.notSent.length
				: 0;

	const close = () => {
		if (busy) return;
		setOpen(false);
		if (phase.step === 'done') flow.reset();
	};

	return (
		<>
			<span title={flow.unavailableReason ?? undefined} className='inline-flex'>
				<ToolButton
					icon={RiUploadLine}
					label='Import'
					title={flow.unavailableReason ? undefined : 'Import records from a CSV file'}
					disabled={Boolean(flow.unavailableReason)}
					aria-describedby={flow.unavailableReason ? reasonId : undefined}
					onClick={() => setOpen(true)}
				/>
				{flow.unavailableReason && (
					<span id={reasonId} className='sr-only'>
						{flow.unavailableReason}
					</span>
				)}
			</span>
			<Dialog open={open} onOpenChange={(next) => (next ? setOpen(true) : close())}>
				<DialogPopup className='max-w-3xl' showCloseButton={!busy}>
					<DialogHeader>
						<DialogTitle>Import into {label}</DialogTitle>
						<DialogDescription>{DESCRIPTIONS[phase.step]}</DialogDescription>
					</DialogHeader>
					<DialogPanel>
						{phase.step === 'source' && <SourceStep flow={flow} />}
						{phase.step === 'mapping' && <MappingStep flow={flow} />}
						{phase.step === 'checking' && (
							<p role='status' className='text-sm'>
								Checking {flow.source?.table.records.length.toLocaleString()} rows…
							</p>
						)}
						{phase.step === 'review' && <ReviewStep flow={flow} rows={phase.rows} issues={phase.issues} />}
						{phase.step === 'running' && <RunningStep progress={phase.progress} />}
						{phase.step === 'done' && <DoneStep result={phase.result} issues={phase.issues} cancelled={phase.cancelled} />}
					</DialogPanel>
					{hasActions && (
						<DialogFooter>
							{reportCount > 0 && (
								<Button variant='outline' onClick={downloadReport}>
									Download error report
								</Button>
							)}
							{(phase.step === 'mapping' || phase.step === 'review') && (
								<Button variant='ghost' onClick={flow.back}>
									Back
								</Button>
							)}
							{busy && (
								<Button variant='outline' onClick={flow.cancel}>
									Cancel
								</Button>
							)}
							{phase.step === 'mapping' && (
								<Button
									disabled={flow.problems.length > 0 || flow.loadingLinkedTables}
									title={flow.loadingLinkedTables ? 'The linked tables are still loading.' : undefined}
									onClick={() => void flow.check()}
								>
									{flow.loadingLinkedTables ? 'Loading linked tables…' : 'Check rows'}
								</Button>
							)}
							{phase.step === 'review' && (
								<Button
									disabled={phase.rows.length === 0}
									title={phase.rows.length === 0 ? 'No row is ready to import.' : undefined}
									onClick={() => void flow.start()}
								>
									{phase.rows.length === 0 ? 'Nothing to import' : `Import ${phase.rows.length.toLocaleString()} ${phase.rows.length === 1 ? 'row' : 'rows'}`}
								</Button>
							)}
							{phase.step === 'done' && (
								<>
									<Button variant='outline' onClick={flow.reset}>
										Import another file
									</Button>
									<Button onClick={close}>Close</Button>
								</>
							)}
						</DialogFooter>
					)}
				</DialogPopup>
			</Dialog>
		</>
	);
}

// The steps of the import dialog. Each step renders what `useImportRecords`
// holds; none of them reads or writes data on its own.

import { useId, useMemo, useRef, useState } from 'react';

import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';

import type { ColumnValueKind } from '@constructive-io/data';

import type { Delimiter } from './delimited-text';
import { fileColumnName, type ImportIssue, type ImportRow } from './import-plan';
import type { ImportProgress, ImportRunResult } from './run-import';
import type { UseImportRecordsResult } from './use-import-records';

/** Rows the review step shows. */
export const PREVIEW_ROWS = 20;

const SKIP = '__skip__';

const DELIMITER_NAMES: Record<Delimiter, string> = { ',': 'Comma', '\t': 'Tab', ';': 'Semicolon', '|': 'Vertical bar' };

function plural(count: number, one: string, many = `${one}s`): string {
	return `${count.toLocaleString()} ${count === 1 ? one : many}`;
}

function Problems({ items, label }: { items: readonly string[]; label: string }) {
	if (items.length === 0) return null;
	return (
		<div role='alert' aria-label={label} className='border-destructive/30 bg-destructive/5 text-destructive rounded-md border px-3 py-2 text-sm'>
			<ul className='list-disc space-y-1 ps-4'>
				{items.map((item) => (
					<li key={item}>{item}</li>
				))}
			</ul>
		</div>
	);
}

export function SourceStep({ flow }: { flow: UseImportRecordsResult }) {
	const fileRef = useRef<HTMLInputElement>(null);
	const pasteId = useId();
	const [pasted, setPasted] = useState('');
	const phase = flow.phase.step === 'source' ? flow.phase : null;

	return (
		<div
			className='space-y-4'
			onDragOver={(event) => event.preventDefault()}
			onDrop={(event) => {
				event.preventDefault();
				const file = event.dataTransfer.files[0];
				if (file) void flow.readFile(file);
			}}
		>
			<div className='border-input flex flex-col items-center gap-2 rounded-md border border-dashed px-4 py-6 text-center'>
				<p className='text-sm'>Choose a CSV or tab-separated file, or drop it here. The first row must name the columns.</p>
				<input
					ref={fileRef}
					type='file'
					accept='.csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain'
					aria-label='Choose a file to import'
					className='sr-only'
					tabIndex={-1}
					onChange={(event) => {
						const file = event.target.files?.[0];
						event.target.value = '';
						if (file) void flow.readFile(file);
					}}
				/>
				<Button variant='outline' size='sm' disabled={phase?.reading} onClick={() => fileRef.current?.click()}>
					{phase?.reading ? 'Reading the file…' : 'Choose a file'}
				</Button>
			</div>
			<div className='space-y-2'>
				<label htmlFor={pasteId} className='text-sm font-medium'>
					Or paste rows from a spreadsheet
				</label>
				<Textarea
					id={pasteId}
					rows={6}
					value={pasted}
					placeholder={'name,code\nFirst record,A1'}
					onChange={(event) => setPasted(event.target.value)}
				/>
				<div className='flex justify-end'>
					<Button variant='outline' size='sm' disabled={pasted.trim() === ''} onClick={() => flow.readText(pasted, '')}>
						Use pasted rows
					</Button>
				</div>
			</div>
			{phase?.error && <Problems items={[phase.error]} label='The rows cannot be read' />}
		</div>
	);
}

export function MappingStep({ flow }: { flow: UseImportRecordsResult }) {
	const { source, mapping, targets } = flow;
	const labels = useMemo(
		() => Object.fromEntries([[SKIP, 'Do not import'], ...targets.map((target) => [target.key, target.label])]) as Record<string, string>,
		[targets],
	);
	if (!source) return null;
	const { table } = source;
	const sample = table.records[0]?.fields ?? [];
	const error = flow.phase.step === 'mapping' ? flow.phase.error ?? null : null;

	return (
		<div className='space-y-4'>
			<div className='flex flex-wrap items-center justify-between gap-2 text-sm'>
				<span role='status'>
					{plural(table.records.length, 'row')} in {source.name}
				</span>
				<span className='flex items-center gap-2'>
					<span className='text-muted-foreground'>Separator</span>
					<Select value={table.delimiter} onValueChange={(value) => flow.setDelimiter(value as Delimiter)}>
						<SelectTrigger size='sm' className='w-[9rem]' aria-label='Separator'>
							<SelectValue />
						</SelectTrigger>
						<SelectContent>
							{(Object.keys(DELIMITER_NAMES) as Delimiter[]).map((delimiter) => (
								<SelectItem key={delimiter} value={delimiter}>
									{DELIMITER_NAMES[delimiter]}
								</SelectItem>
							))}
						</SelectContent>
					</Select>
				</span>
			</div>
			{source.warnings.length > 0 && (
				<p role='status' className='rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-sm'>
					{source.warnings.join(' ')}
				</p>
			)}
			<table className='w-full text-sm'>
				<caption className='sr-only'>Columns of the file and the field each one fills</caption>
				<thead className='text-muted-foreground text-left text-xs'>
					<tr>
						<th className='py-1 pe-3 font-medium'>Column of the file</th>
						<th className='py-1 pe-3 font-medium'>First value</th>
						<th className='py-1 font-medium'>Import into</th>
					</tr>
				</thead>
				<tbody>
					{table.header.map((_, index) => {
						const name = fileColumnName(table.header, index);
						return (
							<tr key={index} className='border-border/60 border-t'>
								<td className='py-1.5 pe-3 font-medium'>{name}</td>
								<td className='text-muted-foreground max-w-[12rem] truncate py-1.5 pe-3' title={sample[index] ?? ''}>
									{sample[index] ?? ''}
								</td>
								<td className='py-1.5'>
									<Select
										value={mapping[index] ?? SKIP}
										items={labels}
										onValueChange={(value) => flow.setTarget(index, value === SKIP ? null : value)}
									>
										<SelectTrigger size='sm' className='w-[14rem]' aria-label={`Field for ${name}`}>
											<SelectValue />
										</SelectTrigger>
										<SelectContent>
											<SelectItem value={SKIP}>Do not import</SelectItem>
											{targets.map((target) => (
												<SelectItem key={target.key} value={target.key}>
													{target.label}
												</SelectItem>
											))}
										</SelectContent>
									</Select>
								</td>
							</tr>
						);
					})}
				</tbody>
			</table>
			<Problems items={error ? [error, ...flow.problems] : flow.problems} label='The import cannot be checked yet' />
		</div>
	);
}

/** Value kinds whose preview column is right-aligned with tabular figures. */
const NUMERIC_KINDS: ReadonlySet<ColumnValueKind> = new Set(['integer', 'bigint', 'decimal', 'float']);
/** Value kinds whose preview column uses tabular figures; dates and times stay left-aligned. */
const TABULAR_KINDS: ReadonlySet<ColumnValueKind> = new Set(['date', 'time', 'datetime', 'interval']);

/** Alignment and figures of a preview column, from the field its file column fills. */
function previewColumnClass(flow: UseImportRecordsResult, columnIndex: number): string {
	const target = flow.targets.find((candidate) => candidate.key === flow.mapping[columnIndex]);
	const kind = target?.kind === 'column' && !target.column.value.isArray ? target.column.value.kind : null;
	if (kind && NUMERIC_KINDS.has(kind)) return 'text-end tabular-nums';
	if (kind && TABULAR_KINDS.has(kind)) return 'tabular-nums';
	return '';
}

/** The reasons of each cell of the preview, by row and file column. */
function issuesByCell(issues: readonly ImportIssue[]): Map<string, string[]> {
	const out = new Map<string, string[]>();
	for (const issue of issues) {
		const key = `${issue.row}:${issue.columnIndex ?? ''}`;
		out.set(key, [...(out.get(key) ?? []), issue.reason]);
	}
	return out;
}

export function ReviewStep({ flow, rows, issues }: { flow: UseImportRecordsResult; rows: readonly ImportRow[]; issues: readonly ImportIssue[] }) {
	const { source, mapping } = flow;
	if (!source) return null;
	const failedRows = new Set(issues.map((issue) => issue.row)).size;
	const columns = mapping.flatMap((key, index) => (key ? [index] : []));
	const cells = issuesByCell(issues);
	const preview = source.table.records.slice(0, PREVIEW_ROWS);

	return (
		<div className='space-y-4'>
			<p role='status' className='text-sm'>
				{plural(rows.length, 'row is', 'rows are')} ready to import.
				{failedRows > 0 && ` ${plural(failedRows, 'row has', 'rows have')} problems and will not be imported.`}
			</p>
			<div className='overflow-x-auto'>
				<table className='w-full text-sm'>
					<caption className='sr-only'>
						The first {Math.min(PREVIEW_ROWS, source.table.records.length)} rows of the file, checked
					</caption>
					<thead className='text-muted-foreground text-left text-xs'>
						<tr>
							<th className='py-1 pe-3 text-end font-medium'>Row</th>
							{/* Problems come before the values, so a wide file never pushes them out of view. */}
							<th className='min-w-[14rem] py-1 pe-3 font-medium'>Problems</th>
							{columns.map((index) => (
								<th key={index} className={`py-1 pe-3 font-medium ${previewColumnClass(flow, index)}`}>
									{fileColumnName(source.table.header, index)}
								</th>
							))}
						</tr>
					</thead>
					<tbody>
						{preview.map((record) => {
							const rowProblems = issues.filter((issue) => issue.row === record.row).map((issue) => issue.reason);
							return (
								<tr key={record.row} className='border-border/60 border-t align-top'>
									<td className='text-muted-foreground py-1.5 pe-3 text-end tabular-nums'>{record.row}</td>
									<td className='text-destructive py-1.5 pe-3'>{rowProblems.join(' ')}</td>
									{columns.map((index) => {
										const reasons = cells.get(`${record.row}:${index}`);
										return (
											<td
												key={index}
												className={`max-w-[10rem] truncate py-1.5 pe-3 ${previewColumnClass(flow, index)}${reasons ? ' text-destructive' : ''}`}
												title={reasons ? reasons.join(' ') : record.fields[index] ?? ''}
												aria-invalid={reasons ? true : undefined}
											>
												{record.fields[index] ?? ''}
											</td>
										);
									})}
								</tr>
							);
						})}
					</tbody>
				</table>
			</div>
			{source.table.records.length > PREVIEW_ROWS && (
				<p className='text-muted-foreground text-xs'>
					Showing the first {PREVIEW_ROWS} rows. The error report lists the problems of every row.
				</p>
			)}
		</div>
	);
}

export function RunningStep({ progress }: { progress: ImportProgress }) {
	return (
		<div className='space-y-3'>
			<Progress value={progress.done} min={0} max={Math.max(progress.total, 1)} aria-label='Import progress' />
			<p role='status' aria-live='polite' className='text-sm tabular-nums'>
				{progress.done.toLocaleString()} of {plural(progress.total, 'row')} sent
				{progress.failed > 0 ? `, ${progress.failed.toLocaleString()} refused` : ''}.
			</p>
		</div>
	);
}

/** Reasons shown for refused rows; the report has every row. */
const TOP_REASONS = 5;

/**
 * Why the server refused rows, most common first, each with how many rows it refused:
 * "Another record already has this value. (1,150 rows)". The rest are counted in one line.
 */
export function refusalReasons(failures: readonly ImportIssue[], limit = TOP_REASONS): string[] {
	const counts = new Map<string, number>();
	for (const failure of failures) counts.set(failure.reason, (counts.get(failure.reason) ?? 0) + 1);
	const ranked = [...counts].sort((a, b) => b[1] - a[1]);
	const lines = ranked.slice(0, limit).map(([reason, count]) => `${reason} (${plural(count, 'row')})`);
	const rest = ranked.slice(limit).reduce((sum, [, count]) => sum + count, 0);
	if (rest > 0) lines.push(`${plural(rest, 'more row was', 'more rows were')} refused for other reasons; the report lists each one.`);
	return lines;
}

export function DoneStep({ result, issues, cancelled }: { result: ImportRunResult; issues: readonly ImportIssue[]; cancelled: boolean }) {
	const skipped = new Set(issues.map((issue) => issue.row)).size;
	const lines = [
		`${plural(result.created, 'record')} ${result.created === 1 ? 'was' : 'were'} added.`,
		result.failures.length > 0 ? `${plural(result.failures.length, 'row was', 'rows were')} refused.` : null,
		skipped > 0 ? `${plural(skipped, 'row was', 'rows were')} not imported because of problems in the file.` : null,
		result.notSent.length > 0
			? `${plural(result.notSent.length, 'row was', 'rows were')} not sent, because the import ${cancelled ? 'was cancelled' : 'stopped'}.`
			: null,
	].filter((line): line is string => Boolean(line));

	return (
		<div className='space-y-3'>
			<p role='status' className='text-sm'>
				{lines.join(' ')}
			</p>
			<Problems items={refusalReasons(result.failures)} label='Why rows were refused' />
			{result.stopReason && <Problems items={[result.stopReason]} label='The import stopped' />}
		</div>
	);
}

// What a column of an imported file can fill, and the automatic header match.
//
// A file column fills one field a new record accepts (`write.create`), or a
// linked record of a belongsTo relation, matched later by an exact key value or
// an exact unique label. Matching a header to a field compares letters and
// digits only (`Due on`, `due_on` and `dueOn` match `dueOn`); a header that
// matches no field, or more than one, starts unmapped.

import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import { fieldLabel, relationLabelIn } from '../cell-types/field-label';

export type ImportTarget =
	| { kind: 'column'; key: string; label: string; column: ColumnModel }
	| { kind: 'relation'; key: string; label: string; relation: RelationModel };

/** A header index -> target key, or null for "do not import". */
export type ImportMapping = readonly (string | null)[];

/** Kinds a file cell cannot carry: files need an upload, the rest can only be viewed. */
const NOT_IMPORTABLE = new Set(['file', 'binary', 'vector', 'fulltext', 'unknown']);

function normalized(text: string): string {
	return text.replace(/[^A-Za-z0-9]/g, '').toLowerCase();
}

/** Fields of a new record a file can fill, in the model's order. */
export function importTargets(model: TableModel): ImportTarget[] {
	const columns: ImportTarget[] = model.columns
		.filter((column) => column.write.create && !NOT_IMPORTABLE.has(column.value.kind))
		.map((column) => ({ kind: 'column', key: `column:${column.name}`, label: fieldLabel(column.name), column }));
	const writable = new Set(columns.map((target) => (target.kind === 'column' ? target.column.name : '')));
	const relations: ImportTarget[] = model.relations
		.filter(
			(relation) =>
				relation.kind === 'belongsTo' &&
				relation.editable &&
				relation.targetKey !== null &&
				relation.keys.length > 0 &&
				relation.keys.every((pair) => writable.has(pair.local)),
		)
		.map((relation) => ({ kind: 'relation', key: `relation:${relation.fieldName}`, label: relationLabelIn(model, relation), relation }));
	return [...columns, ...relations];
}

/** The fields a target writes. */
export function targetFields(target: ImportTarget): string[] {
	return target.kind === 'column' ? [target.column.name] : target.relation.keys.map((pair) => pair.local);
}

/** The automatic mapping: each header to the one target it names, each target used at most once. */
export function matchHeaders(headers: readonly string[], targets: readonly ImportTarget[]): (string | null)[] {
	const used = new Set<string>();
	return headers.map((header) => {
		const wanted = normalized(header);
		if (!wanted) return null;
		const matches = targets.filter((target) => {
			const name = target.kind === 'column' ? target.column.name : target.relation.fieldName;
			return normalized(name) === wanted || normalized(target.label) === wanted;
		});
		const [match] = matches;
		if (matches.length !== 1 || !match || used.has(match.key)) return null;
		used.add(match.key);
		return match.key;
	});
}

/** Why a mapping cannot be imported as it stands, or an empty list. */
export function mappingProblems(mapping: ImportMapping, targets: readonly ImportTarget[], model: TableModel): string[] {
	const byKey = new Map(targets.map((target) => [target.key, target]));
	const mapped = mapping.flatMap((key) => {
		const target = key ? byKey.get(key) : undefined;
		return target ? [target] : [];
	});
	if (mapped.length === 0) return ['Choose a field for at least one column of the file.'];
	const problems: string[] = [];

	const uses = new Map<ImportTarget, number>();
	for (const target of mapped) uses.set(target, (uses.get(target) ?? 0) + 1);
	for (const [target, count] of uses) {
		if (count > 1) problems.push(`${target.label} is chosen for ${count} columns of the file. Choose it for one column.`);
	}

	// A linked record writes its key fields, so the same field cannot also come from a column of its own.
	const writers = new Map<string, ImportTarget>();
	for (const target of uses.keys()) {
		for (const field of targetFields(target)) {
			const other = writers.get(field);
			if (other) problems.push(`${other.label} and ${target.label} both set ${fieldLabel(field)}. Choose one of them.`);
			else writers.set(field, target);
		}
	}

	const importable = new Set(targets.flatMap(targetFields));
	for (const column of model.columns) {
		if (!column.write.requiredOnCreate || writers.has(column.name)) continue;
		const label = fieldLabel(column.name);
		problems.push(
			importable.has(column.name)
				? `Every new record needs ${label}. Choose a column of the file for it.`
				: `Every new record needs ${label}, and ${label} cannot be set from a file.`,
		);
	}
	return problems;
}

// Find the linked record a file cell names, for a belongsTo column of an import.
//
// A cell names a record by an exact key value or by an exact label (the related
// table's label fields). Each distinct cell text is looked up once, in batches,
// with the filter fields and operators the related table really has. A text
// that matches exactly one record links to it; a text that matches no record,
// or more than one, is an error of its row. Nothing is guessed: no partial,
// case-insensitive or trimmed matching.

import type { ColumnModel, RelationModel, TableModel } from '@constructive-io/data';

import { parseColumnInput } from '../cell-types/column-value';
import { fieldLabel, relationFieldLabel } from '../cell-types/field-label';
import { readAllRows, type RowSource } from './read-all-rows';

type RowRecord = Record<string, unknown>;

/** The key values a cell text links to, or why it links to nothing. */
export type LinkResult = { ok: true; values: Record<string, unknown> } | { ok: false; reason: string };

/** Values per lookup request. */
const LOOKUP_BATCH = 50;

interface Matcher {
	column: ColumnModel;
	/** Filter input field of the column. */
	filterField: string;
}

function isAbort(error: unknown, signal: AbortSignal | undefined): boolean {
	return Boolean(signal?.aborted) || (error instanceof Error && error.name === 'AbortError');
}

/** One value as a comparable string. UUIDs compare without case, everything else exactly. */
function comparable(column: ColumnModel, value: unknown): string | null {
	if (value === null || value === undefined) return null;
	const text = typeof value === 'string' ? value : JSON.stringify(value);
	return column.value.kind === 'uuid' ? text.toLowerCase() : text;
}

/** Columns of the related table that can find a record by an exact value: the linked key, then the label fields. */
function matchersOf(relation: RelationModel, target: TableModel): Matcher[] {
	const fields = [...(relation.keys.length === 1 ? [relation.keys[0]!.remote] : []), ...relation.target.labelFields];
	const matchers: Matcher[] = [];
	for (const field of new Set(fields)) {
		const column = target.columns.find((candidate) => candidate.name === field);
		const filter = column?.filter;
		if (!column || !filter || !column.readable || column.value.isArray) continue;
		if (!filter.operators.some((operator) => operator.name === 'in')) continue;
		matchers.push({ column, filterField: filter.field });
	}
	return matchers;
}

/** Why the records of the related table cannot be matched at all, or null. */
export function linkUnavailableReason(relation: RelationModel, target: TableModel | null): string | null {
	const label = relationFieldLabel(relation);
	if (!target) return `The records of ${label} could not be loaded, so no record can be linked.`;
	if (!target.operations.list?.filter) return `The records of ${label} cannot be searched, so no record can be linked.`;
	const remote = relation.keys.map((pair) => target.columns.find((column) => column.name === pair.remote));
	if (remote.some((column) => !column?.readable)) return `The records of ${label} cannot be read, so no record can be linked.`;
	if (matchersOf(relation, target).length === 0) return `The records of ${label} cannot be found by a value.`;
	return null;
}

function chunks<T>(items: readonly T[], size: number): T[][] {
	const out: T[][] = [];
	for (let index = 0; index < items.length; index += size) out.push(items.slice(index, index + size));
	return out;
}

/**
 * Resolve each distinct cell text of a belongsTo column to the key values of
 * the one record it names. Throws only when `signal` aborts.
 */
export async function resolveLinkedRecords(
	relation: RelationModel,
	source: Omit<RowSource, 'model'> & { target: TableModel | null },
	texts: readonly string[],
	signal?: AbortSignal,
): Promise<Map<string, LinkResult>> {
	const results = new Map<string, LinkResult>();
	const distinct = [...new Set(texts)];
	const unavailable = linkUnavailableReason(relation, source.target);
	if (unavailable || !source.target) {
		for (const text of distinct) results.set(text, { ok: false, reason: unavailable ?? '' });
		return results;
	}
	const target = source.target;
	const matchers = matchersOf(relation, target);
	const remoteFields = relation.keys.map((pair) => pair.remote);
	const columns = [...new Set([...remoteFields, ...matchers.map((matcher) => matcher.column.name)])];

	// Text -> the records it matches, by their linked key values.
	const found = new Map<string, Map<string, RowRecord>>(distinct.map((text) => [text, new Map()]));
	try {
		for (const matcher of matchers) {
			// Comparable value -> the parsed value and the texts that parse to it.
			const values = new Map<string, { value: unknown; texts: string[] }>();
			for (const text of distinct) {
				const parsed = parseColumnInput(matcher.column, text, { fromText: true });
				const key = parsed.ok ? comparable(matcher.column, parsed.value) : null;
				if (!parsed.ok || key === null) continue;
				const entry = values.get(key) ?? { value: parsed.value, texts: [] };
				entry.texts.push(text);
				values.set(key, entry);
			}
			for (const batch of chunks([...values.values()], LOOKUP_BATCH)) {
				const rows = await readAllRows(
					{ adapter: source.adapter, execute: source.execute, model: target },
					{ where: { [matcher.filterField]: { in: batch.map((entry) => entry.value) } }, columns, relations: 'none' },
					{ signal },
				);
				for (const row of rows) {
					const key = comparable(matcher.column, row[matcher.column.name]);
					const entry = key === null ? undefined : values.get(key);
					if (!entry || remoteFields.some((field) => row[field] === null || row[field] === undefined)) continue;
					const identity = JSON.stringify(remoteFields.map((field) => row[field]));
					for (const text of entry.texts) found.get(text)!.set(identity, row);
				}
			}
		}
	} catch (error) {
		if (isAbort(error, signal)) throw error;
		const message = error instanceof Error && error.message ? ` ${error.message}` : '';
		for (const text of distinct) results.set(text, { ok: false, reason: `The linked records could not be looked up.${message}` });
		return results;
	}

	const byWhat = matchers.map((matcher) => fieldLabel(matcher.column.name).toLowerCase()).join(' or ');
	for (const text of distinct) {
		const records = [...found.get(text)!.values()];
		const [record] = records;
		if (records.length === 1 && record) {
			results.set(text, { ok: true, values: Object.fromEntries(relation.keys.map((pair) => [pair.local, record[pair.remote]])) });
		} else if (records.length === 0) {
			results.set(text, { ok: false, reason: `No record has "${text}" as its ${byWhat}.` });
		} else {
			results.set(text, { ok: false, reason: `${records.length} records match "${text}". Use a value that only one record has.` });
		}
	}
	return results;
}

// Every row of a list query, read page by page.
//
// A table that continues from a cursor is read that way, because a cursor keeps
// its place while rows change. Otherwise pages are read by offset, and the
// primary key is added as the last sort key so that rows with equal sort values
// keep one order from page to page. Only the first page asks for the total count.

import type { SortSpec, TableModel } from '@constructive-io/data';

import type { AdapterListQuery, SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsExecuteFn } from '../context/sheets-execute';

type RowRecord = Record<string, unknown>;

/** Where rows are read from. */
export interface RowSource {
	adapter: SheetsBackendAdapter;
	execute: SheetsExecuteFn;
	model: TableModel;
}

/** What to read: the query without its paging. */
export type RowQuery = Omit<AdapterListQuery, 'limit' | 'offset' | 'after' | 'includeTotalCount' | 'signal'>;

export interface ReadAllRowsOptions {
	/** Rows per request. Default 200. */
	pageSize?: number;
	signal?: AbortSignal;
	/** After each page: the rows read so far, and the total the first page counted (null when the table cannot count). */
	onPage?: (progress: { loaded: number; total: number | null }) => void;
}

const DEFAULT_PAGE_SIZE = 200;

function withKeyOrder(model: TableModel, orderBy: readonly SortSpec[] | undefined): readonly SortSpec[] | undefined {
	const sorted = new Set((orderBy ?? []).map((spec) => spec.field));
	const keyColumns = model.primaryKey.map((field) => model.columns.find((column) => column.name === field));
	if (keyColumns.some((column) => !column?.sort)) return orderBy;
	const tail = model.primaryKey.filter((field) => !sorted.has(field)).map((field): SortSpec => ({ field, direction: 'asc' }));
	return tail.length ? [...(orderBy ?? []), ...tail] : orderBy;
}

/** Throw the abort reason when the signal has aborted. */
export function stopIfAborted(signal: AbortSignal | undefined): void {
	if (signal?.aborted) throw signal.reason ?? new DOMException('The operation was aborted.', 'AbortError');
}

/** Read every row the query matches. Throws the abort reason when `signal` aborts. */
export async function readAllRows(source: RowSource, query: RowQuery, options: ReadAllRowsOptions = {}): Promise<RowRecord[]> {
	const { adapter, execute, model } = source;
	const list = model.operations.list;
	const pageSize = options.pageSize ?? DEFAULT_PAGE_SIZE;
	const ctx = { model, tableName: model.key };
	const byCursor = Boolean(list?.after && list.pageInfo);
	// A list that can neither continue from a cursor nor skip rows is read in one request.
	const paged = Boolean(list?.first && (byCursor || list.offset));
	const orderBy = byCursor || !paged ? query.orderBy : withKeyOrder(model, query.orderBy);

	const rows: RowRecord[] = [];
	let total: number | null = null;
	let cursor: string | undefined;
	for (let page = 0; ; page += 1) {
		stopIfAborted(options.signal);
		const result = await adapter.listRows<RowRecord>(
			ctx,
			{
				...query,
				orderBy,
				limit: paged ? pageSize : undefined,
				offset: paged && !byCursor && rows.length > 0 ? rows.length : undefined,
				after: byCursor ? cursor : undefined,
				includeTotalCount: page === 0 && Boolean(list?.totalCount),
				signal: options.signal,
			},
			execute,
		);
		if (page === 0 && list?.totalCount) total = result.totalCount;
		rows.push(...result.rows);
		options.onPage?.({ loaded: rows.length, total });

		if (!paged || result.rows.length === 0) break;
		if (byCursor) {
			const next = result.pageInfo?.endCursor ?? undefined;
			if (!result.pageInfo?.hasNextPage || !next || next === cursor) break;
			cursor = next;
		} else if (result.rows.length < pageSize) {
			break;
		}
	}
	return rows;
}

// Create the checked rows of an import, a few at a time.
//
// A small pool of workers takes rows in file order, so the server sees a bounded
// number of creates at once. Cancelling stops new creates; a create already sent
// is not aborted, because the server may have saved it, so its outcome is still
// counted. An ended session also stops the run, since every later create would
// fail the same way. Rows that were never sent are reported, so they can be
// imported again.

import { getErrorCode, isAuthenticationError } from '@constructive-io/data';

import type { ImportIssue, ImportRow } from './import-plan';

export interface ImportProgress {
	/** Rows sent and answered. */
	done: number;
	created: number;
	failed: number;
	total: number;
}

export interface ImportRunResult {
	created: number;
	/** Rows the server refused, with its reason. */
	failures: ImportIssue[];
	/** Rows never sent, because the run was cancelled or stopped. */
	notSent: number[];
	/** Why the run stopped early, or null when it sent every row or was cancelled. */
	stopReason: string | null;
}

export interface RunImportOptions {
	/** Creates in flight at once. Default 4. */
	concurrency?: number;
	/** Stops sending new rows when it aborts. */
	signal?: AbortSignal;
	onProgress?: (progress: ImportProgress) => void;
	/** The reason a failed create shows. */
	describeError: (error: unknown) => string;
}

const DEFAULT_CONCURRENCY = 4;
/** After an ended session or a suspended database, no later create can succeed. */
function stopsTheRun(error: unknown): boolean {
	return isAuthenticationError(error) || getErrorCode(error) === 'ACCESS_SUSPENDED';
}

export async function runImport(
	rows: readonly ImportRow[],
	create: (values: Record<string, unknown>) => Promise<unknown>,
	options: RunImportOptions,
): Promise<ImportRunResult> {
	const concurrency = Math.max(1, Math.min(options.concurrency ?? DEFAULT_CONCURRENCY, rows.length || 1));
	const failures: ImportIssue[] = [];
	const sent = new Set<number>();
	let created = 0;
	let next = 0;
	let stopReason: string | null = null;

	const report = () =>
		options.onProgress?.({ done: created + failures.length, created, failed: failures.length, total: rows.length });

	const work = async () => {
		while (next < rows.length && !options.signal?.aborted && stopReason === null) {
			const index = next;
			next += 1;
			const row = rows[index]!;
			sent.add(index);
			try {
				await create(row.values);
				created += 1;
			} catch (error) {
				const reason = options.describeError(error);
				failures.push({ row: row.row, column: '', columnIndex: null, reason });
				if (stopsTheRun(error)) stopReason ??= reason;
			}
			report();
		}
	};

	report();
	await Promise.all(Array.from({ length: concurrency }, work));
	failures.sort((left, right) => left.row - right.row);
	const notSent = rows.flatMap((row, index) => (sent.has(index) ? [] : [row.row]));
	return { created, failures, notSent, stopReason };
}

// The import flow of one table, as state a dialog renders: read a file or pasted
// text, map its columns to fields, check every row, create the rows, report.

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';

import type { TableModel } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
import { writeErrorMessages } from '../grid/feedback/write-errors';
import { sheetsQueryKeys } from '../hooks/query-keys';
import { useTableModels } from '../hooks/use-table-model';
import { readDelimitedTable, type DelimitedTable, type Delimiter } from './delimited-text';
import { NOT_UTF8_WARNING, readTextFile } from './files';
import { draftImportRows, finishImportRows, linkedTexts, type ImportIssue, type ImportRow } from './import-plan';
import { importTargets, mappingProblems, matchHeaders, type ImportMapping, type ImportTarget } from './import-targets';
import { resolveLinkedRecords, type LinkResult } from './linked-records';
import { runImport, type ImportProgress, type ImportRunResult } from './run-import';

export interface ImportSource {
	/** The file name, or "Pasted text". */
	name: string;
	text: string;
	table: DelimitedTable;
	/** Problems that do not stop the import, such as characters that could not be read. */
	warnings: readonly string[];
}

export type ImportPhase =
	| { step: 'source'; reading: boolean; error: string | null }
	| { step: 'mapping'; error?: string | null }
	| { step: 'checking' }
	| { step: 'review'; rows: readonly ImportRow[]; issues: readonly ImportIssue[] }
	| { step: 'running'; rows: readonly ImportRow[]; issues: readonly ImportIssue[]; progress: ImportProgress }
	| { step: 'done'; issues: readonly ImportIssue[]; result: ImportRunResult; cancelled: boolean };

export interface UseImportRecordsResult {
	phase: ImportPhase;
	/** Why the table takes no import, or null. */
	unavailableReason: string | null;
	targets: readonly ImportTarget[];
	source: ImportSource | null;
	mapping: ImportMapping;
	/** Why the current mapping cannot be checked yet; empty when it can. */
	problems: readonly string[];
	/** True while the tables of the chosen linked records load. */
	loadingLinkedTables: boolean;
	readText: (text: string, name: string) => void;
	readFile: (file: File) => Promise<void>;
	setDelimiter: (delimiter: Delimiter) => void;
	setTarget: (columnIndex: number, targetKey: string | null) => void;
	check: () => Promise<void>;
	start: () => Promise<void>;
	/** Stop checking or creating. Rows already sent still finish. */
	cancel: () => void;
	back: () => void;
	reset: () => void;
}

const PASTED_NAME = 'Pasted text';
/** What a UTF-8 reader puts in place of bytes it cannot decode. */
const REPLACEMENT_CHARACTER = '\uFFFD';

function readSource(text: string, name: string, delimiter?: Delimiter): ImportSource | string {
	const table = readDelimitedTable(text, delimiter);
	if (table.header.every((cell) => cell.trim() === '')) return 'There are no rows to import. The first row must name the columns.';
	if (table.records.length === 0) return 'There is a header row, but no rows under it to import.';
	if (table.unclosedQuoteRow !== null) {
		return `A quoted value that starts on row ${table.unclosedQuoteRow} is never closed. Check the quotes in the file and try again.`;
	}
	return { name, text, table, warnings: text.includes(REPLACEMENT_CHARACTER) ? [NOT_UTF8_WARNING] : [] };
}

function unavailableReasonOf(model: TableModel | null, targets: readonly ImportTarget[]): string | null {
	if (!model) return 'Import is available once the table has loaded.';
	if (!model.operations.create) {
		return model.issues.find((issue) => issue.scope === 'operation' && issue.target === 'create')?.message ?? 'New records cannot be added to this table.';
	}
	if (targets.length === 0) return 'No field of this table can be set from a file.';
	return null;
}

export function useImportRecords(model: TableModel | null): UseImportRecordsResult {
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const queryClient = useQueryClient();

	const targets = useMemo(() => (model ? importTargets(model) : []), [model]);
	const [phase, setPhase] = useState<ImportPhase>({ step: 'source', reading: false, error: null });
	const [source, setSource] = useState<ImportSource | null>(null);
	const [mapping, setMapping] = useState<ImportMapping>([]);
	const controllerRef = useRef<AbortController | null>(null);

	useEffect(() => () => controllerRef.current?.abort(), []);

	const linkedTargetKeys = useMemo(() => {
		const keys = new Set<string>();
		for (const key of mapping) {
			const target = targets.find((candidate) => candidate.key === key);
			if (target?.kind === 'relation' && target.relation.targetKey) keys.add(target.relation.targetKey);
		}
		return [...keys];
	}, [mapping, targets]);
	const { models: linkedModels, isLoading: loadingLinkedTables } = useTableModels(linkedTargetKeys);

	const problems = useMemo(
		() => (model && source ? mappingProblems(mapping, targets, model) : []),
		[mapping, model, source, targets],
	);

	const applySource = useCallback(
		(next: ImportSource | string) => {
			if (typeof next === 'string') {
				setPhase({ step: 'source', reading: false, error: next });
				return;
			}
			setSource(next);
			setMapping(matchHeaders(next.table.header, targets));
			setPhase({ step: 'mapping' });
		},
		[targets],
	);

	const readText = useCallback((text: string, name: string) => applySource(readSource(text, name || PASTED_NAME)), [applySource]);

	const readFile = useCallback(
		async (file: File) => {
			setPhase({ step: 'source', reading: true, error: null });
			try {
				applySource(readSource(await readTextFile(file), file.name));
			} catch {
				setPhase({ step: 'source', reading: false, error: `${file.name} could not be read.` });
			}
		},
		[applySource],
	);

	const setDelimiter = useCallback(
		(delimiter: Delimiter) => {
			if (source) applySource(readSource(source.text, source.name, delimiter));
		},
		[source, applySource],
	);

	const setTarget = useCallback((columnIndex: number, targetKey: string | null) => {
		setMapping((current) => current.map((key, index) => (index === columnIndex ? targetKey : key)));
	}, []);

	const check = useCallback(async () => {
		if (!model || !source || problems.length > 0) return;
		const controller = new AbortController();
		controllerRef.current = controller;
		setPhase({ step: 'checking' });
		try {
			const drafts = draftImportRows(source.table, mapping, targets);
			const links = new Map<string, Map<string, LinkResult>>();
			for (const [key, texts] of linkedTexts(drafts)) {
				const target = targets.find((candidate) => candidate.key === key);
				if (target?.kind !== 'relation') continue;
				const linked = target.relation.targetKey ? linkedModels.get(target.relation.targetKey) ?? null : null;
				links.set(key, await resolveLinkedRecords(target.relation, { adapter, execute, target: linked }, texts, controller.signal));
			}
			const { rows, issues } = finishImportRows(drafts, source.table.header, links);
			if (!controller.signal.aborted) setPhase({ step: 'review', rows, issues });
		} catch {
			setPhase({ step: 'mapping', error: controller.signal.aborted ? null : 'The rows could not be checked. Try again.' });
		}
	}, [adapter, execute, linkedModels, mapping, model, problems.length, source, targets]);

	const start = useCallback(async () => {
		if (!model || phase.step !== 'review' || phase.rows.length === 0) return;
		const { rows, issues } = phase;
		const controller = new AbortController();
		controllerRef.current = controller;
		const ctx = { model, tableName: model.key };
		setPhase({ step: 'running', rows, issues, progress: { done: 0, created: 0, failed: 0, total: rows.length } });
		const result = await runImport(rows, (values) => adapter.createRow(ctx, values, execute), {
			signal: controller.signal,
			describeError: (error) => writeErrorMessages(error, 'create').join(' '),
			onProgress: (progress) => setPhase((current) => (current.step === 'running' ? { ...current, progress } : current)),
		});
		if (result.created > 0) {
			// Every cached page of the table, in each paging mode. A bare table name is a prefix of each schema's entries.
			for (const queryKey of [
				sheetsQueryKeys.table(scopeKey, model.name),
				sheetsQueryKeys.infiniteTable(scopeKey, model.name),
				sheetsQueryKeys.cursorTable(scopeKey, model.name).slice(0, -1),
			]) {
				void queryClient.invalidateQueries({ queryKey });
			}
		}
		setPhase({ step: 'done', issues, result, cancelled: controller.signal.aborted });
	}, [adapter, execute, model, phase, queryClient, scopeKey]);

	const cancel = useCallback(() => controllerRef.current?.abort(), []);

	const back = useCallback(() => {
		controllerRef.current?.abort();
		setPhase((current) => {
			if (current.step === 'mapping') return { step: 'source', reading: false, error: null };
			if (current.step === 'review' || current.step === 'checking') return { step: 'mapping' };
			return current;
		});
	}, []);

	const reset = useCallback(() => {
		controllerRef.current?.abort();
		setSource(null);
		setMapping([]);
		setPhase({ step: 'source', reading: false, error: null });
	}, []);

	return {
		phase,
		unavailableReason: unavailableReasonOf(model, targets),
		targets,
		source,
		mapping,
		problems,
		loadingLinkedTables,
		readText,
		readFile,
		setDelimiter,
		setTarget,
		check,
		start,
		cancel,
		back,
		reset,
	};
}

