'use client';

// A new record filled in the panel (an alternative to a draft row). Every field uses
// the grid's editor and parser; nothing is sent until Create. The model form schema
// checks the whole record first: fields the create requires, and every value by its
// column's rules. Only fields the user set are sent (the database fills the rest), and
// a field the create does not accept is never sent. On success the panel shows the
// created record.

import { useMemo, useState } from 'react';

import type { ColumnModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import { SheetDescription, SheetFooter, SheetHeader, SheetTitle } from '@/components/ui/sheet';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import { parseColumnInput } from '../cell-types/column-value';
import { buildModelFormSchema, buildModelFormSpec } from '../forms/model-form';
import { writeErrorMessages } from '../grid/feedback/write-errors';
import { useSheetsTable } from '../hooks/use-sheets-table';
import { useTableModel } from '../hooks/use-table-model';
import type { SheetsOpenRecordRequest } from '../relations/relation-navigation';
import { RecordField } from './record-field';
import { recordFieldCell, recordLayout } from './record-layout';
import type { RecordRelationSectionComponent } from './record-relation-section';
import { recordKeyOf, recordTitle, type RecordPanelNewEntry, type RecordPanelRecordEntry } from './record-target';

type RowRecord = Record<string, unknown>;

export interface RecordCreateViewProps {
	entry: RecordPanelNewEntry;
	registry: CellTypeRegistry;
	typeOverrides?: Readonly<Record<string, string>>;
	/** Why files cannot be changed here (no storage endpoint), or null. */
	mediaReason?: string | null;
	/** The record was created: show it. */
	onCreated: (entry: RecordPanelRecordEntry) => void;
	/** Leave without creating. */
	onCancel: () => void;
	/** A record was created; refresh the grid. */
	onInvalidate: () => void;
	/** Open a linked record (from a belongsTo section). */
	onOpenRecord: (request: SheetsOpenRecordRequest) => void;
	RelationSection: RecordRelationSectionComponent | null;
}

function withoutKey(record: Readonly<Record<string, string>>, key: string): Record<string, string> {
	if (!(key in record)) return record;
	const { [key]: _removed, ...rest } = record;
	return rest;
}

export function RecordCreateView({ entry, registry, typeOverrides, mediaReason, onCreated, onCancel, onInvalidate, onOpenRecord, RelationSection }: RecordCreateViewProps) {
	const { model, isLoading, error: modelError } = useTableModel(entry.tableName);
	const table = useSheetsTable<RowRecord>(entry.tableName, { enabled: false });
	const [values, setValues] = useState<RowRecord>({});
	const [errors, setErrors] = useState<Record<string, string>>({});
	const [submitError, setSubmitError] = useState<string | null>(null);
	const [creating, setCreating] = useState(false);
	const recordId = `${entry.tableKey}:new`;

	const spec = useMemo(() => (model ? buildModelFormSpec(model, 'create', { typeOverrides }) : null), [model, typeOverrides]);
	const layout = useMemo(
		() => (model ? recordLayout(model, { mode: 'create', row: values, withRelations: RelationSection !== null, typeOverrides, mediaReason }) : []),
		[model, values, RelationSection, typeOverrides, mediaReason],
	);
	const createReason = model && !model.operations.create
		? model.issues.find((issue) => issue.scope === 'operation' && issue.target === 'create')?.message ?? 'New records cannot be added to this table.'
		: null;

	function setField(column: ColumnModel, value: unknown, fromText: boolean): boolean {
		const parsed = parseColumnInput(column, value, { fromText, creating: true });
		if (parsed.ok === false) {
			setErrors((current) => ({ ...current, [column.name]: parsed.reason }));
			return false;
		}
		setErrors((current) => withoutKey(current, column.name));
		setSubmitError(null);
		setValues((current) => ({ ...current, [column.name]: parsed.value }));
		return true;
	}

	async function submit() {
		if (!model || !spec || creating || createReason) return;
		const result = buildModelFormSchema(spec).safeParse(values);
		if (!result.success) {
			const next: Record<string, string> = {};
			for (const issue of result.error.issues) {
				const field = String(issue.path[0] ?? '');
				if (field && !(field in next)) next[field] = issue.message;
			}
			setErrors(next);
			setSubmitError('Some fields need attention before the record can be created.');
			return;
		}
		const createValues = Object.fromEntries(Object.entries(result.data).filter(([, value]) => value !== undefined));
		setCreating(true);
		setSubmitError(null);
		try {
			const { createdRow } = await table.create(createValues);
			onInvalidate();
			const key = recordKeyOf(model, createdRow);
			if (!createdRow || !key) {
				setSubmitError('The record was created, but the server did not return its key, so it cannot be opened here.');
				return;
			}
			onCreated({ kind: 'record', tableKey: model.key, tableName: model.name, key, label: recordTitle(model, createdRow) });
		} catch (error) {
			setSubmitError(writeErrorMessages(error, 'create').join('\n'));
		} finally {
			setCreating(false);
		}
	}

	return (
		<div
			data-slot='record-create'
			className='flex min-h-0 flex-1 flex-col gap-4'
			onKeyDown={(e) => {
				if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
					e.preventDefault();
					void submit();
				}
			}}
		>
			<SheetHeader className='gap-1'>
				<span className='text-muted-foreground text-xs font-medium'>{entry.tableName}</span>
				<SheetTitle>New record</SheetTitle>
				<SheetDescription>Fill in the fields, then create the record. Fields marked * are required.</SheetDescription>
				{createReason ? <p className='text-muted-foreground text-xs'>{createReason}</p> : null}
			</SheetHeader>

			{modelError ? (
				<p role='alert' className='text-destructive text-sm'>This table could not be loaded: {modelError.message}</p>
			) : isLoading || !model ? (
				<div aria-busy='true' className='flex flex-col gap-3'>
					{[0, 1, 2].map((index) => (
						<div key={index} className='bg-muted h-10 animate-pulse rounded-md' />
					))}
				</div>
			) : (
				<div className='flex flex-col gap-4'>
					{layout.map((item) =>
						item.kind === 'field' ? (
							<RecordField
								key={item.field.name}
								name={item.field.name}
								label={item.field.label}
								description={item.field.description}
								column={item.field.column}
								cellType={item.cellType}
								readOnlyReason={item.readOnlyReason}
								required={item.field.required}
								emptyText={item.emptyText}
								value={values[item.field.name]}
								cell={recordFieldCell(registry, model, item, values[item.field.name], false)}
								saving={false}
								error={errors[item.field.name] ?? null}
								registry={registry}
								table={model}
								row={values}
								rowIdentifier={null}
								recordId={recordId}
								onSave={(value, fromText) => setField(item.field.column, value, fromText)}
								onCommitPatch={(patch) => setValues((current) => ({ ...current, ...patch }))}
								onInvalidate={onInvalidate}
							/>
						) : RelationSection ? (
							<RelationSection
								key={item.relation.fieldName}
								table={model}
								relation={item.relation}
								row={values}
								rowIdentifier={null}
								isDraft
								required={item.required}
								readOnlyReason={item.readOnlyReason}
								onCommitPatch={(patch) => setValues((current) => ({ ...current, ...patch }))}
								onInvalidateData={onInvalidate}
								onOpenRecord={onOpenRecord}
							/>
						) : null,
					)}
				</div>
			)}

			<SheetFooter variant='band' className='mt-auto'>
				{submitError ? (
					<p role='alert' className='text-destructive me-auto text-xs whitespace-pre-wrap'>
						{submitError}
					</p>
				) : null}
				<Button size='sm' variant='outline' onClick={onCancel} disabled={creating}>
					Cancel
				</Button>
				<Button size='sm' onClick={() => void submit()} disabled={creating || Boolean(createReason) || !model} title={createReason ?? undefined}>
					{creating ? 'Creating…' : 'Create record'}
				</Button>
			</SheetFooter>
		</div>
	);
}

'use client';

// One field of the record panel. It uses the grid's own pieces: the cell type and
// read-only reason from the model routing, the cell factories for the shown value,
// the edit intent and the editor components (built-in or a host override), and
// `parseColumnInput` for every value. Simple values edit in place (text, numbers,
// booleans); every other kind opens the same editor the grid opens, inline below the
// field. A field that cannot be changed shows why.

import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { Lock } from 'lucide-react';

import type { ColumnModel, TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import { TABULAR_TEXT_TYPES } from '../cell-types/cell-type-groups';
import { GeometryCellView } from '../cell-model/views/geometry-view';
import { ImageCellView } from '../cell-model/views/image-view';
import type { CellProps } from '../cell-model/cell-props';
import type { SheetsCell } from '../cell-model/sheets-cell';
import { uriCellHref } from '../cell-model/uri-link';
import type { CellType } from '../cell-types/types';
import { EditorFocusTrap } from '../grid/editors/editor-focus-trap';
import { OverlayMeasureContext } from '../grid/editors/overlay-viewport-guard';
import { resolveEditIntent } from '../grid-dom/editors/edit-intent';
import type { SheetsRowIdentifier } from '../row-identity';
import { cn } from '../utils/cn';

/** Editors render inline in the panel; this bounds their own scroll areas. */
const EDITOR_MAX_HEIGHT = 420;
const EDITOR_MEASURE = { maxHeight: EDITOR_MAX_HEIGHT, shouldFlip: false };
const noop = () => {};

export interface RecordFieldProps {
	/** Field name. */
	name: string;
	/** Readable label. */
	label: string;
	/** Column comment, or null. */
	description: string | null;
	column: ColumnModel;
	/** The routed cell type key (built-in or host override). */
	cellType: string;
	/** Why the field cannot be changed here, or null. */
	readOnlyReason: string | null;
	/** A value must be given (shown with a marker). */
	required: boolean;
	/** What an empty value reads as, when not "Empty" (a field a new record gets filled in). */
	emptyText?: string | null;
	/** The stored (or entered) value. */
	value: unknown;
	/** The neutral cell for the value (from the grid's cell factories). */
	cell: SheetsCell;
	/** A save of this field is in flight. */
	saving: boolean;
	/** The last problem with this field, or null. */
	error: string | null;
	registry: CellTypeRegistry;
	table: TableModel;
	/** The record (saved values, or the values of a new record). */
	row: Readonly<Record<string, unknown>> | null;
	/** The saved record's identifier, or null for a new record. */
	rowIdentifier: SheetsRowIdentifier | null;
	/** A stable id of the record entry (an editor's `rowId`). */
	recordId: string;
	/** Save a value. `fromText` is true for typed text. Resolves true when it was kept. */
	onSave: (value: unknown, fromText: boolean) => Promise<boolean> | boolean;
	/** A self-committing editor (files) changed several fields. */
	onCommitPatch: (patch: Record<string, unknown>) => void;
	/** A self-committing editor wrote to the server. */
	onInvalidate: () => void;
}

function seedText(value: unknown): string {
	if (value === null || value === undefined) return '';
	return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

/** The shown value, laid out for a panel (no grid roles). */
function FieldValue({
	cell,
	value,
	name,
	recordId,
	readOnlyReason,
	emptyText,
}: {
	cell: SheetsCell;
	value: unknown;
	name: string;
	recordId: string;
	readOnlyReason: string | null;
	/** What an empty value reads as. */
	emptyText: string;
}) {
	const props: CellProps = {
		cell,
		value,
		colKey: name,
		rowId: recordId,
		rowIndex: -1,
		column: { key: name, name, cellType: (cell.meta?.cellType ?? 'unknown') as CellType },
		isEditing: false,
		onStartEdit: noop,
		disabled: true,
		readOnlyReason: readOnlyReason ?? undefined,
	};
	if (cell.styleHint?.unreadable) return <p className='text-muted-foreground text-sm italic'>{cell.displayData}</p>;
	switch (cell.kind) {
		case 'image':
			return <div className='h-9'><ImageCellView {...props} /></div>;
		case 'geometry':
			return <div className='h-9'><GeometryCellView {...props} /></div>;
		case 'badges': {
			const items = Array.isArray(cell.data) ? (cell.data as string[]) : [];
			if (items.length === 0) return <p className='text-muted-foreground text-sm'>{emptyText}</p>;
			return (
				<ul className='flex flex-wrap gap-1'>
					{items.map((item, index) => (
						<li key={`${index}-${item}`} className='bg-muted text-muted-foreground rounded-md px-2 py-0.5 text-xs font-medium tabular-nums'>
							{item}
						</li>
					))}
				</ul>
			);
		}
		case 'uri': {
			if (!cell.displayData) return <p className='text-muted-foreground text-sm'>{emptyText}</p>;
			// Only an address that may open is a link (the grid's rule); other text stays text.
			const href = uriCellHref(cell);
			return href ? (
				<a
					href={href}
					target={href.startsWith('mailto:') ? undefined : '_blank'}
					rel='noreferrer'
					className='text-link text-sm break-all underline-offset-2 hover:underline'
				>
					{cell.displayData}
				</a>
			) : (
				<p className='text-sm break-all'>{cell.displayData}</p>
			);
		}
		default:
			return cell.displayData ? (
				<p
					className={cn(
						'text-sm break-words whitespace-pre-wrap',
						(cell.kind === 'number' || TABULAR_TEXT_TYPES.has(cell.meta?.cellType ?? '')) && 'tabular-nums',
					)}
					// A date, time or range shown differently from its stored text carries the exact text (and zone) here, as in the grid.
					title={typeof cell.meta?.title === 'string' && cell.meta.title !== cell.displayData ? cell.meta.title : undefined}
				>
					{cell.displayData}
				</p>
			) : (
				<p className='text-muted-foreground text-sm'>{emptyText}</p>
			);
	}
}

/** Text and numbers edit in place: saved on blur or Enter (Ctrl/Cmd+Enter in multi-line text), Escape restores. */
function TextValue({ id, column, value, numeric, describedBy, placeholder, onSave }: {
	id: string;
	column: ColumnModel;
	value: unknown;
	numeric: boolean;
	describedBy: string | undefined;
	placeholder: string | undefined;
	onSave: (value: unknown, fromText: boolean) => Promise<boolean> | boolean;
}) {
	const seed = seedText(value);
	const [text, setText] = useState(seed);
	const [dirty, setDirty] = useState(false);
	// A saved or refetched value replaces the text unless the user is still typing.
	useEffect(() => {
		if (!dirty) setText(seed);
	}, [seed, dirty]);

	const multiline = column.value.kind === 'text' && !column.value.options;
	const savingRef = useRef(false);

	async function save() {
		if (!dirty || savingRef.current) return;
		savingRef.current = true;
		const kept = await onSave(text, true);
		savingRef.current = false;
		if (kept) setDirty(false);
	}

	function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) {
		if (e.key === 'Escape') {
			if (!dirty) return;
			// Restore the stored value; the panel stays open.
			e.preventDefault();
			e.stopPropagation();
			setText(seed);
			setDirty(false);
			return;
		}
		if (e.key === 'Enter' && (!multiline || e.metaKey || e.ctrlKey)) {
			e.preventDefault();
			void save();
		}
	}

	const shared = {
		id,
		value: text,
		'aria-describedby': describedBy,
		placeholder,
		onBlur: (): void => void save(),
		onKeyDown: handleKeyDown,
		spellCheck: false,
		className: cn(
			'placeholder:text-muted-foreground bg-muted/40 border-border/60 focus-visible:border-ring/60 focus-visible:ring-ring/35 w-full rounded-md border px-2.5 py-1.5 text-sm outline-none focus-visible:ring-[3px]',
			numeric && 'tabular-nums',
		),
	};
	return multiline ? (
		<textarea
			{...shared}
			rows={Math.min(8, Math.max(1, text.split('\n').length))}
			onChange={(e) => {
				setDirty(true);
				setText(e.target.value);
			}}
		/>
	) : (
		<input
			{...shared}
			inputMode={numeric ? 'decimal' : undefined}
			onChange={(e) => {
				setDirty(true);
				setText(e.target.value);
			}}
		/>
	);
}

/** A boolean is a choice of Yes, No and (when the field accepts no value) Empty, so no value never reads as No. */
function BooleanValue({ name, column, value, describedBy, onSave }: {
	name: string;
	column: ColumnModel;
	value: unknown;
	describedBy: string | undefined;
	onSave: (value: unknown, fromText: boolean) => Promise<boolean> | boolean;
}) {
	const groupName = useId();
	const choices: { label: string; value: boolean | null }[] = [
		{ label: 'Yes', value: true },
		{ label: 'No', value: false },
		...(column.nullable ? [{ label: 'Empty', value: null }] : []),
	];
	const current = value === true || value === false ? value : null;
	return (
		<div role='radiogroup' aria-label={name} aria-describedby={describedBy} className='flex flex-wrap gap-3'>
			{choices.map((choice) => (
				<label key={choice.label} className='flex items-center gap-1.5 text-sm'>
					<input
						type='radio'
						name={groupName}
						checked={current === choice.value}
						onChange={() => void onSave(choice.value, false)}
					/>
					{choice.label}
				</label>
			))}
		</div>
	);
}

export function RecordField(props: RecordFieldProps) {
	const { name, label, description, column, cellType, readOnlyReason, required, value, cell, saving, error, registry } = props;
	const emptyText = props.emptyText ?? 'Empty';
	const inputId = useId();
	const noteId = useId();
	const [editing, setEditing] = useState(false);
	const editButtonRef = useRef<HTMLButtonElement>(null);
	// When the editor closes, the Edit button that replaces it takes focus back, so the keyboard
	// stays on this field. The editor and the button that opened it are gone by then: focus is
	// either lost (on the page) or back where it was when Edit was pressed (the focus trap
	// restores that element; a click does not focus a button in every browser).
	const focusBeforeEdit = useRef<Element | null>(null);
	const refocusEditButton = useRef(false);
	const openEditor = () => {
		focusBeforeEdit.current = document.activeElement;
		setEditing(true);
	};
	const closeEditor = () => {
		refocusEditButton.current = true;
		setEditing(false);
	};
	useEffect(() => {
		if (editing || !refocusEditButton.current) return;
		refocusEditButton.current = false;
		const active = document.activeElement;
		if (active === null || active === document.body || active === focusBeforeEdit.current) editButtonRef.current?.focus();
	}, [editing]);

	const intent = useMemo(
		() => resolveEditIntent(cellType, { readonly: Boolean(readOnlyReason) }, registry.getEditorComponent),
		[cellType, readOnlyReason, registry],
	);
	const notes = readOnlyReason || error || description ? noteId : undefined;

	let control: React.ReactNode;
	if (intent.mode === 'inline-edit') {
		control = (
			<TextValue
				id={inputId}
				column={column}
				value={value}
				numeric={cell.kind === 'number'}
				describedBy={notes}
				placeholder={props.emptyText ?? undefined}
				onSave={props.onSave}
			/>
		);
	} else if (intent.mode === 'inline-toggle') {
		control = <BooleanValue name={label} column={column} value={value} describedBy={notes} onSave={props.onSave} />;
	} else if (intent.mode === 'overlay') {
		const Editor = intent.editor;
		const viewing = Boolean(readOnlyReason);
		control = editing ? (
			<EditorFocusTrap onEscape={closeEditor} className='relative'>
				<OverlayMeasureContext.Provider value={EDITOR_MEASURE}>
					<Editor
						value={value}
						cell={cell}
						colKey={name}
						rowId={props.recordId}
						rowIdentifier={props.rowIdentifier}
						row={props.row}
						rowIndex={-1}
						tableName={props.table.name}
						column={column}
						relation={null}
						table={props.table}
						readOnlyReason={readOnlyReason}
						onCommit={(next) => {
							closeEditor();
							void props.onSave(next, false);
						}}
						onCommitPatch={(patch) => {
							closeEditor();
							props.onCommitPatch(patch);
						}}
						onInvalidateData={props.onInvalidate}
						onCancel={closeEditor}
						overlay={{ maxHeight: EDITOR_MAX_HEIGHT, flipped: false }}
					/>
				</OverlayMeasureContext.Provider>
			</EditorFocusTrap>
		) : (
			<div className='flex items-start justify-between gap-2'>
				{/* A one-line value shares the Edit button's center line; a taller value keeps the button at its top. */}
				<div className='flex min-h-7 min-w-0 flex-1 flex-col justify-center'>
					<FieldValue cell={cell} value={value} name={name} recordId={props.recordId} readOnlyReason={readOnlyReason} emptyText={emptyText} />
				</div>
				<Button
					ref={editButtonRef}
					size='xs'
					variant='outline'
					aria-label={`${viewing ? 'View' : 'Edit'} ${label}`}
					aria-describedby={notes}
					onClick={openEditor}
				>
					{viewing ? 'View' : 'Edit'}
				</Button>
			</div>
		);
	} else {
		control = <FieldValue cell={cell} value={value} name={name} recordId={props.recordId} readOnlyReason={readOnlyReason} emptyText={emptyText} />;
	}

	return (
		<div data-slot='record-field' data-field={name} className='flex flex-col gap-1.5'>
			<label htmlFor={intent.mode === 'inline-edit' ? inputId : undefined} className='text-muted-foreground flex items-center gap-1 text-xs font-medium'>
				{label}
				{required ? <span aria-hidden>*</span> : null}
				{saving ? <span className='text-muted-foreground ms-auto font-normal'>Saving…</span> : null}
			</label>
			{control}
			<div id={noteId} className='flex flex-col gap-0.5'>
				{description ? <p className='text-muted-foreground text-xs'>{description}</p> : null}
				{readOnlyReason ? (
					<p data-slot='record-field-reason' className='text-muted-foreground flex items-start gap-1 text-xs'>
						<Lock aria-hidden className='mt-0.5 size-3 shrink-0' />
						{readOnlyReason}
					</p>
				) : null}
				{error ? (
					<p role='alert' className='text-destructive text-xs whitespace-pre-wrap'>
						{error}
					</p>
				) : null}
			</div>
		</div>
	);
}

// What the record panel lists, in order: the grid's column order (primary key
// first, a shown belongsTo in place of its key columns, then the list relations),
// so the panel and the grid show a record the same way.

import { readCellError, type RelationModel, type TableModel } from '@constructive-io/data';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import type { CellType } from '../cell-types/types';
import type { SheetsCell } from '../cell-model/sheets-cell';
import { MEDIA_TYPES } from '../cell-types/cell-type-groups';
import { buildModelFormSpec, type ModelFormField, type ModelFormMode } from '../forms/model-form';
import { CELL_READ_ERROR_TEXT, relationCellReadOnlyReason, resolveModelCellRoute } from '../grid/cell-routing';
import { gridColumnKeys } from '../relations/relation-columns';

/** Why a file cannot be added to a record that does not exist yet. */
const SAVE_BEFORE_FILES = 'Save the record first, then add files.';

/** What an empty field of a new record gets when the table fills it in itself. */
export const AUTOMATIC_VALUE_TEXT = 'Set automatically when created';

export type RecordLayoutItem =
	| {
			kind: 'field';
			field: ModelFormField;
			cellType: string;
			readOnlyReason: string | null;
			/** What an empty value reads as, when not "Empty" (a new record's field the table fills in). */
			emptyText: string | null;
	  }
	| {
			kind: 'relation';
			relation: RelationModel;
			readOnlyReason: string | null;
			/** A new record cannot be created without this link (a required key field behind it). */
			required: boolean;
	  };

/** A link a new record needs: a belongsTo whose key fields a create must fill. */
function linkRequiredOnCreate(model: TableModel, relation: RelationModel): boolean {
	if (relation.kind !== 'belongsTo') return false;
	return relation.keys.some((pair) => model.columns.find((column) => column.name === pair.local)?.write.requiredOnCreate);
}

export interface RecordLayoutOptions {
	mode: ModelFormMode;
	/** The record's values (for per-cell read errors), or null. */
	row: Readonly<Record<string, unknown>> | null;
	/** True when relations are shown as sections; otherwise their key columns are listed as fields. */
	withRelations: boolean;
	/** Host cell-type overrides (`SheetsConfig.fieldTypeOverrides`). */
	typeOverrides?: Readonly<Record<string, string>>;
	/** Why files cannot be changed here (for example no storage endpoint), as in the grid; null when they can. */
	mediaReason?: string | null;
}

/** The fields and relation sections of one record, each routed exactly like its grid cell. */
export function recordLayout(model: TableModel, options: RecordLayoutOptions): RecordLayoutItem[] {
	const spec = buildModelFormSpec(model, options.mode, { typeOverrides: options.typeOverrides });
	const fields = new Map(spec.fields.map((field) => [field.name, field] as const));
	const relations = new Map(model.relations.map((relation) => [relation.fieldName, relation] as const));
	const lockedFields = new Set(model.primaryKey);
	const order = options.withRelations ? gridColumnKeys(model) : spec.fields.map((field) => field.name);

	const items: RecordLayoutItem[] = [];
	for (const name of order) {
		const field = fields.get(name);
		if (field) {
			// The saved record is routed per row (a value the server could not send is read-only).
			const route = resolveModelCellRoute({
				column: field.column,
				table: model,
				isDraftRow: options.mode === 'create',
				cellError: options.mode === 'update' ? readCellError(options.row, name) : null,
				typeOverride: options.typeOverrides?.[`${model.name}.${name}`] ?? null,
				lockedFields,
			});
			const isMedia = MEDIA_TYPES.has(route.cellType);
			const mediaReason = isMedia ? (options.mode === 'create' ? SAVE_BEFORE_FILES : options.mediaReason ?? null) : null;
			const readOnlyReason = route.readOnlyReason ?? mediaReason;
			items.push({
				kind: 'field',
				field,
				cellType: route.cellType,
				readOnlyReason,
				// A read-only field already says why it is empty (its reason); an editable one says it may stay so.
				emptyText: options.mode === 'create' && field.column.hasDefault && !readOnlyReason ? AUTOMATIC_VALUE_TEXT : null,
			});
			continue;
		}
		const relation = relations.get(name);
		if (relation && options.withRelations) {
			const creating = options.mode === 'create';
			items.push({
				kind: 'relation',
				relation,
				readOnlyReason: relationCellReadOnlyReason(relation, model, creating),
				required: creating && linkRequiredOnCreate(model, relation),
			});
		}
	}
	return items;
}

/** The neutral cell for one field value, from the grid's cell factories (or the unreadable notice). */
export function recordFieldCell(
	registry: CellTypeRegistry,
	model: TableModel,
	item: Extract<RecordLayoutItem, { kind: 'field' }>,
	value: unknown,
	unreadable: boolean,
): SheetsCell {
	if (unreadable) {
		return {
			kind: 'text',
			data: '',
			displayData: CELL_READ_ERROR_TEXT,
			readonly: true,
			styleHint: { unreadable: true },
			meta: { cellType: item.cellType as CellType },
		};
	}
	return registry.toSheetsCell(item.cellType, value, {
		metadata: {
			cellType: item.cellType,
			fieldName: item.field.name,
			column: item.field.column,
			relation: null,
			table: model,
			canEdit: item.readOnlyReason === null,
			isReadonly: item.readOnlyReason !== null,
			activationBehavior: 'double-click',
		},
	});
}

'use client';

// The record detail panel: a side sheet beside the grid (not modal, so the grid stays
// usable and a click on another row's expand control switches the record). It shows
// one record, a linked record stacked above it (Back returns), or a new-record form.
// Escape or the close button closes it, and focus returns to the grid.
//
// The panel opens and closes at once, with no slide: people open it from the keyboard
// and move through records many times in a row, so it must not lag behind them
// (Craft: Hover Restraint). Surfaces inside it (menus, dialogs) keep their own motion.

import { useCallback } from 'react';
import { MotionConfig } from 'motion/react';

import { Sheet, SheetContent } from '@/components/ui/sheet';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import {
	SheetsOpenRecordContext,
	SheetsOpenTableContext,
	type SheetsOpenRecordRequest,
	type SheetsOpenTableHandler,
} from '../relations/relation-navigation';
import { RecordCreateView } from './record-create-view';
import type { RecordRelationSectionComponent } from './record-relation-section';
import type { RecordPanelRecordEntry } from './record-target';
import { RecordView, type RecordNavigation } from './record-view';
import type { RecordPanelController } from './use-record-panel-state';

export interface RecordPanelProps {
	controller: RecordPanelController;
	registry: CellTypeRegistry;
	/** Host cell-type overrides (`SheetsConfig.fieldTypeOverrides`). */
	typeOverrides?: Readonly<Record<string, string>>;
	/** Why files cannot be changed here (no storage endpoint), as in the grid; null when they can. */
	mediaReason?: string | null;
	/** Previous/next for a record of the grid's table, from the grid's rows. */
	navigationFor: (entry: RecordPanelRecordEntry) => RecordNavigation;
	/** A write changed rows the grid may show. */
	onGridInvalidate: () => void;
	/** The host's handler for "Open {table}" (impure links), passed to the linked-record sections. */
	onOpenTable?: SheetsOpenTableHandler | null;
	/** The element that takes focus when the panel closes (the grid). */
	returnFocus: () => HTMLElement | null;
	/** Linked-record sections, or null to list a relation's key fields as plain fields. */
	RelationSection?: RecordRelationSectionComponent | null;
}

function entryKey(entry: RecordPanelRecordEntry): string {
	return `${entry.tableKey}:${JSON.stringify(Object.entries(entry.key).sort(([a], [b]) => a.localeCompare(b)))}`;
}

export function RecordPanel({
	controller,
	registry,
	typeOverrides,
	mediaReason = null,
	navigationFor,
	onGridInvalidate,
	onOpenTable,
	returnFocus,
	RelationSection = null,
}: RecordPanelProps) {
	const entry = controller.current;
	const { pushRecord, back, close, replaceCurrent } = controller;

	const openLinked = useCallback(
		(request: SheetsOpenRecordRequest) =>
			pushRecord({ kind: 'record', tableKey: request.tableKey, tableName: request.tableName, key: request.key, label: request.label }),
		[pushRecord],
	);
	const isRoot = entry !== null && entry === controller.root;

	return (
		<MotionConfig skipAnimations>
			<Sheet
				open={entry !== null}
				onOpenChange={(open) => {
					if (!open) close();
				}}
				modal={false}
				disablePointerDismissal
			>
				<SheetContent
					side='right'
					overlay={false}
					data-slot='record-panel'
					className='w-full gap-0 sm:max-w-xl'
					finalFocus={() => returnFocus() ?? true}
				>
					<MotionConfig skipAnimations={false}>
						<SheetsOpenTableContext.Provider value={onOpenTable ?? null}>
							<SheetsOpenRecordContext.Provider value={openLinked}>
								{/* Escape closes the panel when it is not taken by an editor or a field inside it. */}
								<div
									className='contents'
									onKeyDown={(event) => {
										if (event.key === 'Escape' && !event.defaultPrevented) {
											event.preventDefault();
											close();
										}
									}}
								>
									{entry?.kind === 'record' ? (
										<RecordView
											key={entryKey(entry)}
											entry={entry}
											registry={registry}
											typeOverrides={typeOverrides}
											mediaReason={mediaReason}
											navigation={isRoot ? navigationFor(entry) : undefined}
											onBack={controller.canGoBack ? back : undefined}
											onOpenRecord={openLinked}
											onDeleted={() => {
												onGridInvalidate();
												const next = isRoot ? navigationFor(entry).next : null;
												if (next) next();
												else replaceCurrent(null);
											}}
											onInvalidate={onGridInvalidate}
											RelationSection={RelationSection}
										/>
									) : entry?.kind === 'new' ? (
										<RecordCreateView
											key={`${entry.tableKey}:new`}
											entry={entry}
											registry={registry}
											typeOverrides={typeOverrides}
											mediaReason={mediaReason}
											onCreated={(created) => replaceCurrent(created)}
											onCancel={close}
											onInvalidate={onGridInvalidate}
											onOpenRecord={openLinked}
											RelationSection={RelationSection}
										/>
									) : null}
								</div>
							</SheetsOpenRecordContext.Provider>
						</SheetsOpenTableContext.Provider>
					</MotionConfig>
				</SheetContent>
			</Sheet>
		</MotionConfig>
	);
}

// The contract between the record panel and the relations lane's embeddable
// linked-records section: one section per relation of the open record.

import type { ComponentType } from 'react';

import type { RelationModel, TableModel } from '@constructive-io/data';

import type { SheetsOpenRecordRequest } from '../relations/relation-navigation';
import type { SheetsRowIdentifier } from '../row-identity';

export interface RecordRelationSectionProps {
	/** The record's table model. */
	table: TableModel;
	/** One relation of `table`. */
	relation: RelationModel;
	/** The saved record, or the values of a new record; null while loading. */
	row: Readonly<Record<string, unknown>> | null;
	/** The saved record's identifier, or null for a new record. */
	rowIdentifier: SheetsRowIdentifier | null;
	/** True for a new record that is not created yet. */
	isDraft: boolean;
	/** A new record cannot be created without this link; the heading is marked required. */
	required?: boolean;
	/** The relation-level reason the links cannot change here, or null. */
	readOnlyReason: string | null;
	/** belongsTo: the local key fields (and the chosen record under the relation field) to keep or that were written. */
	onCommitPatch: (patch: Record<string, unknown>) => void;
	/** After a write: the panel refetches the record and the grid. */
	onInvalidateData: () => void;
	/** Open a linked record (the panel stacks it; Back returns). */
	onOpenRecord: (request: SheetsOpenRecordRequest) => void;
}

export type RecordRelationSectionComponent = ComponentType<RecordRelationSectionProps>;

// Which record the record panel shows, and how it is named.
//
// A record is addressed by its table (`TableModel.key` plus the GraphQL type name)
// and the values of its primary key, by field name. Nothing assumes a key called
// `id` or a one-field key; the public identifier a host sees keeps the grid's
// existing contract (a scalar for a key named `id`, else the key object).

import type { RowKey, TableModel } from '@constructive-io/data';

import { targetRecordLabel } from '../relations/relation-label';
import type { SheetsRowIdentifier } from '../row-identity';

/** One saved record in the panel. */
export interface RecordPanelRecordEntry {
	kind: 'record';
	/** `TableModel.key` of the record's table. */
	tableKey: string;
	/** GraphQL type name of that table. */
	tableName: string;
	/** Primary-key values, by field name. */
	key: RowKey;
	/** A label to show while the record loads ('' when unknown). */
	label: string;
	/** The grid row the record was opened from, a hint for previous/next (checked against the key). */
	rowIndex?: number;
}

/** A new record being filled in the panel, not created yet. */
export interface RecordPanelNewEntry {
	kind: 'new';
	tableKey: string;
	tableName: string;
}

export type RecordPanelEntry = RecordPanelRecordEntry | RecordPanelNewEntry;

/** The primary-key values of a row, or null when the table has no key or the row lacks a key value. */
export function recordKeyOf(model: TableModel, row: Readonly<Record<string, unknown>> | null | undefined): RowKey | null {
	if (!row || model.primaryKey.length === 0) return null;
	const key: Record<string, unknown> = {};
	for (const field of model.primaryKey) {
		const value = row[field];
		if (value === null || value === undefined || value === '') return null;
		key[field] = value;
	}
	return key;
}

/** True when two entries show the same saved record. */
export function sameRecord(a: RecordPanelEntry | null, b: RecordPanelEntry | null): boolean {
	if (!a || !b || a.kind !== 'record' || b.kind !== 'record' || a.tableKey !== b.tableKey) return false;
	const fields = Object.keys(a.key);
	return fields.length === Object.keys(b.key).length && fields.every((field) => String(a.key[field]) === String(b.key[field]));
}

/** The grid's public row identifier for a key: a scalar for a key named `id`, else the key object. */
export function identifierOfKey(key: RowKey): SheetsRowIdentifier {
	const fields = Object.keys(key);
	const only = fields.length === 1 ? key[fields[0]!] : undefined;
	if (fields[0] === 'id' && (typeof only === 'string' || typeof only === 'number')) return only;
	return Object.fromEntries(
		Object.entries(key).map(([field, value]) => [field, typeof value === 'number' ? value : String(value)]),
	);
}

/** The key of a public row identifier (the inverse of `identifierOfKey`). */
export function keyOfIdentifier(model: TableModel, identifier: SheetsRowIdentifier): RowKey | null {
	if (typeof identifier === 'object' && identifier !== null) return identifier;
	return model.primaryKey.length === 1 ? { [model.primaryKey[0]!]: identifier } : null;
}

/** The record's title: its table's display fields, else its key values. */
export function recordTitle(model: TableModel, row: Readonly<Record<string, unknown>> | null | undefined): string {
	return targetRecordLabel(row ?? null, { primaryKey: model.primaryKey, labelFields: model.display.fields }) || 'Untitled record';
}

'use client';

// One saved record in the panel: its title, every field (edited like its grid cell),
// its linked records, previous/next through the grid's rows, and delete.

import { useMemo, useRef, useState } from 'react';
import { ChevronDown, ChevronLeft, ChevronUp, Trash2 } from 'lucide-react';

import { readCellError, type TableModel } from '@constructive-io/data';
import { Button } from '@/components/ui/button';
import { SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet';

import type { CellTypeRegistry } from '../cell-types/cell-type-registry';
import { writeErrorMessages } from '../grid/feedback/write-errors';
import type { SheetsOpenRecordRequest } from '../relations/relation-navigation';
import { RecordField } from './record-field';
import { recordFieldCell, recordLayout } from './record-layout';
import type { RecordRelationSectionComponent } from './record-relation-section';
import { identifierOfKey, recordTitle, type RecordPanelRecordEntry } from './record-target';
import { useRecord } from './use-record';

export interface RecordNavigation {
	/** Show the previous row's record, or null at the first row. */
	previous: (() => void) | null;
	/** Show the next row's record, or null at the last row. */
	next: (() => void) | null;
}

export interface RecordViewProps {
	entry: RecordPanelRecordEntry;
	registry: CellTypeRegistry;
	typeOverrides?: Readonly<Record<string, string>>;
	/** Why files cannot be changed here (no storage endpoint), or null. */
	mediaReason?: string | null;
	/** Previous/next through the grid's rows (root records only). */
	navigation?: RecordNavigation;
	/** Shown when a linked record is open above the grid's record. */
	onBack?: () => void;
	/** Open a linked record above this one. */
	onOpenRecord: (request: SheetsOpenRecordRequest) => void;
	/** The record was deleted. */
	onDeleted: () => void;
	/** Something changed outside the record's own table (a relation write); refresh the grid. */
	onInvalidate: () => void;
	/** Linked-record sections from the relations lane, or null to list key fields instead. */
	RelationSection: RecordRelationSectionComponent | null;
}

function operationIssue(model: TableModel, operation: 'delete'): string | null {
	return model.issues.find((issue) => issue.scope === 'operation' && issue.target === operation)?.message ?? null;
}

export function RecordView({ entry, registry, typeOverrides, mediaReason, navigation, onBack, onOpenRecord, onDeleted, onInvalidate, RelationSection }: RecordViewProps) {
	const data = useRecord(entry.tableName, entry.key);
	const { model, record } = data;
	const [confirmDelete, setConfirmDelete] = useState(false);
	const deleteButtonRef = useRef<HTMLButtonElement>(null);
	// Cancelling the confirmation removes the focused Cancel button: focus goes back to the
	// delete button, so the keyboard stays in the panel (and Escape still closes it).
	const cancelDelete = () => {
		deleteButtonRef.current?.focus();
		setConfirmDelete(false);
	};
	const [deleteError, setDeleteError] = useState<string | null>(null);
	const [deleting, setDeleting] = useState(false);
	const recordId = useMemo(() => `${entry.tableKey}:${JSON.stringify(entry.key)}`, [entry]);
	const identifier = useMemo(() => identifierOfKey(entry.key), [entry.key]);

	const layout = useMemo(
		() => (model ? recordLayout(model, { mode: 'update', row: record, withRelations: RelationSection !== null, typeOverrides, mediaReason }) : []),
		[model, record, RelationSection, typeOverrides, mediaReason],
	);

	const title = model && record ? recordTitle(model, record) : entry.label || 'Loading record…';
	const deleteReason = model && !model.operations.delete
		? operationIssue(model, 'delete') ?? 'Records in this table cannot be deleted.'
		: null;

	async function remove() {
		setDeleting(true);
		setDeleteError(null);
		try {
			await data.table.delete(identifier);
			onDeleted();
		} catch (error) {
			setDeleteError(writeErrorMessages(error, 'delete').join('\n'));
		} finally {
			setDeleting(false);
		}
	}

	return (
		<div data-slot='record-view' className='flex min-h-0 flex-1 flex-col gap-4'>
			<SheetHeader className='gap-2'>
				{/* Pulled up so its icons share a center line with the panel's close button. */}
				<div className='-mt-1.5 flex items-center gap-1'>
					{onBack ? (
						// Less padding on the chevron side: the icon's own empty space already pads it.
						<Button size='xs' variant='ghost' className='ps-1' onClick={onBack} aria-label='Back to the previous record'>
							<ChevronLeft aria-hidden className='size-4' />
							Back
						</Button>
					) : null}
					<span className='text-muted-foreground truncate text-xs font-medium'>{entry.tableName}</span>
					<div className='ms-auto flex items-center gap-1'>
						{navigation ? (
							<>
								<Button
									size='icon-xs'
									variant='ghost'
									aria-label='Previous record'
									title={navigation.previous ? 'Previous record' : 'This is the first row'}
									disabled={!navigation.previous}
									onClick={() => navigation.previous?.()}
								>
									<ChevronUp aria-hidden className='size-4' />
								</Button>
								<Button
									size='icon-xs'
									variant='ghost'
									aria-label='Next record'
									title={navigation.next ? 'Next record' : 'This is the last row'}
									disabled={!navigation.next}
									onClick={() => navigation.next?.()}
								>
									<ChevronDown aria-hidden className='size-4' />
								</Button>
							</>
						) : null}
						<Button
							ref={deleteButtonRef}
							size='icon-xs'
							variant='ghost'
							aria-label='Delete record'
							title={deleteReason ?? 'Delete record'}
							disabled={Boolean(deleteReason) || !record || deleting}
							onClick={() => setConfirmDelete(true)}
						>
							<Trash2 aria-hidden className='size-4' />
						</Button>
					</div>
				</div>
				<SheetTitle className='break-words'>{title}</SheetTitle>
				<SheetDescription className='sr-only'>The fields and linked records of this {entry.tableName} record.</SheetDescription>
				{deleteReason ? <p className='text-muted-foreground text-xs'>{deleteReason}</p> : null}
				{confirmDelete ? (
					// Confirmed inline: a second modal on top of the side panel would take the grid's focus.
					<div
						role='group'
						aria-label='Confirm delete'
						data-slot='record-delete-confirm'
						// Outer radius = the buttons' radius + the 1px border + the 4px padding, so the corners stay parallel.
						className='border-destructive/40 bg-destructive/5 flex flex-wrap items-center gap-2 rounded-[calc(var(--radius-md)+5px)] border p-1 ps-3'
						onKeyDown={(e) => {
							if (e.key === 'Escape') {
								e.preventDefault();
								e.stopPropagation();
								cancelDelete();
							}
						}}
					>
						<p className='me-auto py-1 text-xs'>Delete “{title}” permanently? This cannot be undone.</p>
						<Button size='xs' variant='outline' autoFocus onClick={cancelDelete}>
							Cancel
						</Button>
						<Button
							size='xs'
							className='bg-destructive text-white hover:bg-destructive/90'
							onClick={() => {
								setConfirmDelete(false);
								void remove();
							}}
						>
							Delete
						</Button>
					</div>
				) : null}
				{deleting ? <p className='text-muted-foreground text-xs'>Deleting…</p> : null}
				{deleteError ? (
					<p role='alert' className='text-destructive text-xs whitespace-pre-wrap'>
						The record was not deleted: {deleteError}
					</p>
				) : null}
			</SheetHeader>

			{data.error ? (
				<div role='alert' className='flex flex-col items-start gap-2 text-sm'>
					<p className='text-destructive'>This record could not be loaded: {data.error.message}</p>
					<Button size='xs' variant='outline' onClick={data.refetch}>
						Try again
					</Button>
				</div>
			) : data.isLoading ? (
				<div aria-busy='true' className='flex flex-col gap-3'>
					{[0, 1, 2, 3].map((index) => (
						<div key={index} className='bg-muted h-10 animate-pulse rounded-md' />
					))}
				</div>
			) : data.isMissing || !record || !model ? (
				<p className='text-muted-foreground text-sm'>This record no longer exists. It may have been deleted.</p>
			) : (
				<div className='flex flex-col gap-4'>
					{layout.map((item) =>
						item.kind === 'field' ? (
							<RecordField
								key={item.field.name}
								name={item.field.name}
								label={item.field.label}
								description={item.field.description}
								column={item.field.column}
								cellType={item.cellType}
								readOnlyReason={item.readOnlyReason}
								required={item.field.required}
								value={record[item.field.name]}
								cell={recordFieldCell(registry, model, item, record[item.field.name], readCellError(record, item.field.name) !== null)}
								saving={item.field.name in data.pending}
								error={data.errors[item.field.name] ?? null}
								registry={registry}
								table={model}
								row={record}
								rowIdentifier={identifier}
								recordId={recordId}
								onSave={(value, fromText) => data.saveField(item.field.column, value, { fromText })}
								onCommitPatch={() => data.refetch()}
								onInvalidate={() => {
									data.refetch();
									onInvalidate();
								}}
							/>
						) : RelationSection ? (
							<RelationSection
								key={item.relation.fieldName}
								table={model}
								relation={item.relation}
								row={record}
								rowIdentifier={identifier}
								isDraft={false}
								readOnlyReason={item.readOnlyReason}
								onCommitPatch={() => data.refetch()}
								onInvalidateData={() => {
									data.refetch();
									onInvalidate();
								}}
								onOpenRecord={onOpenRecord}
							/>
						) : null,
					)}
				</div>
			)}

		</div>
	);
}

// The record panel's link to the grid: which row's record to open, previous/next
// through the grid's rows (saved rows only; drafts and unloaded rows are skipped),
// and the open/new entry points the commands and the host handle call.

import { useCallback, useMemo } from 'react';

import type { TableModel } from '@constructive-io/data';

import { getDraftMeta, type SheetsRow } from '../grid/row-model';
import type { SheetsOpenRecordRequest } from '../relations/relation-navigation';
import type { SheetsRowIdentifier } from '../row-identity';
import { keyOfIdentifier, recordKeyOf, recordTitle, sameRecord, type RecordPanelRecordEntry } from './record-target';
import type { RecordNavigation } from './record-view';
import { useRecordPanelState, type RecordPanelController } from './use-record-panel-state';

export interface UseGridRecordPanelArgs {
	tableModel: TableModel | null;
	/** The grid's rows (server rows, then drafts); an unloaded row reads as null. */
	rows: readonly (SheetsRow | null | undefined)[];
	/** Number of server rows at the start of `rows`. */
	serverRowCount: number;
	recordId?: SheetsRowIdentifier | null;
	onRecordOpenChange?: (recordId: SheetsRowIdentifier | null) => void;
}

export interface GridRecordPanel {
	controller: RecordPanelController;
	/** Open the record of a grid row. False for a draft, an unloaded row or a row without a key. */
	openRecordAt: (rowIndex: number) => boolean;
	/** Why a row's record cannot be opened, or null when it can. */
	openRecordReason: (rowIndex: number) => string | null;
	/** Open a record of the grid's table by its identifier. False when the identifier does not name a record. */
	openRecordById: (recordId: SheetsRowIdentifier) => boolean;
	/** Open the new-record form. False when the table does not allow new records. */
	openNewRecord: () => boolean;
	/** Open a linked record (from a relation chip or editor in the grid) above the current one. */
	openLinkedRecord: (request: SheetsOpenRecordRequest) => void;
	/** Previous/next for a record of the grid's table. */
	navigationFor: (entry: RecordPanelRecordEntry) => RecordNavigation;
}

export function useGridRecordPanel({ tableModel, rows, serverRowCount, recordId, onRecordOpenChange }: UseGridRecordPanelArgs): GridRecordPanel {
	const controller = useRecordPanelState({ table: tableModel, recordId, onRecordOpenChange });
	const { openRecord, openNew, pushRecord } = controller;

	const entryAt = useCallback(
		(rowIndex: number): RecordPanelRecordEntry | null => {
			if (!tableModel || rowIndex < 0 || rowIndex >= serverRowCount) return null;
			const row = rows[rowIndex];
			if (!row || getDraftMeta(row)) return null;
			const key = recordKeyOf(tableModel, row);
			if (!key) return null;
			return { kind: 'record', tableKey: tableModel.key, tableName: tableModel.name, key, label: recordTitle(tableModel, row), rowIndex };
		},
		[tableModel, rows, serverRowCount],
	);

	const openRecordReason = useCallback(
		(rowIndex: number): string | null => {
			if (!tableModel) return 'The table is still loading.';
			if (tableModel.primaryKey.length === 0) return 'This table has no primary key, so its records cannot be opened one by one.';
			const row = rows[rowIndex];
			if (row && getDraftMeta(row)) return 'Save this row first, then open it as a record.';
			if (!row) return 'This row is still loading.';
			return entryAt(rowIndex) ? null : 'This row has no key value, so it cannot be opened as a record.';
		},
		[tableModel, rows, entryAt],
	);

	const openRecordAt = useCallback(
		(rowIndex: number) => {
			const entry = entryAt(rowIndex);
			if (!entry) return false;
			openRecord(entry);
			return true;
		},
		[entryAt, openRecord],
	);

	const openRecordById = useCallback(
		(id: SheetsRowIdentifier) => {
			const key = tableModel ? keyOfIdentifier(tableModel, id) : null;
			if (!tableModel || !key) return false;
			openRecord({ kind: 'record', tableKey: tableModel.key, tableName: tableModel.name, key, label: '' });
			return true;
		},
		[tableModel, openRecord],
	);

	const openNewRecord = useCallback(() => {
		if (!tableModel?.operations.create) return false;
		openNew();
		return true;
	}, [tableModel, openNew]);

	const openLinkedRecord = useCallback(
		(request: SheetsOpenRecordRequest) =>
			pushRecord({ kind: 'record', tableKey: request.tableKey, tableName: request.tableName, key: request.key, label: request.label }),
		[pushRecord],
	);

	const navigationFor = useCallback(
		(entry: RecordPanelRecordEntry): RecordNavigation => {
			let index = -1;
			if (entry.rowIndex !== undefined && sameRecord(entryAt(entry.rowIndex), entry)) index = entry.rowIndex;
			else for (let i = 0; i < serverRowCount && index < 0; i++) if (sameRecord(entryAt(i), entry)) index = i;
			if (index < 0) return { previous: null, next: null };
			const neighbour = (step: -1 | 1): RecordPanelRecordEntry | null => {
				for (let i = index + step; i >= 0 && i < serverRowCount; i += step) {
					const candidate = entryAt(i);
					if (candidate) return candidate;
				}
				return null;
			};
			const previous = neighbour(-1);
			const next = neighbour(1);
			return {
				previous: previous ? () => openRecord(previous) : null,
				next: next ? () => openRecord(next) : null,
			};
		},
		[entryAt, serverRowCount, openRecord],
	);

	return useMemo(
		() => ({ controller, openRecordAt, openRecordReason, openRecordById, openNewRecord, openLinkedRecord, navigationFor }),
		[controller, openRecordAt, openRecordReason, openRecordById, openNewRecord, openLinkedRecord, navigationFor],
	);
}

// State of the record panel: which record of the grid's table is open (the root),
// and the linked records opened from it (a navigation stack; Back returns).
//
// A host can control the root for deep links: pass `recordId` (null for closed)
// and `onRecordOpenChange`. Without `recordId` the panel keeps its own state and
// still reports every change. Linked records and a new-record form stay inside
// the panel either way.

import { useCallback, useEffect, useMemo, useState } from 'react';

import type { TableModel } from '@constructive-io/data';

import type { SheetsRowIdentifier } from '../row-identity';
import {
	identifierOfKey,
	keyOfIdentifier,
	type RecordPanelEntry,
	type RecordPanelRecordEntry,
} from './record-target';

export interface UseRecordPanelStateArgs {
	/** The grid's table model, or null while it loads. */
	table: TableModel | null;
	/** Controlled root record of the grid's table: an identifier, or null for closed. Omit to let the panel own it. */
	recordId?: SheetsRowIdentifier | null;
	/** Called with the root record whenever the user opens, moves or closes the panel (null when closed). */
	onRecordOpenChange?: (recordId: SheetsRowIdentifier | null) => void;
}

export interface RecordPanelController {
	/** The entry the panel shows, or null when it is closed. */
	current: RecordPanelEntry | null;
	/** True when a linked record is shown above the root. */
	canGoBack: boolean;
	/** The root entry (a record of the grid's table, or the new-record form). */
	root: RecordPanelEntry | null;
	/** Open a record of the grid's table as the root (clears linked records). */
	openRecord: (entry: RecordPanelRecordEntry) => void;
	/** Open a linked record above the current one. */
	pushRecord: (entry: RecordPanelRecordEntry) => void;
	/** Show the record below the current one. */
	back: () => void;
	/** Open the form for a new record of the grid's table. */
	openNew: () => void;
	/** Replace the current entry (a created record replaces its form; a deleted linked record leaves). */
	replaceCurrent: (entry: RecordPanelRecordEntry | null) => void;
	/** Close the panel. */
	close: () => void;
}

export function useRecordPanelState({ table, recordId, onRecordOpenChange }: UseRecordPanelStateArgs): RecordPanelController {
	const controlled = recordId !== undefined;
	const [ownRoot, setOwnRoot] = useState<RecordPanelEntry | null>(null);
	const [creating, setCreating] = useState(false);
	const [linked, setLinked] = useState<RecordPanelRecordEntry[]>([]);

	const controlledRoot = useMemo<RecordPanelEntry | null>(() => {
		if (!controlled || !table) return null;
		if (recordId === null || recordId === undefined) {
			return creating ? { kind: 'new', tableKey: table.key, tableName: table.name } : null;
		}
		const key = keyOfIdentifier(table, recordId);
		return key ? { kind: 'record', tableKey: table.key, tableName: table.name, key, label: '' } : null;
	}, [controlled, table, recordId, creating]);

	const root = controlled ? controlledRoot : ownRoot;

	// A host that opens another record (or closes) leaves the linked records behind.
	useEffect(() => {
		if (controlled) setLinked([]);
	}, [controlled, recordId]);

	const setRoot = useCallback(
		(next: RecordPanelEntry | null) => {
			setLinked([]);
			if (next?.kind === 'new') {
				setCreating(true);
				if (!controlled) setOwnRoot(next);
				else if (recordId !== null) onRecordOpenChange?.(null);
				return;
			}
			setCreating(false);
			if (!controlled) setOwnRoot(next);
			onRecordOpenChange?.(next ? identifierOfKey(next.key) : null);
		},
		[controlled, recordId, onRecordOpenChange],
	);

	const openRecord = useCallback((entry: RecordPanelRecordEntry) => setRoot(entry), [setRoot]);
	const openNew = useCallback(() => {
		if (table) setRoot({ kind: 'new', tableKey: table.key, tableName: table.name });
	}, [table, setRoot]);
	const close = useCallback(() => {
		setLinked([]);
		setRoot(null);
	}, [setRoot]);
	const pushRecord = useCallback((entry: RecordPanelRecordEntry) => setLinked((stack) => [...stack, entry]), []);
	const back = useCallback(() => setLinked((stack) => stack.slice(0, -1)), []);
	const replaceCurrent = useCallback(
		(entry: RecordPanelRecordEntry | null) => {
			if (linked.length > 0) {
				setLinked((stack) => (entry ? [...stack.slice(0, -1), entry] : stack.slice(0, -1)));
				return;
			}
			setRoot(entry);
		},
		[linked.length, setRoot],
	);

	const current = linked.length > 0 ? linked[linked.length - 1]! : root;

	// Back leaves a linked record: to the one below it, or to the grid's record (closing when there is none).
	const canGoBack = linked.length > 1 || (linked.length === 1 && root !== null);
	return useMemo(
		() => ({ current, canGoBack, root, openRecord, pushRecord, back, openNew, replaceCurrent, close }),
		[current, canGoBack, root, openRecord, pushRecord, back, openNew, replaceCurrent, close],
	);
}

// Load one record for the panel and write its fields.
//
// The record is read through the adapter's list read filtered by its primary key
// (with every readable relation), so a cell the API could not serve still loads and
// carries its error, as in the grid. It is cached under the table's query key, so
// every create, update or delete of that table (from the grid, the panel or a
// relation editor) refetches it.
//
// A field write follows the grid's write path: the value is parsed by the column's
// rules first (a value that does not fit is refused with its reason and nothing is
// sent), shown at once (optimistic), sent through the table's update mutation (the
// write codec encodes it), and on failure put back, with the server's message kept
// on that field until the next edit. Nothing is dropped without a message.

import { useCallback, useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';

import { TableModelError, type ColumnModel, type RowKey, type TableModel } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';

import { parseColumnInput } from '../cell-types/column-value';
import { useSheetsContext } from '../context/sheets-context';
import { useOptionalFeedback } from '../grid/feedback/feedback-context';
import { writeErrorMessages } from '../grid/feedback/write-errors';
import { sheetsTableQueryKeys, useSheetsTable, type UseTableResult } from '../hooks/use-sheets-table';
import { useTableModel } from '../hooks/use-table-model';
import { equalityFilter } from '../relations/relation-keys';
import { identifierOfKey } from './record-target';

type RowRecord = Record<string, unknown>;

export interface RecordFieldWriteState {
	/** Values sent and not answered yet, by field. */
	pending: Readonly<Record<string, unknown>>;
	/** The last problem per field: a value that did not fit, or what the server said. */
	errors: Readonly<Record<string, string>>;
}

export interface UseRecordResult extends RecordFieldWriteState {
	model: TableModel | null;
	/** The record with pending values applied, or null while it loads or when it does not exist. */
	record: RowRecord | null;
	isLoading: boolean;
	/** Why the record could not be loaded, or null. */
	error: Error | null;
	/** True when the read succeeded but no record has this key (deleted elsewhere). */
	isMissing: boolean;
	/** The table's operations (create, update, delete) for this record's table. */
	table: UseTableResult<RowRecord>;
	/**
	 * Parse and save one field. `fromText` is true for typed text (JSON and lists are read
	 * from it). Resolves true when the value was saved.
	 */
	saveField: (column: ColumnModel, value: unknown, options?: { fromText?: boolean }) => Promise<boolean>;
	/** Note a problem on a field without writing (for example an editor that refused the value). */
	setFieldError: (field: string, message: string | null) => void;
	/** Refetch the record. */
	refetch: () => void;
}

function serializeKey(key: RowKey | null): string {
	if (!key) return '';
	return JSON.stringify(Object.keys(key).sort().map((field) => [field, key[field]]));
}

export function useRecord(tableName: string, key: RowKey | null, options: { enabled?: boolean } = {}): UseRecordResult {
	const enabled = options.enabled !== false && key !== null;
	const { scopeKey, execute } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const { model, tableKey, isLoading: isModelLoading, error: modelError } = useTableModel(tableName);
	const table = useSheetsTable<RowRecord>(tableName, { enabled: false, select: 'full' });
	const cacheRef = tableKey ?? tableName;
	const keyText = serializeKey(key);

	const query = useQuery<RowRecord | null>({
		queryKey: [...sheetsTableQueryKeys.table(scopeKey, cacheRef), 'record', keyText],
		queryFn: async ({ signal }) => {
			const where = model && key ? equalityFilter(model, key) : null;
			if (!model || !where) {
				throw new TableModelError('FILTER_UNAVAILABLE', 'This record cannot be looked up on its own.', { tableKey: model?.key });
			}
			const result = await adapter.listRows<RowRecord>(
				{ model, tableName },
				{ where, limit: model.operations.list?.first ? 1 : undefined, relations: 'all', includeTotalCount: false, signal },
				execute,
			);
			return result.rows[0] ?? null;
		},
		enabled: enabled && model !== null,
	});

	const [pending, setPending] = useState<Record<string, unknown>>({});
	const [errors, setErrors] = useState<Record<string, string>>({});

	const setFieldError = useCallback((field: string, message: string | null) => {
		setErrors((current) => {
			if (message === null) {
				if (!(field in current)) return current;
				const { [field]: _removed, ...rest } = current;
				return rest;
			}
			return { ...current, [field]: message };
		});
	}, []);

	const update = table.update;
	const refetchQuery = query.refetch;
	// Inside a grid, a field save reports to the grid's save status with every other write.
	const feedback = useOptionalFeedback();
	const trackWrite = feedback?.trackWrite;
	const saveField = useCallback(
		async (column: ColumnModel, value: unknown, saveOptions: { fromText?: boolean } = {}): Promise<boolean> => {
			if (!key) return false;
			const parsed = parseColumnInput(column, value, { fromText: saveOptions.fromText ?? false });
			if (parsed.ok === false) {
				setFieldError(column.name, parsed.reason);
				return false;
			}
			setFieldError(column.name, null);
			setPending((current) => ({ ...current, [column.name]: parsed.value }));
			try {
				const write = () => update(identifierOfKey(key), { [column.name]: parsed.value });
				await (trackWrite ? trackWrite('update', 1, write, { saved: 'Saved', failed: 'Not saved' }) : write());
				await refetchQuery();
				return true;
			} catch (error) {
				setFieldError(column.name, writeErrorMessages(error, 'update').join('\n'));
				return false;
			} finally {
				setPending((current) => {
					const { [column.name]: _sent, ...rest } = current;
					return rest;
				});
			}
		},
		[key, update, refetchQuery, setFieldError, trackWrite],
	);

	const record = useMemo<RowRecord | null>(() => {
		const base = query.data ?? null;
		if (!base) return null;
		return Object.keys(pending).length > 0 ? { ...base, ...pending } : base;
	}, [query.data, pending]);

	const refetch = useCallback(() => {
		void refetchQuery();
	}, [refetchQuery]);

	return {
		model,
		record,
		isLoading: enabled && (isModelLoading || query.isLoading),
		error: (modelError as Error | null) ?? (query.error as Error | null) ?? null,
		isMissing: enabled && query.isSuccess && query.data === null,
		table,
		pending,
		errors,
		saveField,
		setFieldError,
		refetch,
	};
}

/**
 * What the relation editor may do for one relation of one row, with a
 * human-readable reason for everything it may not do. Decided only from the
 * table models: a write the models cannot prove is not offered.
 */
import type { RelationModel, TableModel } from '@constructive-io/data';

import { hasLinkPatch, junctionLeftValues, linkFields, type RecordValues } from './relation-keys';

export interface RelationEditContext {
	relation: RelationModel;
	/** The grid table. */
	table: TableModel;
	/** The related table, or null while it loads or when it failed. */
	target: TableModel | null;
	/** The junction table of a manyToMany relation, or null. */
	junction: TableModel | null;
	/** The row being edited (server or draft). */
	row: RecordValues | null;
	/** True for a draft row that does not exist on the server yet. */
	isDraft: boolean;
	/** True when the server row can be addressed by its primary key. */
	rowIdentified: boolean;
}

export interface RelationEditCapability {
	/** Links can be added (or, for a single link, chosen). */
	canLink: boolean;
	/** Why links cannot be added, or null. */
	linkReason: string | null;
	/** Links can be removed (or, for a single link, cleared). */
	canUnlink: boolean;
	/** Why links cannot be removed, or null. */
	unlinkReason: string | null;
}

const SAVE_FIRST = 'Save this record first, then link records to it.';
const TARGET_UNAVAILABLE = 'The linked table could not be loaded, so these links cannot be changed.';
const JUNCTION_UNAVAILABLE = 'The table that stores these links could not be loaded, so they cannot be changed.';
const ROW_UNIDENTIFIED = 'This record cannot be identified, so its links cannot be changed.';

function blocked(reason: string): RelationEditCapability {
	return { canLink: false, linkReason: reason, canUnlink: false, unlinkReason: reason };
}

function operationIssue(model: TableModel, operation: 'create' | 'update' | 'delete'): string | null {
	return model.issues.find((issue) => issue.scope === 'operation' && issue.target === operation)?.message ?? null;
}

/** The first column of `fields` that `operation` cannot write, with its reason. */
function unwritable(model: TableModel, fields: readonly string[], operation: 'create' | 'update'): string | null {
	for (const field of fields) {
		const column = model.columns.find((candidate) => candidate.name === field);
		if (!column) return 'A field this link needs is not available.';
		if (!column.write[operation]) {
			return (operation === 'create' ? column.write.createReason : column.write.updateReason) ?? 'A field this link needs cannot be changed.';
		}
	}
	return null;
}

function unlinkState(relation: RelationModel, link: RelationEditCapability): RelationEditCapability {
	if (!link.canLink && link.linkReason) return { ...link, canUnlink: false, unlinkReason: link.linkReason };
	if (!relation.unlinkable) {
		return { ...link, canUnlink: false, unlinkReason: relation.reason ?? 'These links cannot be removed.' };
	}
	return { ...link, canUnlink: true, unlinkReason: null };
}

function belongsTo(ctx: RelationEditContext): RelationEditCapability {
	const { relation, table, isDraft } = ctx;
	const fields = relation.keys.map((pair) => pair.local);
	if (isDraft) {
		if (!table.operations.create) return blocked(operationIssue(table, 'create') ?? 'New records cannot be added to this table.');
		const reason = unwritable(table, fields, 'create');
		return reason ? blocked(reason) : unlinkState(relation, { canLink: true, linkReason: null, canUnlink: true, unlinkReason: null });
	}
	if (!table.operations.update) return blocked(operationIssue(table, 'update') ?? 'Records in this table cannot be changed.');
	if (!ctx.rowIdentified) return blocked(ROW_UNIDENTIFIED);
	const reason = unwritable(table, fields, 'update');
	if (reason) return blocked(reason);
	return unlinkState(relation, { canLink: true, linkReason: null, canUnlink: true, unlinkReason: null });
}

function hasRelated(ctx: RelationEditContext, target: TableModel): RelationEditCapability {
	const { relation, row } = ctx;
	if (!target.operations.update) return blocked('The linked table does not allow changes, so these links cannot be changed.');
	if (target.primaryKey.length === 0) return blocked('The linked records cannot be identified, so these links cannot be changed.');
	const reason = unwritable(target, relation.keys.map((pair) => pair.remote), 'update');
	if (reason) return blocked(reason);
	if (!row || !hasLinkPatch(relation, row)) return blocked('This record has no value to link by yet.');
	return unlinkState(relation, { canLink: true, linkReason: null, canUnlink: true, unlinkReason: null });
}

function manyToMany(ctx: RelationEditContext, junctionModel: TableModel): RelationEditCapability {
	const { relation, row } = ctx;
	const junction = relation.junction;
	if (!junction) return blocked(relation.reason ?? 'These links cannot be changed here.');
	if (!row || !junctionLeftValues(relation, row)) return blocked('This record has no value to link by yet.');

	const fields = [...junction.left.map((pair) => pair.junction), ...junction.right.map((pair) => pair.junction)];
	const createReason = !junctionModel.operations.create
		? 'The table that stores these links does not allow new links.'
		: unwritable(junctionModel, fields, 'create');
	const deleteReason = !junctionModel.operations.delete || junctionModel.primaryKey.length === 0
		? 'The table that stores these links does not allow removing links.'
		: null;
	const link: RelationEditCapability = {
		canLink: createReason === null,
		linkReason: createReason,
		canUnlink: true,
		unlinkReason: null,
	};
	if (!relation.unlinkable) return { ...link, canUnlink: false, unlinkReason: relation.reason ?? 'These links cannot be removed.' };
	if (deleteReason) return { ...link, canUnlink: false, unlinkReason: deleteReason };
	return link;
}

/** True when every field is a column the related table's list can return. */
function readable(model: TableModel, fields: readonly string[]): boolean {
	return fields.length > 0 && fields.every((field) => model.columns.some((column) => column.name === field && column.readable));
}

/** Decide what the editor may do for this relation and row. */
export function relationEditCapability(ctx: RelationEditContext): RelationEditCapability {
	const { relation, target } = ctx;
	if (!relation.editable) return blocked(relation.reason ?? 'These links cannot be changed here.');
	if (ctx.isDraft && relation.kind !== 'belongsTo') return blocked(SAVE_FIRST);
	if (!target) return blocked(TARGET_UNAVAILABLE);
	if (!readable(target, linkFields(relation))) {
		return blocked('The linked records do not show the fields this link needs, so these links cannot be changed.');
	}
	if (relation.kind === 'belongsTo') return belongsTo(ctx);
	if (relation.kind === 'manyToMany') return ctx.junction ? manyToMany(ctx, ctx.junction) : blocked(JUNCTION_UNAVAILABLE);
	return hasRelated(ctx, target);
}

/**
 * The writes that turn an edited link set into server state, and running
 * them one by one so a partial failure can be reported per change. Every
 * write names its table model and the exact key and values; the adapter
 * builds the documents from the model.
 */
import { getHumanReadableError, type RelationModel, type TableModel } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import type { SheetsRowIdentifier } from '../row-identity';
import {
	belongsToClearPatch,
	belongsToLinkPatch,
	hasLinkPatch,
	hasUnlinkPatch,
	junctionLinkValues,
	linkKey,
	primaryKeyValues,
	type FieldValues,
	type RecordValues,
} from './relation-keys';
import { relationRecordLabel } from './relation-label';

interface ChangeBase {
	/** The table the write goes to. */
	model: TableModel;
	/** Whether the write adds or removes a link. */
	action: 'link' | 'unlink';
	/** Label of the related record, for messages. */
	label: string;
	/** Identity of the related record (see `linkKey`), or '' when a link is cleared. */
	linkKey: string;
}

/**
 * `prior` is what the write replaces (the patched fields' values before an update, the whole
 * row before a delete), so the change can be undone; null or absent when it was not known.
 */
export type RelationChange =
	| (ChangeBase & { op: 'update'; key: SheetsRowIdentifier; patch: FieldValues; prior?: FieldValues | null })
	| (ChangeBase & { op: 'create'; values: FieldValues })
	| (ChangeBase & { op: 'delete'; key: SheetsRowIdentifier; prior?: RecordValues | null });

/** A planned set of writes, or why the edit cannot be written. */
export type RelationPlan = { ok: true; changes: RelationChange[] } | { ok: false; reason: string };

export interface RelationChangeFailure {
	change: RelationChange;
	message: string;
}

export interface RelationChangeOutcome {
	applied: RelationChange[];
	failed: RelationChangeFailure[];
	/** Changes not attempted because an earlier one they depend on failed. */
	skipped: RelationChange[];
	/** The row each applied create made, when the server returned it. */
	created: Map<RelationChange, RecordValues>;
}

/** The values of `fields` on `record`, or null when one of them was not read. */
function priorValues(record: RecordValues | null | undefined, fields: readonly string[]): FieldValues | null {
	if (!record) return null;
	const prior: FieldValues = {};
	for (const field of fields) {
		if (!(field in record)) return null;
		prior[field] = record[field];
	}
	return prior;
}

/** A record removed from or added to a list relation. */
export interface LinkedRecord {
	/** Comparable identity (see `linkKey`). */
	key: string;
	/** The related record. */
	record: RecordValues;
	/** For manyToMany: the junction row that holds the link. */
	junctionRow?: RecordValues | null;
}

/** belongsTo on a server row: one update of this row's local key fields. `row` holds their values now. */
export function planBelongsTo(
	relation: RelationModel,
	table: TableModel,
	rowKey: SheetsRowIdentifier,
	record: RecordValues | null,
	row: RecordValues | null = null,
): RelationPlan {
	if (!record) {
		const patch = belongsToClearPatch(relation);
		return {
			ok: true,
			changes: [
				{ op: 'update', model: table, key: rowKey, patch, prior: priorValues(row, Object.keys(patch)), action: 'unlink', label: '', linkKey: '' },
			],
		};
	}
	const patch = belongsToLinkPatch(relation, record);
	if (!patch) return { ok: false, reason: 'The chosen record has no value to link by.' };
	return {
		ok: true,
		changes: [
			{
				op: 'update',
				model: table,
				key: rowKey,
				patch,
				prior: priorValues(row, Object.keys(patch)),
				action: 'link',
				label: relationRecordLabel(relation, record),
				linkKey: linkKey(relation, record) ?? '',
			},
		],
	};
}

/**
 * hasOne/hasMany: detach the removed records, then point the added records
 * at this row. Each write updates one related record by its primary key.
 */
export function planHasLinks(
	relation: RelationModel,
	target: TableModel,
	row: RecordValues,
	change: { added: readonly LinkedRecord[]; removed: readonly LinkedRecord[] },
): RelationPlan {
	const linkPatch = hasLinkPatch(relation, row);
	if (!linkPatch) return { ok: false, reason: 'This record has no value to link by yet.' };
	const changes: RelationChange[] = [];
	for (const entry of [...change.removed, ...change.added]) {
		const key = primaryKeyValues(target, entry.record);
		const label = relationRecordLabel(relation, entry.record);
		if (!key) return { ok: false, reason: `"${label || 'A record'}" cannot be identified, so its link cannot be changed.` };
		const removing = change.removed.includes(entry);
		const patch = removing ? hasUnlinkPatch(relation) : linkPatch;
		changes.push({
			op: 'update',
			model: target,
			key: key as SheetsRowIdentifier,
			patch,
			// A record linked elsewhere goes back to its old owner on undo.
			prior: priorValues(entry.record, Object.keys(patch)),
			action: removing ? 'unlink' : 'link',
			label,
			linkKey: entry.key,
		});
	}
	return { ok: true, changes };
}

/**
 * manyToMany: delete the junction rows of removed links (by the junction's
 * primary key), then create one junction row per added link.
 */
export function planJunctionLinks(
	relation: RelationModel,
	junction: TableModel,
	row: RecordValues,
	change: { added: readonly LinkedRecord[]; removed: readonly LinkedRecord[] },
): RelationPlan {
	const changes: RelationChange[] = [];
	for (const entry of change.removed) {
		const label = relationRecordLabel(relation, entry.record);
		const key = entry.junctionRow ? primaryKeyValues(junction, entry.junctionRow) : null;
		if (!key) return { ok: false, reason: `The link to "${label || 'a record'}" cannot be identified, so it cannot be removed.` };
		changes.push({ op: 'delete', model: junction, key: key as SheetsRowIdentifier, prior: entry.junctionRow, action: 'unlink', label, linkKey: entry.key });
	}
	for (const entry of change.added) {
		const label = relationRecordLabel(relation, entry.record);
		const values = junctionLinkValues(relation, row, entry.record);
		if (!values) return { ok: false, reason: `"${label || 'A record'}" has no value to link by.` };
		changes.push({ op: 'create', model: junction, values, action: 'link', label, linkKey: entry.key });
	}
	return { ok: true, changes };
}

/** Runs one change; a create resolves to the row it made, when the server returns it. */
export type RelationChangeRunner = (change: RelationChange) => Promise<RecordValues | null | void>;

/** Run one change through the host's adapter. */
export function adapterChangeRunner(adapter: SheetsBackendAdapter, execute: SheetsExecuteFn): RelationChangeRunner {
	return async (change) => {
		const ctx = { model: change.model, tableName: change.model.key };
		if (change.op === 'update') await adapter.updateRow(ctx, change.key, change.patch, execute);
		else if (change.op === 'create') return adapter.createRow<RecordValues>(ctx, change.values, execute);
		else await adapter.deleteRow(ctx, change.key, execute);
	};
}

/**
 * Run changes in order. With `dependent`, the first failure stops the rest
 * (a single link is replaced by removing the old one first); otherwise every
 * change is tried and each failure is reported.
 */
export async function applyRelationChanges(
	changes: readonly RelationChange[],
	run: RelationChangeRunner,
	options: { dependent?: boolean } = {},
): Promise<RelationChangeOutcome> {
	const outcome: RelationChangeOutcome = { applied: [], failed: [], skipped: [], created: new Map() };
	for (const change of changes) {
		if (options.dependent && outcome.failed.length > 0) {
			outcome.skipped.push(change);
			continue;
		}
		try {
			const row = await run(change);
			outcome.applied.push(change);
			if (change.op === 'create' && row) outcome.created.set(change, row);
		} catch (error) {
			outcome.failed.push({ change, message: getHumanReadableError(error) });
		}
	}
	return outcome;
}

/** One sentence per failure, naming the record and the server's message. */
export function describeFailures(outcome: RelationChangeOutcome): string[] {
	const lines = outcome.failed.map(({ change, message }) => {
		const verb = change.action === 'link' ? 'link' : 'unlink';
		return change.label ? `Could not ${verb} "${change.label}": ${message}` : `Could not ${verb}: ${message}`;
	});
	if (outcome.skipped.length > 0) lines.push(`${outcome.skipped.length} more change${outcome.skipped.length === 1 ? ' was' : 's were'} not tried.`);
	return lines;
}

const flip = (action: RelationChange['action']): RelationChange['action'] => (action === 'link' ? 'unlink' : 'link');

/**
 * The writes that undo applied changes, last first: an update writes back what it replaced, a
 * removed link row is created again from its old values, and a created one is deleted. Not
 * possible (with the reason) when a change did not keep what it replaced.
 */
export function invertRelationChanges(outcome: Pick<RelationChangeOutcome, 'applied' | 'created'>): RelationPlan {
	const changes: RelationChange[] = [];
	for (const change of [...outcome.applied].reverse()) {
		const base = { model: change.model, action: flip(change.action), label: change.label, linkKey: change.linkKey };
		if (change.op === 'update') {
			if (!change.prior) return { ok: false, reason: 'The values this link change replaced are not known.' };
			changes.push({ ...base, op: 'update', key: change.key, patch: change.prior, prior: change.patch });
		} else if (change.op === 'delete') {
			if (!change.prior) return { ok: false, reason: 'The removed link is not known, so it cannot be added again.' };
			const values: FieldValues = {};
			for (const column of change.model.columns) {
				if (column.write.create && change.prior[column.name] !== undefined) values[column.name] = change.prior[column.name];
			}
			changes.push({ ...base, op: 'create', values });
		} else {
			const row = outcome.created.get(change) ?? change.values;
			const key = primaryKeyValues(change.model, row);
			if (!key) return { ok: false, reason: 'The added link cannot be identified, so it cannot be removed.' };
			changes.push({ ...base, op: 'delete', key: key as SheetsRowIdentifier, prior: row });
		}
	}
	return { ok: true, changes };
}

/**
 * Which relation and foreign-key columns the grid shows, and in what order,
 * from the table model alone (never from the keys of a loaded row).
 *
 * - Every readable relation is a column, except a hasMany to a junction
 *   table that a pure manyToMany relation already shows.
 * - A foreign-key column is hidden only when its belongsTo relation is shown;
 *   the relation column takes the place of its first key column.
 * - Primary-key columns come first, then the other columns in model order,
 *   then hasOne, hasMany and manyToMany relations in model order.
 */
import type { RelationModel, TableModel } from '@constructive-io/data';

/** The relations the grid shows as columns, in model order. */
export function gridRelations(model: TableModel): RelationModel[] {
	const shownJunctions = new Set(
		model.relations.flatMap((relation) =>
			relation.kind === 'manyToMany' && relation.readable && relation.junction?.pure ? [relation.junction.tableKey] : [],
		),
	);
	return model.relations.filter(
		(relation) =>
			relation.readable &&
			!(relation.kind === 'hasMany' && relation.targetKey !== null && shownJunctions.has(relation.targetKey)),
	);
}

/** Relation fields the grid selects with its rows. */
export function gridRelationFieldNames(model: TableModel | null | undefined): string[] {
	return model ? gridRelations(model).map((relation) => relation.fieldName) : [];
}

/** Column keys in display order: columns and relation fields. */
export function gridColumnKeys(model: TableModel): string[] {
	const relations = gridRelations(model);
	const belongsToByKey = new Map<string, RelationModel>();
	for (const relation of relations) {
		if (relation.kind !== 'belongsTo') continue;
		for (const pair of relation.keys) if (!belongsToByKey.has(pair.local)) belongsToByKey.set(pair.local, relation);
	}

	const readable = model.columns.filter((column) => column.readable).map((column) => column.name);
	const keyFirst = [
		...model.primaryKey.filter((name) => readable.includes(name)),
		...readable.filter((name) => !model.primaryKey.includes(name)),
	];

	const keys: string[] = [];
	const placed = new Set<string>();
	for (const name of keyFirst) {
		const relation = belongsToByKey.get(name);
		if (!relation) {
			keys.push(name);
			continue;
		}
		if (!placed.has(relation.fieldName)) {
			placed.add(relation.fieldName);
			keys.push(relation.fieldName);
		}
	}
	for (const relation of relations) {
		if (!placed.has(relation.fieldName)) {
			placed.add(relation.fieldName);
			keys.push(relation.fieldName);
		}
	}
	return keys;
}

'use client';

/**
 * Create a related record from the relation editor with the record form
 * (`forms/model-form.ts`): the required and label fields first, the rest
 * behind "More fields". Every value is checked and parsed by the column's own
 * rules (`readRelatedCreate`); the parent links the result.
 */
import { useId, useState, type FormEvent } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

import type { ModelFormField } from '../forms/model-form';
import { readRelatedCreate, type RelatedCreatePlan } from './relation-create';
import type { FieldValues } from './relation-keys';

export interface RelationCreateFormProps {
	targetName: string;
	plan: Extract<RelatedCreatePlan, { ok: true }>;
	/** Create the record; resolves to an error message, or null on success. */
	onSubmit: (values: FieldValues) => Promise<string | null>;
	onCancel: () => void;
}

type RawValues = Record<string, unknown>;

function FieldInput({
	field,
	id,
	value,
	error,
	onChange,
}: {
	field: ModelFormField;
	id: string;
	value: unknown;
	error: string | undefined;
	onChange: (value: unknown) => void;
}) {
	if (field.cellType === 'boolean') {
		return (
			<label htmlFor={id} className='flex items-center gap-2 text-sm'>
				<input id={id} type='checkbox' checked={value === true} onChange={(event) => onChange(event.target.checked)} />
				{field.label}
			</label>
		);
	}
	const label = (
		<Label htmlFor={id} className='text-xs' title={field.description ?? undefined}>
			{field.label}
			{field.required ? <span aria-hidden> *</span> : null}
		</Label>
	);
	if (field.options && field.options.length > 0) {
		return (
			<>
				{label}
				<select
					id={id}
					className='border-input bg-background h-8 w-full rounded-md border px-2 text-sm'
					value={typeof value === 'string' ? value : ''}
					aria-invalid={Boolean(error) || undefined}
					onChange={(event) => onChange(event.target.value === '' ? undefined : event.target.value)}
				>
					<option value=''>Choose…</option>
					{field.options.map((option) => (
						<option key={option.value} value={option.value}>
							{option.label}
						</option>
					))}
				</select>
			</>
		);
	}
	return (
		<>
			{label}
			<Input
				id={id}
				size='sm'
				value={typeof value === 'string' ? value : ''}
				maxLength={field.maxLength ?? undefined}
				aria-invalid={Boolean(error) || undefined}
				onChange={(event) => onChange(event.target.value === '' ? undefined : event.target.value)}
			/>
		</>
	);
}

export function RelationCreateForm({ targetName, plan, onSubmit, onCancel }: RelationCreateFormProps) {
	const baseId = useId();
	const [raw, setRaw] = useState<RawValues>({});
	const [errors, setErrors] = useState<Record<string, string>>({});
	const [submitError, setSubmitError] = useState<string | null>(null);
	const [submitting, setSubmitting] = useState(false);
	const [showAll, setShowAll] = useState(false);

	const fields = showAll ? [...plan.primary, ...plan.secondary] : plan.primary;

	const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		event.stopPropagation();
		const read = readRelatedCreate(plan, raw);
		if (read.ok === false) {
			setErrors(read.errors);
			// A message on a hidden field must be visible.
			if (Object.keys(read.errors).some((name) => plan.secondary.some((field) => field.name === name))) setShowAll(true);
			return;
		}
		setErrors({});
		setSubmitError(null);
		setSubmitting(true);
		const message = await onSubmit(read.values);
		setSubmitting(false);
		if (message) setSubmitError(message);
	};

	return (
		<form aria-label={`New ${targetName}`} className='space-y-2 rounded-md border p-2' onSubmit={(event) => void handleSubmit(event)}>
			<div className='text-xs font-medium'>New {targetName}</div>
			{fields.length === 0 ? <p className='text-muted-foreground text-xs'>No fields are needed.</p> : null}
			{fields.map((field) => {
				const id = `${baseId}-${field.name}`;
				const error = errors[field.name];
				return (
					<div key={field.name} className='space-y-1'>
						<FieldInput
							field={field}
							id={id}
							value={raw[field.name]}
							error={error}
							onChange={(next) => setRaw((current) => ({ ...current, [field.name]: next }))}
						/>
						{error ? <p className='text-destructive text-xs'>{error}</p> : null}
					</div>
				);
			})}
			{plan.secondary.length > 0 ? (
				// Ghost: pulled out by its padding so its text lines up with the field labels.
				<Button type='button' variant='ghost' size='sm' className='-ms-2' onClick={() => setShowAll((value) => !value)}>
					{showAll ? 'Fewer fields' : `More fields (${plan.secondary.length})`}
				</Button>
			) : null}
			{submitError ? (
				<p role='alert' className='text-destructive text-xs'>
					{submitError}
				</p>
			) : null}
			<div className='flex justify-end gap-2'>
				<Button type='button' variant='outline' size='sm' onClick={onCancel} disabled={submitting}>
					Back
				</Button>
				<Button type='submit' size='sm' disabled={submitting}>
					{submitting ? 'Creating…' : 'Create'}
				</Button>
			</div>
		</form>
	);
}

/**
 * Creating a related record from the relation editor, with the record form
 * the grid and the record panel use (`forms/model-form.ts`): the same fields,
 * read-only reasons, parsers and required checks. The fields the link itself
 * fills (hasOne/hasMany: the related table's `keys[].remote` = this record's
 * values) are fixed and not shown.
 */
import type { RelationModel, TableModel } from '@constructive-io/data';

import { buildModelFormSchema, buildModelFormSpec, type ModelFormField, type ModelFormSpec } from '../forms/model-form';
import { hasLinkPatch, type FieldValues, type RecordValues } from './relation-keys';

export type RelatedCreatePlan =
	| {
			ok: true;
			spec: ModelFormSpec;
			/** Fields shown first: required ones and the label fields. */
			primary: ModelFormField[];
			/** Other fields the form can set. */
			secondary: ModelFormField[];
			/** Values the link fills, sent with the create. */
			fixed: FieldValues;
	  }
	| { ok: false; reason: string };

/** Plan the create form for a record of `target` linked through `relation` to `row`. */
export function planRelatedCreate(relation: RelationModel, target: TableModel, row: RecordValues | null): RelatedCreatePlan {
	const spec = buildModelFormSpec(target, 'create');
	if (!target.operations.create) {
		return { ok: false, reason: spec.fields.find((field) => field.readOnlyReason)?.readOnlyReason ?? 'New records cannot be added to the linked table.' };
	}

	let fixed: FieldValues = {};
	if (relation.kind === 'hasOne' || relation.kind === 'hasMany') {
		const link = row ? hasLinkPatch(relation, row) : null;
		if (!link) return { ok: false, reason: 'This record has no value to link by yet.' };
		fixed = link;
	}
	for (const name of Object.keys(fixed)) {
		const field = spec.fields.find((candidate) => candidate.name === name);
		if (!field?.writable) return { ok: false, reason: field?.readOnlyReason ?? 'A new linked record cannot be given this link.' };
	}

	const blocking = spec.fields.find((field) => !field.writable && field.column.write.requiredOnCreate && !(field.name in fixed));
	if (blocking) return { ok: false, reason: `A new record needs "${blocking.label}": ${blocking.readOnlyReason ?? 'it cannot be entered here.'}` };

	const open = spec.fields.filter((field) => field.writable && !(field.name in fixed));
	const isPrimary = (field: ModelFormField) => field.required || relation.target.labelFields.includes(field.name);
	return { ok: true, spec, primary: open.filter(isPrimary), secondary: open.filter((field) => !isPrimary(field)), fixed };
}

/**
 * Check and parse the form values (plus the fixed link values) with the record
 * form's schema. Untouched fields are left out, so their defaults apply.
 */
export function readRelatedCreate(
	plan: Extract<RelatedCreatePlan, { ok: true }>,
	raw: Readonly<Record<string, unknown>>,
): { ok: true; values: FieldValues } | { ok: false; errors: Record<string, string> } {
	const result = buildModelFormSchema(plan.spec).safeParse({ ...raw, ...plan.fixed });
	if (!result.success) {
		const errors: Record<string, string> = {};
		for (const issue of result.error.issues) {
			const name = String(issue.path[0] ?? '');
			if (name && !errors[name]) errors[name] = issue.message;
		}
		return { ok: false, errors };
	}
	const values: FieldValues = {};
	for (const [name, value] of Object.entries(result.data)) if (value !== undefined) values[name] = value;
	return { ok: true, values };
}

'use client';

/**
 * The content of a relation editor, shared by the grid's cell editor and the
 * record panel's relation section: the model's reason when nothing can change,
 * the current links, "Open {table}" for links that need more fields, the
 * picker, the create form, messages, and the "Create new" / "Clear link"
 * actions. The host adds its own header and its Save/Cancel footer.
 */
import { useState, type RefObject } from 'react';
import { ExternalLink, Link, Plus } from 'lucide-react';

import { Button } from '@/components/ui/button';

import { RelationCreateForm } from './relation-create-form';
import { RelationLinkList } from './relation-link-list';
import { RelationPicker } from './relation-picker';
import type { RelationEditor } from './use-relation-editor';

export interface RelationEditorBodyProps {
	editor: RelationEditor;
	/**
	 * 'overlay' (the cell editor): the picker shows at once. 'section' (a record panel
	 * listing several relations): the picker appears after "Add link" ("Change link" for a
	 * to-one relation that has one), and the host's heading carries the link count. The
	 * search box takes focus when the picker appears.
	 */
	layout?: 'overlay' | 'section';
	/**
	 * Section layout: the host controls whether the picker is open, so it can close it
	 * after a save and give focus back to the "Add link" / "Change link" button
	 * (`toggleRef`). Escape in the search box closes the picker.
	 */
	picker?: {
		open: boolean;
		setOpen: (open: boolean) => void;
		toggleRef: RefObject<HTMLButtonElement | null>;
	};
}

export function RelationEditorBody({ editor, layout = 'overlay', picker }: RelationEditorBodyProps) {
	const [creating, setCreating] = useState(false);
	const [ownPickerOpen, setOwnPickerOpen] = useState(layout === 'overlay');
	const showPicker = picker ? picker.open : ownPickerOpen;
	const setPickerOpen = picker ? picker.setOpen : setOwnPickerOpen;
	const { relation, capability, editable, selection, saving, create } = editor;
	const isList = relation.kind === 'hasMany' || relation.kind === 'manyToMany';
	const hasLink = selection.pending.some((link) => link.state !== 'removed');
	// A to-one relation with a link replaces it; a hasOne whose link must stay cannot be replaced.
	const replaces = !isList && editor.current.length > 0;
	const replaceReason = replaces && relation.kind === 'hasOne' && !capability.canUnlink ? capability.unlinkReason : null;

	return (
		<>
			{editor.blockedReason ? (
				<p role='note' className='bg-muted text-muted-foreground rounded-md px-3 py-2 text-xs' data-testid='relation-readonly-reason'>
					{editor.blockedReason}
				</p>
			) : null}
			<RelationLinkList
				relation={relation}
				pending={selection.pending}
				total={editor.links.total}
				isLoading={editor.links.isLoading || (editor.modelsLoading && editor.current.length === 0 && relation.kind !== 'belongsTo')}
				error={editor.links.error}
				hasNextPage={editor.links.hasNextPage}
				isFetchingNextPage={editor.links.isFetchingNextPage}
				onLoadMore={editor.links.fetchNextPage}
				onToggle={editor.toggle}
				// While the related table loads, the model already says whether links can be removed:
				// show that now, so the reason line and the remove controls do not appear later.
				removeReason={
					editor.linkPending
						? relation.unlinkable
							? null
							: relation.reason
						: editable
							? capability.canUnlink
								? null
								: capability.unlinkReason
							: null
				}
				readOnly={!editable && !editor.linkPending}
				disabled={saving || editor.linkPending}
				placeholderCount={editor.links.placeholderCount}
				moveHint={editor.moveHint}
				onOpen={editor.openRecord ?? undefined}
				openReason={editor.openRecordReason}
				showSummary={layout === 'overlay'}
			/>

			{!editable && editor.junctionAction ? (
				<Button type='button' variant='outline' size='sm' className='self-start' onClick={editor.junctionAction.open}>
					<ExternalLink className='mr-1 h-3 w-3' aria-hidden />
					Open {editor.junctionAction.tableName}
				</Button>
			) : null}

			{(capability.canLink || editor.linkPending) && !creating && showPicker ? (
				<RelationPicker
					relation={relation}
					targetName={relation.targetName}
					search={editor.search}
					onSearchChange={editor.setSearch}
					searchReason={editor.searchReason}
					candidates={editor.candidates.rows}
					total={editor.candidates.total}
					isLoading={editor.candidates.isLoading || editor.linkPending}
					error={editor.candidates.error ?? editor.targetError}
					hasNextPage={editor.candidates.hasNextPage}
					isFetchingNextPage={editor.candidates.isFetchingNextPage}
					onLoadMore={editor.candidates.fetchNextPage}
					isSelected={selection.isSelected}
					onToggle={editor.toggle}
					disabled={saving || editor.linkPending}
					moveHint={editor.moveHint}
					onEscape={layout === 'section' ? () => setPickerOpen(false) : undefined}
				/>
			) : null}

			{creating && create.plan?.ok ? (
				<RelationCreateForm
					targetName={relation.targetName}
					plan={create.plan}
					onSubmit={async (values) => {
						const message = await create.submit(values);
						if (!message) setCreating(false);
						return message;
					}}
					onCancel={() => setCreating(false)}
				/>
			) : null}

			{editor.notice ? (
				<p role='status' className='text-muted-foreground text-xs'>
					{editor.notice}
				</p>
			) : null}
			{editor.errors.length > 0 ? (
				<div role='alert' className='border-destructive/40 text-destructive space-y-0.5 rounded-md border px-3 py-2 text-xs'>
					{editor.errors.map((line) => (
						<p key={line}>{line}</p>
					))}
				</div>
			) : null}

			{/* One action row, so the link actions line up and share spacing. */}
			{(editable || editor.linkPending) && !creating ? (
				<div className='flex flex-wrap items-center gap-2'>
					{(capability.canLink || editor.linkPending) && !showPicker ? (
						<Button
							ref={picker?.toggleRef}
							type='button'
							variant='outline'
							size='sm'
							disabled={Boolean(replaceReason) || editor.linkPending}
							title={replaceReason ?? undefined}
							onClick={() => setPickerOpen(true)}
						>
							<Link className='mr-1 h-3 w-3' aria-hidden />
							{replaces ? 'Change link' : 'Add link'}
						</Button>
					) : null}
					<Button
						type='button'
						variant='ghost'
						size='sm'
						// A leading ghost button has no visible box: pull it out by its padding so its
						// icon lines up with the content above.
						className={(capability.canLink || editor.linkPending) && !showPicker ? undefined : '-ms-2'}
						disabled={editor.linkPending || Boolean(create.blocked) || saving}
						title={editor.linkPending ? 'Loading the linked table…' : (create.blocked ?? undefined)}
						onClick={() => setCreating(true)}
					>
						<Plus className='mr-1 h-3 w-3' aria-hidden />
						Create new
					</Button>
					{/* In the cell editor, Clear is in the shared footer. */}
					{layout === 'section' && !isList && capability.canUnlink && hasLink ? (
						<Button type='button' variant='ghost' size='sm' disabled={saving} onClick={editor.clear}>
							Clear link
						</Button>
					) : null}
				</div>
			) : null}
		</>
	);
}

/**
 * Identity and write values of related records, read only from the relation
 * model. Nothing here assumes a key named `id`, a one-field key, or a naming
 * convention: every field comes from `RelationModel.keys`, `junction` or
 * `target.primaryKey`, and records are compared by value.
 */
import type { RelationModel, TableModel } from '@constructive-io/data';

/** A record as the API returns it. */
export type RecordValues = Readonly<Record<string, unknown>>;

/** Key values per field, in the shape a document builder takes. */
export type FieldValues = Record<string, unknown>;

function present(value: unknown): boolean {
	return value !== null && value !== undefined;
}

/**
 * A comparable key for the values of `fields`, or null when any of them is
 * missing. Two records with the same values get the same key.
 */
export function valuesKey(values: readonly unknown[]): string | null {
	if (values.length === 0 || !values.every(present)) return null;
	return JSON.stringify(values);
}

/** The comparable key of `record` over `fields`, or null when a field has no value. */
export function recordKey(record: RecordValues | null | undefined, fields: readonly string[]): string | null {
	if (!record) return null;
	return valuesKey(fields.map((field) => record[field]));
}

/** The values of `fields` in `record`, or null when one is missing. */
export function fieldValues(record: RecordValues | null | undefined, fields: readonly string[]): FieldValues | null {
	if (!record || fields.length === 0) return null;
	const values: FieldValues = {};
	for (const field of fields) {
		const value = record[field];
		if (!present(value)) return null;
		values[field] = value;
	}
	return values;
}

/**
 * The fields of a related record that identify it for this relation:
 * the referenced fields for belongsTo, the related table's primary key for
 * hasOne/hasMany (the write targets that row), and the fields the junction
 * references for manyToMany.
 */
export function linkFields(relation: RelationModel): readonly string[] {
	switch (relation.kind) {
		case 'belongsTo':
			return relation.keys.map((pair) => pair.remote);
		case 'hasOne':
		case 'hasMany':
			return relation.target.primaryKey;
		case 'manyToMany':
			return relation.junction?.right.map((pair) => pair.remote) ?? [];
	}
}

/** The comparable identity of a related record for this relation. */
export function linkKey(relation: RelationModel, record: RecordValues | null | undefined): string | null {
	return recordKey(record, linkFields(relation));
}

/** belongsTo: the key of the record this row links to now, read from the row's own fields. */
export function belongsToCurrentKey(relation: RelationModel, row: RecordValues | null | undefined): string | null {
	if (!row) return null;
	return valuesKey(relation.keys.map((pair) => row[pair.local]));
}

/**
 * belongsTo: the values to write on this row to link `record`
 * (`keys[].local` from `keys[].remote`), or null when the record lacks one
 * of the referenced values.
 */
export function belongsToLinkPatch(relation: RelationModel, record: RecordValues): FieldValues | null {
	const patch: FieldValues = {};
	for (const pair of relation.keys) {
		const value = record[pair.remote];
		if (!present(value)) return null;
		patch[pair.local] = value;
	}
	return patch;
}

/** belongsTo: the values that clear the link on this row. */
export function belongsToClearPatch(relation: RelationModel): FieldValues {
	return Object.fromEntries(relation.keys.map((pair): [string, null] => [pair.local, null]));
}

/**
 * hasOne/hasMany: the values to write on a related record so it points at
 * this row (`keys[].remote` from this row's `keys[].local`), or null when this
 * row has no value for one of them.
 */
export function hasLinkPatch(relation: RelationModel, row: RecordValues): FieldValues | null {
	const patch: FieldValues = {};
	for (const pair of relation.keys) {
		const value = row[pair.local];
		if (!present(value)) return null;
		patch[pair.remote] = value;
	}
	return patch;
}

/** hasOne/hasMany: the values that detach a related record from this row. */
export function hasUnlinkPatch(relation: RelationModel): FieldValues {
	return Object.fromEntries(relation.keys.map((pair): [string, null] => [pair.remote, null]));
}

/**
 * hasOne/hasMany: where a related record points now. `here` when it links to
 * this row, `elsewhere` when it links to another record, `none` when it is free.
 */
export function hasLinkOwner(
	relation: RelationModel,
	row: RecordValues,
	record: RecordValues,
): 'here' | 'elsewhere' | 'none' {
	const values = relation.keys.map((pair) => record[pair.remote]);
	if (!values.some(present)) return 'none';
	const here = valuesKey(relation.keys.map((pair) => row[pair.local]));
	return here !== null && valuesKey(values) === here ? 'here' : 'elsewhere';
}

/**
 * manyToMany: the values of a new junction row linking this row and `record`,
 * or null when either side lacks a referenced value.
 */
export function junctionLinkValues(relation: RelationModel, row: RecordValues, record: RecordValues): FieldValues | null {
	const junction = relation.junction;
	if (!junction) return null;
	const values: FieldValues = {};
	for (const pair of junction.left) {
		const value = row[pair.local];
		if (!present(value)) return null;
		values[pair.junction] = value;
	}
	for (const pair of junction.right) {
		const value = record[pair.remote];
		if (!present(value)) return null;
		values[pair.junction] = value;
	}
	return values;
}

/** manyToMany: the filter values that select this row's junction rows (`left[].junction` = this row's values). */
export function junctionLeftValues(relation: RelationModel, row: RecordValues): FieldValues | null {
	const junction = relation.junction;
	if (!junction) return null;
	const values: FieldValues = {};
	for (const pair of junction.left) {
		const value = row[pair.local];
		if (!present(value)) return null;
		values[pair.junction] = value;
	}
	return values;
}

/** manyToMany: the identity of the related record a junction row points at, comparable with {@link linkKey}. */
export function junctionRightKey(relation: RelationModel, junctionRow: RecordValues): string | null {
	const right = relation.junction?.right ?? [];
	return valuesKey(right.map((pair) => junctionRow[pair.junction]));
}

/**
 * manyToMany: a stand-in for the related record a junction row points at,
 * carrying the referenced values under the related table's field names.
 */
export function junctionRightRecord(relation: RelationModel, junctionRow: RecordValues): FieldValues {
	const right = relation.junction?.right ?? [];
	return Object.fromEntries(right.map((pair) => [pair.remote, junctionRow[pair.junction]]));
}

/** The primary-key values of a record of `model`, or null when the table has no key or the record lacks a value. */
export function primaryKeyValues(model: TableModel, record: RecordValues): FieldValues | null {
	return fieldValues(record, model.primaryKey);
}

/**
 * The equality filter that selects records of `model` whose `fields` equal
 * `values`, using the filter input names and operators the model proved.
 * Null when one of the fields cannot be filtered by equality.
 */
export function equalityFilter(model: TableModel, values: FieldValues): Record<string, unknown> | null {
	const filter: Record<string, unknown> = {};
	for (const [field, value] of Object.entries(values)) {
		const column = model.columns.find((candidate) => candidate.name === field);
		const supportsEquality = column?.filter?.operators.some((operator) => operator.name === 'equalTo');
		if (!column?.filter || !supportsEquality) return null;
		filter[column.filter.field] = { equalTo: value };
	}
	return Object.keys(filter).length > 0 ? filter : null;
}

/**
 * Labels of related records, from the related table's display rule
 * (`RelationTargetModel.labelFields`, which already applies the host
 * override). No field-name lists live here.
 */
import type { RelationModel, RelationTargetModel } from '@constructive-io/data';

import { linkFields, type RecordValues } from './relation-keys';

const KEY_SEPARATOR = ' · ';

function text(value: unknown): string {
	if (value === null || value === undefined) return '';
	if (typeof value === 'object') return '';
	return String(value).trim();
}

function sameFields(left: readonly string[], right: readonly string[]): boolean {
	return left.length === right.length && left.every((field, index) => field === right[index]);
}

/** Join the values of `fields` that have text, or '' when none has. */
function joined(record: RecordValues, fields: readonly string[]): string {
	return fields.map((field) => text(record[field])).filter(Boolean).join(KEY_SEPARATOR);
}

/**
 * The label of one related record. The first non-empty label field wins; a
 * label made of the key fields shows every key value, because one part of a
 * composite key does not identify the record. A record whose label fields are
 * empty falls back to its key value.
 */
export function targetRecordLabel(
	record: RecordValues | null | undefined,
	target: RelationTargetModel,
	fallbackFields: readonly string[] = [],
): string {
	if (!record || typeof record !== 'object') return '';
	const { labelFields, primaryKey } = target;
	if (labelFields.length > 0 && sameFields(labelFields, primaryKey)) {
		const key = joined(record, primaryKey);
		if (key) return key;
	} else {
		for (const field of labelFields) {
			const value = text(record[field]);
			if (value) return value;
		}
	}
	return joined(record, primaryKey) || joined(record, fallbackFields);
}

/** The label of a record related through `relation`, falling back to the fields the relation links by. */
export function relationRecordLabel(relation: RelationModel, record: RecordValues | null | undefined): string {
	return targetRecordLabel(record, relation.target, linkFields(relation));
}

/**
 * What tells a related record apart from others with the same label: its other label fields
 * (an email beside a name), else its key. '' when nothing adds to the label.
 */
export function relationRecordDistinction(relation: RelationModel, record: RecordValues | null | undefined): string {
	if (!record || typeof record !== 'object') return '';
	const label = relationRecordLabel(relation, record);
	const others = relation.target.labelFields.map((field) => text(record[field])).filter((value) => value && value !== label);
	const distinction = others.length > 0 ? others.join(KEY_SEPARATOR) : joined(record, relation.target.primaryKey);
	return distinction === label ? '' : distinction;
}

/** The labels more than one record in a list shares. */
export function sharedLabels(labels: readonly string[]): ReadonlySet<string> {
	const seen = new Set<string>();
	const shared = new Set<string>();
	for (const label of labels) {
		if (seen.has(label)) shared.add(label);
		else seen.add(label);
	}
	return shared;
}

/** A link cell as text to read elsewhere: the linked record's label, or a list's labels, comma separated. */
export function relationCopyText(relation: RelationModel, value: unknown): string {
	if (Array.isArray(value)) {
		return value
			.map((record) => relationRecordLabel(relation, record as RecordValues))
			.filter(Boolean)
			.join(', ');
	}
	return value && typeof value === 'object' ? relationRecordLabel(relation, value as RecordValues) : '';
}

'use client';

/**
 * The links a row has, as they will be after Save: current links, links the
 * user removed (struck through, with Undo) and records the user added.
 */
import { useMemo } from 'react';
import { ExternalLink, Loader2, RotateCcw, X } from 'lucide-react';

import type { RelationModel } from '@constructive-io/data';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';

import { cn } from '../utils/cn';
import { relationRecordDistinction, relationRecordLabel, sharedLabels } from './relation-label';
import type { RecordValues } from './relation-keys';
import type { PendingLink } from './use-relation-selection';

/** The list shows about five rows before it scrolls; more placeholders would only overflow. */
const MAX_PLACEHOLDER_ROWS = 5;

export interface RelationLinkListProps {
	relation: RelationModel;
	pending: readonly PendingLink[];
	/** Every current link on the server, or null when unknown. */
	total: number | null;
	isLoading: boolean;
	error: Error | null;
	hasNextPage: boolean;
	isFetchingNextPage: boolean;
	onLoadMore: () => void;
	onToggle: (record: RecordValues) => void;
	/** Why a current link cannot be removed, or null when it can. Its remove control is then not shown; the reason is. */
	removeReason: string | null;
	/** Nothing can change: no remove or undo controls. */
	readOnly: boolean;
	/** Controls are shown but not usable for now (a save is running). */
	disabled: boolean;
	/** Text for a record that is linked elsewhere and will move here, or null. */
	moveHint?: (record: RecordValues) => string | null;
	/** Open a linked record (the record panel); omit to hide the control. */
	onOpen?: (record: RecordValues) => void;
	/** Why a record cannot be opened, or null when it can. */
	openReason?: (record: RecordValues) => string | null;
	/** Show the "Linked N" line above the list. Default true. */
	showSummary?: boolean;
	/** While loading: rows to hold space for (the links the record already shows), so the list does not grow when they arrive. */
	placeholderCount?: number;
}

export function RelationLinkList({
	relation,
	pending,
	total,
	isLoading,
	error,
	hasNextPage,
	isFetchingNextPage,
	onLoadMore,
	onToggle,
	removeReason,
	readOnly,
	disabled,
	moveHint,
	onOpen,
	openReason,
	showSummary = true,
	placeholderCount = 0,
}: RelationLinkListProps) {
	const linkedCount = total ?? pending.filter((link) => link.state === 'linked').length;
	const labels = useMemo(() => pending.map((link) => relationRecordLabel(relation, link.record) || 'Unnamed record'), [pending, relation]);
	const shared = useMemo(() => sharedLabels(labels), [labels]);

	return (
		<section aria-label='Linked records' className='space-y-1.5'>
			{showSummary ? (
				<div className='text-muted-foreground flex items-center gap-2 text-xs'>
					<span>Linked</span>
					<Badge variant='outline' size='sm' className='tabular-nums' data-testid='relation-linked-count'>
						{linkedCount}
					</Badge>
				</div>
			) : null}
			<div className='max-h-44 overflow-y-auto rounded-md border' data-testid='relation-links'>
				{isLoading && placeholderCount > 0 ? (
					<ul className='space-y-1 p-1' role='status' aria-label='Loading links'>
						{Array.from({ length: Math.min(placeholderCount, MAX_PLACEHOLDER_ROWS) }, (_, index) => (
							<li key={index} aria-hidden className='bg-muted/40 h-8 animate-pulse rounded-[calc(var(--radius-md)-5px)]' />
						))}
					</ul>
				) : isLoading ? (
					<div className='text-muted-foreground flex items-center justify-center gap-2 py-4 text-sm'>
						<Loader2 className='h-3.5 w-3.5 animate-spin' aria-hidden />
						Loading links…
					</div>
				) : error ? (
					<div role='alert' className='text-destructive px-3 py-3 text-sm'>
						The links could not be loaded: {error.message}
					</div>
				) : pending.length === 0 ? (
					<div className='text-muted-foreground py-4 text-center text-sm'>No linked records</div>
				) : (
					// Rows nest in the bordered list: radius = list radius - (border 1px + padding 4px).
					<ul className='space-y-1 p-1'>
						{pending.map((link, index) => {
							const label = labels[index]!;
							const removing = link.state === 'removed';
							const adding = link.state === 'added';
							// Links that share a label say what tells them apart.
							const distinction = shared.has(label) ? relationRecordDistinction(relation, link.record) : '';
							const hint = [distinction, adding ? moveHint?.(link.record) ?? null : null].filter(Boolean).join(' · ') || null;
							// A link that cannot be removed gets no remove control (the reason shows below the list).
							const showToggle = !readOnly && (adding || removing || !removeReason);
							return (
								<li
									key={`${link.state}:${link.key}`}
									data-state={link.state}
									className={cn(
										'bg-muted/60 flex items-center gap-2 rounded-[calc(var(--radius-md)-5px)] px-2 py-1',
										removing && 'opacity-64',
									)}
								>
									<div className='min-w-0 flex-1'>
										<div className={cn('truncate text-sm', removing && 'line-through')} title={label}>
											{label}
										</div>
										{hint ? <div className='text-muted-foreground truncate text-xs'>{hint}</div> : null}
									</div>
									{onOpen && !removing ? (
										<Button
											type='button'
											variant='ghost'
											size='sm'
											className='h-6 w-6 shrink-0 p-0'
											disabled={Boolean(openReason?.(link.record))}
											title={openReason?.(link.record) ?? `Open ${label}`}
											aria-label={`Open ${label}`}
											onClick={() => onOpen(link.record)}
										>
											<ExternalLink className='h-3 w-3' />
										</Button>
									) : null}
									{adding ? <Badge variant='secondary' size='sm'>New</Badge> : null}
									{removing ? <Badge variant='outline' size='sm'>Removed</Badge> : null}
									{showToggle ? (
										<Button
											type='button'
											variant='ghost'
											size='sm'
											className='h-6 w-6 shrink-0 p-0'
											disabled={disabled}
											title={removing ? `Keep ${label}` : adding ? `Don't link ${label}` : `Remove ${label}`}
											aria-label={removing ? `Keep ${label}` : adding ? `Don't link ${label}` : `Remove ${label}`}
											onClick={() => onToggle(link.record)}
										>
											{removing ? <RotateCcw className='h-3 w-3' /> : <X className='h-3 w-3' />}
										</Button>
									) : null}
								</li>
							);
						})}
					</ul>
				)}
				{hasNextPage ? (
					<div className='flex justify-center py-1'>
						<Button type='button' variant='ghost' size='sm' onClick={onLoadMore} disabled={isFetchingNextPage}>
							{isFetchingNextPage ? 'Loading…' : 'Show more links'}
						</Button>
					</div>
				) : null}
			</div>
			{removeReason && pending.some((link) => link.state === 'linked') ? (
				<p className='text-muted-foreground text-xs'>{removeReason}</p>
			) : null}
		</section>
	);
}

/**
 * Requests from the relation editor to show something else: another table
 * (for example the table that stores links which need more information than
 * the editor can enter) or one linked record. The relation components never
 * navigate themselves; the host or the record panel decides what opening means.
 */
import { createContext, useContext } from 'react';

import type { SheetsFilterGroup } from '../grid/view-state/view-state.types';

export interface SheetsOpenTableRequest {
	/** `TableModel.key` of the table to open. */
	tableKey: string;
	/** GraphQL type name of that table. */
	tableName: string;
	/**
	 * The rows the user was looking at (the junction rows of this record), as a filter
	 * group a host passes straight to `<Sheets filters>`; null when no exact filter can be
	 * built, in which case the host opens the table unfiltered.
	 */
	filters: SheetsFilterGroup | null;
	/** Why the editor asks: the links live in a table with more fields than the editor can fill. */
	reason: 'linked-records';
}

export type SheetsOpenTableHandler = (request: SheetsOpenTableRequest) => void;

export const SheetsOpenTableContext = createContext<SheetsOpenTableHandler | null>(null);

/** The host's handler for opening another table, or null when the host has none. */
export function useOpenTableHandler(): SheetsOpenTableHandler | null {
	return useContext(SheetsOpenTableContext);
}

/** A request to show one linked record, for example in the record panel's navigation stack. */
export interface SheetsOpenRecordRequest {
	/** `TableModel.key` of the record's table. */
	tableKey: string;
	/** GraphQL type name of that table. */
	tableName: string;
	/** Primary-key values of the record, by field name. */
	key: Readonly<Record<string, unknown>>;
	/** The record's label, for a title while it loads. */
	label: string;
}

export type SheetsOpenRecordHandler = (request: SheetsOpenRecordRequest) => void;

export const SheetsOpenRecordContext = createContext<SheetsOpenRecordHandler | null>(null);

/** The host's handler for opening a linked record, or null when the host has none. */
export function useOpenRecordHandler(): SheetsOpenRecordHandler | null {
	return useContext(SheetsOpenRecordContext);
}

'use client';

/**
 * Search and pick related records. The search box drives a listbox
 * (combobox pattern): ArrowUp/ArrowDown/Home/End move the highlight, Enter
 * picks or unpicks it, and focus stays in the search box. Records load page
 * by page from the related table.
 */
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type UIEvent } from 'react';
import { Check, Loader2, Search } from 'lucide-react';

import type { RelationModel } from '@constructive-io/data';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

import { cn } from '../utils/cn';
import { linkKey, type RecordValues } from './relation-keys';
import { relationRecordDistinction, relationRecordLabel, sharedLabels } from './relation-label';

export interface RelationPickerProps {
	relation: RelationModel;
	/** Name of the related table, for the heading. */
	targetName: string;
	search: string;
	onSearchChange: (text: string) => void;
	/** Why the records cannot be searched, or null when they can. */
	searchReason: string | null;
	candidates: readonly RecordValues[];
	total: number | null;
	isLoading: boolean;
	error: Error | null;
	hasNextPage: boolean;
	isFetchingNextPage: boolean;
	onLoadMore: () => void;
	isSelected: (record: RecordValues) => boolean;
	onToggle: (record: RecordValues) => void;
	disabled: boolean;
	/** Text for a record that is linked elsewhere and will move here, or null. */
	moveHint?: (record: RecordValues) => string | null;
	/** Focus the search box when the picker mounts. Default true. */
	autoFocus?: boolean;
	/** Escape in the search box: close the picker (a record panel section). Omit to let Escape reach the host (the cell editor closes). */
	onEscape?: () => void;
}

const LOAD_MORE_MARGIN_PX = 48;

export function RelationPicker({
	relation,
	targetName,
	search,
	onSearchChange,
	searchReason,
	candidates,
	total,
	isLoading,
	error,
	hasNextPage,
	isFetchingNextPage,
	onLoadMore,
	isSelected,
	onToggle,
	disabled,
	moveHint,
	autoFocus = true,
	onEscape,
}: RelationPickerProps) {
	const baseId = useId();
	const listId = `${baseId}-options`;
	const [active, setActive] = useState(0);
	const inputRef = useRef<HTMLInputElement>(null);
	const count = candidates.length;
	const labels = useMemo(() => candidates.map((record) => relationRecordLabel(relation, record) || 'Unnamed record'), [candidates, relation]);
	const shared = useMemo(() => sharedLabels(labels), [labels]);

	// The picker mounts once the related table is known; start typing right away.
	useEffect(() => {
		if (autoFocus) inputRef.current?.focus();
		// Only on mount: a later prop change must not steal focus.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);

	useEffect(() => {
		setActive((index) => (count === 0 ? 0 : Math.min(index, count - 1)));
	}, [count]);
	useEffect(() => {
		setActive(0);
	}, [search]);

	// A to-one relation picks one record; a to-many relation adds records.
	const verb = relation.kind === 'belongsTo' || relation.kind === 'hasOne' ? 'Choose from' : 'Add from';
	const optionId = (index: number) => `${baseId}-option-${index}`;
	const activeRecord = candidates[active];

	const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
		if (event.key === 'Escape' && onEscape) {
			event.preventDefault();
			event.stopPropagation();
			onEscape();
			return;
		}
		if (count === 0) return;
		if (event.key === 'ArrowDown') {
			event.preventDefault();
			setActive((index) => {
				const next = Math.min(index + 1, count - 1);
				if (next === count - 1 && hasNextPage && !isFetchingNextPage) onLoadMore();
				return next;
			});
		} else if (event.key === 'ArrowUp') {
			event.preventDefault();
			setActive((index) => Math.max(index - 1, 0));
		} else if (event.key === 'Home') {
			event.preventDefault();
			setActive(0);
		} else if (event.key === 'End') {
			event.preventDefault();
			setActive(count - 1);
		} else if (event.key === 'Enter' && !event.ctrlKey && !event.metaKey) {
			event.preventDefault();
			if (activeRecord && !disabled) onToggle(activeRecord);
		}
	};

	useEffect(() => {
		if (typeof document === 'undefined') return;
		document.getElementById(optionId(active))?.scrollIntoView?.({ block: 'nearest' });
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [active]);

	const handleScroll = (event: UIEvent<HTMLDivElement>) => {
		const element = event.currentTarget;
		if (!hasNextPage || isFetchingNextPage) return;
		if (element.scrollTop + element.clientHeight >= element.scrollHeight - LOAD_MORE_MARGIN_PX) onLoadMore();
	};

	return (
		<section aria-label={`${verb} ${targetName}`} className='flex flex-col gap-1.5'>
			<div className='text-muted-foreground flex items-center gap-2 text-xs'>
				<span>{verb}</span>
				<Badge variant='outline' size='sm' className='max-w-[12rem] truncate' title={targetName}>
					{targetName}
				</Badge>
				{total !== null ? (
					<Badge variant='secondary' size='sm' className='ml-auto tabular-nums'>
						{count} / {total}
					</Badge>
				) : null}
			</div>
			<InputGroup>
				<InputGroupAddon>
					<Search />
				</InputGroupAddon>
				<InputGroupInput
					ref={inputRef}
					role='combobox'
					aria-expanded='true'
					aria-controls={listId}
					aria-autocomplete='list'
					aria-activedescendant={activeRecord ? optionId(active) : undefined}
					aria-label={`Search ${targetName}`}
					value={search}
					onChange={(event) => onSearchChange(event.target.value)}
					onKeyDown={handleKeyDown}
					// The reason sits in the box itself, so no extra line appears once it is known.
					placeholder={searchReason ?? 'Type to search…'}
					disabled={Boolean(searchReason)}
					title={searchReason ?? undefined}
					size='sm'
				/>
			</InputGroup>
			{/* A fixed height, so the editor does not change size as records load or a search narrows them. */}
			<div className='h-48 overflow-y-auto rounded-md border' onScroll={handleScroll}>
				<div id={listId} role='listbox' aria-label={targetName} aria-multiselectable={relation.kind === 'hasMany' || relation.kind === 'manyToMany'} data-testid='relation-options' className='space-y-0.5 p-1'>
					{isLoading ? (
						<div className='text-muted-foreground flex items-center justify-center gap-2 py-5 text-sm'>
							<Loader2 className='h-3.5 w-3.5 animate-spin' aria-hidden />
							Loading…
						</div>
					) : error ? (
						<div role='alert' className='text-destructive px-2 py-4 text-sm'>
							The records could not be loaded: {error.message}
						</div>
					) : count === 0 ? (
						<div className='text-muted-foreground py-5 text-center text-sm'>{search.trim() ? 'No matching records' : 'No records yet'}</div>
					) : (
						candidates.map((record, index) => {
							const label = labels[index]!;
							const selected = isSelected(record);
							// Records that share a label say what tells them apart.
							const distinction = shared.has(label) ? relationRecordDistinction(relation, record) : '';
							const hint = [distinction, selected ? null : moveHint?.(record) ?? null].filter(Boolean).join(' · ') || null;
							return (
								<div
									key={linkKey(relation, record) ?? `row-${index}`}
									id={optionId(index)}
									role='option'
									aria-selected={selected}
									aria-disabled={disabled}
									data-active={index === active || undefined}
									onMouseDown={(event) => event.preventDefault()}
									onMouseEnter={() => setActive(index)}
									onClick={() => {
										if (!disabled) onToggle(record);
									}}
									className={cn(
										// Options nest in the bordered list: radius = list radius - (border 1px + padding 4px).
										'flex items-center gap-2 rounded-[calc(var(--radius-md)-5px)] px-2 py-1.5',
										disabled ? 'cursor-not-allowed opacity-64' : 'cursor-pointer',
										index === active && 'bg-accent/60',
										selected && 'text-link',
									)}
								>
									<div className='min-w-0 flex-1'>
										<div className='truncate text-sm' title={label}>
											{label}
										</div>
										{hint ? <div className='text-muted-foreground truncate text-xs'>{hint}</div> : null}
									</div>
									{selected ? <Check className='text-primary h-3.5 w-3.5 shrink-0' aria-hidden /> : null}
								</div>
							);
						})
					)}
				</div>
				{hasNextPage && !isLoading ? (
					<div className='flex justify-center py-1'>
						<Button type='button' variant='ghost' size='sm' onClick={onLoadMore} disabled={isFetchingNextPage}>
							{isFetchingNextPage ? 'Loading…' : 'Show more'}
						</Button>
					</div>
				) : null}
			</div>
		</section>
	);
}

/**
 * Searching related records by their label fields, with only the filter
 * fields and operators the related table's filter model really has.
 */
import type { TableModel } from '@constructive-io/data';

/** Text operators in order of preference. */
const TEXT_OPERATORS = ['includesInsensitive', 'includes'] as const;

interface SearchClause {
	/** Filter input field. */
	field: string;
	/** Operator to use. */
	operator: (typeof TEXT_OPERATORS)[number];
}

/** The label fields that can be searched as text, with the operator each uses. */
export function searchClauses(target: TableModel, fields: readonly string[]): SearchClause[] {
	const clauses: SearchClause[] = [];
	for (const name of fields) {
		const column = target.columns.find((candidate) => candidate.name === name);
		const filter = column?.filter;
		if (!filter || column.value.isArray) continue;
		const operator = TEXT_OPERATORS.find((candidate) => filter.operators.some((entry) => entry.name === candidate));
		if (operator) clauses.push({ field: filter.field, operator });
	}
	return clauses;
}

/**
 * The filter for a search text, or null when the text is empty or nothing
 * can be searched. Several fields are combined with `or` only when the
 * related table's filter has it; otherwise the first searchable field is used.
 */
export function searchFilter(
	target: TableModel,
	fields: readonly string[],
	text: string,
): Record<string, unknown> | null {
	const query = text.trim();
	if (!query) return null;
	const clauses = searchClauses(target, fields);
	if (clauses.length === 0) return null;
	const parts = clauses.map((clause) => ({ [clause.field]: { [clause.operator]: query } }));
	const canCombine = target.operations.list?.logicalOperators.includes('or') ?? false;
	if (parts.length > 1 && canCombine) return { or: parts };
	return parts[0] ?? null;
}

'use client';

/**
 * One relation of one record, for the record panel: the same rules as the
 * grid's cell editor (`useRelationEditor`), rendered inline (no overlay, no
 * focus trap). Pending choices are kept until the section's own Save (Discard
 * drops them; Ctrl or Cmd+Enter saves). belongsTo hands its change to
 * `onCommitPatch` (a new record keeps it locally instead of a write); list
 * relations wait until the record exists. Opening a linked record calls
 * `onOpenRecord`, or else the nearest `SheetsOpenRecordContext` handler.
 */
import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from 'react';
import { Check, RotateCcw } from 'lucide-react';

import type { RelationModel, TableModel } from '@constructive-io/data';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';

import { relationLabelIn } from '../cell-types/field-label';
import type { SheetsRowIdentifier } from '../row-identity';
import { RelationEditorBody } from './relation-editor-body';
import type { RecordValues } from './relation-keys';
import type { SheetsOpenRecordHandler } from './relation-navigation';
import { useRelationEditor } from './use-relation-editor';

export interface RelationSectionProps {
	/** The record's table model. */
	table: TableModel;
	/** One relation of that table (the grid's rule for which to show: `gridRelations(table)`). */
	relation: RelationModel;
	/** The saved record (scalar fields and relation fields as read) or the new record's values; null while it loads. */
	row: Readonly<Record<string, unknown>> | null;
	/** The saved record's primary key; null for a record that is not created yet. */
	rowIdentifier: SheetsRowIdentifier | null;
	/** True for a record that is not created yet. */
	isDraft: boolean;
	/** A new record needs this link: the heading is marked like a required field. */
	required?: boolean;
	/** A reason the host already holds for keeping the relation read-only; it wins over the model's rules. */
	readOnlyReason?: string | null;
	/**
	 * belongsTo: the local key fields plus the chosen record under `relation.fieldName`
	 * (the grid editor's shape). On a new record this is the change itself; on a saved
	 * record it follows the write, for an immediate update of the shown record.
	 */
	onCommitPatch?: (patch: Record<string, unknown>) => void;
	/** Called after any write (the affected tables are already refetching). */
	onInvalidateData?: () => void;
	/** Open a linked record; defaults to the nearest `SheetsOpenRecordContext` handler. Without either, no open control is shown. */
	onOpenRecord?: SheetsOpenRecordHandler;
	/** Heading level of the section title. Default 3. */
	headingLevel?: 2 | 3 | 4;
}

export function RelationSection({
	table,
	relation,
	row,
	rowIdentifier,
	isDraft,
	required = false,
	readOnlyReason,
	onCommitPatch,
	onInvalidateData,
	onOpenRecord,
	headingLevel = 3,
}: RelationSectionProps) {
	const headingId = useId();
	const record = (row ?? null) as RecordValues | null;
	const editor = useRelationEditor({
		relation,
		table,
		row: record,
		rowIdentifier,
		isDraft,
		value: record ? record[relation.fieldName] : null,
		onInvalidateData,
		readOnlyReason,
		onOpenRecord,
	});
	const { editable, saving, selection, save, discard } = editor;

	// The picker opens from "Add link" / "Change link" and closes on Escape, after a save
	// and on Discard; focus then goes back to that button.
	const toggleRef = useRef<HTMLButtonElement | null>(null);
	const [pickerOpen, setPickerOpenState] = useState(false);
	const [returnFocus, setReturnFocus] = useState(false);
	const setPickerOpen = useCallback((open: boolean) => {
		setPickerOpenState(open);
		if (!open) setReturnFocus(true);
	}, []);
	useEffect(() => {
		if (!returnFocus || pickerOpen) return;
		toggleRef.current?.focus();
		setReturnFocus(false);
	}, [pickerOpen, returnFocus]);
	const picker = useMemo(() => ({ open: pickerOpen, setOpen: setPickerOpen, toggleRef }), [pickerOpen, setPickerOpen]);

	const handleSave = useCallback(async () => {
		const result = await save();
		if ((result.status === 'draft' || result.status === 'saved') && result.patch) onCommitPatch?.(result.patch);
		if (result.status === 'draft' || result.status === 'saved') setPickerOpen(false);
	}, [onCommitPatch, save, setPickerOpen]);

	const handleDiscard = useCallback(() => {
		discard();
		setPickerOpen(false);
	}, [discard, setPickerOpen]);

	const handleKeyDown = useCallback(
		(event: KeyboardEvent<HTMLElement>) => {
			if (event.key === 'Enter' && (event.ctrlKey || event.metaKey) && selection.dirty) {
				event.preventDefault();
				void handleSave();
			}
		},
		[handleSave, selection.dirty],
	);

	const Heading = `h${headingLevel}` as 'h2' | 'h3' | 'h4';
	const count = editor.links.total ?? editor.current.length;

	return (
		<section
			aria-labelledby={headingId}
			data-slot='relation-section'
			data-relation={relation.fieldName}
			className='flex flex-col gap-2'
			onKeyDown={handleKeyDown}
		>
			<div className='flex items-center gap-2'>
				<Heading id={headingId} className='truncate text-sm font-medium' title={relation.fieldName}>
					{relationLabelIn(table, relation)}
					{required ? <span aria-hidden> *</span> : null}
				</Heading>
				<Badge variant='outline' size='sm' className='tabular-nums' data-testid='relation-linked-count'>
					{count}
				</Badge>
				<span className='text-muted-foreground truncate text-xs' title={relation.targetName}>
					{relation.targetName}
				</span>
			</div>

			<RelationEditorBody editor={editor} layout='section' picker={picker} />

			{editable && selection.dirty ? (
				<div className='flex justify-end gap-2'>
					<Button type='button' variant='outline' size='sm' onClick={handleDiscard} disabled={saving}>
						<RotateCcw className='mr-1 h-3 w-3' aria-hidden />
						Discard
					</Button>
					<Button type='button' size='sm' onClick={() => void handleSave()} disabled={saving}>
						<Check className='mr-1 h-3 w-3' aria-hidden />
						{saving ? 'Saving…' : isDraft && relation.kind === 'belongsTo' ? 'Apply' : 'Save links'}
					</Button>
				</div>
			) : null}
		</section>
	);
}

// Undo for a saved link change. Each step runs the inverse of the writes the step before it
// made (see `invertRelationChanges`), so undo and redo take turns over the same links. A step
// that changes nothing throws after it says why, and the history keeps it to try again.
import type { HistoryEntry } from '../grid/hooks/use-undo-redo';
import {
	applyRelationChanges,
	describeFailures,
	invertRelationChanges,
	type RelationChangeOutcome,
	type RelationChangeRunner,
} from './relation-changes';

export interface RelationUndoDeps {
	run: RelationChangeRunner;
	/** Read the changed tables again. */
	refresh: () => Promise<void>;
	/** The step ran. */
	onDone?: (message: string) => void;
	/** The step, or part of it, did not run: why. */
	onFailed: (title: string, messages: readonly string[]) => void;
}

/** Thrown by a step that changed nothing; its reason was already reported. */
class RelationUndoRefused extends Error {}

/** The history entry for `outcome`, or null when it applied nothing. */
export function relationHistoryEntry(outcome: RelationChangeOutcome, deps: RelationUndoDeps): HistoryEntry | null {
	if (outcome.applied.length === 0) return null;
	let last: Pick<RelationChangeOutcome, 'applied' | 'created'> = outcome;
	let running = false;

	const step = (done: string, failed: string) => async () => {
		if (running) throw new RelationUndoRefused();
		const plan = invertRelationChanges(last);
		if (plan.ok === false) {
			deps.onFailed(failed, [plan.reason]);
			throw new RelationUndoRefused(plan.reason);
		}
		running = true;
		try {
			// In order, stopping at the first refusal: a single link is freed before it is taken again.
			const result = await applyRelationChanges(plan.changes, deps.run, { dependent: true });
			if (result.applied.length > 0) await deps.refresh();
			if (result.failed.length > 0) deps.onFailed(failed, describeFailures(result));
			if (result.applied.length === 0) throw new RelationUndoRefused();
			// What ran is what the next step turns back.
			last = result;
			if (result.failed.length === 0) deps.onDone?.(done);
		} finally {
			running = false;
		}
	};

	return {
		label: 'Change links',
		undo: step('Link change undone', 'The link change could not be undone'),
		redo: step('Link change redone', 'The link change could not be redone'),
	};
}

/**
 * Page through one table's rows with the paging its list field really has
 * (cursor, offset, or one page), through the host's adapter. Cache entries
 * live under the table's cache key, so invalidating a table after a write
 * refreshes these lists too.
 */
import { useMemo } from 'react';
import { useInfiniteQuery } from '@tanstack/react-query';

import type { TableModel } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
import { sheetsQueryKeys } from '../hooks/query-keys';
import type { RecordValues } from './relation-keys';

/** Rows per page in the relation editor. */
export const RELATION_PAGE_SIZE = 25;

export interface ModelPagesOptions {
	/** The table to read, or null while it loads. */
	model: TableModel | null;
	/** What the list is for; part of the cache key. */
	purpose: 'relation-candidates' | 'relation-links' | 'relation-junction-links';
	/** Extra cache-key parts that change the result (filter inputs). */
	keyParts: readonly unknown[];
	/** A filter in the server's filter input shape, or null for every row. */
	where: Readonly<Record<string, unknown>> | null;
	/** Relation fields to select with each row. */
	relations?: readonly string[];
	enabled?: boolean;
	pageSize?: number;
}

export interface ModelPages {
	rows: RecordValues[];
	/** Every matching row, or null when the list does not count. */
	total: number | null;
	isLoading: boolean;
	isFetchingNextPage: boolean;
	hasNextPage: boolean;
	fetchNextPage: () => void;
	error: Error | null;
}

type PageParam = { after?: string; offset?: number } | null;

interface Page {
	rows: RecordValues[];
	total: number | null;
	nextAfter: string | null;
	hasNextPage: boolean;
}

type PagingMode = 'cursor' | 'offset' | 'single';

function pagingMode(model: TableModel): PagingMode {
	const list = model.operations.list;
	if (!list?.first) return 'single';
	if (list.after && list.pageInfo) return 'cursor';
	if (list.offset) return 'offset';
	return 'single';
}

export function useModelPages(options: ModelPagesOptions): ModelPages {
	const { model, purpose, keyParts, where, relations, enabled = true, pageSize = RELATION_PAGE_SIZE } = options;
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const mode = model ? pagingMode(model) : 'single';
	const counts = Boolean(model?.operations.list?.totalCount);

	const query = useInfiniteQuery<Page, Error>({
		queryKey: [...sheetsQueryKeys.table(scopeKey, model?.key ?? ''), purpose, mode, pageSize, where, relations ?? null, ...keyParts],
		queryFn: async ({ pageParam }) => {
			if (!model) throw new Error('The table is not ready.');
			const param = pageParam as PageParam;
			const result = await adapter.listRows(
				{ model, tableName: model.key },
				{
					where: where ?? undefined,
					limit: mode === 'single' ? undefined : pageSize,
					after: param?.after,
					offset: param?.offset,
					relations: relations && relations.length > 0 ? relations : 'none',
					includeTotalCount: counts,
				},
				execute,
			);
			const loadedBefore = param?.offset ?? 0;
			const hasNextPage =
				mode === 'cursor'
					? Boolean(result.pageInfo?.hasNextPage && result.pageInfo.endCursor)
					: mode === 'offset'
						? result.rows.length === pageSize && (!counts || loadedBefore + result.rows.length < result.totalCount)
						: false;
			return {
				rows: result.rows,
				total: counts ? result.totalCount : null,
				nextAfter: result.pageInfo?.endCursor ?? null,
				hasNextPage,
			};
		},
		initialPageParam: null as PageParam,
		getNextPageParam: (last, pages): PageParam | undefined => {
			if (!last.hasNextPage) return undefined;
			if (mode === 'cursor') return last.nextAfter ? { after: last.nextAfter } : undefined;
			return { offset: pages.reduce((sum, page) => sum + page.rows.length, 0) };
		},
		enabled: enabled && Boolean(model),
		staleTime: 30 * 1000,
	});

	const rows = useMemo(() => query.data?.pages.flatMap((page) => page.rows) ?? [], [query.data]);
	const pages = query.data?.pages;
	const total = pages && pages.length > 0 ? (pages[pages.length - 1]?.total ?? null) : null;

	return {
		rows,
		total,
		isLoading: enabled && Boolean(model) && query.isPending,
		isFetchingNextPage: query.isFetchingNextPage,
		hasNextPage: Boolean(query.hasNextPage),
		fetchNextPage: () => {
			void query.fetchNextPage();
		},
		error: query.error ?? null,
	};
}

/**
 * The state and actions of editing one relation of one record, shared by the
 * grid's cell editor and the record panel's relation section. Driven only by
 * the relation model: belongsTo writes the record's local key fields,
 * hasOne/hasMany write the related records' key fields, manyToMany creates
 * and deletes junction rows. Nothing is written until `save`; a failure keeps
 * the user's choices with the server's message; after a write the affected
 * tables refetch.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';

import type { RelationModel, TableModel } from '@constructive-io/data';

import { useSheetsAdapter } from '../adapter/use-sheets-adapter';
import { useSheetsContext } from '../context/sheets-context';
