import type { SheetsRowIdentifier } from '../row-identity';
import { relationEditCapability, type RelationEditCapability } from './relation-capability';
import {
	adapterChangeRunner,
	applyRelationChanges,
	describeFailures,
	planBelongsTo,
	planHasLinks,
	planJunctionLinks,
	type LinkedRecord,
