export interface RelationEditorOptions {
	relation: RelationModel;
	/** The record's table. */
	table: TableModel;
	/** The record (server row or draft values), or null when it is not known. */
	row: RecordValues | null;
	/** The saved record's primary key, or null for a draft or a record that cannot be identified. */
	rowIdentifier: SheetsRowIdentifier | null;
	/** True for a record that does not exist on the server yet. */
	isDraft: boolean;
	/** The value of the relation field on the record. */
	value: unknown;
	/** Ask the host to refetch after an out-of-band write. */
	onInvalidateData?: () => void;
	/** A reason the host already holds for keeping the relation read-only (it wins over the model's rules). */
	readOnlyReason?: string | null;
	/** Open a linked record; defaults to the nearest `SheetsOpenRecordContext` handler. */
	onOpenRecord?: SheetsOpenRecordHandler | null;
}

/** What `save` did. `patch` is the belongsTo change for the record (local key fields plus the record under the relation field). */
export type RelationSaveResult =
	| { status: 'unchanged' }
	| { status: 'draft'; patch: Record<string, unknown> }
	| { status: 'saved'; patch: Record<string, unknown> | null }
	| { status: 'failed' };

export interface RelationEditor {
	relation: RelationModel;
	target: TableModel | null;
	junction: TableModel | null;
	/** True while the related or junction table model loads. */
	modelsLoading: boolean;
	/** The related table could not be loaded. */
	targetError: Error | null;
	capability: RelationEditCapability;
	/** Links can be added or removed. */
	editable: boolean;
	/**
	 * The related table is still loading and links will most likely be addable: the
	 * picker can show its frame (disabled) now, so the editor keeps its height when
	 * the table arrives.
	 */
	linkPending: boolean;
	/** Why nothing can be changed, shown once the models are known; null when something can. */
	blockedReason: string | null;
	links: RelationLinks;
	/** Current links (belongsTo: from the record's own key fields). */
	current: readonly LinkedRecord[];
	selection: RelationSelection;
	/** For hasOne/hasMany: text for a record linked elsewhere, which linking moves here. */
	moveHint: ((record: RecordValues) => string | null) | undefined;
	search: string;
	setSearch: (text: string) => void;
	searchReason: string | null;
	candidates: ModelPages;
	saving: boolean;
	errors: string[];
	notice: string | null;
	/** Pick or unpick a record; a refusal is shown as the notice. */
	toggle: (record: RecordValues) => void;
	/** Single relation: remove the link; a refusal is shown as the notice. */
	clear: () => void;
	/** Write the pending choices (or hand a draft belongsTo choice back). `clear` writes "no link" for a to-one relation instead. */
	save: (options?: { clear?: boolean }) => Promise<RelationSaveResult>;
	/** Forget the pending choices and messages. */
	discard: () => void;
	create: {
		/** Why a related record cannot be created here, or null. */
		blocked: string | null;
		/** The create form plan, or null while the related model loads. */
		plan: RelatedCreatePlan | null;
		/** Create the record from parsed form values; resolves to an error message or null. */
		submit: (values: FieldValues) => Promise<string | null>;
	};
	/** "Open {table}" for links that live in a table with more fields than the editor fills, or null. */
	junctionAction: { tableName: string; open: () => void } | null;
	/** Open a linked record in the host (record panel), or null when the host has no handler. */
	openRecord: ((record: RecordValues) => void) | null;
	/** Why a linked record cannot be opened, or null when it can. */
	openRecordReason: (record: RecordValues) => string | null;
}

const SEARCH_DELAY_MS = 250;

function useDebounced<T>(value: T, delay: number): T {
	const [debounced, setDebounced] = useState(value);
	useEffect(() => {
		const timer = setTimeout(() => setDebounced(value), delay);
		return () => clearTimeout(timer);
	}, [value, delay]);
	return debounced;
}

/** belongsTo: the current link, keyed by the record's own key fields. */
function belongsToCurrent(relation: RelationModel, row: RecordValues | null, value: unknown): LinkedRecord[] {
	const nested = value && typeof value === 'object' && !Array.isArray(value) ? (value as RecordValues) : null;
	const fromRow = row ? Object.fromEntries(relation.keys.map((pair) => [pair.remote, row[pair.local]])) : {};
	const key = belongsToCurrentKey(relation, row) ?? linkKey(relation, nested);
	if (!key) return [];
	return [{ key, record: nested ? { ...fromRow, ...nested } : fromRow }];
}

export function useRelationEditor(options: RelationEditorOptions): RelationEditor {
	const { relation, table, row, rowIdentifier, isDraft, value, onInvalidateData, readOnlyReason = null } = options;
	const queryClient = useQueryClient();
	const { execute, scopeKey } = useSheetsContext();
	const adapter = useSheetsAdapter();
	const openTable = useOpenTableHandler();
	const contextOpenRecord = useOpenRecordHandler();
	const openRecordHandler = options.onOpenRecord ?? contextOpenRecord;

	const targetModel = useTableModel(relation.targetKey);
	const junctionModel = useTableModel(relation.junction?.tableKey ?? null, { enabled: relation.kind === 'manyToMany' });
	const target = targetModel.model;
	const junction = junctionModel.model;
	const modelsLoading =
		(!target && targetModel.isLoading) || (relation.kind === 'manyToMany' && !junction && junctionModel.isLoading);

	const capability = useMemo<RelationEditCapability>(
		() =>
			readOnlyReason
				? { canLink: false, linkReason: readOnlyReason, canUnlink: false, unlinkReason: readOnlyReason }
				: relationEditCapability({ relation, table, target, junction, row, isDraft, rowIdentified: rowIdentifier != null }),
		[readOnlyReason, relation, table, target, junction, row, isDraft, rowIdentifier],
	);
	const editable = capability.canLink || capability.canUnlink;
	const linkPending =
		!capability.canLink &&
		modelsLoading &&
		relation.editable &&
		!readOnlyReason &&
		!(isDraft && relation.kind !== 'belongsTo');

	const links = useRelationLinks({
		relation,
		row,
		rowValue: value,
		target,
		junction,
		modelsLoading,
		enabled: relation.kind !== 'belongsTo' && !isDraft,
	});
	const current = useMemo(
		() => (relation.kind === 'belongsTo' ? belongsToCurrent(relation, row, value) : links.links),
		[links.links, relation, row, value],
	);

	const linkedHere = useMemo(
		() => (relation.kind === 'hasMany' && row ? (record: RecordValues) => hasLinkOwner(relation, row, record) === 'here' : undefined),
		[relation, row],
	);
	const selection = useRelationSelection({ relation, current, capability, linkedHere });

	const moveHint = useMemo(() => {
		if ((relation.kind !== 'hasMany' && relation.kind !== 'hasOne') || !row) return undefined;
		return (record: RecordValues) =>
			hasLinkOwner(relation, row, record) === 'elsewhere' ? 'Linked to another record; choosing it moves it here.' : null;
	}, [relation, row]);

	const [search, setSearch] = useState('');
	const debouncedSearch = useDebounced(search, SEARCH_DELAY_MS);
	const labelFields = relation.target.labelFields;
	const searchReason = target && searchClauses(target, labelFields).length === 0 ? 'These records cannot be searched by their label.' : null;
	const where = useMemo(
		() => (target ? searchFilter(target, labelFields, debouncedSearch) : null),
		[target, labelFields, debouncedSearch],
	);
	const candidates = useModelPages({
		model: target,
		purpose: 'relation-candidates',
		keyParts: [debouncedSearch.trim()],
		where,
		enabled: capability.canLink,
	});

	const [saving, setSaving] = useState(false);
	const [errors, setErrors] = useState<string[]>([]);
	const [notice, setNotice] = useState<string | null>(null);

	const toggle = useCallback(
		(record: RecordValues) => {
			setErrors([]);
			setNotice(selection.toggle(record));
		},
		[selection],
	);

	const clear = useCallback(() => {
		const refused = selection.clear();
		if (refused) setNotice(refused);
	}, [selection]);

	const refresh = useCallback(async () => {
		const models = [table, target, junction].filter((model): model is TableModel => Boolean(model));
		await Promise.all(
			models.flatMap((model) => [
				queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.table(scopeKey, model.key) }),
				queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.infiniteTable(scopeKey, model.key) }),
			]),
		);
		onInvalidateData?.();
	}, [junction, onInvalidateData, queryClient, scopeKey, table, target]);

	const run = useMemo(() => adapterChangeRunner(adapter, execute), [adapter, execute]);
	// A saved change takes a step in the grid's undo history; undoing it reports like any save.
	const recordHistory = useRecordHistory();
	const feedback = useOptionalFeedback();

	const planSave = useCallback((choice: RecordValues | null): RelationPlan => {
		if (relation.kind === 'belongsTo') {
			if (rowIdentifier == null) return { ok: false, reason: 'This record cannot be identified, so its links cannot be changed.' };
			return planBelongsTo(relation, table, rowIdentifier, choice, row);
		}
		if (!row) return { ok: false, reason: 'This record has no value to link by yet.' };
		if (relation.kind === 'manyToMany') {
			if (!junction) return { ok: false, reason: 'The table that stores these links could not be loaded.' };
			return planJunctionLinks(relation, junction, row, { added: selection.added, removed: selection.removed });
		}
		if (!target) return { ok: false, reason: 'The linked table could not be loaded.' };
		if (relation.kind === 'hasOne') {
			const chosen = choice;
			const added = chosen ? [{ key: linkKey(relation, chosen) ?? '', record: chosen }] : [];
			const removed = current[0] ? [current[0]] : [];
			return planHasLinks(relation, target, row, { added, removed });
		}
		return planHasLinks(relation, target, row, { added: selection.added, removed: selection.removed });
	}, [current, junction, relation, row, rowIdentifier, selection, table, target]);

	/** belongsTo: the record's new key fields plus the chosen record under the relation field. */
	const belongsToPatch = useCallback(
		(record: RecordValues | null): Record<string, unknown> | null => {
			const patch = record ? belongsToLinkPatch(relation, record) : belongsToClearPatch(relation);
			return patch ? { ...patch, [relation.fieldName]: record } : null;
		},
		[relation],
	);

	const save = useCallback(async (options: { clear?: boolean } = {}): Promise<RelationSaveResult> => {
		if (saving) return { status: 'failed' };
		// Clear (to-one): write "no link" now, whatever is pending.
		const clearing = Boolean(options.clear) && (relation.kind === 'belongsTo' || relation.kind === 'hasOne');
		const choice = clearing ? null : selection.choice ?? null;
		if (clearing ? current.length === 0 : !selection.dirty) return { status: 'unchanged' };
		setErrors([]);
		setNotice(null);

		const patch = relation.kind === 'belongsTo' ? belongsToPatch(choice) : null;
		if (relation.kind === 'belongsTo' && !patch) {
			setErrors(['The chosen record has no value to link by.']);
			return { status: 'failed' };
		}
		if (patch && isDraft) {
			selection.settle(new Set(selection.pending.map((link) => link.key)));
			return { status: 'draft', patch };
		}

		const plan = planSave(choice);
		if (plan.ok === false) {
			setErrors([plan.reason]);
			return { status: 'failed' };
		}
		setSaving(true);
		const outcome = await applyRelationChanges(plan.changes, run, {
			dependent: relation.kind === 'belongsTo' || relation.kind === 'hasOne',
		});
		if (outcome.applied.length > 0) await refresh();
		setSaving(false);
		const step =
			recordHistory &&
			relationHistoryEntry(outcome, {
				run,
				refresh,
				onDone: (message) => feedback?.noteWrite('update', 'success', message),
				onFailed: (title, messages) => feedback?.reportWriteError(title, messages),
			});
		if (step) recordHistory(step);

		if (outcome.failed.length === 0) {
			selection.settle(new Set(outcome.applied.map((change) => change.linkKey)));
			return { status: 'saved', patch };
		}
		const lines = describeFailures(outcome);
		if (outcome.applied.length > 0) {
			lines.unshift(`Saved ${outcome.applied.length} of ${plan.changes.length} changes.`);
			selection.settle(new Set(outcome.applied.map((change) => change.linkKey)));
		}
		setErrors(lines);
		return { status: 'failed' };
	}, [belongsToPatch, current.length, feedback, isDraft, planSave, recordHistory, refresh, relation.kind, run, saving, selection]);

	const discard = useCallback(() => {
		selection.reset();
		setErrors([]);
		setNotice(null);
		setSearch('');
	}, [selection]);

	const plan = useMemo(() => (target ? planRelatedCreate(relation, target, row) : null), [relation, row, target]);
	const createBlocked = !capability.canLink
		? capability.linkReason
		: isDraft && relation.kind !== 'belongsTo'
			? 'Save this record first, then link records to it.'
			: relation.kind === 'hasOne' && current.length > 0
				? 'Remove the current link first.'
				: plan && plan.ok === false
					? plan.reason
					: null;

	const submitCreate = useCallback(
		async (values: FieldValues): Promise<string | null> => {
			if (!target || !plan?.ok) return 'The linked table could not be loaded.';
			try {
				const created = await adapter.createRow<RecordValues>(
					{ model: target, tableName: target.key },
					{ ...plan.fixed, ...values },
					execute,
				);
				const label = relationRecordLabel(relation, created ?? values) || 'the new record';
				if (relation.kind === 'hasOne' || relation.kind === 'hasMany') {
					await refresh();
					setNotice(`Created and linked "${label}".`);
				} else {
					await queryClient.invalidateQueries({ queryKey: sheetsQueryKeys.table(scopeKey, target.key) });
					if (created) {
						const refused = selection.toggle(created);
						setNotice(refused ?? `Created "${label}". Save to link it.`);
					} else {
						setNotice(`Created "${label}". Find it in the list to link it.`);
					}
				}
				return null;
			} catch (error) {
				return error instanceof Error ? error.message : 'The record could not be created.';
			}
		},
		[adapter, execute, plan, queryClient, refresh, relation, scopeKey, selection, target],
	);

	const junctionInfo = relation.junction;
	const junctionAction = useMemo(() => {
		if (!openTable || !junctionInfo || junctionInfo.pure) return null;
		return {
			tableName: junctionInfo.tableName,
			open: () => {
				const leftValues = row ? junctionLeftValues(relation, row) : null;
				openTable({
					tableKey: junctionInfo.tableKey,
					tableName: junctionInfo.tableName,
					filters: junction && leftValues ? equalityFilterGroup(junction, leftValues) : null,
					reason: 'linked-records',
				});
			},
		};
	}, [junction, junctionInfo, openTable, relation, row]);

	const openRecordReason = useCallback(
		(record: RecordValues): string | null => {
			if (!relation.targetKey) return 'The linked table is not available.';
			return fieldValues(record, relation.target.primaryKey) ? null : 'This record cannot be identified, so it cannot be opened.';
		},
		[relation],
	);
	const openRecord = useMemo(() => {
		if (!openRecordHandler || !relation.targetKey) return null;
		const tableKey = relation.targetKey;
		return (record: RecordValues) => {
			const key = fieldValues(record, relation.target.primaryKey);
			if (!key) return;
			openRecordHandler({ tableKey, tableName: relation.targetName, key, label: relationRecordLabel(relation, record) });
		};
	}, [openRecordHandler, relation]);

	return {
		relation,
		target,
		junction,
		modelsLoading,
		targetError: targetModel.error,
		capability,
		editable,
		linkPending,
		// Shown from the first frame when the relation or the host already decides it; a reason
		// that needs the related table waits for it (the picker frame holds its place meanwhile).
		blockedReason:
			!editable && (!modelsLoading || !relation.editable || Boolean(readOnlyReason))
				? capability.linkReason ?? capability.unlinkReason
				: null,
		links,
		current,
		selection,
		moveHint,
		search,
		setSearch,
		searchReason,
		candidates,
		saving,
		errors,
		notice,
		toggle,
		clear,
		save,
		discard,
		create: { blocked: createBlocked, plan, submit: submitCreate },
		junctionAction,
		openRecord,
		openRecordReason,
	};
}

/**
 * The full current link set of one row's hasOne, hasMany or manyToMany
 * relation, read page by page through a filtered query instead of the
 * capped nested list the grid row carries.
 *
 * - hasOne/hasMany: the related table, filtered by `keys[].remote` = this row's `keys[].local`.
 * - manyToMany: the junction table, filtered by `junction.left`, with the
 *   junction's own belongsTo relation to the related table for labels.
 */
import { useMemo } from 'react';

import type { RelationModel, TableModel } from '@constructive-io/data';

import {
	equalityFilter,
	hasLinkPatch,
	junctionLeftValues,
	junctionRightKey,
	junctionRightRecord,
	linkKey,
	type RecordValues,
} from './relation-keys';
import type { LinkedRecord } from './relation-changes';
import { useModelPages } from './use-model-pages';

export interface RelationLinks {
	/** Current links, in server order, as loaded so far. */
	links: LinkedRecord[];
	/** Every current link, or null when the server does not count them. */
	total: number | null;
	isLoading: boolean;
	isFetchingNextPage: boolean;
	hasNextPage: boolean;
	fetchNextPage: () => void;
	error: Error | null;
	/** False when the link set cannot be queried; `links` then come from the row itself. */
	queried: boolean;
	/** While loading: how many links the row itself already shows (its first page), to hold their space. */
	placeholderCount: number;
}

/** The junction's belongsTo relation that points at the related table through `junction.right`. */
export function junctionTargetRelation(relation: RelationModel, junction: TableModel): RelationModel | null {
	const right = relation.junction?.right ?? [];
	return (
		junction.relations.find(
			(candidate) =>
				candidate.kind === 'belongsTo' &&
				candidate.readable &&
				candidate.targetKey === relation.targetKey &&
				candidate.keys.length === right.length &&
				right.every((pair) => candidate.keys.some((key) => key.local === pair.junction && key.remote === pair.remote)),
		) ?? null
	);
}

function asRecords(value: unknown): RecordValues[] {
	if (!Array.isArray(value)) return value && typeof value === 'object' ? [value as RecordValues] : [];
	return value.filter((entry): entry is RecordValues => Boolean(entry) && typeof entry === 'object');
}

export function useRelationLinks(options: {
	relation: RelationModel;
	row: RecordValues | null;
	/** The value of the relation field on the row, used when the link set cannot be queried. */
	rowValue: unknown;
	target: TableModel | null;
	junction: TableModel | null;
	/** True while the related or junction table model is still loading. */
	modelsLoading: boolean;
	enabled: boolean;
}): RelationLinks {
	const { relation, row, rowValue, target, junction, modelsLoading, enabled } = options;
	const isJunction = relation.kind === 'manyToMany';
	const listModel = isJunction ? junction : target;

	const where = useMemo(() => {
		if (!row || !listModel) return null;
		const values = isJunction ? junctionLeftValues(relation, row) : hasLinkPatch(relation, row);
		return values ? equalityFilter(listModel, values) : null;
	}, [isJunction, listModel, relation, row]);

	const throughRelation = useMemo(
		() => (isJunction && junction ? junctionTargetRelation(relation, junction) : null),
		[isJunction, junction, relation],
	);

	const listed = enabled && relation.kind !== 'belongsTo';
	const queried = listed && Boolean(listModel && where);
	// Until the model that lists the links is known, show nothing rather than the capped
	// nested list: a link taken from it has no junction row, so it could not be removed.
	const waiting = listed && !listModel && modelsLoading;
	const pages = useModelPages({
		model: listModel,
		purpose: isJunction ? 'relation-junction-links' : 'relation-links',
		keyParts: [relation.fieldName],
		where,
		relations: throughRelation ? [throughRelation.fieldName] : undefined,
		enabled: queried,
	});

	const links = useMemo<LinkedRecord[]>(() => {
		if (waiting) return [];
		if (!queried) {
			return asRecords(rowValue).flatMap((record): LinkedRecord[] => {
				const key = linkKey(relation, record);
				return key ? [{ key, record, junctionRow: null }] : [];
			});
		}
		return pages.rows.flatMap((entry) => {
			if (!isJunction) {
				const key = linkKey(relation, entry);
				return key ? [{ key, record: entry }] : [];
			}
			const key = junctionRightKey(relation, entry);
			if (!key) return [];
			const nested = throughRelation ? entry[throughRelation.fieldName] : null;
			const record = nested && typeof nested === 'object'
				? { ...junctionRightRecord(relation, entry), ...(nested as RecordValues) }
				: junctionRightRecord(relation, entry);
			return [{ key, record, junctionRow: entry }];
		});
	}, [isJunction, pages.rows, queried, relation, rowValue, throughRelation, waiting]);

	return {
		links,
		total: queried ? pages.total : null,
		isLoading: waiting || (queried && pages.isLoading),
		isFetchingNextPage: pages.isFetchingNextPage,
		hasNextPage: queried && pages.hasNextPage,
		fetchNextPage: pages.fetchNextPage,
		error: queried ? pages.error : null,
		queried,
		placeholderCount: asRecords(rowValue).length,
	};
}

/**
 * The user's pending link choices in the relation editor, kept apart from
 * server state until Save. A single relation (belongsTo, hasOne) holds one
 * choice; a list relation (hasMany, manyToMany) holds the records to add and
 * the links to remove. Refused choices return the model's reason.
 */
import { useCallback, useMemo, useState } from 'react';

import type { RelationModel } from '@constructive-io/data';

import type { RelationEditCapability } from './relation-capability';
import type { LinkedRecord } from './relation-changes';
import { linkKey, type RecordValues } from './relation-keys';

export type LinkState = 'linked' | 'added' | 'removed';

export interface PendingLink extends LinkedRecord {
	state: LinkState;
}

export interface RelationSelection {
	/** One link (belongsTo, hasOne) or many (hasMany, manyToMany). */
	mode: 'single' | 'multi';
	/** Links as they will be after Save: current ones (some marked removed) and added ones. */
	pending: PendingLink[];
	/** Whether a record is linked after Save. */
	isSelected: (record: RecordValues) => boolean;
	/** Pick or unpick a record. Returns the reason when the model forbids it. */
	toggle: (record: RecordValues) => string | null;
	/** Single relation: remove the link. Returns the reason when the model forbids it. */
	clear: () => string | null;
	/** True when Save would write something. */
	dirty: boolean;
	/** Single relation: the chosen record (null to clear), or undefined when unchanged. */
	choice: RecordValues | null | undefined;
	/** List relation: records to link. */
	added: LinkedRecord[];
	/** List relation: links to remove. */
	removed: LinkedRecord[];
	/** Drop pending choices that the server now holds. */
	settle: (keys: ReadonlySet<string>) => void;
	/** Drop every pending choice. */
	reset: () => void;
}

const NO_KEY = 'This record has no value to link by.';

export function useRelationSelection(options: {
	relation: RelationModel;
	/** Current links from the server (or the row), first page first. */
	current: readonly LinkedRecord[];
	capability: RelationEditCapability;
	/** hasMany: true when a record already points at this row although its link is not loaded yet. */
	linkedHere?: (record: RecordValues) => boolean;
}): RelationSelection {
	const { relation, current, capability, linkedHere } = options;
	const mode = relation.kind === 'belongsTo' || relation.kind === 'hasOne' ? 'single' : 'multi';

	const [choice, setChoice] = useState<{ record: RecordValues | null } | null>(null);
	const [added, setAdded] = useState<ReadonlyMap<string, LinkedRecord>>(() => new Map());
	const [removed, setRemoved] = useState<ReadonlyMap<string, LinkedRecord>>(() => new Map());

	const currentByKey = useMemo(() => new Map(current.map((link) => [link.key, link])), [current]);
	const currentKey = current[0]?.key ?? null;
	const choiceKey = choice ? (choice.record ? linkKey(relation, choice.record) : null) : currentKey;

	const isLinkedNow = useCallback(
		(key: string, record: RecordValues) => currentByKey.has(key) || Boolean(linkedHere?.(record)),
		[currentByKey, linkedHere],
	);

	const isSelected = useCallback(
		(record: RecordValues) => {
			const key = linkKey(relation, record);
			if (!key) return false;
			if (mode === 'single') return key === choiceKey;
			return added.has(key) || (isLinkedNow(key, record) && !removed.has(key));
		},
		[added, choiceKey, isLinkedNow, mode, relation, removed],
	);

	const toggle = useCallback(
		(record: RecordValues): string | null => {
			const key = linkKey(relation, record);
			if (!key) return NO_KEY;
			if (mode === 'single') {
				if (key === choiceKey) {
					// Unpicking a new choice goes back to the current link; unpicking the current link clears it.
					if (choice) {
						setChoice(null);
						return null;
					}
					if (!capability.canUnlink) return capability.unlinkReason;
					setChoice({ record: null });
					return null;
				}
				if (!capability.canLink) return capability.linkReason;
				if (currentKey !== null && !capability.canUnlink && relation.kind === 'hasOne') return capability.unlinkReason;
				setChoice(key === currentKey ? null : { record });
				return null;
			}
			if (added.has(key)) {
				setAdded((map) => withoutKey(map, key));
				return null;
			}
			if (removed.has(key)) {
				setRemoved((map) => withoutKey(map, key));
				return null;
			}
			if (isLinkedNow(key, record)) {
				if (!capability.canUnlink) return capability.unlinkReason;
				const link = currentByKey.get(key) ?? { key, record, junctionRow: null };
				setRemoved((map) => withKey(map, key, link));
				return null;
			}
			if (!capability.canLink) return capability.linkReason;
			setAdded((map) => withKey(map, key, { key, record }));
			return null;
		},
		[added, capability, choice, choiceKey, currentByKey, currentKey, isLinkedNow, mode, relation, removed],
	);

	const clear = useCallback((): string | null => {
		if (choiceKey === null) return null;
		if (!capability.canUnlink) return capability.unlinkReason;
		setChoice(currentKey === null ? null : { record: null });
		return null;
	}, [capability, choiceKey, currentKey]);

	const settle = useCallback((keys: ReadonlySet<string>) => {
		setAdded((map) => withoutKeys(map, keys));
		setRemoved((map) => withoutKeys(map, keys));
		setChoice(null);
	}, []);

	const reset = useCallback(() => {
		setAdded(new Map());
		setRemoved(new Map());
		setChoice(null);
	}, []);

	const pending = useMemo<PendingLink[]>(() => {
		if (mode === 'single') {
			const now = current[0] ?? null;
			if (!choice) return now ? [{ ...now, state: 'linked' }] : [];
			const next = choice.record && choiceKey ? [{ key: choiceKey, record: choice.record, state: 'added' as const }] : [];
			return now ? [...next, { ...now, state: 'removed' }] : next;
		}
		return [
			...current.map((link) => ({ ...link, state: removed.has(link.key) ? ('removed' as const) : ('linked' as const) })),
			...[...removed.values()].filter((link) => !currentByKey.has(link.key)).map((link) => ({ ...link, state: 'removed' as const })),
			...[...added.values()].map((link) => ({ ...link, state: 'added' as const })),
		];
	}, [added, choice, choiceKey, current, currentByKey, mode, removed]);

	const dirty = mode === 'single' ? choice !== null && choiceKey !== currentKey : added.size + removed.size > 0;

	return {
		mode,
		pending,
		isSelected,
		toggle,
		clear,
		dirty,
		choice: choice ? choice.record : undefined,
		added: [...added.values()],
		removed: [...removed.values()],
		settle,
		reset,
	};
}

function withKey<T>(map: ReadonlyMap<string, T>, key: string, value: T): ReadonlyMap<string, T> {
	const next = new Map(map);
	next.set(key, value);
	return next;
}

function withoutKey<T>(map: ReadonlyMap<string, T>, key: string): ReadonlyMap<string, T> {
	const next = new Map(map);
	next.delete(key);
	return next;
}

function withoutKeys<T>(map: ReadonlyMap<string, T>, keys: ReadonlySet<string>): ReadonlyMap<string, T> {
	if (![...keys].some((key) => map.has(key))) return map;
	const next = new Map(map);
	for (const key of keys) next.delete(key);
	return next;
}

import {
	TableModelError,
	assessTableWriteCapability,
	resolveRowIdentity,
	rowIdentityToPrimaryKey,
	serializeRowIdentity,
	type MetaTable,
	type RowIdentityValue,
	type RowKey,
	type TableModel,
	type TableWriteCapability,
} from '@constructive-io/data';

/** A row locator accepted by Sheets CRUD operations. */
export type SheetsRowIdentifier =
	| string
	| number
	| Readonly<Record<string, RowIdentityValue>>;

export type SheetsMutationOperation = 'create' | 'update' | 'delete';

export type SheetsRowIdentityResolution =
	| Readonly<{
			status: 'identified';
			/** Backwards-compatible scalar for an ordinary `id` PK; otherwise the PK object. */
			identifier: SheetsRowIdentifier;
			/** GraphQL primary-key input, including renamed and composite keys. */
			primaryKey: Readonly<Record<string, RowIdentityValue>>;
			/** Stable, schema-qualified key used by caches, selection, and editors. */
			key: string;
	  }>
	| Readonly<{
			status: 'unavailable';
			reason: 'no-primary-key' | 'invalid-row';
	  }>;

function isLegacyScalarId(
	primaryKey: Readonly<Record<string, RowIdentityValue>>,
): primaryKey is Readonly<{ id: string | number }> {
	const entries = Object.entries(primaryKey);
	return (
		entries.length === 1 &&
		entries[0][0] === 'id' &&
		(typeof entries[0][1] === 'string' || typeof entries[0][1] === 'number')
	);
}

/**
 * Resolve one server row from `_meta`. The familiar scalar `id` contract is kept
 * for existing adapters, while renamed and composite keys use the full PK input.
 */
export function resolveSheetsRowIdentity(
	table: MetaTable,
	row: Readonly<Record<string, unknown>>,
): SheetsRowIdentityResolution {
	const resolution = resolveRowIdentity(table, row);
	if (resolution.status === 'read-only') {
		return { status: 'unavailable', reason: 'no-primary-key' };
	}
	if (resolution.status === 'invalid-row') {
		return { status: 'unavailable', reason: 'invalid-row' };
	}

	const primaryKey = rowIdentityToPrimaryKey(resolution.identity);
	return {
		status: 'identified',
		identifier: isLegacyScalarId(primaryKey) ? primaryKey.id : primaryKey,
		primaryKey,
		key: serializeRowIdentity(resolution.identity),
	};
}

/** Resolve a public CRUD identifier through the same `_meta` identity contract. */
export function resolveSheetsIdentifier(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): SheetsRowIdentityResolution {
	const row =
		typeof identifier === 'object' && identifier !== null
			? identifier
			: { id: identifier };
	return resolveSheetsRowIdentity(table, row);
}

/** Build the PostGraphile connection filter used by `findOne`. */
export function sheetsIdentifierToWhere(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): Record<string, { equalTo: RowIdentityValue }> | null {
	const resolution = resolveSheetsIdentifier(table, identifier);
	if (resolution.status !== 'identified') return null;
	return Object.fromEntries(
		Object.entries(resolution.primaryKey).map(([field, value]) => [field, { equalTo: value }]),
	);
}

/**
 * The primary-key values a model document needs. A scalar identifier is the
 * value of a one-field key, whatever that field is called; an object must
 * carry every key field.
 */
export function sheetsIdentifierToRowKey(model: TableModel, identifier: SheetsRowIdentifier): RowKey {
	if (typeof identifier === 'object' && identifier !== null) return identifier;
	if (model.primaryKey.length !== 1) {
		throw new TableModelError(
			'KEY_INCOMPLETE',
			model.primaryKey.length === 0
				? 'This table has no primary key, so its records cannot be changed.'
				: 'This table has a multi-field key; pass every key field.',
			{ tableKey: model.key },
		);
	}
	return { [model.primaryKey[0]!]: identifier };
}

/** Use scalar IDs as cache keys for compatibility; use serialized identities otherwise. */
export function sheetsIdentifierCacheKey(
	table: MetaTable,
	identifier: SheetsRowIdentifier,
): string | number | null {
	const resolution = resolveSheetsIdentifier(table, identifier);
	if (resolution.status !== 'identified') return null;
	return typeof resolution.identifier === 'object'
		? resolution.key
		: resolution.identifier;
}

/** Stable TanStack/selection/editor key with an index fallback only for non-writable rows. */
export function sheetsRowKey(
	table: MetaTable,
	row: Readonly<Record<string, unknown>>,
	index: number,
): string {
	const resolution = resolveSheetsRowIdentity(table, row);
	if (resolution.status === 'identified') {
		return typeof resolution.identifier === 'object'
			? resolution.key
			: String(resolution.identifier);
	}
	return `${table.schemaName ?? ''}:${table.name}:row:${index}`;
}

export function getSheetsWriteCapability(table: MetaTable | null): TableWriteCapability | null {
	return table ? assessTableWriteCapability(table) : null;
}

export function canRunSheetsMutation(
	capability: TableWriteCapability | null,
	operation: SheetsMutationOperation,
): boolean {
	if (!capability || capability.status !== 'mutable') return false;
	return capability.operations[operation];
}

export function assertSheetsMutationAllowed(
	table: MetaTable,
	operation: SheetsMutationOperation,
): void {
	const capability = assessTableWriteCapability(table);
	if (capability.status === 'read-only') {
		throw new Error(`Table '${table.name}' is read-only because it has no primary key.`);
	}
	if (!capability.operations[operation]) {
		const article = operation === 'update' ? 'an' : 'a';
		throw new Error(`Table '${table.name}' does not expose ${article} ${operation} mutation.`);
	}
}

/**
 * Range-value extractor — pulls the matrix of cell values covered by a
 * {@link SelectionRect} out of the (possibly virtualized) row array.
 *
 * PURE + SSR-safe — no React, no DOM. The BOUNDED contract is load-bearing: it
 * reads only the cells inside the rect (w×h), never enumerates `rows.length`, so
 * a paste/fill/copy targeting a few cells of a million-row grid stays O(w·h). An
 * unfetched proxy row (infinite-mode) reads as `null` -> its cells come back as
 * `null`; an out-of-range column reads as `null` too.
 *
 * Reused by P3 (paste/fill writes the same coordinate matrix back) and P4 (copy
 * serializes {@link toTSV}).
 */

import type { SelectionRect } from './selection-model';

/** The extracted block: a `values[row][col]` matrix plus the row indices + col keys it covers. */
export interface ExtractedRange {
	/** `values[r][c]` — outer index aligns with `rows[r]`, inner with `cols[c]`. */
	values: unknown[][];
	/** Absolute row indices covered (y .. y+height-1). */
	rows: number[];
	/** Column keys covered (columnKeys[x .. x+width-1]). */
	cols: string[];
}

/**
 * Read every cell inside `range` (half-open: x/width = cols, y/height = rows) from
 * `rows` keyed by `columnKeys`. `getDisplay`, when supplied, maps the raw value to
 * the value to emit (e.g. a display string for copy) — defaults to the raw value.
 * Null-safe for unfetched proxy rows and out-of-range columns.
 */
export function getCellsInRange(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
	getDisplay?: (value: unknown, rowIndex: number, colKey: string) => unknown,
): ExtractedRange {
	const cols: string[] = [];
	for (let c = 0; c < range.width; c++) {
		cols.push(columnKeys[range.x + c]);
	}

	const rowIndices: number[] = [];
	const values: unknown[][] = [];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		rowIndices.push(rowIndex);
		const rowData = rows[rowIndex] as Record<string, unknown> | null | undefined;
		const line: unknown[] = [];
		for (let c = 0; c < range.width; c++) {
			const colKey = cols[c];
			const raw = rowData && colKey != null ? rowData[colKey] : null;
			const cellValue = raw === undefined ? null : raw;
			line.push(getDisplay ? getDisplay(cellValue, rowIndex, colKey) : cellValue);
		}
		values.push(line);
	}

	return { values, rows: rowIndices, cols };
}

/** A cell holding a tab, a line break or a leading quote is quoted, as spreadsheets do. */
const NEEDS_QUOTES_RE = /[\t\n\r]|^"/;

function tsvCell(cell: unknown): string {
	if (cell == null) return '';
	const text = typeof cell === 'object' ? JSON.stringify(cell) : String(cell);
	return NEEDS_QUOTES_RE.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

/**
 * Serialize a value matrix to TSV (tab-joined cols, newline-joined rows). Each value
 * is stringified (an object as JSON); `null`/`undefined` become an empty cell. A cell
 * with a tab, a line break or a leading quote is quoted (`"two\nlines"`, inner quotes
 * doubled), so multi-line text survives a copy and paste. Spreadsheet-paste shape —
 * reused by P4 copy.
 */
export function toTSV(values: readonly (readonly unknown[])[]): string {
	return values.map((row) => row.map(tsvCell).join('\t')).join('\n');
}

/**
 * Fill-math — REPLICATE a source row/column across a target range (P4 Phase 3).
 *
 * PURE + SSR-safe (no React, no DOM) — the analog of {@link getCellsInRange} on the
 * WRITE side: it reads the seed cells out of the raw `rows` array (null-safe for
 * unfetched proxy rows / out-of-range columns, exactly like the extractor) and emits
 * the {@link CellWrite}[] the command hands to `commitCells` (readonly/UUID skips +
 * undo live inside that batch, never here).
 *
 * SCOPE — value REPLICATION only. Numeric/date SERIES detection (1,2 -> 3,4 ; Jan,Feb
 * -> Mar) is DEFERRED: every filled cell is a verbatim copy of the seed.
 */

import type { SelectionRect } from './selection-model';
import type { CellWrite } from '../grid/hooks/use-batch-commit';

/** Read one raw cell value, null-safe (mirrors getCellsInRange: undefined -> null). */
function readCell(rows: readonly unknown[], rowIndex: number, colKey: string): unknown {
	const rowData = rows[rowIndex] as Record<string, unknown> | null | undefined;
	const raw = rowData && colKey != null ? rowData[colKey] : null;
	return raw === undefined ? null : raw;
}

/**
 * Fill DOWN: SOURCE = the TOP row of `range` (y). For each col `x..x+width-1`, replicate
 * the seed cell value into every row `y+1..y+height-1`. Returns the writes column-major
 * is not required — emitted row-major (top-to-bottom within each... actually outer loop is
 * target rows, inner is cols) so commitCells coalesces per row. A single-row range yields
 * no writes (nothing below the seed).
 */
export function fillDownWrites(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	const sourceRow = range.y;
	for (let targetRow = range.y + 1; targetRow < range.y + range.height; targetRow++) {
		for (let c = 0; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex: targetRow, colKey, value: readCell(rows, sourceRow, colKey) });
		}
	}
	return writes;
}

/**
 * Fill RIGHT: SOURCE = the LEFT column of `range` (x). For each col `x+1..x+width-1`,
 * replicate that column's seed (the value in the LEFT column of the SAME row) rightward
 * across every row `y..y+height-1`. A single-column range yields no writes.
 */
export function fillRightWrites(
	range: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	const sourceColKey = columnKeys[range.x];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		const seed = sourceColKey == null ? null : readCell(rows, rowIndex, sourceColKey);
		for (let c = 1; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value: seed });
		}
	}
	return writes;
}

/**
 * Bulk-edit: FAN a single committed `value` across every cell of `range` (the classic
 * "select range, type, commit, fill" edit). Unlike fill-down/right this reads NO seed
 * out of the data — every cell in the range gets the SAME `value` (per-column coercion
 * happens downstream in commitCells/resolveServerPatch). The write set is the COMPLETE
 * range INCLUDING the active cell, so the caller does ONE commitCells (never a single
 * commit + a separate range commit) — no double-write, one optimistic patch, one undo.
 * Out-of-bounds column slots are skipped (mirrors the other fill writers).
 */
export function bulkEditWrites(
	range: SelectionRect,
	value: unknown,
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let r = 0; r < range.height; r++) {
		const rowIndex = range.y + r;
		for (let c = 0; c < range.width; c++) {
			const colKey = columnKeys[range.x + c];
			if (colKey == null) continue;
			writes.push({ rowIndex, colKey, value });
		}
	}
	return writes;
}

/**
 * Fill-handle DRAG geometry — extend `from` toward target cell `[col,row]` along the
 * DOMINANT axis (v1 supports one axis at a time). PURE.
 *
 * The axis is chosen by which direction the target overshoots `from` the most: if the
 * vertical overshoot (below the bottom / above the top) exceeds the horizontal one we
 * fill VERTICALLY (the rect's height grows); otherwise HORIZONTALLY (width grows). Ties
 * and a target already inside `from` collapse to `from` (no extension). The off-axis span
 * is left exactly as `from`'s.
 */
export function extendedFillRect(from: SelectionRect, target: readonly [number, number]): SelectionRect {
	const [col, row] = target;
	const bottom = from.y + from.height - 1;
	const right = from.x + from.width - 1;
	// Overshoot past the source band on each axis (0 when target is within the band).
	const vOver = row > bottom ? row - bottom : from.y - row > 0 ? from.y - row : 0;
	const hOver = col > right ? col - right : from.x - col > 0 ? from.x - col : 0;
	if (vOver === 0 && hOver === 0) return from;
	if (vOver >= hOver) {
		// Vertical fill: grow the height toward `row`, keep x/width.
		const y = Math.min(from.y, row);
		const yEnd = Math.max(bottom, row);
		return { x: from.x, y, width: from.width, height: yEnd - y + 1 };
	}
	// Horizontal fill: grow the width toward `col`, keep y/height.
	const x = Math.min(from.x, col);
	const xEnd = Math.max(right, col);
	return { x, y: from.y, width: xEnd - x + 1, height: from.height };
}

/**
 * Replicate the SOURCE band `from` across the NEW cells of `extended` (the cells in
 * `extended` that are NOT in `from`). For a vertical extension each new row copies the
 * matching column's value from the NEAREST source row (the band repeats); for a horizontal
 * extension each new column copies the matching row's nearest source column. Value
 * REPLICATION only — SERIES detection DEFERRED. Skips the `from` band (already populated).
 */
export function fillDragWrites(
	from: SelectionRect,
	extended: SelectionRect,
	rows: readonly unknown[],
	columnKeys: readonly string[],
): CellWrite[] {
	const writes: CellWrite[] = [];
	for (let ty = extended.y; ty < extended.y + extended.height; ty++) {
		for (let tx = extended.x; tx < extended.x + extended.width; tx++) {
			// Inside the source band — already has its value, never overwrite.
			if (tx >= from.x && tx < from.x + from.width && ty >= from.y && ty < from.y + from.height) continue;
			const colKey = columnKeys[tx];
			if (colKey == null) continue;
			// Tile the source band: map the target back into the band on each axis.
			const srcCol = from.x + ((tx - from.x) % from.width + from.width) % from.width;
			const srcRow = from.y + ((ty - from.y) % from.height + from.height) % from.height;
			const srcKey = columnKeys[srcCol];
			writes.push({ rowIndex: ty, colKey, value: srcKey == null ? null : readCell(rows, srcRow, srcKey) });
		}
	}
	return writes;
}

/**
 * RangeSet — the immutable selection primitive for the native (TanStack DOM)
 * grid. It replaces glide's `CompactSelection` for row selection state.
 *
 * Internal representation: a sorted, non-overlapping, NON-ADJACENT array of
 * `[start, end)` half-open ranges. Adjacency MERGES on touch (so `add([0,3))`
 * then `add([3,5))` collapses to a single `[0,5)`), keeping a 10k-row selection
 * O(#ranges) instead of O(#rows). Every mutator returns a NEW RangeSet; the
 * receiver is never mutated.
 *
 * Focused tests protect merging, splitting, offsets, and immutability without
 * freezing the obsolete grid implementation this class replaced.
 */

type Range = readonly [start: number, end: number];

/** Normalize the `number | [number, number]` arg to a half-open `[start, end)`. */
function toRange(i: number | [number, number]): Range {
	return typeof i === 'number' ? [i, i + 1] : [i[0], i[1]];
}

/** True when the range is empty/inverted (start >= end) and contributes nothing. */
function isEmptyRange([start, end]: Range): boolean {
	return start >= end;
}

/**
 * Insert `[s, e)` into a sorted, disjoint, non-adjacent range list, merging any
 * ranges it overlaps OR merely TOUCHES (touch = adjacency merge). Returns a new
 * sorted, disjoint, non-adjacent list.
 */
function insertRange(ranges: readonly Range[], [s, e]: Range): Range[] {
	const out: Range[] = [];
	let start = s;
	let end = e;
	let inserted = false;
	for (const [rs, re] of ranges) {
		if (re < start) {
			// Entirely before the new range (and not touching) — keep as-is.
			out.push([rs, re]);
		} else if (rs > end) {
			// Entirely after the new range (and not touching) — emit the merged
			// range once, then keep the rest.
			if (!inserted) {
				out.push([start, end]);
				inserted = true;
			}
			out.push([rs, re]);
		} else {
			// Overlaps or touches — widen the in-flight merged range.
			start = Math.min(start, rs);
			end = Math.max(end, re);
		}
	}
	if (!inserted) out.push([start, end]);
	return out;
}

/**
 * Subtract `[selMin, selMax)` from a sorted, disjoint range list, SPLITTING any
 * covering range (removing the middle of one yields two).
 *
 * This is a faithful port of glide `CompactSelection.remove`, including its two
 * documented quirks rather than a clean set difference:
 *
 *   1. Overlap test is `start <= selMax && selMin <= end` — both bounds `<=`, so
 *      a range touching the cut is "intersected" (usually a harmless in-place
 *      replace with an identical range).
 *   2. It SPLICES `items` in place while iterating with `items.entries()`, whose
 *      cursor just counts iterations (0,1,2,…) regardless of mutation. So when a
 *      range is fully consumed (`toAdd` empty), `splice(i, 1)` shrinks the array
 *      and the element that slides into slot `i` is SKIPPED — the next read is
 *      slot `i + 1`. A plain index loop over the MUTATED array reproduces this
 *      exactly: never re-align `i`. ("remove-spanning-three-ranges" depends on
 *      it — the range after a fully dropped middle range survives untouched.)
 */
function subtractRange(ranges: readonly Range[], [selMin, selMax]: Range): Range[] {
	const items: Range[] = ranges.map(([start, end]) => [start, end]);
	for (let i = 0; i < items.length; i++) {
		const [start, end] = items[i];
		if (start <= selMax && selMin <= end) {
			const toAdd: Range[] = [];
			if (start < selMin) toAdd.push([start, selMin]);
			if (selMax < end) toAdd.push([selMax, end]);
			items.splice(i, 1, ...toAdd);
		}
	}
	return items;
}

export class RangeSet {
	private readonly ranges: readonly Range[];

	private constructor(ranges: readonly Range[]) {
		this.ranges = ranges;
	}

	static empty(): RangeSet {
		return new RangeSet([]);
	}

	/** RESET to a single index `[i, i+1)` or a single `[start, end)` range. */
	static fromSingleSelection(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		return isEmptyRange(range) ? new RangeSet([]) : new RangeSet([range]);
	}

	/** Add an index/range; merges adjacent + overlapping ranges; contained = no-op. */
	add(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		if (isEmptyRange(range)) return this;
		return new RangeSet(insertRange(this.ranges, range));
	}

	/** Remove an index/range; SPLITS a covering range. */
	remove(i: number | [number, number]): RangeSet {
		const range = toRange(i);
		if (isEmptyRange(range)) return this;
		return new RangeSet(subtractRange(this.ranges, range));
	}

	/** Shift every range by `amount`. */
	offset(amount: number): RangeSet {
		if (amount === 0) return this;
		return new RangeSet(this.ranges.map(([start, end]) => [start + amount, end + amount]));
	}

	hasIndex(i: number): boolean {
		for (const [start, end] of this.ranges) {
			if (i >= start && i < end) return true;
		}
		return false;
	}

	/** Ascending expansion of every selected index. */
	toArray(): number[] {
		const out: number[] = [];
		for (const [start, end] of this.ranges) {
			for (let i = start; i < end; i++) out.push(i);
		}
		return out;
	}

	/** Total selected count — sum of `(end - start)` across ranges. */
	get length(): number {
		let total = 0;
		for (const [start, end] of this.ranges) total += end - start;
		return total;
	}

	/** Lowest selected index, or `undefined` when empty. */
	first(): number | undefined {
		return this.ranges.length === 0 ? undefined : this.ranges[0][0];
	}

	/** Highest selected index, or `undefined` when empty. */
	last(): number | undefined {
		if (this.ranges.length === 0) return undefined;
		return this.ranges[this.ranges.length - 1][1] - 1;
	}
}

/**
 * SheetsSelection — the native (TanStack DOM) selection value that replaces
 * glide's `GridSelection`. It is the canonical selection state for the new grid;
 * glide's `GridSelection` is only a derived projection (see `glide-projection.ts`)
 * kept alive for the still-drawing canvas during the phased port.
 *
 * Shape mirrors the slice of glide the grid actually reads/round-trips:
 *   - `rows`    — selected ROW indices (a {@link RangeSet}; the only thing
 *                 production consumes via `.toArray()` / `.length`).
 *   - `columns` — selected COLUMN indices. Nothing consumes it today; it exists
 *                 solely so the glide projection has a faithful slot. Stays empty.
 *   - `current` — the active cell + optional active range (glide's `current.cell`
 *                 + `current.range`). The canvas keyboard-nav cursor depends on it,
 *                 so the projection must preserve it round-trip.
 *
 * The interaction helpers below are PURE and own the click logic glide used to
 * own internally (plain/ctrl/shift row clicks). They operate on ROW indices.
 *
 * NOTE — anchor tracking for shift-click is NOT stored here: `selectRange` takes
 * the anchor as an argument, so the caller (the reducer / interaction layer) owns
 * "where the last plain click landed". This keeps the model a pure value with no
 * hidden interaction state.
 */

import { RangeSet } from './range-set';

/** A half-open active range in cell coordinates (mirrors glide's `Rectangle`). */
export interface SelectionRect {
	x: number;
	y: number;
	width: number;
	height: number;
}

/** The active cell (and optional active range) — glide's `current`, trimmed. */
export interface SelectionCurrent {
	/** `[col, row]` — mirrors glide's `Item` ordering. */
	cell: [number, number];
	/** Active range; absent for a bare single-cell cursor. */
	range?: SelectionRect;
}

export interface SheetsSelection {
	current?: SelectionCurrent;
	rows: RangeSet;
	columns: RangeSet;
}

/** The zero value — no rows, no columns, no active cell. */
export const emptySheetsSelection: SheetsSelection = {
	rows: RangeSet.empty(),
	columns: RangeSet.empty()
};

/**
 * Plain row click: REPLACE the row selection with just `index` and park the
 * active cell on that row (column 0). Columns are left empty.
 */
export function selectRow(sel: SheetsSelection, index: number): SheetsSelection {
	return {
		current: { cell: [0, index] },
		rows: RangeSet.fromSingleSelection(index),
		columns: sel.columns
	};
}

/**
 * Ctrl/cmd row click: TOGGLE `index` in the existing row selection (add when
 * absent, remove when present). The active cell follows the touched row.
 */
export function toggleRow(sel: SheetsSelection, index: number): SheetsSelection {
	const rows = sel.rows.hasIndex(index) ? sel.rows.remove(index) : sel.rows.add(index);
	return {
		current: { cell: [0, index] },
		rows,
		columns: sel.columns
	};
}

/**
 * Shift row click: REPLACE the row selection with the contiguous block spanning
 * `anchor`..`index` (inclusive, either order). The active cell follows `index`.
 */
export function selectRange(sel: SheetsSelection, anchor: number, index: number): SheetsSelection {
	const min = Math.min(anchor, index);
	const max = Math.max(anchor, index);
	return {
		current: { cell: [0, index] },
		rows: RangeSet.fromSingleSelection([min, max + 1]),
		columns: sel.columns
	};
}

/** Clear everything back to the empty selection. */
export function clear(_sel: SheetsSelection): SheetsSelection {
	return emptySheetsSelection;
}

/** Clamp `n` into the inclusive `[min, max]` range. */
function clamp(n: number, min: number, max: number): number {
	return Math.max(min, Math.min(max, n));
}

/**
 * Park the active cell on `[col, row]`, dropping any prior active range. PRESERVES
 * `rows` and `columns` — cell navigation must NOT touch the row-checkbox selection
 * that drives delete/export.
 */
export function selectCell(sel: SheetsSelection, col: number, row: number): SheetsSelection {
	return { ...sel, current: { cell: [col, row] } };
}

/**
 * Extend the active range from an anchor cell to `[col, row]`. The active cell
 * becomes `[col, row]`; `current.range` is a normalized HALF-OPEN {@link SelectionRect}
 * spanning anchor..target in either order. PRESERVES `rows` and `columns`.
 */
export function extendRangeToCell(
	sel: SheetsSelection,
	col: number,
	row: number,
	anchorCol: number,
	anchorRow: number,
): SheetsSelection {
	return {
		...sel,
		current: {
			cell: [col, row],
			range: {
				x: Math.min(col, anchorCol),
				y: Math.min(row, anchorRow),
				width: Math.abs(col - anchorCol) + 1,
				height: Math.abs(row - anchorRow) + 1,
			},
		},
	};
}

/**
 * Select the WHOLE grid as a single cell range (Ctrl/Cmd+A). `current.range` is ONE
 * rect spanning every column/row and `current.cell` parks at `[0, 0]`; `rows`/`columns`
 * are untouched. Coordinate-only — NEVER enumerates rows (the infinite row-model is
 * O(totalCount)), so a million-row grid stays a single interval.
 */
export function selectAllCells(sel: SheetsSelection, colCount: number, rowCount: number): SheetsSelection {
	return {
		...sel,
		current: { cell: [0, 0], range: { x: 0, y: 0, width: colCount, height: rowCount } },
	};
}

/**
 * Move the active cell by `[dCol, dRow]`, clamped to the grid bounds. Starts from
 * `[0, 0]` when no active cell exists. Drops any prior range; PRESERVES rows/columns.
 */
export function moveActive(
	sel: SheetsSelection,
	dCol: number,
	dRow: number,
	colCount: number,
	rowCount: number,
): SheetsSelection {
	const base = sel.current?.cell ?? [0, 0];
	const col = clamp(base[0] + dCol, 0, colCount - 1);
	const row = clamp(base[1] + dRow, 0, rowCount - 1);
	return selectCell(sel, col, row);
}

/**
 * Pure nav-key resolver for the extended spreadsheet keys (Tab/Home/End + their
 * Ctrl/Cmd variants + PageUp/PageDown). Returns the NEW `[col, row]` target clamped
 * to grid bounds, or `null` when the key is not one of these moves (Arrow keys and
 * Enter/F2 are handled separately). `base` is the current active cell, `pageRows` is
 * the row span of one visible page (PageUp/Dn). Coordinate-only — never enumerates rows.
 */
export function computeKeyNavTarget(
	key: string,
	mods: { ctrlOrMeta: boolean; shift: boolean },
	base: [number, number],
	colCount: number,
	rowCount: number,
	pageRows: number,
): [number, number] | null {
	const [col, row] = base;
	const lastCol = colCount - 1;
	const lastRow = rowCount - 1;

	switch (key) {
		case 'Tab': {
			if (mods.shift) {
				// col-1; before col 0 wrap to the last col of the previous row. Clamp at grid start.
				if (col > 0) return [col - 1, row];
				if (row > 0) return [lastCol, row - 1];
				return [0, 0];
			}
			// col+1; past the last col wrap to col 0 of the next row. Clamp at grid end.
			if (col < lastCol) return [col + 1, row];
			if (row < lastRow) return [0, row + 1];
			return [lastCol, lastRow];
		}
		case 'Home':
			return mods.ctrlOrMeta ? [0, 0] : [0, row];
		case 'End':
			return mods.ctrlOrMeta ? [lastCol, lastRow] : [lastCol, row];
		case 'PageUp':
			return [col, clamp(row - pageRows, 0, lastRow)];
		case 'PageDown':
			return [col, clamp(row + pageRows, 0, lastRow)];
		default:
			return null;
	}
}

/**
 * TSV parse + tile — the INVERSE of {@link toTSV} (cell-extract.ts), used by the
 * clipboard.paste command. PURE + SSR-safe (no React, no DOM, no clipboard).
 *
 * `parseTSV` round-trips a `toTSV` string back into a `string[][]` matrix (split rows
 * on `\n`, cols on `\t`), tolerating ONE trailing newline (a spreadsheet copy ends the
 * last row with `\n`) so it does not yield a spurious empty trailing row. `tileMatrix`
 * implements spreadsheet fill semantics: a 1×N / N×1 source REPEATS to fill a larger
 * target, otherwise the source is written from the anchor as-is.
 */

/**
 * Parse a TSV string into a `string[][]` matrix (rows × cols). Splits rows on `\n`
 * (a lone trailing `\n` is dropped so it does not add an empty row) and cols on `\t`.
 * `\r` is stripped so a CRLF clipboard payload parses the same as LF. An empty string
 * yields a single empty cell `[['']]` (mirrors a 1×1 blank paste).
 */
export function parseTSV(text: string): string[][] {
	const normalized = text.replace(/\r\n?/g, '\n');
	// Drop a single trailing newline so a spreadsheet copy's terminal `\n` is not an extra row.
	const body = normalized.endsWith('\n') ? normalized.slice(0, -1) : normalized;
	if (!body.includes('"')) return body.split('\n').map((line) => line.split('\t'));
	return parseQuotedTSV(body);
}

/**
 * Parse TSV whose cells may be quoted, as spreadsheets write a cell holding a tab, a
 * line break or a quote: `"two\nlines"` is one cell, `""` inside quotes is one quote.
 * A quote that does not open a cell is an ordinary character.
 */
function parseQuotedTSV(body: string): string[][] {
	const rows: string[][] = [];
	let row: string[] = [];
	let cell = '';
	let index = 0;
	let cellStart = true;
	while (index < body.length) {
		const char = body[index];
		if (cellStart && char === '"') {
			// Quoted cell: read to the closing quote, unescaping doubled quotes.
			index += 1;
			while (index < body.length) {
				if (body[index] === '"') {
					if (body[index + 1] === '"') {
						cell += '"';
						index += 2;
						continue;
					}
					index += 1;
					break;
				}
				cell += body[index];
				index += 1;
			}
			cellStart = false;
			continue;
		}
		cellStart = false;
		if (char === '\t') {
			row.push(cell);
			cell = '';
			cellStart = true;
		} else if (char === '\n') {
			row.push(cell);
			rows.push(row);
			row = [];
			cell = '';
			cellStart = true;
		} else {
			cell += char;
		}
		index += 1;
	}
	row.push(cell);
	rows.push(row);
	return rows;
}

/**
 * Tile `source` to fill a `targetW × targetH` region (spreadsheet fill semantics):
 *   • a 1×N source (single row) repeats DOWN to fill targetH rows.
 *   • an N×1 source (single col) repeats ACROSS to fill targetW cols.
 *   • a 1×1 source repeats in both axes.
 *   • any other (genuinely 2-D) source is returned unchanged — the caller writes it
 *     from the anchor as-is (no tiling), matching spreadsheet "paste block" behavior.
 *
 * Only repeats when the source is strictly smaller than the target on the repeating
 * axis; a source already >= the target is left intact (clamping is the caller's job).
 */
export function tileMatrix(source: string[][], targetW: number, targetH: number): string[][] {
	const srcH = source.length;
	const srcW = srcH > 0 ? source[0].length : 0;
	if (srcH === 0 || srcW === 0) return source;

	const isSingleRow = srcH === 1;
	const isSingleCol = srcW === 1;
	// Only 1×N / N×1 (and 1×1) sources tile; a real 2-D block pastes as-is.
	if (!isSingleRow && !isSingleCol) return source;

	const outH = isSingleRow && targetH > srcH ? targetH : srcH;
	const outW = isSingleCol && targetW > srcW ? targetW : srcW;

	const out: string[][] = [];
	for (let r = 0; r < outH; r++) {
		const srcRow = source[r % srcH];
		const line: string[] = [];
		for (let c = 0; c < outW; c++) {
			line.push(srcRow[c % srcW]);
		}
		out.push(line);
	}
	return out;
}

import type { RelationInfo } from './relation-info-slice';

type DraftRowStatus = 'idle' | 'saving' | 'error';

export interface DraftRow {
  id: string;
  values: Record<string, unknown>;
  status: DraftRowStatus;
  errors: Record<string, string> | null;
  createdAt: number;
  metaVersion: string;
}

interface DraftRowsTableState {
  order: string[];
  map: Record<string, DraftRow>;
  template: Record<string, unknown>;
  metaVersion: string;
  columnOrder: string[];
}

export function parseDraftTableKey(tableKey: string): { databaseId: string | null; tableName: string } | null {
  const parts = tableKey.split('::');
  if (parts.length === 2) {
    const [databaseId, tableName] = parts;
    if (!databaseId || !tableName) return null;
    return { databaseId, tableName };
  }
  return null;
}

export interface DraftRowCreationArgs {
  tableKey: string;
  columnOrder: readonly string[];
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>;
  relationInfoByKey?: Record<string, RelationInfo | undefined>;
  metaVersion: string;
}

export type DraftRowsSyncArgs = DraftRowCreationArgs;

export interface DraftRowUpdateArgs {
  tableKey: string;
  draftRowId: string;
  columnKey: string;
  value: unknown;
  extraValues?: Record<string, unknown>;
}

export interface DraftRowsSlice {
  draftRowsByTable: Record<string, DraftRowsTableState | undefined>;
  createDraftRow: (args: DraftRowCreationArgs) => string;
  updateDraftCell: (args: DraftRowUpdateArgs) => void;
  removeDraftRow: (tableKey: string, draftRowId: string) => void;
  clearDraftRowsForTable: (tableKey: string) => void;
  clearDraftRowsForDatabase: (databaseId: string) => void;
  clearAllDraftRows: () => void;
  syncDraftRowsWithMeta: (args: DraftRowsSyncArgs) => void;
  setDraftRowStatus: (args: {
    tableKey: string;
    draftRowId: string;
    status: DraftRowStatus;
    errors?: Record<string, string> | null;
  }) => void;
}

type DraftFieldMetadata = {
  name?: string | null;
  isNotNull?: boolean | null;
  hasDefault?: boolean | null;
  type?: {
    gqlType?: string | null;
    isArray?: boolean | null;
    pgAlias?: string | null;
    pgType?: string | null;
    subtype?: string | null;
  } | null;
};

type DraftRowsSetState = (
	partial: Partial<DraftRowsSlice> | ((state: DraftRowsSlice) => Partial<DraftRowsSlice> | DraftRowsSlice),
) => void;

export function createDraftRowsSlice(set: DraftRowsSetState): DraftRowsSlice {
	return {
    draftRowsByTable: {},

    createDraftRow: (args) => {
      const { tableKey, columnOrder, fieldMetaByKey, relationInfoByKey, metaVersion } = args;

      const effectiveColumnOrder = ensureColumnOrder(columnOrder, fieldMetaByKey, relationInfoByKey);
      const template = buildTemplate(effectiveColumnOrder, relationInfoByKey);
      const draftRowId = `draft:${generateDraftSuffix()}`;
      const values = initializeValuesFromTemplate(template);

      set((state: DraftRowsSlice) => {
        const existing = state.draftRowsByTable[tableKey];

        const nextOrder = existing ? [...existing.order, draftRowId] : [draftRowId];
	        const nextMap: Record<string, DraftRow> = {
	          ...(existing?.map ?? {}),
          [draftRowId]: {
            id: draftRowId,
            values,
            status: 'idle' as const,
            errors: null,
            createdAt: Date.now(),
            metaVersion,
          },
        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              order: nextOrder,
              map: nextMap,
              template,
              metaVersion,
              columnOrder: [...effectiveColumnOrder],
            },
          },
        };
      });

      return draftRowId;
    },

	    updateDraftCell: ({ tableKey, draftRowId, columnKey, value, extraValues }) => {
	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        if (!tableState) return state;

	        const existingRow = tableState.map[draftRowId];
	        if (!existingRow) return state;

	        let hasValueChanges = !deepEqual(existingRow.values[columnKey], value);
	        if (!hasValueChanges && extraValues) {
	          for (const [key, extraValue] of Object.entries(extraValues)) {
	            if (!deepEqual(existingRow.values[key], extraValue)) {
	              hasValueChanges = true;
	              break;
	            }
	          }
	        }

	        const shouldResetErrors = existingRow.status === 'error' || existingRow.errors !== null;
	        if (!hasValueChanges && !shouldResetErrors) return state;

	        const updatedValues = hasValueChanges ? { ...existingRow.values, [columnKey]: deepClone(value) } : existingRow.values;
	        if (hasValueChanges && extraValues) {
	          for (const [key, extraValue] of Object.entries(extraValues)) {
	            updatedValues[key] = deepClone(extraValue);
	          }
	        }

	        const nextMap: Record<string, DraftRow> = {
	          ...tableState.map,
          [draftRowId]: {
            ...existingRow,
            values: updatedValues,
            status: existingRow.status === 'error' ? ('idle' as const) : existingRow.status,
            errors: null,
          },
        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              ...tableState,
              map: nextMap,
            },
          },
        };
      });
    },

    removeDraftRow: (tableKey, draftRowId) => {
      set((state: DraftRowsSlice) => {
        const tableState = state.draftRowsByTable[tableKey];
        if (!tableState) return state;
        if (!tableState.map[draftRowId]) return state;

        const nextOrder = tableState.order.filter((id) => id !== draftRowId);
        const nextMap = { ...tableState.map };
        delete nextMap[draftRowId];

        const nextTableState: DraftRowsTableState | undefined = nextOrder.length
          ? { ...tableState, order: nextOrder, map: nextMap }
          : undefined;

        const nextByTable = { ...state.draftRowsByTable };
        if (nextTableState) {
          nextByTable[tableKey] = nextTableState;
        } else {
          delete nextByTable[tableKey];
        }

        return { draftRowsByTable: nextByTable };
      });
    },

    clearDraftRowsForTable: (tableKey) => {
      set((state: DraftRowsSlice) => {
        if (!state.draftRowsByTable[tableKey]) return state;
        const nextByTable = { ...state.draftRowsByTable };
        delete nextByTable[tableKey];
        return { draftRowsByTable: nextByTable };
      });
    },

    clearDraftRowsForDatabase: (databaseId) => {
      set((state: DraftRowsSlice) => {
        if (!databaseId || !Object.keys(state.draftRowsByTable).length) return state;
        let changed = false;
        const nextByTable: Record<string, DraftRowsTableState | undefined> = { ...state.draftRowsByTable };

        for (const tableKey of Object.keys(nextByTable)) {
          const parsed = parseDraftTableKey(tableKey);
          const matchesDatabase = parsed ? parsed.databaseId === databaseId : tableKey.includes(`${databaseId}::`);

          if (matchesDatabase) {
            delete nextByTable[tableKey];
            changed = true;
          }
        }

        return changed ? { draftRowsByTable: nextByTable } : state;
      });
    },

    clearAllDraftRows: () => {
      set((state: DraftRowsSlice) => {
        if (!Object.keys(state.draftRowsByTable).length) return state;
        return { draftRowsByTable: {} };
      });
    },

	    syncDraftRowsWithMeta: (args) => {
	      const { tableKey, columnOrder, fieldMetaByKey, relationInfoByKey, metaVersion } = args;

	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        const effectiveColumnOrder = ensureColumnOrder(columnOrder, fieldMetaByKey, relationInfoByKey);
	        const template = buildTemplate(effectiveColumnOrder, relationInfoByKey);

	        if (!tableState) {
	          return state;
	        }

	        if (tableState.order.length === 0) {
	          const nextByTable = { ...state.draftRowsByTable };
	          delete nextByTable[tableKey];
	          return { draftRowsByTable: nextByTable };
	        }

	        const isSameMeta =
	          tableState.metaVersion === metaVersion && shallowEqualArrays(tableState.columnOrder, effectiveColumnOrder);

        if (isSameMeta) return state;

        const nextMap: Record<string, DraftRow> = {};
        for (const draftId of tableState.order) {
          const row = tableState.map[draftId];
          if (!row) continue;

          const mergedValues: Record<string, unknown> = initializeValuesFromTemplate(template);
          for (const key of Object.keys(row.values)) {
            if (Object.prototype.hasOwnProperty.call(template, key)) {
              mergedValues[key] = deepClone(row.values[key]);
            }
          }

          nextMap[draftId] = {
            ...row,
            values: mergedValues,
            metaVersion,
            status: row.status === 'error' ? 'idle' as const : row.status,
            errors: row.status === 'error' ? null : row.errors,
          };
        }

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: {
              order: [...tableState.order],
              map: nextMap,
              template,
              metaVersion,
              columnOrder: [...effectiveColumnOrder],
            },
          },
        };
      });
    },

	    setDraftRowStatus: ({ tableKey, draftRowId, status, errors }) => {
	      set((state: DraftRowsSlice) => {
	        const tableState = state.draftRowsByTable[tableKey];
	        if (!tableState) return state;
	        const row = tableState.map[draftRowId];
	        if (!row) return state;
	        const nextErrors = errors ?? null;
	        if (row.status === status && shallowEqualRecords(row.errors, nextErrors)) return state;

	        const nextMap: Record<string, DraftRow> = {
	          ...tableState.map,
	          [draftRowId]: { ...row, status, errors: nextErrors },
	        };

        return {
          draftRowsByTable: {
            ...state.draftRowsByTable,
            [tableKey]: { ...tableState, map: nextMap },
          },
        };
      });
    },
  };
}

function ensureColumnOrder(
  columnOrder: readonly string[],
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>,
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): string[] {
  if (columnOrder.length > 0) return [...columnOrder];

  const keys = new Set<string>();
  Object.keys(fieldMetaByKey).forEach((key) => {
    if (key) keys.add(key);
  });
  if (relationInfoByKey) {
    Object.keys(relationInfoByKey).forEach((key) => {
      if (key) keys.add(key);
    });
  }
  return Array.from(keys).sort((a, b) => a.localeCompare(b));
}

function buildTemplate(
  columnOrder: readonly string[],
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): Record<string, unknown> {
  const template: Record<string, unknown> = {};

  for (const column of columnOrder) {
    if (!column) continue;
    const relationInfo = relationInfoByKey?.[column];

    if (relationInfo && (relationInfo.kind === 'hasMany' || relationInfo.kind === 'manyToMany')) {
      template[column] = [];
    } else {
      // Untouched: the key exists (so a meta sync keeps the cell) but holds no value, so
      // the create leaves it out and the database default applies. A value the user set,
      // null and '' included, is sent as given.
      template[column] = undefined;
    }
  }

  return template;
}

function generateDraftSuffix(): string {
  const cryptoObj = typeof globalThis !== 'undefined' ? (globalThis as any).crypto : undefined;
  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    const buffer = new Uint32Array(1);
    cryptoObj.getRandomValues(buffer);
    return buffer[0].toString(36).slice(0, 8);
  }
  return Math.random().toString(36).slice(2, 10);
}

// A draft row is identified by its DraftMeta (`draftRowId`), never by a value: every
// column starts empty, so a key column the user must type (a key with no default)
// is an ordinary editable cell and is sent on create.
function initializeValuesFromTemplate(template: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(template)) {
    result[key] = deepClone(value);
  }
  return result;
}

function deepClone<T>(value: T): T {
  if (Array.isArray(value)) return value.map((item) => deepClone(item)) as unknown as T;
  if (value instanceof Date) return new Date(value.getTime()) as unknown as T;
  if (value && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(value as Record<string, unknown>)) {
      result[key] = deepClone(val);
    }
    return result as unknown as T;
  }
	return value;
}

function deepEqual(a: unknown, b: unknown): boolean {
	if (Object.is(a, b)) return true;
	if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();
	if (Array.isArray(a) && Array.isArray(b)) {
		if (a.length !== b.length) return false;
		for (let i = 0; i < a.length; i += 1) {
			if (!deepEqual(a[i], b[i])) return false;
		}
		return true;
	}
	if (a && b && typeof a === 'object' && typeof b === 'object') {
		const keysA = Object.keys(a as Record<string, unknown>);
		const keysB = Object.keys(b as Record<string, unknown>);
		if (keysA.length !== keysB.length) return false;
		for (const key of keysA) {
			if (!(key in (b as Record<string, unknown>))) return false;
			if (!deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key])) return false;
		}
		return true;
	}
	return false;
}

function shallowEqualRecords(
	a: Record<string, string> | null,
	b: Record<string, string> | null,
): boolean {
	if (a === b) return true;
	if (!a || !b) return false;
	const keysA = Object.keys(a);
	const keysB = Object.keys(b);
	if (keysA.length !== keysB.length) return false;
	for (const key of keysA) {
		if (a[key] !== b[key]) return false;
	}
	return true;
}

function shallowEqualArrays(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

export function computeDraftMetaSignature(
  columnOrder: readonly string[],
  fieldMetaByKey: Record<string, DraftFieldMetadata | undefined>,
  relationInfoByKey?: Record<string, RelationInfo | undefined>,
): string {
  const signatureParts = columnOrder.map((column) => {
    const typeMeta = fieldMetaByKey[column]?.type;
    const relationMeta = relationInfoByKey?.[column];

    const typePart = typeMeta
      ? [
          typeMeta.gqlType ?? '',
          typeMeta.isArray ? '1' : '0',
          typeMeta.pgAlias ?? '',
          typeMeta.pgType ?? '',
          typeMeta.subtype ?? '',
        ].join(':')
      : '';

    const relationPart = relationMeta
      ? [relationMeta.kind ?? '', relationMeta.foreignKeyField ?? '', relationMeta.relationField ?? ''].join(':')
      : '';

    return `${column}|${typePart}|${relationPart}`;
  });

  return hashString(signatureParts.join('||'));
}

function hashString(input: string): string {
  let hash = 0;
  for (let i = 0; i < input.length; i += 1) {
    hash = (hash << 5) - hash + input.charCodeAt(i);
    hash |= 0;
  }
  return hash.toString(16);
}

import type { RelationModel, TableModel } from '@constructive-io/data';

import { gridRelations } from '../relations/relation-columns';

export type RelationKind = 'belongsTo' | 'hasOne' | 'hasMany' | 'manyToMany';

/**
 * Per-column relation facts for cell routing, draft rows and draft submission.
 * Built from the table model by {@link relationInfoFromModel}; `relation` is the
 * model's relation itself and is the source of truth for keys and labels.
 */
export interface RelationInfo {
  kind: RelationKind;
  /** GraphQL type name of the related table. */
  relatedTable?: string;
  /** Fields that label a related record (the related table's display rule). */
  displayCandidates: string[];
  /** The relation field on the row. */
  relationField?: string;
  /** belongsTo only: the local key field this entry stands for (on the relation entry, the first one). */
  foreignKeyField?: string;
  /** The relation model behind this entry. */
  relation?: RelationModel;
}

/**
 * Relation entries per column key, from the table model: one entry per relation
 * column the grid shows, plus one per local key field of a shown belongsTo (so a
 * draft submission sends those fields and skips the relation field). Derived, not
 * cached: a new model (after a `_meta` refetch) gives new entries.
 */
export function relationInfoFromModel(model: TableModel | null | undefined): Map<string, RelationInfo> {
  const info = new Map<string, RelationInfo>();
  if (!model) return info;
  for (const relation of gridRelations(model)) {
    const base = {
      kind: relation.kind,
      relatedTable: relation.targetName,
      displayCandidates: [...relation.target.labelFields],
      relationField: relation.fieldName,
      relation,
    };
    if (relation.kind !== 'belongsTo') {
      info.set(relation.fieldName, base);
      continue;
    }
    info.set(relation.fieldName, { ...base, foreignKeyField: relation.keys[0]?.local });
    for (const pair of relation.keys) {
      if (!info.has(pair.local)) info.set(pair.local, { ...base, foreignKeyField: pair.local });
    }
  }
  return info;
}

import { createContext, useContext } from 'react';
import { createStore, useStore as useZustandStore, type StoreApi } from 'zustand';

import { createDraftRowsSlice, type DraftRowsSlice } from './draft-rows-slice';

export interface SheetsAuthState {
  isAuthenticated: boolean;
  accessToken: string | null;
  expiresAt: string | null;
  identityKey: string | null;
  setAuthenticated: (token: string, expiresAt: string, identityKey?: string | null) => void;
  setUnauthenticated: () => void;
}

export type SheetsStoreState = DraftRowsSlice & SheetsAuthState;

export function createSheetsStore(): StoreApi<SheetsStoreState> {
  return createStore<SheetsStoreState>((set) => ({
    // Draft rows
    ...createDraftRowsSlice(set),

    // Auth state (standalone mode)
    isAuthenticated: false,
    accessToken: null,
    expiresAt: null,
    identityKey: null,
    setAuthenticated: (token: string, expiresAt: string, identityKey = null) =>
      set({ isAuthenticated: true, accessToken: token, expiresAt, identityKey }),
    setUnauthenticated: () => set({ isAuthenticated: false, accessToken: null, expiresAt: null, identityKey: null }),
  }));
}

export const SheetsStoreContext = createContext<StoreApi<SheetsStoreState> | null>(null);

export function useSheetsStore<T>(selector: (state: SheetsStoreState) => T): T {
  const store = useContext(SheetsStoreContext);
  if (!store) {
    throw new Error('useSheetsStore must be used within a <SheetsProvider>');
  }
  return useZustandStore(store, selector);
}

export function useSheetsStoreApi(): StoreApi<SheetsStoreState> {
  const store = useContext(SheetsStoreContext);
  if (!store) {
    throw new Error('useSheetsStoreApi must be used within a <SheetsProvider>');
  }
  return store;
}

/**
 * Column widths that fill the grid.
 *
 * When the shown columns are narrower than the grid, the spare width goes to the
 * columns the user has not resized, in proportion to their widths, so the last
 * column ends at the grid's right edge (the rounding remainder goes to the last
 * flexible column). Narrow kinds (a checkbox, a number) keep their width while a
 * wider kind (text, a date, a list, a link) can take the space, and share it only
 * when nothing else can grow. A column the user resized keeps its width, and so do
 * frozen columns unless every column is frozen. When no column may grow, the columns
 * keep their widths and `filler` says how much empty width is left for an inert
 * filler. Columns wider than the grid are returned unchanged (the grid scrolls).
 *
 * A frozen column the user has not resized takes at most 40% of a narrow grid (and no
 * less than 96 px), so a long key such as a UUID does not cover a phone screen while
 * the other columns scroll under it.
 *
 * The result is for display only: it is never stored, so a saved view keeps the
 * widths the user chose, not the widths one window size produced.
 */

export interface ColumnFillInput {
	/** Each shown column's width before filling (the user's width, else its default), in display order. */
	widths: readonly number[];
	/** True for a column that keeps its width: the user resized it. */
	fixed: readonly boolean[];
	/** True for a column frozen at the start: it keeps its width unless every column is frozen. */
	frozen: readonly boolean[];
	/** True for a narrow kind (a checkbox, a number): it grows only when no other column can. */
	narrow: readonly boolean[];
	/** The width the columns may take: the grid's inner width without the row marker. */
	available: number;
}

export interface ColumnFill {
	/** The widths to draw. The input array itself when nothing changes. */
	widths: readonly number[];
	/** Empty width after the last column when no column may grow, else 0. */
	filler: number;
}

/**
 * The columns that may grow, by preference: unresized, unfrozen columns of a wide kind;
 * else every unresized, unfrozen column; else, when every column is frozen, every
 * unresized column.
 */
function flexibleColumns({ fixed, frozen, narrow }: Pick<ColumnFillInput, 'fixed' | 'frozen' | 'narrow'>, count: number): number[] {
	const indexes = Array.from({ length: count }, (_, index) => index);
	const unfrozen = indexes.filter((index) => !fixed[index] && !frozen[index]);
	const wide = unfrozen.filter((index) => !narrow[index]);
	if (wide.length > 0) return wide;
	if (unfrozen.length > 0) return unfrozen;
	const allFrozen = indexes.every((index) => frozen[index]);
	return allFrozen ? indexes.filter((index) => !fixed[index]) : [];
}

/** The most a frozen column takes of the grid's width, unless the user resized it. */
const FROZEN_SHARE = 0.4;
const FROZEN_MIN_WIDTH = 96;

function capFrozen({ widths, fixed, frozen, available }: Pick<ColumnFillInput, 'widths' | 'fixed' | 'frozen' | 'available'>): readonly number[] {
	if (!(available > 0) || frozen.every(Boolean)) return widths;
	const cap = Math.max(FROZEN_MIN_WIDTH, Math.floor(available * FROZEN_SHARE));
	if (!widths.some((width, index) => frozen[index] && !fixed[index] && width > cap)) return widths;
	return widths.map((width, index) => (frozen[index] && !fixed[index] ? Math.min(width, cap) : width));
}

export function fillColumnWidths({ widths: base, fixed, frozen, narrow, available }: ColumnFillInput): ColumnFill {
	const widths = capFrozen({ widths: base, fixed, frozen, available });
	const total = widths.reduce((sum, width) => sum + width, 0);
	const spare = available - total;
	if (!(spare > 0)) return { widths, filler: 0 };

	const flexible = flexibleColumns({ fixed, frozen, narrow }, widths.length);
	if (flexible.length === 0) return { widths, filler: spare };

	const flexibleWidth = flexible.reduce((sum, index) => sum + widths[index]!, 0);
	const next = [...widths];
	let given = 0;
	flexible.forEach((index, position) => {
		const last = position === flexible.length - 1;
		const proportional = flexibleWidth > 0 ? (spare * widths[index]!) / flexibleWidth : spare / flexible.length;
		const share = last ? spare - given : Math.floor(proportional);
		next[index] = widths[index]! + share;
		given += share;
	});
	return { widths: next, filler: 0 };
}

/**
 * A press on an empty part of the grid: the space below the last row, a row line past the
 * last column, or the header band past the last header. Cells, headers, the row markers,
 * the fill handle and any control keep their own meaning, and so does a scrollbar.
 */

/** Parts of the grid a press acts on; anything else inside the viewport is empty space. */
const PRESSABLE = [
	'[role="gridcell"]',
	'[role="columnheader"]',
	'[data-part-id^="sheets-row-marker"]',
	'[data-part-id="sheets-fill-handle"]',
	'button',
	'input',
	'a',
].join(', ');

export function isEmptyGridPress(target: Element, viewport: HTMLElement, clientX: number, clientY: number): boolean {
	if (!viewport.contains(target)) return false;
	if (target === viewport) {
		// A press on a scrollbar lands on the viewport itself, outside its client box.
		const rect = viewport.getBoundingClientRect();
		const x = clientX - rect.left - viewport.clientLeft;
		const y = clientY - rect.top - viewport.clientTop;
		return x >= 0 && y >= 0 && x < viewport.clientWidth && y < viewport.clientHeight;
	}
	const pressable = target.closest(PRESSABLE);
	return pressable === null || !viewport.contains(pressable);
}

// The TanStack Table v9 feature set for the DOM port — EXACTLY the three
// column-state features. No row features and no row-model factories: the table
// holds columns only, and the viewport draws rows by index from the row array.
//
// Built at module scope so the feature object has a stable identity across
// renders (a fresh tableFeatures({...}) per render would churn the table).
import {
	columnSizingFeature, // committed column widths   -> state.columnSizing
	columnResizingFeature, // transient drag-resize    -> state.columnResizing
	columnPinningFeature, // logical start/end pin      -> state.columnPinning
	tableFeatures
} from '@tanstack/react-table';

export const sheetsTableFeatures = tableFeatures({
	columnSizingFeature,
	columnResizingFeature,
	columnPinningFeature
});

export type SheetsTableFeatures = typeof sheetsTableFeatures;

// One header cell of the DOM grid: title, sort caret with priority, a slot for
// the column's menu, a right-edge resize handle, and drag to reorder. The cell
// knows nothing about views; the viewport passes plain callbacks.
import type { Column, Header } from '@tanstack/react-table';

import { cn } from '../utils/cn';
import type { SheetsRow } from '../grid/row-model';
import type { SheetsTableFeatures } from './features';

type SheetsTableColumn = Column<SheetsTableFeatures, SheetsRow, unknown>;

/** One sort key as the header shows it. The first key sorts first. */
export interface GridViewportSortKey {
	column: string;
	direction: 'asc' | 'desc';
}

/** Where a dragged header would land, shown as a bar on that side of the target. */
export interface HeaderDropTarget {
	key: string;
	side: 'before' | 'after';
}

/** Header drag-to-reorder wiring, shared by every header cell of one viewport. */
export interface HeaderDrag {
	/** The key being dragged, or null. */
	dragging: string | null;
	dropTarget: HeaderDropTarget | null;
	start: (key: string) => void;
	over: (target: HeaderDropTarget | null) => void;
	/** Drop on the current target; the viewport reports the move. */
	drop: () => void;
	end: () => void;
}

/** Narrowest width the resize handle drags a column to. */
const MIN_DRAG_WIDTH = 40;

/** Header label: shell meta title -> string header -> column id. `meta` is the empty v9 type, so read it loosely. */
export function columnTitle(column: SheetsTableColumn): string {
	const meta = column.columnDef.meta as { title?: string } | undefined;
	if (meta?.title) return meta.title;
	const header = column.columnDef.header;
	if (typeof header === 'string') return header;
	return column.id;
}

export interface HeaderCellProps {
	column: SheetsTableColumn;
	header: Header<SheetsTableFeatures, SheetsRow, unknown>;
	sort: readonly GridViewportSortKey[];
	onHeaderClick?: (colKey: string, additive: boolean) => void;
	getUnsortableReason?: (colKey: string) => string | null;
	onResize?: (colKey: string, width: number) => void;
	/** The width the column is drawn at (it may be wider than its own width when the grid fills). A resize starts from it. */
	width?: number;
	/** Drag to reorder; omitted when columns cannot be moved. */
	drag?: HeaderDrag;
	/** The column's menu (trigger and popup), rendered after the caret. */
	menu?: React.ReactNode;
	/** The column's index among the grid's columns, as its cells have it (`aria-colindex` is one more). */
	colIndex?: number;
}

/** A single header cell: title + sort caret and priority (click toggles) + menu + right-edge resize handle. */
export function HeaderCell({ column, header, sort, onHeaderClick, getUnsortableReason, onResize, width, drag, menu, colIndex }: HeaderCellProps) {
	const position = sort.findIndex((key) => key.column === column.id);
	const direction: 'asc' | 'desc' | 'none' = position === -1 ? 'none' : sort[position]!.direction;
	const priority = position !== -1 && sort.length > 1 ? position + 1 : null;
	const unsortableReason = onHeaderClick ? getUnsortableReason?.(column.id) ?? null : null;
	const sortable = Boolean(onHeaderClick) && unsortableReason === null;
	// An unsortable column shows no caret, so its menu takes the right edge.
	const noCaret = Boolean(onHeaderClick) && !sortable;
	const title = columnTitle(column);
	const hint = !onHeaderClick
		? undefined
		: unsortableReason !== null
			? unsortableReason || undefined
			: `Sort by ${title}. Shift+click to add it to the sort.`;
	const dropSide = drag?.dropTarget?.key === column.id && drag.dragging !== column.id ? drag.dropTarget.side : null;

	function onResizePointerDown(e: React.PointerEvent<HTMLDivElement>) {
		// Don't toggle sort while grabbing the handle, and don't select header text or start a drag.
		e.preventDefault();
		e.stopPropagation();
		if (onResize) {
			const startX = e.clientX;
			const startWidth = width ?? column.getSize();
			const onMove = (move: PointerEvent) => onResize(column.id, Math.max(MIN_DRAG_WIDTH, startWidth + (move.clientX - startX)));
			const onUp = () => {
				window.removeEventListener('pointermove', onMove);
				window.removeEventListener('pointerup', onUp);
			};
			window.addEventListener('pointermove', onMove);
			window.addEventListener('pointerup', onUp);
			return;
		}
		// Fall back to the v9 feature handler (columnResizeMode 'onChange').
		header.getResizeHandler()(e.nativeEvent);
	}

	return (
		<div
			role='columnheader'
			data-part-id='sheets-header-cell'
			data-col-key={column.id}
			// With columns virtualized, a screen reader reads the position from here, as on the cells.
			aria-colindex={colIndex === undefined ? undefined : colIndex + 1}
			data-sortable={onHeaderClick ? String(sortable) : undefined}
			data-dragging={drag?.dragging === column.id || undefined}
			aria-sort={direction === 'asc' ? 'ascending' : direction === 'desc' ? 'descending' : 'none'}
			title={hint}
			draggable={drag ? true : undefined}
			onDragStart={
				drag
					? (e) => {
							e.dataTransfer?.setData('text/plain', column.id);
							if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move';
							drag.start(column.id);
						}
					: undefined
			}
			onDragOver={
				drag
					? (e) => {
							if (drag.dragging === null) return;
							e.preventDefault();
							const rect = e.currentTarget.getBoundingClientRect();
							drag.over({ key: column.id, side: e.clientX < rect.left + rect.width / 2 ? 'before' : 'after' });
						}
					: undefined
			}
			onDrop={
				drag
					? (e) => {
							e.preventDefault();
							drag.drop();
						}
					: undefined
			}
			onDragEnd={drag ? () => drag.end() : undefined}
			onClick={(e) => {
				if (sortable) onHeaderClick?.(column.id, e.shiftKey);
			}}
			className={cn(
				'group relative flex h-full w-full select-none items-center gap-1 border-b border-border bg-background px-3 text-xs font-medium text-muted-foreground',
				sortable && 'cursor-pointer hover:bg-muted/50 hover:text-foreground',
				onHeaderClick && !sortable && unsortableReason && 'cursor-not-allowed',
				drag?.dragging === column.id && 'opacity-50',
			)}
		>
			{dropSide && (
				<span
					aria-hidden='true'
					data-part-id='sheets-header-drop-indicator'
					className={cn('bg-primary absolute top-0 z-10 h-full w-0.5', dropSide === 'before' ? 'left-0' : 'right-0')}
				/>
			)}
			{/* The raw field name, for people who know the schema; saved views and commands use it too. */}
			<span className='truncate' title={column.id === title ? undefined : column.id}>
				{title}
			</span>
			{noCaret ? (
				unsortableReason && <span className='sr-only'>{unsortableReason}</span>
			) : (
				<SortCaret direction={direction} priority={priority} />
			)}
			{menu && (
				// The menu trigger neither sorts nor starts a drag.
				<span
					className={cn('shrink-0', noCaret && 'ml-auto')}
					onClick={(e) => e.stopPropagation()}
					onDragStart={(e) => {
						e.preventDefault();
						e.stopPropagation();
					}}
				>
					{menu}
				</span>
			)}
			<div
				role='separator'
				aria-orientation='vertical'
				data-part-id='sheets-resize-handle'
				onClick={(e) => e.stopPropagation()}
				onPointerDown={onResizePointerDown}
				className='absolute right-0 top-0 h-full w-1 cursor-col-resize touch-none select-none bg-transparent hover:bg-primary/50'
			/>
		</div>
	);
}

/**
 * Up/down/neutral sort caret (inline SVG, no icon-lib dep — matches the package's glyph style),
 * with the key's priority when several columns sort.
 */
function SortCaret({ direction, priority }: { direction: 'asc' | 'desc' | 'none'; priority: number | null }) {
	return (
		<span className='ml-auto inline-flex shrink-0 items-center gap-0.5'>
			{priority !== null && (
				<span data-part-id='sheets-sort-priority' className='text-foreground text-[0.625rem] tabular-nums' aria-label={`sort priority ${priority}`}>
					{priority}
				</span>
			)}
			<svg
				data-part-id='sheets-sort-caret'
				data-direction={direction}
				width='8'
				height='8'
				viewBox='0 0 8 8'
				aria-hidden='true'
				className={cn('shrink-0', direction === 'none' && 'opacity-30')}
			>
				{direction === 'desc' ? <path d='M0 2 L4 6 L8 2 Z' fill='currentColor' /> : <path d='M0 6 L4 2 L8 6 Z' fill='currentColor' />}
			</svg>
		</span>
	);
}

// The DOM viewport for the TanStack port — where LAYOUT happens (the v9 table
// instance from S3 is a pure state-mirror; this is the dual-axis TanStack
// Virtual shell that paints it).
//
// VERTICAL virtualizer over rows, HORIZONTAL virtualizer over columns. The
// FROZEN columns (the first `frozenCount` columns; without `frozenCount`, the
// start-pinned column or else the first column) are painted OUTSIDE the
// horizontal virtual window — sticky elements per row — so they stay put under
// horizontal scroll. The horizontal virtualizer still counts them (so column
// start offsets stay correct), but the item loop SKIPS them; they are never
// double-painted.
//
// A sticky HEADER band sits at the top of the scroll content, reusing the SAME
// column layout as the body (see `grid-header.tsx` for one header cell: sort
// caret with priority, the column's menu, resize handle, drag to reorder).
//
// `renderCell` is injected so the viewport stays host-decoupled and testable. The
// root carries `data-impl="dom"` so tests / Chrome can assert the DOM path is live.
//
// ROWS are drawn by index straight from `rows` (the v9 table holds columns only), and
// each one is a memoized `GridBodyRow` that receives its own share of the selection
// and editing state as primitives: a cursor move renders the row it leaves and the
// row it enters, never the whole window. The header band is memoized the same way.
import { memo, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import type { Ref } from 'react';
import { useVirtualizer, type VirtualItem } from '@tanstack/react-virtual';
import type { Column, Header, Table } from '@tanstack/react-table';

import { cn } from '../utils/cn';
import type { SheetsRow } from '../grid/row-model';
import type { SelectionRect } from '../selection/selection-model';
import type { SheetsTableFeatures } from './features';
import { HeaderCell, type GridViewportSortKey, type HeaderDrag, type HeaderDropTarget } from './grid-header';
import { PINNED_HOVER_BG, RowMarkerCell, RowMarkerHeaderCell, markerWidthOf, type RowMarker } from './row-marker';
import { fillColumnWidths } from './column-fill';
import { useInnerWidth } from './use-inner-width';
import { isEmptyGridPress } from './empty-press';

export type { GridViewportSortKey } from './grid-header';
export type { RowMarker } from './row-marker';

/** Default row height (the "medium" setting). Drives the v-virtualizer estimate, range-band /
 *  fill-nub geometry, and hit-testing when the shell passes no `rowHeight`. */
const DEFAULT_ROW_HEIGHT = 44;
/** Extra rows rendered above/below the visible window — fewer blank rows on fast vertical scroll. */
const ROW_OVERSCAN = 12;
/** Extra columns rendered left/right of the visible window — fewer blank cells on fast horizontal scroll. */
const COLUMN_OVERSCAN = 6;
/** Header band height (DESIGN_SPEC §5 comfortable) — slightly shorter than the body row. */
const HEADER_HEIGHT = 40;

type SheetsTable = Table<SheetsTableFeatures, SheetsRow>;
type SheetsTableColumn = Column<SheetsTableFeatures, SheetsRow, unknown>;
type SheetsTableHeader = Header<SheetsTableFeatures, SheetsRow, unknown>;

const NO_SORT: readonly GridViewportSortKey[] = [];

/** Everything a host needs to draw one cell: where it is, its row, and its state. */
export interface RenderCellContext {
	rowIndex: number;
	columnIndex: number;
	/** The column's id (its key). */
	columnId: string;
	/** The row at `rowIndex`; null for a row whose page has not loaded yet. */
	row: SheetsRow | null | undefined;
	/** The row's stable id (see `getRowId`). */
	rowId: string;
	/** True for a frozen column, painted outside the h-virtual window. */
	isStickyColumn: boolean;
	/** True when this cell is the active (keyboard cursor) cell. Drives the focus ring. */
	isActive: boolean;
	/** True for the active cell and every cell of the active range: the cell is selected (`aria-selected`). */
	isSelected: boolean;
	/** True when this cell is edited in place (see `editingCell`). */
	isEditing: boolean;
	/** Type-to-edit seed of the in-place editor; set only when `isEditing`. */
	inlineInitialText?: string;
}

export type RenderCell = (ctx: RenderCellContext) => React.ReactNode;

/** The cell edited in place: its row, its column and the text that opened it. */
export interface GridEditingCell {
	rowIndex: number;
	columnId: string;
	initialText?: string;
}

function defaultGetRowId(row: SheetsRow | null | undefined, index: number): string {
	return row?.id != null ? String(row.id) : String(index);
}

/** Imperative handle for the later SheetsHandle scrollToRow path. */
export interface GridViewportHandle {
	scrollToIndex: (rowIndex: number) => void;
	/** Scroll the given cell into view (row + column virtualizers). Used by keyboard nav. */
	scrollToCell: (columnIndex: number, rowIndex: number) => void;
	/** Give the grid root keyboard focus, so typing reaches the active cell. */
	focus: () => void;
}

/** Visible row window (overscan-inclusive) reported to the shell for infinite-scroll prefetch. */
export interface VisibleRange {
	startIndex: number;
	endIndex: number;
}

export interface GridViewportProps {
	/** The v9 table: the columns (sizes, pins, headers). Rows come from `rows`. */
	table: SheetsTable;
	/** The rows, drawn by index; an index whose page has not loaded reads back null. */
	rows: readonly (SheetsRow | null | undefined)[];
	/** A row's stable id. Default: its `id`, else its index. */
	getRowId?: (row: SheetsRow | null | undefined, index: number) => string;
	renderCell: RenderCell;
	/** The cell edited in place, if any. */
	editingCell?: GridEditingCell;
	handleRef?: Ref<GridViewportHandle>;
	/**
	 * Fired on the scroll root's `scroll`. The DOM grid uses this to close (commit-or-
	 * dismiss) any open overlay editor: a virtualized cell anchor can unmount under
	 * scroll, so Phase-4 closes rather than re-positions against a stale rect.
	 */
	onScroll?: (e: React.UIEvent<HTMLDivElement>) => void;
	/** Sort keys, first key first, for the header carets. Defaults to unsorted. */
	sort?: readonly GridViewportSortKey[];
	/** Header click on a sortable column; `additive` is true for Shift+click. */
	onHeaderClick?: (colKey: string, additive: boolean) => void;
	/**
	 * Why a column cannot be sorted, or null when it can. A column with a reason is not
	 * clickable and shows the reason. Omitted: every column is sortable when `onHeaderClick` is set.
	 */
	getUnsortableReason?: (colKey: string) => string | null;
	/**
	 * Commit a column width from the header drag-resize handle. When provided, the handle
	 * drives a manual pointer-drag against this. When omitted, the handle falls back to the
	 * v9 `header.getResizeHandler()` (columnResizeMode 'onChange' feeds the table's own columnSizing state).
	 */
	onResize?: (colKey: string, width: number) => void;
	/**
	 * How many leading columns stay in place under horizontal scroll. Omitted: the start-pinned
	 * column, else the first column.
	 */
	frozenCount?: number;
	/** Row height in pixels. Default 44. */
	rowHeight?: number;
	/** Move a column beside another one (header drag). Omitted: headers cannot be dragged. */
	onColumnMove?: (colKey: string, target: string, side: 'before' | 'after') => void;
	/** The menu of a column's header (trigger and popup). Omitted: headers have no menu. */
	renderHeaderMenu?: (colKey: string) => React.ReactNode;
	/**
	 * Total row count for the VERTICAL virtualizer. Defaults to `rows.length`.
	 * Infinite scroll passes the server total here so the scrollbar spans every (lazily loaded)
	 * row — `rows` is the same-length proxy, so this matches `rows.length` in practice
	 * but is threaded explicitly so the shell stays the single source of truth for row count.
	 */
	count?: number;
	/**
	 * Fired (effect-free, via the row virtualizer's `onChange`) with the current overscan-inclusive
	 * visible window, for infinite-scroll prefetch. Omitted in paginated mode.
	 */
	onVisibleRangeChange?: (range: VisibleRange) => void;
	/**
	 * Optional leading checkbox / select-all column. When supplied, a sticky MARKER column is
	 * painted to the LEFT of the frozen columns, driving the canonical SheetsSelection RangeSet.
	 * When OMITTED, the grid renders without a marker column.
	 */
	rowMarker?: RowMarker;
	/** Active (keyboard cursor) cell `[col, row]`. Drives the per-cell focus ring + aria-activedescendant. */
	activeCell?: [number, number];
	/** Active range (cell coords) — rendered as an inert pointer-events-none band overlay. */
	activeRange?: SelectionRect;
	/**
	 * Keydown handler for the grid root — the shell owns spreadsheet nav (arrows / Enter / F2).
	 * Keys from a portalled surface rendered inside the grid (a header menu) are not grid keys
	 * and do not reach it.
	 */
	onGridKeyDown?: (e: React.KeyboardEvent) => void;
	/** The grid root took keyboard focus (Tab, or a script), not focus from a pointer press. */
	onGridFocus?: () => void;
	/**
	 * Native clipboard handlers for the grid root. They fire only when the root (tabIndex=0) holds
	 * focus and an overlay editor is NOT open (the editor owns its own clipboard while editing). The
	 * shell routes each to the `clipboard.copy`/`cut`/`paste` command through the ONE dispatch pipeline.
	 */
	onCopy?: (e: React.ClipboardEvent) => void;
	onCut?: (e: React.ClipboardEvent) => void;
	onPaste?: (e: React.ClipboardEvent) => void;
	/** DOM id of the active cell node, mirrored to `aria-activedescendant` on the grid root. */
	activeDescendantId?: string;
	/**
	 * Fired on a fill-handle (nub) drag RELEASE when the dropped cell extends the source range.
	 * `sourceRange` is the active range (or a 1×1 rect at the active cell) the drag started from;
	 * `target` is the `[col,row]` under the pointer at release (clamped to grid bounds). The shell
	 * routes this to the `fill.drag` command. Omitted = no nub rendered.
	 */
	onFillDrag?: (sourceRange: SelectionRect, target: [number, number]) => void;
	/**
	 * Columns that keep their width when the columns are narrower than the grid (the
	 * user resized them). The others share the spare width; see {@link fillColumnWidths}.
	 */
	fixedWidthColumns?: ReadonlySet<string>;
	/** Narrow kinds (checkbox and number columns): they take spare width only when no other column can. */
	narrowColumns?: ReadonlySet<string>;
	/**
	 * A primary-button press on empty grid space (below the last row, a row line past the
	 * last column, the header band past the last header). The shell clears the cursor.
	 */
	onPressEmpty?: () => void;
	className?: string;
}

/** The element shows keyboard focus (`:focus-visible`); true where the selector is unknown. */
function isKeyboardFocus(element: HTMLElement): boolean {
	try {
		return element.matches(':focus-visible');
	} catch {
		return true;
	}
}

/** Left offset and width (px) of a column span, from the drawn column widths plus the marker offset. */
function spanGeometry(x: number, width: number, widths: readonly number[], markerWidth: number) {
	let left = markerWidth;
	for (let i = 0; i < x && i < widths.length; i++) left += widths[i]!;
	let span = 0;
	for (let i = x; i < x + width && i < widths.length; i++) span += widths[i]!;
	return { left, width: span };
}

/** Box of the inert range-band overlay for a half-open {@link SelectionRect} (cell coords). */
function rangeBandStyle(range: SelectionRect, widths: readonly number[], markerWidth: number, rowHeight: number): React.CSSProperties {
	const { left, width } = spanGeometry(range.x, range.width, widths, markerWidth);
	return {
		transform: `translate(${left}px, ${range.y * rowHeight}px)`,
		width,
		height: range.height * rowHeight
	};
}

/** Side of the square fill-handle nub (px). Centered on the source rect's bottom-right corner. */
const FILL_NUB_SIZE = 8;

/** Position the fill-handle nub centered on the BOTTOM-RIGHT corner of the source {@link SelectionRect}. */
function fillNubStyle(source: SelectionRect, widths: readonly number[], markerWidth: number, rowHeight: number): React.CSSProperties {
	const { left, width } = spanGeometry(source.x, source.width, widths, markerWidth);
	const right = left + width;
	const bottom = (source.y + source.height) * rowHeight;
	return {
		transform: `translate(${right - FILL_NUB_SIZE / 2}px, ${bottom - FILL_NUB_SIZE / 2}px)`,
		width: FILL_NUB_SIZE,
		height: FILL_NUB_SIZE
	};
}

/**
 * Hit-test a client pointer position to a `[col, row]` cell index over the virtualized body.
 *
 * Converts to CONTENT space (add the scroll element's scroll offset, subtract its bounding-rect
 * origin), then: X walks the per-column widths from the leading `markerWidth` to find the column
 * whose band the pointer is over; Y subtracts the sticky `headerHeight` and floors by the uniform
 * `rowHeight`. Both axes CLAMP to `[0, count-1]` so a drag past the grid edge lands on the last
 * cell. PURE (takes the geometry, returns indices) — testable without a DOM.
 */
export function hitTestCell(
	clientX: number,
	clientY: number,
	geom: {
		rect: { left: number; top: number };
		scrollLeft: number;
		scrollTop: number;
		markerWidth: number;
		headerHeight: number;
		rowHeight: number;
		colWidths: readonly number[];
		rowCount: number;
	},
): [number, number] {
	const { rect, scrollLeft, scrollTop, markerWidth, headerHeight, rowHeight, colWidths, rowCount } = geom;
	// Column: walk widths in content space from the marker offset.
	const localX = clientX - rect.left + scrollLeft - markerWidth;
	let col = 0;
	let acc = 0;
	for (let i = 0; i < colWidths.length; i++) {
		acc += colWidths[i];
		if (localX < acc) {
			col = i;
			break;
		}
		col = i;
	}
	col = Math.max(0, Math.min(col, colWidths.length - 1));
	// Row: subtract the sticky header, floor by the uniform row height.
	const localY = clientY - rect.top + scrollTop - headerHeight;
	let row = Math.floor(localY / rowHeight);
	row = Math.max(0, Math.min(row, rowCount - 1));
	return [col, row];
}

/**
 * The column indices painted frozen: the first `frozenCount` columns, or without it the
 * start-pinned column, else the first column (the grid's earlier sticky-by-default rule).
 */
function frozenColumnIndices(columns: readonly SheetsTableColumn[], frozenCount: number | undefined): number[] {
	if (frozenCount !== undefined) {
		return Array.from({ length: Math.max(0, Math.min(frozenCount, columns.length)) }, (_, index) => index);
	}
	const pinned = columns.findIndex((col) => col.getIsPinned() === 'start');
	if (pinned >= 0) return [pinned];
	return columns.length > 0 ? [0] : [];
}

/** Drag-to-reorder state for the header cells of one viewport. */
function useHeaderDrag(onColumnMove: GridViewportProps['onColumnMove']): HeaderDrag | undefined {
	const [dragging, setDragging] = useState<string | null>(null);
	const [dropTarget, setDropTarget] = useState<HeaderDropTarget | null>(null);
	const latest = useRef({ dragging, dropTarget, onColumnMove });
	latest.current = { dragging, dropTarget, onColumnMove };
	return useMemo<HeaderDrag | undefined>(() => {
		if (!onColumnMove) return undefined;
		const end = () => {
			setDragging(null);
			setDropTarget(null);
		};
		return {
			dragging,
			dropTarget,
			start: (key) => setDragging(key),
			over: (target) =>
				setDropTarget((current) => (current?.key === target?.key && current?.side === target?.side ? current : target)),
			drop: () => {
				const { dragging: key, dropTarget: target, onColumnMove: move } = latest.current;
				if (key && target && key !== target.key) move?.(key, target.key, target.side);
				end();
			},
			end,
		};
	}, [onColumnMove, dragging, dropTarget]);
}

interface GridHeaderBandProps {
	columns: readonly SheetsTableColumn[];
	headersByColumnId: ReadonlyMap<string, SheetsTableHeader>;
	frozen: readonly number[];
	frozenLefts: readonly number[];
	widths: readonly number[];
	virtualColumns: readonly VirtualItem[];
	markerWidth: number;
	rowWidth: number;
	contentWidth: number;
	filler: number;
	rowMarker: RowMarker | undefined;
	sort: readonly GridViewportSortKey[];
	onHeaderClick: GridViewportProps['onHeaderClick'];
	getUnsortableReason: GridViewportProps['getUnsortableReason'];
	onResize: GridViewportProps['onResize'];
	drag: HeaderDrag | undefined;
	renderHeaderMenu: GridViewportProps['renderHeaderMenu'];
}

/** The sticky header band, same column layout as the body. Memoized: a cursor move does not render it. */
const GridHeaderBand = memo(function GridHeaderBand({
	columns,
	headersByColumnId,
	frozen,
	frozenLefts,
	widths,
	virtualColumns,
	markerWidth,
	rowWidth,
	contentWidth,
	filler,
	rowMarker,
	sort,
	onHeaderClick,
	getUnsortableReason,
	onResize,
	drag,
	renderHeaderMenu
}: GridHeaderBandProps) {
	const lastFrozen = frozen[frozen.length - 1];
	const headerCell = (index: number) => {
		const column = columns[index]!;
		const header = headersByColumnId.get(column.id);
		if (!header) return null;
		return (
			<HeaderCell
				column={column}
				header={header}
				colIndex={index}
				sort={sort}
				onHeaderClick={onHeaderClick}
				getUnsortableReason={getUnsortableReason}
				onResize={onResize}
				width={widths[index]}
				drag={drag}
				menu={renderHeaderMenu?.(column.id)}
			/>
		);
	};
	return (
		<div
			role='row'
			data-part-id='sheets-header-row'
			className='sticky top-0 z-30 flex bg-background'
			style={{ height: HEADER_HEIGHT, width: rowWidth }}
		>
			{rowMarker && (
				<div className='sticky left-0 z-40 flex shrink-0' style={{ width: markerWidth, height: '100%' }}>
					<RowMarkerHeaderCell rowMarker={rowMarker} />
				</div>
			)}
			{frozen.map((index, position) => (
				<div
					key={columns[index]!.id}
					data-frozen=''
					className={cn('sticky z-40 flex shrink-0', index === lastFrozen && 'border-r border-border')}
					style={{ left: frozenLefts[position], width: widths[index], height: '100%' }}
				>
					{headerCell(index)}
				</div>
			))}
			{virtualColumns.map((virtualCol) => {
				if (frozen.includes(virtualCol.index)) return null; // frozen header painted above
				return (
					<div
						key={virtualCol.key}
						className='absolute top-0 flex'
						style={{ transform: `translateX(${virtualCol.start + markerWidth}px)`, width: virtualCol.size, height: '100%' }}
					>
						{headerCell(virtualCol.index)}
					</div>
				);
			})}
			{filler > 0 && (
				<div
					aria-hidden='true'
					data-part-id='sheets-header-filler'
					className='absolute top-0 h-full border-b border-border'
					style={{ left: contentWidth, width: filler }}
				/>
			)}
		</div>
	);
});

interface GridBodyRowProps {
	rowIndex: number;
	row: SheetsRow | null | undefined;
	rowId: string;
	start: number;
	height: number;
	columnIds: readonly string[];
	frozen: readonly number[];
	frozenLefts: readonly number[];
	widths: readonly number[];
	virtualColumns: readonly VirtualItem[];
	markerWidth: number;
	rowMarker: RowMarker | undefined;
	rowSelected: boolean;
	/** Column of the active cell when it is in this row, else -1. */
	activeColumn: number;
	/** The active range's columns `[rangeStart, rangeEnd)` when it covers this row, else -1 and -1. */
	rangeStart: number;
	rangeEnd: number;
	/** The column edited in place in this row, else null, and the text that opened the editor. */
	editingColumnId: string | null;
	editingText: string | undefined;
	renderCell: RenderCell;
}

/**
 * One body row. Every prop is a primitive or keeps its identity until what it describes
 * changes, so the memo skips the rows a cursor move, a range drag or an edit does not touch.
 */
const GridBodyRow = memo(function GridBodyRow({
	rowIndex,
	row,
	rowId,
	start,
	height,
	columnIds,
	frozen,
	frozenLefts,
	widths,
	virtualColumns,
	markerWidth,
	rowMarker,
	rowSelected,
	activeColumn,
	rangeStart,
	rangeEnd,
	editingColumnId,
	editingText,
	renderCell
}: GridBodyRowProps) {
	const lastFrozen = frozen[frozen.length - 1];
	const cell = (columnIndex: number, isStickyColumn: boolean) => {
		const columnId = columnIds[columnIndex]!;
		const isEditing = columnId === editingColumnId;
		return renderCell({
			rowIndex,
			columnIndex,
			columnId,
			row,
			rowId,
			isStickyColumn,
			isActive: activeColumn === columnIndex,
			isSelected: activeColumn === columnIndex || (columnIndex >= rangeStart && columnIndex < rangeEnd),
			isEditing,
			inlineInitialText: isEditing ? editingText : undefined
		});
	};
	return (
		<div
			role='row'
			data-index={rowIndex}
			data-row={rowIndex}
			data-selected={rowSelected || undefined}
			aria-rowindex={rowIndex + 1}
			className={cn('group absolute left-0 top-0 flex border-b border-border', rowSelected ? 'bg-primary/5' : 'hover:bg-muted/50')}
			style={{ transform: `translateY(${start}px)`, height, width: '100%' }}
		>
			{rowMarker && (
				<div className='sticky left-0 z-20 flex shrink-0' style={{ width: markerWidth }}>
					<RowMarkerCell rowIndex={rowIndex} rowMarker={rowMarker} isActiveRow={activeColumn !== -1} />
				</div>
			)}
			{frozen.map((index, position) => (
				<div
					key={columnIds[index]}
					className={cn('sticky z-10 flex shrink-0 bg-background', PINNED_HOVER_BG, index === lastFrozen && 'border-r border-border')}
					data-col={index}
					style={{ left: frozenLefts[position], width: widths[index] }}
				>
					{cell(index, true)}
				</div>
			))}
			{virtualColumns.map((virtualCol) => {
				if (frozen.includes(virtualCol.index)) return null; // frozen col painted above
				return (
					<div
						key={virtualCol.key}
						className='absolute top-0 flex'
						data-col={virtualCol.index}
						style={{ transform: `translateX(${virtualCol.start + markerWidth}px)`, width: virtualCol.size, height: '100%' }}
					>
						{cell(virtualCol.index, false)}
					</div>
				);
			})}
		</div>
	);
});

/** The same array while its content key is the same, so memoized children keep their props. */
function useStableArray<T>(items: readonly T[], key: string): readonly T[] {
	// eslint-disable-next-line react-hooks/exhaustive-deps -- the key describes the items
	return useMemo(() => items, [key]);
}

export function GridViewport({
	table,
	rows,
	getRowId = defaultGetRowId,
	renderCell,
	editingCell,
	handleRef,
	onScroll,
	sort = NO_SORT,
	onHeaderClick,
	getUnsortableReason,
	onResize,
	frozenCount,
	rowHeight = DEFAULT_ROW_HEIGHT,
	onColumnMove,
	renderHeaderMenu,
	count,
	onVisibleRangeChange,
	rowMarker,
	activeCell,
	activeRange,
	onGridKeyDown,
	onGridFocus,
	onCopy,
	onCut,
	onPaste,
	activeDescendantId,
	onFillDrag,
	fixedWidthColumns,
	narrowColumns,
	onPressEmpty,
	className
}: GridViewportProps) {
	const scrollRef = useRef<HTMLDivElement>(null);
	const innerWidth = useInnerWidth(scrollRef);

	const rowCount = count ?? rows.length;
	const columns = table.getAllLeafColumns();
	const columnIds = useMemo(() => columns.map((column) => column.id), [columns]);

	// Report the visible window WITHOUT an effect: the virtualizer's `onChange` fires on every
	// recompute (scroll/resize/measure) with the live instance, whose `.range` is the overscan-
	// inclusive {startIndex,endIndex}. Keep the ref current each render so the latch never goes stale.
	const onVisibleRangeChangeRef = useRef(onVisibleRangeChange);
	onVisibleRangeChangeRef.current = onVisibleRangeChange;
	const lastRangeRef = useRef<string | null>(null);

	const rowVirtualizer = useVirtualizer({
		count: rowCount,
		getScrollElement: () => scrollRef.current,
		estimateSize: () => rowHeight,
		overscan: ROW_OVERSCAN,
		onChange: (instance) => {
			const range = instance.range;
			if (!range) return;
			// Report only real changes, and after the render: the virtualizer can notify while this
			// component renders (first measure), and a host state update there re-renders it mid-render
			// in a loop ("Too many re-renders" once a table has rows).
			const key = `${range.startIndex}:${range.endIndex}`;
			if (key === lastRangeRef.current) return;
			lastRangeRef.current = key;
			const { startIndex, endIndex } = range;
			queueMicrotask(() => onVisibleRangeChangeRef.current?.({ startIndex, endIndex }));
		}
	});

	// A new row height changes every row's size: drop the measured sizes so rows lay out again.
	const measuredRowHeight = useRef(rowHeight);
	useEffect(() => {
		if (measuredRowHeight.current === rowHeight) return;
		measuredRowHeight.current = rowHeight;
		rowVirtualizer.measure();
	}, [rowHeight, rowVirtualizer]);

	// The optional leading marker column shifts EVERYTHING right by its width: the frozen columns
	// pin after it, virtualized columns translate by it, and the content width grows by it.
	const markerWidth = markerWidthOf(rowMarker);
	const frozenNow = frozenColumnIndices(columns, frozenCount);
	const frozen = useStableArray(frozenNow, frozenNow.join());

	// The widths drawn: the columns' own widths, with spare grid width shared among the columns
	// the user has not resized (O(columns), recomputed only when an input changes). Never stored.
	const baseWidths = columns.map((column) => column.getSize());
	const fixedFlags = columns.map((column) => fixedWidthColumns?.has(column.id) ?? false);
	const narrowFlags = columns.map((column) => narrowColumns?.has(column.id) ?? false);
	const fillKey = `${innerWidth - markerWidth}|${baseWidths.join()}|${fixedFlags.join()}|${narrowFlags.join()}|${frozen.join()}`;
	const fill = useMemo(
		() =>
			fillColumnWidths({
				widths: baseWidths,
				fixed: fixedFlags,
				frozen: columns.map((_, index) => frozen.includes(index)),
				narrow: narrowFlags,
				available: innerWidth - markerWidth,
			}),
		// eslint-disable-next-line react-hooks/exhaustive-deps -- the key covers every input
		[fillKey],
	);
	const widths = fill.widths;

	const columnVirtualizer = useVirtualizer({
		horizontal: true,
		count: columns.length,
		getScrollElement: () => scrollRef.current,
		estimateSize: (index) => widths[index] ?? columns[index].getSize(),
		getItemKey: (index) => columns[index]?.id ?? index,
		overscan: COLUMN_OVERSCAN
	});

	useImperativeHandle(
		handleRef,
		() => ({
			scrollToIndex: (rowIndex: number) => rowVirtualizer.scrollToIndex(rowIndex),
			scrollToCell: (columnIndex: number, rowIndex: number) => {
				rowVirtualizer.scrollToIndex(rowIndex);
				columnVirtualizer.scrollToIndex(columnIndex);
			},
			focus: () => scrollRef.current?.focus({ preventScroll: true })
		}),
		[rowVirtualizer, columnVirtualizer]
	);

	const headersByColumnId = useMemo(() => new Map(table.getLeafHeaders().map((h) => [h.column.id, h])), [table, columns]);
	const drag = useHeaderDrag(onColumnMove);

	const frozenLefts = useMemo(() => {
		const lefts: number[] = [];
		let left = markerWidth;
		for (const index of frozen) {
			lefts.push(left);
			left += widths[index]!;
		}
		return lefts;
	}, [frozen, widths, markerWidth]);

	const totalWidth = columnVirtualizer.getTotalSize();
	const virtualColumnsNow = columnVirtualizer.getVirtualItems();
	const virtualColumns = useStableArray(
		virtualColumnsNow,
		virtualColumnsNow.map((column) => `${column.key}:${column.start}:${column.size}`).join()
	);
	const contentWidth = totalWidth + markerWidth;
	// Every column keeps its width and they end before the grid's edge: the rows (lines, hover,
	// selection) still run to the edge over an inert filler, with no cell and no focus stop.
	const rowWidth = contentWidth + fill.filler;

	// Fill-handle SOURCE rect: the active range, else a 1×1 rect at the active cell. Drives the nub
	// position (its bottom-right corner) and is the `from` handed to onFillDrag. Absent when neither.
	const fillSource: SelectionRect | undefined = onFillDrag
		? activeRange ?? (activeCell ? { x: activeCell[0], y: activeCell[1], width: 1, height: 1 } : undefined)
		: undefined;

	function onFillNubPointerDown(e: React.PointerEvent<HTMLDivElement>) {
		// Don't start a cell selection / text-select while grabbing the nub.
		e.preventDefault();
		e.stopPropagation();
		if (!onFillDrag || !fillSource) return;
		const source = fillSource;
		const scrollEl = scrollRef.current;
		if (!scrollEl) return;
		const colWidths = widths;
		let target: [number, number] = [source.x + source.width - 1, source.y + source.height - 1];
		const onMove = (move: PointerEvent) => {
			const rect = scrollEl.getBoundingClientRect();
			target = hitTestCell(move.clientX, move.clientY, {
				rect: { left: rect.left, top: rect.top },
				scrollLeft: scrollEl.scrollLeft,
				scrollTop: scrollEl.scrollTop,
				markerWidth,
				headerHeight: HEADER_HEIGHT,
				rowHeight,
				colWidths,
				rowCount
			});
		};
		const onUp = () => {
			window.removeEventListener('pointermove', onMove);
			window.removeEventListener('pointerup', onUp);
			onFillDrag(source, target);
		};
		window.addEventListener('pointermove', onMove);
		window.addEventListener('pointerup', onUp);
	}

	return (
		<div
			ref={scrollRef}
			data-impl='dom'
			data-part-id='sheets-viewport'
			role='grid'
			tabIndex={0}
			onScroll={onScroll}
			onPointerDown={(e) => {
				if (onPressEmpty && e.button === 0 && isEmptyGridPress(e.target as Element, e.currentTarget, e.clientX, e.clientY)) onPressEmpty();
			}}
			onKeyDown={(e) => {
				if (e.currentTarget.contains(e.target as Node)) onGridKeyDown?.(e);
			}}
			onFocus={(e) => {
				if (e.target === e.currentTarget && isKeyboardFocus(e.currentTarget)) onGridFocus?.();
			}}
			onCopy={onCopy}
			onCut={onCut}
			onPaste={onPaste}
			aria-activedescendant={activeDescendantId}
			aria-rowcount={rowCount}
			aria-colcount={columns.length}
			className={cn('relative h-full w-full overflow-auto outline-none', className)}
		>
			<GridHeaderBand
				columns={columns}
				headersByColumnId={headersByColumnId}
				frozen={frozen}
				frozenLefts={frozenLefts}
				widths={widths}
				virtualColumns={virtualColumns}
				markerWidth={markerWidth}
				rowWidth={rowWidth}
				contentWidth={contentWidth}
				filler={fill.filler}
				rowMarker={rowMarker}
				sort={sort}
				onHeaderClick={onHeaderClick}
				getUnsortableReason={getUnsortableReason}
				onResize={onResize}
				drag={drag}
				renderHeaderMenu={renderHeaderMenu}
			/>

			{/* BODY — virtualized rows × columns. Cells are not text: a double-click or a drag must not
			    leave a native text selection on them. An inline editor's field stays selectable. */}
			<div
				className='select-none [&_[contenteditable=true]]:select-text [&_input]:select-text [&_textarea]:select-text'
				style={{ height: rowVirtualizer.getTotalSize(), width: rowWidth, position: 'relative' }}
			>
				{rowVirtualizer.getVirtualItems().map((virtualRow) => {
					const index = virtualRow.index;
					// Defensive: when `count` (server total) leads `rows`, guard the off-by-one race.
					if (index >= rows.length) return null;
					const row = rows[index];
					const inRange = activeRange !== undefined && index >= activeRange.y && index < activeRange.y + activeRange.height;
					const editingHere = editingCell?.rowIndex === index;
					return (
						<GridBodyRow
							key={virtualRow.key}
							rowIndex={index}
							row={row}
							rowId={getRowId(row, index)}
							start={virtualRow.start}
							height={rowHeight}
							columnIds={columnIds}
							frozen={frozen}
							frozenLefts={frozenLefts}
							widths={widths}
							virtualColumns={virtualColumns}
							markerWidth={markerWidth}
							rowMarker={rowMarker}
							rowSelected={rowMarker?.isSelected(index) ?? false}
							activeColumn={activeCell?.[1] === index ? activeCell[0] : -1}
							rangeStart={inRange ? activeRange.x : -1}
							rangeEnd={inRange ? activeRange.x + activeRange.width : -1}
							editingColumnId={editingHere ? editingCell.columnId : null}
							editingText={editingHere ? editingCell.initialText : undefined}
							renderCell={renderCell}
						/>
					);
				})}
				{activeRange && (
					<div
						data-part-id='sheets-range-band'
						aria-hidden='true'
						className='pointer-events-none absolute z-[5] border border-primary/50 bg-primary/10'
						style={rangeBandStyle(activeRange, widths, markerWidth, rowHeight)}
					/>
				)}
				{fillSource && (
					<div
						data-part-id='sheets-fill-handle'
						role='button'
						aria-label='Fill handle'
						onPointerDown={onFillNubPointerDown}
						className='absolute z-10 cursor-crosshair touch-none select-none rounded-[1px] border border-background bg-primary'
						style={fillNubStyle(fillSource, widths, markerWidth, rowHeight)}
					/>
				)}
			</div>
		</div>
	);
}

// The leading row-marker column: a select-all checkbox in the header and, per
// row, a selection checkbox plus an optional "open record" button. The shell
// derives the wiring from the canonical SheetsSelection.
import { RiExpandDiagonalLine } from '@remixicon/react';

import { Checkbox } from '@/components/ui/checkbox';

import { cn } from '../utils/cn';

/** Width of the marker column with the checkbox only, and with the open-record button too. */
export const MARKER_WIDTH = 40;
export const MARKER_WIDTH_WITH_EXPAND = 64;

// Row-hover tint for the PINNED (sticky) cells. The pinned column/marker sit OVER the
// horizontally-scrolled body, so their hover background must be fully OPAQUE — a translucent
// `bg-muted/50` (as used on the row itself) would let the scrolled-away cells bleed through the
// pinned column on hover. `color-mix` precomputes the SAME tint as opaque: 50% muted over the
// surface, so the pinned column matches the row exactly while staying solid. Theme-safe (the raw
// `--muted`/`--background` vars flip in dark mode). Uses raw vars, not `--color-*`, because the UI
// theme is `@theme inline` (the `--color-*` aliases aren't emitted at runtime).
export const PINNED_HOVER_BG = 'group-hover:bg-[color-mix(in_oklab,var(--muted)_50%,var(--background))]';

/** Selection wiring for the leading checkbox column. The shell derives this from SheetsSelection. */
export interface RowMarker {
	/** True when row `rowIndex` is in the canonical selection. */
	isSelected: (rowIndex: number) => boolean;
	/** Toggle row `rowIndex`; `shiftKey` requests a contiguous range-select from the last anchor. */
	onToggleRow: (rowIndex: number, shiftKey: boolean) => void;
	/** Every row selected — the header checkbox shows checked. */
	allSelected: boolean;
	/** Some (but not all) rows selected — the header checkbox shows indeterminate. */
	someSelected: boolean;
	/** Select-all / clear-all from the header checkbox. */
	onToggleAll: () => void;
	/**
	 * Open one record (the record panel). When set, each row's marker shows an open
	 * button: on row hover or focus, and always on the active row.
	 */
	onExpandRow?: (rowIndex: number) => void;
	/** Accessible name of a row's open button. Default "Open record". */
	expandLabel?: (rowIndex: number) => string;
}

export function markerWidthOf(rowMarker: RowMarker | undefined): number {
	if (!rowMarker) return 0;
	return rowMarker.onExpandRow ? MARKER_WIDTH_WITH_EXPAND : MARKER_WIDTH;
}

/** Header marker cell: the select-all checkbox (checked = all, indeterminate = some). */
export function RowMarkerHeaderCell({ rowMarker }: { rowMarker: RowMarker }) {
	return (
		<div
			role='columnheader'
			data-part-id='sheets-row-marker-header'
			data-slot='row-marker-header'
			className='flex h-full w-full select-none items-center justify-center border-b border-border bg-background'
		>
			<Checkbox
				checked={rowMarker.allSelected}
				indeterminate={rowMarker.someSelected}
				onClick={() => rowMarker.onToggleAll()}
				aria-label={rowMarker.allSelected ? 'Deselect all rows' : 'Select all rows'}
			/>
		</div>
	);
}

/** Body marker cell per row: a checkbox reflecting selection, and the open-record button when wired. */
export function RowMarkerCell({ rowIndex, rowMarker, isActiveRow }: { rowIndex: number; rowMarker: RowMarker; isActiveRow: boolean }) {
	const selected = rowMarker.isSelected(rowIndex);
	// Reveal-on-hover (DESIGN_SPEC §9): checkbox is hidden until the row is hovered, but stays
	// visible once this row is checked OR any selection is active (so multi-select stays legible).
	const reveal = selected || rowMarker.someSelected || rowMarker.allSelected;
	const onExpandRow = rowMarker.onExpandRow;
	return (
		<div
			data-part-id='sheets-row-marker-cell'
			data-slot='row-marker-cell'
			// Stop the click from bubbling into the row (which would also start a cell edit).
			onClick={(e) => e.stopPropagation()}
			onDoubleClick={(e) => e.stopPropagation()}
			className={`flex h-full w-full select-none items-center justify-center gap-1 bg-background ${PINNED_HOVER_BG}`}
		>
			<Checkbox
				checked={selected}
				// base-ui Checkbox renders a <button>; onClick carries the native shiftKey for range-select.
				onClick={(e) => rowMarker.onToggleRow(rowIndex, e.shiftKey)}
				aria-label={`Select row ${rowIndex}`}
				className={cn(!reveal && 'opacity-0 group-hover:opacity-100 focus-visible:opacity-100')}
			/>
			{onExpandRow && (
				<button
					type='button'
					data-part-id='sheets-row-expand'
					aria-label={rowMarker.expandLabel?.(rowIndex) ?? 'Open record'}
					title={rowMarker.expandLabel?.(rowIndex) ?? 'Open record'}
					onClick={() => onExpandRow(rowIndex)}
					className={cn(
						'text-muted-foreground hover:text-foreground rounded p-0.5 focus-visible:opacity-100',
						!isActiveRow && 'opacity-0 group-hover:opacity-100',
					)}
				>
					<RiExpandDiagonalLine className='size-3.5' aria-hidden='true' />
				</button>
			)}
		</div>
	);
}

import { useLayoutEffect, useState, type RefObject } from 'react';

/**
 * The inner width of an element (without its scrollbar), in whole pixels: 0 until it
 * is measured. It follows the element through one `ResizeObserver`, applies at most
 * one change per animation frame, and ignores changes under 1 px, so a container
 * resize renders the grid once per frame at most.
 */
export function useInnerWidth(ref: RefObject<HTMLElement | null>): number {
	const [width, setWidth] = useState(0);

	useLayoutEffect(() => {
		const element = ref.current;
		if (!element) return;
		// Measure before the first paint, so the grid never shows unfilled for a frame.
		let applied = element.clientWidth;
		setWidth(applied);
		if (typeof ResizeObserver === 'undefined') return;

		let pending: number | null = null;
		let frame = 0;
		const observer = new ResizeObserver((entries) => {
			const entry = entries[entries.length - 1];
			if (!entry) return;
			// The content box excludes the scrollbar, like clientWidth, and reading it forces no layout.
			pending = Math.floor(entry.contentRect.width);
			if (frame) return;
			frame = requestAnimationFrame(() => {
				frame = 0;
				if (pending === null || Math.abs(pending - applied) < 1) return;
				applied = pending;
				setWidth(applied);
			});
		});
		observer.observe(element);
		return () => {
			observer.disconnect();
			if (frame) cancelAnimationFrame(frame);
		};
	}, [ref]);

	return width;
}

// The TanStack Table v9 instance for the DOM port: the COLUMNS (sizes, pins,
// resizing, headers). It is a state-mirror, not a layout layer (TanStack Virtual
// lays out in GridViewport) and not a data layer (useSheets loads the rows).
//
// It holds no rows. v9 builds its row model eagerly over every row of `data` and
// rebuilds it whenever the array changes, which on a 100k-row table cost seconds per
// interaction. The viewport draws rows by index straight from the row array instead.
//
// Controlled state (S1): v8-style `state` partial + per-feature `on*Change`
// callbacks. The CALLER owns the slices (useGridState / the store) — the table
// is never a second writer, so there is no echo loop.
import { useMemo } from 'react';
import { createColumnHelper, useTable } from '@tanstack/react-table';
import type {
	ColumnDef,
	ColumnPinningState,
	ColumnResizeMode,
	ColumnSizingState,
	OnChangeFn
} from '@tanstack/react-table';

import type { SheetsRow } from '../grid/row-model';
import { sheetsTableFeatures, type SheetsTableFeatures } from './features';

/** Smallest column descriptor the instance needs — key + header label (+ optional width). */
export interface SheetsColumnDescriptor {
	key: string;
	name: string;
	size?: number;
}

export type SheetsColumnDef = ColumnDef<SheetsTableFeatures, SheetsRow>;

export interface UseSheetsTableInstanceParams {
	/** Render-column descriptors (header label + key), in display order. */
	columns: SheetsColumnDescriptor[];
	/** Committed column widths (caller-owned). */
	columnSizing: ColumnSizingState;
	/** Logical start/end column pins (caller-owned). */
	columnPinning: ColumnPinningState;
	onColumnSizingChange: OnChangeFn<ColumnSizingState>;
	onColumnPinningChange: OnChangeFn<ColumnPinningState>;
}

const NO_ROWS: SheetsRow[] = [];

/**
 * Build a v9 table instance wired with {@link sheetsTableFeatures} and the
 * caller-owned controlled column state. The column defs carry only a minimal value
 * accessor (`row[key]`); the cell RENDER is the cell host's job.
 */
export function useSheetsTableInstance(params: UseSheetsTableInstanceParams) {
	const { columns, columnSizing, columnPinning, onColumnSizingChange, onColumnPinningChange } = params;

	const columnDefs = useMemo<SheetsColumnDef[]>(() => {
		const helper = createColumnHelper<SheetsTableFeatures, SheetsRow>();
		// accessor-FUNCTION branch (value by key) → requires an explicit `id`.
		return columns.map((col) => helper.accessor((row) => row?.[col.key], { id: col.key, header: col.name, size: col.size }));
	}, [columns]);

	// The v9 pinning feature reads `state.columnPinning.{start,end}` directly (no defaulting
	// when a partial object is supplied), so `column.getIsPinned()` throws on a bare `{}`.
	// Normalize to a complete shape so callers may pass `{}` for "nothing pinned".
	const normalizedPinning = useMemo<ColumnPinningState>(
		() => ({ start: columnPinning.start ?? [], end: columnPinning.end ?? [] }),
		[columnPinning]
	);

	// `useTable` returns a new object whenever this options object is new: memoized, the table
	// (and the header and row components memoized on what it gives) keeps its identity.
	const options = useMemo(
		() => ({
			features: sheetsTableFeatures,
			columns: columnDefs,
			data: NO_ROWS,
			enableColumnPinning: true,
			enableColumnResizing: true,
			columnResizeMode: 'onChange' as ColumnResizeMode,
			// Controlled: our reducer/store is the source of truth for these slices.
			state: { columnSizing, columnPinning: normalizedPinning },
			onColumnSizingChange,
			onColumnPinningChange
		}),
		[columnDefs, columnSizing, normalizedPinning, onColumnSizingChange, onColumnPinningChange]
	);

	// Subscribe to NOTHING (`() => null`). v9 `useTable` runs `table.setOptions(...)` DURING render
	// to sync the controlled `state` above into its @tanstack/store atoms; a broad selector would make
	// THIS component a store subscriber, so that render-phase write notifies it synchronously →
	// `forceStoreRerender` → React's "Cannot update a component while rendering" warning. The slices
	// are caller-owned (the shell is the single source of truth) and the DOM grid reads layout via direct
	// table methods (getSize/getIsPinned), not `table.state`, so no subscription is needed —
	// the grid already re-renders from the shell's own state. (TanStack production-readiness: prefer
	// `() => null` + `table.Subscribe` over a broad `() => state` selector.)
	return useTable(options, (): null => null);
}

// Bucket limits checked before an upload, so a file the bucket would refuse is
// refused in the browser with a precise message and no request.
//
// The limits are columns of the storage module's buckets table, read through
// the storage-side table model. The storage module generates these columns
// with fixed names (`key`, `is_public`, `max_file_size`, `allowed_mime_types`;
// the upload mutation reads them by the same names), so they are looked up by
// their API field names. A missing column skips that check; the server still
// enforces every limit, so a skipped check only costs a round trip.
//
// The bucket rows are read once per storage plane and cached. Which row applies:
//   1. the configured bucket key;
//   2. the bucket an earlier upload of this plane and access landed in;
//   3. the only visible bucket with the requested access (the server resolves
//      the default bucket under the caller's visibility, so with one visible
//      candidate it is that one).
// Otherwise nothing is checked before the upload.

import type { ColumnModel, TableModel } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsStorageTransport } from '../context/sheets-context';
import { formatFileSize } from '../utils/file.utils';
import type { PlaneDetails } from './storage-catalog';
import type { ResolvedUploadChoices } from './upload-config';

const BUCKET_COLUMNS = {
	key: 'key',
	isPublic: 'isPublic',
	maxFileSize: 'maxFileSize',
	allowedMimeTypes: 'allowedMimeTypes',
} as const;

/** Most bucket rows read for one plane. */
const BUCKET_PAGE_SIZE = 100;

export interface BucketLimits {
	/** Bucket key, for messages. */
	key: string | null;
	maxFileSize: number | null;
	allowedMimeTypes: readonly string[] | null;
}

interface BucketRow extends BucketLimits {
	id: unknown;
	isPublic: boolean | null;
}

const bucketRows = new WeakMap<SheetsStorageTransport, Map<string, Promise<BucketRow[] | null>>>();
/** Bucket id of the last upload per storage plane and access. */
const landedBuckets = new WeakMap<SheetsStorageTransport, Map<string, unknown>>();

function column(model: TableModel, name: string): ColumnModel | null {
	return model.columns.find((candidate) => candidate.name === name && candidate.readable) ?? null;
}

function numberOf(value: unknown): number | null {
	if (typeof value === 'number' && Number.isFinite(value)) return value;
	if (typeof value === 'string' && /^\d+$/.test(value)) return Number(value);
	return null;
}

async function readBucketRows(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'listRows'>,
	buckets: TableModel,
): Promise<BucketRow[] | null> {
	const keyField = buckets.primaryKey.length === 1 ? buckets.primaryKey[0]! : null;
	const hasLimits = column(buckets, BUCKET_COLUMNS.maxFileSize) || column(buckets, BUCKET_COLUMNS.allowedMimeTypes);
	if (!keyField || !hasLimits || !buckets.operations.list) return null;
	const { rows } = await adapter.listRows<Record<string, unknown>>(
		{ model: buckets, tableName: buckets.key },
		{ limit: BUCKET_PAGE_SIZE, includeTotalCount: false },
		storage.execute,
	);
	return rows.map((row) => ({
		id: row[keyField],
		key: typeof row[BUCKET_COLUMNS.key] === 'string' ? (row[BUCKET_COLUMNS.key] as string) : null,
		isPublic: typeof row[BUCKET_COLUMNS.isPublic] === 'boolean' ? (row[BUCKET_COLUMNS.isPublic] as boolean) : null,
		maxFileSize: numberOf(row[BUCKET_COLUMNS.maxFileSize]),
		allowedMimeTypes: Array.isArray(row[BUCKET_COLUMNS.allowedMimeTypes])
			? (row[BUCKET_COLUMNS.allowedMimeTypes] as unknown[]).filter((type): type is string => typeof type === 'string')
			: null,
	}));
}

function rowsFor(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'listRows'>,
	details: PlaneDetails,
): Promise<BucketRow[] | null> {
	if (!details.buckets) return Promise.resolve(null);
	let byPlane = bucketRows.get(storage);
	if (!byPlane) {
		byPlane = new Map();
		bucketRows.set(storage, byPlane);
	}
	const planeKey = details.plane.filesTableKey;
	const cached = byPlane.get(planeKey);
	if (cached) return cached;
	const request = readBucketRows(storage, adapter, details.buckets).catch((): null => {
		// Unreadable limits skip the pre-check; the next upload tries again.
		byPlane.delete(planeKey);
		return null;
	});
	byPlane.set(planeKey, request);
	return request;
}

function accessKey(details: PlaneDetails, choices: ResolvedUploadChoices): string {
	return `${details.plane.filesTableKey}|${choices.bucketKey ?? (choices.isPublic ? 'public' : 'private')}`;
}

/** Remember which bucket an upload landed in, so the next one is checked against it. */
export function rememberLandedBucket(
	storage: SheetsStorageTransport,
	details: PlaneDetails,
	choices: ResolvedUploadChoices,
	bucketId: unknown,
): void {
	if (bucketId == null) return;
	let byAccess = landedBuckets.get(storage);
	if (!byAccess) {
		byAccess = new Map();
		landedBuckets.set(storage, byAccess);
	}
	byAccess.set(accessKey(details, choices), bucketId);
}

/** The limits of the bucket an upload will land in, or null when that bucket is not known. */
export async function bucketLimitsFor(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'listRows'>,
	details: PlaneDetails,
	choices: ResolvedUploadChoices,
	requiresOwner: boolean,
): Promise<BucketLimits | null> {
	const rows = await rowsFor(storage, adapter, details);
	if (!rows) return null;
	if (choices.bucketKey) return rows.find((row) => row.key === choices.bucketKey) ?? null;
	const landed = landedBuckets.get(storage)?.get(accessKey(details, choices));
	if (landed != null) {
		const row = rows.find((candidate) => candidate.id === landed);
		if (row) return row;
	}
	// Owner-scoped buckets repeat per owner, so "the only one" proves nothing there.
	if (requiresOwner) return null;
	const candidates = rows.filter((row) => row.isPublic === choices.isPublic);
	return candidates.length === 1 ? candidates[0]! : null;
}

function typeAllowed(contentType: string, allowed: readonly string[]): boolean {
	return allowed.some((pattern) => {
		if (pattern === '*/*') return true;
		if (pattern.endsWith('/*')) return contentType.startsWith(pattern.slice(0, -1));
		return contentType === pattern;
	});
}

/** Why the bucket would refuse this file, in the server's own terms, or null when it would accept it. */
export function bucketRefusal(file: File, limits: BucketLimits | null): string | null {
	if (!limits) return null;
	if (limits.maxFileSize != null && file.size > limits.maxFileSize) {
		return `"${file.name}" is ${formatFileSize(file.size)}. This bucket accepts files up to ${formatFileSize(limits.maxFileSize)}.`;
	}
	const contentType = file.type || 'application/octet-stream';
	if (limits.allowedMimeTypes && limits.allowedMimeTypes.length > 0 && !typeAllowed(contentType, limits.allowedMimeTypes)) {
		return `"${file.name}" is a ${contentType} file. This bucket accepts ${limits.allowedMimeTypes.join(', ')}.`;
	}
	return null;
}

// Everything a file column needs from storage, resolved once per column:
// whether it can upload (and how), and how its previews are signed.
//
// Order of authority:
//   1. A host-injected uploader (`SheetsConfig.executeUpload`) owns uploads.
//   2. Otherwise the storage service's `_meta` names the upload mutation of
//      the column's files table (see `upload-binding.ts`).
//   3. A storage service whose `_meta` names none falls back to shape
//      discovery, and only when it finds exactly one upload mutation.

import { createError, type ColumnModel } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsStorageTransport } from '../context/sheets-context';
import type { SheetsUploadFn } from '../context/sheets-execute';
import {
	discoverSoleUploadCapability,
	fetchMediaDownloadUrls,
	requestDiscoveredUpload,
} from '../context/sheets-upload-discovery';
import { transferFile, withUnfinishedUpload, type FileProjection, type TransferOptions } from '../context/sheets-upload-presigned';
import { downloadUrlSourceOf, fetchDownloadUrls } from './download-urls';
import { planeUpload } from './plane-upload';
import { loadPlaneDetails, loadStorageCatalog } from './storage-catalog';
import { resolveUploadBinding } from './upload-binding';
import { uploadChoicesFor, type ResolvedUploadChoices, type SheetsUploadConfig } from './upload-config';

export interface SendFileOptions extends TransferOptions {
	/** The row the file is for, passed to a host-injected uploader. */
	recordId?: string | number;
}

/** Sends one file to storage and resolves to its projection. */
export type SendFile = (file: File, options?: SendFileOptions) => Promise<FileProjection>;

export type ColumnUploadState =
	| { status: 'ready'; send: SendFile }
	| { status: 'unavailable'; reason: string };

export interface ColumnStorage {
	choices: ResolvedUploadChoices;
	upload: ColumnUploadState;
	/** Resolves download URLs by file id, or null when this column's previews cannot be signed. */
	resolveUrls: ((ids: readonly string[]) => Promise<Map<string, string>>) | null;
	/** Identity of the URL resolver, for batching and caching. */
	previewKey: string | null;
}

export interface ColumnStorageTarget {
	storage: SheetsStorageTransport | undefined;
	adapter: Pick<SheetsBackendAdapter, 'fetchMeta' | 'fetchTableModel' | 'listRows'>;
	/** The data table that holds the column. */
	table: { key: string; name: string };
	column: Pick<ColumnModel, 'name' | 'value'>;
	config: SheetsUploadConfig | undefined;
	databaseId: string | null;
	/** Host-injected uploader, when the host supplies one. */
	executeUpload?: SheetsUploadFn;
}

export const NO_STORAGE_REASON = 'Uploads need a storage endpoint';

const LINK_NEEDS_PUBLIC_REASON = 'This column stores a link to each file, so it needs a public bucket.';

function hostUpload(executeUpload: SheetsUploadFn, target: ColumnStorageTarget): SendFile {
	return async (file, options) => {
		const { file: projection } = await executeUpload(file, undefined, {
			tableName: target.table.name,
			fieldName: target.column.name,
			recordId: options?.recordId,
			onProgress: options?.onProgress,
		});
		return projection;
	};
}

function discoveryStorage(storage: SheetsStorageTransport, choices: ResolvedUploadChoices, databaseId: string | null): ColumnStorage {
	const send: SendFile = async (file, options) => {
		const cap = await discoverSoleUploadCapability(storage);
		if (!cap.hasFileProjection) throw createError.badRequest('The storage service does not return the file details an upload needs.');
		try {
			const payload = await transferFile(file, (input, signal) => requestDiscoveredUpload(storage.execute, cap, {
				...input,
				...(choices.bucketKey ? { bucketKey: choices.bucketKey } : { isPublic: choices.isPublic }),
				...(databaseId ? { databaseId } : {}),
			}, signal), options);
			return payload.file;
		} catch (error) {
			throw withUnfinishedUpload(error, { filesType: cap.download?.fileTypeName ?? null });
		}
	};
	return {
		choices,
		upload: { status: 'ready', send },
		resolveUrls: (ids) => fetchMediaDownloadUrls(storage, () => ids),
		previewKey: `${storage.endpoint}|discovery`,
	};
}

/** Resolve the column's storage. Never throws for a deterministic "cannot": that is an unavailable state. */
export async function loadColumnStorage(target: ColumnStorageTarget): Promise<ColumnStorage> {
	const { storage, adapter, table, column, config, databaseId, executeUpload } = target;
	const choices = uploadChoicesFor(config, table, column.name);
	const file = column.value.file;
	const unavailable = (reason: string, resolveUrls: ColumnStorage['resolveUrls'] = null, previewKey: string | null = null): ColumnStorage =>
		({ choices, upload: { status: 'unavailable', reason }, resolveUrls, previewKey });

	if (file?.kind === 'attachment' && !choices.bucketKey && !choices.isPublic) return unavailable(LINK_NEEDS_PUBLIC_REASON);
	if (!storage) {
		return executeUpload
			? { choices, upload: { status: 'ready', send: hostUpload(executeUpload, target) }, resolveUrls: null, previewKey: null }
			: unavailable(NO_STORAGE_REASON);
	}

	const catalog = await loadStorageCatalog(storage, adapter);
	const binding = resolveUploadBinding(column, catalog, choices);
	if (binding.status === 'discovery') {
		const discovered = discoveryStorage(storage, choices, databaseId);
		return executeUpload ? { ...discovered, upload: { status: 'ready', send: hostUpload(executeUpload, target) } } : discovered;
	}
	if (binding.status === 'unavailable' || catalog.source !== 'meta') {
		// A host uploader decides where the file goes itself; only previews need the binding.
		if (executeUpload) return { choices, upload: { status: 'ready', send: hostUpload(executeUpload, target) }, resolveUrls: null, previewKey: null };
		return unavailable(binding.status === 'unavailable' ? binding.reason : 'Uploads are not enabled for this storage service.');
	}

	const details = await loadPlaneDetails(storage, adapter, catalog, binding.plane);
	const previewKey = `${storage.endpoint}|${details.plane.filesTableKey}`;
	const urlSource = downloadUrlSourceOf(storage, details);
	const resolveUrls = urlSource ? (ids: readonly string[]) => fetchDownloadUrls(urlSource, ids) : null;
	if (executeUpload) return { choices, upload: { status: 'ready', send: hostUpload(executeUpload, target) }, resolveUrls, previewKey };

	const upload = planeUpload(storage, adapter, details, { choices, databaseId });
	if (upload.status === 'unavailable') return unavailable(upload.reason, resolveUrls, previewKey);
	const send: SendFile = async (file, options) => (await upload.send(file, options)).file;
	return { choices, upload: { status: 'ready', send }, resolveUrls, previewKey };
}

// Download URLs for stored files, read in batches through the model of the
// files table: its list field, its filter argument, its key column and the
// download URL field `_meta.storage` names. One request per batch with the
// key's `in` operator; one request per file when the key filter has only
// `equalTo`. A file the reader cannot see, or a field the schema lacks, simply
// has no URL: the cell then shows the file's name.

import type { ColumnModel, TableModel } from '@constructive-io/data';

import type { SheetsStorageTransport } from '../context/sheets-context';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import { fileKeyField, type PlaneDetails } from './storage-catalog';

/** Where download URLs are read: an executor and the files table model on that API. */
export interface DownloadUrlSource {
	execute: SheetsExecuteFn;
	files: TableModel;
	/** Field on the files type that returns the URL; checked against the schema by the caller. */
	downloadUrlField: string;
}

/** The download URL source of a storage plane, or null when its previews cannot be signed. */
export function downloadUrlSourceOf(storage: SheetsStorageTransport, details: PlaneDetails): DownloadUrlSource | null {
	if (!details.files || !details.hasDownloadUrl || !details.plane.downloadUrlField) return null;
	const source = { execute: storage.execute, files: details.files, downloadUrlField: details.plane.downloadUrlField };
	return urlQueryFor(source) ? source : null;
}

interface UrlQuery {
	keyColumn: ColumnModel;
	operator: 'in' | 'equalTo';
	source: string;
	variables: (ids: readonly string[]) => Record<string, unknown>;
	read: (data: unknown) => Array<Record<string, unknown> | null>;
}

function urlQueryFor({ files, downloadUrlField }: Omit<DownloadUrlSource, 'execute'>): UrlQuery | null {
	const keyField = fileKeyField(files);
	const keyColumn = files.columns.find((column) => column.name === keyField && column.readable);
	const list = files.operations.list;
	const filter = keyColumn?.filter;
	if (!keyColumn || !list?.filter || !filter) return null;
	const operators = new Set(filter.operators.map((operator) => operator.name));
	const operator = operators.has('in') ? 'in' : operators.has('equalTo') ? 'equalTo' : null;
	if (!operator) return null;
	const first = list.first ? `, $first: ${list.first.type}` : '';
	const firstArg = list.first ? `, ${list.first.name}: $first` : '';
	const nodes = `{ ${keyColumn.name} ${downloadUrlField} }`;
	const selection = list.shape === 'connection' ? `{ nodes ${nodes} }` : nodes;
	return {
		keyColumn,
		operator,
		source: `query SheetsFileDownloadUrls($where: ${list.filter.type}${first}) { ${list.field}(${list.filter.name}: $where${firstArg}) ${selection} }`,
		variables: (ids) => ({
			where: { [filter.field]: operator === 'in' ? { in: ids } : { equalTo: ids[0] } },
			...(list.first ? { first: ids.length } : {}),
		}),
		read: (data) => {
			const value = (data as Record<string, unknown> | null)?.[list.field];
			const rows = list.shape === 'connection' ? (value as { nodes?: unknown } | null)?.nodes : value;
			return Array.isArray(rows) ? (rows as Array<Record<string, unknown> | null>) : [];
		},
	};
}

/** Download URLs by file id. Ids without a URL have no entry. */
export async function fetchDownloadUrls(source: DownloadUrlSource, ids: readonly string[]): Promise<Map<string, string>> {
	const urls = new Map<string, string>();
	const query = urlQueryFor(source);
	if (ids.length === 0 || !query) return urls;
	const collect = (data: unknown) => {
		for (const row of query.read(data)) {
			const id = row?.[query.keyColumn.name];
			const url = row?.[source.downloadUrlField];
			if (typeof id === 'string' && typeof url === 'string' && url) urls.set(id, url);
		}
	};
	if (query.operator === 'in') {
		collect(await source.execute(query.source, query.variables(ids)));
	} else {
		const results = await Promise.allSettled(ids.map((id) => source.execute(query.source, query.variables([id]))));
		for (const result of results) if (result.status === 'fulfilled') collect(result.value);
	}
	return urls;
}

// The drop target of the file editor: drop files, or press Enter or Space (or
// click) to pick them. Paste is handled by the editor around it.

import { useState } from 'react';
import type React from 'react';
import { UploadIcon } from 'lucide-react';

import { cn } from '../../utils/cn';
import { ADD_CONTROL } from './use-editor-focus';

interface FileDropzoneProps {
	/** What to call the files: "image", "file", "files". */
	noun: string;
	hint: string;
	disabled: boolean;
	onPick: () => void;
	onFiles: (files: File[]) => void;
	compact: boolean;
}

export function FileDropzone({ noun, hint, disabled, onPick, onFiles, compact }: FileDropzoneProps) {
	const [dragging, setDragging] = useState(false);

	const onDrag = (event: React.DragEvent, active: boolean) => {
		event.preventDefault();
		event.stopPropagation();
		if (!disabled) setDragging(active);
	};

	return (
		<div
			role="button"
			tabIndex={disabled ? -1 : 0}
			aria-disabled={disabled || undefined}
			aria-label={`Drop ${noun} here or press Enter to browse`}
			data-slot="file-dropzone"
			data-initial-focus={ADD_CONTROL}
			data-dragging={dragging || undefined}
			className={cn(
				// Same corner as the file rows above it; the full border token keeps the dashed edge visible in dark mode.
				'flex w-full cursor-pointer flex-col items-center justify-center rounded-md border border-dashed border-border',
				// Hover is instant: no transition on the highlight.
				'bg-muted/20 text-center outline-hidden hover:bg-muted/30',
				'focus-visible:ring-[3px] focus-visible:ring-ring/50',
				'data-[dragging=true]:border-primary/40 data-[dragging=true]:bg-accent/50',
				compact ? 'gap-1 px-4 py-3' : 'gap-2 px-4 py-6',
				disabled && 'pointer-events-none opacity-50',
			)}
			onClick={disabled ? undefined : onPick}
			onKeyDown={(event) => {
				if (disabled || (event.key !== 'Enter' && event.key !== ' ')) return;
				if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) return;
				event.preventDefault();
				onPick();
			}}
			onDragEnter={(event) => onDrag(event, true)}
			onDragOver={(event) => onDrag(event, true)}
			onDragLeave={(event) => onDrag(event, false)}
			onDrop={(event) => {
				onDrag(event, false);
				if (disabled) return;
				const files = Array.from(event.dataTransfer.files);
				if (files.length > 0) onFiles(files);
			}}
		>
			{!compact ? (
				<span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-muted/60" aria-hidden="true">
					<UploadIcon className="size-4 text-muted-foreground" />
				</span>
			) : null}
			<span className="text-sm font-medium">Drop {noun} here or browse</span>
			<span className="text-xs text-muted-foreground">{hint}</span>
		</div>
	);
}

// One file in the file editor: preview, name, type and size, upload progress,
// and its actions (open, move, remove or cancel). Every action is a button or
// a link, so it works with Tab, Enter and Space.

import { AlertCircleIcon, ArrowDownIcon, ArrowUpIcon, ExternalLinkIcon, FileIcon, LinkIcon, XIcon } from 'lucide-react';

import type { ColumnFileModel } from '@constructive-io/data';

import { useSheetsMediaUrl, type MediaUrlResolver } from '../../hooks/use-sheets-media-url';
import { cn } from '../../utils/cn';
import { fileDetails, fileLabel, fileTypeLabel, formatFileSize, isImageFile } from '../../utils/file.utils';
import type { FileEntry } from './use-file-editor';

interface FileEntryRowProps {
	entry: FileEntry;
	kind: ColumnFileModel['kind'];
	resolver: MediaUrlResolver | null | undefined;
	/** List columns can reorder; a single-file column has no position. */
	reorder: { index: number; count: number } | null;
	disabled: boolean;
	readOnly: boolean;
	onMove: (delta: -1 | 1) => void;
	onRemove: () => void;
}

const ICON_BUTTON = cn(
	// Hover is instant: no transition on the highlight.
	'flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-hidden',
	'hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50',
	'disabled:pointer-events-none disabled:opacity-40',
);

function details(entry: FileEntry): string {
	if (entry.file) {
		return [fileTypeLabel(entry.file.type || null, entry.file.name), formatFileSize(entry.file.size)].filter(Boolean).join(' • ');
	}
	if (!entry.stored) return '';
	return [fileTypeLabel(entry.stored.mime, fileLabel(entry.stored)), entry.stored.size != null ? formatFileSize(entry.stored.size) : null]
		.filter(Boolean)
		.join(' • ');
}

export function FileEntryRow({ entry, kind, resolver, reorder, disabled, readOnly, onMove, onRemove }: FileEntryRowProps) {
	const stored = entry.stored;
	const name = entry.file?.name ?? (stored ? fileLabel(stored) : 'File');
	const showsImage = entry.file ? entry.file.type.startsWith('image/') : stored ? kind !== 'attachment' && isImageFile(stored, kind) : false;
	// A stored file resolves its URL for opening even when it is not an image.
	const media = useSheetsMediaUrl(stored?.raw ?? null, { previewImage: Boolean(stored), resolver });
	const openUrl = stored ? media.url : null;
	const previewUrl = entry.previewUrl ?? (showsImage ? media.url : null);
	const Icon = kind === 'attachment' ? LinkIcon : FileIcon;
	const uploading = entry.status === 'uploading';
	// A single-file cell keeps the short labels; a list names each file.
	const removeLabel = uploading
		? `Cancel upload of ${name}`
		: reorder ? `Remove ${name}` : previewUrl ? 'Remove image' : 'Remove file';

	return (
		<li
			data-slot="file-entry"
			data-status={entry.status}
			className="flex items-center gap-3 rounded-md border border-border/60 bg-background py-1 ps-1 pe-2"
		>
			{/* The preview sits 5px inside the row (4px padding and the border), so its corner is the row's 8px less 5px. */}
			<div className="relative flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-[3px] bg-muted" aria-hidden="true">
				{previewUrl ? (
					<img
						src={previewUrl}
						alt=""
						className="absolute inset-0 size-full rounded-[3px] object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10"
						onError={entry.previewUrl ? undefined : media.onImageError}
						onLoad={entry.previewUrl ? undefined : media.onImageLoad}
					/>
				) : (
					<Icon className="size-4 text-muted-foreground" />
				)}
			</div>
			<div className="min-w-0 flex-1">
				<p className="truncate text-sm font-medium" title={stored ? fileDetails(stored) : name}>{name}</p>
				{entry.status === 'failed' ? (
					<p className="mt-0.5 flex items-center gap-1 text-xs text-destructive" role="alert">
						<AlertCircleIcon className="size-3 shrink-0" aria-hidden="true" />
						<span className="truncate" title={entry.error ?? undefined}>{entry.error ?? 'Upload failed'}</span>
					</p>
				) : uploading ? (
					<div
						role="progressbar"
						aria-label={`Uploading ${name}`}
						aria-valuemin={0}
						aria-valuemax={100}
						aria-valuenow={entry.progress ?? 0}
						className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted"
					>
						<div
							className="h-1 rounded-full bg-primary transition-[width] duration-(--duration-slow)"
							style={{ width: `${entry.progress ?? 0}%` }}
						/>
					</div>
				) : (
					<p className="mt-0.5 truncate text-xs text-muted-foreground tabular-nums">
						{entry.status === 'selected' ? `${details(entry)} • Not uploaded yet` : details(entry)}
					</p>
				)}
			</div>
			<div className="flex shrink-0 items-center gap-0.5">
				{openUrl ? (
					<a
						href={openUrl}
						target="_blank"
						rel="noreferrer"
						download={stored?.filename ?? undefined}
						className={ICON_BUTTON}
						aria-label={`Open ${name}`}
						title="Open or download"
					>
						<ExternalLinkIcon className="size-3.5" aria-hidden="true" />
					</a>
				) : null}
				{reorder && !readOnly ? (
					<>
						<button
							type="button"
							className={ICON_BUTTON}
							aria-label={`Move ${name} up`}
							disabled={disabled || reorder.index === 0}
							onClick={() => onMove(-1)}
						>
							<ArrowUpIcon className="size-3.5" aria-hidden="true" />
						</button>
						<button
							type="button"
							className={ICON_BUTTON}
							aria-label={`Move ${name} down`}
							disabled={disabled || reorder.index === reorder.count - 1}
							onClick={() => onMove(1)}
						>
							<ArrowDownIcon className="size-3.5" aria-hidden="true" />
						</button>
					</>
				) : null}
				{!readOnly ? (
					<button
						type="button"
						className={ICON_BUTTON}
						aria-label={removeLabel}
						title={uploading ? 'Cancel upload' : 'Remove'}
						disabled={disabled && !uploading}
						onClick={onRemove}
					>
						<XIcon className="size-3.5" aria-hidden="true" />
					</button>
				) : null}
			</div>
		</li>
	);
}

// Keyboard focus in the file editor.
//
// First focus goes to the control that adds a file (the dropzone, or "Replace"),
// or to Close or Cancel when the editor cannot take a file. Not to the first
// file's first action: that is an "Open" link, which a held Enter would follow.
//
// Focus also comes back when the focused control goes away: a removed file row,
// or a button that turns disabled while an upload runs. The browser then moves
// focus to the page body, where Escape and Tab no longer reach the editor.

import { useCallback, useEffect, useRef, type RefObject } from 'react';

/** Marks the control that adds a file. */
export const ADD_CONTROL = 'add';
/** Marks the Close or Cancel button. */
export const CLOSE_CONTROL = 'close';

function focusTarget(root: HTMLElement): HTMLElement | null {
	return root.querySelector<HTMLElement>(`[data-initial-focus="${ADD_CONTROL}"]:not([aria-disabled="true"]):not([disabled])`)
		?? root.querySelector<HTMLElement>(`[data-initial-focus="${CLOSE_CONTROL}"]:not([disabled])`);
}

function focusIsLost(): boolean {
	const active = document.activeElement;
	return !active || active === document.body || active === document.documentElement;
}

/**
 * `canAdd` is true once the editor can take a file (storage resolved, nothing
 * running). An editor that opened before that has focus on Close or Cancel; it
 * moves to the add control when it appears, unless the user has moved on.
 */
export function useEditorFocus(rootRef: RefObject<HTMLElement | null>, canAdd: boolean): void {
	const placed = useRef<HTMLElement | null>(null);

	const recover = useCallback(() => {
		const root = rootRef.current;
		if (root?.isConnected && focusIsLost()) focusTarget(root)?.focus();
	}, [rootRef]);

	// A passive effect, so it runs after the focus traps' own first focus.
	useEffect(() => {
		const root = rootRef.current;
		const target = root ? focusTarget(root) : null;
		target?.focus();
		placed.current = target;
	}, [rootRef]);

	useEffect(() => {
		const root = rootRef.current;
		const first = placed.current;
		if (!canAdd || !root || !first || document.activeElement !== first || first.dataset.initialFocus !== CLOSE_CONTROL) return;
		const target = focusTarget(root);
		if (target && target !== first) {
			target.focus();
			placed.current = target;
		}
	}, [canAdd, rootRef]);

	useEffect(() => {
		const root = rootRef.current;
		if (!root) return;
		// Focus leaving for nowhere (no related target): a removed control leaves at once,
		// a disabled one on the browser's next rendering step. Check once it has settled.
		let timer: ReturnType<typeof setTimeout> | undefined;
		const onFocusOut = (event: FocusEvent) => {
			if (event.relatedTarget) return;
			clearTimeout(timer);
			timer = setTimeout(recover, 0);
		};
		root.addEventListener('focusout', onFocusOut);
		return () => {
			root.removeEventListener('focusout', onFocusOut);
			clearTimeout(timer);
		};
	}, [recover, rootRef]);
}

// State of the file editor: the files a cell will hold, the uploads in flight,
// and the save sequence.
//
// Save runs in order:
//   1. a draft row is created first, and its key is read from the created row
//      with the table model's primary key (so a key without a default works);
//   2. new files upload, at most UPLOAD_CONCURRENCY at a time, each with its own
//      progress and cancel; a failed file keeps its error and a retry, and the
//      others keep their uploads;
//   3. the cell is written once with the whole value (one file, a list in the
//      order shown, or null), waiting out the server's file confirmation.
// Cancel aborts the uploads in flight. The server expires a file row whose PUT
// never finished, so a cancelled upload leaves nothing behind.

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import type { ColumnModel, TableModel } from '@constructive-io/data';

import { isAbortError } from '../../context/sheets-upload-presigned';
import { incompleteDraftMessage } from '../../grid/draft-guidance';
import type { DraftSubmitResult } from '../../grid/draft-types';
import { cellElementFor, type FileCellWriteJob, type FileUploadState } from '../../hooks/use-sheets-upload';
import type { SheetsRowIdentifier } from '../../row-identity';
import { fileWriteMessage } from '../file-cell-write';
import { storedFilesOf, type StoredFile } from '../../utils/file.utils';

/** Uploads in flight at once, per editor. */
export const UPLOAD_CONCURRENCY = 3;

export type FileEntryStatus = 'stored' | 'selected' | 'uploading' | 'uploaded' | 'failed';

export interface FileEntry {
	/** Local key. */
	key: string;
	/** The stored file, for a file the cell already holds. */
	stored: StoredFile | null;
	/** The picked file, for a new one. */
	file: File | null;
	/** Object URL of a picked image, for its preview. */
	previewUrl: string | null;
	status: FileEntryStatus;
	/** Upload progress in percent, while uploading. */
	progress: number | null;
	error: string | null;
	/** The element the cell stores for this file, once known. */
	element: unknown;
}

export type FileEditorPhase =
	| { name: 'idle' }
	| { name: 'creating-row' }
	| { name: 'uploading' }
	| { name: 'saving' }
	| { name: 'processing' }
	| { name: 'failed'; message: string };

export interface SaveTarget {
	rowKey: SheetsRowIdentifier;
	/** Grid row id, which keys the cell's pending state. */
	rowId: string;
}

export interface UseFileEditorArgs {
	value: unknown;
	table: TableModel | null;
	column: ColumnModel | null;
	multiple: boolean;
	upload: FileUploadState;
	write: (job: FileCellWriteJob) => Promise<unknown>;
	/** The row, or null for a draft row that has not been created. */
	target: SaveTarget | null;
	submitDraft?: () => Promise<DraftSubmitResult>;
	/** The key and grid row id of a row the draft created, or null when its key cannot be read. */
	targetOfCreatedRow: (row: Record<string, unknown>) => SaveTarget | null;
	onUploadError?: (message: string) => void;
	/** Called once the draft row exists on the server. */
	onRowCreated?: () => void;
	onSaved: (saved: unknown, info: { createdRow: boolean }) => void;
}

let nextKey = 1;
const entryKey = () => `entry-${nextKey++}`;

function storedEntries(value: unknown, column: ColumnModel | null): FileEntry[] {
	return storedFilesOf(value, column?.value.file).map((stored): FileEntry => ({
		key: entryKey(),
		stored,
		file: null,
		previewUrl: null,
		status: 'stored',
		progress: null,
		error: null,
		element: stored.raw,
	}));
}

function isImageUpload(file: File): boolean {
	return file.type.startsWith('image/');
}

async function runPool<T>(items: readonly T[], limit: number, worker: (item: T) => Promise<void>): Promise<void> {
	let next = 0;
	const lanes = Array.from({ length: Math.min(limit, items.length) }, async () => {
		while (next < items.length) {
			const item = items[next]!;
			next += 1;
			await worker(item);
		}
	});
	await Promise.all(lanes);
}

export function useFileEditor(args: UseFileEditorArgs) {
	const { value, table, column, multiple, upload, write, target, submitDraft, targetOfCreatedRow, onUploadError, onRowCreated, onSaved } = args;
	// The files the cell held when the editor opened; a refetch while it is open does not reset the edit.
	const [initial] = useState(() => storedEntries(value, column));
	const [entries, setEntriesState] = useState<FileEntry[]>(initial);
	const [phase, setPhase] = useState<FileEditorPhase>({ name: 'idle' });
	const entriesRef = useRef(entries);
	const controllers = useRef(new Map<string, AbortController>());
	const committed = useRef<SaveTarget | null>(null);
	const mounted = useRef(true);
	/** Set when the user cancels an upload during a save: that save stops before writing. */
	const cancelled = useRef(false);

	const setEntries = useCallback((update: (current: FileEntry[]) => FileEntry[]) => {
		entriesRef.current = update(entriesRef.current);
		if (mounted.current) setEntriesState(entriesRef.current);
	}, []);
	const patch = useCallback((key: string, change: Partial<FileEntry>) => {
		setEntries((current) => current.map((entry) => (entry.key === key ? { ...entry, ...change } : entry)));
	}, [setEntries]);

	useEffect(() => {
		mounted.current = true;
		const active = controllers.current;
		return () => {
			mounted.current = false;
			for (const controller of active.values()) controller.abort();
			for (const entry of entriesRef.current) if (entry.previewUrl) URL.revokeObjectURL(entry.previewUrl);
		};
	}, []);

	const busy = phase.name === 'creating-row' || phase.name === 'uploading' || phase.name === 'saving' || phase.name === 'processing';

	const dirty = useMemo(() => {
		if (entries.length !== initial.length) return true;
		return entries.some((entry, index) => entry.file !== null || entry.stored !== initial[index]?.stored);
	}, [entries, initial]);

	const discard = useCallback((entry: FileEntry) => {
		const controller = controllers.current.get(entry.key);
		if (controller) {
			cancelled.current = true;
			controller.abort();
		}
		controllers.current.delete(entry.key);
		if (entry.previewUrl) URL.revokeObjectURL(entry.previewUrl);
	}, []);

	const addFiles = useCallback((files: readonly File[]) => {
		if (files.length === 0) return;
		const picked = (multiple ? files : files.slice(0, 1)).map((file): FileEntry => ({
			key: entryKey(),
			stored: null,
			file,
			previewUrl: isImageUpload(file) && typeof URL.createObjectURL === 'function' ? URL.createObjectURL(file) : null,
			status: 'selected',
			progress: null,
			error: null,
			element: undefined,
		}));
		setEntries((current) => {
			if (multiple) return [...current, ...picked];
			current.forEach(discard);
			return picked;
		});
		setPhase((current) => (current.name === 'failed' ? { name: 'idle' } : current));
	}, [discard, multiple, setEntries]);

	const remove = useCallback((key: string) => {
		setEntries((current) => {
			const entry = current.find((candidate) => candidate.key === key);
			if (entry) discard(entry);
			return current.filter((candidate) => candidate.key !== key);
		});
	}, [discard, setEntries]);

	const move = useCallback((key: string, delta: -1 | 1) => {
		setEntries((current) => {
			const index = current.findIndex((entry) => entry.key === key);
			const to = index + delta;
			if (index < 0 || to < 0 || to >= current.length) return current;
			const next = [...current];
			[next[index], next[to]] = [next[to]!, next[index]!];
			return next;
		});
	}, [setEntries]);

	const uploadEntry = useCallback(async (entry: FileEntry, recordId: string | number | undefined) => {
		if (upload.status !== 'ready' || !entry.file || !column) return;
		const controller = new AbortController();
		controllers.current.set(entry.key, controller);
		patch(entry.key, { status: 'uploading', progress: 0, error: null });
		try {
			const projection = await upload.send(entry.file, {
				recordId,
				signal: controller.signal,
				onProgress: ({ percentage }) => patch(entry.key, { progress: percentage }),
			});
			patch(entry.key, { status: 'uploaded', progress: 100, element: cellElementFor(column, projection, entry.file) });
		} catch (error) {
			if (controller.signal.aborted || isAbortError(error)) return;
			const message = error instanceof Error && error.message ? error.message : 'Upload failed';
			patch(entry.key, { status: 'failed', progress: null, error: message });
			onUploadError?.(message);
		} finally {
			controllers.current.delete(entry.key);
		}
	}, [column, onUploadError, patch, upload]);

	const save = useCallback(async () => {
		if (busy || !table || !column) return;
		try {
			let saveTarget = committed.current ?? target;
			if (!saveTarget) {
				if (!submitDraft) throw new Error('Save the row before adding a file.');
				setPhase({ name: 'creating-row' });
				const { createdRow: row, missing } = await submitDraft();
				// Save was refused before sending: the draft is still there, with the fields to fill.
				if (missing?.length) throw new Error(incompleteDraftMessage(missing));
				// The draft is gone from here on: the host refetches whatever happens next.
				onRowCreated?.();
				saveTarget = row ? targetOfCreatedRow(row) : null;
				if (!saveTarget) throw new Error('The row was created, but its key could not be read, so the file was not saved.');
				committed.current = saveTarget;
			}

			const pending = entriesRef.current.filter((entry) => entry.file && entry.status !== 'uploaded');
			if (pending.length > 0) {
				if (upload.status !== 'ready') {
					throw new Error(upload.status === 'unavailable' ? upload.reason : 'Storage is not ready yet.');
				}
				setPhase({ name: 'uploading' });
				cancelled.current = false;
				const recordId = typeof saveTarget.rowKey === 'object' ? undefined : saveTarget.rowKey;
				await runPool(pending, UPLOAD_CONCURRENCY, (entry) => uploadEntry(entry, recordId));
				if (!mounted.current) return;
				if (cancelled.current) {
					// A cancelled upload is not a request to save without it.
					cancelled.current = false;
					setPhase({ name: 'idle' });
					return;
				}
				const failed = entriesRef.current.filter((entry) => entry.status === 'failed').length;
				const unfinished = entriesRef.current.some((entry) => entry.file && entry.status !== 'uploaded');
				if (unfinished) {
					setPhase(failed
						? { name: 'failed', message: failed === 1 ? 'A file could not be uploaded.' : `${failed} files could not be uploaded.` }
						: { name: 'idle' });
					return;
				}
			}

			const elements = entriesRef.current.map((entry) => entry.element);
			const nextValue = multiple ? elements : elements[0] ?? null;
			setPhase({ name: 'saving' });
			const saved = await write({
				table,
				column,
				rowKey: saveTarget.rowKey,
				rowId: saveTarget.rowId,
				value: nextValue,
				onProcessing: () => {
					if (mounted.current) setPhase({ name: 'processing' });
				},
			});
			// After the editor closed, the cell shows the saved value from the refetch.
			if (!mounted.current) return;
			setPhase({ name: 'idle' });
			onSaved(saved, { createdRow: committed.current !== null });
		} catch (error) {
			if (isAbortError(error) || !mounted.current) return;
			setPhase({ name: 'failed', message: fileWriteMessage(error) });
		}
	}, [busy, column, multiple, onRowCreated, onSaved, submitDraft, table, target, targetOfCreatedRow, upload, uploadEntry, write]);

	/** Stop the uploads in flight. A write already sent keeps going and shows on the cell. */
	const cancelUploads = useCallback(() => {
		if (controllers.current.size > 0) cancelled.current = true;
		for (const controller of controllers.current.values()) controller.abort();
		controllers.current.clear();
	}, []);

	return {
		entries,
		phase,
		busy,
		dirty,
		/** True when the draft row still has to be created by the save. */
		needsRowCreation: !target && committed.current === null,
		addFiles,
		remove,
		move,
		save,
		cancelUploads,
	};
}

// Writing a file cell, including the wait for the server's file confirmation.
//
// A managed file column checks every new file document as it is written: the
// files row must be live (`uploaded` or `processed`). The upload mutation
// creates the row as `requested`, and a background job confirms the PUT later
// (by default about 30 seconds after the request). Until then the write is
// refused with the error code FILE_REF_FILE_NOT_LIVE and the context
// `{ field, file_id, status }` (constructive-db
// `ast_plpgsql_helpers.file_ref_guard_body`, raised through
// `errors.raise_error`; the GraphQL error carries the code as its message and
// in `extensions.code`). So the write is retried with backoff for a bounded
// time. A row the job `rejected` never becomes live, so that answer stops at once.

import { getErrorCode, toError, type ColumnModel, type TableModel } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import { responseErrorsOf, type SheetsExecuteFn } from '../context/sheets-execute';
import type { SheetsRowIdentifier } from '../row-identity';
import type { ProcessingPolicy } from './upload-config';

export const FILE_NOT_LIVE_CODE = 'FILE_REF_FILE_NOT_LIVE';

/** The write is waiting for the server to confirm the file. */
export class FileProcessingTimeoutError extends Error {
	constructor() {
		super('The file is still being processed, so it was not saved to this cell yet.');
		this.name = 'FileProcessingTimeoutError';
	}
}

/** Friendlier text for the file-reference refusals a managed file column raises. */
const FILE_REF_MESSAGES: Record<string, string> = {
	FILE_REF_FILE_NOT_LIVE: 'The storage service has not accepted this file.',
	FILE_REF_FILE_NOT_FOUND: 'This file could not be found, or you cannot see it.',
	FILE_REF_BUCKET_MISMATCH: 'This column keeps its files in a different bucket.',
	FILE_REF_ID_INVALID: 'This file reference is not valid.',
};

/** The status the server reported for a file that is not live, when it said. */
function notLiveStatus(error: unknown): string | null {
	const fromContext = toError(error).context?.status;
	if (typeof fromContext === 'string') return fromContext;
	const response = responseErrorsOf(error)?.find((candidate) => candidate.extensions?.code === FILE_NOT_LIVE_CODE);
	const status = response?.extensions?.context?.status;
	return typeof status === 'string' ? status : null;
}

function isNotLive(error: unknown): boolean {
	if (getErrorCode(error) === FILE_NOT_LIVE_CODE) return true;
	return Boolean(responseErrorsOf(error)?.some((candidate) =>
		candidate.extensions?.code === FILE_NOT_LIVE_CODE || candidate.message === FILE_NOT_LIVE_CODE));
}

/** A user-facing message for a failed file write. */
export function fileWriteMessage(error: unknown): string {
	if (error instanceof FileProcessingTimeoutError) return error.message;
	const code = getErrorCode(error);
	if (code === FILE_NOT_LIVE_CODE && notLiveStatus(error) === 'rejected') {
		return 'The storage service rejected this file (its contents did not match what was uploaded).';
	}
	if (code && FILE_REF_MESSAGES[code]) return FILE_REF_MESSAGES[code]!;
	return error instanceof Error && error.message ? error.message : 'The file could not be saved.';
}

function wait(ms: number, signal?: AbortSignal): Promise<void> {
	return new Promise((resolve, reject) => {
		if (signal?.aborted) {
			reject(signal.reason ?? new Error('Cancelled'));
			return;
		}
		const timer = setTimeout(() => {
			signal?.removeEventListener('abort', onAbort);
			resolve();
		}, ms);
		const onAbort = () => {
			clearTimeout(timer);
			reject(signal?.reason ?? new Error('Cancelled'));
		};
		signal?.addEventListener('abort', onAbort, { once: true });
	});
}

export interface FileCellWrite {
	adapter: Pick<SheetsBackendAdapter, 'updateRow'>;
	execute: SheetsExecuteFn;
	model: TableModel;
	column: ColumnModel;
	rowKey: SheetsRowIdentifier;
	/** The value to store: a projection, a link, a list, or null to clear. */
	value: unknown;
	policy: ProcessingPolicy;
	/** Called once when the first write is refused because the file is still processing. */
	onProcessing?: () => void;
	signal?: AbortSignal;
}

/** Write the cell and return the stored value. Waits out FILE_REF_FILE_NOT_LIVE within the policy. */
export async function writeFileCell(write: FileCellWrite): Promise<unknown> {
	const { adapter, execute, model, column, rowKey, value, policy, signal } = write;
	const started = Date.now();
	let delay = policy.initialDelayMs;
	let announced = false;
	for (;;) {
		try {
			const row = await adapter.updateRow<Record<string, unknown>>(
				{ model, tableName: model.key },
				rowKey,
				{ [column.name]: value },
				execute,
				{ returning: [column.name] },
			);
			if (!row || !Object.prototype.hasOwnProperty.call(row, column.name)) {
				throw new Error(`The update did not return "${column.name}".`);
			}
			return row[column.name];
		} catch (error) {
			if (!isNotLive(error) || notLiveStatus(error) === 'rejected') throw error;
			if (Date.now() - started + delay > policy.timeoutMs) throw new FileProcessingTimeoutError();
			if (!announced) {
				announced = true;
				write.onProcessing?.();
			}
			await wait(delay, signal);
			delay = Math.min(delay * 2, policy.maxDelayMs);
		}
	}
}

// A preview column for a storage files table (`table.storage.role === 'files'`):
// each row shows its file (a thumbnail for an image) and a download link. This
// is not a storage browser; the files table's own columns stay as they are.
//
// The URL comes from the files type's download URL field (`_meta.storage`
// names it, and a `__type` lookup confirms the API has it), read in batches
// through the table's own list field and key filter on the data endpoint.
//
// Two columns of the storage module are read by their API names for display
// only: `mimeType` (whether to show a thumbnail) and `filename`. Without them
// the row shows its key and no thumbnail.

import { useQuery } from '@tanstack/react-query';
import { DownloadIcon, FileIcon } from 'lucide-react';

import { createSchemaTypeLoader, type SchemaTypeLoader, type TableModel } from '@constructive-io/data';

import type { CellProps } from '../cell-model/cell-props';
import type { SheetsCellResolution } from '../grid-dom/use-sheets-content';
import { useSheetsContext } from '../context/sheets-context';
import type { SheetsExecuteFn } from '../context/sheets-execute';
import { sheetsQueryKeys } from '../hooks/query-keys';
import { useSheetsMediaUrl, type MediaUrlResolver } from '../hooks/use-sheets-media-url';
import { cn } from '../utils/cn';
import { basename } from '../utils/file.utils';
import { fetchDownloadUrls, type DownloadUrlSource } from './download-urls';
import { fileKeyField } from './storage-catalog';

export const FILE_PREVIEW_COLUMN_KEY = '__file_preview__';

const FILE_COLUMNS = { mime: 'mimeType', filename: 'filename', key: 'key' } as const;

/** The preview column of a files table, or null for any other table. */
export function filesTablePreviewColumn(table: TableModel | null | undefined): { id: string; title: string; width: number } | null {
	if (table?.storage?.role !== 'files' || !table.storage.downloadUrlField || !fileKeyField(table) || !table.operations.list) return null;
	return { id: FILE_PREVIEW_COLUMN_KEY, title: 'File', width: 168 };
}

/** Resolve the preview column's cells; every other cell goes to `resolve`. */
export function withFilePreviewCells(
	resolve: (rowIndex: number, colKey: string) => SheetsCellResolution,
	/** The row at an index, read when a cell resolves (the latest rows). */
	rowAt: (rowIndex: number) => unknown,
	table: TableModel | null | undefined,
): (rowIndex: number, colKey: string) => SheetsCellResolution {
	if (!filesTablePreviewColumn(table)) return resolve;
	return (rowIndex, colKey) => {
		if (colKey !== FILE_PREVIEW_COLUMN_KEY) return resolve(rowIndex, colKey);
		const row = rowAt(rowIndex);
		return {
			cell: { kind: row ? 'custom' : 'loading', data: row ?? null, displayData: '', readonly: true, meta: { table } },
			component: row ? FileRowPreviewCellView : undefined,
			colKey,
			typeKey: 'file-preview',
			column: null,
			relation: null,
		};
	};
}

const loaders = new WeakMap<SheetsExecuteFn, SchemaTypeLoader>();

async function readSource(execute: SheetsExecuteFn, table: TableModel): Promise<DownloadUrlSource | null> {
	const field = table.storage?.downloadUrlField;
	if (!field) return null;
	let loader = loaders.get(execute);
	if (!loader) {
		loader = createSchemaTypeLoader();
		loaders.set(execute, loader);
	}
	await loader.loadTypes(execute, [table.name]);
	const type = loader.index.get(table.name);
	return type?.fields?.some((candidate) => candidate.name === field) ? { execute, files: table, downloadUrlField: field } : null;
}

function useFilesTableResolver(table: TableModel | null): MediaUrlResolver | null {
	const { execute, scopeKey } = useSheetsContext();
	const query = useQuery({
		queryKey: [...sheetsQueryKeys.scope(scopeKey), 'files-table-download', table?.key ?? ''],
		queryFn: () => readSource(execute, table!),
		enabled: Boolean(table),
		staleTime: Number.POSITIVE_INFINITY,
		structuralSharing: false,
	});
	const source = query.data;
	return source && table ? { key: `data|${table.key}`, resolve: (ids) => fetchDownloadUrls(source, ids) } : null;
}

function text(row: Record<string, unknown>, name: string): string | null {
	const value = row[name];
	return typeof value === 'string' && value ? value : null;
}

/** The preview cell of one files-table row: thumbnail or icon, name, and a download link. */
export function FileRowPreviewCellView(props: CellProps) {
	const table = ((props.cell.meta as { table?: TableModel } | undefined)?.table) ?? null;
	const row = (props.cell.data ?? {}) as Record<string, unknown>;
	const keyField = fileKeyField(table);
	const id = keyField && typeof row[keyField] === 'string' ? (row[keyField] as string) : null;
	const mime = text(row, FILE_COLUMNS.mime);
	const objectKey = text(row, FILE_COLUMNS.key);
	const name = text(row, FILE_COLUMNS.filename) ?? (objectKey ? basename(objectKey) : 'File');
	const resolver = useFilesTableResolver(table);
	const isImage = Boolean(mime?.startsWith('image/'));
	const { url, onImageError, onImageLoad } = useSheetsMediaUrl(id ? { id } : null, { previewImage: true, resolver });

	return (
		<div data-slot="file-preview-cell" className="flex h-full w-full items-center gap-2 overflow-hidden ps-3 pe-1.5">
			<span className="relative flex aspect-square h-full max-h-7 shrink-0 items-center justify-center overflow-hidden rounded-sm bg-muted" aria-hidden="true">
				{isImage && url ? (
					<img src={url} alt="" decoding="async" onError={onImageError} onLoad={onImageLoad} className="absolute inset-0 size-full rounded-sm object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10" />
				) : (
					<FileIcon className="size-3.5 text-muted-foreground" />
				)}
			</span>
			<span className="min-w-0 flex-1 truncate text-sm" title={mime ? `${name}\n${mime}` : name}>{name}</span>
			{url ? (
				<a
					href={url}
					target="_blank"
					rel="noreferrer"
					download={name}
					aria-label={`Download ${name}`}
					title="Download"
					onClick={(event) => event.stopPropagation()}
					onDoubleClick={(event) => event.stopPropagation()}
					className={cn(
						'flex size-6 shrink-0 items-center justify-center rounded-sm text-muted-foreground outline-hidden',
						'hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50',
					)}
				>
					<DownloadIcon className="size-3.5" aria-hidden="true" />
				</a>
			) : (
				<span className="flex size-6 shrink-0 items-center justify-center text-xs text-muted-foreground" title="The file is not available for download yet.">—</span>
			)}
		</div>
	);
}

// File cell writes that outlive the editor: while the server confirms a new
// file, the cell shows "Processing file…"; if the wait runs out or the write
// fails, the cell shows that the file was not saved and offers a retry. The
// uploaded file is never dropped silently.
//
// One store per Sheets scope (endpoint, database, user), keyed by table, grid
// row id and column.

import { useCallback, useSyncExternalStore } from 'react';

import type { SheetsScopeKey } from '../context/sheets-context';

export type PendingFileWrite =
	| { status: 'processing' }
	| { status: 'failed'; message: string; retry: () => void; dismiss: () => void };

type Listener = () => void;

class PendingFileWrites {
	private readonly entries = new Map<string, PendingFileWrite>();
	private readonly listeners = new Set<Listener>();

	get(key: string): PendingFileWrite | null {
		return this.entries.get(key) ?? null;
	}

	set(key: string, entry: PendingFileWrite | null): void {
		if (entry) this.entries.set(key, entry);
		else this.entries.delete(key);
		for (const listener of this.listeners) listener();
	}

	subscribe = (listener: Listener): (() => void) => {
		this.listeners.add(listener);
		return () => this.listeners.delete(listener);
	};
}

const stores = new WeakMap<SheetsScopeKey, PendingFileWrites>();

function storeFor(scope: SheetsScopeKey): PendingFileWrites {
	let store = stores.get(scope);
	if (!store) {
		store = new PendingFileWrites();
		stores.set(scope, store);
	}
	return store;
}

export function pendingWriteKey(tableKey: string, rowId: string, column: string): string {
	return JSON.stringify([tableKey, rowId, column]);
}

export function setPendingFileWrite(scope: SheetsScopeKey, key: string, entry: PendingFileWrite | null): void {
	storeFor(scope).set(key, entry);
}

export function getPendingFileWrite(scope: SheetsScopeKey, key: string): PendingFileWrite | null {
	return storeFor(scope).get(key);
}

/** The pending write of one cell, or null. */
export function usePendingFileWrite(scope: SheetsScopeKey, key: string | null): PendingFileWrite | null {
	const store = storeFor(scope);
	const read = useCallback(() => (key ? store.get(key) : null), [store, key]);
	return useSyncExternalStore(store.subscribe, read, read);
}

// Upload into one storage plane through the model: the plane's upload mutation
// as the storage schema declares it, the bucket's limits checked first, then the
// shared transfer (hash, request, PUT with the returned headers, one renewal of
// an expired URL). Both the grid's file columns and `uploadToFilesTable` use it.
// A file row an unfinished upload leaves is never deleted here; the error names
// it and its files table (`unfinishedUploadOf`), and the storage service expires it.

import { createError } from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsStorageTransport } from '../context/sheets-context';
import { transferFile, withUnfinishedUpload, type TransferOptions, type UploadPayload } from '../context/sheets-upload-presigned';
import { bucketLimitsFor, bucketRefusal, rememberLandedBucket } from './bucket-limits';
import type { PlaneDetails } from './storage-catalog';
import { createUploadRequester, uploadOperationProblem, type UploadRequestContext } from './upload-request';

export type PlaneUpload =
	| { status: 'ready'; send: (file: File, options?: TransferOptions) => Promise<UploadPayload> }
	| { status: 'unavailable'; reason: string };

const NOT_ENABLED_REASON = 'Uploads are not enabled for this storage service.';

/** The plane's uploader with these choices, or why it cannot upload. Never throws. */
export function planeUpload(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'listRows'>,
	details: PlaneDetails,
	context: UploadRequestContext,
): PlaneUpload {
	const op = details.upload;
	if (!op) return { status: 'unavailable', reason: details.uploadReason ?? NOT_ENABLED_REASON };
	const problem = uploadOperationProblem(op, context);
	if (problem) return { status: 'unavailable', reason: problem };

	const request = createUploadRequester(storage.execute, op, context);
	const requiresOwner = op.inputFields.some((field) => field.name === 'ownerId');
	const send = async (file: File, options?: TransferOptions): Promise<UploadPayload> => {
		const refusal = bucketRefusal(file, await bucketLimitsFor(storage, adapter, details, context.choices, requiresOwner));
		if (refusal) throw createError.badRequest(refusal);
		let payload: UploadPayload;
		try {
			payload = await transferFile(file, request, options);
		} catch (error) {
			// Name the files table beside the file id the error may carry.
			throw withUnfinishedUpload(error, { filesType: details.plane.filesType, filesTableKey: details.plane.filesTableKey });
		}
		rememberLandedBucket(storage, details, context.choices, payload.file.bucket_id);
		return payload;
	};
	return { status: 'ready', send };
}

// The storage planes a storage service offers, read from that service's own
// `_meta` and checked with targeted introspection on the same service.
//
// Uploads, download URL lookups and bucket reads all run on the storage
// endpoint, so every name they use comes from the storage endpoint too: the
// files table and its upload mutation from `_meta.storage`, the mutation's
// input fields and payload fields from `__type` lookups, the files and buckets
// tables' list fields and keys from their table models.
//
// A storage service whose `_meta` names no upload mutation (a server older than
// `MetaStorage.upload`, or one without `_meta`) falls back to the shape
// discovery in `context/sheets-upload-discovery.ts`. That fallback is the only
// place names are found by shape.

import {
	MetaContractError,
	createSchemaTypeLoader,
	metaTablesOf,
	namedTypeOf,
	printTypeRef,
	tableKeyOf,
	type IntrospectedInputValue,
	type MetaQuery,
	type SchemaTypeLoader,
	type TableModel,
} from '@constructive-io/data';

import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsStorageTransport } from '../context/sheets-context';

/** A files table on the storage service and the operation that uploads into it. */
export interface StoragePlane {
	/** GraphQL type name of the files table. */
	filesType: string;
	/** `TableModel.key` of the files table on the storage service. */
	filesTableKey: string;
	/** `TableModel.key` of the paired buckets table, or null when the server does not say. */
	bucketsTableKey: string | null;
	/** Field on the files type that returns a download URL, or null. */
	downloadUrlField: string | null;
	/** Root mutation that uploads one file. */
	uploadMutation: string;
	/** Input type of that mutation, as `_meta` names it, or null. */
	uploadInputType: string | null;
	/** Payload type of that mutation, as `_meta` names it, or null. */
	uploadPayloadType: string | null;
}

export type StorageCatalog =
	| { source: 'meta'; planes: readonly StoragePlane[]; meta: MetaQuery }
	/** The storage `_meta` names no upload mutation; uploads use shape discovery. */
	| { source: 'discovery' };

const catalogs = new WeakMap<SheetsStorageTransport, Promise<StorageCatalog>>();

function planesOf(meta: MetaQuery): StoragePlane[] {
	const tables = metaTablesOf(meta);
	const keyByName = new Map(tables.map((table) => [table.name, tableKeyOf(table)] as const));
	return tables.flatMap((table) => {
		const storage = table.storage;
		const mutation = storage?.upload?.mutation;
		if (!storage?.isFilesTable || !mutation) return [];
		return [{
			filesType: table.name,
			filesTableKey: tableKeyOf(table),
			bucketsTableKey: storage.bucketsType ? keyByName.get(storage.bucketsType) ?? null : null,
			downloadUrlField: storage.downloadUrlField ?? null,
			uploadMutation: mutation,
			uploadInputType: storage.upload?.inputType ?? null,
			uploadPayloadType: storage.upload?.payloadType ?? null,
		}];
	});
}

/**
 * The storage catalog of one storage transport, loaded once. A deterministic
 * answer (planes, or "use discovery") is kept; a failed request is not, so the
 * next caller tries again.
 */
export function loadStorageCatalog(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'fetchMeta'>,
): Promise<StorageCatalog> {
	const cached = catalogs.get(storage);
	if (cached) return cached;
	const request = (async (): Promise<StorageCatalog> => {
		try {
			const meta = await adapter.fetchMeta(storage.execute);
			const planes = planesOf(meta);
			return planes.length > 0 ? { source: 'meta', planes, meta } : { source: 'discovery' };
		} catch (error) {
			// An endpoint whose `_meta` contract does not match is answered by discovery.
			if (error instanceof MetaContractError) return { source: 'discovery' };
			throw error;
		}
	})();
	catalogs.set(storage, request);
	request.catch(() => {
		if (catalogs.get(storage) === request) catalogs.delete(storage);
	});
	return request;
}

// ============================================================================
// Plane details: the upload operation as the storage schema declares it
// ============================================================================

/** The upload mutation of a plane, checked against the storage schema. */
export interface UploadOperation {
	/** Root mutation field. */
	field: string;
	/** Argument that carries the input object. */
	argName: string;
	/** Printed type of that argument, for the variable definition. */
	argType: string;
	/** Input fields the mutation really accepts. */
	inputFields: readonly IntrospectedInputValue[];
	/** Payload fields the mutation really returns. */
	payloadFields: ReadonlySet<string>;
}

export interface PlaneDetails {
	plane: StoragePlane;
	/** The upload operation, or null with `uploadReason`. */
	upload: UploadOperation | null;
	uploadReason: string | null;
	/** True when the files type really has `downloadUrlField`. */
	hasDownloadUrl: boolean;
	/** Storage-side model of the files table, or null when it could not be built. */
	files: TableModel | null;
	/** Storage-side model of the buckets table, or null. */
	buckets: TableModel | null;
}

const NO_UPLOAD_REASON = 'The storage service does not offer uploads for this file table.';

const loaders = new WeakMap<SheetsStorageTransport, SchemaTypeLoader>();
const details = new WeakMap<SheetsStorageTransport, Map<string, Promise<PlaneDetails>>>();

function loaderFor(storage: SheetsStorageTransport): SchemaTypeLoader {
	let loader = loaders.get(storage);
	if (!loader) {
		loader = createSchemaTypeLoader();
		loaders.set(storage, loader);
	}
	return loader;
}

async function tableModel(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'fetchTableModel'>,
	meta: MetaQuery,
	tableKey: string | null,
): Promise<TableModel | null> {
	if (!tableKey) return null;
	try {
		return await adapter.fetchTableModel(storage.execute, meta, tableKey);
	} catch {
		// Without the model the plane still uploads; previews and limits degrade.
		return null;
	}
}

async function readPlaneDetails(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'fetchTableModel'>,
	meta: MetaQuery,
	plane: StoragePlane,
): Promise<PlaneDetails> {
	const loader = loaderFor(storage);
	const { execute } = storage;
	const roots = await loader.loadRoots(execute);
	const field = roots.mutation?.fields?.find((candidate) => candidate.name === plane.uploadMutation) ?? null;
	const arg = field
		? field.args.find((candidate) => namedTypeOf(candidate.type)?.name === plane.uploadInputType) ??
			(field.args.length === 1 ? field.args[0] : undefined)
		: undefined;
	const inputType = arg ? namedTypeOf(arg.type)?.name ?? null : null;
	const payloadType = field ? namedTypeOf(field.type)?.name ?? null : null;
	await loader.loadTypes(execute, [inputType, payloadType, plane.filesType].filter((name): name is string => Boolean(name)));

	const input = inputType ? loader.index.get(inputType) : null;
	const payload = payloadType ? loader.index.get(payloadType) : null;
	const filesType = loader.index.get(plane.filesType);
	const upload: UploadOperation | null = field && arg && input?.inputFields && payload?.fields
		? {
			field: field.name,
			argName: arg.name,
			argType: printTypeRef(arg.type),
			inputFields: input.inputFields,
			payloadFields: new Set(payload.fields.map((candidate) => candidate.name)),
		}
		: null;

	const [files, buckets] = await Promise.all([
		tableModel(storage, adapter, meta, plane.filesTableKey),
		tableModel(storage, adapter, meta, plane.bucketsTableKey),
	]);
	return {
		plane,
		upload,
		uploadReason: upload ? null : NO_UPLOAD_REASON,
		hasDownloadUrl: Boolean(
			plane.downloadUrlField && filesType?.fields?.some((candidate) => candidate.name === plane.downloadUrlField),
		),
		files,
		buckets,
	};
}

/** Details of one plane, loaded once per storage transport. A failed load is retried by the next caller. */
export function loadPlaneDetails(
	storage: SheetsStorageTransport,
	adapter: Pick<SheetsBackendAdapter, 'fetchTableModel'>,
	catalog: Extract<StorageCatalog, { source: 'meta' }>,
	plane: StoragePlane,
): Promise<PlaneDetails> {
	let byPlane = details.get(storage);
	if (!byPlane) {
		byPlane = new Map();
		details.set(storage, byPlane);
	}
	const cached = byPlane.get(plane.filesTableKey);
	if (cached) return cached;
	const request = readPlaneDetails(storage, adapter, catalog.meta, plane);
	byPlane.set(plane.filesTableKey, request);
	request.catch(() => {
		if (byPlane.get(plane.filesTableKey) === request) byPlane.delete(plane.filesTableKey);
	});
	return request;
}

/** The single primary-key field of a files table, or null when the key is composite or unknown. */
export function fileKeyField(files: TableModel | null): string | null {
	return files?.primaryKey.length === 1 ? files.primaryKey[0]! : null;
}

// Which files table a file column uploads into. Pure: no requests.
//
// The server binds a column to its files table (`MetaField.file.filesType`)
// when the API has exactly one. Otherwise the storage service's only files
// table is used, and with several the host must choose one
// (`SheetsConfig.upload.columns[table][column].filesType`, or
// `upload.filesType` for every column). Without a choice the column is
// read-only: the grid never picks a files table by name.

import type { ColumnModel } from '@constructive-io/data';

import type { ResolvedUploadChoices } from './upload-config';
import type { StorageCatalog, StoragePlane } from './storage-catalog';

export type UploadBinding =
	| { status: 'plane'; plane: StoragePlane }
	/** The storage `_meta` names no upload mutation: the fallback discovery decides (one plane only). */
	| { status: 'discovery' }
	| { status: 'unavailable'; reason: string };

export const SEVERAL_FILE_STORES_REASON =
	'The storage service has several file stores, and none is chosen for this column.';

export function resolveUploadBinding(
	column: Pick<ColumnModel, 'value'>,
	catalog: StorageCatalog,
	choices: ResolvedUploadChoices,
): UploadBinding {
	const file = column.value.file;
	if (!file) return { status: 'unavailable', reason: 'This column does not hold files.' };
	if (catalog.source === 'discovery') return { status: 'discovery' };

	const wanted = file.filesType ?? choices.filesType;
	if (wanted) {
		const plane = catalog.planes.find((candidate) => candidate.filesType === wanted);
		return plane
			? { status: 'plane', plane }
			: { status: 'unavailable', reason: `The storage service does not offer the file store "${wanted}" this column uses.` };
	}
	if (catalog.planes.length === 1) return { status: 'plane', plane: catalog.planes[0]! };
	return { status: 'unavailable', reason: SEVERAL_FILE_STORES_REASON };
}

// Host configuration for file uploads (`SheetsConfig.upload`).
//
// Every field is optional. A server that names the files table of each file
// column needs none of them: Sheets reads the upload operation from the
// storage service's own `_meta`. The fields below choose a bucket, supply an
// owner for entity-scoped storage, and bind columns the server leaves open.

/** Per-column upload choices. Each field overrides the matching top-level field. */
export interface SheetsUploadColumnConfig {
	/** Files table (GraphQL type name) to upload into, when the server does not bind the column to one. */
	filesType?: string;
	/** Bucket key to upload into. */
	bucketKey?: string;
	/** Which default bucket to use when no bucket key is set: the public one (true) or the private one (false). */
	isPublic?: boolean;
	/** Owner id for a files table whose uploads need one. */
	ownerId?: string;
}

/** How long Sheets keeps retrying a cell write while the server confirms a new file. */
export interface SheetsUploadProcessingConfig {
	/** Give up and offer a manual retry after this long. Default 120 000 ms. */
	timeoutMs?: number;
	/** First wait between attempts. Doubles up to `maxDelayMs`. Default 1 000 ms. */
	initialDelayMs?: number;
	/** Longest wait between attempts. Default 8 000 ms. */
	maxDelayMs?: number;
}

export interface SheetsUploadConfig {
	/** Bucket key to upload into. Omit to use the default bucket chosen by `isPublic`. */
	bucketKey?: string;
	/** Which default bucket to use when no bucket key is set. Default true (the public default bucket). */
	isPublic?: boolean;
	/** Owner id sent when a files table needs one (entity-scoped storage). */
	ownerId?: string;
	/**
	 * Files table (GraphQL type name) for file columns the server does not bind,
	 * when the storage service has several files tables.
	 */
	filesType?: string;
	/** Per-column choices, keyed by `TableModel.key` or table name, then by column name. */
	columns?: Readonly<Record<string, Readonly<Record<string, SheetsUploadColumnConfig>>>>;
	/** Retry window for a write that waits on the server's file confirmation. */
	processing?: SheetsUploadProcessingConfig;
}

/** The choices that apply to one column, after per-column entries are merged over the top level. */
export interface ResolvedUploadChoices {
	filesType: string | null;
	bucketKey: string | null;
	/** The access the default bucket is chosen by. Ignored by the server when a bucket key is set. */
	isPublic: boolean;
	ownerId: string | null;
}

/** Choices for one column: the per-column entry (by table key first, then table name) over the top level. */
export function uploadChoicesFor(
	config: SheetsUploadConfig | undefined,
	table: { key: string; name: string },
	columnName: string,
): ResolvedUploadChoices {
	const byTable = config?.columns?.[table.key] ?? config?.columns?.[table.name];
	const column = byTable?.[columnName];
	return {
		filesType: column?.filesType ?? config?.filesType ?? null,
		bucketKey: column?.bucketKey ?? config?.bucketKey ?? null,
		isPublic: column?.isPublic ?? config?.isPublic ?? true,
		ownerId: column?.ownerId ?? config?.ownerId ?? null,
	};
}

export interface ProcessingPolicy {
	timeoutMs: number;
	initialDelayMs: number;
	maxDelayMs: number;
}

const DEFAULT_PROCESSING: ProcessingPolicy = { timeoutMs: 120_000, initialDelayMs: 1_000, maxDelayMs: 8_000 };

export function processingPolicyOf(config: SheetsUploadConfig | undefined): ProcessingPolicy {
	const processing = config?.processing;
	return {
		timeoutMs: processing?.timeoutMs ?? DEFAULT_PROCESSING.timeoutMs,
		initialDelayMs: processing?.initialDelayMs ?? DEFAULT_PROCESSING.initialDelayMs,
		maxDelayMs: processing?.maxDelayMs ?? DEFAULT_PROCESSING.maxDelayMs,
	};
}

// The upload mutation for one file, built from the operation the storage
// schema declares. Only input fields the mutation really has are sent, and a
// required field the grid cannot fill (an owner id nobody configured) stops the
// upload before any request with a reason.

import { createError, isRequiredInput } from '@constructive-io/data';

import type { SheetsExecuteFn } from '../context/sheets-execute';
import {
	UPLOAD_PAYLOAD_FIELDS,
	readUploadPayload,
	type UploadPayload,
	type UploadRequestInput,
	type UploadRequester,
} from '../context/sheets-upload-presigned';
import type { UploadOperation } from './storage-catalog';
import type { ResolvedUploadChoices } from './upload-config';

/** Values the host or the session supplies beside the file itself. */
export interface UploadRequestContext {
	choices: ResolvedUploadChoices;
	/** `SheetsConfig.databaseId`, sent when the input has `databaseId`. */
	databaseId: string | null;
}

/** Payload fields the grid needs to complete an upload. */
const REQUIRED_PAYLOAD_FIELDS = ['deduplicated', 'file'] as const;

/** Why an upload operation cannot be called with this context, or null when it can. */
export function uploadOperationProblem(op: UploadOperation, context: UploadRequestContext): string | null {
	if (!REQUIRED_PAYLOAD_FIELDS.every((name) => op.payloadFields.has(name))) {
		return 'The storage service does not return the file details an upload needs.';
	}
	const ownerId = op.inputFields.find((field) => field.name === 'ownerId');
	if (ownerId && isRequiredInput(ownerId) && !context.choices.ownerId) {
		return 'Uploads to this file store need an owner, and none is set.';
	}
	return null;
}

function inputValues(op: UploadOperation, file: UploadRequestInput, context: UploadRequestContext): Record<string, unknown> {
	const accepted = new Set(op.inputFields.map((field) => field.name));
	const { choices } = context;
	const values: Record<string, unknown> = {
		contentHash: file.contentHash,
		contentType: file.contentType,
		size: file.size,
		filename: file.filename,
		// A bucket key names the bucket; without one, `isPublic` picks the default bucket.
		...(choices.bucketKey ? { bucketKey: choices.bucketKey } : { isPublic: choices.isPublic }),
		...(choices.ownerId ? { ownerId: choices.ownerId } : {}),
		...(context.databaseId ? { databaseId: context.databaseId } : {}),
	};
	const input = Object.fromEntries(Object.entries(values).filter(([name]) => accepted.has(name)));
	const missing = op.inputFields.find((field) => isRequiredInput(field) && !(field.name in input));
	if (missing) {
		throw createError.badRequest(`The upload cannot be sent: the storage service needs "${missing.name}".`);
	}
	return input;
}

/** A requester that sends the operation's mutation on the storage executor. */
export function createUploadRequester(
	execute: SheetsExecuteFn,
	op: UploadOperation,
	context: UploadRequestContext,
): UploadRequester {
	const selection = UPLOAD_PAYLOAD_FIELDS.filter((name) => op.payloadFields.has(name)).join(' ');
	const source = `mutation SheetsUploadFile($input: ${op.argType}) { ${op.field}(${op.argName}: $input) { ${selection} } }`;
	return async (file, signal): Promise<UploadPayload> => {
		const data = await execute<Record<string, unknown>>(source, { input: inputValues(op, file, context) }, { signal });
		return readUploadPayload(data?.[op.field]);
	};
}

// Upload one file into a files table of the storage service, outside any cell:
// for a host screen that stores a file somewhere other than a grid column (an
// entity's attachment, a record created around an uploaded file).
//
// The same path as a file column: the upload mutation is the one the storage
// service's `_meta` names for that files table, its input and payload fields
// come from the storage schema, the bucket's limits are checked first, the PUT
// sends the returned `uploadHeaders` unchanged, and bytes the service already
// holds are not sent again.

import { createError, type TableModel } from '@constructive-io/data';

import { createPostGraphileAdapter } from '../adapter/postgraphile-adapter';
import type { SheetsBackendAdapter } from '../adapter/sheets-adapter';
import type { SheetsStorageTransport } from '../context/sheets-context';
import type { FileProjection, UploadProgressEvent } from '../context/sheets-upload-presigned';
import { planeUpload } from './plane-upload';
import { loadPlaneDetails, loadStorageCatalog, type StoragePlane } from './storage-catalog';

export interface UploadToFilesTableOptions {
	/**
	 * The storage service: its GraphQL endpoint and an executor bound to it. Pass the
	 * same object on every call; the storage catalog and schema lookups are cached on it.
	 */
	storage: SheetsStorageTransport;
	/** The files table: its `TableModel.key`, its GraphQL type name, or its model. */
	filesTable: string | Pick<TableModel, 'key' | 'name'>;
	file: File;
	/** Owner of the file, for a files table whose uploads need one. Sent only when the mutation takes `ownerId`. */
	ownerId?: string;
	/** Bucket to upload into. Sent only when the mutation takes `bucketKey`. */
	bucketKey?: string;
	/** Without a bucket key, the public (true, the default) or private default bucket. Sent only when the mutation takes `isPublic`. */
	isPublic?: boolean;
	/** Sent only when the mutation takes `databaseId`. */
	databaseId?: string;
	/** Cancels the request and the PUT. The promise then rejects with an `AbortError`. */
	signal?: AbortSignal;
	onProgress?: (progress: UploadProgressEvent) => void;
	/** Reads `_meta`, table models and bucket rows. Default: the built-in adapter. */
	adapter?: Pick<SheetsBackendAdapter, 'fetchMeta' | 'fetchTableModel' | 'listRows'>;
}

export interface UploadedFile {
	/** Id of the files table row. */
	fileId: string;
	/** The stored file as the storage service returned it: the value a file column stores. */
	file: FileProjection;
	/** True when the service already held these bytes; no PUT was sent and `file` is the existing file. */
	deduplicated: boolean;
}

const defaultAdapter = createPostGraphileAdapter();

function matchesPlane(plane: StoragePlane, filesTable: UploadToFilesTableOptions['filesTable']): boolean {
	if (typeof filesTable === 'string') return plane.filesTableKey === filesTable || plane.filesType === filesTable;
	return plane.filesTableKey === filesTable.key;
}

function tableLabel(filesTable: UploadToFilesTableOptions['filesTable']): string {
	return typeof filesTable === 'string' ? filesTable : filesTable.name;
}

/**
 * Upload `file` into `filesTable` and return the stored file and its id. Rejects
 * with the reason when the storage service does not offer uploads for that
 * table, when a required input (an owner id) is missing, when the bucket would
 * refuse the file, or when the request or the PUT fails.
 */
export async function uploadToFilesTable(options: UploadToFilesTableOptions): Promise<UploadedFile> {
	const { storage, filesTable, file, signal, onProgress } = options;
	const adapter = options.adapter ?? defaultAdapter;
	const catalog = await loadStorageCatalog(storage, adapter);
	if (catalog.source !== 'meta') {
		throw createError.badRequest('This storage service does not say which mutation uploads its files, so the file cannot be uploaded.');
	}
	const plane = catalog.planes.find((candidate) => matchesPlane(candidate, filesTable));
	if (!plane) {
		throw createError.badRequest(`"${tableLabel(filesTable)}" is not a files table of this storage service.`);
	}
	const details = await loadPlaneDetails(storage, adapter, catalog, plane);
	const upload = planeUpload(storage, adapter, details, {
		choices: {
			filesType: plane.filesType,
			bucketKey: options.bucketKey ?? null,
			isPublic: options.isPublic ?? true,
			ownerId: options.ownerId ?? null,
		},
		databaseId: options.databaseId ?? null,
	});
	if (upload.status === 'unavailable') throw createError.badRequest(upload.reason);
	const payload = await upload.send(file, { signal, onProgress });
	return { fileId: payload.fileId, file: payload.file, deduplicated: payload.deduplicated };
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

// What a file cell holds, read through the value domains the backend defines:
//
//   image / upload  an object with at least one of `url`, `id`, `key`, plus
//                   optional `bucket`, `bucket_id`, `provider`, `mime`, `size`,
//                   `filename` (and `versions` for images). The upload
//                   mutation returns exactly this projection; `url` is set only
//                   for a public bucket and is durable.
//   attachment      an http(s) URL string.
//   lists           an array of the above (upload[]).
//
// Nothing here guesses other property names. A signed download URL never
// enters a stored value: it expires, so it lives only in the preview cache.

import type { ColumnFileModel } from '@constructive-io/data';

/** One file of a cell, normalized for display. */
export interface StoredFile {
	/** Files-row id from the projection, or null. */
	id: string | null;
	/** Object key from the projection, or null. */
	key: string | null;
	/** Durable URL: the projection's public `url`, or the attachment link. Never a signed URL. */
	url: string | null;
	filename: string | null;
	mime: string | null;
	size: number | null;
	/** The stored element exactly as the cell holds it, written back unchanged when the file is kept. */
	raw: unknown;
}

function text(value: unknown): string | null {
	return typeof value === 'string' && value !== '' ? value : null;
}

function size(value: unknown): number | null {
	if (typeof value === 'number' && Number.isFinite(value)) return value;
	if (typeof value === 'string' && /^\d+$/.test(value)) return Number(value);
	return null;
}

function fromObject(value: Record<string, unknown>): StoredFile {
	return {
		id: text(value.id),
		key: text(value.key),
		url: text(value.url),
		filename: text(value.filename),
		mime: text(value.mime),
		size: size(value.size),
		raw: value,
	};
}

function fromLink(value: string): StoredFile {
	return { id: null, key: null, url: value, filename: basename(value), mime: null, size: null, raw: value };
}

function fromElement(value: unknown): StoredFile | null {
	if (value == null) return null;
	if (typeof value === 'string') return value ? fromLink(value) : null;
	if (typeof value === 'object' && !Array.isArray(value)) return fromObject(value as Record<string, unknown>);
	// Unknown element: keep it so a list write never drops data it did not understand.
	return { id: null, key: null, url: null, filename: null, mime: null, size: null, raw: value };
}

/**
 * The files of a cell value, in order. A list column yields every element; a
 * single column yields zero or one file. `file` may be null when the column
 * model is not known: the value's shape is then read as is.
 */
export function storedFilesOf(value: unknown, file?: ColumnFileModel | null): StoredFile[] {
	if (Array.isArray(value)) return value.flatMap((element): StoredFile[] => { const file = fromElement(element); return file ? [file] : []; });
	if (file?.multiple && value == null) return [];
	const single = fromElement(value);
	return single ? [single] : [];
}

/** Last path segment of a URL, without query or hash. */
export function basename(url: string): string {
	const path = url.split(/[?#]/)[0] ?? url;
	const segment = path.slice(path.lastIndexOf('/') + 1);
	try {
		return decodeURIComponent(segment) || url;
	} catch {
		return segment || url;
	}
}

/** The name to show for a file: its filename, else the URL's last segment, else its key. */
export function fileLabel(file: StoredFile): string {
	return file.filename ?? (file.url ? basename(file.url) : null) ?? (file.key ? basename(file.key) : null) ?? 'File';
}

/** True when the file should preview as an image. */
export function isImageFile(file: StoredFile, kind: ColumnFileModel['kind'] | null): boolean {
	if (file.mime) return file.mime.startsWith('image/');
	return kind === 'image';
}

/** A short human type label: `PNG`, `PDF`, or the mime type. */
export function fileTypeLabel(mime: string | null, name?: string | null): string | null {
	if (mime) {
		const subtype = mime.split('/')[1];
		if (subtype && /^[a-z0-9.+-]+$/i.test(subtype) && subtype.length <= 8) return subtype.replace(/^x-/, '').toUpperCase();
		return mime;
	}
	const extension = name?.match(/\.([a-z0-9]{1,8})$/i)?.[1];
	return extension ? extension.toUpperCase() : null;
}

/** Name, type and size, joined for a title or a chip's second line. */
export function fileDetails(file: StoredFile): string {
	const label = fileLabel(file);
	return [label, fileTypeLabel(file.mime, label), file.size != null ? formatFileSize(file.size) : null]
		.filter(Boolean)
		.join(' • ');
}

/** Format a byte count: `0 B`, `1.5 KB`, `10 MB`. */
export const formatFileSize = (bytes: number): string => {
	if (bytes === 0) return '0 B';
	const k = 1024;
	const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
	const i = Math.min(sizes.length - 1, Math.floor(Math.log(bytes) / Math.log(k)));
	return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
};

/** Durable URL of the first file of a value, for copy and export. */
export function durableUrlOf(value: unknown): string | null {
	return storedFilesOf(value).find((file) => file.url)?.url ?? null;
}

'use client';

import React, { lazy, Suspense, useCallback, useEffect, useRef, useState } from 'react';
import type { LeafletMouseEvent } from 'leaflet';
import { MapPinIcon, SearchIcon, XIcon, Loader2 } from 'lucide-react';

import { cn } from './cn';
import { moduleExports } from './module-interop';
import { DEFAULT_MAP_TILES, DEFAULT_PLACE_SEARCH, type MapSettings, type SheetsMapPlaceSearch } from './map-settings';
import { sheetsLogger } from './sheets-logger';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

// TypeScript interfaces
interface GeoJSONPoint {
	type: 'Point';
	coordinates: [number, number]; // [longitude, latitude]
}

interface MapPickerValue {
	geojson: GeoJSONPoint;
	srid: number;
	x: number;
	y: number;
}

type MapTiles = NonNullable<MapSettings['tiles']>;

interface MapPickerProps {
	value?: MapPickerValue | GeoJSONPoint | any;
	onChange?: (value: MapPickerValue | undefined) => void;
	className?: string;
	placeholder?: string;
	disabled?: boolean;
	height?: number;
	markerColor?: string;
	/** Where the map tiles come from (`SheetsConfig.map.tiles`). Default: OpenStreetMap. */
	tiles?: MapTiles;
	/** The place search endpoint, or null for no search box (`SheetsConfig.map.placeSearch`). */
	placeSearch?: SheetsMapPlaceSearch | null;
}

interface SearchResult {
	display_name: string;
	lat: string;
	lon: string;
	place_id: string;
}

// Utility functions
const createMapValue = (lat: number, lng: number): MapPickerValue => ({
	geojson: {
		type: 'Point',
		coordinates: [lng, lat],
	},
	srid: 4326,
	x: lng,
	y: lat,
});

const extractPosition = (value: any): [number, number] | null => {
	if (!value) return null;

	let coordinates: [number, number] | undefined;

	if (value.type === 'Point' && Array.isArray(value.coordinates)) {
		coordinates = value.coordinates;
	} else if (value.geojson?.type === 'Point' && Array.isArray(value.geojson.coordinates)) {
		coordinates = value.geojson.coordinates;
	}

	if (!coordinates || coordinates.length < 2) return null;

	const [lng, lat] = coordinates;

	if (typeof lng !== 'number' || typeof lat !== 'number') return null;
	if (!isFinite(lng) || !isFinite(lat)) return null;

	return [lat, lng];
};

/** Ask the place search endpoint (Nominatim's `/search` form) for up to five places. */
const searchLocation = async (endpoint: string, query: string): Promise<SearchResult[]> => {
	if (!query.trim()) return [];

	try {
		const url = new URL(endpoint);
		url.searchParams.set('format', 'json');
		url.searchParams.set('q', query);
		url.searchParams.set('limit', '5');
		url.searchParams.set('addressdetails', '1');
		const response = await fetch(url.toString());
		const results = await response.json();
		return results || [];
	} catch (error) {
		sheetsLogger().error('Search error:', error);
		return [];
	}
};

/**
 * Inner map component that uses react-leaflet.
 * Lazy-loaded to avoid bundling ~270KB Leaflet in main chunk.
 */
const LeafletMapInner = lazy(() =>
	Promise.all([import('react-leaflet'), import('leaflet')]).then(([reactLeafletModule, leafletModule]) => {
		// Leaflet is UMD-only, so a bundler may hand back `{ default: L }`; read both through the same boundary.
		const reactLeaflet = moduleExports(reactLeafletModule);
		const L = moduleExports(leafletModule);
		const { MapContainer, TileLayer, Marker, useMapEvents, useMap } = reactLeaflet;

		const createCustomIcon = (color: string = '#3b82f6') => {
			return L.divIcon({
				html: `
					<div style="
						width: 32px;
						height: 32px;
						display: flex;
						align-items: center;
						justify-content: center;
						background: ${color};
						border: 3px solid white;
						border-radius: 50% 50% 50% 0;
						transform: rotate(-45deg);
						box-shadow: 0 2px 8px rgba(0,0,0,0.3);
					">
						<svg width="16" height="16" viewBox="0 0 24 24" fill="white" style="transform: rotate(45deg);">
							<path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
						</svg>
					</div>
				`,
				className: 'custom-marker',
				iconSize: [32, 32],
				iconAnchor: [16, 32],
				popupAnchor: [0, -32],
			});
		};

		function MapEventHandler({
			onMapClick,
			position,
		}: {
			onMapClick: (lat: number, lng: number) => void;
			position: [number, number] | null;
		}): React.ReactElement | null {
			const map = useMap();

			useMapEvents({
				click(e: LeafletMouseEvent) {
					onMapClick(e.latlng.lat, e.latlng.lng);
				},
			});

			React.useEffect(() => {
				if (position && map) {
					map.setView(position, 15);
				}
			}, [position, map]);

			return null;
		}

		function LeafletMap({
			position,
			onMapClick,
			disabled,
			height,
			markerColor,
			tiles,
		}: {
			tiles: MapTiles;
			position: [number, number] | null;
			onMapClick: (lat: number, lng: number) => void;
			disabled: boolean;
			height: number;
			markerColor: string;
		}) {
			const defaultCenter: [number, number] = [40.7128, -74.006];

			return (
				<div style={{ height: `${height}px` }} className='relative'>
					<MapContainer
						center={position || defaultCenter}
						zoom={position ? 15 : 10}
						style={{ height: '100%', width: '100%' }}
						className={cn('z-0', disabled && 'pointer-events-none opacity-64')}
					>
						<TileLayer
							attribution={tiles.attribution}
							url={tiles.url}
							{...(tiles.subdomains ? { subdomains: tiles.subdomains } : {})}
						/>

						{position && <Marker position={position} icon={createCustomIcon(markerColor)} />}

						<MapEventHandler onMapClick={onMapClick} position={position} />
					</MapContainer>

					{disabled && <div className='bg-background/50 absolute inset-0 z-10' />}
				</div>
			);
		}

		return { default: LeafletMap };
	})
);

function MapLoading({ height }: { height: number }) {
	return (
		<div style={{ height: `${height}px` }} className='bg-muted flex items-center justify-center rounded-lg border'>
			<Loader2 className='h-6 w-6 animate-spin text-muted-foreground' />
		</div>
	);
}

export function MapPicker({
	value,
	onChange,
	className,
	placeholder = 'Search for a location...',
	disabled = false,
	height = 300,
	markerColor = '#3b82f6',
	tiles = DEFAULT_MAP_TILES,
	placeSearch = DEFAULT_PLACE_SEARCH,
}: MapPickerProps) {
	const [searchQuery, setSearchQuery] = useState('');
	const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
	const [isSearching, setIsSearching] = useState(false);
	const [showResults, setShowResults] = useState(false);
	const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

	const position = extractPosition(value);

	const handleMapClick = useCallback(
		(lat: number, lng: number) => {
			if (disabled) return;
			const newValue = createMapValue(lat, lng);
			onChange?.(newValue);
			setSearchQuery('');
			setShowResults(false);
		},
		[disabled, onChange],
	);

	const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
		const query = e.target.value;
		setSearchQuery(query);

		if (searchTimeoutRef.current) {
			clearTimeout(searchTimeoutRef.current);
		}

		searchTimeoutRef.current = setTimeout(async () => {
			if (!placeSearch) return;
			if (query.trim()) {
				setIsSearching(true);
				setShowResults(true);
				const results = await searchLocation(placeSearch.url, query);
				setSearchResults(results);
				setIsSearching(false);
			} else {
				setShowResults(false);
				setSearchResults([]);
			}
		}, 300);
	}, [placeSearch]);

	const handleResultSelect = useCallback(
		(result: SearchResult) => {
			if (disabled) return;
			const lat = parseFloat(result.lat);
			const lng = parseFloat(result.lon);
			const newValue = createMapValue(lat, lng);
			onChange?.(newValue);
			setSearchQuery(result.display_name);
			setShowResults(false);
		},
		[disabled, onChange],
	);

	const clearSearch = useCallback(() => {
		setSearchQuery('');
		setShowResults(false);
		setSearchResults([]);
	}, []);

	const clearLocation = useCallback(() => {
		if (disabled) return;
		onChange?.(undefined);
		setSearchQuery('');
	}, [disabled, onChange]);

	useEffect(() => {
		return () => {
			if (searchTimeoutRef.current) {
				clearTimeout(searchTimeoutRef.current);
			}
		};
	}, []);

	return (
		<div className={cn('relative w-full', className)}>
			{/* Search Input (only with a place search; SheetsConfig.map.placeSearch can turn it off) */}
			{placeSearch ? (
				<div className='relative mb-2'>
					<InputGroup>
						<InputGroupAddon>
							<SearchIcon />
						</InputGroupAddon>
						<InputGroupInput
							type='text'
							placeholder={placeholder}
							value={searchQuery}
							onChange={handleSearchChange}
							disabled={disabled}
						/>
						<InputGroupAddon align='inline-end'>
							{searchQuery && (
								<Button
									type='button'
									variant='ghost'
									size='sm'
									onClick={clearSearch}
									disabled={disabled}
									className='h-7 w-7 p-0'
								>
									<XIcon className='h-3 w-3' />
								</Button>
							)}
							{position && (
								<Button
									type='button'
									variant='ghost'
									size='sm'
									onClick={clearLocation}
									disabled={disabled}
									className='h-7 w-7 p-0'
								>
									<MapPinIcon className='h-3 w-3' />
								</Button>
							)}
						</InputGroupAddon>
					</InputGroup>

					{/* Search Results */}
					{showResults && (
						<Card className='absolute top-full right-0 left-0 z-50 mt-1 max-h-60 overflow-y-auto'>
							<CardContent className='p-0'>
								{isSearching && <div className='text-muted-foreground px-3 py-2 text-sm'>Searching...</div>}
								{!isSearching && searchResults.length === 0 && searchQuery && (
									<div className='text-muted-foreground px-3 py-2 text-sm'>No results found</div>
								)}
								{!isSearching &&
									searchResults.map((result) => (
										<button
											key={result.place_id}
											onClick={() => handleResultSelect(result)}
											disabled={disabled}
											className='hover:bg-accent hover:text-accent-foreground w-full px-3 py-2 text-left text-sm
												disabled:cursor-not-allowed disabled:opacity-64'
										>
											{result.display_name}
										</button>
									))}
							</CardContent>
						</Card>
					)}
				</div>
			) : null}

			{/* Map Container: the map fills the frame (no card padding bands above and below it). */}
			<Card className='overflow-hidden py-0'>
				<CardContent className='p-0'>
					<Suspense fallback={<MapLoading height={height} />}>
						<LeafletMapInner
							tiles={tiles}
							position={position}
							onMapClick={handleMapClick}
							disabled={disabled}
							height={height}
							markerColor={markerColor}
						/>
					</Suspense>
				</CardContent>
			</Card>

			{/* Current Location Info */}
			{position && (
				<div className='text-muted-foreground mt-2 text-xs'>
					<div className='flex items-center gap-1'>
						<MapPinIcon className='h-3 w-3' />
						<span>
							Latitude: {position[0].toFixed(6)}, Longitude: {position[1].toFixed(6)}
						</span>
					</div>
				</div>
			)}
		</div>
	);
}

// Where the geometry editor's map gets its tiles and its place search, from
// `SheetsConfig.map`. The defaults are OpenStreetMap's public tile server and its
// Nominatim search, as before. A host can point either at its own service, or turn it
// off: with no tiles, shapes are edited as GeoJSON text; with no place search, the map
// has no search box.
//
// Content security: the browser loads tile images from the tile URL's host (`img-src`)
// and calls the place search with fetch (`connect-src`). A host with a
// Content-Security-Policy must allow both, or turn them off.

import { useContext, useMemo } from 'react';

import { SheetsContext } from '../context/sheets-context';
import { sheetsLogger } from './sheets-logger';

/** Map tiles: an `https` URL template with `{z}`, `{x}` and `{y}` (and `{s}` for subdomains), and the attribution the provider requires. */
export interface SheetsMapTiles {
	url: string;
	/** Attribution HTML shown on the map, as the tile provider requires. It is host-supplied, trusted markup. */
	attribution: string;
	/** Letters for `{s}` in the URL (default "abc"). */
	subdomains?: string;
}

/** Place search: an endpoint that answers like Nominatim's `/search` (`format=json`: `display_name`, `lat`, `lon`, `place_id`). */
export interface SheetsMapPlaceSearch {
	url: string;
}

export interface SheetsMapConfig {
	/** Map tiles, or `'off'` to edit shapes as GeoJSON text only. Default: OpenStreetMap. */
	tiles?: SheetsMapTiles | 'off';
	/** Place search for the map's search box, or `'off'` for no search box. Default: OpenStreetMap Nominatim. */
	placeSearch?: SheetsMapPlaceSearch | 'off';
}

export interface MapSettings {
	/** Null: no map; shapes are edited as GeoJSON text. */
	tiles: Required<Pick<SheetsMapTiles, 'url' | 'attribution'>> & Pick<SheetsMapTiles, 'subdomains'> | null;
	/** Null: no search box. */
	placeSearch: SheetsMapPlaceSearch | null;
}

export const DEFAULT_MAP_TILES: SheetsMapTiles = {
	url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
	attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
};

export const DEFAULT_PLACE_SEARCH: SheetsMapPlaceSearch = { url: 'https://nominatim.openstreetmap.org/search' };

const HTTP_URL_RE = /^https?:\/\/[^\s]+$/i;

function tilesFrom(tiles: SheetsMapConfig['tiles']): MapSettings['tiles'] {
	if (tiles === 'off') return null;
	if (tiles === undefined) return DEFAULT_MAP_TILES;
	const usable =
		typeof tiles.url === 'string' && HTTP_URL_RE.test(tiles.url) && ['{z}', '{x}', '{y}'].every((part) => tiles.url.includes(part));
	if (!usable) {
		// A broken template would show an empty map; GeoJSON text still edits the shape.
		sheetsLogger().warn('SheetsConfig.map.tiles needs an http(s) URL template with {z}, {x} and {y}; the map is turned off.', tiles);
		return null;
	}
	return { url: tiles.url, attribution: typeof tiles.attribution === 'string' ? tiles.attribution : '', subdomains: tiles.subdomains };
}

function placeSearchFrom(search: SheetsMapConfig['placeSearch']): MapSettings['placeSearch'] {
	if (search === 'off') return null;
	if (search === undefined) return DEFAULT_PLACE_SEARCH;
	if (typeof search.url !== 'string' || !HTTP_URL_RE.test(search.url)) {
		sheetsLogger().warn('SheetsConfig.map.placeSearch needs an http(s) URL; the search box is turned off.', search);
		return null;
	}
	return { url: search.url };
}

/** The map settings for a `SheetsConfig.map` value. A setting that is not usable is turned off, never sent to a default service. */
export function resolveMapSettings(config: SheetsMapConfig | undefined): MapSettings {
	return { tiles: tilesFrom(config?.tiles), placeSearch: placeSearchFrom(config?.placeSearch) };
}

/** The map settings of the nearest Sheets provider (the defaults outside one). */
export function useMapSettings(): MapSettings {
	const map = useContext(SheetsContext)?.config.map;
	return useMemo(() => resolveMapSettings(map), [map]);
}

/**
 * The real exports of a dynamically imported package, whatever shape the bundler
 * gives it. A CommonJS or UMD package (leaflet 1.9 ships only a UMD `main`) can
 * arrive as a namespace whose only member is `default`; an ES module arrives with
 * its named exports. A namespace that has named exports is used as it is, even when
 * it also has a default export.
 */
export function moduleExports<T extends object>(namespace: T): T {
	const named = Object.keys(namespace).filter((key) => key !== 'default' && key !== '__esModule');
	if (named.length > 0) return namespace;
	const inner: unknown = (namespace as { default?: unknown }).default;
	if ((typeof inner === 'object' && inner !== null) || typeof inner === 'function') return inner as T;
	return namespace;
}

import type { Transition } from 'motion/react';

/**
 * Shared motion configuration for consistent animations across the app.
 * Based on practical animation tips from https://emilkowal.ski/ui/7-practical-animation-tips
 *
 * Key principles:
 * 1. Keep UI animations under 300ms
 * 2. Never animate from scale(0) - use 0.9+ for natural feel
 * 3. Use custom easing curves for more impactful animations
 * 4. Make animations origin-aware when possible
 * 5. Use blur to smooth transitions when needed
 */

// =============================================================================
// Easing Curves
// =============================================================================

/**
 * Standard easing curves for UI animations.
 * Reference: https://easings.co/
 */
export const easings = {
	/** Smooth deceleration - good for elements entering the screen */
	easeOut: [0.25, 0.1, 0.25, 1] as const,

	/** Smooth acceleration - good for elements leaving the screen */
	easeIn: [0.42, 0, 1, 1] as const,

	/** Smooth both ways - good for hover states and toggles */
	easeInOut: [0.42, 0, 0.58, 1] as const,

	/** Snappy entrance with soft landing - great for modals/dialogs */
	snappy: [0.2, 0, 0, 1] as const,

	/** Bouncy feel - use sparingly for playful interactions */
	bounce: [0.34, 1.56, 0.64, 1] as const,

	/** Quick start, gradual stop - good for quick feedback */
	emphasized: [0.4, 0, 0.2, 1] as const,

	/** Physical feel for exit animations */
	physicalExit: [0.4, 0, 0.6, 1] as const,
} as const;

// =============================================================================
// Duration Presets
// =============================================================================

/**
 * Duration presets in seconds.
 * Rule: UI animations should be under 300ms (0.3s)
 */
export const durations = {
	/** Instant feedback (button press, toggle) */
	instant: 0.1,

	/** Quick transitions (tooltips, small elements) */
	fast: 0.15,

	/** Standard UI transitions (modals, panels) */
	normal: 0.2,

	/** Deliberate animations (page transitions, complex reveals) */
	slow: 0.3,

	/** Maximum for UI - use rarely */
	deliberate: 0.4,
} as const;

// =============================================================================
// Spring Presets
// =============================================================================

/**
 * Spring configurations for physics-based animations.
 * These create more natural, organic motion.
 */
export const springs = {
	/** Snappy spring - good for quick interactions */
	snappy: {
		type: 'spring' as const,
		stiffness: 400,
		damping: 30,
		mass: 0.8,
	},

	/** Bouncy spring - good for playful elements */
	bouncy: {
		type: 'spring' as const,
		stiffness: 300,
		damping: 20,
		mass: 0.6,
	},

	/** Gentle spring - good for large elements */
	gentle: {
		type: 'spring' as const,
		stiffness: 150,
		damping: 25,
		mass: 1,
	},

	/** Stiff spring - good for precise movements */
	stiff: {
		type: 'spring' as const,
		stiffness: 500,
		damping: 35,
		mass: 0.5,
	},

	/** Panel/sheet animations */
	panel: {
		type: 'spring' as const,
		stiffness: 150,
		damping: 25,
	},
} as const;

// =============================================================================
// Transition Presets
// =============================================================================

/**
 * Pre-configured transitions for common animation patterns.
 */
export const transitions = {
	/** Fast fade for overlays and simple elements */
	fade: {
		duration: durations.fast,
		ease: easings.easeOut,
	} satisfies Transition,

	/** Standard enter/exit for UI elements */
	enterExit: {
		duration: durations.normal,
		ease: easings.easeOut,
	} satisfies Transition,

	/** Snappy transition for interactive elements */
	snappy: {
		duration: durations.fast,
		ease: easings.snappy,
	} satisfies Transition,

	/** Panel slide transition */
	panel: {
		type: 'spring',
		stiffness: 150,
		damping: 25,
	} satisfies Transition,

	/** Exit transition with physical feel */
	exit: {
		type: 'tween',
		duration: durations.normal,
		ease: easings.physicalExit,
	} satisfies Transition,

	/** Layout animations */
	layout: {
		type: 'spring',
		stiffness: 300,
		damping: 30,
	} satisfies Transition,
} as const;

// =============================================================================
// Animation Variants
// =============================================================================

/**
 * Common animation variants for AnimatePresence patterns.
 * Follows the rule: never animate from scale(0), use 0.9+ instead.
 */
export const variants = {
	/** Fade with subtle scale - good for modals, cards */
	fadeScale: {
		initial: { opacity: 0, scale: 0.95 },
		animate: { opacity: 1, scale: 1 },
		exit: { opacity: 0, scale: 0.95 },
	},

	/** Fade with subtle slide up - good for content reveals */
	fadeSlideUp: {
		initial: { opacity: 0, y: 8 },
		animate: { opacity: 1, y: 0 },
		exit: { opacity: 0, y: -8 },
	},

	/** Fade with subtle slide down - good for dropdowns */
	fadeSlideDown: {
		initial: { opacity: 0, y: -8 },
		animate: { opacity: 1, y: 0 },
		exit: { opacity: 0, y: 8 },
	},

	/** Simple fade - for overlays */
	fade: {
		initial: { opacity: 0 },
		animate: { opacity: 1 },
		exit: { opacity: 0 },
	},

	/** Dock/floating element - scales from bottom */
	floatUp: {
		initial: { opacity: 0, y: 8, scale: 0.98 },
		animate: { opacity: 1, y: 0, scale: 1 },
		exit: { opacity: 0, y: 8, scale: 0.98 },
	},
} as const;

// =============================================================================
// Convenience Aliases (from original template)
// =============================================================================

export const MOTION_SPRING = springs.stiff;
export const MOTION_DURATION = { duration: durations.normal };

/**
 * Locale seam for @constructive-io/sheets.
 *
 * The host app may set a BCP-47 locale via SheetsConfig.locale. The provider
 * installs it into this module singleton (see sheets-provider.tsx), so any cell
 * renderer / editor can format dates and numbers locale-aware without threading
 * the locale through props/context. Defaults to 'en-US' (the prior hardcoded
 * behavior), so omitting `locale` changes nothing.
 */
const DEFAULT_LOCALE = 'en-US';

let active: string = DEFAULT_LOCALE;

/** Install (or reset) the active locale. Pass null/undefined to restore the default. */
export function setSheetsLocale(locale?: string | null): void {
	active = locale || DEFAULT_LOCALE;
}

/** Get the active locale (BCP-47). Safe to call anywhere; returns 'en-US' until set. */
export function sheetsLocale(): string {
	return active;
}

/**
 * Injectable logger seam for @constructive-io/sheets.
 *
 * The host app may provide a custom logger via SheetsConfig.logger. The provider
 * installs it into this module singleton (see sheets-provider.tsx), so any module
 * or hook can log without threading the logger through props/context.
 *
 * Default behaviour matches the prior console.* calls. `debug` is omitted from the
 * default logger (no-op) so verbose diagnostics stay silent unless a host opts in.
 */
export interface SheetsLogger {
	debug?(msg: string, ctx?: unknown): void;
	warn(msg: string, ctx?: unknown): void;
	error(msg: string, ctx?: unknown): void;
}

const defaultLogger: SheetsLogger = {
	warn: (...a) => console.warn(...a),
	error: (...a) => console.error(...a),
	// debug omitted = no-op
};

let active: SheetsLogger = defaultLogger;

/**
 * Install (or reset) the active logger. Pass a host logger to override; pass
 * null/undefined to restore the default. Host overrides are merged over the
 * default so a partial logger still gets working warn/error.
 */
export function setSheetsLogger(l?: SheetsLogger | null): void {
	active = l ? { ...defaultLogger, ...l } : defaultLogger;
}

/** Get the active logger. Safe to call anywhere (returns the default until set). */
export function sheetsLogger(): SheetsLogger {
	return active;
}

import { useEffect, useState } from 'react';

export function useColorScheme(): 'light' | 'dark' {
	const [scheme, setScheme] = useState<'light' | 'dark'>('light');

	useEffect(() => {
		const update = () => {
			setScheme(document.documentElement.classList.contains('dark') ? 'dark' : 'light');
		};
		update();
		const observer = new MutationObserver(() => update());
		observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
		return () => observer.disconnect();
	}, []);

	return scheme;
}

import { useCallback, useRef, useState } from 'react';

interface Size { width: number; height: number; }

export function useResizeObserver<T extends HTMLElement>(): [React.RefCallback<T>, Size] {
	const [size, setSize] = useState<Size>({ width: 0, height: 0 });
	const observerRef = useRef<ResizeObserver | null>(null);

	const ref = useCallback((node: T | null) => {
		if (observerRef.current) {
			observerRef.current.disconnect();
			observerRef.current = null;
		}
		if (node) {
			const observer = new ResizeObserver(([entry]) => {
				if (entry) {
					setSize({ width: entry.contentRect.width, height: entry.contentRect.height });
				}
			});
			observer.observe(node);
			observerRef.current = observer;
		}
	}, []);

	return [ref, size];
}

docs:
Import from `@/components/ui/sheets`. A CRUD grid driven by the API's table model: it reads `_meta` (contract `2026-07`) and targeted introspection, builds one model per table (keys, column kinds, write rules, relations, filter operators, order-by values, label fields), then loads, edits, creates and deletes rows itself over GraphQL with the host's session. There's no `data` prop and no save callback. The host owns the endpoint, the session token and auth errors; PostgreSQL privileges and RLS decide every read and write, and anything the model cannot prove is read-only with a visible reason.

Render it in a client component. `Sheets` fills its parent, so give the parent a bounded height, and mount `<PortalRoot />` from `@/components/ui/portal` once as the last child of `<body>` for the cell editors:
```tsx
'use client';
import { useMemo } from 'react';
import { Sheets, SheetsProvider, type SheetsConfig } from '@/components/ui/sheets';

export function ProjectsGrid({ endpoint, userId, getToken }: { endpoint: string; userId: string; getToken: () => string | null }) {
  const config = useMemo<SheetsConfig>(
    () => ({ endpoint, auth: { mode: 'embedded', getToken, getIdentityKey: () => userId }, onAuthError: signOut }),
    [endpoint, getToken, userId],
  );
  return (
    <SheetsProvider config={config}>
      <div className="h-[680px] min-h-0">
        <Sheets tableName="Project" pageSize={25} />
      </div>
    </SheetsProvider>
  );
}
```
`tableName` is a table's `name` in `_meta` (its GraphQL type name), or its `TableModel.key` (`schema.Name`) when two schemas share the name. To let people pick one, call `useSheetsMeta()` inside the provider, pass `data?._meta?.tables ?? []` to `selectConsoleDataTables` from `@constructive-io/data`, and give the names to `<SheetsTableSelector tables={names} activeTable={name} onTableChange={setName} isLoading={isLoading} />`. `useTableModel(nameOrKey)` returns the model.

The geometry editor draws a map with Leaflet: import `leaflet/dist/leaflet.css` once in the app. `SheetsConfig.map` sets its `tiles` (`{ url, attribution, subdomains? }` or `'off'`) and `placeSearch` (`{ url }` or `'off'`); the default is OpenStreetMap tiles and its Nominatim search, so a Content-Security-Policy needs `img-src` for the tile host and `connect-src` for the search. With no tiles, or when the map cannot load, the editor edits the shape as GeoJSON text.

`SheetsProvider` takes `config: SheetsConfig`; keep it referentially stable.
- `endpoint` (the data GraphQL endpoint) and `auth` are required. `auth` is `{ mode: 'embedded', getToken: () => string | null, getIdentityKey?: () => string | null }`, where the identity key is a non-secret user id that keeps each user's cache apart, or `{ mode: 'standalone' }` with `authEndpoint` and the grid wrapped in `SheetsAuthGate` from `@/components/ui/sheets/auth`.
- Optional: `databaseId`, `displayFields` (label fields per table, `{ Task: ['title'] }`), `fieldTypeOverrides` (`{ 'Task.notes': 'textarea' }`), `locale` (default en-US), `queryClient` (reuse yours), `onAuthError()` (on HTTP 401 or the code `UNAUTHENTICATED` or `BAD_TOKEN_DEFINITION` only, never message text, before the error throws), `onError(error, { source?: 'grid' | 'editor' | 'mutation' | 'upload', tableName? })`, `views` (saved views storage), `logger`, `plugins`.
- Files: `storage: { endpoint, execute? }` (the tenant storage endpoint; without it file cells are view-only) and `upload` (`bucketKey`, `isPublic` (default true), `ownerId`, `filesType`, per-column `columns[tableKeyOrName][column]`, `processing: { timeoutMs, initialDelayMs, maxDelayMs }`). The upload mutation is read from the storage service's `_meta`; the PUT sends the returned `uploadHeaders`; image and upload cells store the returned file projection, attachment cells its public URL. To upload a file outside any cell, call `uploadToFilesTable({ storage, filesTable, file, ownerId?, bucketKey?, isPublic?, databaseId?, signal?, onProgress? })`, which resolves to `{ fileId, file, deduplicated }`. A file whose upload did not finish is left for the storage service to expire; `unfinishedUploadOf(error)` names it.
- To replace the transport: `execute(document, variables?, { signal }?)`, `executeUpload(file, path?, options?) => Promise<{ file: SheetsFileValue; url?: string }>`, or a whole `adapter: SheetsBackendAdapter` (`fetchMeta`, `fetchTableModel`, `listRows`, `createRow`, `updateRow`, `deleteRow`, each taking `{ model, tableName }`).

`Sheets` props:
- `tableName` (required), `pageSize` (default 100), `showSelection` and `showPagination` (default true), `infiniteScroll` (default false), `relationChipLimit`, `relationLabelMaxLength`, `readOnly` (`true` or a reason: every write refuses with it; viewing, sorting, filtering, search and export stay), `csvExport: { protectFormulas }` (off by default: when on, text that starts like a spreadsheet formula is exported with a leading apostrophe), `className`.
- View state: `filters` / `onFiltersChange`, `sort` / `onSortChange`, `search` / `onSearchChange`, `columns` / `onColumnsChange` (order, hidden, frozen count, widths, row height) let a host own any part (`SheetsViewState` version 2, validated against the model with `validateSheetsViewState`; omitted parts are owned by the grid). The toolbar's view switcher saves named views through `SheetsConfig.views` (`SheetsViewStorage`: `list`, `save`, `remove`, optional `getActiveViewId` / `setActiveViewId`; default: browser local storage per endpoint, database, user and table).
- Observers only, since the grid does its own writes: `onRowSelect(rows)`, `onCellEdit(id, field, value)` once an edit is saved (`id` is the primary key, or an object for a composite key), and `onEvent({ type, tableName, at, meta? })` with `type` load:success | load:error | cell:edit | row:create | row:delete | filter:apply | sort:change | search:change | page:change. `onOpenTable({ tableKey, tableName, filters, reason })` is called when the link editor or the record panel asks to open another table; pass `filters` (a filter group, or null) to the opened grid's `filters` prop. `recordId` / `onRecordOpenChange(recordId)` control the record panel (one record beside the grid with its fields, linked records and files; `null` closes it, omit to let the grid own it).
- The toolbar has the view switcher, search, Add row, New record, Import (CSV/TSV/pasted rows, mapped to fields, every cell checked, an error report), Export view (every row of the view as CSV), Export selected, Delete, Fields, Sort and Filters. `slots: { toolbar?, empty?, error?({ error, retry }), loading? }` replace those regions (`ImportRecordsControl` and `ExportViewControl` are exported for a custom toolbar); `cellTypes` and `cellSlots` customize cells and editors; `commands`, `keymap`, `interceptors`, and `onCommand(event, result)` extend or observe grid commands; `theme` and `themeMode` ('light' | 'dark' | 'system') style it.
- A `ref` gets `SheetsHandle`: `scrollToRow(index)`, `submitDrafts()`, `refetch()`, `getSelectedRows()`, `exportCsv({ columns?, filename?, protectFormulas? })`, `openRecord(recordId)`, `openNewRecord()`, `closeRecord()`.
